// Restore persisted BE Rule (default 2.4R)
{
  const savedBERule = parseFloat(localStorage.getItem('beRule'));
  if (Number.isFinite(savedBERule) && savedBERule > 0) appState.ui.beRule = savedBERule;
}
// Restore persisted BE Management mode
{
  const savedBeMode = localStorage.getItem('flipping_be_mode');
  if (savedBeMode === 'be-fallback' || savedBeMode === 'flipping-be') {
    appState.ui.beMode = savedBeMode;
  } else if (savedBeMode === 'no-be') {
    // Migration (PR feat/kill-no-be-mode, 2026-04): the no-be mode was removed.
    // Silently fold to be-fallback (the operational-reality default).
    appState.ui.beMode = 'be-fallback';
    try { localStorage.setItem('flipping_be_mode', 'be-fallback'); } catch {}
  }
}
// Restore persisted ghost mode & warning threshold
{
  const savedGhost = localStorage.getItem('ghostMode');
  if (savedGhost !== null) appState.ui.ghostMode = savedGhost !== 'false';
  const savedWarnThreshold = parseInt(localStorage.getItem('warningThreshold'), 10);
  if ([0, 5, 10, 20, 50].includes(savedWarnThreshold)) appState.ui.warningThreshold = savedWarnThreshold;
}

function _setGhostMode(on) {
  appState.ui.ghostMode = !!on;
  localStorage.setItem('ghostMode', appState.ui.ghostMode);
  _syncGhostUI();
  invalidateFilterCache();
  render();
}

function _setWarningThreshold(val) {
  if (![0, 5, 10, 20, 50].includes(val)) return;
  appState.ui.warningThreshold = val;
  localStorage.setItem('warningThreshold', val);
  _syncGhostUI();
  invalidateFilterCache();
  render();
}

function _syncGhostUI() {
  document.getElementById('ghost-on')?.classList.toggle('active', appState.ui.ghostMode);
  document.getElementById('ghost-off')?.classList.toggle('active', !appState.ui.ghostMode);
  document.querySelectorAll('.ghost-th-btn').forEach(btn => {
    btn.classList.toggle('active', parseInt(btn.dataset.threshold, 10) === appState.ui.warningThreshold);
  });
}

