// Canonical chronological sort used by every equity-curve / max-DD path on
// the dashboard (calcStats, streak analytics, monthly views, the Partial
// Optimizer — see _poSimulateModel) so cross-widget Max DD aligns to the same
// ordering.
//
// Tiebreaker is `_rawRowIndex` (CSV / API insertion order). Crucially, the
// previous "losses before gains" tiebreaker called isLoser(a/b) which routes
// through computeEffectiveRR with the active tpConfig — so changing TP mode
// re-ordered same-date+hour clusters and shifted Max DD in a non-deterministic,
// mode-dependent way. That also broke PO ↔ Personalised convergence: PO
// simulates a counterfactual plan but the sort tiebreaker reflected the
// dashboard's active plan, so the equity curve was being computed under one
// classification with an order produced by another.
//
// _rawRowIndex is stamped at ingestion (CSV parsers / API normalizer / demo
// loader) and is mode-independent. When absent (legacy trades, manual
// injection) we fall back to 0 — Array.sort stability then preserves the
// pre-sort order, which is itself deterministic for a given dataset.
function _sortTradesChronological(trades) {
  return [...trades].sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
    const h = (a.hour ?? 99) - (b.hour ?? 99);
    if (h !== 0) return h;
    return (a._rawRowIndex ?? 0) - (b._rawRowIndex ?? 0);
  });
}

// ── computeEffectiveRR warning rate-limiter ──
// Keyed by '<type>:<discriminator>'. Cleared at the end of every _saveTpConfig
// so the user sees a fresh signal after each config edit instead of stale silence.
const _computeRRWarningsEmitted = new Set();
function _warnComputeRROnce(type, discriminator, message) {
  const key = type + ':' + discriminator;
  if (_computeRRWarningsEmitted.has(key)) return;
  _computeRRWarningsEmitted.add(key);
  console.warn(message);
}

/**
 * Effective R for a trade under the active TP Management mode.
 * Single source of truth: every widget that aggregates or classifies R
 * (except exclusions below) routes through this.
 *
 * Modes:
 *   fixed        -> trade.r unchanged (default / pre-Multi-TP baseline)
 *   multi        -> (Phase 3) weighted sum of tp_N_rr fields by value-presence;
 *                   SL / BE-SL pass through journaled r
 *   personalised -> (Phase 4) delegates to _ppSimTrade (Partial Planner
 *                   simulator) for ALL 4 outcomes. rrMax is the single source
 *                   of truth for the realized price path, so TP / BE-TP /
 *                   BE-SL / SL all route through the same simulator — this
 *                   guarantees dashboard KPIs match the Partial Planner widget
 *                   exactly. BE-SL is no longer short-circuited to trade.r.
 *
 * Simulation interaction: _applySimulation (Partial Planner rrMinFilter) creates
 * new trade objects with t.r and t.outcome overwritten by the simulator. In fixed
 * mode this propagates correctly. In multi mode, simulated trades lack tp_N_rr
 * coherent fields and effectively fall back to t.r — intentional for Phase 1.B.
 * In personalised mode, _ppSimTrade reads rrMax directly (via _getTradeReachR),
 * so the simulator result is consistent regardless of any upstream ORR/PP
 * simulation layering.
 *
 * Exclusions (do NOT route through this):
 *   - Optimal RR Analysis (dashboard.js:9550-9941) — reads trade.rrMax
 *   - Partial Planner     (dashboard.js:12116-13629) — reads _getTradeReachR
 *   - Display-only color/sign sites (trade-log rows, calendar cells, mobile
 *     tradelog) — must show the ORIGINAL trade outcome, not a weighted value
 *   - Identity-match lookups (click-to-locate at 1248, 7858, 10486) — match
 *     on raw r so clicks resolve to the correct trade regardless of mode
 */
function computeEffectiveRR(trade, tpConfig) {
  // ORR pill simulation has already computed the effective r and stamped the
  // trade via _applySimulation. Short-circuit so multi / personalised modes
  // don't re-derive r from outcome+rrMax (which would apply the saved plan
  // payout instead of the ORR pill's "TP=tp 100%" payout, breaking
  // convergence between the sticky-bar KPIs, the ORR widget, and the Partial
  // Optimizer's "Full TP <tp>R" model).
  if (trade && trade._simulated) return trade.r;

  const mode = tpConfig && tpConfig.mode;
  switch (mode) {
    case 'fixed':
      // Fixed mode has no plan — BE-TP / BE-SL are handled by _resolveBeRFixed
      // which encodes the per-mode policy (be-fallback = passthrough trade.r,
      // flipping-be = BE-TP→trade.r / BE-SL→0 if reach≥2.4, else binary
      // rrMax≥2.4→+2.4R else -1).
      if (trade.outcome === 'BE-TP' || trade.outcome === 'BE-SL') {
        return _resolveBeRFixed(trade);
      }
      return trade.r;
    case 'multi': {
      // Phase 3.B active: weighted sum of hit tp_N_rr tiers for TP/BE-TP outcomes.
      // SL / BE-SL pass-through, since journaled r already reflects the realized loss.
      // Every fallback path (incomplete mapping, invalid partials, no-tp-rr, unknown
      // outcome) returns trade.r so the app stays coherent under misconfiguration;
      // _warnComputeRROnce surfaces a single dev warning per distinct condition.
      const mCfg = tpConfig.multi;
      if (!_isMultiMappingComplete(mCfg)) {
        _warnComputeRROnce('multi-mapping-incomplete', 'global',
          '[computeEffectiveRR] Multi mode: mapping incomplete. Falling back to trade.r.');
        return trade.r;
      }
      const pSum = (mCfg.partials.tp1 || 0) + (mCfg.partials.tp2 || 0)
                 + (mCfg.tpCount === 3 ? (mCfg.partials.tp3 || 0) : 0);
      if (Math.abs(pSum - 100) > 0.01) {
        _warnComputeRROnce('multi-partials-sum', String(pSum),
          '[computeEffectiveRR] Multi mode: partials sum=' + pSum + ' (expected 100). Falling back to trade.r.');
        return trade.r;
      }
      if (trade.outcome === 'SL') {
        // True SL: rrMax < TP1 by definition; journaled r already reflects -1R.
        return trade.r;
      }
      if (trade.outcome === 'TP') {
        const p = mCfg.partials;
        const n = mCfg.tpCount;
        let rr = 0;
        let anyHit = false;
        if (trade.tp1_rr != null) { rr += (p.tp1 / 100) * trade.tp1_rr; anyHit = true; }
        if (trade.tp2_rr != null) { rr += (p.tp2 / 100) * trade.tp2_rr; anyHit = true; }
        if (n === 3 && trade.tp3_rr != null) { rr += (p.tp3 / 100) * trade.tp3_rr; anyHit = true; }
        if (!anyHit) {
          const disc = (trade.id != null ? trade.id
                      : (trade._rawRowIndex != null ? trade._rawRowIndex : trade.date)) + '|' + trade.outcome;
          _warnComputeRROnce('multi-no-tp-rr', String(disc),
            '[computeEffectiveRR] Multi mode: trade has outcome=' + trade.outcome + ' but no tp_N_rr filled. Falling back to trade.r.');
          return trade.r;
        }
        return rr;
      }
      if (trade.outcome === 'BE-TP' || trade.outcome === 'BE-SL') {
        // Routes through _resolveBeRMulti which encodes the active BE
        // Management mode:
        //   - be-fallback : tp_N_rr capped at the parsed chip trigger.
        //     Null chip → 0R (BE neutre).
        //   - flipping-be (BE-SL reach ≥ 2.4) : capped at 2.4R hardcoded.
        //   - flipping-be (BE-TP, or BE-SL reach < 2.4) : routed through the
        //     fallback path (BE-TP weighted sum no cap, BE-SL passthrough r).
        return _resolveBeRMulti(trade, mCfg);
      }
      return trade.r;
    }
    case 'personalised': {
      // BE-aware partial-plan simulator. The position closure mechanics are
      // identical for BE-TP and BE-SL: BE armed at trigger → price retraced
      // to 0R → position closed. What happened AFTER the closure (price
      // reaching final TP vs final SL) is irrelevant to the partial plan
      // payout, since the position was already out.
      //
      // Semantics (user convention):
      //   - TP    : rrMax >= TP1, price went straight to target — full
      //             plan simulation via _ppSimTrade.
      //   - BE-TP : BE was armed at beTriggerR (max R parsed from
      //             trade.beManagement chips), price retraced to 0R.
      //             ONLY legs with lv <= beTriggerR are credited; legs above
      //             count 0R (position was already closed).
      //   - BE-SL : same closure mechanics as BE-TP. ONLY legs with
      //             lv <= beTriggerR are credited.
      //   - SL    : rrMax < TP1, never reached 1R → full -1R via _ppSimTrade.
      //
      // rrMax is NOT used for BE-TP/BE-SL because it includes price action
      // AFTER the BE retrace (cosmetic for these outcomes). Only beTriggerR
      // — the actual protection level armed on the position — is reliable.
      //
      // Trades with no parseable beManagement chip return 0R + console warning
      // (suggests the trade is mistagged in the journal).
      const psCfg = tpConfig.personalised;
      if (!_isValidPersonalisedConfig(psCfg)) {
        _warnComputeRROnce('personalised-invalid-config', 'global',
          '[computeEffectiveRR] Personalised mode: config invalid. Falling back to trade.r.');
        return trade.r;
      }
      const psSum = (psCfg.partials.tp1 || 0) + (psCfg.partials.tp2 || 0)
                  + (psCfg.tpCount === 3 ? (psCfg.partials.tp3 || 0) : 0);
      if (Math.abs(psSum - 100) > 0.01) {
        _warnComputeRROnce('personalised-partials-sum', String(psSum),
          '[computeEffectiveRR] Personalised mode: partials sum=' + psSum + ' (expected 100). Falling back to trade.r.');
        return trade.r;
      }

      // Build partials array in the shape _ppSimTrade expects, sorted by level.
      const psT = psCfg.targets;
      const psP = psCfg.partials;
      const partials = [
        { lv: psT.tp1, pct: psP.tp1 / 100 },
        { lv: psT.tp2, pct: psP.tp2 / 100 },
      ];
      if (psCfg.tpCount === 3) partials.push({ lv: psT.tp3, pct: psP.tp3 / 100 });
      partials.sort((a, b) => a.lv - b.lv);

      if (trade.outcome === 'BE-TP' || trade.outcome === 'BE-SL') {
        // Routes through _resolveBeR (shared with PO `_poSimTradeBeAware`).
        // The reach proxy is needed by the flipping-be fallback branches
        // (pure-tp-no-sl for BE-TP, pure-tp-with-sl for BE-SL reach<2.4)
        // where the per-leg payout depends on the actual price excursion.
        return _resolveBeR(trade, partials, _getTradeReachR(trade));
      }

      // TP / SL: delegate to _ppSimTrade with the same reach proxy the Partial
      // Optimizer uses (`_getTradeReachR` = max(rrMax, r if r > 0)). When rrMax
      // is null, _getTradeReachR falls back to realizedR — same as PO — so the
      // sticky-bar KPIs and the PO Full Plan card converge to rounding even on
      // datasets with sparse rrMax. The previous early `return trade.r` on null
      // rrMax broke this invariant and was removed.
      if (trade.rrMax == null || !Number.isFinite(trade.rrMax)) {
        _warnComputeRROnce('personalised-no-rrmax', 'global',
          '[computeEffectiveRR] Personalised mode: trade has no rrMax — using realizedR fallback (mirrors Partial Optimizer).');
      }
      const reachR = _getTradeReachR(trade);
      return _ppSimTrade(reachR, partials);
    }
    default:
      return trade.r;
  }
}

// Enrich trades with effective-R-based classification under a given TP config.
// Mutates each trade in place with:
//   - t.effectiveR             : computeEffectiveRR(t, cfg)
//   - t.effectiveClass         : 'win' (>0) | 'loss' (<0) | 'be' (===0)
//   - t._effectiveClassMode    : _hashTpConfig(cfg) — cache invalidation key
//
// Hooked into filterDataset so every render path that flows through it picks
// up classification automatically. Per-trade hash check makes repeated calls
// near-free when the config hasn't changed (~50ns/trade for the hash compare).
//
// When called with an alt config (e.g. calcStats receives a presetTpConfig),
// trades carry that alt-config classification on return — the next active-
// config render detects the hash mismatch and re-enriches. is*(t, cfg) reads
// classification under the requested cfg, so internal calcStats consistency
// is preserved within a single call.
function _enrichTradeClassification(trades, tpConfig) {
  const cfg = tpConfig || appState.ui.tpConfig;
  const cfgHash = _hashTpConfig(cfg);
  for (const t of trades) {
    if (t._effectiveClassMode === cfgHash) continue;
    const r = computeEffectiveRR(t, cfg);
    t.effectiveR = r;
    t.effectiveClass = r > 0 ? 'win' : (r < 0 ? 'loss' : 'be');
    t._effectiveClassMode = cfgHash;
  }
  return trades;
}

const TP_CONFIG_LS_KEY = 'tpManagementConfig';
const TP_CONFIG_VALID_MODES = ['fixed', 'multi', 'personalised'];

// Fresh default for the multi sub-config. Equal split 50/50 for tpCount=2
// (tp3 kept at 0 so the shape stays uniform regardless of tpCount).
function _defaultMultiConfig() {
  return { tpCount: 2, partials: { tp1: 50, tp2: 50, tp3: 0 } };
}

// Shape check for a stored multi sub-config. Does NOT enforce partials sum = 100
// (that's a UI-level soft validation per the 3.A spec).
function _isValidMultiConfig(m) {
  if (!m || typeof m !== 'object') return false;
  if (m.tpCount !== 2 && m.tpCount !== 3) return false;
  const p = m.partials;
  if (!p || typeof p !== 'object') return false;
  for (const k of ['tp1', 'tp2', 'tp3']) {
    if (typeof p[k] !== 'number' || !Number.isFinite(p[k])) return false;
  }
  return true;
}

// Fresh default for the personalised sub-config. Mirrors _defaultMultiConfig:
// tpCount=2 with 50/50 partials. Targets are seeded 1R / 2R / 3R so switching
// to tpCount=3 yields a sensible ladder without re-editing.
function _defaultPersonalisedConfig() {
  return {
    tpCount: 2,
    targets: { tp1: 1, tp2: 2, tp3: 3 },
    partials: { tp1: 50, tp2: 50, tp3: 0 },
  };
}

// Shape check for a stored personalised sub-config. Does NOT enforce partials
// sum = 100 (UI-level soft validation, same contract as multi). Does NOT
// enforce target > 0 / partial >= 0 — mid-edit states (e.g. empty input
// parsed as 0) must preserve the user's other values on mode switch. The
// input min="0.1" hint and the calc fallback handle those cases gracefully.
function _isValidPersonalisedConfig(p) {
  if (!p || typeof p !== 'object') return false;
  if (p.tpCount !== 2 && p.tpCount !== 3) return false;
  const t = p.targets, pt = p.partials;
  if (!t || typeof t !== 'object' || !pt || typeof pt !== 'object') return false;
  for (const k of ['tp1', 'tp2', 'tp3']) {
    if (typeof t[k] !== 'number' || !Number.isFinite(t[k])) return false;
    if (typeof pt[k] !== 'number' || !Number.isFinite(pt[k])) return false;
  }
  return true;
}

// Default TP Management config used as fallback for both snapshots and live
// slots in the per-preset architecture. Mirrors _loadTpConfig's fallback() shape.
function _defaultTpConfig() {
  return {
    mode: 'fixed',
    multi: _defaultMultiConfig(),
    personalised: _defaultPersonalisedConfig(),
  };
}

// Lightweight shape check used in migration paths (snapshots / live slots
// loaded from localStorage). Returns true if cfg has a valid mode + valid
// sub-configs.
function _isValidTpConfigShape(cfg) {
  if (!cfg || typeof cfg !== 'object') return false;
  if (!TP_CONFIG_VALID_MODES.includes(cfg.mode)) return false;
  if (!_isValidMultiConfig(cfg.multi)) return false;
  if (!_isValidPersonalisedConfig(cfg.personalised)) return false;
  return true;
}

// Deep equality check for two tpConfig objects (mode + multi + personalised).
// Used by _getPresetDivergenceCount to detect when the live tpConfig diverges
// from the snapshot — drives the "preset modified" badge.
function _tpConfigEqual(a, b) {
  if (!a || !b) return a === b;
  if (a.mode !== b.mode) return false;
  if (!a.multi || !b.multi) return false;
  if (a.multi.tpCount !== b.multi.tpCount) return false;
  for (const k of ['tp1', 'tp2', 'tp3']) {
    if (a.multi.partials[k] !== b.multi.partials[k]) return false;
  }
  if (!a.personalised || !b.personalised) return false;
  if (a.personalised.tpCount !== b.personalised.tpCount) return false;
  for (const k of ['tp1', 'tp2', 'tp3']) {
    if (a.personalised.targets[k] !== b.personalised.targets[k]) return false;
    if (a.personalised.partials[k] !== b.personalised.partials[k]) return false;
  }
  return true;
}

// DEPRECATED: tpConfig is now per-preset (stored in presetLiveFilters[id].tpConfig
// and presetSnapshots[id].tpConfig). This loader stays for legacy migration
// reference but is no longer called at boot. The localStorage key
// 'tpManagementConfig' is no longer maintained.
function _loadTpConfig() {
  const fallback = () => ({ mode: 'fixed', multi: _defaultMultiConfig(), personalised: _defaultPersonalisedConfig() });
  try {
    const raw = localStorage.getItem(TP_CONFIG_LS_KEY);
    if (!raw) return fallback();
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') throw new Error('not an object');
    if (!TP_CONFIG_VALID_MODES.includes(parsed.mode)) throw new Error('invalid mode: ' + parsed.mode);

    const multiValid = _isValidMultiConfig(parsed.multi);
    const personalisedValid = _isValidPersonalisedConfig(parsed.personalised);
    // Lenient recovery policy (applied symmetrically to multi and personalised):
    //   - mode === 'X' + X sub-config invalid → hard fail (back to fixed + warn): the
    //     active mode depends on the sub-config being usable, we must not pretend it's ok.
    //   - mode !== 'X' + X sub-config invalid → silent repair with defaults: the sub-config
    //     isn't being consumed right now, so no need to escalate to the user.
    if (parsed.mode === 'multi' && !multiValid) {
      throw new Error('multi sub-config malformed while mode=multi');
    }
    if (parsed.mode === 'personalised' && !personalisedValid) {
      throw new Error('personalised sub-config malformed while mode=personalised');
    }

    const result = { mode: parsed.mode };
    result.multi = multiValid
      ? { tpCount: parsed.multi.tpCount, partials: { ...parsed.multi.partials } }
      : _defaultMultiConfig();
    result.personalised = personalisedValid
      ? {
          tpCount: parsed.personalised.tpCount,
          targets: { ...parsed.personalised.targets },
          partials: { ...parsed.personalised.partials },
        }
      : _defaultPersonalisedConfig();
    return result;
  } catch (e) {
    console.warn('[tpConfig] Invalid stored config, falling back to fixed mode:', e.message);
    return fallback();
  }
}

function _saveTpConfig(cfg) {
  // tpConfig is now per-preset: instead of writing to a global localStorage
  // key, sync it into the active preset's LIVE slot. Snapshot capture happens
  // separately on Save preset action (see _buildSnapshotFromActiveChips).
  try {
    const activeId = appState.presets?.activeId ?? null;
    const slot = getPresetLiveSlot(activeId);
    slot.tpConfig = JSON.parse(JSON.stringify(cfg));
    savePresetLiveFilters();
  } catch (e) {
    console.warn('[tpConfig] persist failed:', e.message);
  }
  // Clear the computeEffectiveRR warning rate-limiter: any config change may
  // have fixed a misconfiguration (or produced a new one with different inputs),
  // so the user needs to see a fresh signal rather than stale silence.
  _computeRRWarningsEmitted.clear();
  // Dashboard re-render: every tpConfig mutation flows through here, so this
  // is the single leverage point to refresh widgets after a mode / tpCount /
  // partials / targets change. Matches the setBE / applyPreset pattern.
  // Guarded because render() is declared later in the file and may not yet
  // exist during very-early calls (none today, but cheap insurance).
  try { if (typeof render === 'function') render(); } catch (e) {
    console.warn('[tpConfig] re-render after save failed:', e.message);
  }
  // Sync active-preset badge (header button + chip highlight). Guarded — the
  // function may not exist yet during very-early bootstrap calls.
  try { if (typeof _ppSyncActivePresetBadge === 'function') _ppSyncActivePresetBadge(); } catch (e) {
    console.warn('[tpConfig] preset badge sync failed:', e.message);
  }
  // ORR badge depends on tpConfig.mode (anchor prefix in Fixed) — sync along.
  try { if (typeof _rrSyncActiveFilterBadge === 'function') _rrSyncActiveFilterBadge(); } catch (e) {
    console.warn('[tpConfig] ORR badge sync failed:', e.message);
  }
  // Refresh Compare Presets table if its section is open — it computes per-
  // preset stats with each preset's tpConfig, so a TPM change must re-render
  // both columns to reflect the new active preset's TPM.
  try {
    if (_presetCmpOpen && typeof runPresetCompare === 'function') {
      runPresetCompare();
    }
  } catch (e) {
    console.warn('[tpConfig] preset compare refresh failed:', e.message);
  }
}

// tpConfig is now scoped per-preset. The default global value is initialized
// to a fixed default; applyPreset (and the boot tail hydration in the load
// handler) will swap it in/out from the active preset's live slot. Mirror of
// the rrMinFilter pattern.
appState.ui.tpConfig = _defaultTpConfig();
function _normSession(s) { return _SESSION_MAP[(s||'').toLowerCase().trim()]||s||''; }
function _normDay(s)     { return _DAY_MAP[(s||'').toLowerCase().trim()]||s||''; }
function _isBadFeeling(v){ return (v||'').toLowerCase().trim()==='yes'; }
function _colLast(headers, name) {
  let last=-1;
  headers.forEach((h,i)=>{ if(h.trim().toLowerCase()===name.toLowerCase()) last=i; });
  return last;
}
function _colFirst(headers, name) {
  return headers.findIndex(h=>h.trim().toLowerCase()===name.toLowerCase());
}
function _colAny(headers, ...names) {
  for (const name of names) {
    const i = _colFirst(headers, name);
    if (i >= 0) return i;
  }
  return -1;
}

function _normalizeHourKey(value) {
  return String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const _HOUR_HEADER_ALIASES = new Set([
  'hour',
  'heure',
  'time',
  'time utc 1',
  'time utc 2',
  'hour 1',
  'hour 2',
  'utc 1',
  'utc 2',
  'cet',
  'cest',
  'paris time',
  'heure paris',
]);

function _looksLikeHourHeader(value) {
  const normalized = _normalizeHourKey(value);
  if (!normalized) return false;
  if (_HOUR_HEADER_ALIASES.has(normalized)) return true;
  return (
    /(hour|heure|time)/.test(normalized) &&
    /(utc|cet|cest|paris|gmt)/.test(normalized)
  );
}

function _findHourColumnIndex(headers) {
  for (let i = 0; i < headers.length; i++) {
    if (_looksLikeHourHeader(headers[i])) return i;
  }
  return -1;
}

function _parseHourValue(raw) {
  if (raw == null) return null;
  if (typeof raw === 'number' && Number.isFinite(raw)) {
    const hour = Math.trunc(raw);
    return hour >= 0 && hour <= 23 ? hour : null;
  }
  if (typeof raw === 'object') {
    if (Array.isArray(raw)) {
      for (const item of raw) {
        const parsed = _parseHourValue(item);
        if (parsed != null) return parsed;
      }
      return null;
    }
    if ('name' in raw) return _parseHourValue(raw.name);
    if ('value' in raw) return _parseHourValue(raw.value);
    if ('plain_text' in raw) return _parseHourValue(raw.plain_text);
    if ('text' in raw) return _parseHourValue(raw.text);
  }
  const value = String(raw).trim();
  if (!value) return null;
  const timeMatch = value.match(/(?:^|[t\s])([01]?\d|2[0-3])[:h][0-5]\d(?:[:][0-5]\d)?(?:\b|z|[+-]\d{2}:?\d{2})/i);
  if (timeMatch) return parseInt(timeMatch[1], 10);
  const explicitHourMatch = value.match(/^(?:hour|heure|time)?\s*([01]?\d|2[0-3])\s*(?:h|:00)?$/i);
  if (explicitHourMatch) return parseInt(explicitHourMatch[1], 10);
  return null;
}

function _extractTradeHour(trade) {
  if (!trade || typeof trade !== 'object') return null;
  const candidates = [
    trade.hour,
    trade.timeUtc1,
    trade.timeUtcPlus1,
    trade.timeUtc2,
    trade.timeUtcPlus2,
    trade.timeCet,
    trade.timeCest,
    trade['Hour'],
    trade['Heure'],
    trade['Time (UTC+1)'],
    trade['Time (UTC+2)'],
    trade['Hour +1'],
    trade['Hour +2'],
  ];
  for (const candidate of candidates) {
    const parsed = _parseHourValue(candidate);
    if (parsed != null) return parsed;
  }
  for (const [key, value] of Object.entries(trade)) {
    if (!_looksLikeHourHeader(key)) continue;
    const parsed = _parseHourValue(value);
    if (parsed != null) return parsed;
  }
  return null;
}


