function _getRawAPICache(source = null) {
  const src = source || _getCurrentHTFSource();
  const slot = _getProfileScopedSourceSlot(src);
  if (Array.isArray(_rawAPICacheMemory[slot]) && _rawAPICacheMemory[slot].length) {
    return _rawAPICacheMemory[slot];
  }
  // In-memory cache empty (page reloaded) — restore from sessionStorage.
  const session = _loadRawAPIFromSession(src);
  if (session) {
    _rawAPICacheMemory[slot] = session;
    return session;
  }
  return [];
}
function _setRawAPICache(rawTrades, source = null, options = {}) {
  const src = source || _getCurrentHTFSource();
  const slot = _getProfileScopedSourceSlot(src);
  if (Array.isArray(rawTrades)) {
    _rawAPICacheMemory[slot] = rawTrades;
    // Persist field names for the Mapping-tab picker.
    try {
      const names = _listAPIKeys(rawTrades);
      debugLog('[DashboardDebug]');
      debugLog('[DashboardDebug]');
      safeSetLocalStorage(_fieldNamesKeyFor(src), JSON.stringify(names), {
        kind: 'apiFieldNames',
        activeProfileId: getActiveJournalProfile()?.id || '',
        activeHtfSource: src,
      });
    } catch (e) { console.warn('[DS] FieldNames persist failed:', e.message); }
    // Persist raw trades to sessionStorage so custom widget fields survive
    // page reload (raw cache was in-memory only — widgets showed "no data"
    // after refresh because _getRawAPICache() returned empty).
    _persistRawAPIToSession(rawTrades, src);
    // ── Cross-device propagation (Task #3.10) ──
    // Schedule a debounced upload of the raw payload to Supabase Storage so a
    // fresh device can hydrate _rawAPICacheMemory at boot without a Sync.
    // options.fromBlobDownload skips the upload to avoid the immediate-loop
    // we'd get when the raw was JUST downloaded from the bucket. We resolve
    // the profile id via _getJournalProfileCacheContext (NOT via
    // getActiveJournalProfile) so the scheduler's later slot lookup
    // (_rawAPICacheMemory[`<src>_<profileId>`]) hits the same slot we just
    // wrote to (via _getProfileScopedSourceSlot above). Skips for `__demo`
    // — demo data never crosses devices.
    if (!options.fromBlobDownload && rawTrades.length) {
      const { profileId: ctxProfileId } = _getJournalProfileCacheContext();
      if (ctxProfileId && ctxProfileId !== '__demo') {
        _scheduleRawBlobUpload(ctxProfileId, src);
      }
    }
  }
  // If the Journal panel is open, refresh its field count right away so the
  // "loading fields…" placeholder never sticks after a background API fetch.
  if (typeof journalPanelOpen !== 'undefined' && journalPanelOpen) {
    try { updateJournalPanel(); } catch (e) {}
  }
}

// One-time migration: copy only old keys that were already scoped to the same
// profile. Never copy bare source keys (apiFieldOverrides_v1_m15/_h4), because
// those can belong to a different profile and would contaminate M15/H4 mappings.
function _migrateFieldOverridesToProfileScope() {
  const { profileId } = _getJournalProfileCacheContext();
  if (!profileId) return;
  const newKey = _fieldOverridesKeyFor();
  debugLog('[DashboardDebug]');
  if (localStorage.getItem(newKey) !== null) {
    debugLog('[DashboardDebug]');
    return; // already migrated
  }
  const src = localStorage.getItem(HTF_SOURCE_KEY) || 'm15';
  const oldScopedKey = `apiFieldOverrides_v1_${profileId}_${src}`;
  const oldBareKey = `apiFieldOverrides_v1_${src}`;
  const candidate = localStorage.getItem(oldScopedKey);
  if (candidate) {
    try {
      localStorage.setItem(newKey, candidate);
      debugLog('[DashboardDebug]');
    } catch (e) { console.warn('[Mapping] migration failed:', e.message); }
  } else {
    debugLog('[DashboardDebug]');
  }
  // Same for field names
  const newNamesKey = _fieldNamesKeyFor();
  if (localStorage.getItem(newNamesKey) === null) {
    const oldScopedNamesKey = `apiFieldNames_v1_${profileId}_${src}`;
    const oldBareNamesKey = `apiFieldNames_v1_${src}`;
    const namesCandidate = localStorage.getItem(oldScopedNamesKey);
    if (namesCandidate) {
      try {
        localStorage.setItem(newNamesKey, namesCandidate);
        debugLog('[DashboardDebug]');
      } catch (e) { console.warn('[Mapping] migration names failed:', e.message); }
    } else {
      debugLog('[DashboardDebug]');
    }
  }
}

// ── API field overrides — { setup: 'm15Type', session: 'sessionUtc', ... } ──
function _getAPIFieldOverrides(_source = null) {
  // _source ignored — overrides are per-profile, not per-source
  const { profileId } = _getJournalProfileCacheContext();
  const key = _fieldOverridesKeyFor();
  debugLog('[DashboardDebug]');
  try {
    const parsed = JSON.parse(localStorage.getItem(key) || '{}');
    debugLog('[DashboardDebug]');
    return (parsed && typeof parsed === 'object') ? parsed : {};
  } catch { return {}; }
}
function _saveAPIFieldOverrides(obj) {
  const key = _fieldOverridesKey();
  debugLog('[DashboardDebug]');
  try { safeSetLocalStorage(key, JSON.stringify(obj || {}), { kind: 'apiFieldOverrides' }); }
  catch (e) { console.warn('[DS] API overrides save failed:', e.message); }
  try { _clearNotionSyncCursor(); } catch (e) {}
  // Mapping just changed — the parsed-trades cache was normalized against
  // the previous mapping and is now stale. Wipe it so callers that follow
  // up with _reapplyAPIOverrides() / _loadNotionTrades rewrite it fresh,
  // and so future boots that find no cache fall through to a fresh sync
  // instead of rendering stale normalization (the legacy-profile bug from
  // 2026-05-21: profiles synced before a template fix kept h4: [] until a
  // manual force-sync). All current callers re-render synchronously, so
  // the invalidate-then-rewrite window is microseconds in the happy path.
  try { _invalidateNormalizedTradesCache(null, 'overrides-saved'); } catch (e) {}
}

// Wipe the parsed-trades cache (LS + sessionStorage + in-memory) for a
// profile across both HTF sources. Hooked from _saveAPIFieldOverrides so
// every mapping change — template auto-mapping, manual pencil-pick,
// Re-apply template defaults, TP backfill, screenshot auto-map — leaves
// the cache state consistent with the new mapping. _clearNotionProfileMappings
// also calls it directly for the database-change path (which bypasses
// _saveAPIFieldOverrides by deleting the LS key directly).
//
// Re-render is the caller's job. _reapplyAPIOverrides (pickAPIField path,
// _reapplyTemplateMapping) re-normalizes from in-memory raw trades and
// rewrites the cache immediately. _loadNotionTrades does the same in the
// sync path. If neither runs (e.g. user closes the tab between an override
// write and any re-render), the next boot's getCachedAPIData() returns null
// and the boot path falls through to a fresh sync — the desired self-heal.
function _invalidateNormalizedTradesCache(profileId = null, reason = 'mapping-change') {
  const id = String(profileId || _getJournalProfileCacheContext()?.profileId || '').trim();
  if (!id) return;
  const sources = ['m15', 'h4'];
  let purged = 0;
  for (const src of sources) {
    const lsKey = `apiTradesCache_v2_rrmax_${id}_${src}`;
    try {
      if (localStorage.getItem(lsKey) !== null) {
        localStorage.removeItem(lsKey);
        purged++;
      }
    } catch (e) {}
    const sessKey = `apiTradesSessionCache_v1_${id}_${src}`;
    try { sessionStorage.removeItem(sessKey); } catch (e) {}
    const slot = `${src}_${id}`;
    if (_parsedAPICacheMemory[slot]) _parsedAPICacheMemory[slot] = null;
  }
  if (purged) debugLog('[CacheInvalidation] parsed cache purged for profile', id, '· reason:', reason, '· slots:', purged);
}

// Collect every top-level key ever observed across the raw trades.
// When called with a non-empty rawTrades, computes freshly from them (the
// authoritative source during a live fetch). When rawTrades is empty (post-
// reload, no fetch yet), falls back to the persisted apiFieldNames_v1 so the
// Mapping-tab picker still works without requiring a network round-trip.
function _listAPIKeys(rawTrades) {
  const arr = Array.isArray(rawTrades) ? rawTrades : [];
  if (arr.length) {
    // Only keep keys that have at least one non-null, non-empty value across
    // the dataset. This filters out M15-specific fields (all null in H4)
    // and H4-specific fields (all null in M15) from the mapping panel.
    const hasValue = {};
    for (const t of arr) {
      if (!t || typeof t !== 'object' || Array.isArray(t)) continue;
      for (const [k, v] of Object.entries(t)) {
        if (hasValue[k]) continue;
        if (v === null || v === undefined || v === '') continue;
        if (Array.isArray(v) && v.length === 0) continue;
        hasValue[k] = true;
      }
    }
    return Object.keys(hasValue).sort((a, b) => a.localeCompare(b));
  }
  try {
    const { profileId: _fnProfileId } = _getJournalProfileCacheContext();
    const key = _fieldNamesKeyFor();
    debugLog('[DashboardDebug]');
    const parsed = JSON.parse(localStorage.getItem(key) || '[]');
    debugLog('[DashboardDebug]');
    return Array.isArray(parsed)
      ? parsed.slice().sort((a, b) => a.localeCompare(b))
      : [];
  } catch { return []; }
}

// Re-normalize the raw cache with current overrides and re-inject if in API mode.
// Raw cache lives in memory only (Phase 3.A quota fix). If the user remaps a
// field after a page reload (no in-memory raw), we can't re-normalize locally
// — trigger a fresh fetch instead. The fetch writes both the parsed cache and
// apiFieldNames_v1, and calls _injectTrades on completion (see
// _fetchAPICacheSilently's success path).
// Pre-inject user-mapped outcome field as `positionResult` before normalization.
// _normalizeAPITrade does not use _pick() for the outcome — it reads a hardcoded
// set of fallback keys. When the user overrides 'outcome' via the mapping UI,
// this wrapper bridges the gap so _reapplyAPIOverrides + _loadNotionTrades both
// benefit from the same mapping without touching _normalizeAPITrade.
function _applyOutcomeOverride(trades, source) {
  return _applyMappedFieldAliases(trades, source);
}

function _copyMappedAliasPatch(t, overrides, dimKey, aliasKey) {
  const field = overrides && overrides[dimKey];
  if (!field || (typeof _isNoMappingValue === 'function' && _isNoMappingValue(field))) return null;
  if (!t || typeof t !== 'object' || !(field in t)) return null;
  const existing = t[aliasKey];
  if (existing !== null && existing !== undefined && existing !== '' && !(Array.isArray(existing) && !existing.length)) return null;
  return { [aliasKey]: t[field] };
}

// Bridge user mappings into the raw aliases that _normalizeAPITrade reads
// directly. This keeps _normalizeAPITrade unchanged while allowing remaps for
// hard-coded fields such as date, rrMax, order and positionResult.
function _applyMappedFieldAliases(trades, source) {
  if (!trades || !trades.length) return trades;
  const activeSource = source || _getCurrentHTFSource();
  const ov = (typeof _getAPIFieldOverrides === 'function') ? _getAPIFieldOverrides(activeSource) : {};
  const setupDetailAlias = activeSource === 'h4' ? 'h4TypeDetail' : 'm15TypeDetail';
  return trades.map(t => {
    if (!t || typeof t !== 'object') return t;
    const patch = {
      ...(_copyMappedAliasPatch(t, ov, 'outcome', 'positionResult') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'date', 'date') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'rrMax', 'rrMax') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'direction', 'order') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'pair', 'pair') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'setupDetail', setupDetailAlias) || {}),
      ...(_copyMappedAliasPatch(t, ov, 'setup', activeSource === 'h4' ? 'm15Type' : 'm15Type') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'h4', 'obstaclesH4') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'obstacles', activeSource === 'h4' ? 'obstaclesH4' : 'obstaclesM15') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'beManagement', 'beManagement') || {}),
      ...(_copyMappedAliasPatch(t, ov, 'tp1_rr', 'rrTp1') || {}),
    };
    return Object.keys(patch).length ? { ...t, ...patch } : t;
  });
}

function _resolveNotionAlias(sample, candidates) {
  if (!sample || typeof sample !== 'object') return null;
  return candidates.find(k => {
    if (!(k in sample)) return false;
    const v = sample[k];
    return v !== null && v !== undefined && v !== '' && !(Array.isArray(v) && !v.length);
  }) || null;
}

function _applyResolvedAlias(aliasMap, alias, sample, candidates) {
  if (alias in sample) {
    const existing = sample[alias];
    if (existing !== null && existing !== undefined && existing !== '' && !(Array.isArray(existing) && !existing.length)) return;
  }
  const resolved = _resolveNotionAlias(sample, candidates);
  if (resolved) aliasMap[alias] = resolved;
}

function _applyH4NotionAliases(aliasMap, sample) {
  _applyResolvedAlias(aliasMap, 'h4TypeDetail', sample, [
    'setupDetail', 'H4 Type Detailed', 'h4TypeDetailed', 'h4TypeDetail', 'h4TypeDetails',
    'setup', 'Position Type', 'positionType',
  ]);
  _applyResolvedAlias(aliasMap, 'm15Type', sample, [
    'setup', 'H4 Type Detailed', 'h4TypeDetailed', 'h4TypeDetail', 'setupDetail',
    'Position Type', 'positionType',
  ]);
  _applyResolvedAlias(aliasMap, 'obstaclesH4', sample, [
    'h4', 'structure', 'H4 Structure', 'h4Structure',
    'h4Obstacles', 'obstaclesH4', 'H4 Obstacles', 'obstacles',
  ]);
}

function _applyCommonNotionAliases(aliasMap, sample) {
  _applyResolvedAlias(aliasMap, 'date', sample, ['Date Start', 'dateStart', 'Date', 'date']);
  _applyResolvedAlias(aliasMap, 'beManagement', sample, ['beManagement', 'BE Management']);
  _applyResolvedAlias(aliasMap, 'rrMax', sample, ['rrMax', 'RR Max', 'RR Max ', 'rrMaxAtteint', 'RR max atteint']);
  _applyResolvedAlias(aliasMap, 'pair', sample, ['pair', 'Pair', 'paire', 'Paire']);
  _applyResolvedAlias(aliasMap, 'order', sample, ['order', 'Order']);
  _applyResolvedAlias(aliasMap, 'rrTp1', sample, ['rr', 'tp', 'RR TP 1', 'rrTp1', 'RR Max', 'rrMax']);
}

// ── Flipping Market shipped templates — auto-mapping ─────────────────────
// Five Notion templates distributed in the "Flipping Market Templates" page
// share schema fingerprints (column-name presence + select-option values).
// When a community user OAuth-connects a Notion DB matching one of them, we
// inject the canonical override mapping into apiFieldOverrides_v1_<profile>
// so they don't have to manually map dimensions. Detection runs on the
// first sync only — any existing user overrides short-circuit the auto-apply.

const TEMPLATE_LABELS = {
  'm15-pro':  'Flipping Market M15 (Pro Template)',
  'm15-beg':  'Flipping Market M15 (Beginner)',
  'm15-free': 'Flipping Market M15 (Free Notion version)',
  'h4-pro':   'Flipping Market H4 (Pro Template)',
  'h4-beg':   'Flipping Market H4 (Beginner)',
};

// Canonical dimKey → Notion column name. '__NO_MAPPING__' = explicit
// no-mapping (the dim is irrelevant for this template; the Mapping panel
// hides it from view by default).
const TEMPLATE_MAPPINGS = {
  'm15-pro': {
    outcome: 'Position Result', r: 'RR TP 1', date: 'Date', pair: 'Pair ',
    setup: 'M15 Confirmation / Continu', setupDetail: 'M15 Type Detailed',
    session: 'Session', day: 'Day Formula',
    obstacles: 'M15 Obstacles', h4: 'H4 Obstacles',
    beManagement: 'BE Management', hour: 'Time',
    positionType: 'Position Type', direction: 'Order',
    rrMax: 'RR Max', badFeeling: 'Bad feeling', notionUrl: 'Notion Url',
    img_m15: 'URL M15 Before', img_h4_before: 'URL H4 Before', img_m15_after: 'URL M15 After',
    tp1_rr: 'RR TP 1', tp2_rr: 'RR TP -27', tp3_rr: 'RR Trailing',
  },
  'm15-beg': {
    outcome: 'Position Result', r: 'RR TP 1', date: 'Date', pair: 'Pair ',
    setup: 'M15 Confirmation / Continu', setupDetail: 'M15 Type Detailed',
    session: '__NO_MAPPING__', day: 'Day Formula',
    obstacles: 'M15 Obstacles', h4: '__NO_MAPPING__',
    beManagement: 'BE Management', hour: '__NO_MAPPING__',
    positionType: 'Position Type', direction: 'Order',
    rrMax: 'RR max', badFeeling: 'Bad feeling', notionUrl: 'Notion URL',
    img_m15: 'URL M15 Before', img_h4_before: 'URL H4 Before', img_m15_after: 'URL M15 After',
    tp1_rr: 'RR TP 1', tp2_rr: 'RR TP -27', tp3_rr: 'RR Trailing',
  },
  'm15-free': {
    outcome: 'Result', r: 'RR TP 1', date: 'Date', pair: 'Pair ',
    setup: 'M15 Confirmation / Continu', setupDetail: 'M15 Type Detailed',
    session: '__NO_MAPPING__', day: 'Day Formula',
    obstacles: 'M15 Obstacles', h4: '__NO_MAPPING__',
    beManagement: 'BE Management', hour: '__NO_MAPPING__',
    positionType: 'Account', direction: 'Order',
    rrMax: 'RR max', badFeeling: 'Bad feeling', notionUrl: 'Notion URL',
    img_m15: 'M15', img_h4_before: 'URL H4 Before', img_m15_after: 'URL M15 After',
  },
  'h4-pro': {
    outcome: 'Position Result', r: 'RR TP 1', date: 'Date', pair: 'Pair ',
    setup: 'H4 Confirmation / Continu', setupDetail: 'H4 Type Detailed',
    session: '__NO_MAPPING__', day: 'Day Formula',
    obstacles: '__NO_MAPPING__', h4: 'H4 Obstacles',
    beManagement: 'BE Management', hour: '__NO_MAPPING__',
    positionType: 'Position type', direction: 'Order',
    rrMax: 'RR max', badFeeling: 'Bad feeling', notionUrl: 'Notion URL',
    img_m15: '__NO_MAPPING__', img_h4_before: 'URL H4 Before', img_m15_after: 'URL H4 After',
    tp1_rr: 'RR TP 1', tp2_rr: 'RR TP -27', tp3_rr: 'RR Trailing',
  },
  'h4-beg': {
    outcome: 'Position Result', r: 'RR TP 1', date: 'Date', pair: 'Pair ',
    setup: 'H4 Confirmation / Continu', setupDetail: 'H4 Type Detailed',
    session: '__NO_MAPPING__', day: 'Day Formula',
    obstacles: '__NO_MAPPING__', h4: 'H4 Obstacles',
    beManagement: 'BE Management', hour: '__NO_MAPPING__',
    positionType: 'Position type', direction: 'Order',
    rrMax: 'RR max', badFeeling: 'Bad feeling', notionUrl: 'Notion URL',
    img_m15: '__NO_MAPPING__', img_h4_before: 'URL H4 Before', img_m15_after: 'URL H4 After',
    tp1_rr: 'RR TP 1', tp2_rr: 'RR TP -27', tp3_rr: 'RR Trailing',
  },
  // "Other" bucket — partial mapping, only the dims the user explicitly
  // opted out of. Chunk B will run the existing _detectTemplate first; if
  // it matches one of the 5 Flipping templates above, that template's
  // mapping is applied, THEN these exclusions overlay on top so the 4
  // opted-out dims always end up __NO_MAPPING__ regardless. If detect
  // returns null, only these exclusions are written (the user pencils the
  // rest manually). Aligned with TEMPLATE_LAYOUTS.other which removes the
  // widgets that consume these 3 dims (w-hour, w-m15, w-h4) — badFeeling
  // has no widget but is excluded by user request too.
  other: {
    obstacles:    '__NO_MAPPING__',
    h4:           '__NO_MAPPING__',
    badFeeling:   '__NO_MAPPING__',
    hour:         '__NO_MAPPING__',
  },
};

// Cheap title heuristic to pre-fill the Template <select> at DB-pick time.
// Cannot reuse _detectTemplate here: that one fingerprints actual trade
// VALUES (e.g. "External Fib Touched") and the DB picker only exposes
// {id, title} per database. Word-boundary regex avoids false positives
// like "M152" or "h4beg". Manual override remains the source of truth —
// this is just a suggestion, the user can still change the select.
function _inferTemplateBucketFromTitle(title) {
  const s = String(title || '').toLowerCase();
  if (/\bm15\b/.test(s)) return 'm15';
  if (/\bh4\b/.test(s)) return 'h4';
  return 'other';
}

const DETECTED_TEMPLATE_LS_PREFIX = 'flipping_detected_template_v1';
function _getDetectedTemplate() {
  // Read live from the active profile's DB title rather than the LS cache.
  // The LS is still written by sync-time auto-apply for backward compat
  // (and as a record of what was applied), but reading from it lagged
  // behind any DB title change until the next sync — the banner would
  // show a stale label even after the title was corrected. Title-based
  // reads make the banner always reflect today's truth.
  try {
    const profile = (typeof getActiveJournalProfile === 'function') ? getActiveJournalProfile() : null;
    if (!profile) return null;
    return _detectTemplateFromTitle(profile.notionDatabaseTitle);
  } catch (e) { return null; }
}
function _setDetectedTemplate(id) {
  try {
    const key = getProfileScopedKey(DETECTED_TEMPLATE_LS_PREFIX);
    if (id) localStorage.setItem(key, id); else localStorage.removeItem(key);
  } catch (e) {}
}

// Set of dim keys whose override was written by template auto-mapping
// (not by an explicit user pencil-pick). Rendered with green status in the
// Mapping panel — same visual as `is-ok` (auto-detected via canonical name)
// because both are "no user action needed". Blue/gold `is-remapped` stays
// reserved for dims the user actively customised. Cleared per-dim on user
// pencil-pick, fully cleared on Reset all overrides / database change.
const AUTO_MAPPED_DIMS_LS_PREFIX = 'flipping_auto_mapped_dims_v1';
function _getAutoMappedDims() {
  try {
    const raw = localStorage.getItem(getProfileScopedKey(AUTO_MAPPED_DIMS_LS_PREFIX));
    if (!raw) return new Set();
    const arr = JSON.parse(raw);
    return new Set(Array.isArray(arr) ? arr.filter(x => typeof x === 'string') : []);
  } catch (e) { return new Set(); }
}
function _setAutoMappedDims(set) {
  try {
    const key = getProfileScopedKey(AUTO_MAPPED_DIMS_LS_PREFIX);
    const arr = Array.from(set || []);
    if (arr.length) localStorage.setItem(key, JSON.stringify(arr));
    else localStorage.removeItem(key);
  } catch (e) {}
}
function _removeAutoMappedDim(dimKey) {
  if (!dimKey) return;
  const s = _getAutoMappedDims();
  if (s.has(dimKey)) { s.delete(dimKey); _setAutoMappedDims(s); }
}
function _clearAutoMappedDims() {
  try { localStorage.removeItem(getProfileScopedKey(AUTO_MAPPED_DIMS_LS_PREFIX)); } catch (e) {}
}

// Seed gs_layout_active_<profileId> + gs_hidden_widgets_<profileId> from
// TEMPLATE_LAYOUTS[choice] on profile creation, so the dashboard grid
// renders with the user-chosen template layout from the very first
// activation — no waiting for a sync, no flash of the canonical default.
//
// Storage shape mirrors a "slot" payload (_loadSectionSlot): per-section
// {x,y,w,h,minW,minH} per widget + hiddenWidgets embedded + dynamicWidgets
// empty. The dedicated gs_hidden_widgets_<profileId> sidecar is also
// written because _loadSectionSlot intentionally ignores the embedded
// hiddenWidgets in favor of the standalone key (per the comment in that
// fn — "single source of truth").
//
// Guards: only writes when the LS keys don't already exist (defensive — a
// fresh profile shouldn't have them, but doesn't hurt). No-op when
// TEMPLATE_LAYOUTS doesn't have the bucket (shouldn't happen since we
// hardcode all 3 buckets, but keeps the function tolerant if a future
// templateChoice value sneaks through normalisation).
function _applyTemplateLayoutsForProfile(profile) {
  if (!profile?.id || !profile?.templateChoice) return;
  const layout = (typeof TEMPLATE_LAYOUTS !== 'undefined') ? TEMPLATE_LAYOUTS[profile.templateChoice] : null;
  if (!layout) return;
  const slotPayload = {
    global:        { ...(layout.global || {}) },
    'optimal-rr':  { ...(layout['optimal-rr'] || {}) },
    partials:      { ...(layout.partials || {}) },
    hiddenWidgets: { ...(layout.hiddenWidgets || {}) },
    dynamicWidgets: [],
  };
  const layoutKey = `gs_layout_active_${profile.id}`;
  const hiddenKey = `gs_hidden_widgets_${profile.id}`;
  try {
    if (!localStorage.getItem(layoutKey)) {
      localStorage.setItem(layoutKey, JSON.stringify(slotPayload));
    }
    if (!localStorage.getItem(hiddenKey) && Object.keys(slotPayload.hiddenWidgets).length) {
      localStorage.setItem(hiddenKey, JSON.stringify(slotPayload.hiddenWidgets));
    }
    debugLog('[TemplateLayout] seeded:', profile.templateChoice, '→', layoutKey, '+', hiddenKey);
  } catch (e) {
    console.error('[TemplateLayout] LS write failed:', e);
  }
}

// Fingerprint a Notion DB against the 5 shipped templates from its TITLE.
// Returns the matched template id, or null when the title doesn't carry
// enough signal. We deliberately use the title (not columns/options)
// because (a) the 5 canonical templates ship with stable canonical names
// ("Flipping M15 Pro", "Flipping H4 Beginner", etc.), and (b) title-based
// matching is synchronous, predictable, and survives schema drift.
//
// Strict adjacency: the qualifier (pro / beg / free) must come DIRECTLY
// after m15/h4 (separated only by space, dash, colon, or parens). This
// avoids the trap where a title like "Flipping M15 Pro - beginner-friendly
// edition" would mis-fire to Beginner because "beg" exists somewhere in
// the string. Only if no adjacent qualifier is found do we fall back to a
// looser global scan, prioritising Pro over Beg.
function _detectTemplateFromTitle(title) {
  const s = String(title || '').toLowerCase();
  // 1. Strict adjacent qualifier — most reliable.
  if (/\bm15[\s\-:()]+pro\b/.test(s))           return 'm15-pro';
  if (/\bm15[\s\-:()]+beg(?:inner)?\b/.test(s)) return 'm15-beg';
  if (/\bm15[\s\-:()]+free\b/.test(s))          return 'm15-free';
  if (/\bh4[\s\-:()]+pro\b/.test(s))            return 'h4-pro';
  if (/\bh4[\s\-:()]+beg(?:inner)?\b/.test(s))  return 'h4-beg';
  // 2. Title contains m15/h4 but no adjacent qualifier — fall back to a
  // whole-title scan, prioritising Pro over Beg so a stray "beginner"
  // somewhere doesn't downgrade a Pro template.
  if (/\bm15\b/.test(s)) {
    if (/\bfree\b/.test(s))           return 'm15-free';
    if (/\bpro\b/.test(s))            return 'm15-pro';
    if (/\bbeg(?:inner)?\b/.test(s))  return 'm15-beg';
    return 'm15-pro';
  }
  if (/\bh4\b/.test(s)) {
    if (/\bpro\b/.test(s))            return 'h4-pro';
    if (/\bbeg(?:inner)?\b/.test(s))  return 'h4-beg';
    return 'h4-pro';
  }
  return null;
}

// First-connect hook — write canonical overrides iff the user has none yet.
// Returns the matched template id (or null) so the caller can log/banner.
//
// IMPORTANT: detection + _setDetectedTemplate run on EVERY sync (not just
// the first one) so the Mapping banner stays in sync with the live DB
// schema. The override write still short-circuits when the user already
// has mappings — we never clobber user customisation. Without this, a
// profile that was first-synced before a detection-logic fix kept the
// stale template id forever (the banner lied about what the DB actually
// looks like today).
function _maybeAutoApplyTemplateMapping(rawTrades, profileOverride = null) {
  // Respect the explicit bucket the user picked at profile creation. Three
  // possible values on profile.templateChoice : 'm15' / 'h4' / 'other'.
  // Existing profiles created before the chooser default to 'other' via
  // _normalizeJournalProfile (no change to behavior).
  //
  // profileOverride is THE essential argument when called from inside
  // _loadNotionTrades — without it, this function would read
  // getActiveJournalProfile() which can race when the user switches profiles
  // mid-sync (fetch resolves AFTER the user has moved on, helper would
  // happily apply the now-active profile's template choice to the old
  // profile's overrides, corrupting both). The override is null for
  // user-driven callers (_reapplyTemplateMapping) where getActiveJournalProfile
  // is the truly-correct source.
  const profile = profileOverride || getActiveJournalProfile();
  const bucket = profile?.templateChoice || 'other';
  // Title-based detection — see _detectTemplateFromTitle. The rawTrades
  // param is preserved for signature stability (some call sites still
  // pass it) but the fingerprint comes from profile.notionDatabaseTitle.
  void rawTrades;
  const detected = _detectTemplateFromTitle(profile?.notionDatabaseTitle);
  let mapping = null;
  let trackingId = detected;
  let mismatchToast = '';
  if (bucket === 'm15') {
    // User explicitly picked Flipping M15. Honor the detection if it
    // narrowed to one of the 3 M15 variants; otherwise force m15-pro
    // (the most complete M15 mapping) and warn via toast — but only if
    // we actually write overrides (no spam on every re-sync).
    if (detected && detected.startsWith('m15-')) {
      mapping = TEMPLATE_MAPPINGS[detected];
      trackingId = detected;
    } else {
      mapping = TEMPLATE_MAPPINGS['m15-pro'];
      trackingId = 'm15-pro';
      mismatchToast = 'Database does not look like Flipping M15 — applied M15 Pro defaults. Adjust via the Mapping panel if needed.';
    }
  } else if (bucket === 'h4') {
    // Symmetric for H4. h4-pro/h4-beg share the same mapping anyway, so
    // the fallback to h4-pro is essentially canonical for the bucket.
    if (detected && detected.startsWith('h4-')) {
      mapping = TEMPLATE_MAPPINGS[detected];
      trackingId = detected;
    } else {
      mapping = TEMPLATE_MAPPINGS['h4-pro'];
      trackingId = 'h4-pro';
      mismatchToast = 'Database does not look like Flipping H4 — applied H4 Pro defaults. Adjust via the Mapping panel if needed.';
    }
  } else {
    // "Other" bucket: no forced template. Apply detected mapping if any,
    // then overlay TEMPLATE_MAPPINGS.other on top so the 4 opted-out dims
    // (obstacles, h4, badFeeling, hour) always end up __NO_MAPPING__
    // regardless of what was detected. If nothing was detected, write
    // only the exclusions (the user pencils the rest manually).
    if (detected) {
      mapping = { ...TEMPLATE_MAPPINGS[detected], ...TEMPLATE_MAPPINGS.other };
      trackingId = detected;
    } else {
      mapping = { ...TEMPLATE_MAPPINGS.other };
      trackingId = 'other';
    }
  }

  // Always refresh the detected-template LS so the Mapping banner reflects
  // the CURRENT sync — even when overrides already exist and we won't
  // re-write them. This fixes a class of bugs where the banner kept showing
  // a stale "Auto-detected: <X>" forever after the first sync.
  _setDetectedTemplate(trackingId);

  // Short-circuit override writing if the user already has mappings —
  // never overwrite user customisation. Banner update above still happens.
  const existing = _getAPIFieldOverrides();
  if (existing && Object.keys(existing).length > 0) {
    // Backfill exception: tp1_rr / tp2_rr / tp3_rr were added to the
    // Flipping templates after the initial release. Profiles synced
    // before that release have the rest of the mapping but no TP keys.
    // Write just those (never overwrite an existing value) so the user
    // doesn't have to Reset all overrides to get Multi TP pre-mapped.
    if (mapping) {
      const backfillKeys = ['tp1_rr', 'tp2_rr', 'tp3_rr'];
      const merged = { ...existing };
      let didBackfill = false;
      for (const k of backfillKeys) {
        if (!(k in existing) && mapping[k]) {
          merged[k] = mapping[k];
          didBackfill = true;
        }
      }
      if (didBackfill) {
        _saveAPIFieldOverrides(merged);
        const autoSet = _getAutoMappedDims();
        for (const k of backfillKeys) {
          if (merged[k] && !(k in existing)) autoSet.add(k);
        }
        _setAutoMappedDims(autoSet);
        debugLog('[TplDetect] backfilled multi-tp keys for existing profile:', backfillKeys.filter(k => !(k in existing) && merged[k]));
      }
    }
    return trackingId;
  }

  if (!mapping || !Object.keys(mapping).length) return null;
  _saveAPIFieldOverrides({ ...mapping });
  // Tag every dim as "auto-mapped" so the Mapping panel renders them green
  // (is-auto-mapped) instead of blue (is-remapped). The flag is per-dim:
  // when the user manually pencil-picks a dim, its key is removed from the
  // set in `pickAPIField`, which flips it back to is-remapped (blue).
  // EXCLUSION: never tag __NO_MAPPING__ values as auto-mapped. A dim with
  // status `is-auto-no-mapping` is rendered FULLY invisible by
  // _renderMappingSectionsHtml — no row, no footer toggle, no resurrect.
  // For the TEMPLATE_MAPPINGS.other overlay (obstacles/h4/badFeeling/hour
  // forced to __NO_MAPPING__), this meant those 4 dims vanished after every
  // Reapply on a templateChoice='other' profile. Excluding NO_MAPPING from
  // the auto-mapped set demotes them to `is-no-mapping`, which is hidden by
  // default but resurrectable via the "Show N no-mapping fields" footer
  // toggle in each tier section. Repro: Max 2026-05-24.
  const autoMappedKeys = Object.keys(mapping).filter(k => !_isNoMappingValue(mapping[k]));
  _setAutoMappedDims(new Set(autoMappedKeys));
  if (mismatchToast && typeof showThemeToast === 'function') showThemeToast(mismatchToast, false);
  debugLog('[TplDetect] bucket:', bucket, '· detected:', detected, '· applied:', trackingId, '· wrote', Object.keys(mapping).length, 'overrides');
  return trackingId;
}

// ──────────────────────────────────────────────────────────────────────
// Screenshot dims (img_m15 / img_h4_before / img_m15_after) often come in
// from Notion as "Files & Media" properties whose names don't match the
// canonical TEMPLATE_MAPPINGS values (e.g. user has "M15 before" rather
// than "URL M15 Before"). The Vercel proxy normalises every key into a
// camelCase alias _as well as_ keeping the original name, so the raw
// trade payload contains BOTH. _normalizeAPITrade picks the value via a
// hardcoded camelCase fallback chain, but the original Notion column
// name is never written anywhere — and the Mapping panel + lightbox
// modal both rely on the override to know what to label the slot.
//
// Result: with no override, the screenshot row stays "TV Image N" forever
// even though the data is flowing in fine. This pass backfills the
// override for any screenshot dim that's currently empty:
//   1) finds the camelCase alias that has data in the raw sample
//   2) finds the OTHER raw key (containing a space) that holds the same
//      value — that's the original Notion column name
//   3) writes it as the override AND tags the dim auto-mapped (green dot)
//
// Skips dims that already have an override (so it never clobbers a user
// pencil-pick or a previous template auto-detect). Runs alongside
// _maybeAutoApplyTemplateMapping in the sync path — its check is
// independent (overrides[dimKey] per-dim, not a global "any override"
// short-circuit), so it works for the "Other" bucket case where the
// outer auto-apply bailed early.
// ──────────────────────────────────────────────────────────────────────
const _SCREENSHOT_CAMEL_ALIASES = {
  img_m15:       ['imgM15', 'm15Before', 'm15Image', 'imageM15'],
  img_h4_before: ['imgH4Before', 'h4Before', 'h4Image', 'imageH4'],
  // img_m15_after carries the "After" screenshot. M15 profiles get the
  // M15-flavored camel aliases first; H4 profiles repurpose this slot for
  // the H4 After screenshot (see useH4AfterInImgM15After in _normalizeAPITrade)
  // so we also list the H4-flavored aliases. The find() short-circuits on the
  // first alias with data, so M15 profiles still pick the M15 variant and
  // H4 profiles transparently pick the H4 one.
  img_m15_after: ['imgM15After', 'm15After', 'm15AfterImage', 'imgH4After', 'h4After', 'h4AfterImage', 'imageH4After', 'h4ImageAfter'],
};
// Detect what shape a sample value carries:
//   'fm'   = Notion Files & Media — array of { file?: {url}, external?: {url} }.
//            Most reliable source: Notion stores the file, the proxy resigns
//            URLs each fetch, and _mediaQueue migrates Notion S3 URLs to
//            permanent Supabase storage so they survive after the 1h expiry.
//   'url'  = plain URL string (or array of URL strings). Less reliable for
//            screenshots that aren't permanent — but the only viable source
//            when the user pastes a TradingView /x/ share link.
//   null   = neither; ignore for screenshot mapping.
function _classifyScreenshotValue(v) {
  if (v === null || v === undefined || v === '') return null;
  if (Array.isArray(v)) {
    if (!v.length) return null;
    const item = v[0];
    if (typeof item === 'string') return /^https?:\/\//i.test(item.trim()) ? 'url' : null;
    if (item && typeof item === 'object') {
      if ((item.file && typeof item.file.url === 'string') ||
          (item.external && typeof item.external.url === 'string') ||
          typeof item.url === 'string') return 'fm';
    }
    return null;
  }
  if (typeof v === 'string') return /^https?:\/\//i.test(v.trim()) ? 'url' : null;
  if (typeof v === 'object') {
    if ((v.file && typeof v.file.url === 'string') ||
        (v.external && typeof v.external.url === 'string') ||
        typeof v.url === 'string') return 'fm';
  }
  return null;
}

// Per-dim semantic hints used by the name-keyword pass below. Position keys
// are matched as substrings of the lowercased property name. Negative position
// = automatic disqualifier (a "Before" property cannot fill the After slot).
// img_m15_after carries the After slot for both M15 and H4 profiles, so
// the primary keyword set is source-dependent (H4 profiles bias toward 'h4'
// matches first, M15 profiles toward 'm15').
function _getScreenshotDimHints(dimKey, source) {
  if (dimKey === 'img_m15') {
    return { primary: ['m15'], positive: ['before', 'avant'], negative: ['after', 'apres', 'après'] };
  }
  if (dimKey === 'img_h4_before') {
    return { primary: ['h4'], positive: ['before', 'avant'], negative: ['after', 'apres', 'après'] };
  }
  if (dimKey === 'img_m15_after') {
    const prim = source === 'h4' ? ['h4', 'm15'] : ['m15', 'h4'];
    return { primary: prim, positive: ['after', 'apres', 'après'], negative: ['before', 'avant'] };
  }
  return null;
}

// Best-candidate name search. Iterates sample properties, classifies each as
// F&M/URL/none, filters by primary keyword (m15/h4) and disqualifies on the
// negative position keyword (before/after). Scores: F&M (100) >> URL (10),
// + bonus for matching the positive position keyword, + bonus for matching
// the source-preferred primary on the After slot. Returns null if no
// candidate qualifies — caller then falls back to the camel-alias pass.
function _findScreenshotCandidateByName(sample, dimKey, source) {
  const hints = _getScreenshotDimHints(dimKey, source);
  if (!hints) return null;
  let best = null;
  for (const [key, val] of Object.entries(sample)) {
    const kind = _classifyScreenshotValue(val);
    if (!kind) continue;
    const lowKey = key.toLowerCase();
    const primaryIdx = hints.primary.findIndex(k => lowKey.includes(k));
    if (primaryIdx === -1) continue;
    if (hints.negative.some(k => lowKey.includes(k))) continue;
    let score = (kind === 'fm') ? 100 : 10;
    if (hints.positive.some(k => lowKey.includes(k))) score += 5;
    // Source bias for img_m15_after: primary[0] is the source-preferred keyword
    if (dimKey === 'img_m15_after' && primaryIdx === 0) score += 3;
    if (!best || score > best.score) best = { key, score, kind, primaryIdx };
  }
  return best;
}

// Build a "merged sample" by walking every raw trade and recording the FIRST
// non-empty screenshot-classifiable value seen per property name. Without this,
// users whose first trade happens to be missing the H4 After screenshot (but
// later trades have it) would fail the auto-detect: the single-sample scan
// would see an empty array and classify the property as non-screenshot.
// Surfaced 2026-05-22 when Max's H4 perso profile auto-mapped H4 Before
// correctly but left H4 After stuck on the stale 'URL H4 After' template
// default — his first sync'd trade had a Before file but no After file.
// Falls back to the first valid trade's keys for property-existence checks
// (so _overrideIsLiveInSample still recognises empty-but-present columns).
function _buildScreenshotMergedSample(rawTrades) {
  const merged = {};
  const firstTrade = rawTrades.find(t => t && typeof t === 'object' && !Array.isArray(t));
  if (!firstTrade) return null;
  // Pass 1: scan every trade, record first classifiable value per key
  for (const trade of rawTrades) {
    if (!trade || typeof trade !== 'object' || Array.isArray(trade)) continue;
    for (const [key, val] of Object.entries(trade)) {
      if (key in merged) continue;
      if (_classifyScreenshotValue(val)) merged[key] = val;
    }
  }
  // Pass 2: backfill empty-but-present keys from first trade so existence
  // checks still work (used by validation logic to spot stale overrides
  // pointing to columns that exist but never have data).
  for (const key of Object.keys(firstTrade)) {
    if (!(key in merged)) merged[key] = firstTrade[key];
  }
  return merged;
}

function _autoMapScreenshotsByRawKeys(rawTrades, source = null) {
  if (!Array.isArray(rawTrades) || !rawTrades.length) return;
  const sample = _buildScreenshotMergedSample(rawTrades);
  if (!sample) return;
  const effectiveSource = String(source || _getCurrentHTFSource() || 'm15').toLowerCase();
  const overrides = _getAPIFieldOverrides();
  const newAutoKeys = [];
  let changed = false;

  // Two-stage decision per dim:
  //   1) Name-keyword + F&M-preferred pass (handles users with custom DB
  //      schemas, where a Notion Files & Media property carries the actual
  //      screenshot file). F&M wins over URL when both exist for the slot,
  //      because F&M is permanent (via Supabase migration) whereas URL
  //      strings can rot when the TV chart is deleted.
  //   2) Legacy camel-alias pass (proxy-generated aliases like imgM15After /
  //      h4Before). Acts as the fallback when the user's DB uses property
  //      names that don't contain m15/h4 + before/after keywords.
  // Existing override behaviour:
  //   - __NO_MAPPING__ → never touched (intentional opt-out).
  //   - Live F&M override → kept (already the best shape).
  //   - Live URL override → replaced ONLY if a better F&M candidate exists
  //     (the F&M property gives Supabase-backed permanence; the URL might be
  //     a transient TV link).
  //   - Stale override (points to nothing in sample) → replaced freely.
  for (const dimKey of Object.keys(_SCREENSHOT_CAMEL_ALIASES)) {
    const existing = String(overrides[dimKey] || '').trim();
    if (_isNoMappingValue(existing)) continue;

    const existingKind = existing && Object.prototype.hasOwnProperty.call(sample, existing)
      ? _classifyScreenshotValue(sample[existing])
      : null;

    const nameCandidate = _findScreenshotCandidateByName(sample, dimKey, effectiveSource);

    // Decide which property to use for this dim
    let chosen = null;
    let reason = '';
    if (nameCandidate && nameCandidate.kind === 'fm') {
      // F&M candidate found — wins over any URL override or stale override.
      // Only skip the replace if existing is ALREADY this exact F&M property.
      if (existing === nameCandidate.key) continue;
      chosen = nameCandidate.key;
      reason = `kind: fm, score: ${nameCandidate.score}`;
    } else if (existingKind) {
      // No F&M candidate, but existing override is live (URL or otherwise).
      // Keep it — the user picked a URL property or the template wrote one
      // that exists. Falling back to camel-alias detection could replace a
      // working URL override with a different URL override pointing to the
      // same data, which is pointless churn.
      continue;
    } else if (nameCandidate && nameCandidate.kind === 'url') {
      // No F&M, no live existing — use the URL candidate found by name.
      if (existing === nameCandidate.key) continue;
      chosen = nameCandidate.key;
      reason = `kind: url, score: ${nameCandidate.score}`;
    } else {
      // Name search found nothing. Fall back to camel-alias detection.
      const camelAliases = _SCREENSHOT_CAMEL_ALIASES[dimKey] || [];
      const camelKey = camelAliases.find(k => {
        if (!(k in sample)) return false;
        return _classifyScreenshotValue(sample[k]) !== null;
      });
      if (!camelKey) continue;
      const camelValStr = JSON.stringify(sample[camelKey]);
      const sourceKey = Object.keys(sample).find(k =>
        k !== camelKey && /\s/.test(k) && JSON.stringify(sample[k]) === camelValStr
      );
      if (!sourceKey || sourceKey === existing) continue;
      chosen = sourceKey;
      reason = `camel alias: ${camelKey} (legacy fallback)`;
    }

    if (!chosen) continue;
    const wasReplaced = existing && existing !== chosen;
    overrides[dimKey] = chosen;
    newAutoKeys.push(dimKey);
    changed = true;
    debugLog(
      '[ScreenshotAutoMap] dim', dimKey, '→', chosen,
      `(${reason})`,
      wasReplaced ? `(replaced override: "${existing}")` : ''
    );
  }

  if (changed) {
    _saveAPIFieldOverrides(overrides);
    const existingSet = _getAutoMappedDims();
    newAutoKeys.forEach(k => existingSet.add(k));
    _setAutoMappedDims(existingSet);
  }
}

// Auto-map Notion property keys to the aliases expected by _normalizeAPITrade,
// without modifying _normalizeAPITrade or overwriting any explicit user overrides.
// Only called for Notion profiles; safe to call on legacy profiles (no-ops when
// the target alias is already present in the raw trade object).
function _applyNotionAutoMap(trades, source) {
  if (!trades || !trades.length) return trades;
  const overrides = _getAPIFieldOverrides(source);
  const sample = trades.find(t => t && typeof t === 'object');
  if (!sample) return trades;

  // ── Resolve a single alias from a candidate list ─────────────────────────────
  // Returns the first candidate key that (a) exists in sample and (b) has a
  // non-empty value. Skips the whole alias if a user override is already set.
  const _resolve = (alias, dimKey, candidates) => {
    if (alias in sample) return null; // already present
    if (dimKey && overrides[dimKey] && !_isNoMappingValue(overrides[dimKey])) return null;
    return candidates.find(k => {
      if (!(k in sample)) return false;
      const v = sample[k];
      return v !== null && v !== undefined && v !== '' && !(Array.isArray(v) && !v.length);
    }) || null;
  };

  const aliasMap = {};

  // ── positionResult (outcome) ────────────────────────────────────────────────
  // _normalizeAPITrade hard-codes t.positionResult ?? t.resultatTp1 ?? t.resultatTP1
  // ?? t['Position Result']. French Notion databases often use different names.
  // Priority: most-specific French camelCase variants first, then generic English.
  const posResult = _resolve('positionResult', 'outcome', [
    'resultatRr3', 'resultatRr2', 'resultatRr1',
    'resultatOb',
    'resultat27',
    'resultatTp3', 'resultatTp2', 'resultatTp1',
    'resultatTP3', 'resultatTP2', 'resultatTP1',
    'positionResult', 'Position Result',
    'result', 'Result', 'outcome', 'Outcome',
  ]);
  if (posResult) {
    aliasMap.positionResult = posResult;
  } else if (!('positionResult' in sample) &&
             !(overrides.outcome && !_isNoMappingValue(overrides.outcome))) {
    // Fallback: scan all keys for any that contain "resultat" or "result"
    // in their normalized name and carry a non-empty value.
    const fallback = Object.keys(sample).find(k => {
      if (k.startsWith('_') || k === 'notionUrl' || k === 'notion url') return false;
      const norm = k.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
      if (!norm.includes('resultat') && !norm.includes('result') && !norm.includes('outcome')) return false;
      const v = sample[k];
      return v !== null && v !== undefined && v !== '' && !(Array.isArray(v) && !v.length);
    });
    if (fallback) aliasMap.positionResult = fallback;
  }

  _applyCommonNotionAliases(aliasMap, sample);
  if ((source || _getCurrentHTFSource()) === 'h4') _applyH4NotionAliases(aliasMap, sample);

  if (!Object.keys(aliasMap).length) {
    debugLog('[NotionAutoMap] selected aliases:', '(none)');
    return trades;
  }

  debugLog('[NotionAutoMap] selected aliases:', aliasMap);

  return trades.map(t => {
    if (!t || typeof t !== 'object') return t;
    const patch = {};
    for (const [alias, src] of Object.entries(aliasMap)) {
      const existing = t[alias];
      const hasExisting = existing !== null && existing !== undefined && existing !== '' && !(Array.isArray(existing) && !existing.length);
      if (!hasExisting && src in t) patch[alias] = t[src];
    }
    return Object.keys(patch).length ? { ...t, ...patch } : t;
  });
}

function _reapplyAPIOverrides() {
  const raw = _getRawAPICache();
  if (!raw || !raw.length) {
    // No raw cache after a page refresh: do not auto-fetch. The user must
    // explicitly press Notion Live to refresh the API.
    return false;
  }
  const processed = _applyOutcomeOverride(raw, _getCurrentHTFSource());
  const autoMapped = _applyNotionAutoMap(processed, _getCurrentHTFSource());
  _getOutcomeValueReport(autoMapped, _getCurrentHTFSource());
  _resetOutcomeDebugCounts();
  const parsed = autoMapped.map((t, i) => {
    const norm = _normalizeAPITrade(t, i);
    // Preserve _notionId across re-normalization — same fallback chain as the
    // sync path at line 9456. Without this, every Reapply call would strip
    // _notionId from cached trades, breaking the media queue's ability to
    // match Supabase migrations back to the correct trade. Surfaced when
    // Max's Reapply on H4 Perso wiped _notionId and the post-refresh merge
    // of session media URLs failed because byNotionId.get returned undefined.
    if (norm) {
      const notionId = t._notionId || t.notionId || t.id || '';
      if (notionId) norm._notionId = notionId;
    }
    return norm;
  }).filter(Boolean);
  _flushOutcomeDebugCounts();
  const preserved = _preservePermanentImageUrls(parsed);
  setCachedAPIData(preserved);
  if (localStorage.getItem(DS_KEY) === 'api') {
    const savedState = (typeof _saveFilterState === 'function') ? _saveFilterState() : null;
    _injectTrades(preserved, 'Notion Live', savedState);
  }
  return true;
}

// Re-seed the template's auto-mapping from scratch, as if the profile had
// just been synced for the first time. Wipes the user's overrides, clears
// the auto-mapped flag set + the detected-template marker, then re-runs
// _maybeAutoApplyTemplateMapping so the template's canonical defaults
// (TEMPLATE_MAPPINGS[bucket]) are written cleanly and every dim is tagged
// is-auto-mapped (green) in the Mapping panel.
//
// Use case: user pencil-picked a few dims, regrets, wants to go back to
// the template baseline without recreating the profile. Destructive — any
// manual override is overwritten.
function _reapplyTemplateMapping() {
  // ── Safety guard: empty raw cache means we can't re-derive screenshots ─────
  // After a page refresh the raw cache is wiped (no sessionStorage persistence
  // by design — _persistRawAPIToSession is a no-op). If Reapply runs in that
  // state and _reapplyAPIOverrides early-returns (no raw to normalise), the
  // invalidate-from-`_saveAPIFieldOverrides({})` purge of LS + session parsed
  // caches has already happened — leaving the user with an empty dashboard.
  // Block the Reapply with a toast pointing at Sync, which is the only path
  // that can refill raw cache.
  const rawForCheck = (typeof _getRawAPICache === 'function') ? _getRawAPICache() : null;
  if (!Array.isArray(rawForCheck) || !rawForCheck.length) {
    _openReapplyResyncConfirm();
    console.warn('[ReapplyTemplate] aborted — no raw cache, sync required first.');
    return;
  }

  // ── Safety guard: partial raw cache (post-refresh + incremental sync) ──────
  // After refresh, raw cache is in-memory only so it starts empty. A subsequent
  // incremental Sync only fetches trades modified since the last cursor — often
  // 0-5 of the user's 500+ trades. The LS parsed cache still holds the full
  // set (merged in _loadNotionTrades), but raw now has only the few fetched
  // rows. If Reapply runs here, `_reapplyAPIOverrides` re-normalises just those
  // few trades and overwrites the LS parsed cache with that small set — on the
  // next refresh, the user's dashboard goes nearly empty (500+ trades vanish,
  // their screenshots with them). Repro path Max confirmed 2026-05-23: refresh
  // → Sync → Reapply → refresh = screenshots gone.
  // Fix: detect raw < cached and abort with a toast pointing at Full resync,
  // which is the only path that refills raw to parity with the parsed cache.
  const cachedForCheck = (typeof getCachedAPIData === 'function') ? (getCachedAPIData() || []) : [];
  if (cachedForCheck.length && rawForCheck.length < cachedForCheck.length) {
    _openReapplyResyncConfirm();
    console.warn('[ReapplyTemplate] aborted — raw cache partial (', rawForCheck.length, 'trades) vs cached parsed (', cachedForCheck.length, '). Full resync required.');
    return;
  }

  // ── Preserve screenshot overrides across Reapply ───────────────────────────
  // Max's request 2026-05-23: Re-apply template defaults should NOT touch the
  // screenshot mappings (img_m15 / img_h4_before / img_m15_after). For users
  // with custom Notion DBs (e.g. H4 Perso with Files & Media properties named
  // 'H4 Before' / 'H4 After' instead of the template's 'URL H4 Before' /
  // 'URL H4 After'), the user manually pencil-picked or the auto-detect ran
  // and found the correct F&M property. Reapply would otherwise wipe these
  // and re-write the template's URL defaults, which point to columns that
  // don't exist in custom DBs → "no value detected" until manual fix again.
  //
  // Strategy: snapshot the 3 screenshot overrides + their auto-mapped flags
  // BEFORE the wipe, then restore them AFTER `_maybeAutoApplyTemplateMapping`
  // has written the rest of the template defaults. Net effect: every NON-
  // screenshot dim is reset to template baseline; screenshots stay as the
  // user / previous auto-detect resolved them. If the user explicitly wants
  // to reset a screenshot mapping, they can still pencil-pick the dim back
  // to the template default (or 'No Mapping').
  const SCREENSHOT_DIMS = ['img_m15', 'img_h4_before', 'img_m15_after'];
  const overridesBefore = _getAPIFieldOverrides();
  const autoSetBefore = _getAutoMappedDims();
  const preservedOverrides = {};
  const preservedAutoSet = new Set();
  for (const k of SCREENSHOT_DIMS) {
    if (overridesBefore[k]) preservedOverrides[k] = overridesBefore[k];
    if (autoSetBefore.has(k)) preservedAutoSet.add(k);
  }

  _saveAPIFieldOverrides({});
  _setDetectedTemplate(null);
  _clearAutoMappedDims();
  // Re-run the template auto-mapping. The function reads the active
  // profile's templateChoice + notionDatabaseTitle, picks the matching
  // mapping from TEMPLATE_MAPPINGS, writes it to gs_api_field_overrides_<id>,
  // and tags every key in the auto-mapped set. rawTrades param is
  // unused inside (kept for signature stability) so we pass undefined.
  if (typeof _maybeAutoApplyTemplateMapping === 'function') {
    try { _maybeAutoApplyTemplateMapping(); }
    catch (e) { console.error('[ReapplyTemplate] auto-map failed:', e); }
  }

  // Restore the preserved screenshot overrides (and their auto-mapped flags)
  // AFTER template defaults have been written, so they win the merge.
  const afterTemplate = _getAPIFieldOverrides();
  const merged = { ...afterTemplate, ...preservedOverrides };
  _saveAPIFieldOverrides(merged);
  const finalAutoSet = _getAutoMappedDims();
  for (const k of preservedAutoSet) finalAutoSet.add(k);
  _setAutoMappedDims(finalAutoSet);

  // If the user has NO existing screenshot overrides (fresh profile, or all
  // 3 are __NO_MAPPING__), run the auto-detect against raw to populate them
  // from F&M / camel-alias candidates. Existing overrides are preserved by
  // the helper's "live override + F&M-prefers" decision tree.
  try { _autoMapScreenshotsByRawKeys(rawForCheck, _getCurrentHTFSource()); }
  catch (e) { console.error('[ReapplyTemplate] screenshot auto-detect failed:', e); }

  _reapplyAPIOverrides();
  updateJournalPanel();
}

