function createTopbarStatCard(item) {
  // Rich .utip tooltip is attached by _attachKpiTooltipHandlersTo after render —
  // keyed by data-kpi-key which matches the keys used by _buildKpiTooltipHtml.
  return `
    <div class="ts" data-stat="${item.valueId}" data-kpi-key="${item.titleKey || ''}">
      <div class="ts-l">${item.label}</div>
      <div class="ts-v ${item.tone}" id="${item.valueId}">—</div>
    </div>`;
}

function createMobileControlItem(item) {
  const dataAttrs = Object.entries(item)
    .filter(([key, value]) => !['id', 'label', 'active', 'className'].includes(key) && value !== undefined)
    .map(([key, value]) => `data-${key === 'includeBe' ? 'include-be' : key}="${value}"`)
    .join(' ');
  return `<div class="mob-bmt${item.active ? ' active' : ''}" id="${item.id}" ${dataAttrs}>${item.label}</div>`;
}

function createMobileControlGroup(group) {
  return `
    <div class="mob-presets-separator" aria-hidden="true"></div>
    <div class="${group.className}" data-mobile-group="${group.type}">
      ${group.items.map(createMobileControlItem).join('')}
    </div>`;
}

function createMobilePresetPill(id, index) {
  const preset = id === null ? { id: null, label: 'P0 — Baseline' } : PRESETS.find(p => p.id === id);
  if (!preset) return '';
  const label = preset.id === null
    ? preset.label
    : `P${_getPresetDisplayNum(preset.id)} — ${preset.label.replace(' Personal Filters', '').replace(' Max Filter', ' Max')}`;
  return `<div class="mob-preset-pill${index === 0 ? ' active' : ''}" data-action="mob-apply-preset" data-preset="${id === null ? '' : id}">${label}</div>`;
}

function _escAttr(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function createPresetRow(preset) {
  const labelSafe = _escAttr(preset.label);
  const descSafe  = _escAttr(preset.description || '');
  return `
    <div class="preset-row" id="preset-row-${preset.id}" data-preset-id="${preset.id}">
      <div class="preset-btn-wrap">
        <button class="preset-btn" id="preset-${preset.id}" data-action="apply-preset" data-preset="${preset.id}">
          <span class="preset-num">P${_getPresetDisplayNum(preset.id)}</span>
          <span class="preset-info">
            <span class="preset-name">${labelSafe}</span>
            <span class="preset-desc">${descSafe}</span>
          </span>
        </button>
        <button class="preset-tune-btn" id="tune-${preset.id}" data-action="toggle-tune-panel" data-preset="${preset.id}" title="Tune preset filters">⚙</button>
      </div>
      <div class="preset-override-panel" id="po-panel-${preset.id}"></div>
    </div>`;
}

// "+ New preset" placeholder row, only rendered when there is at least one
// free slot (PRESETS.length < PRESET_MAX).
function createPresetAddRow() {
  return `
    <div class="preset-row preset-row-add">
      <button class="preset-add-btn" data-action="create-preset" title="Create a new preset">
        <span class="preset-add-icon">+</span>
        <span class="preset-add-label">New preset</span>
        <span class="preset-add-count">${PRESETS.length}/${PRESET_MAX}</span>
      </button>
    </div>`;
}

// ── Preset CRUD operations ──
function createPreset() {
  const id = _nextPresetId();
  if (id < 0) {
    alert(`Maximum ${PRESET_MAX} presets allowed.`);
    return;
  }
  const maxOrder = PRESETS.reduce((m, p) => Math.max(m, (typeof p.order === 'number' ? p.order : -1)), -1);
  const newPreset = {
    id,
    order: maxOrder + 1,
    label: '',
    description: 'Click ✎ to rename · use ⚙ to add filters',
    be: false,
    clear: true,
    m15Exclude: [],
    h4Exclude: [],
    sessionExclude: [],
    noBaseExclusions: true,
  };
  PRESETS.push(newPreset);
  PRESETS.sort((a, b) => a.order - b.order);
  // Label uses the VISUAL position (post-sort) so the auto-name matches what
  // the user sees. Frozen at creation — later deletions shift the stored name
  // only visually via _getPresetDisplayNum.
  newPreset.label = `Custom P${_getPresetDisplayNum(id)}`;

  // Defensive: wipe EVERY possible persisted slot for this id before use.
  // Since ids are never recycled, these should already be empty, but the
  // explicit clear guarantees no carry-over if localStorage state ever gets
  // out of sync with the id counter.
  presetOverrides[id] = {};
  SB_DIMS.forEach(d => {
    presetOverrides[id][d.key] = { mode: 'neutral', included: new Set(), excluded: new Set() };
  });
  presetOverrides[id].customChips = {};
  presetSnapshots[id] = _blankSnapshot();
  delete presetLiveFilters[_liveKey(id)];

  savePresetsList();
  savePresetSnapshots();
  savePresetOverrides();
  savePresetLiveFilters();
  // Auto-select the freshly-created preset (Max invariant: creating a preset
  // should switch focus to it, otherwise the user has no signal that the
  // action succeeded beyond it appearing in the list). Render the preset list
  // FIRST so applyPreset's downstream syncPresetSelectionState finds the new
  // button in the DOM and can apply the `.active` class to it. Swapping the
  // order would wipe the active class on the subsequent renderPresetList.
  renderPresetList();
  try { applyPreset(id); } catch (e) { console.warn('[createPreset] applyPreset failed:', e?.message || e); }
  refreshPresetCompareDropdowns();
}

function renamePreset(id) {
  const preset = PRESETS.find(p => p.id === id);
  if (!preset) return;
  const newLabel = prompt('Preset name:', preset.label);
  if (newLabel === null) return; // cancelled
  const trimmed = newLabel.trim();
  if (!trimmed) return;
  preset.label = trimmed;
  const newDesc = prompt('Preset description (optional):', preset.description || '');
  if (newDesc !== null) preset.description = newDesc.trim();
  savePresetsList();
  renderPresetList();
  refreshPresetCompareDropdowns();
  // Re-sync mobile preset pills if the renamed preset is in the mobile list
  renderMobilePresetControls();
}

function deletePreset(id) {
  const preset = PRESETS.find(p => p.id === id);
  if (!preset) return;
  if (!confirm(`Delete preset "${preset.label}"?`)) return;

  const wasActive = appState.presets.activeId === id;
  const deletedOrder = typeof preset.order === 'number' ? preset.order : 0;

  PRESETS = PRESETS.filter(p => p.id !== id);
  // Compact order: every preset whose order was above the deleted one
  // shifts down by 1, so the display numbering (P1, P2, ...) has no gap.
  PRESETS.forEach(p => {
    if (typeof p.order === 'number' && p.order > deletedOrder) p.order -= 1;
  });
  PRESETS.sort((a, b) => a.order - b.order);

  // Reset override state for the deleted slot so stale data doesn't stick
  // around in LS (ids are never recycled, so this is defensive hygiene).
  if (presetOverrides[id]) {
    SB_DIMS.forEach(d => {
      presetOverrides[id][d.key] = { mode: 'neutral', included: new Set(), excluded: new Set() };
    });
    presetOverrides[id].customChips = {};
  }
  if (presetSnapshots[id]) presetSnapshots[id] = _blankSnapshot();
  delete presetLiveFilters[_liveKey(id)];
  savePresetSnapshots();
  savePresetLiveFilters();

  if (wasActive) {
    // Max invariant (Refacto Total 2026-05-24): the user is NEVER on "no
    // preset". Falling back to P0 (RAW Baseline) keeps the dashboard usable.
    // Pre-clearing chips before applyPreset(0) makes its inner
    // _syncLiveSlotFromActiveChips write empty arrays to presetLiveFilters[id]
    // (the just-deleted slot is re-allocated blank), then we re-delete it.
    _removeAllPresetChips();
    _removeAllLiveChips();
    _clearComboFilters();
    try { applyPreset(0); } catch (e) {
      console.warn('[deletePreset] applyPreset(0) failed:', e?.message || e);
      appState.presets.activeId = null;
    }
    // Re-cleanup au cas où sync aurait recréé un slot pour l'id supprimé.
    delete presetLiveFilters[_liveKey(id)];
    savePresetLiveFilters();
  }

  savePresetsList();
  savePresetOverrides();
  renderPresetList();
  refreshPresetCompareDropdowns();
  renderMobilePresetControls();
  render();
}

function refreshPresetCompareDropdowns() {
  const selA = document.getElementById('pcmp-a');
  const selB = document.getElementById('pcmp-b');
  if (!selA || !selB) return;
  const prevA = parseInt(selA.value, 10);
  const prevB = parseInt(selB.value, 10);
  const optsHtml = PRESETS.map(p => `<option value="${p.id}">P${_getPresetDisplayNum(p.id)} — ${_escAttr(p.label)}</option>`).join('');
  selA.innerHTML = optsHtml;
  selB.innerHTML = optsHtml;
  // Restore previous selection if still present, else pick first
  if (PRESETS.some(p => p.id === prevA)) selA.value = String(prevA);
  if (PRESETS.some(p => p.id === prevB)) selB.value = String(prevB);
  if (_presetCmpOpen) runPresetCompare();
  if (typeof renderSaveButton === 'function') renderSaveButton();
}

function createMobileKpiCell(item) {
  const title = (item.titleKey && KPI_TITLES[item.titleKey]) || '';
  return `
    <div class="mob-kpi-cell ${item.cellTone}" data-kpi="${item.key}"${title ? ` title="${title}"` : ''}>
      <div class="mob-kpi-label">${item.label}</div>
      <div class="mob-kpi-value ${item.valueTone}" id="${item.valueId}">—</div>
      <div class="mob-kpi-sub"${item.subId ? ` id="${item.subId}"` : ''}>${item.subText}</div>
    </div>`;
}

function syncDashboardChrome() {
  syncPresetSelectionState(appState.presets.activeId);
  setResetButtonMode(appState.ui.showRawAll);
}

function renderTopbarStats() {
  const container = document.getElementById('topbar-stats');
  if (!container) return;
  // Boot snapshot may have already injected last-session HTML inline (before
  // dashboard.js loaded). Skip the placeholder rebuild in that case so the
  // user keeps seeing real values instead of "—" cells until live _setText
  // calls overwrite them.
  const hasSnapshot = container.children.length > 0 && container.querySelector('.ts');
  if (!hasSnapshot) {
    container.innerHTML = TOPBAR_STAT_ITEMS.map(createTopbarStatCard).join('');
  }
  _attachTopbarKpiTooltipsLive();
}

// Topbar KPI cells persist across stats updates (only their inner text changes).
// To keep the rich .utip tooltip in sync with current filters, handlers read
// from these module-level refs at hover time — refreshed by updateStatsWidget.
let _topbarKpiStatsRef = null;
let _topbarKpiBeStatsRef = null;
let _topbarKpiTipsAttached = false;
function _attachTopbarKpiTooltipsLive() {
  const container = document.getElementById('topbar-stats');
  if (!container || _topbarKpiTipsAttached) return;
  const cells = container.querySelectorAll('.ts[data-kpi-key]');
  cells.forEach(cell => {
    const key = cell.dataset.kpiKey;
    if (!key) return;
    cell.addEventListener('mouseenter', (e) => {
      const html = _buildKpiTooltipHtml(key, _topbarKpiStatsRef, _topbarKpiBeStatsRef);
      if (html) showUtip(e, html);
    });
    cell.addEventListener('mousemove', (e) => {
      const html = _buildKpiTooltipHtml(key, _topbarKpiStatsRef, _topbarKpiBeStatsRef);
      if (html) showUtip(e, html);
    });
    cell.addEventListener('mouseleave', () => hideUtip());
  });
  _topbarKpiTipsAttached = true;
}

function renderMobilePresetControls() {
  const container = document.getElementById('mob-presets');
  if (!container) return;
  const presetMarkup = MOBILE_PRESET_IDS.map(createMobilePresetPill).join('');
  const controlMarkup = MOBILE_CONTROL_GROUPS.map(createMobileControlGroup).join('');
  container.innerHTML = `${presetMarkup}${controlMarkup}`;
}

function renderPresetList() {
  const container = document.getElementById('preset-list');
  if (!container) return;
  let html = PRESETS.map(createPresetRow).join('');
  if (PRESETS.length < PRESET_MAX) html += createPresetAddRow();
  container.innerHTML = html;
}

function syncPresetSelectionState(presetId) {
  document.querySelectorAll('.preset-btn').forEach(btn => {
    btn.classList.toggle('active', parseInt(btn.dataset.preset, 10) === presetId);
  });
  document.querySelectorAll('.mob-preset-pill').forEach(pill => {
    const pillPreset = pill.dataset.preset === '' ? null : parseInt(pill.dataset.preset, 10);
    pill.classList.toggle('active', pillPreset === presetId);
  });
}

function renderMobileKpiGrid() {
  const container = document.getElementById('mob-kpi-grid');
  if (!container) return;
  container.innerHTML = MOBILE_KPI_ITEMS.map(createMobileKpiCell).join('');
}

function setResetButtonMode(isRawMode) {
  const resetBtn = document.querySelector('.reset-btn');
  if (!resetBtn) return;
  resetBtn.textContent = isRawMode ? '✕ Raw mode' : '↺ Reset';
  resetBtn.title = isRawMode ? 'Click to return to normal mode' : '';
  resetBtn.classList.toggle('raw-active', isRawMode);
  resetBtn.dataset.action = isRawMode ? 'exit-raw-mode' : 'reset-all';
}

function renderStaticDashboardChrome() {
  renderTopbarStats();
  renderMobilePresetControls();
  renderMobileKpiGrid();
  renderPresetList();
}

// Returns P2 (Claude V1 Max Filter) trades.
// Used as a stable reference for the optimal zone across all presets.
function getP2RefTrades() {
  const p2 = PRESETS.find(x => x.id === 2);
  const m15Ex = [...BASE_M15_EXCLUDE, ...(p2.m15Exclude || [])].map(o => o.toLowerCase());
  const h4Ex  = (p2.h4Exclude  || []).map(o => o.toLowerCase());
  const sessEx = [...BASE_SESSION_EXCLUDE, ...(p2.sessionExclude || [])];
  return appState.trades.items.filter(t => {
    if (m15Ex.length) {
      const obs = t.obstacles.map(o => o.toLowerCase());
      if (m15Ex.some(o => obs.includes(o))) return false;
    }
    if (h4Ex.length) {
      const h4 = t.h4.map(o => o.toLowerCase());
      if (h4Ex.some(o => h4.includes(o))) return false;
    }
    if (sessEx.length && sessEx.includes(t.session)) return false;
    if (p2.dayInclude?.length && !p2.dayInclude.includes(t.day)) return false;
    return true;
  });
}

function applyPreset(id) {
  invalidateFilterCache();
  setRawMode(false);
  // Phase 3 : id === null est une cible valide (pseudo-preset "aucun preset
  // actif"), pour que applyPreset(null) soit utilisable comme bascule vers
  // le contexte null avec swap correct du live slot. Pour un id numérique,
  // on exige qu'il existe dans PRESETS.
  if (id !== null) {
    const p = PRESETS.find(x => x.id === id);
    if (!p) return;
  }

  // Phase 3: live filters are scoped PER PRESET. Switching presets swaps both
  // glow AND live context.
  //   1. Sync sortant → snapshot les live du preset actif courant avant de
  //      changer activeId (la fonction lit appState.presets.activeId).
  //   2. État propre : supprimer chips preset + chips live du DOM de l'état.
  //   3. Flip activeId.
  //   4. Hydrater glow depuis presetSnapshots[newId].
  //   5. Hydrater live depuis presetLiveFilters[newId] (+ comboFilters).
  //   6. Synchroniser legacy state + UI.
  _syncLiveSlotFromActiveChips();
  _removeAllPresetChips();
  _removeAllLiveChips();
  _clearComboFilters();
  setActivePreset(id);
  _hydrateChipsFromSnapshot(presetSnapshots[id]);
  _hydrateChipsFromLiveSlot(getPresetLiveSlot(id));
  // Hydrate the ORR bubble from the preset's live slot. Each preset tracks
  // its own rrMinFilter — switching presets swaps the bubble along with the
  // filter context.
  const liveSlot = getPresetLiveSlot(id);
  appState.ui.rrMinFilter = (typeof liveSlot.rrMinFilter === 'number') ? liveSlot.rrMinFilter : null;
  // tpConfig: hydrate the active TPM from the preset's live slot. Mirror of
  // the rrMinFilter pattern — switching presets swaps the TP Management
  // context. getPresetLiveSlot guarantees a valid shape, so the else branch
  // is purely defensive.
  if (_isValidTpConfigShape(liveSlot.tpConfig)) {
    appState.ui.tpConfig = JSON.parse(JSON.stringify(liveSlot.tpConfig));
  } else {
    appState.ui.tpConfig = _defaultTpConfig();
    liveSlot.tpConfig = _defaultTpConfig();
  }
  // Re-render TPM panel + badge if available, so mode/partials/targets reflect
  // the newly hydrated config. Guarded — these may not exist during very-early
  // bootstrap calls.
  try { if (typeof _renderTpmModeBody === 'function') _renderTpmModeBody(); } catch (e) {
    console.warn('[applyPreset] TPM panel sync failed:', e.message);
  }
  try { if (typeof _renderTpmDropdownOptions === 'function') _renderTpmDropdownOptions(); } catch (e) {
    console.warn('[applyPreset] TPM dropdown sync failed:', e.message);
  }
  try { if (typeof _updateTpmBadge === 'function') _updateTpmBadge(); } catch (e) {
    console.warn('[applyPreset] TPM badge sync failed:', e.message);
  }
  // Sync the topbar TPM/Custom/Multi badge — depends on the freshly hydrated
  // tpConfig and must be refreshed when switching presets.
  try { if (typeof _ppSyncActivePresetBadge === 'function') _ppSyncActivePresetBadge(); } catch (e) {
    console.warn('[applyPreset] TPM topbar badge sync failed:', e.message);
  }
  invalidateFilterCache();
  resetExclusionState();
  Object.keys(appState.filters.chips).forEach(key => _syncChipModeButtons(key));
  render();
  if (typeof _rrSyncActiveFilterBadge === 'function') _rrSyncActiveFilterBadge();
}

/** Wipe appState.filters.comboFilters en place. Appelée par applyPreset avant
 *  de rehydrater le slot live du nouveau preset — les combo filters sont du
 *  live pur, jamais partagés entre presets. */
function _clearComboFilters() {
  const cf = appState.filters.comboFilters;
  if (!cf) return;
  for (const key of ['sessionDay', 'pairSession']) {
    const entry = cf[key];
    if (!entry) continue;
    entry.included.clear();
    entry.excluded.clear();
  }
}

/** Hydrate appState.filters.chips + customChips from a preset snapshot,
 *  tagging every injected value as fromPreset:true. No-op on null/empty. */
function _hydrateChipsFromSnapshot(snap) {
  if (!snap) return;
  // Natives
  if (snap.chips && typeof snap.chips === 'object') {
    for (const [dimKey, dim] of Object.entries(snap.chips)) {
      const entry = appState.filters.chips[dimKey];
      if (!entry) continue;
      _ensureFromPresetSets(entry);
      (dim.included || []).forEach(v => _setChipValue(entry, 'included', v, 'add', true));
      (dim.excluded || []).forEach(v => _setChipValue(entry, 'excluded', v, 'add', true));
      // Keep the sticky mode consistent: if only one bucket has values, lock
      // it; if both, 'include' (arbitrary — chips still render individually).
      if (entry.included.size && !entry.excluded.size) entry.mode = 'include';
      else if (!entry.included.size && entry.excluded.size) entry.mode = 'exclude';
      else if (entry.included.size && entry.excluded.size) entry.mode = 'include';
    }
  }
  // Custom props
  if (snap.customChips && typeof snap.customChips === 'object') {
    for (const [k, v] of Object.entries(snap.customChips)) {
      if (!v) continue;
      let entry = appState.filters.customChips[k];
      if (!entry) {
        // Allocate a fresh entry — renderCustomFilterChips will rebuild DOM later.
        entry = appState.filters.customChips[k] = {
          mode: 'neutral',
          included: new Set(),
          excluded: new Set(),
          includedFromPreset: new Set(),
          excludedFromPreset: new Set(),
          matchMode: v.matchMode === 'all' ? 'all' : 'any',
        };
      }
      _ensureFromPresetSets(entry);
      entry.matchMode = v.matchMode === 'all' ? 'all' : 'any';
      (v.included || []).forEach(x => _setChipValue(entry, 'included', x, 'add', true));
      (v.excluded || []).forEach(x => _setChipValue(entry, 'excluded', x, 'add', true));
      if (entry.included.size && !entry.excluded.size) entry.mode = 'include';
      else if (!entry.included.size && entry.excluded.size) entry.mode = 'exclude';
      else if (entry.included.size && entry.excluded.size) entry.mode = 'include';
    }
  }
}

/** Hydrate appState.filters.chips + customChips + comboFilters depuis un slot
 *  live (forme _blankLiveSlot — snapshot-like avec un bloc comboFilters). Tag
 *  les valeurs fromPreset:false. Règle "glow prime" : si une valeur est déjà
 *  dans includedFromPreset/excludedFromPreset, elle est ignorée côté live
 *  (le slot ne doit pas ressusciter un chip déjà servi par le preset). */
function _hydrateChipsFromLiveSlot(slot) {
  if (!slot) return;
  if (slot.chips && typeof slot.chips === 'object') {
    for (const [dimKey, dim] of Object.entries(slot.chips)) {
      const entry = appState.filters.chips[dimKey];
      if (!entry) continue;
      _ensureFromPresetSets(entry);
      (dim.included || []).forEach(v => {
        if (entry.includedFromPreset.has(v)) return;
        _setChipValue(entry, 'included', v, 'add', false);
      });
      (dim.excluded || []).forEach(v => {
        if (entry.excludedFromPreset.has(v)) return;
        _setChipValue(entry, 'excluded', v, 'add', false);
      });
      // Re-apply tombstones (and flipped chips) that the user persisted in
      // the live slot. Keeps fromPreset flag intact so _hydrateChipsFromSnapshot
      // populated lineage is preserved for tombstone rendering.
      (dim.removedFromIncluded || []).forEach(v => {
        if (entry.includedFromPreset.has(v)) entry.included.delete(v);
      });
      (dim.removedFromExcluded || []).forEach(v => {
        if (entry.excludedFromPreset.has(v)) entry.excluded.delete(v);
      });
      if (entry.included.size && !entry.excluded.size) entry.mode = 'include';
      else if (!entry.included.size && entry.excluded.size) entry.mode = 'exclude';
      else if (entry.included.size && entry.excluded.size) entry.mode = 'include';
    }
  }
  if (slot.customChips && typeof slot.customChips === 'object') {
    for (const [k, v] of Object.entries(slot.customChips)) {
      if (!v) continue;
      let entry = appState.filters.customChips[k];
      if (!entry) {
        entry = appState.filters.customChips[k] = {
          mode: 'neutral',
          included: new Set(),
          excluded: new Set(),
          includedFromPreset: new Set(),
          excludedFromPreset: new Set(),
          matchMode: v.matchMode === 'all' ? 'all' : 'any',
        };
      }
      _ensureFromPresetSets(entry);
      entry.matchMode = v.matchMode === 'all' ? 'all' : 'any';
      (v.included || []).forEach(x => {
        if (entry.includedFromPreset.has(x)) return;
        _setChipValue(entry, 'included', x, 'add', false);
      });
      (v.excluded || []).forEach(x => {
        if (entry.excludedFromPreset.has(x)) return;
        _setChipValue(entry, 'excluded', x, 'add', false);
      });
      if (entry.included.size && !entry.excluded.size) entry.mode = 'include';
      else if (!entry.included.size && entry.excluded.size) entry.mode = 'exclude';
      else if (entry.included.size && entry.excluded.size) entry.mode = 'include';
    }
  }
  // comboFilters — purement live (pas de flag fromPreset à considérer).
  if (slot.comboFilters && typeof slot.comboFilters === 'object') {
    for (const ck of ['sessionDay', 'pairSession']) {
      const src = slot.comboFilters[ck];
      const dst = appState.filters.comboFilters?.[ck];
      if (!src || !dst) continue;
      (src.included || []).forEach(v => dst.included.add(v));
      (src.excluded || []).forEach(v => dst.excluded.add(v));
    }
  }
}

/** Build a snapshot from the current preset-flagged chip values. Inverse
 *  of _hydrateChipsFromSnapshot — reads the includedFromPreset / excludedFromPreset
 *  Sets (+ live values promoted by commitLiveFiltersToActivePreset). */
function _buildSnapshotFromActiveChips() {
  const snap = _blankSnapshot();
  for (const [dimKey, entry] of Object.entries(appState.filters.chips)) {
    const dst = snap.chips[dimKey];
    if (!dst) continue;
    _ensureFromPresetSets(entry);
    dst.included = [...entry.includedFromPreset];
    dst.excluded = [...entry.excludedFromPreset];
  }
  for (const [k, entry] of Object.entries(appState.filters.customChips || {})) {
    if (!entry) continue;
    _ensureFromPresetSets(entry);
    const inc = [...entry.includedFromPreset];
    const exc = [...entry.excludedFromPreset];
    if (!inc.length && !exc.length) continue;
    snap.customChips[k] = {
      mode: entry.mode || 'neutral',
      matchMode: entry.matchMode || 'any',
      included: inc,
      excluded: exc,
    };
  }
  return snap;
}

