// ══════════════════════════════════════════════════════
// FILTER ENGINE
// ══════════════════════════════════════════════════════
// ── getFiltered cache ──
let _filteredCache    = null;
let _filterCacheKey   = '';

function getActivePresetDefinition() {
  return typeof appState.presets.activeId === 'number'
    ? PRESETS.find(x => x.id === appState.presets.activeId) || null
    : null;
}

function _filterStateKey() {
  let ovKey = '';
  if (typeof appState.presets.activeId === 'number' && presetOverrides[appState.presets.activeId]) {
    const ov = presetOverrides[appState.presets.activeId];
    ovKey = SB_DIMS.map(d => {
      const s = ov[d.key];
      return d.key + ':I=' + [...s.included].sort().join(',') + ';E=' + [...s.excluded].sort().join(',');
    }).join(';');
  }
  return [
    appState.ui.showRawAll,
    appState.presets.activeId,
    appState.filters.exclusions.m15Exclude.join(','),
    appState.filters.exclusions.h4Exclude.join(','),
    appState.filters.exclusions.sessionExclude.join(','),
    (appState.filters.exclusions.dayExclude || []).join(','),
    ...Object.entries(appState.filters.chips).flatMap(([k, v]) => [
      k + 'I:' + [...v.included].sort().join(','),
      k + 'E:' + [...v.excluded].sort().join(','),
    ]),
    ...Object.entries(appState.filters.comboFilters || {}).flatMap(([k, v]) => [
      'cf_' + k + 'I:' + [...v.included].sort().join(','),
      'cf_' + k + 'E:' + [...v.excluded].sort().join(','),
    ]),
    // Custom chips snapshot — includes matchMode so any/all flips invalidate cache.
    ...Object.entries(appState.filters.customChips || {})
      .filter(([, e]) => e && (e.mode !== 'neutral' || e.included?.size || e.excluded?.size))
      .map(([k, e]) =>
        'cc_' + k + ':' + (e.mode || 'neutral') + ':' + (e.matchMode || 'any') +
        ':I=' + [...(e.included || [])].sort().join(',') +
        ';E=' + [...(e.excluded || [])].sort().join(','))
      .sort(),
    appState.filters.temporal.dateFrom || '',
    appState.filters.temporal.dateTo || '',
    appState.trades.items.length,
    ovKey,
    appState.ui.rrMinFilter ?? '',
    appState.ui.beRule,
    (appState.ui.beManagementExclude || []).slice().sort().join(','),
  ].join('|');
}

function invalidateFilterCache() {
  _filteredCache  = null;
  _filterCacheKey = '';
}


function filterDataset(trades) {
  // Canonical entry point for every render path. Enrich trades with effective-R
  // classification (effectiveR, effectiveClass, _effectiveClassMode) under the
  // active TP config. Per-trade hash check makes this near-free on subsequent
  // calls when the config hasn't changed.
  _enrichTradeClassification(trades);
  return trades;
}

function filterPreset(trades) {
  const preset = getActivePresetDefinition();
  if (!preset) return trades;
  // v2: all preset filter values now live in appState.filters.chips (hydrated
  // from presetSnapshots on applyPreset). The only preset-intrinsic exclusions
  // left here are the always-on hygiene filters (invalide + badFeeling) that
  // aren't surfaced as chip groups.
  return trades;
}

/** Apply a preset snapshot (pure value lists) to a trade array with the same
 *  include/exclude semantics as filterChips + filterCustomChips. Used by
 *  tools that preview/compare a preset without making it active — e.g.
 *  _getPresetStats (Preset Compare) and getPoPreview (tune-panel live stats). */
function _filterTradesBySnapshot(trades, snap) {
  if (!snap) return trades;
  const c = snap.chips || {};
  const scalar = (val, dim) => {
    const d = c[dim]; if (!d) return true;
    if (d.included.length && !d.included.includes(val)) return false;
    if (d.excluded.includes(val)) return false;
    return true;
  };
  const array = (arr, dim, ci) => {
    const d = c[dim]; if (!d) return true;
    const values = arr || [];
    if (d.included.length) {
      const ok = ci
        ? d.included.some(inc => values.some(v => v.toLowerCase() === inc.toLowerCase()))
        : d.included.some(inc => values.includes(inc));
      if (!ok) return false;
    }
    if (d.excluded.length) {
      const bad = ci
        ? d.excluded.some(exc => values.some(v => v.toLowerCase() === exc.toLowerCase()))
        : d.excluded.some(exc => values.includes(exc));
      if (bad) return false;
    }
    return true;
  };
  const customProps = (typeof loadCustomProps === 'function') ? loadCustomProps() : [];
  const propByKey = Object.create(null);
  for (const p of customProps) propByKey[p.key] = p;
  const customActive = Object.entries(snap.customChips || {}).filter(([k, e]) =>
    propByKey[k] && ((e.included?.length || 0) + (e.excluded?.length || 0) > 0)
  );
  return trades.filter(t => {
    // setup: match against both general and detailed setup (see filterChips for rationale)
    if (!array([t.setup, t.setupDetail].filter(Boolean), 'setup', false)) return false;
    if (!scalar(t.session, 'session')) return false;
    if (!scalar(t.day,     'day'))     return false;
    if (!scalar(t.pair,    'pair'))    return false;
    if (!array(t.obstacles,    'obstacles',    true))  return false;
    if (!array(t.h4,           'h4obs',        true))  return false;
    if (!array(t.tradeType,    'tradeType',    false)) return false;
    if (!array(t.beManagement, 'beManagement', false)) return false;
    if (!array([t.badFeeling ? 'Yes' : 'No'], 'badFeeling', false)) return false;
    if (t.hour != null && !scalar(String(t.hour), 'hour')) return false;
    // Custom chips — reuse the shared matcher. It expects a Set-shaped entry;
    // build a transient view over the snapshot's arrays.
    for (const [k, e] of customActive) {
      const prop = propByKey[k];
      if (!prop) continue;
      const view = {
        mode: e.mode || 'neutral',
        matchMode: e.matchMode || 'any',
        included: new Set(e.included || []),
        excluded: new Set(e.excluded || []),
      };
      if (!_customEntryPasses(t, prop, view)) return false;
    }
    return true;
  });
}

// Return a clone of a chip entry with one value stripped from both sets.
// Used by filterChips / filterCustomChips to skip a single chip value when
// computing its own cross-dimensional count — so for multi-select dimensions,
// OTHER excludes/includes in the same dimension stay active.
function _entryWithoutValue(entry, value) {
  if (!entry) return entry;
  const included = new Set(entry.included);
  const excluded = new Set(entry.excluded);
  included.delete(value);
  excluded.delete(value);
  return { ...entry, included, excluded };
}

function filterChips(trades, skipValue = null) {
  const C = appState.filters.chips;
  const _eff = (dim) => (skipValue?.dim === dim)
    ? _entryWithoutValue(C[dim], skipValue.value)
    : C[dim];
  // ── Scalar-field helper: the trade passes if value is in included (when non-empty)
  //    AND not in excluded.
  const scalarOk = (val, entry) => {
    if (entry.included.size && !entry.included.has(val)) return false;
    if (entry.excluded.has(val)) return false;
    return true;
  };
  // ── Array-field helper: the trade passes if at least one of its values is in
  //    included (when non-empty) AND none of its values is in excluded. Matching
  //    is case-insensitive for obstacles (existing convention).
  const arrayOk = (arr, entry, caseInsensitive = false) => {
    const values = arr || [];
    if (entry.included.size) {
      if (caseInsensitive) {
        const lowered = values.map(v => v.toLowerCase());
        const hasAnyIncluded = [...entry.included].some(inc => lowered.includes(inc.toLowerCase()));
        if (!hasAnyIncluded) return false;
      } else {
        const hasAnyIncluded = values.some(v => entry.included.has(v));
        if (!hasAnyIncluded) return false;
      }
    }
    if (entry.excluded.size) {
      if (caseInsensitive) {
        const lowered = values.map(v => v.toLowerCase());
        const hasAnyExcluded = [...entry.excluded].some(exc => lowered.includes(exc.toLowerCase()));
        if (hasAnyExcluded) return false;
      } else {
        const hasAnyExcluded = values.some(v => entry.excluded.has(v));
        if (hasAnyExcluded) return false;
      }
    }
    return true;
  };

  const CF = appState.filters.comboFilters;
  const sd = CF?.sessionDay;
  const ps = CF?.pairSession;

  return trades.filter(t => {
    if (!scalarOk(t.outcome,   _eff('outcome')))   return false;
    // setup: match against both the general setup (t.setup) and the detailed setup
    // (t.setupDetail) so the Setup Performance bar context menu works in both
    // grouping modes (non-detail uses t.setup values, detail mode uses t.setupDetail).
    if (!arrayOk([t.setup, t.setupDetail].filter(Boolean), _eff('setup'), false)) return false;
    if (!scalarOk(t.session,   _eff('session')))   return false;
    if (!scalarOk(t.day,       _eff('day')))       return false;
    if (!scalarOk(t.pair,      _eff('pair')))      return false;
    if (!scalarOk(t.direction, _eff('direction'))) return false;
    if (!arrayOk(t.obstacles,    _eff('obstacles'),    true))  return false;
    if (!arrayOk(t.h4,           _eff('h4obs'),        true))  return false;
    if (!arrayOk(t.tradeType,    _eff('tradeType'),    false)) return false;
    if (!arrayOk(t.beManagement, _eff('beManagement'), false)) return false;
    const bfEntry = _eff('badFeeling');
    if (bfEntry && !arrayOk([t.badFeeling ? 'Yes' : 'No'], bfEntry, false)) return false;
    const hourEntry = _eff('hour');
    if (hourEntry && !scalarOk(t.hour != null ? String(t.hour) : null, hourEntry)) return false;

    if (skipValue?.dim !== 'sessionDay' && sd) {
      const sdKey = (t.sessionUtc || t.session || '') + '|' + (t.day || '');
      if (sd.included.size && !sd.included.has(sdKey)) return false;
      if (sd.excluded.has(sdKey)) return false;
    }
    if (skipValue?.dim !== 'pairSession' && ps) {
      const psKey = (t.pair || '') + '|' + (t.sessionUtc || t.session || '');
      if (ps.included.size && !ps.included.has(psKey)) return false;
      if (ps.excluded.has(psKey)) return false;
    }
    return true;
  });
}

function filterTemporal(trades) {
  let filtered = trades;
  if (appState.filters.temporal.dateFrom) {
    filtered = filtered.filter(t => t.date >= appState.filters.temporal.dateFrom);
  }
  if (appState.filters.temporal.dateTo) {
    filtered = filtered.filter(t => t.date <= appState.filters.temporal.dateTo);
  }
  return filtered;
}

// ── Custom chips filter (sub-task 4) ──
// Applied after filterChips, before filterTemporal. Reads t.extras[key] which
// Option B keeps in sync with the raw source. scalar for select/checkbox,
// array matching for multi-select (honours per-prop entry.matchMode any/all).
// Module-level matching helpers shared by filterCustomChips (live state) and
// getPresetOverrideFiltered (preset overrides, sub-task 5). Same semantics as
// the local helpers used inside filterChips for natives, but with matchMode
// support for multi-select all/any.
function _customScalarOk(val, entry) {
  if (entry.included.size && !entry.included.has(val)) return false;
  if (entry.excluded.has(val)) return false;
  return true;
}
function _customArrayOk(arr, entry, matchMode) {
  const values = Array.isArray(arr) ? arr.map(v => String(v)) : [];
  if (entry.included.size) {
    if (matchMode === 'all') {
      for (const inc of entry.included) if (!values.includes(String(inc))) return false;
    } else {
      const anyIncluded = values.some(v => entry.included.has(v));
      if (!anyIncluded) return false;
    }
  }
  if (entry.excluded.size) {
    const anyExcluded = values.some(v => entry.excluded.has(v));
    if (anyExcluded) return false;
  }
  return true;
}

// Apply a customChips entry to a trade against a declared prop. Returns true
// if the trade passes, false if it fails the entry's filter. Used by both
// filterCustomChips (live) and getPresetOverrideFiltered (per-preset overrides).
function _customEntryPasses(trade, prop, entry) {
  // Refacto Total 2026-05-24 — step 3: read extras under the prop's immutable
  // notionSourceName (the canonical Notion column key set at creation, never
  // mutated by user renames). Eager bake writes here, so reads always find
  // the value when the prop exists in Notion — no fallback chain needed.
  const raw = trade?.extras?.[prop?.notionSourceName];
  if (prop.type === 'multi-select') {
    return _customArrayOk(raw, entry, entry.matchMode || 'any');
  }
  if (prop.type === 'checkbox') {
    const v = raw === null || raw === undefined ? '' : String(Boolean(raw));
    return _customScalarOk(v, entry);
  }
  // select (+ text/date/number if ever surfaced, though UI hides them)
  const v = raw === null || raw === undefined ? '' : String(raw);
  return _customScalarOk(v, entry);
}

function filterCustomChips(trades, skipCustomValue = null) {
  const CC = appState.filters.customChips;
  if (!CC) return trades;
  const activeEntries = Object.entries(CC)
    .map(([k, e]) => {
      if (!e) return [k, e];
      if (skipCustomValue?.key === k) return [k, _entryWithoutValue(e, skipCustomValue.value)];
      return [k, e];
    })
    .filter(([, e]) => e && (e.included?.size > 0 || e.excluded?.size > 0));
  if (!activeEntries.length) return trades;
  const props = (typeof loadCustomProps === 'function') ? loadCustomProps() : [];
  const propByKey = Object.create(null);
  for (const p of props) propByKey[p.key] = p;

  return trades.filter(t => {
    for (const [key, entry] of activeEntries) {
      const prop = propByKey[key];
      if (!prop) continue;
      if (!_customEntryPasses(t, prop, entry)) return false;
    }
    return true;
  });
}

function _getContextFiltered(includeDatasetFilter = true, opts = {}) {
  let filtered = filterDataset(appState.trades.items);
  if (!includeDatasetFilter) filtered = appState.trades.items.slice();
  if (!appState.ui.showRawAll) {
    filtered = filterPreset(filtered);
    filtered = filterChips(filtered, opts.skipChipValue || null);
    filtered = filterCustomChips(filtered, opts.skipCustomChipValue || null);
  }
  filtered = filterTemporal(filtered);

  // BE Management exclusion (set from the ORR widget header). A trade is dropped
  // when its `beManagement` array contains AT LEAST one of the excluded values.
  // Only applied dashboard-wide when a bubble on the ORR chart is active
  // (rrMinFilter !== null). The ORR widget itself applies this filter
  // unconditionally via getFilteredForORR().
  const beMgmtExclude = appState.ui.beManagementExclude || [];
  if (beMgmtExclude.length && appState.ui.rrMinFilter !== null) {
    const excludeSet = new Set(beMgmtExclude);
    filtered = filtered.filter(t => {
      const arr = t.beManagement;
      if (!Array.isArray(arr) || !arr.length) return true;
      return !arr.some(v => excludeSet.has(v));
    });
  }

  return filtered;
}

function getFiltered(opts = {}) {
  const sv  = opts.skipChipValue       ? opts.skipChipValue.dim       + '=' + opts.skipChipValue.value       : '';
  const scv = opts.skipCustomChipValue ? opts.skipCustomChipValue.key + '=' + opts.skipCustomChipValue.value : '';
  const key = _filterStateKey() + '|sv:' + sv + '|scv:' + scv;
  if (_filteredCache && _filteredCache[key]) return _filteredCache[key];

  let filtered = _getContextFiltered(true, opts);
  // RR Min filter (ORR bubble active). Drop every trade whose simulated outcome
  // at the active TP is null — see _getSimulatedR. Applied here (not in
  // _getContextFiltered) so pre-simulation consumers (KPI BE-out detection,
  // Partial Planner, share view BE stats) keep the full sample.
  if (appState.ui.rrMinFilter !== null) {
    filtered = filtered.filter(t => _getSimulatedR(t) !== null);
  }
  filtered = _applySimulation(filtered);

  if (!_filteredCache) _filteredCache = {};
  _filteredCache[key] = filtered;
  _filterCacheKey = key;
  return filtered;
}

// ── ORR-specific filtered view ──
// The Optimal RR widget must always compute on the full filtered dataset
// (presets, chips, temporal, dataset A/B) WITHOUT rrMinFilter — otherwise,
// clicking a bubble would shrink its own input set and distort the curve.
// Also skips _applySimulation: the ORR widget operates on raw rrMax, not
// simulated r. Not cached — this is an ORR-only code path.
function getFilteredForORR() {
  let filtered = filterDataset(appState.trades.items);
  if (!appState.ui.showRawAll) {
    filtered = filterPreset(filtered);
    filtered = filterChips(filtered);
    filtered = filterCustomChips(filtered);
  }
  filtered = filterTemporal(filtered);

  // BE Management filter: trades tagged with any selected value are removed
  // from the calculation sample entirely.
  const beMgmtExclude = appState.ui.beManagementExclude || [];
  if (beMgmtExclude.length) {
    const excludeSet = new Set(beMgmtExclude);
    filtered = filtered.filter(t => {
      const arr = t.beManagement;
      if (!Array.isArray(arr) || !arr.length) return true;
      return !arr.some(v => excludeSet.has(v));
    });
  }

  return filtered;
}

function calcStats(trades, tpConfigArg) {
  if (!trades.length) return null;
  // Second arg is optional for backwards-compat with all 15 existing callers:
  // they pass only trades, so we fall back to appState. When a test/console
  // caller explicitly passes a config, we respect it — otherwise the arg
  // would be silently ignored, which hid Phase 3.B/4 issues during audit.
  const tpConfig = tpConfigArg || appState.ui.tpConfig;
  // Pre-enrich under tpConfig so wins/losses/bes filters and streak loops
  // see classification under the requested config (preset live preview path
  // passes a non-active presetTpConfig — without this, the filters would
  // fall back to the active config inside is*).
  _enrichTradeClassification(trades, tpConfig);
  const n = trades.length;
  const wins   = trades.filter(t => isWinner(t, tpConfig));
  const losses = trades.filter(t => isLoser(t, tpConfig));
  const bes    = trades.filter(t => isBE(t, tpConfig));
  const w = wins.length, l = losses.length;
  const totalR = trades.reduce((s, t) => s + computeEffectiveRR(t, tpConfig), 0);
  const wr = w / n * 100;
  const ev = totalR / n;
  // Profit Factor inherits the new R-effective wins/losses split: BE neutres
  // (effectiveR === 0) are excluded from both gross_w and gross_l. A BE-SL
  // with effectiveR > 0 in personalised mode does contribute to gross_w
  // — assumed behavior, see PR description.
  const gross_w = wins.reduce((s,t)=>s+computeEffectiveRR(t, tpConfig),0);
  const gross_l = Math.abs(losses.reduce((s,t)=>s+computeEffectiveRR(t, tpConfig),0));
  const pf = gross_l > 0 ? gross_w / gross_l : 9.99;

  // equity curve & max DD — trade by trade, sorted by date+hour. BE neutres
  // contribute 0R, so the curve has flat segments (never a drop) on BE — DD
  // doesn't worsen on a BE.
  const _sorted = _sortTradesChronological(trades);
  let eq = 0, peak = 0, maxDD = 0;
  const curve = _sorted.map(t => {
    eq += computeEffectiveRR(t, tpConfig);
    if (eq > peak) peak = eq;
    const dd = eq - peak;
    if (dd < maxDD) maxDD = dd;
    return eq;
  });

  // streaks — basic count. BE neutres are TRANSPARENT: they don't break a
  // sequence and don't count as either side. Sequence W,W,BE,W → maxW=3.
  let maxW=0,maxL=0,cur=0,curSign=0;
  _sorted.forEach(t => {
    if (isBE(t, tpConfig)) return;
    const s = isWinner(t, tpConfig) ? 1 : -1;
    if (s === curSign) { cur++; } else { cur = 1; curSign = s; }
    if (s === 1 && cur > maxW) maxW = cur;
    if (s === -1 && cur > maxL) maxL = cur;
  });

  // streak analytics — collect all win/loss runs. BE neutres are transparent:
  // they neither extend a run's R total nor break it. If a run is in progress
  // and the trailing trades are all BE, the run is still flushed at the end.
  const winRuns = [];   // R total per consecutive-win run
  const lossRuns = [];  // R total per consecutive-loss run
  let runR = 0, runSign = 0;
  _sorted.forEach((t, i) => {
    if (isBE(t, tpConfig)) {
      if (i === _sorted.length - 1 && runSign !== 0) {
        (runSign === 1 ? winRuns : lossRuns).push(runR);
      }
      return;
    }
    const s = isWinner(t, tpConfig) ? 1 : -1;
    if (s === runSign) {
      runR += t.effectiveR;
    } else {
      if (runSign !== 0) (runSign === 1 ? winRuns : lossRuns).push(runR);
      runR = t.effectiveR; runSign = s;
    }
    if (i === _sorted.length - 1) (runSign === 1 ? winRuns : lossRuns).push(runR);
  });

  const avgWinStreakR  = winRuns.length  ? winRuns.reduce((s,v)=>s+v,0)  / winRuns.length  : null;
  const avgLossStreakR = lossRuns.length ? lossRuns.reduce((s,v)=>s+v,0) / lossRuns.length : null;
  const maxConsecProfitR = winRuns.length ? Math.max(...winRuns) : null;
  const maxConsecLossR   = lossRuns.length ? Math.min(...lossRuns) : null;  // worst consecutive-loss run (negative R)

  const be_tp = trades.filter(t=>t.outcome==='BE-TP').length;
  const be_sl = trades.filter(t=>t.outcome==='BE-SL').length;
  const be    = be_tp + be_sl;
  // Outcome-Notion-pure counts: immutable across TP modes. Distinct from w/l
  // (R-effective classification, mode-dependent). Use cnt_tp/cnt_sl for
  // outcome breakdowns (donut slices, Trades Count tooltip); use w/l for
  // classification breakdowns (KPI WR sub-labels). Mixing them double-counts
  // BE-* trades when a BE-SL/BE-TP gets reclassified by R-effective sign.
  const cnt_tp = trades.filter(t=>t.outcome==='TP').length;
  const cnt_sl = trades.filter(t=>t.outcome==='SL').length;
  const avgWin  = w > 0 ? gross_w / w   : null;
  const avgLoss = l > 0 ? -gross_l / l  : null;

  return { n, w, l, bes:bes.length, be, be_tp, be_sl, cnt_tp, cnt_sl, wr, ev, totalR, pf, curve, maxDD, maxW, maxL, avgWin, avgLoss, avgWinStreakR, avgLossStreakR, maxConsecProfitR, maxConsecLossR };
}

// ══════════════════════════════════════════════════════
// CHIP BUILDER
// ══════════════════════════════════════════════════════

// Count trades having `value` in dimension `filterKey`, computed on the filtered
// dataset with the filterKey dimension skipped (so the chip's own filter does
// not suppress its own count). Cross-dimensional: every other active filter
// applies.
function _chipCountFor(filterKey, value) {
  const opts = filterKey.startsWith('custom:')
    ? { skipCustomChipValue: { key: filterKey.slice(7), value } }
    : { skipChipValue:       { dim: filterKey, value } };
  const dataset = getFiltered(opts);

  return dataset.filter(t => {
    if (filterKey === 'obstacles')    return (t.obstacles || []).some(o => o.toLowerCase() === String(value).toLowerCase());
    if (filterKey === 'h4obs')        return (t.h4 || []).some(h => h.toLowerCase() === String(value).toLowerCase());
    if (filterKey === 'tradeType')    return (t.tradeType || []).includes(value);
    if (filterKey === 'beManagement') return (t.beManagement || []).includes(value);
    if (filterKey === 'badFeeling')   return (t.badFeeling ? 'Yes' : 'No') === value;
    if (filterKey === 'hour')         return String(t.hour) === String(value);
    if (filterKey.startsWith('custom:')) {
      const propKey = filterKey.slice(7);
      const v = t?.extras?.[propKey];
      if (v === null || v === undefined || v === '') return false;
      if (Array.isArray(v)) return v.some(x => String(x) === String(value));
      return String(v) === String(value);
    }
    return t[filterKey] === value;
  }).length;
}

function _chipStateFor(filterKey, item) {
  const entry = _resolveChipEntry(filterKey);
  if (!entry) return 'neutral';
  if (entry.included.has(item)) return 'included';
  if (entry.excluded.has(item)) return 'excluded';
  return 'neutral';
}

/** Is this chip value preset-flagged (drives the glow)? */
function _chipIsFromPreset(filterKey, item) {
  const entry = _resolveChipEntry(filterKey);
  if (!entry) return false;
  return (entry.includedFromPreset && entry.includedFromPreset.has(item))
      || (entry.excludedFromPreset && entry.excludedFromPreset.has(item));
}

function _applyChipClasses(chipEl, state, filterKey) {
  const val = chipEl.dataset.val;
  const suffix = state === 'excluded' ? ' excluded'
               : state === 'included' ? ' included'
               : '';
  const fromPreset = (state !== 'neutral') && _chipIsFromPreset(filterKey, val);
  const tombstoned = state === 'neutral' && _chipIsTombstoned(filterKey, val);
  chipEl.className = 'chip' + suffix
    + (fromPreset ? ' is-from-preset' : '')
    + (tombstoned ? ' is-tombstoned' : '');
  if (tombstoned)                chipEl.title = 'Removed from active preset — click to restore';
  else if (state === 'excluded') chipEl.title = fromPreset ? 'Excluded by active preset — click to strip' : 'Click to clear (excluded)';
  else if (state === 'included') chipEl.title = fromPreset ? 'Included by active preset — click to strip' : 'Click to clear (included)';
  else {
    const groupMode = _resolveChipEntry(filterKey)?.mode || 'neutral';
    chipEl.title = groupMode === 'include' ? 'Click to include'
                 : groupMode === 'exclude' ? 'Click to exclude'
                 : 'Click to add (will switch to include mode)';
  }
}

function buildChips(containerId, items, filterKey, labelFn) {
  const container = document.getElementById(containerId);
  if (!container) return;

  if (container.dataset.dimVersion === String(_dimVersion) && container.children.length === items.length) {
    // Fast path: items list unchanged — refresh state classes AND cross-dimensional counts
    Array.from(container.children).forEach(chip => {
      const item = chip.dataset.val;
      if (item === undefined) return;
      _applyChipClasses(chip, _chipStateFor(filterKey, item), filterKey);
      const nEl = chip.querySelector('.chip-n');
      if (nEl) nEl.textContent = String(_chipCountFor(filterKey, item));
    });
  } else {
    // Full rebuild: new CSV loaded or first render
    container.innerHTML = '';
    items.forEach(item => {
      const count = _chipCountFor(filterKey, item);
      const chip = document.createElement('div');
      chip.className = 'chip';
      chip.tabIndex = 0;
      chip.dataset.action = 'toggle-filter';
      chip.dataset.key = filterKey;
      chip.dataset.val = item;
      _applyChipClasses(chip, _chipStateFor(filterKey, item), filterKey);
      chip.innerHTML = `<span>${labelFn ? labelFn(item) : item}</span><span class="chip-n">${count}</span>`;
      container.appendChild(chip);
    });
    container.dataset.dimVersion = String(_dimVersion);
  }

  // update count badge — total active (included + excluded) or items.length if none
  const entry = _resolveChipEntry(filterKey);
  const activeCount = (entry?.included.size || 0) + (entry?.excluded.size || 0);
  // cntKey mapping covers native alias shortenings + 'custom:<k>' → 'custom-<k>' for
  // the per-prop count span injected by renderCustomFilterChips().
  const cntKey = filterKey==='obstacles'?'obs'
               : filterKey==='tradeType'?'tradetype'
               : filterKey==='beManagement'?'bemgmt'
               : filterKey==='badFeeling'?'badfeeling'
               : (typeof filterKey === 'string' && filterKey.startsWith('custom:'))
                 ? 'custom-' + filterKey.slice(7)
                 : filterKey;
  const cnt = document.getElementById('cnt-' + cntKey);
  if(cnt) cnt.textContent = activeCount || items.length;

  // Sync the 3 mode buttons (NEUTRE/EXCLURE/INCLURE) for this filter group
  _syncChipModeButtons(filterKey);

  // Auto-hide the entire .filter-group parent when the dim is mapped to
  // __NO_MAPPING__ (template exclusion or manual user "No Mapping" pick).
  // The group has zero data by construction (normalize step skips the
  // column) so showing it as a list of zero-count chips is pure noise.
  // Skips custom chips (filterKey starts with 'custom:') — those are
  // user-declared via Custom Fields and outside the JOURNAL_DIMS system.
  if (typeof filterKey === 'string' && !filterKey.startsWith('custom:')) {
    const dimKey = _FILTER_KEY_TO_DIM_KEY[filterKey];
    if (dimKey) {
      const parent = container.closest('.filter-group');
      if (parent) parent.style.display = _isDimNoMapping(dimKey) ? 'none' : '';
    }
  }
}

// 3-state chip cycle (per-key click-mode): if the group's mode is 'neutral',
// clicking a chip auto-switches the group to the last active mode used across
// any group (defaults to 'include'). This way, choosing Exclude on one group
// and then clicking chips in another group keeps Exclude propagating.
let _lastChipMode = 'exclude';

/** Re-apply chip CSS classes (including .is-from-preset glow) on every chip
 *  in the Filters sidebar section, without rebuilding the DOM. Used after
 *  Save/Update/Reset so the flag changes take effect instantly. Mapping
 *  from DOM container id → filter key matches buildChips() calls in render(). */
const _CHIP_CONTAINER_KEY_MAP = {
  'chips-setup': 'setup',
  'chips-session': 'session',
  'chips-day': 'day',
  'chips-pair': 'pair',
  'chips-obs': 'obstacles',
  'chips-h4obs': 'h4obs',
  'chips-tradetype': 'tradeType',
  'chips-bemgmt': 'beManagement',
  'chips-badfeeling': 'badFeeling',
};
function _refreshAllChipDisplays() {
  for (const [containerId, filterKey] of Object.entries(_CHIP_CONTAINER_KEY_MAP)) {
    const container = document.getElementById(containerId);
    if (!container) continue;
    Array.from(container.children).forEach(chipEl => {
      const val = chipEl.dataset.val;
      if (val === undefined) return;
      _applyChipClasses(chipEl, _chipStateFor(filterKey, val), filterKey);
    });
    _syncChipModeButtons(filterKey);
  }
  // Custom chip containers are rendered per-prop with id `chips-custom-<propKey>`.
  document.querySelectorAll('[id^="chips-custom-"]').forEach(container => {
    const propKey = container.id.replace(/^chips-custom-/, '');
    const filterKey = 'custom:' + propKey;
    Array.from(container.children).forEach(chipEl => {
      const val = chipEl.dataset.val;
      if (val === undefined) return;
      _applyChipClasses(chipEl, _chipStateFor(filterKey, val), filterKey);
    });
    _syncChipModeButtons(filterKey);
  });
}

function toggleFilter(key, val) {
  invalidateFilterCache();
  setRawMode(false);
  _exitRawBtn();
  const entry = _resolveChipEntry(key);
  if (!entry) return;
  _ensureFromPresetSets(entry);

  // Tombstoned chip clicked → restore to its original snapshot bucket with
  // the preset glow intact. Skips the include/exclude mode selector because
  // the value belongs to the preset; re-adding means returning to base.
  const tombBucket = _chipTombstoneBucket(key, val);
  if (tombBucket) {
    _restoreTombstone(entry, tombBucket, val);
    _syncChipModeButtons(key);
    _syncLiveSlotFromActiveChips();
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
    render();
    return;
  }

  if (entry.mode === 'neutral') entry.mode = _lastChipMode;
  const activeBucketName = entry.mode === 'include' ? 'included' : 'excluded';
  const otherBucketName  = entry.mode === 'include' ? 'excluded' : 'included';

  const inActive = entry[activeBucketName].has(val);
  const inOther  = entry[otherBucketName].has(val);

  if (inActive) {
    // Clicking a currently-applied chip removes it. If it was preset-flagged,
    // fromPreset stays (value becomes tombstoned). If it was live, main
    // simply empties.
    _setChipValue(entry, activeBucketName, val, 'remove');
  } else if (inOther) {
    // Flip buckets. fromPreset in the other bucket (if any) stays — creates
    // a tombstone in that bucket while the value lives in the new bucket.
    _setChipValue(entry, otherBucketName, val, 'remove');
    _setChipValue(entry, activeBucketName, val, 'add', false);
  } else {
    // Fresh add — live only.
    _setChipValue(entry, activeBucketName, val, 'add', false);
  }

  // Keep the mode buttons in sync (empty sets still show the active mode).
  _syncChipModeButtons(key);
  _syncLiveSlotFromActiveChips();
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
  // Mirror chip-state change into an open tune panel — both views edit the
  // same underlying appState.filters.chips, so the panel must re-render.
  if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
  render();
}

// Remove a chip filter regardless of bucket — used by the "active filters" × pills.
// Routes through _resolveChipEntry so custom:<key> pills work identically to natives.
function removeActiveChipFilter(key, val) {
  invalidateFilterCache();
  const entry = _resolveChipEntry(key);
  if (!entry) return;
  _setChipValue(entry, 'included', val, 'remove');
  _setChipValue(entry, 'excluded', val, 'remove');
  _syncLiveSlotFromActiveChips();
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
  if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
  render();
}

function removeActiveComboFilter(comboType, val) {
  invalidateFilterCache();
  const entry = appState.filters.comboFilters?.[comboType];
  if (!entry) return;
  entry.included.delete(val);
  entry.excluded.delete(val);
  _syncLiveSlotFromActiveChips();
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
  // Combo filters aren't rendered as chips in the tune panel, but the po-stats
  // block (n/WR/avg R/total R) reflects the filtered trade set — and combos
  // participate in filterChips. Rebuild so those numbers stay accurate.
  if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
  render();
}

function resetAll() {
  invalidateFilterCache();
  // Activate raw mode — show all 567 trades unfiltered
  setRawMode(true);

  // Phase 3 : resetAll vide les slots live du preset actif ET du pseudo-preset
  // null (où l'on va atterrir). Les slots des autres presets restent intacts —
  // resetAll est un reset du contexte courant, pas du monde entier.
  const prevActiveId = appState.presets.activeId;
  presetLiveFilters[_liveKey(prevActiveId)] = _blankLiveSlot();
  if (prevActiveId !== null) presetLiveFilters['null'] = _blankLiveSlot();
  savePresetLiveFilters();

  clearChipFilters();
  _clearComboFilters();
  resetExclusionState();
  setActivePreset(null);
  // Reset temporal filter to Global
  appState.filters.temporal.tf.mode = 'global'; appState.filters.temporal.tf.year = null; appState.filters.temporal.tf.quarter = null; appState.filters.temporal.tf.month = null; appState.filters.temporal.tf.compare = false;
  setTemporalRange(null, null);
  tfSetMode('global');
  const chk = document.getElementById('tf-compare-chk');
  if (chk) chk.checked = false;
  tfClearKpiDeltas();
  document.getElementById('pcb-bar')?.classList.add('hidden');
  document.getElementById('cmp-table-wrap')?.classList.add('hidden');

  render();
}

function _exitRawBtn() {
  const resetBtn = document.querySelector('.reset-btn');
  if (resetBtn && resetBtn.classList.contains('raw-active')) {
    setResetButtonMode(false);
  }
}

function exitRawMode() {
  invalidateFilterCache();
  setRawMode(false);
  render();
}

// ══════════════════════════════════════════════════════
// RENDER ACTIVE FILTERS (compat alias)
// ══════════════════════════════════════════════════════
// The active-filter pills + counter now live inside the CONTEXT strip's
// consolidated container, rendered by updateContextStrip(). This alias keeps
// legacy call sites working without a mass rename.
function renderActiveFilters(_filteredCount) {
  if (typeof updateContextStrip === 'function') updateContextStrip();
}

// ══════════════════════════════════════════════════════
// THEME COLOR READER — reads live CSS vars at draw time
// ══════════════════════════════════════════════════════
function tc(varName) {
  const raw = getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
  // When called inside a chart render that's wrapped by _withWidgetScale, scale
  // widget-scoped typography vars by the active stack value so chart-internal
  // text (Chart.js fonts, raw canvas drawText) follows widget size in auto mode.
  if (_widgetScaleStack.length === 0) return raw;
  if (!WIDGET_SCOPED_TYPO_VARS.includes(varName)) return raw;
  const num = parseFloat(raw);
  if (isNaN(num)) return raw;
  const scale = _widgetScaleStack[_widgetScaleStack.length - 1];
  const floor = Math.min(num, TYPO_AUTO_FLOOR_PX);
  return Math.max(floor, num * scale).toFixed(2) + 'px';
}

function hexToRgba(hex, a) {
  const h = String(hex || '').replace('#','').trim();
  const full = h.length === 3 ? h.split('').map(c => c+c).join('') : h;
  if (!/^[0-9a-f]{6}$/i.test(full)) return `rgba(0,0,0,${a})`;
  const r = parseInt(full.slice(0,2), 16);
  const g = parseInt(full.slice(2,4), 16);
  const b = parseInt(full.slice(4,6), 16);
  return `rgba(${r},${g},${b},${a})`;
}
function getWinColor()          { return tc('--g') || '#5dd6a8'; }
function getLossColor()         { return tc('--r') || '#e05a6e'; }
function getWinColorAlpha(a)    { const c = getWinColor();  return c.startsWith('#') ? hexToRgba(c, a) : c; }
function getLossColorAlpha(a)   { const c = getLossColor(); return c.startsWith('#') ? hexToRgba(c, a) : c; }
function tcRgba(varName, alpha) {
  // Read a hex var and return rgba string
  const hex = tc(varName);
  const r = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  if (!r) return hex;
  return `rgba(${parseInt(r[1],16)},${parseInt(r[2],16)},${parseInt(r[3],16)},${alpha})`;
}

// ── Sort state per chart ──
const barSortState = {
  setup:   'desc',
  session: 'canonical',
  pair:    'desc',
  obs:     'desc',
  h4obs:   'desc',
  day:     'canonical',  // canonical = DAY_ORDER (Mon→Sun)
};

// Frozen defaults — used to decide whether to keep the sort row pinned visible
// (class "has-custom-sort") when user picks a non-default mode. Must match
// barSortState initial values above and _hourSort default ('canonical').
const _BAR_SORT_DEFAULTS = Object.freeze({
  setup:   'desc',
  session: 'canonical',
  pair:    'desc',
  obs:     'desc',
  h4obs:   'desc',
  day:     'canonical',
});

// Canonical session order
const SESSION_ORDER = ['Asian','London','Lunch Time Zone','New-York','Hors Session',"No Man's Land"];
// Canonical day order (Mon→Sun)
const DAY_ORDER = ['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];

// ── Sort sync: apply same sort to all bar-chart widgets ──
let _sortSyncEnabled = false;
// Map sort modes between widgets that have 'alpha' vs 'canonical'
const _SORT_CHARTS_WITH_ALPHA     = ['setup', 'pair', 'obs', 'h4obs'];
const _SORT_CHARTS_WITH_CANONICAL = ['session', 'day'];
const _ALL_BAR_CHARTS = ['setup', 'session', 'pair', 'obs', 'h4obs', 'day'];

function _getCustomBarChartDef(chartId) {
  if (!chartId || !String(chartId).startsWith('w-cust-')) return null;
  return _loadCustomWidgetDefs().find(d => d.id === chartId && d.type === 'bars') || null;
}

function _getBarSortFamily(chartId) {
  if (_SORT_CHARTS_WITH_CANONICAL.includes(chartId)) return 'canonical';
  if (_SORT_CHARTS_WITH_ALPHA.includes(chartId)) return 'alpha';
  const def = _getCustomBarChartDef(chartId);
  if (!def) return 'alpha';
  const key = String(def.propertyKey || def.field || '').trim().toLowerCase();
  if (key === 'session' || key === 'day' || key === 'hour') return 'canonical';
  return 'alpha';
}

function _getAllLinkedBarChartIds() {
  const customIds = _loadCustomWidgetDefs()
    .filter(d => d.type === 'bars')
    .map(d => d.id);
  return [..._ALL_BAR_CHARTS, ...customIds];
}

function _getInitialBarSortMode(chartId) {
  const family = _getBarSortFamily(chartId);
  if (!_sortSyncEnabled) return family === 'canonical' ? 'canonical' : 'desc';
  const sourceId = family === 'canonical'
    ? (_ALL_BAR_CHARTS.find(id => _getBarSortFamily(id) === 'canonical') || 'session')
    : (_ALL_BAR_CHARTS.find(id => _getBarSortFamily(id) === 'alpha') || 'setup');
  return barSortState[sourceId] || (family === 'canonical' ? 'canonical' : 'desc');
}

function _renderCustomBarSortToolbarHTML(chartId) {
  const family = _getBarSortFamily(chartId);
  const firstMode = family === 'canonical' ? 'canonical' : 'alpha';
  const activeMode = barSortState[chartId] || _getInitialBarSortMode(chartId);
  return `
    <div class="bar-sort-row" id="sort-${_escapeAttr(chartId)}">
      <button class="bar-sort-btn sort-sync-btn${_sortSyncEnabled ? ' active' : ''}" data-action="toggle-sort-sync" title="Sync sort across all widgets">⛓</button>
      <button class="bar-sort-btn${activeMode === firstMode ? ' active' : ''}" data-action="set-bar-sort" data-chart="${_escapeAttr(chartId)}" data-sort="${firstMode}">A → Z</button>
      <button class="bar-sort-btn${activeMode === 'desc' ? ' active' : ''}" data-action="set-bar-sort" data-chart="${_escapeAttr(chartId)}" data-sort="desc">Best → Worst</button>
      <button class="bar-sort-btn${activeMode === 'asc' ? ' active' : ''}" data-action="set-bar-sort" data-chart="${_escapeAttr(chartId)}" data-sort="asc">Worst → Best</button>
      <button class="bar-sort-btn${activeMode === 'volume' ? ' active' : ''}" data-action="set-bar-sort" data-chart="${_escapeAttr(chartId)}" data-sort="volume">Volume</button>
    </div>`;
}

function _renderBarChartById(chartId, trades = getFiltered()) {
  const filtered = Array.isArray(trades) ? trades : [];
  const absMax = 1.8;
  if (chartId === 'setup')   { renderBars('bars-setup',   groupByEV(filtered, t => setupDetailMode ? (t.setupDetail||t.setup) : t.setup, k => k), absMax, false, 'setup'); return true; }
  if (chartId === 'session') { renderBars('bars-session', groupByEV(filtered, t => t.session, k => SESSION_SHORT[k] || k), absMax, false, 'session'); return true; }
  if (chartId === 'pair')    { renderBars('bars-pair',    groupByEV(filtered, t => t.pair), absMax, false, 'pair'); return true; }
  if (chartId === 'obs')     { renderObsBars(filtered); return true; }
  if (chartId === 'h4obs')   { renderH4ObsBars(filtered); return true; }
  if (chartId === 'day')     { renderDayBars(filtered); return true; }
  const cwDef = _getCustomBarChartDef(chartId);
  if (cwDef) {
    renderCustomBars(cwDef, filtered);
    return true;
  }
  return false;
}

function _getTradesForBarChartSelection(chartId, rawKey, trades = getFiltered()) {
  const filtered = Array.isArray(trades) ? trades : [];
  if (!rawKey) return [];
  switch (chartId) {
    case 'setup':
      return filtered.filter(t => (setupDetailMode ? (t.setupDetail||t.setup) : t.setup) === rawKey);
    case 'session':
      return filtered.filter(t => t.session === rawKey);
    case 'pair':
      return filtered.filter(t => t.pair === rawKey);
    case 'day':
      return filtered.filter(t => t.day === rawKey);
    case 'obs':
      return filtered.filter(t => Array.isArray(t.obstacles) && t.obstacles.includes(rawKey));
    case 'h4obs':
      return filtered.filter(t => Array.isArray(t.h4) && t.h4.includes(rawKey));
    case 'hour': {
      const h = parseInt(rawKey, 10);
      return Number.isNaN(h) ? [] : filtered.filter(t => t.hour === h);
    }
    default: {
      const def = _getCustomBarChartDef(chartId);
      if (!def) return [];
      return filtered.filter(t => {
        const vals = _cwExpandFieldValues(
          _cwGetFieldValue(t, def.field, def, def.fieldSource || def.propertySource),
          def.inferredType
        );
        return vals.includes(rawKey);
      });
    }
  }
}

function _getBarChartIdFromContainerId(containerId) {
  const map = {
    'bars-setup': 'setup',
    'bars-session': 'session',
    'bars-pair': 'pair',
    'bars-day': 'day',
    'bars-obs': 'obs',
    'bars-h4obs': 'h4obs',
    'bars-hour': 'hour',
  };
  if (map[containerId]) return map[containerId];
  if (String(containerId || '').startsWith('bars-w-cust-')) return String(containerId).slice(5);
  return '';
}

function _buildCustomWidgetDeleteButtonHTML(id) {
  return `<button type="button" class="gs-delete-btn" title="Delete this widget" data-action="layout-delete-widget-confirm" data-cw-id="${_escapeAttr(id)}" aria-label="Delete this widget">
    <svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg>
  </button>`;
}

function toggleSortSync() {
  _sortSyncEnabled = !_sortSyncEnabled;
  document.querySelectorAll('.sort-sync-btn').forEach(b => b.classList.toggle('active', _sortSyncEnabled));
}

function _syncedSort(mode) {
  // Maps a mode to the equivalent for charts that support alpha vs canonical
  // desc, asc, volume are universal; alpha ↔ canonical
  if (mode === 'alpha')     return { alpha: 'alpha', canonical: 'canonical' };
  if (mode === 'canonical') return { alpha: 'alpha', canonical: 'canonical' };
  return { alpha: mode, canonical: mode };
}

let _sortSyncGuard = false;

function setBarSort(chart, mode) {
  barSortState[chart] = mode;
  // Update active button
  const row = document.getElementById(`sort-${chart}`);
  if (row) {
    row.querySelectorAll('.bar-sort-btn:not(.sort-sync-btn)').forEach(b => {
      b.classList.toggle('active', b.dataset.sort === mode);
    });
  }
  // Re-render with current data
  const filtered = getFiltered();
  _renderBarChartById(chart, filtered);

  // Propagate to all other charts if sync is enabled
  if (_sortSyncEnabled && !_sortSyncGuard) {
    _sortSyncGuard = true;
    const mapped = _syncedSort(mode);
    _getAllLinkedBarChartIds().forEach(c => {
      if (c === chart) return;
      const m = _getBarSortFamily(c) === 'canonical' ? mapped.canonical : mapped.alpha;
      setBarSort(c, m);
    });
    // Also sync hour widget
    setHourSort(mapped.canonical);
    _sortSyncGuard = false;
  }
}

function sortItems(items, chart, keyFn) {
  // keyFn: optional fn to override the numeric sort key (e.g. d => d.totalR)
  const valFn  = keyFn || (d => d.ev);
  const labelFn = d => d.label;
  const mode   = barSortState[chart] || 'desc';

  if (mode === 'desc')  return [...items].sort((a, b) => valFn(b) - valFn(a));
  if (mode === 'asc')   return [...items].sort((a, b) => valFn(a) - valFn(b));
  if (mode === 'alpha') {
    return [...items].sort((a, b) => {
      const ka = String(labelFn(a)); const kb = String(labelFn(b));
      return ka.localeCompare(kb);
    });
  }

  if (mode === 'volume') return [...items].sort((a, b) => b.n - a.n);

  if (mode === 'canonical') {
    // Session canonical order: Asian → London → Lunch → NY → Off-sess → NML
    return [...items].sort((a, b) => {
      const ia = SESSION_ORDER.indexOf(a._rawKey ?? a.label);
      const ib = SESSION_ORDER.indexOf(b._rawKey ?? b.label);
      // Unknown sessions go to the end, sorted by EV
      if (ia === -1 && ib === -1) return b.ev - a.ev;
      if (ia === -1) return 1;
      if (ib === -1) return -1;
      return ia - ib;
    });
  }
  return items;
}

// ── Bar chart metric mode: 'ev' (Avg R) or 'total' (Total R) ──
const BAR_MODE_KEY = 'flipping_bar_mode';
let barMode = (() => {
  const v = localStorage.getItem(BAR_MODE_KEY);
  return ['total', 'ev', 'wr', 'n'].includes(v) ? v : 'total';
})();

// ── Bar chart view: 'global' (combined) or 'split' (diverging by outcome) ──
const BAR_VIEW_KEY = 'flipping_bar_view';
let barView = (() => {
  const v = localStorage.getItem(BAR_VIEW_KEY);
  return ['global', 'split'].includes(v) ? v : 'global';
})();

// ── TradingView Snapshot URL support ──
// TV "Share" URLs (Alt+S) look like https://www.tradingview.com/x/<ID>/ and host a
// chart snapshot page that embeds the actual PNG. The PNG sits at a deterministic
// S3 path: https://s3.tradingview.com/snapshots/<first-lowercase-char-of-ID>/<ID>.png
// (empirically verified: the shard key is the FIRST char of the ID, not the last.)
// Unlike Notion's signed S3 URLs (~1h TTL), TV snapshots never expire — giving
// CSV-mode users a durable screenshot option when they paste TV links into
// plain URL properties. Passthrough for anything that isn't a TV /x/ URL.
const _TV_SHARE_RE = /^https?:\/\/(?:www\.)?tradingview\.com\/x\/([A-Za-z0-9]+)\/?(?:[?#].*)?$/i;
function _normalizeTvImageUrl(raw) {
  const s = (raw == null) ? '' : String(raw).trim();
  if (!s) return { url: '', isTv: false, origLink: '' };
  const m = s.match(_TV_SHARE_RE);
  if (!m) return { url: s, isTv: false, origLink: '' };
  const id    = m[1];
  const first = id.charAt(0).toLowerCase();
  return {
    url:      `https://s3.tradingview.com/snapshots/${first}/${id}.png`,
    isTv:     true,
    origLink: s,
  };
}

// ── Supabase Storage fallback for expired Notion S3 URLs ──────────────────────
// Notion file URLs expire ~1h after they're minted by the OAuth proxy. The
// media queue uploads them to Supabase Storage at sync-time and patches the
// in-memory trade with the permanent URL, but if (a) the upload silently
// failed, (b) a later re-sync clobbered the patched URL before the
// `_preservePermanentImageUrls` helper shipped (2026-05-24), or (c) the user
// has not re-synced since the helper deployed, the in-memory trade can still
// carry an expired Notion URL while a permanent one sits in Supabase.
//
// Recovery is deterministic: storage path is
//   notion-screenshots/<notion_id>_<slot>.png
// (bucket is public-read, no auth needed). When the lightbox <img> fails to
// load AND the failed URL is a Notion S3 URL, we test-load the Supabase URL.
// On 200 we swap imgEl.src AND patch appState.trades.items so subsequent
// renders of this trade skip straight to the permanent URL — one click
// rescues the trade for the rest of the session.
//
// _notionId resolution: _lbData rows don't carry _notionId (lightbox keys on
// pair+date+URL only), so we match back to the trade in appState by the same
// triple. Slot resolution: m15After is profile-source-dependent (h4_after on
// H4 profiles vs m15_after on M15), per _fieldToSlot in _mediaQueue.
const _SUPABASE_SCREENSHOTS_BASE = 'https://pjkilmmltbyugjxbvyvh.supabase.co/storage/v1/object/public/notion-screenshots';
const _LB_STEP_TO_SLOT = { h4Before: 'h4_before', m15Before: 'm15_before' };
const _LB_STEP_TO_TRADE_FIELD = { h4Before: 'imgH4Before', m15Before: 'imgM15', m15After: 'imgM15After' };
function _resolveLbStepSlot(step) {
  return _LB_STEP_TO_SLOT[step] || ((_getCurrentHTFSource() === 'h4') ? 'h4_after' : 'm15_after');
}
function _findTradeForLbRow(tr, url) {
  // Match a _lbData row back to its source trade in appState by pair+date+URL.
  // URL match across all 6 image fields (current + Orig) to cover the case
  // where the user clicks the H4 Before slot but pair+date alone isn't unique.
  if (!tr) return null;
  const items = appState?.trades?.items;
  if (!Array.isArray(items) || !items.length) return null;
  return items.find(t => {
    if (t.pair !== tr.pair || t.date !== tr.date) return false;
    return !url || t.imgM15 === url || t.imgH4Before === url || t.imgM15After === url
        || t.imgM15Orig === url || t.imgH4BeforeOrig === url || t.imgM15AfterOrig === url;
  }) || null;
}
// Pre-resolve a (potentially expired) Notion S3 URL to its deterministic
// Supabase Storage equivalent BEFORE setting imgEl.src — eliminates the ~1s
// "Lien TradingView invalide" placeholder flash that would otherwise occur
// while waiting for the Notion 403. Returns '' when no swap is possible
// (URL not Notion S3, no matching trade, no _notionId on the trade).
function _resolveLightboxImageUrl(url, tr, step) {
  if (!url || !_isNotionFileUrl(url)) return '';
  const matched = _findTradeForLbRow(tr, url);
  if (!matched?._notionId) return '';
  return `${_SUPABASE_SCREENSHOTS_BASE}/${matched._notionId}_${_resolveLbStepSlot(step)}.png`;
}
function _patchTradeAndLbRowToSupabase(tr, step, supabaseUrl, originalUrl) {
  if (!tr || !step || !supabaseUrl || !originalUrl) return;
  if (tr[step] === originalUrl) tr[step] = supabaseUrl;
  const tradeField = _LB_STEP_TO_TRADE_FIELD[step] || 'imgM15After';
  const items = appState?.trades?.items;
  if (!Array.isArray(items)) return;
  const matched = items.find(t => t.pair === tr.pair && t.date === tr.date && (
    t.imgM15 === originalUrl || t.imgH4Before === originalUrl || t.imgM15After === originalUrl ||
    t.imgM15Orig === originalUrl || t.imgH4BeforeOrig === originalUrl || t.imgM15AfterOrig === originalUrl
  ));
  if (!matched) return;
  if (matched[tradeField] === originalUrl) matched[tradeField] = supabaseUrl;
  const origField = tradeField + 'Orig';
  if (matched[origField] === originalUrl) matched[origField] = supabaseUrl;
}
function _tryRescueFromSupabase(imgEl, failedUrl) {
  if (!imgEl || !failedUrl || !_isNotionFileUrl(failedUrl)) return false;
  const tr = _lbData[_lbTradeIdx];
  if (!tr) return false;
  const items = appState?.trades?.items;
  if (!Array.isArray(items) || !items.length) return false;
  // Match by pair+date+URL across all 6 image fields (current + Orig).
  const matchedItem = items.find(t => {
    if (t.pair !== tr.pair || t.date !== tr.date) return false;
    return t.imgM15 === failedUrl || t.imgH4Before === failedUrl || t.imgM15After === failedUrl
        || t.imgM15Orig === failedUrl || t.imgH4BeforeOrig === failedUrl || t.imgM15AfterOrig === failedUrl;
  });
  const notionId = matchedItem?._notionId;
  if (!notionId) return false;
  const step = _lbStep;
  const slot = _LB_STEP_TO_SLOT[step] || ((_getCurrentHTFSource() === 'h4') ? 'h4_after' : 'm15_after');
  const supabaseUrl = `${_SUPABASE_SCREENSHOTS_BASE}/${notionId}_${slot}.png`;
  const tradeField = _LB_STEP_TO_TRADE_FIELD[step] || 'imgM15After';
  // Test-load asynchronously. On success we swap the lightbox img, patch the
  // trade in-memory (self-healing for this session), and remove the
  // placeholder if the generic fallback already inserted one.
  const test = new Image();
  test.onload = () => {
    if (imgEl.src === failedUrl || _isNotionFileUrl(imgEl.src)) {
      imgEl.src = supabaseUrl;
      imgEl.style.display = '';
    }
    if (matchedItem[tradeField] === failedUrl) matchedItem[tradeField] = supabaseUrl;
    const origField = tradeField + 'Orig';
    if (matchedItem[origField] === failedUrl) matchedItem[origField] = supabaseUrl;
    // Also patch the _lbData row so navigation within the same lightbox
    // session doesn't re-trigger the same broken-URL path.
    if (tr[step] === failedUrl) tr[step] = supabaseUrl;
    const parent = imgEl.parentElement;
    if (parent) parent.querySelectorAll('.tv-img-placeholder').forEach(n => n.remove());
    debugLog('[ImgRescue] swapped expired Notion → Supabase:', notionId, slot);
  };
  test.src = supabaseUrl;
  return true;
}

// Idempotent onerror swap: replaces a broken <img> with a placeholder card.
// Reads the original share URL from imgEl.dataset.tvOrig — empty means non-TV
// source (expired Notion S3, custom host, typo), so we drop the "Open on TV"
// link and show a generic hint instead. Flag tvFallbackInstalled prevents
// double-binding when _lbShow is called repeatedly on the same <img> element.
function _installTvImageFallback(imgEl) {
  if (!imgEl || imgEl.dataset.tvFallbackInstalled === '1') return;
  imgEl.dataset.tvFallbackInstalled = '1';
  // On successful load: if we pre-swapped Notion → Supabase at _lbShow time
  // (notionFallback dataset is set), persist the swap into _lbData + appState
  // so the rest of the app sees the permanent URL. Avoids re-resolving on
  // every navigation and keeps the trade consistent across renders.
  imgEl.addEventListener('load', function _onTvLoad() {
    const notionFallback = imgEl.dataset.notionFallback || '';
    if (!notionFallback) return;
    if (!imgEl.src.startsWith(_SUPABASE_SCREENSHOTS_BASE)) return;
    const tr = _lbData[_lbTradeIdx];
    _patchTradeAndLbRowToSupabase(tr, _lbStep, imgEl.src, notionFallback);
    // Once persisted, clear the dataset so we don't double-patch on later loads.
    delete imgEl.dataset.notionFallback;
    delete imgEl.dataset.notionRetried;
  });
  imgEl.addEventListener('error', function _onTvErr() {
    const parent = imgEl.parentElement;
    if (!parent) return;
    if (parent.querySelector('.tv-img-placeholder')) { imgEl.style.display = 'none'; return; }
    // First failure path: pre-swap to Supabase happened but Supabase 404'd
    // (image was never uploaded for this trade — sync silently failed, or
    // trade is newer than the queue's last successful batch). Retry the
    // original Notion URL once — it may still be fresh enough to load.
    const notionFallback = imgEl.dataset.notionFallback || '';
    if (notionFallback && !imgEl.dataset.notionRetried) {
      imgEl.dataset.notionRetried = '1';
      imgEl.src = notionFallback;
      return;
    }
    // Reactive Supabase rescue — covers the legacy path (no pre-swap, e.g.
    // an <img> outside _lbShow's control). For lightbox-driven loads this is
    // a no-op since pre-swap already handled it.
    _tryRescueFromSupabase(imgEl, imgEl.src);
    const orig = imgEl.dataset.tvOrig || '';
    const ph = document.createElement('div');
    ph.className = 'tv-img-placeholder';
    ph.style.cssText = [
      'display:flex','flex-direction:column','align-items:center','justify-content:center',
      'gap:10px','padding:32px 40px','min-width:280px','min-height:180px',
      'background:var(--panel)','border:1px dashed var(--border)','border-radius:var(--rad-sm)',
      'color:var(--body)','font-size:var(--typo-table-body-size)','text-align:center',
      'margin-top:44px','box-shadow:0 8px 40px rgba(0,0,0,.5)',
    ].join(';');
    const icon = document.createElement('div');
    icon.textContent = '🔗';
    icon.style.cssText = 'font-size:28px;opacity:.75;line-height:1';
    ph.appendChild(icon);
    const title = document.createElement('div');
    title.textContent = 'Lien TradingView invalide';
    title.style.cssText = 'font-weight:600;color:var(--body)';
    ph.appendChild(title);
    if (orig) {
      const link = document.createElement('a');
      link.textContent = 'Ouvrir sur TradingView ↗';
      link.href   = orig;
      link.target = '_blank';
      link.rel    = 'noopener';
      link.style.cssText = 'color:var(--a);text-decoration:underline;font-size:var(--typo-panel-size)';
      link.addEventListener('click', e => e.stopPropagation());
      ph.appendChild(link);
    } else {
      const hint = document.createElement('div');
      hint.textContent = '(check the link in Notion)';
      hint.style.cssText = 'color:var(--dim);font-size:var(--typo-panel-size)';
      ph.appendChild(hint);
    }
    imgEl.style.display = 'none';
    parent.appendChild(ph);
  });
}

// ── Image lightbox overlay ──
// _lbData : [{pair, date, h4Before, m15Before, m15After, h4BeforeOrig, m15BeforeOrig, m15AfterOrig}, ...]
// _lbTradeIdx : index into _lbData for the currently shown trade
// _lbStep : 'h4Before' | 'm15Before' | 'm15After'
let _lbData = [], _lbTradeIdx = 0, _lbStep = 'm15Before';
let _lbKeyHandler = null;

const _LB_STEPS       = ['h4Before', 'm15Before', 'm15After'];
const _LB_STEP_LABELS = { h4Before: 'TV Image 1', m15Before: 'TV Image 2', m15After: 'TV Image 3' };
// Lightbox step → JOURNAL_DIMS key. Used by _getTradeMediaStepLabel to look
// up the mapped Notion column name and surface it as the modal title (e.g.
// "URL H4 Before" instead of the generic "TV Image 1") — same auto-rename
// pattern as _getJournalDimLabel for the Mapping panel.
const _LB_STEP_TO_DIM_KEY = { h4Before: 'img_h4_before', m15Before: 'img_m15', m15After: 'img_m15_after' };

function _getTradeMediaStepLabel(step) {
  // Override wins: when the user (or template auto-mapping) has set a
  // Notion / CSV column name for this screenshot dim, surface that name as
  // the modal title + tradelog button tooltip — regardless of where the
  // file is currently hosted (Notion-original OR migrated to Supabase).
  // The mapping is the canonical identifier of the screenshot slot; the
  // hosting URL is just the data. Generic "TV Image N" fallback only when
  // no override is configured at all.
  const dimKey = _LB_STEP_TO_DIM_KEY[step];
  if (dimKey) {
    const mode = localStorage.getItem(DS_KEY);
    let override = '';
    if (mode === 'api' && typeof _getEffectiveApiOverride === 'function') {
      override = _getEffectiveApiOverride(dimKey) || '';
    } else if (mode === 'csv' && typeof _csvColumnOverrides !== 'undefined') {
      override = _csvColumnOverrides?.[dimKey] || '';
    }
    if (override && !_isNoMappingValue(override) && String(override).trim()) {
      return String(override).trim();
    }
  }
  return _LB_STEP_LABELS[step] || step;
}

function _getTradeLightboxId(trade) {
  if (trade && Number.isFinite(trade._rawRowIndex)) return `row:${trade._rawRowIndex}`;
  if (!trade) return '';
  return [
    trade.date || '',
    trade.pair || '',
    trade.hour ?? '',
    trade.r ?? '',
    trade.outcome || '',
  ].join('|');
}

function _lbGetStepOrder() {
  // In API+H4 mode, M15 Before is intentionally defaulted to No Mapping, so
  // keyboard navigation should cycle only through the two visible screenshot
  // slots to match the smoother M15 behavior the user expects.
  if (_isH4ApiMode()) return ['h4Before', 'm15After'];
  return _LB_STEPS;
}

function _lbRemoveKeyHandler() {
  if (_lbKeyHandler) { document.removeEventListener('keydown', _lbKeyHandler); _lbKeyHandler = null; }
}

function _lbDrawerRight() {
  const d = document.getElementById('wd-drawer');
  if (d && !d.style.transform.includes('100%')) return 340;
  return 0;
}

function _lbShow(tradeIdx, step) {
  _lbTradeIdx = ((tradeIdx % _lbData.length) + _lbData.length) % _lbData.length;
  _lbStep = step;
  const overlay = document.getElementById('img-lightbox-overlay');
  if (!overlay) return;
  overlay.style.right = _lbDrawerRight() + 'px';

  const tr  = _lbData[_lbTradeIdx] || {};
  const url = tr[_lbStep] || '';
  const imgEl = document.getElementById('img-lightbox-img');
  // Clear any placeholder from a previous failed load on the same overlay
  // (happens when the user navigates with arrow keys across broken URLs).
  if (imgEl && imgEl.parentElement) {
    imgEl.parentElement.querySelectorAll('.tv-img-placeholder').forEach(n => n.remove());
  }
  if (imgEl) {
    imgEl.style.display = '';
    imgEl.dataset.tvOrig = tr[_lbStep + 'Orig'] || '';
    _installTvImageFallback(imgEl);
    // Pre-swap expired Notion URLs to deterministic Supabase URLs so the
    // <img> never has to wait for the Notion 403 → eliminates the "Lien
    // TradingView invalide" placeholder flash. The fallback (original Notion
    // URL) is stashed on the dataset; if Supabase 404s the onerror handler
    // retries the original URL once before giving up. notionRetried is reset
    // each call so navigation between trades gets a fresh attempt.
    const swapped = _resolveLightboxImageUrl(url, tr, _lbStep);
    delete imgEl.dataset.notionRetried;
    if (swapped && swapped !== url) {
      imgEl.dataset.notionFallback = url;
      imgEl.src = swapped;
    } else {
      delete imgEl.dataset.notionFallback;
      imgEl.src = url;
    }
  }

  // Highlight active trade card in drawer
  document.querySelectorAll('#wd-drawer .wd-trade-card').forEach(card => {
    card.style.borderColor = 'transparent';
  });
  // Reset all camera button outlines
  document.querySelectorAll('#wd-drawer [data-img-step]').forEach(btn => {
    btn.style.outline = 'none';
  });
  if (url) {
    const activeBtn = [...document.querySelectorAll('#wd-drawer [data-img-step]')].find(btn =>
      (tr.tradeId && (btn.dataset.tradeId || '') === tr.tradeId && btn.dataset.imgStep === _lbStep) ||
      (
        btn.dataset.imgStep === _lbStep &&
        btn.dataset.imgUrl === url &&
        (btn.dataset.tradePair || '') === (tr.pair || '') &&
        (btn.dataset.tradeDate || '') === (tr.date || '')
      )
    ) || document.querySelector(`#wd-drawer [data-img-url="${CSS.escape(url)}"]`);
    if (activeBtn) {
      const card = activeBtn.closest('.wd-trade-card');
      if (card) {
        card.style.borderColor = 'var(--gold)';
        // Only scroll when the card is fully outside the drawer body. The
        // built-in `scrollIntoView({ block: 'nearest' })` was nudging the
        // card to the edge on every keystroke (felt like the drawer
        // "snapped back" each time the lightbox crossed a day separator).
        const body = card.closest('.wd-drawer-body');
        if (body) {
          const cRect = body.getBoundingClientRect();
          const eRect = card.getBoundingClientRect();
          if (eRect.bottom <= cRect.top) {
            body.scrollTop += (eRect.top - cRect.top);
          } else if (eRect.top >= cRect.bottom) {
            body.scrollTop += (eRect.bottom - cRect.bottom);
          }
          // Otherwise (partially or fully visible) leave scroll position alone.
        }
      }
      activeBtn.style.outline = '2px solid var(--a)';
      activeBtn.style.borderRadius = '3px';
    }
  }

  // Selector bar: ‹ pair · date  [STEP]  n/total ›
  const sel = document.getElementById('img-lightbox-sel');
  if (sel) {
    const label     = [tr.pair, tr.date].filter(Boolean).join('  ·  ');
    const stepLabel = _getTradeMediaStepLabel(_lbStep);
    const tradeTotal = _lbData.length;
    const tradeNum   = _lbTradeIdx + 1;
    const hasMulti   = tradeTotal > 1;
    const count    = hasMulti ? `<span class="img-lightbox-count">${tradeNum} / ${tradeTotal}</span>` : '';
    const arrowBtn = (dir, delta) => `<button class="img-lightbox-nav-btn" data-action="lightbox-nav-trade" data-delta="${delta}">${dir}</button>`;
    sel.innerHTML = `
      ${hasMulti ? arrowBtn('‹', -1) : ''}
      <span class="img-lightbox-label">${label}</span>
      <span class="img-lightbox-step">${stepLabel}</span>
      ${count}
      ${hasMulti ? arrowBtn('›', 1) : ''}`;
  }
}

// Left/Right: navigate between trades one by one, keeping current step if available
function _lbNavigateTrade(delta) {
  const n = _lbData.length;
  const idx = ((_lbTradeIdx + delta) % n + n) % n;
  const tr = _lbData[idx] || {};
  if (tr[_lbStep]) {
    _lbShow(idx, _lbStep);
  } else {
    const fallback = _lbGetStepOrder().find(s => tr[s]);
    _lbShow(idx, fallback || _lbStep);
  }
}

// Up/Down: advance/rewind through H4 Before → M15 Before → M15 After at current trade
function _lbNavigateStep(delta) {
  const steps = _lbGetStepOrder();
  const stepIdx = steps.indexOf(_lbStep);
  const n = steps.length;
  for (let i = 1; i <= n; i++) {
    const newIdx  = ((stepIdx + delta * i) % n + n) % n;
    const newStep = steps[newIdx];
    if (_lbData[_lbTradeIdx] && _lbData[_lbTradeIdx][newStep]) { _lbShow(_lbTradeIdx, newStep); return; }
  }
}

function openImgLightbox(url, scopeSelector, imgStep, triggerMeta = null) {
  // Collect [data-img-step] buttons from the scope (or drawer fallback)
  const scope = scopeSelector ? document.querySelector(scopeSelector) : null;
  const btns  = scope
    ? scope.querySelectorAll('[data-img-step]')
    : document.querySelectorAll('#wd-drawer [data-img-step]');

  if (btns.length) {
    // Group by image URLs — each button carries all 3 URLs for its trade.
    // The *Orig fields (present only for TV-share sources) let the lightbox
    // fallback deep-link back to TV when the snapshot PNG fails to load.
    const seen = new Map();
    Array.from(btns).forEach(b => {
      const key = b.dataset.tradeId
        || ((b.dataset.tradePair || '') + '|' + (b.dataset.tradeDate || '') + '|' + (b.dataset.imgUrl || '') + '|' + (b.dataset.imgStep || ''));
      if (!seen.has(key)) {
        seen.set(key, {
          tradeId:       b.dataset.tradeId || key,
          pair:          b.dataset.tradePair    || '',
          date:          b.dataset.tradeDate    || '',
          h4Before:      b.dataset.tradeH4before  || '',
          m15Before:     b.dataset.tradeM15before || '',
          m15After:      b.dataset.tradeM15after  || '',
          h4BeforeOrig:  b.dataset.tradeH4beforeOrig  || '',
          m15BeforeOrig: b.dataset.tradeM15beforeOrig || '',
          m15AfterOrig:  b.dataset.tradeM15afterOrig  || '',
        });
      }
    });
    _lbData = Array.from(seen.values());
  } else {
    // Fallback: single image, treat as m15Before — no Orig (caller unknown)
    _lbData = [{ tradeId: '', pair: '', date: '', h4Before: '', m15Before: url, m15After: '',
                 h4BeforeOrig: '', m15BeforeOrig: '', m15AfterOrig: '' }];
  }

  _lbStep     = imgStep || 'm15Before';
  _lbTradeIdx = 0;
  if (triggerMeta) {
    const targetTradeId = triggerMeta.tradeId || '';
    const targetPair = triggerMeta.pair || '';
    const targetDate = triggerMeta.date || '';
    const targetUrl  = triggerMeta.url || url || '';
    const targetStep = triggerMeta.step || _lbStep;
    const exactIdx = _lbData.findIndex(t =>
      (targetTradeId && (t.tradeId || '') === targetTradeId) ||
      (
      (t.pair || '') === targetPair &&
      (t.date || '') === targetDate &&
      (t[targetStep] || '') === targetUrl
      )
    );
    if (exactIdx >= 0) _lbTradeIdx = exactIdx;
    else {
      const pairDateIdx = _lbData.findIndex(t =>
        (t.pair || '') === targetPair &&
        (t.date || '') === targetDate
      );
      if (pairDateIdx >= 0) _lbTradeIdx = pairDateIdx;
    }
  } else {
    for (let i = 0; i < _lbData.length; i++) {
      if (_lbData[i][_lbStep] === url) { _lbTradeIdx = i; break; }
    }
  }

  let overlay = document.getElementById('img-lightbox-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'img-lightbox-overlay';
    overlay.className = 'img-lightbox-overlay';
    overlay.addEventListener('click', () => { overlay.remove(); _lbRemoveKeyHandler(); });

    // Selector bar at top
    const sel = document.createElement('div');
    sel.id = 'img-lightbox-sel';
    sel.className = 'img-lightbox-sel';
    sel.addEventListener('click', e => e.stopPropagation());
    overlay.appendChild(sel);

    const img = document.createElement('img');
    img.id = 'img-lightbox-img';
    img.className = 'img-lightbox-img';
    img.addEventListener('click', e => e.stopPropagation());
    overlay.appendChild(img);

    _lbRemoveKeyHandler();
    _lbKeyHandler = function(e) {
      const ov = document.getElementById('img-lightbox-overlay');
      if (!ov) { _lbRemoveKeyHandler(); return; }
      if      (e.key === 'Escape')      { ov.remove(); _lbRemoveKeyHandler(); }
      else if (e.key === 'ArrowDown')   { e.preventDefault(); if (!e.repeat) _lbNavigateTrade(1); }
      else if (e.key === 'ArrowUp')     { e.preventDefault(); if (!e.repeat) _lbNavigateTrade(-1); }
      else if (e.key === 'ArrowRight')  { e.preventDefault(); if (!e.repeat) _lbNavigateStep(1); }
      else if (e.key === 'ArrowLeft')   { e.preventDefault(); if (!e.repeat) _lbNavigateStep(-1); }
    };
    document.addEventListener('keydown', _lbKeyHandler);
    document.body.appendChild(overlay);
  }
  _lbShow(_lbTradeIdx, _lbStep);
}

// ── Notion link mode ──
const NOTION_MODE_KEY = 'notionOpenMode';
function setNotionOpenMode(mode) {
  localStorage.setItem(NOTION_MODE_KEY, mode);
  document.querySelectorAll('input[name="notionOpenMode"]').forEach(r => { r.checked = r.value === mode; });
}
function _getNotionMode() {
  return localStorage.getItem(NOTION_MODE_KEY) || 'tab';
}
function _initNotionModeUI() {
  const mode = _getNotionMode();
  document.querySelectorAll('input[name="notionOpenMode"]').forEach(r => { r.checked = r.value === mode; });
}

// ── Notion page — open via preferred mode ──
function openNotionOverlay(url) {
  if (_getNotionMode() === 'tab') {
    window.open(url, '_blank', 'noopener,noreferrer');
  } else {
    window.location.href = url.replace(/^https?:\/\//, 'notion://');
  }
}

// ── Setup Performance: show M15 type or M15 type Detail ──
let setupDetailMode = false;
function toggleSetupDetail() {
  setupDetailMode = !setupDetailMode;
  const btn = document.getElementById('setup-detail-btn');
  if (btn) btn.classList.toggle('active', setupDetailMode);
  const filtered = getFiltered();
  const absMax = 1.8;
  renderBars('bars-setup', groupByEV(filtered, t => setupDetailMode ? (t.setupDetail || t.setup) : t.setup, k => k), absMax, false, 'setup');
}


function setBarView(v) {
  barView = v;
  try { localStorage.setItem(BAR_VIEW_KEY, v); } catch {}
  document.getElementById('bvt-global')?.classList.toggle('active', v === 'global');
  document.getElementById('bvt-split') ?.classList.toggle('active', v === 'split');
  document.getElementById('mob-bvt-global')?.classList.toggle('active', v === 'global');
  document.getElementById('mob-bvt-split') ?.classList.toggle('active', v === 'split');
  const filtered = getFiltered();
  const absMax = 1.8;
  renderBars('bars-setup',   groupByEV(filtered, t => setupDetailMode ? (t.setupDetail||t.setup) : t.setup, k => k), absMax, false, 'setup');
  renderBars('bars-session', groupByEV(filtered, t => t.session, k => SESSION_SHORT[k] || k), absMax, false, 'session');
  renderBars('bars-pair',    groupByEV(filtered, t => t.pair),   absMax, false, 'pair');
  renderDayBars(filtered);
  renderObsBars(filtered);
  renderH4ObsBars(filtered);
  renderHourBars(filtered);
}

function setBarMode(mode) {
  barMode = mode;
  try { localStorage.setItem(BAR_MODE_KEY, mode); } catch {}
  // Sync desktop buttons
  document.getElementById('bmt-ev')   ?.classList.toggle('active', mode === 'ev');
  document.getElementById('bmt-total')?.classList.toggle('active', mode === 'total');
  document.getElementById('bmt-wr')   ?.classList.toggle('active', mode === 'wr');
  // Sync mobile buttons
  document.getElementById('mob-bmt-ev')   ?.classList.toggle('active', mode === 'ev');
  document.getElementById('mob-bmt-total')?.classList.toggle('active', mode === 'total');
  // Sync "Avg R / Total R / Win Rate" label in heatmap and pair×session widget buttons
  const label = mode === 'total' ? 'Total R' : mode === 'wr' ? 'Win Rate' : 'Avg R';
  const sdEvBtn = document.querySelector('#sd-metric-btns .cc-tab[onclick*="\'ev\'"]');
  if (sdEvBtn) sdEvBtn.textContent = label;
  const psEvBtn = document.querySelector('#ps-metric-btns .cc-tab[onclick*="\'ev\'"]');
  if (psEvBtn) psEvBtn.textContent = label;
  // Rerender all bar charts + heatmaps
  const filtered = getFiltered();
  const absMax = 1.8;
  renderBars('bars-setup',   groupByEV(filtered, t => setupDetailMode ? (t.setupDetail||t.setup) : t.setup, k => k), absMax, false, 'setup');
  renderBars('bars-session', groupByEV(filtered, t => t.session, k => SESSION_SHORT[k] || k), absMax, false, 'session');
  renderBars('bars-pair',    groupByEV(filtered, t => t.pair),   absMax, false, 'pair');
  renderDayBars(filtered);
  renderObsBars(filtered);
  renderH4ObsBars(filtered);
  _syncHardModeBtn();
  renderHeatmap(filtered);
  renderHourBars(filtered);
  renderPairSession(filtered);
  renderAllCustomWidgets(filtered);
  // Rerender mobile charts
  if (_isMobile()) {
    drawMobileMonthly2(filtered);
    drawMobilePair(filtered);
    drawMobileSetup(filtered);
    drawMobileObs(filtered);
    renderMobileHeatmap(filtered);
  }
}

function _mixHex(a, b) {
  const pa = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(a);
  const pb = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(b);
  if (!pa || !pb) return a;
  return `rgb(${Math.round((parseInt(pa[1],16)+parseInt(pb[1],16))/2)},${Math.round((parseInt(pa[2],16)+parseInt(pb[2],16))/2)},${Math.round((parseInt(pa[3],16)+parseInt(pb[3],16))/2)})`;
}

function groupByEV(trades, keyFn, labelFn) {
  const tpConfig = appState.ui.tpConfig;
  const groups = {};
  trades.forEach(t => {
    const k = keyFn(t);
    if (!k) return;
    if (!groups[k]) groups[k] = { rs: [], rawKey: k, _oc: { TP: [], 'BE-TP': [], 'BE-SL': [], SL: [] } };
    const r = computeEffectiveRR(t, tpConfig);
    groups[k].rs.push(r);
    const arr = groups[k]._oc[t.outcome];
    if (arr) arr.push(r);
  });
  return Object.entries(groups)
    .map(([k, { rs, rawKey, _oc }]) => {
      const sum = a => a.reduce((s, r) => s + r, 0);
      return {
        label:   labelFn ? labelFn(k) : k,
        _rawKey: rawKey,
        n:       rs.length,
        ev:      sum(rs) / rs.length,
        totalR:  sum(rs),
        oc: {
          tp:   { r: sum(_oc.TP),         n: _oc.TP.length },
          betp: { r: sum(_oc['BE-TP']),   n: _oc['BE-TP'].length },
          besl: { r: sum(_oc['BE-SL']),   n: _oc['BE-SL'].length },
          sl:   { r: sum(_oc.SL),         n: _oc.SL.length },
        },
      };
    })
    .filter(d => d.n >= 1);
}

// ── Sample-size opacity ramp for bar charts ──
// Applied on the whole bar row (label + track + value) so low-n bars are
// visually de-emphasized. Drives the "don't trust this bar" signal.
function barOpacityForN(n) {
  // Share view ignores ghost mode entirely — share images should display the
  // raw stats without low-n attenuation, regardless of the global setting.
  if (currentView === 'share') return 1;
  if (!appState.ui.ghostMode) return 1;
  if (n >= 20) return 1;
  if (n >= 10) return 0.75;
  if (n >= 5)  return 0.55;
  return 0.35;
}

// Warning threshold helper: returns true when n is below the configured threshold
function _isLowVolume(n) {
  // Share view ignores the threshold for the same reason as ghost mode.
  if (currentView === 'share') return false;
  return appState.ui.warningThreshold > 0 && n < appState.ui.warningThreshold;
}

// ══════════════════════════════════════════════════════
// CUSTOM WIDGET RENDERERS
// ══════════════════════════════════════════════════════

// Read a field value from a trade: top-level first, then .extras
function _cwGetFieldValue(t, fieldKey, def = null, sourceOverride = '') {
  if (t[fieldKey] !== undefined && t[fieldKey] !== null) return t[fieldKey];
  if (t.extras && t.extras[fieldKey] !== undefined) return t.extras[fieldKey];
  const mode = localStorage.getItem(DS_KEY) || 'demo';
  const source = sourceOverride || def?.propertySource || '';
  if (source && source === mode && (mode === 'csv' || mode === 'api')) {
    const raw = _getRawForTrade(t, mode);
    if (raw && Object.prototype.hasOwnProperty.call(raw, fieldKey)) return raw[fieldKey];
  }
  return null;
}

function _cwExpandFieldValues(raw, inferredType = '') {
  if (raw === null || raw === undefined) return [];
  if (Array.isArray(raw)) {
    return raw
      .map(v => String(v ?? '').trim())
      .filter(Boolean);
  }
  const str = typeof raw === 'object' ? _flattenApiWidgetValue(raw) : String(raw).trim();
  if (!str) return [];
  if (inferredType === 'multi-select' && (str.includes(', ') || str.includes('|'))) {
    return str.split(/, |\|/).map(v => v.trim()).filter(Boolean);
  }
  return [str];
}

function renderCustomBars(def, trades) {
  const containerId = `bars-${def.id}`;
  if (!trades.length) { renderWidgetEmptyState(containerId); return; }
  const tpConfig = appState.ui.tpConfig;
  const groups = {};
  trades.forEach(t => {
    const vals = _cwExpandFieldValues(_cwGetFieldValue(t, def.field, def, def.fieldSource || def.propertySource), def.inferredType);
    if (!vals.length) return;
    const r = computeEffectiveRR(t, tpConfig);
    vals.forEach(val => {
      if (!groups[val]) groups[val] = { rs: [], rawKey: val, _oc: { TP: [], 'BE-TP': [], 'BE-SL': [], SL: [] } };
      groups[val].rs.push(r);
      const arr = groups[val]._oc[t.outcome];
      if (arr) arr.push(r);
    });
  });
  const data = Object.entries(groups).map(([k, { rs, rawKey, _oc }]) => {
    const sum = a => a.reduce((s, r) => s + r, 0);
    return {
      label: k,
      _rawKey: rawKey,
      n: rs.length,
      ev: sum(rs) / rs.length,
      totalR: sum(rs),
      oc: {
        tp:   { r: sum(_oc.TP),         n: _oc.TP.length },
        betp: { r: sum(_oc['BE-TP']),   n: _oc['BE-TP'].length },
        besl: { r: sum(_oc['BE-SL']),   n: _oc['BE-SL'].length },
        sl:   { r: sum(_oc.SL),         n: _oc.SL.length },
      },
    };
  }).filter(d => d.n >= 1);
  if (!data.length) { renderWidgetEmptyState(containerId); return; }
  renderBars(containerId, data, 1.8, false, def.id);
}

function renderCustomHeatmap(def, trades) {
  const containerId = `heatmap-${def.id}`;
  const container = document.getElementById(containerId);
  if (!container) return;
  const runtime = _getCustomHeatmapRuntimeState(def);
  const metric = barMode === 'wr' ? 'wr' : barMode === 'n' ? 'n' : runtime.metricMode;
  _renderSharedHeatmapGrid({
    container,
    containerId,
    trades,
    rowKey: def.field,
    colKey: def.field2,
    metric,
    threshold: runtime.threshold,
    hardMode: runtime.hardMode,
    getRowValues: t => _cwExpandFieldValues(
      _cwGetFieldValue(t, def.field, def, def.fieldSource || def.propertySource),
      def.inferredType
    ),
    getColValues: t => _cwExpandFieldValues(
      _cwGetFieldValue(t, def.field2, def, def.field2Source || def.propertySource),
      ''
    ),
    getRowLabel: v => _formatHeatmapAxisLabel(v, def.field, true),
    getColLabel: v => _formatHeatmapAxisLabel(v, def.field2, true),
    getCellTitle: (rowVal, colVal) => `${_formatHeatmapAxisLabel(rowVal, def.field, true)} × ${_formatHeatmapAxisLabel(colVal, def.field2, true)}`,
    getCellTrades: (rowVal, colVal) => trades.filter(t => {
      const rowVals = _cwExpandFieldValues(
        _cwGetFieldValue(t, def.field, def, def.fieldSource || def.propertySource),
        def.inferredType
      );
      const colVals = _cwExpandFieldValues(
        _cwGetFieldValue(t, def.field2, def, def.field2Source || def.propertySource),
        ''
      );
      return rowVals.includes(rowVal) && colVals.includes(colVal);
    }),
    rowLabelWidth: 72,
  });
}

function renderAllCustomWidgets(trades) {
  const defs = _loadCustomWidgetDefs();
  for (const def of defs) {
    if (def.type === 'bars')         renderCustomBars(def, trades);
    else if (def.type === 'heatmap') renderCustomHeatmap(def, trades);
    else if (def.type === 'table')   renderCustomTable(def, trades);
  }
}

// ── Threshold color helpers for the custom Table widget ────────────────
// Mirror the dashboard's canonical KPI thresholds so Total R / WR / Avg R /
// PF cells in the per-category breakdown carry the same red→orange→yellow→
// green→blue→purple semantics the user already learned from the Statistics
// Overview KPIs. Sources of truth: _wrColor, _evColor, _pfColor inline
// helpers (~ dashboard.js:11677) + _svProgressTone / _getWinRateTone.
const _CW_TABLE_PALETTE = {
  red:    'var(--r)',
  orange: '#f39a3d',
  yellow: 'var(--a)',
  green:  'var(--g)',
  blue:   'var(--b)',
  purple: '#9b6dff',
};
function _cwTableWrColor(wr) {
  if (!Number.isFinite(wr)) return '';
  if (wr > 55)  return _CW_TABLE_PALETTE.purple;
  if (wr >= 48) return _CW_TABLE_PALETTE.blue;
  if (wr >= 40) return _CW_TABLE_PALETTE.green;
  if (wr >= 35) return _CW_TABLE_PALETTE.yellow;
  if (wr >= 30) return _CW_TABLE_PALETTE.orange;
  return _CW_TABLE_PALETTE.red;
}
function _cwTableAvgColor(avg) {
  if (!Number.isFinite(avg)) return '';
  if (avg >= 1)   return _CW_TABLE_PALETTE.purple;
  if (avg >= 0.6) return _CW_TABLE_PALETTE.blue;
  if (avg >= 0.3) return _CW_TABLE_PALETTE.green;
  if (avg >= 0.1) return _CW_TABLE_PALETTE.yellow;
  if (avg >= 0)   return _CW_TABLE_PALETTE.orange;
  return _CW_TABLE_PALETTE.red;
}
function _cwTablePfColor(pf) {
  if (!Number.isFinite(pf)) return _CW_TABLE_PALETTE.purple; // ∞ → top tier
  if (pf >= 3)   return _CW_TABLE_PALETTE.purple;
  if (pf >= 2.2) return _CW_TABLE_PALETTE.blue;
  if (pf >= 1.7) return _CW_TABLE_PALETTE.green;
  if (pf >= 1.3) return _CW_TABLE_PALETTE.yellow;
  if (pf >= 1)   return _CW_TABLE_PALETTE.orange;
  return _CW_TABLE_PALETTE.red;
}
function _cwTableTotalColor(v) {
  // Total R uses sign-only coloring (green/red) — its magnitude varies wildly
  // across categories so a single threshold scale isn't meaningful. The KPI
  // tooltip breakdown uses the same simple sign convention (see line 17653).
  return v > 0 ? 'var(--g)' : v < 0 ? 'var(--r)' : '';
}

// Toolbar above the table:
//   ⛓ link button → sync ALL custom table widgets (sort + bars mode).
//                    Same UX as the heatmap sync chain icon.
//   Bars toggle   → enable/disable the horizontal data-bar overlay on the
//                    Total R column. Off renders a clean tabular grid.
// When sync is on, both controls read/write the shared master state so
// every table updates in lockstep. When sync is off, settings live per-widget.
function _renderCustomTableToolbarHTML(def) {
  const synced = _customTableSyncEnabled === true;
  const barsMode = synced
    ? _customTableMasterSettings.barsMode === true
    : def?.settings?.barsMode !== false;
  const cwAttr = ` data-cw-id="${_escapeAttr(def.id)}"`;
  return `
    <div class="cc-head-controls cc-head-controls-sm">
      <button class="bar-sort-btn cw-table-sync-btn${synced ? ' active' : ''}"
              type="button"
              data-action="toggle-custom-table-sync"${cwAttr}
              title="Sync all table widgets — share sort + bar mode">⛓</button>
      <button class="cc-tab cw-table-bars-btn${barsMode ? ' active' : ''}"
              type="button"
              data-action="set-table-bars-mode"${cwAttr}
              title="Toggle the data-bar overlay on Total R">Bars</button>
    </div>`;
}

// ── Custom Table sync state (mirrors the heatmap sync pattern) ────────────
// When _customTableSyncEnabled is true, all custom table widgets read sort
// + bars mode from _customTableMasterSettings instead of their own
// def.settings. Clicks on sort headers / bars toggle update the master,
// then all tables re-render in lockstep. Turning sync off commits the
// current master state to every widget's def.settings.
let _customTableSyncEnabled = false;
let _customTableMasterSettings = { sortKey: 'total', sortDir: 'desc', barsMode: true, labelMinWidth: null };

// Resolve the effective sort + bars + label-min-width settings for a table
// widget, accounting for sync mode. Returns { sortKey, sortDir, barsMode,
// labelMinWidth }.
function _getCustomTableEffectiveSettings(def) {
  if (_customTableSyncEnabled) {
    return {
      sortKey: _customTableMasterSettings.sortKey,
      sortDir: _customTableMasterSettings.sortDir,
      barsMode: _customTableMasterSettings.barsMode === true,
      labelMinWidth: _customTableMasterSettings.labelMinWidth ?? null,
    };
  }
  const s = def?.settings || {};
  return {
    sortKey: s.sortKey || 'total',
    sortDir: s.sortDir === 'asc' ? 'asc' : 'desc',
    barsMode: s.barsMode !== false,
    labelMinWidth: Number.isFinite(Number(s.labelMinWidth)) ? Number(s.labelMinWidth) : null,
  };
}

// Re-render every custom Table widget that's currently mounted. Used after
// any sync-mode change so all tables visually update together.
function _rerenderAllCustomTables() {
  const filtered = (typeof getFiltered === 'function') ? getFiltered() : [];
  const defs = (typeof _loadCustomWidgetDefs === 'function') ? _loadCustomWidgetDefs() : [];
  for (const def of defs) {
    if (def?.type === 'table') {
      try { renderCustomTable(def, filtered); } catch (e) {}
    }
  }
  // Refresh every table's toolbar active state (sync button + bars button).
  document.querySelectorAll('.gs-widget[data-cw-id] .cw-table-sync-btn').forEach(btn => {
    btn.classList.toggle('active', _customTableSyncEnabled === true);
  });
  const effectiveBarsMode = _customTableSyncEnabled
    ? _customTableMasterSettings.barsMode === true
    : null;
  document.querySelectorAll('.gs-widget[data-cw-id] .cw-table-bars-btn').forEach(btn => {
    const root = btn.closest('.gs-widget[data-cw-id]');
    const cwId = root?.dataset?.cwId;
    const def = defs.find(d => d.id === cwId);
    const isOn = effectiveBarsMode !== null
      ? effectiveBarsMode
      : def?.settings?.barsMode !== false;
    btn.classList.toggle('active', isOn === true);
  });
}

// Toggle sync on/off. Turning ON seeds the master state from the clicked
// widget's current settings (so the user's last view becomes the new
// shared truth). Turning OFF commits the master state to every widget's
// def.settings so each widget keeps the synced layout after the chain breaks.
function toggleCustomTableSync(cwId) {
  if (!_customTableSyncEnabled) {
    const defs = _loadCustomWidgetDefs();
    const seed = defs.find(d => d.id === cwId && d.type === 'table')?.settings
      || _customTableMasterSettings;
    _customTableMasterSettings = {
      sortKey: seed.sortKey || 'total',
      sortDir: seed.sortDir === 'asc' ? 'asc' : 'desc',
      barsMode: seed.barsMode !== false,
      labelMinWidth: Number.isFinite(Number(seed.labelMinWidth)) ? Number(seed.labelMinWidth) : null,
    };
    _customTableSyncEnabled = true;
  } else {
    // Commit master state to every table def before breaking the chain.
    const defs = _loadCustomWidgetDefs();
    const masterLabelMin = _customTableMasterSettings.labelMinWidth ?? null;
    let changed = false;
    for (const def of defs) {
      if (def?.type !== 'table') continue;
      const prev = def.settings || {};
      const prevLabelMin = Number.isFinite(Number(prev.labelMinWidth)) ? Number(prev.labelMinWidth) : null;
      if (prev.sortKey === _customTableMasterSettings.sortKey
          && prev.sortDir === _customTableMasterSettings.sortDir
          && (prev.barsMode !== false) === (_customTableMasterSettings.barsMode === true)
          && prevLabelMin === masterLabelMin) continue;
      def.settings = {
        ...prev,
        sortKey: _customTableMasterSettings.sortKey,
        sortDir: _customTableMasterSettings.sortDir,
        barsMode: _customTableMasterSettings.barsMode === true,
        labelMinWidth: masterLabelMin,
      };
      changed = true;
    }
    if (changed) _saveCustomWidgetDefs(defs);
    _customTableSyncEnabled = false;
  }
  _rerenderAllCustomTables();
}

// Renders a custom Table widget: one row per category (field value) with
// the canonical trading metrics — Total R / WR / Avg R / PF / # Trades.
// WR/Avg R/PF cells carry threshold colors matching the KPI tier scheme.
// Sort header click toggles asc/desc. Click a row to open the trade drawer
// filtered to that category's trades. The Total R column gets an Excel-style
// horizontal data-bar gradient when `barsMode` is on — toggle via the
// header button. Settings sync globally when the chain icon is active.
function renderCustomTable(def, trades) {
  const root = document.querySelector(`.gs-widget[data-cw-id="${CSS.escape(def.id)}"]`);
  const host = root?.querySelector('.cw-table-host');
  if (!root || !host) return;

  const tpConfig = appState?.ui?.tpConfig;

  // Single-pass per-category bucket: count, sumR, winners, gross win/loss
  // (for profit factor), and the matching trades array for drill-down.
  const buckets = new Map();
  for (const t of (trades || [])) {
    const vals = _cwExpandFieldValues(
      _cwGetFieldValue(t, def.field, def, def.fieldSource || def.propertySource),
      def.inferredType
    );
    if (!vals.length) continue;
    const effR = (typeof computeEffectiveRR === 'function')
      ? computeEffectiveRR(t, tpConfig)
      : (Number(t.r) || 0);
    const isWin = (typeof isWinner === 'function') ? isWinner(t, tpConfig) : (effR > 0);
    for (const v of vals) {
      const key = String(v);
      let b = buckets.get(key);
      if (!b) {
        b = { count: 0, sumR: 0, winners: 0, sumWins: 0, sumLosses: 0 };
        buckets.set(key, b);
      }
      b.count++;
      b.sumR += effR;
      if (effR > 0) b.sumWins += effR;
      else if (effR < 0) b.sumLosses += Math.abs(effR);
      if (isWin) b.winners++;
    }
  }

  // Derive metrics. PF=Infinity when wins>0 and losses=0 (perfect win-only
  // category — rendered as a larger "∞" glyph so the no-loss case stands out
  // vs. a real high PF like "3.42").
  const rows = [];
  for (const [label, b] of buckets.entries()) {
    const avgR = b.count > 0 ? b.sumR / b.count : 0;
    const wr = b.count > 0 ? (b.winners / b.count) * 100 : 0;
    const pf = b.sumLosses > 0
      ? b.sumWins / b.sumLosses
      : (b.sumWins > 0 ? Infinity : 0);
    rows.push({ label, count: b.count, sumR: b.sumR, avgR, wr, pf });
  }

  // Effective settings — pulled from the sync master if the chain is active,
  // else from this widget's own def.settings.
  const eff = _getCustomTableEffectiveSettings(def);
  const { sortKey, sortDir, barsMode, labelMinWidth } = eff;

  const cmpFn = {
    label: (a, b) => String(a.label).localeCompare(String(b.label)),
    count: (a, b) => a.count - b.count,
    wr:    (a, b) => a.wr - b.wr,
    avg:   (a, b) => a.avgR - b.avgR,
    pf:    (a, b) => {
      const av = isFinite(a.pf) ? a.pf : Number.MAX_VALUE;
      const bv = isFinite(b.pf) ? b.pf : Number.MAX_VALUE;
      return av - bv;
    },
    total: (a, b) => a.sumR - b.sumR,
  }[sortKey] || ((a, b) => a.sumR - b.sumR);
  rows.sort(cmpFn);
  if (sortDir === 'desc') rows.reverse();

  if (!rows.length) {
    host.innerHTML = '<div class="cw-table-empty">No data for this property under the current filters.</div>';
    return;
  }

  const cwIdAttr = _escapeAttr(def.id);
  const fmtR = v => (v >= 0 ? '+' : '') + v.toFixed(2) + 'R';
  const fmtPct = v => v.toFixed(0) + '%';
  // PF formatter renders ∞ inside a larger-font span so the perfect-PF
  // case (winners only, zero losses) jumps out visually vs. a finite PF.
  const fmtPF = v => !isFinite(v)
    ? '<span class="cw-pf-inf">∞</span>'
    : v.toFixed(2);

  const arrow = k => sortKey !== k ? '' : (sortDir === 'desc' ? ' ▼' : ' ▲');
  const headerLabel = _escapeHtml(def.fieldLabel || def.label || def.field);
  // The label header carries the drag handle. Other headers stay verbatim
  // so the rest of the table behaviour is identical to the pre-feature
  // state.
  const headerCell = (key, text, alignClass = 'cw-th-num') => `
    <th class="cw-th ${alignClass}${sortKey === key ? ' is-active' : ''}"
        data-action="set-table-sort" data-cw-id="${cwIdAttr}" data-sort-key="${key}"
        title="Sort by ${text.replace(/['"<>&]/g, '')}">${text}${arrow(key)}</th>`;
  const labelHeaderCell = `
    <th class="cw-th cw-th-label${sortKey === 'label' ? ' is-active' : ''}"
        data-action="set-table-sort" data-cw-id="${cwIdAttr}" data-sort-key="label"
        title="Sort by ${String(headerLabel).replace(/['"<>&]/g, '')}">${headerLabel}${arrow('label')}<span class="cw-col-resize-handle" data-cw-id="${cwIdAttr}" title="Drag to widen the property column · double-click to reset"></span></th>`;

  // Bar magnitude relative to max |sumR|. Guard against all-zero rows (e.g.
  // BE-only categories) by clamping the denominator.
  const maxAbs = barsMode ? Math.max(...rows.map(r => Math.abs(r.sumR)), 0.0001) : 0;

  // CSS variable expressing the user-set minimum width for the label column.
  // Read by the .cw-th-label / .cw-td-label rules added in dashboard.css.
  // No variable → fallback to 0 → no effect, identical to legacy behaviour.
  const tableStyle = (labelMinWidth != null && labelMinWidth > 0)
    ? ` style="--cw-label-min:${labelMinWidth}px"`
    : '';

  host.innerHTML = `
    <div class="cw-table-scroll">
      <table class="cw-table${barsMode ? ' cw-table-bars' : ''}"${tableStyle}>
        <thead>
          <tr>
            ${labelHeaderCell}
            ${headerCell('total', 'Total R', barsMode ? 'cw-th-bar' : 'cw-th-num')}
            ${headerCell('wr',    'WR')}
            ${headerCell('avg',   'Avg R')}
            ${headerCell('pf',    'PF')}
            ${headerCell('count', 'Vol')}
          </tr>
        </thead>
        <tbody>
          ${rows.map(r => {
            let totalCellStyle = `color:${_cwTableTotalColor(r.sumR)}`;
            let totalCellClass = 'cw-td cw-td-num';
            if (barsMode) {
              const barPct = (Math.abs(r.sumR) / maxAbs) * 100;
              const barColor = r.sumR >= 0 ? 'var(--g)' : 'var(--r)';
              const barBg = `linear-gradient(to right, color-mix(in srgb, ${barColor} 22%, transparent) 0 ${barPct.toFixed(2)}%, transparent ${barPct.toFixed(2)}% 100%)`;
              totalCellStyle = `background:${barBg};color:${_cwTableTotalColor(r.sumR)}`;
              totalCellClass = 'cw-td cw-td-num cw-td-bar';
            }
            return `
            <tr class="cw-table-row"
                data-action="open-custom-row-drawer"
                data-cw-id="${cwIdAttr}"
                data-row-label="${_escapeAttr(r.label)}"
                title="Click to drill into ${r.count} trade${r.count > 1 ? 's' : ''}">
              <td class="cw-td cw-td-label">${_escapeHtml(r.label)}</td>
              <td class="${totalCellClass}" style="${totalCellStyle}">${fmtR(r.sumR)}</td>
              <td class="cw-td cw-td-num" style="color:${_cwTableWrColor(r.wr)}">${fmtPct(r.wr)}</td>
              <td class="cw-td cw-td-num" style="color:${_cwTableAvgColor(r.avgR)}">${fmtR(r.avgR)}</td>
              <td class="cw-td cw-td-num" style="color:${_cwTablePfColor(r.pf)}">${fmtPF(r.pf)}</td>
              <td class="cw-td cw-td-num cw-td-count">${r.count}</td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>
    </div>`;
}

// ── Property-column resize for custom Table widgets ────────────────────────
// Adds a user-controllable minimum width to the label column only — every
// other column keeps its existing auto behaviour. State lives in module
// scope for the duration of one drag (mousedown → mousemove → mouseup) and
// is persisted to def.settings.labelMinWidth (or _customTableMasterSettings
// when sync is ON). Double-click resets to "no minimum" (the original auto
// flex behaviour where the label absorbs leftover space).
let _cwLabelResizeState = null;

function _cwOnLabelResizeMove(e) {
  const st = _cwLabelResizeState;
  if (!st) return;
  const dx = e.clientX - st.startX;
  const next = Math.max(60, Math.min(1600, st.startWidth + dx));
  st.currentWidth = next;
  // Live preview: write the CSS variable on the matching table(s) so the
  // label cells reflect the drag in real time. In sync mode, every table
  // is updated; otherwise only the table being dragged.
  const tables = _customTableSyncEnabled
    ? document.querySelectorAll('.gs-widget[data-cw-id] table.cw-table')
    : document.querySelectorAll(`.gs-widget[data-cw-id="${CSS.escape(st.cwId)}"] table.cw-table`);
  tables.forEach(t => t.style.setProperty('--cw-label-min', next + 'px'));
}

function _cwOnLabelResizeEnd() {
  const st = _cwLabelResizeState;
  if (!st) return;
  document.body.classList.remove('cw-col-resizing');
  st.handleEl?.classList.remove('is-dragging');
  document.removeEventListener('mousemove', _cwOnLabelResizeMove);
  document.removeEventListener('mouseup', _cwOnLabelResizeEnd);
  if (st.currentWidth !== st.startWidth) {
    const finalPx = Math.round(st.currentWidth);
    if (_customTableSyncEnabled) {
      _customTableMasterSettings.labelMinWidth = finalPx;
    } else {
      _updateCustomWidgetDef(st.cwId, (cur) => ({
        ...cur,
        settings: { ...(cur.settings || {}), labelMinWidth: finalPx },
      }));
    }
    // Re-render so a hard refresh picks up the new persisted state. We
    // intentionally don't await — render is cheap.
    _rerenderAllCustomTables();
  }
  _cwLabelResizeState = null;
}

function _cwStartLabelResize(handleEl, e) {
  if (!handleEl) return;
  const cwId = handleEl.getAttribute('data-cw-id');
  if (!cwId) return;
  const th = handleEl.closest('.cw-th');
  if (!th) return;
  e.preventDefault();
  e.stopPropagation();
  const rect = th.getBoundingClientRect();
  _cwLabelResizeState = {
    cwId,
    handleEl,
    startX: e.clientX,
    startWidth: rect.width,
    currentWidth: rect.width,
  };
  handleEl.classList.add('is-dragging');
  document.body.classList.add('cw-col-resizing');
  document.addEventListener('mousemove', _cwOnLabelResizeMove);
  document.addEventListener('mouseup', _cwOnLabelResizeEnd);
}

function _cwResetLabelWidth(handleEl) {
  if (!handleEl) return;
  const cwId = handleEl.getAttribute('data-cw-id');
  if (!cwId) return;
  if (_customTableSyncEnabled) {
    _customTableMasterSettings.labelMinWidth = null;
  } else {
    _updateCustomWidgetDef(cwId, (cur) => ({
      ...cur,
      settings: { ...(cur.settings || {}), labelMinWidth: null },
    }));
  }
  _rerenderAllCustomTables();
}

document.addEventListener('mousedown', (e) => {
  const handle = e.target?.closest?.('.cw-col-resize-handle');
  if (!handle) return;
  _cwStartLabelResize(handle, e);
});
// The handle sits inside a <th> that has its own click→sort handler.
// Without these capture-phase guards every drag (and any benign click on
// the handle) would also flip the sort.
document.addEventListener('click', (e) => {
  const handle = e.target?.closest?.('.cw-col-resize-handle');
  if (!handle) return;
  e.preventDefault();
  e.stopPropagation();
}, true);
document.addEventListener('dblclick', (e) => {
  const handle = e.target?.closest?.('.cw-col-resize-handle');
  if (!handle) return;
  e.preventDefault();
  e.stopPropagation();
  _cwResetLabelWidth(handle);
}, true);

function renderBarsSplit(containerId, items, small, chart) {
  const container = document.getElementById(containerId);
  if (!container) return;
  if (!items || !items.length) { container.innerHTML = '<div class="no-data">No data</div>'; return; }

  const cG = tc('--g'), cR = tc('--r'), cA = tc('--gold') || tc('--a');
  const cBETP = tc('--oc-betp');
  const cBESL = tc('--oc-besl');

  const useTotal = barMode === 'total';
  const useWR    = barMode === 'wr';
  const useN     = barMode === 'n';
  const _wrFn    = d => d.n > 0 ? (d.oc.tp.n / d.n) * 100 : 0;
  const sorted = chart
    ? sortItems(items, chart, useTotal ? d => d.totalR : useWR ? _wrFn : useN ? d => d.n : null)
    : [...items].sort((a, b) => useTotal ? b.totalR - a.totalR : useWR ? _wrFn(b) - _wrFn(a) : useN ? b.n - a.n : b.ev - a.ev);

  const allSideVals = sorted.flatMap(d => {
    const oc = d.oc || {};
    return [
      Math.abs((oc.tp?.r || 0) + (oc.betp?.r || 0)),
      Math.abs((oc.sl?.r || 0) + (oc.besl?.r || 0)),
    ];
  });
  const absMax = Math.max(...allSideVals) || 1;

  const isObs = containerId.includes('obs');
  const cls = (small ? 'bar-row sm' : 'bar-row') + ' split' + (isObs ? ' obs' : '');
  const decimals = useTotal ? 1 : 2;

  container.innerHTML = sorted.map(d => {
    const oc = d.oc || { tp:{r:0,n:0}, betp:{r:0,n:0}, besl:{r:0,n:0}, sl:{r:0,n:0} };
    const winR = oc.tp.r + oc.betp.r;
    const losR = oc.sl.r + oc.besl.r;
    const winPct = Math.min(Math.abs(winR) / absMax * 100, 100);
    const losPct = Math.min(Math.abs(losR) / absMax * 100, 100);

    const winAbs = Math.abs(winR) || 1;
    const losAbs = Math.abs(losR) || 1;
    const tpPct   = Math.abs(oc.tp.r)   / winAbs * 100;
    const betpPct = Math.abs(oc.betp.r) / winAbs * 100;
    const slPct   = Math.abs(oc.sl.r)   / losAbs * 100;
    const beslPct = Math.abs(oc.besl.r) / losAbs * 100;

    const losN = oc.sl.n + oc.besl.n;
    const winN = oc.tp.n + oc.betp.n;
    // In Avg R mode: side cells show only counts; net cell shows ev (same as consolidated)
    // In Total R mode: side cells show total R per side; net cell shows net total R
    const losValStr = useTotal ? (losR < 0 ? losR.toFixed(decimals) + 'R' : '—') : '';
    const winValStr = useTotal ? (winR > 0 ? '+' + winR.toFixed(decimals) + 'R' : '—') : '';
    const netR  = d.totalR;
    const wrPct = _wrFn(d);
    const netVal = useWR ? wrPct : useN ? d.n : useTotal ? netR : d.ev;
    const netStr = useWR ? wrPct.toFixed(0) + '%'
                 : useN  ? String(d.n)
                 : (netVal >= 0 ? '+' : '') + netVal.toFixed(useTotal ? decimals : 3) + 'R';
    const netCol = useWR
                   ? (barColorMode === 'binary'
                       ? (wrPct >= 40 ? cG : cR)
                       : _kpiTooltipColor(wrPct, 'wr'))
                 : useN  ? (d.totalR > 0 ? cG : d.totalR < 0 ? cR : cA)
                 : useTotal
                     ? (barColorMode === 'binary'
                         ? (netVal > 0 ? cG : netVal < 0 ? cR : tc('--body'))
                         : _kpiTooltipColor(d.ev, 'avgr'))
                     : _kpiTooltipColor(d.ev, 'avgr');

    const losBar = losPct > 0.1 ? `<div class="split-bar" style="width:${losPct}%">
        <div class="split-seg" style="width:${beslPct}%;background:${cBESL}"></div>
        <div class="split-seg" style="width:${slPct}%;background:${cR}"></div>
      </div>` : '';
    const winBar = winPct > 0.1 ? `<div class="split-bar" style="width:${winPct}%">
        <div class="split-seg" style="width:${tpPct}%;background:${cG}"></div>
        <div class="split-seg" style="width:${betpPct}%;background:${cBETP}"></div>
      </div>` : '';

    const _ocStr = `${oc.tp.n},${oc.tp.r.toFixed(2)},${oc.sl.n},${oc.sl.r.toFixed(2)},${oc.betp.n},${oc.betp.r.toFixed(2)},${oc.besl.n},${oc.besl.r.toFixed(2)}`;
    const op = barOpacityForN(d.n);
    const totalNCls = _isLowVolume(d.n) ? 'split-n bar-n-low' : 'split-n';
    const totalNStr = _isLowVolume(d.n) ? `×${d.n} ⚠` : `×${d.n}`;
    return `<div class="${cls}" style="opacity:${op}" data-bar-label="${d.label.replace(/"/g,'&quot;')}" data-bar-rawkey="${(d._rawKey||d.label).replace(/"/g,'&quot;')}" data-bar-n="${d.n}" data-bar-oc="${_ocStr}" data-bar-totalr="${d.totalR.toFixed(2)}">
      <div class="bar-label" title="${d.label}">${d.label}</div>
      <div class="split-track">
        <div class="split-left">${losBar}</div>
        <div class="split-divider"></div>
        <div class="split-right">${winBar}</div>
      </div>
      <div class="split-vals">
        <div class="split-val-cell">
          ${losValStr ? `<span style="color:${cR}">${losValStr}</span>` : ''}
          <span class="split-n">${losN > 0 ? '×' + losN : ''}</span>
        </div>
        <div class="split-val-cell">
          ${winValStr ? `<span style="color:${cG}">${winValStr}</span>` : ''}
          <span class="split-n">${winN > 0 ? '×' + winN : ''}</span>
        </div>
        <div class="split-val-cell split-val-net">
          <span style="color:${netCol}">${netStr}</span>
          <span class="${totalNCls}">${totalNStr}</span>
        </div>
      </div>
    </div>`;
  }).join('');
}

// Suppress internal scroll in a .bar-list. Leaves typography under the
// Theme Editor sliders' control (--typo-bar-{id}-{label,val}-size are set
// at :root so all 7 performance widgets stay uniform). Row height adapts
// naturally to whatever fontLabel / fontVal the slider sets, plus the CSS
// `line-height:1` on .bar-net / .bar-n keeps the trade-count visible without
// clipping. If the slider is set so large that 24 rows can't fit a tiny
// widget, items at the bottom are clipped (clean) rather than scrolled.
function _fitBarList(containerId, nItems) {
  const container = document.getElementById(containerId);
  if (!container || !nItems) return;
  const widget = container.closest('[data-gs-id]');
  if (!widget) return;
  // Clear any previous per-widget typo override (legacy from the auto-font
  // calculation) so the slider-controlled :root vars take effect again.
  const gsId = widget.getAttribute('data-gs-id');
  const idMap = { 'w-setup':'setup','w-pair':'pair','w-session':'session','w-day':'day','w-m15':'m15','w-h4':'h4','w-hour':'hour' };
  const suffix = idMap[gsId];
  if (suffix) {
    widget.style.removeProperty(`--typo-bar-${suffix}-label-size`);
    widget.style.removeProperty(`--typo-bar-${suffix}-val-size`);
  }
  // Drop the row/track sizing vars — rows now size to their natural content.
  container.style.removeProperty('--bar-row-h');
  container.style.removeProperty('--bar-track-h');
  // Override .bar-list's default overflow-y:auto.
  container.style.overflow = 'hidden';
}

function renderBars(containerId, data, maxAbsR, small, chart) {
  if (barView === 'split') { renderBarsSplit(containerId, data, small, chart); return; }
  const container = document.getElementById(containerId);
  if (!container) return;
  if (!data.length) { renderWidgetEmptyState(containerId); return; }

  const useTotal = barMode === 'total';
  const useWR    = barMode === 'wr';
  const useN     = barMode === 'n';
  const valFn    = d => useN ? d.n : useTotal ? d.totalR : useWR ? (d.n > 0 ? (d.oc.tp.n / d.n) * 100 : 0) : d.ev;
  const forceAlphaSort = containerId === 'sv-bars-pair' || containerId === 'sv-bars-setup';

  // Apply sort — sort by current metric
  const sorted = forceAlphaSort
    ? [...data].sort((a, b) => String(a.label).localeCompare(String(b.label), undefined, { sensitivity: 'base' }))
    : chart
      ? sortItems(data, chart, useTotal ? d => d.totalR : useN ? d => d.n : null)
      : [...data].sort((a, b) => valFn(b) - valFn(a));
  const absMax = useWR ? 100 : useN ? (Math.max(...sorted.map(d => d.n)) || 1) : (maxAbsR && !useTotal ? maxAbsR : Math.max(...sorted.map(d => Math.abs(valFn(d)))) || 1);

  const cG = tc('--g'), cA = tc('--gold') || tc('--a'), cT = tc('--t'), cR = tc('--r');
  const getColBar = d => useWR
    ? (barColorMode === 'binary'
        ? (valFn(d) >= 40 ? cG : cR)
        : _kpiTooltipColor(valFn(d), 'wr'))
    : barColorMode === 'binary'
      ? (d.ev > 0 ? cG : d.ev < 0 ? cR : cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const getColVal = d => useWR
    ? _kpiTooltipColor(valFn(d), 'wr')
    : useTotal && barColorMode === 'binary'
      ? (d.ev > 0 ? cG : d.ev < 0 ? cR : cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const cls    = small ? 'bar-row sm' : (chart === 'setup' ? 'bar-row setup' : 'bar-row');
  const decimals = useTotal ? 1 : useWR ? 0 : useN ? 0 : 3;
  const fmtVal = v => useWR ? v.toFixed(0) + '%' : useN ? String(v) : (v >= 0 ? '+' : '') + v.toFixed(decimals) + 'R';

  const _oc = d => `${d.oc.tp.n},${d.oc.tp.r.toFixed(2)},${d.oc.sl.n},${d.oc.sl.r.toFixed(2)},${d.oc.betp.n},${d.oc.betp.r.toFixed(2)},${d.oc.besl.n},${d.oc.besl.r.toFixed(2)}`;
  const _netStr = d => fmtVal(valFn(d));
  container.innerHTML = sorted.map(d => {
    const val = valFn(d);
    const pct = Math.min(Math.abs(val) / absMax * 100, 100);
    const colBar = getColBar(d);
    const colVal = getColVal(d);
    const valStr = fmtVal(val);
    const op = barOpacityForN(d.n);
    const nCls = _isLowVolume(d.n) ? 'bar-n bar-n-low' : 'bar-n';
    const nStr = _isLowVolume(d.n) ? ` ×${d.n} ⚠` : ` ×${d.n}`;
    return `<div class="${cls}" style="opacity:${op}" data-bar-label="${d.label.replace(/"/g,'&quot;')}" data-bar-rawkey="${(d._rawKey||d.label).replace(/"/g,'&quot;')}" data-bar-n="${d.n}" data-bar-oc="${_oc(d)}" data-bar-totalr="${d.totalR.toFixed(2)}">
      <div class="bar-label" title="${d.label}">${d.label}</div>
      <div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${colBar}"></div></div>
      <div class="bar-val" style="color:${colVal}"><span class="bar-r">${valStr}</span><span class="bar-net">${_netStr(d)}</span><span class="${nCls}">${nStr}</span></div>
    </div>`;
  }).join('');
  _fitBarList(containerId, sorted.length);
}

function renderDayBars(trades) {
  const container = document.getElementById('bars-day');
  if (!container) return;
  if (!trades.length) { renderWidgetEmptyState('bars-day'); return; }
  const tpConfig = appState.ui.tpConfig;
  const groups = {};
  trades.forEach(t => {
    const k = t.day;
    if (!k) return;
    if (!groups[k]) groups[k] = { rs: [], _oc: { TP: [], 'BE-TP': [], 'BE-SL': [], SL: [] } };
    const r = computeEffectiveRR(t, tpConfig);
    groups[k].rs.push(r);
    const arr = groups[k]._oc[t.outcome];
    if (arr) arr.push(r);
  });

  const _dsum = a => a.reduce((s,r)=>s+r,0);
  const useTotal = barMode === 'total';
  const useWR    = barMode === 'wr';
  const useN     = barMode === 'n';
  const valFn  = d => useN ? d.n : useTotal ? d.totalR : useWR ? (d.n > 0 ? (d.oc.tp.n / d.n) * 100 : 0) : d.ev;
  const cG = tc('--g'), cA = tc('--gold') || tc('--a'), cT = tc('--t'), cR = tc('--r');
  const getColBar = (v, d) => useWR
    ? (barColorMode === 'binary'
        ? (v >= 40 ? cG : cR)
        : _kpiTooltipColor(v, 'wr'))
    : barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : _kpiTooltipColor(d ? d.ev : v, 'avgr');
  const getColVal = (v, d) => useWR
    ? _kpiTooltipColor(v, 'wr')
    : useTotal && barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : _kpiTooltipColor(d ? d.ev : v, 'avgr');

  // Build items from actual data. Canonical Mon→Sun first, then any
  // non-canonical keys (alphabetical) so users who remapped the Day column
  // to a non-day-named source (e.g. Pair) still see every distinct value.
  const _dataKeys = Object.keys(groups).filter(d => groups[d].rs.length > 0);
  const _orderedKeys = DAY_ORDER.filter(d => _dataKeys.includes(d))
    .concat(_dataKeys.filter(d => !DAY_ORDER.includes(d)).sort());
  let items = _orderedKeys.map(d => {
    const { rs, _oc } = groups[d];
    const ev = _dsum(rs) / rs.length;
    return {
      label: DAY_FULL[d] || DAY_EN[d] || d, _rawKey: d, n: rs.length, ev, totalR: _dsum(rs),
      oc: {
        tp:   { r: _dsum(_oc.TP),       n: _oc.TP.length },
        betp: { r: _dsum(_oc['BE-TP']), n: _oc['BE-TP'].length },
        besl: { r: _dsum(_oc['BE-SL']), n: _oc['BE-SL'].length },
        sl:   { r: _dsum(_oc.SL),       n: _oc.SL.length },
      },
    };
  });

  // Sort: canonical = DAY_ORDER, desc/asc = by current metric
  const dayMode = barSortState['day'] || 'canonical';
  if (dayMode === 'canonical') {
    // already in DAY_ORDER from filter above — keep as-is
  } else {
    items = sortItems(items, 'day', useTotal ? d => d.totalR : useN ? d => d.n : null);
  }

  if (!items.length) { container.innerHTML = '<div class="no-data">No data</div>'; return; }
  if (barView === 'split') { renderBarsSplit('bars-day', items, false, null); return; }
  const decimals = useTotal ? 1 : useWR ? 0 : useN ? 0 : 3;
  const localMax = useWR ? 100 : useN ? (Math.max(...items.map(d => d.n)) || 1) : Math.max(...items.map(d => Math.abs(valFn(d)))) || 1;
  const fmtDayVal = v => useWR ? v.toFixed(0) + '%' : useN ? String(v) : (v >= 0 ? '+' : '') + v.toFixed(decimals) + 'R';

  const _ocD = d => `${d.oc.tp.n},${d.oc.tp.r.toFixed(2)},${d.oc.sl.n},${d.oc.sl.r.toFixed(2)},${d.oc.betp.n},${d.oc.betp.r.toFixed(2)},${d.oc.besl.n},${d.oc.besl.r.toFixed(2)}`;
  const _dayNetStr = d => fmtDayVal(valFn(d));
  container.innerHTML = items.map(d => {
    const val = valFn(d);
    const pct = Math.min(Math.abs(val) / localMax * 100, 100);
    const colBar = getColBar(useN ? d.ev : val, d);
    const colVal = getColVal(useN ? d.ev : val, d);
    const valStr = fmtDayVal(val);
    const op = barOpacityForN(d.n);
    const nCls = _isLowVolume(d.n) ? 'bar-n bar-n-low' : 'bar-n';
    const nStr = _isLowVolume(d.n) ? ` ×${d.n} ⚠` : ` ×${d.n}`;
    return `<div class="bar-row" style="opacity:${op}" data-bar-label="${d.label.replace(/"/g,'&quot;')}" data-bar-rawkey="${(d._rawKey||d.label).replace(/"/g,'&quot;')}" data-bar-n="${d.n}" data-bar-oc="${_ocD(d)}" data-bar-totalr="${d.totalR.toFixed(2)}">
      <div class="bar-label" title="${d.label}">${d.label}</div>
      <div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${colBar}"></div></div>
      <div class="bar-val" style="color:${colVal}"><span class="bar-r">${valStr}</span><span class="bar-net">${_dayNetStr(d)}</span><span class="${nCls}">${nStr}</span></div>
    </div>`;
  }).join('');
  _fitBarList('bars-day', items.length);
}

function renderObsBars(trades) {
  const container = document.getElementById('bars-obs');
  if (!container) return;
  if (!trades.length) { renderWidgetEmptyState('bars-obs'); return; }
  const tpConfig = appState.ui.tpConfig;
  const obsData = {};
  trades.forEach(t => {
    const r = computeEffectiveRR(t, tpConfig);
    t.obstacles.forEach(o => {
      if (!obsData[o]) obsData[o] = { rs: [], _oc: { TP: [], 'BE-TP': [], 'BE-SL': [], SL: [] } };
      obsData[o].rs.push(r);
      const arr = obsData[o]._oc[t.outcome];
      if (arr) arr.push(r);
    });
  });

  const obsKeys = [...new Set([...ALL_OBS, ...Object.keys(obsData)])];
  const _osum = a => a.reduce((s,r)=>s+r,0);
  let items = obsKeys
    .filter(o => obsData[o] && obsData[o].rs && obsData[o].rs.length >= 1)
    .map(o => {
      const { rs, _oc } = obsData[o];
      return {
        label: o, n: rs.length, ev: _osum(rs)/rs.length, totalR: _osum(rs),
        oc: {
          tp:   { r: _osum(_oc.TP),       n: _oc.TP.length },
          betp: { r: _osum(_oc['BE-TP']), n: _oc['BE-TP'].length },
          besl: { r: _osum(_oc['BE-SL']), n: _oc['BE-SL'].length },
          sl:   { r: _osum(_oc.SL),       n: _oc.SL.length },
        },
      };
    });

  const useTotal = barMode === 'total';
  const useWR    = barMode === 'wr';
  const useN     = barMode === 'n';
  const valFn  = d => useN ? d.n : useTotal ? d.totalR : useWR ? (d.n > 0 ? (d.oc.tp.n / d.n) * 100 : 0) : d.ev;
  items = sortItems(items, 'obs', useTotal ? d => d.totalR : useN ? d => d.n : null);
  if (!items.length) { container.innerHTML = '<div class="no-data">No data</div>'; return; }
  if (barView === 'split') { renderBarsSplit('bars-obs', items, false, null); return; }
  const absMax = useWR ? 100 : useN ? (Math.max(...items.map(d => d.n)) || 1) : (Math.max(...items.map(d => Math.abs(valFn(d)))) || 1);
  const cG = tc('--g'), cA = tc('--gold') || tc('--a'), cT = tc('--t'), cR = tc('--r');
  const getCBar = (v, d) => useWR
    ? (barColorMode === 'binary'
        ? (v >= 40 ? cG : cR)
        : _kpiTooltipColor(v, 'wr'))
    : barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const getCVal = (v, d) => useWR
    ? _kpiTooltipColor(v, 'wr')
    : useTotal && barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const decimals = useTotal ? 1 : useWR ? 0 : useN ? 0 : 3;
  const fmtObsVal = v => useWR ? v.toFixed(0) + '%' : useN ? String(v) : (v >= 0 ? '+' : '') + v.toFixed(decimals) + 'R';

  const _ocO = d => `${d.oc.tp.n},${d.oc.tp.r.toFixed(2)},${d.oc.sl.n},${d.oc.sl.r.toFixed(2)},${d.oc.betp.n},${d.oc.betp.r.toFixed(2)},${d.oc.besl.n},${d.oc.besl.r.toFixed(2)}`;
  const _obsNetStr = d => fmtObsVal(valFn(d));
  container.innerHTML = items.map(d => {
    const val = valFn(d);
    const pct = Math.min(Math.abs(val) / absMax * 100, 100);
    const colBar = getCBar(useN ? d.ev : val, d);
    const colVal = getCVal(useN ? d.ev : val, d);
    const valStr = fmtObsVal(val);
    const op = barOpacityForN(d.n);
    const nCls = _isLowVolume(d.n) ? 'bar-n bar-n-low' : 'bar-n';
    const nStr = _isLowVolume(d.n) ? ` ×${d.n} ⚠` : ` ×${d.n}`;
    return `<div class="bar-row obs tip-always" style="opacity:${op}" data-bar-label="${d.label.replace(/"/g,'&quot;')}" data-bar-rawkey="${d.label.replace(/"/g,'&quot;')}" data-bar-n="${d.n}" data-bar-oc="${_ocO(d)}" data-bar-totalr="${d.totalR.toFixed(2)}">
      <div class="bar-label" title="${d.label}">${d.label}</div>
      <div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${colBar}"></div></div>
      <div class="bar-val" style="color:${colVal}"><span class="bar-r">${valStr}</span><span class="bar-net">${_obsNetStr(d)}</span><span class="${nCls}">${nStr}</span></div>
    </div>`;
  }).join('');
  _fitBarList('bars-obs', items.length);
}

function renderH4ObsBars(trades) {
  const container = document.getElementById('bars-h4obs');
  if (!container) return;
  if (!trades.length) { renderWidgetEmptyState('bars-h4obs'); return; }

  const tpConfig = appState.ui.tpConfig;
  const h4Data = {};
  trades.forEach(t => {
    const h4arr = Array.isArray(t.h4) ? t.h4 : (t.h4 ? [t.h4] : []);
    const r = computeEffectiveRR(t, tpConfig);
    h4arr.forEach(tag => {
      if (!tag) return;
      if (!h4Data[tag]) h4Data[tag] = { rs: [], _oc: { TP: [], 'BE-TP': [], 'BE-SL': [], SL: [] } };
      h4Data[tag].rs.push(r);
      const arr = h4Data[tag]._oc[t.outcome];
      if (arr) arr.push(r);
    });
  });

  const _h4sum = a => a.reduce((s,r)=>s+r,0);
  let items = Object.entries(h4Data)
    .filter(([, d]) => d.rs.length >= 1)
    .map(([tag, { rs, _oc }]) => ({
      label:  tag,
      n:      rs.length,
      ev:     _h4sum(rs) / rs.length,
      totalR: _h4sum(rs),
      oc: {
        tp:   { r: _h4sum(_oc.TP),       n: _oc.TP.length },
        betp: { r: _h4sum(_oc['BE-TP']), n: _oc['BE-TP'].length },
        besl: { r: _h4sum(_oc['BE-SL']), n: _oc['BE-SL'].length },
        sl:   { r: _h4sum(_oc.SL),       n: _oc.SL.length },
      },
    }));

  const useTotal = barMode === 'total';
  const useWR    = barMode === 'wr';
  const useN     = barMode === 'n';
  const valFn  = d => useN ? d.n : useTotal ? d.totalR : useWR ? (d.n > 0 ? (d.oc.tp.n / d.n) * 100 : 0) : d.ev;
  items = sortItems(items, 'h4obs', useTotal ? d => d.totalR : useN ? d => d.n : null);

  if (!items.length) {
    container.innerHTML = '<div class="no-data">No H4 obstacle data</div>';
    return;
  }
  if (barView === 'split') { renderBarsSplit('bars-h4obs', items, false, null); return; }
  const absMax = useWR ? 100 : useN ? (Math.max(...items.map(d => d.n)) || 1) : (Math.max(...items.map(d => Math.abs(valFn(d)))) || 1);
  const cG = tc('--g'), cA = tc('--gold') || tc('--a'), cT = tc('--t'), cR = tc('--r');
  const getCBar = (v, d) => useWR
    ? (barColorMode === 'binary'
        ? (v >= 40 ? cG : cR)
        : _kpiTooltipColor(v, 'wr'))
    : useN ? cA
    : barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const getCVal = (v, d) => useWR
    ? _kpiTooltipColor(v, 'wr')
    : useN ? cA
    : useTotal && barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const decimals = useTotal ? 1 : useWR ? 0 : useN ? 0 : 3;
  const fmtH4Val = v => useWR ? v.toFixed(0) + '%' : useN ? String(v) : (v >= 0 ? '+' : '') + v.toFixed(decimals) + 'R';

  const _ocH4 = d => `${d.oc.tp.n},${d.oc.tp.r.toFixed(2)},${d.oc.sl.n},${d.oc.sl.r.toFixed(2)},${d.oc.betp.n},${d.oc.betp.r.toFixed(2)},${d.oc.besl.n},${d.oc.besl.r.toFixed(2)}`;
  const _h4NetStr = d => fmtH4Val(valFn(d));
  container.innerHTML = items.map(d => {
    const val = valFn(d);
    const pct = Math.min(Math.abs(val) / absMax * 100, 100);
    const colBar = getCBar(val, d);
    const colVal = getCVal(val, d);
    const valStr = fmtH4Val(val);
    const op = barOpacityForN(d.n);
    const nCls = _isLowVolume(d.n) ? 'bar-n bar-n-low' : 'bar-n';
    const nStr = _isLowVolume(d.n) ? ` ×${d.n} ⚠` : ` ×${d.n}`;
    return `<div class="bar-row obs tip-always" style="opacity:${op}" data-bar-label="${d.label.replace(/"/g,'&quot;')}" data-bar-rawkey="${d.label.replace(/"/g,'&quot;')}" data-bar-n="${d.n}" data-bar-oc="${_ocH4(d)}" data-bar-totalr="${d.totalR.toFixed(2)}">
      <div class="bar-label" title="${d.label}">${d.label}</div>
      <div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${colBar}"></div></div>
      <div class="bar-val" style="color:${colVal}"><span class="bar-r">${valStr}</span><span class="bar-net">${_h4NetStr(d)}</span><span class="${nCls}">${nStr}</span></div>
    </div>`;
  }).join('');
  _fitBarList('bars-h4obs', items.length);
}

// ══════════════════════════════════════════════════════
// EQUITY CURVE CANVAS — unified equity + drawdown chart
// ══════════════════════════════════════════════════════
let _chartEqMin   = 0;
let _chartEqRange = 1;
let ddVisible     = false;  // DD overlay hidden by default
let cumulMarkersVisible = true;  // Peak + current cumul labels — visible by default
let wrVisible     = false;  // Rolling WR overlay hidden by default
let _wrSeries     = [];     // Last computed WR series (for hover tooltip)
let   WR_WINDOW   = 20;     // Rolling window size (trades) — user-configurable
let equityMode    = 'trade'; // 'trade' | 'date' — granularity of equity chart
let _chartDayMode = false;   // true when equityMode === 'date'

// ... (computed inside drawCharts, stored here for reuse)
let _chartDays        = [];   // [{ date, trades[], eqEnd, ddEnd }] — one per day (for grouping)
let _chartTrades      = [];   // flat sorted trade array — one per equity series point
let _chartEquitySeries = [];  // equity values, one per trade (parallel to _chartTrades)
let _chartPad   = null;
let _chartW     = 0;
let _chartH     = 0;
let _selectedDayIdx = null;
let _selRange       = null;  // { iMin, iMax } — persistent range marker, null when none
let _activeSelection = null; // last sel object passed to updateSelectionWidget (for drawer sync)

// ── Group trades by calendar day ──
function groupByDay(trades) {
  const tpConfig = appState.ui.tpConfig;
  // KEEP raw t.r — data-validity existence check, not a numerical aggregation.
  const valid  = trades.filter(t => t.date && t.r !== undefined);
  const map    = new Map();
  valid.forEach(t => {
    if (!map.has(t.date)) map.set(t.date, []);
    map.get(t.date).push(t);
  });
  // Sort by date string (YYYY-MM-DD, lexicographic = chronological)
  const days = [...map.entries()]
    .sort(([a], [b]) => a < b ? -1 : 1)
    .map(([date, dayTrades]) => ({
      date,
      // Sort within each day by hour, then pair A-Z as tiebreak
      trades: [...dayTrades].sort((a, b) => {
        const hDiff = (a.hour ?? 99) - (b.hour ?? 99);
        if (hDiff !== 0) return hDiff;
        return (a.pair || '').localeCompare(b.pair || '');
      }),
      rSum: dayTrades.reduce((s, t) => s + computeEffectiveRR(t, tpConfig), 0),
    }));

  // Compute cumulative equity and drawdown end-of-day
  let eq = 0, peak = 0;
  days.forEach(d => {
    eq += d.rSum;
    if (eq > peak) peak = eq;
    d.eqEnd = eq;
    d.ddEnd = eq - peak;
  });
  return days;
}

// ── Nice tick helper ──
function niceStep(range, targetTicks) {
  const raw = range / targetTicks;
  const mag = Math.pow(10, Math.floor(Math.log10(raw || 1)));
  const nice = [1, 2, 2.5, 5, 10];
  return mag * (nice.find(n => mag * n >= raw) || 1);
}

// ── Resize + init all three canvases ──
function _initCanvases() {
  const wrap = getByIdSafe('equity-chart-wrap');
  if (!wrap) return null;
  // Force layout flush to get accurate dimensions
  const W = wrap.getBoundingClientRect().width  || wrap.offsetWidth  || 400;
  const H = wrap.getBoundingClientRect().height || wrap.offsetHeight || 200;
  if (W < 10 || H < 10) return null; // not laid out yet

  ['equityCanvas', 'ddCanvas', 'wrCanvas', 'crossCanvas'].forEach(id => {
    const c = getByIdSafe(id);
    if (!c) return;
    // Set CSS size first (visible size)
    c.style.width  = W + 'px';
    c.style.height = H + 'px';
    // Then set backing store size for sharpness
    c.width  = Math.round(W * devicePixelRatio);
    c.height = Math.round(H * devicePixelRatio);
    const ctx = c.getContext?.('2d');
    if (!ctx) return;
    ctx.resetTransform();
    ctx.scale(devicePixelRatio, devicePixelRatio);
    ctx.clearRect(0, 0, W, H);
  });
  return { W, H };
}

// ── Main entry called from render() ──
function drawCharts(trades) {

  // ── Adapt wrap height — let flex handle it, just ensure minimum ──
  const days = groupByDay(trades);
  _chartDays = days;

  const wrap = getByIdSafe('equity-chart-wrap');
  if (wrap) {
    wrap.style.minHeight = '110px';
    wrap.style.height    = '';
  }

  const dim = _initCanvases();
  if (!dim) return;
  const { W, H } = dim;
  _chartW = W; _chartH = H;

  const ddMaxEl  = getByIdSafe('dd-max-val');
  const ddCurrEl = getByIdSafe('dd-curr-val');

  if (!days.length) {
    if (ddMaxEl)  ddMaxEl.textContent = '—';
    if (ddCurrEl) ddCurrEl.textContent = '—';
    renderCanvasEmptyState('#equity-chart-wrap', ['equityCanvas', 'ddCanvas', 'crossCanvas']);
    return;
  }
  clearCanvasEmptyState('#equity-chart-wrap');

  // Build equity and DD series — per trade or per date depending on equityMode
  let equitySeries, ddSeries;
  if (equityMode === 'date') {
    _chartDayMode = true;
    _chartTrades  = [];
    equitySeries  = days.map(d => d.eqEnd);
    ddSeries      = days.map(d => d.ddEnd);
  } else {
    _chartDayMode = false;
    const allTrades = days.flatMap(d => d.trades);
    _chartTrades    = allTrades;
    const tpConfig = appState.ui.tpConfig;
    let _eq = 0, _peak = 0;
    equitySeries = [];
    ddSeries = [];
    for (const t of allTrades) {
      const r = t.effectiveR ?? computeEffectiveRR(t, tpConfig);
      _eq += r;
      if (_eq > _peak) _peak = _eq;
      equitySeries.push(_eq);
      ddSeries.push(_eq - _peak);
    }
  }
  _chartEquitySeries = equitySeries;

  const maxDD  = ddSeries.length ? Math.min(...ddSeries) : 0;
  const currDD = ddSeries.length ? ddSeries[ddSeries.length - 1] : 0;

  if (ddMaxEl)  ddMaxEl.textContent = maxDD.toFixed(2) + 'R';
  if (ddCurrEl) {
    ddCurrEl.textContent = currDD.toFixed(2) + 'R';
    ddCurrEl.style.color = currDD < -0.001 ? tc('--r') : tc('--dim');
  }

  // ── Layout ──
  const n   = equitySeries.length;  // one point per trade (or per day in date mode)
  const pad = { t: 10, r: ddVisible ? 46 : 14, b: _chartDayMode ? 24 : 20, l: 44 };
  _chartPad = pad;
  const cw  = W - pad.l - pad.r;
  const ch  = H - pad.t - pad.b;

  // Equity scale
  const eqMin   = Math.min(0, ...equitySeries);
  const eqMax   = Math.max(...equitySeries);
  const eqRange = (eqMax - eqMin) || 1;
  const toXi    = i => pad.l + (i / (n - 1 || 1)) * cw;
  const toYeq   = v => pad.t + ch - ((v - eqMin) / eqRange) * ch;
  _chartEqMin   = eqMin;
  _chartEqRange = eqRange;

  // DD scale (0 top → maxDD bottom)
  const ddRange = Math.abs(maxDD) || 1;
  const toYdd   = v => pad.t + (Math.abs(v) / ddRange) * ch;

  // ── LAYER 1: equityCanvas ──
  const eqCtx = getCanvasContext('equityCanvas');
  if (!eqCtx) return;
  eqCtx.clearRect(0, 0, W, H);

  const accent = tc('--t');  // equity line color — teal, matches mobile version
  const dimCol = tc('--dim');
  const cLine  = tc('--line');
  const cLine2 = tc('--line2');

  // Grid + left axis ticks
  const eqStep  = niceStep(eqRange, 4);
  const eqTicks = [];
  for (let v = Math.ceil(eqMin / eqStep) * eqStep; v <= eqMax + eqStep * 0.1; v += eqStep)
    eqTicks.push(parseFloat(v.toFixed(6)));
  if (!eqTicks.some(v => Math.abs(v) < 0.001)) eqTicks.push(0);

  eqCtx.font = `${tc('--typo-eq-axis-size')} DM Mono, monospace`;
  eqCtx.textAlign = 'right';
  eqTicks.forEach(v => {
    const y = toYeq(v);
    if (y < pad.t - 4 || y > H - pad.b + 4) return;
    const isZero = Math.abs(v) < 0.001;
    eqCtx.strokeStyle = isZero ? cLine2 : cLine;
    eqCtx.lineWidth   = isZero ? 1 : 0.6;
    eqCtx.setLineDash(isZero ? [4, 4] : [2, 5]);
    eqCtx.beginPath(); eqCtx.moveTo(pad.l, y); eqCtx.lineTo(pad.l + cw, y); eqCtx.stroke();
    eqCtx.setLineDash([]);
    eqCtx.fillStyle = isZero ? cLine2 : dimCol;
    eqCtx.fillText((v >= 0 ? '+' : '') + v.toFixed(0) + 'R', pad.l - 4, y + 3);
  });

  // Equity gradient fill
  const y0eq  = toYeq(0);
  const eqGrd = eqCtx.createLinearGradient(0, pad.t, 0, H - pad.b);
  eqGrd.addColorStop(0, tcRgba('--t', 0.18));
  eqGrd.addColorStop(1, tcRgba('--t', 0.02));
  eqCtx.beginPath();
  eqCtx.moveTo(toXi(0), y0eq);
  equitySeries.forEach((v, i) => eqCtx.lineTo(toXi(i), toYeq(v)));
  eqCtx.lineTo(toXi(n - 1), y0eq);
  eqCtx.closePath();
  eqCtx.fillStyle = eqGrd; eqCtx.fill();

  // Equity line
  eqCtx.beginPath();
  eqCtx.strokeStyle = accent; eqCtx.lineWidth = 1.8;
  equitySeries.forEach((v, i) => i === 0 ? eqCtx.moveTo(toXi(i), toYeq(v)) : eqCtx.lineTo(toXi(i), toYeq(v)));
  eqCtx.stroke();

  // ── X axis: month labels in date mode ──
  if (_chartDayMode && days.length > 1) {
    const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    eqCtx.font = `${tc('--typo-eq-xaxis-size')} DM Mono, monospace`;
    eqCtx.textBaseline = 'top';
    let lastMonth = '';
    days.forEach((d, i) => {
      const month = d.date.slice(0, 7); // YYYY-MM
      if (month !== lastMonth) {
        lastMonth = month;
        const x = toXi(i);
        const [yr, mo] = month.split('-');
        const lbl = MONTHS[parseInt(mo) - 1] + ' \'' + yr.slice(2);
        // avoid clipping near right edge
        eqCtx.textAlign = x > W - pad.r - 20 ? 'right' : x < pad.l + 10 ? 'left' : 'center';
        eqCtx.fillStyle = dimCol;
        eqCtx.fillText(lbl, x, H - pad.b + 4);
        // subtle vertical divider at month boundary
        if (i > 0) {
          eqCtx.strokeStyle = cLine2;
          eqCtx.lineWidth   = 0.5;
          eqCtx.setLineDash([2, 4]);
          eqCtx.beginPath(); eqCtx.moveTo(x, pad.t); eqCtx.lineTo(x, pad.t + ch); eqCtx.stroke();
          eqCtx.setLineDash([]);
        }
      }
    });
    eqCtx.textBaseline = 'alphabetic';
  }

  // ── Peak / current cumul labels (matches the Share Your Data style) ──
  // Two roundrect markers on the equity line: gold for the all-time peak
  // (max of equitySeries) and the equity-tone marker for the current cumul
  // (last point). Skipped when peak === last (single dot suffices).
  // Gated by `cumulMarkersVisible` — toggled via the "Markers" button in
  // the widget header.
  if (cumulMarkersVisible) {
    const cGold     = tc('--gold') || '#f5c451';
    const cWin      = tc('--g') || '#5dd6a8';
    const cLoss     = tc('--r') || '#e05a72';
    const lastEq    = equitySeries[n - 1];
    const peakVal   = Math.max(...equitySeries);
    const peakIdx   = equitySeries.indexOf(peakVal);
    const lastIdx   = n - 1;
    const eqAccent  = lastEq >= 0 ? cWin : cLoss;
    const markerFs  = tc('--typo-eq-marker-size') || '10px';

    const drawCumulLabel = (idx, value, color) => {
      const x = toXi(idx);
      const y = toYeq(value);
      const text = (value >= 0 ? '+' : '') + value.toFixed(1) + 'R';

      // Dot at the data point
      eqCtx.save();
      eqCtx.beginPath();
      eqCtx.arc(x, y, 3.5, 0, Math.PI * 2);
      eqCtx.fillStyle = color;
      eqCtx.fill();
      eqCtx.strokeStyle = tc('--bg1') || '#0b1220';
      eqCtx.lineWidth = 1.5;
      eqCtx.stroke();

      // Roundrect label
      eqCtx.font = `${markerFs} DM Mono, monospace`;
      const textW = Math.ceil(eqCtx.measureText(text).width);
      const boxW  = textW + 12;
      const boxH  = 18;
      // Place label above when point is in upper half, below otherwise — keeps
      // it from clipping the top edge for a peak near the chart roof.
      const isUpperHalf = y < pad.t + ch / 2;
      let boxY = isUpperHalf ? y + 8 : y - boxH - 8;
      boxY = Math.max(pad.t, Math.min(boxY, H - pad.b - boxH));
      const boxX = Math.max(pad.l, Math.min(x - boxW / 2, W - pad.r - boxW));

      eqCtx.fillStyle = tcRgba('--bg4', 0.88);
      eqCtx.strokeStyle = color;
      eqCtx.lineWidth = 1;
      eqCtx.beginPath();
      eqCtx.roundRect(boxX, boxY, boxW, boxH, 5);
      eqCtx.fill();
      eqCtx.stroke();

      eqCtx.fillStyle = tc('--white');
      eqCtx.textAlign = 'center';
      eqCtx.textBaseline = 'middle';
      eqCtx.fillText(text, boxX + boxW / 2, boxY + boxH / 2);
      eqCtx.restore();
    };

    drawCumulLabel(peakIdx, peakVal, cGold);
    if (lastIdx !== peakIdx) drawCumulLabel(lastIdx, lastEq, eqAccent);
  }

  // ── LAYER 2: ddCanvas ──
  const ddCanvas = getByIdSafe('ddCanvas');
  const ddCtx    = ddCanvas?.getContext?.('2d');
  if (!ddCanvas || !ddCtx) return;
  ddCtx.clearRect(0, 0, W, H);

  if (ddVisible && maxDD < -0.001) {
    const cRed = tc('--r');

    // DD gradient fill
    const ddGrd = ddCtx.createLinearGradient(0, pad.t, 0, H - pad.b);
    ddGrd.addColorStop(0, tcRgba('--r', 0.30));
    ddGrd.addColorStop(1, tcRgba('--r', 0.04));
    ddCtx.beginPath();
    ddCtx.moveTo(toXi(0), toYdd(0));
    ddSeries.forEach((v, i) => ddCtx.lineTo(toXi(i), toYdd(v)));
    ddCtx.lineTo(toXi(n - 1), toYdd(0));
    ddCtx.closePath();
    ddCtx.fillStyle = ddGrd; ddCtx.fill();

    // DD curve
    ddCtx.beginPath();
    ddCtx.strokeStyle = cRed; ddCtx.lineWidth = 1.5;
    ddSeries.forEach((v, i) => i === 0 ? ddCtx.moveTo(toXi(i), toYdd(v)) : ddCtx.lineTo(toXi(i), toYdd(v)));
    ddCtx.stroke();

    // Right axis ticks
    const ddStep  = niceStep(Math.abs(maxDD), 3);
    const ddTicks = [0];
    for (let v = -ddStep; v >= maxDD - ddStep * 0.3; v -= ddStep) ddTicks.push(parseFloat(v.toFixed(6)));
    ddCtx.font = `${tc('--typo-dd-axis-size')} DM Mono, monospace`; ddCtx.textAlign = 'left';
    ddTicks.forEach(v => {
      const y = toYdd(v);
      if (y < pad.t - 4 || y > H - pad.b + 4) return;
      const isMaxDDTick = Math.abs(v - maxDD) < 0.001;
      ddCtx.fillStyle = v === 0 ? dimCol : (isMaxDDTick ? cRed : tcRgba('--r', 0.6));
      const absV = Math.abs(v);
      const lbl  = v === 0 ? '' : ('−' + (absV % 1 < 0.05 ? absV.toFixed(0) : absV.toFixed(1)));
      if (lbl) ddCtx.fillText(lbl, pad.l + cw + 4, y + 3);
    });

    // Max DD: dotted line + dot + label
    const yMaxDD  = toYdd(maxDD);
    const maxIdx  = ddSeries.indexOf(maxDD);
    ddCtx.strokeStyle = tcRgba('--r', 0.5); ddCtx.lineWidth = 1; ddCtx.setLineDash([4, 3]);
    ddCtx.beginPath(); ddCtx.moveTo(pad.l, yMaxDD); ddCtx.lineTo(pad.l + cw, yMaxDD); ddCtx.stroke();
    ddCtx.setLineDash([]);
    if (maxIdx >= 0) {
      const mx = toXi(maxIdx);
      ddCtx.beginPath(); ddCtx.arc(mx, yMaxDD, 4, 0, Math.PI * 2);
      ddCtx.fillStyle = cRed; ddCtx.fill();
      ddCtx.strokeStyle = tc('--bg1'); ddCtx.lineWidth = 1.5; ddCtx.stroke();
      ddCtx.fillStyle = cRed; ddCtx.font = `${tc('--typo-dd-label-size')} DM Mono, monospace`; ddCtx.textAlign = 'center';
      ddCtx.fillText('max', mx, yMaxDD - 7);
    }
    // Current DD dot
    if (currDD < -0.001) {
      ddCtx.beginPath(); ddCtx.arc(toXi(n - 1), toYdd(currDD), 3.5, 0, Math.PI * 2);
      ddCtx.fillStyle = cRed; ddCtx.fill();
      ddCtx.strokeStyle = tc('--bg1'); ddCtx.lineWidth = 1.5; ddCtx.stroke();
    }
  }

  // ── Draw selected-day highlight if any ──
  if (_selectedDayIdx !== null && _selectedDayIdx >= 0 && _selectedDayIdx < n) {
    const cc2 = document.getElementById('crossCanvas');
    if (cc2) {
      const ctx2 = cc2.getContext?.('2d');
      if (!ctx2) return;
      ctx2.clearRect(0, 0, W, H);
    }
    _drawDayHighlight(_selectedDayIdx, toXi, toYeq, toYdd, equitySeries, ddSeries, pad, ch);
  }

  // ── Restore persistent range marker if one is active ──
  if (_selRange !== null) {
    const { iMin, iMax } = _selRange;
    if (iMin >= 0 && iMax < n && iMin <= iMax) {
      const cc2 = document.getElementById('crossCanvas');
      if (cc2) {
        const rect2 = cc2.getBoundingClientRect();
        _drawPersistentRangeMarker(iMin, iMax, toXi, toYeq, equitySeries, pad, rect2);
      }
    } else {
      // Range is out of bounds for current data — clear it
      _selRange = null;
    }
  }

  // ── LAYER 3: wrCanvas — rolling win rate ──
  const wrCanvas = getByIdSafe('wrCanvas');
  const wrCtx    = wrCanvas?.getContext?.('2d');
  if (!wrCanvas || !wrCtx) return;
  wrCtx.clearRect(0, 0, W, H);

  const _wrEnough = _chartDayMode ? days.length >= WR_WINDOW : _chartTrades.length >= WR_WINDOW;
  if (!wrVisible || !_wrEnough) { _wrSeries = []; }
  if (wrVisible && _wrEnough) {
    const cBlue = tc('--b');

    // Build rolling WR series — per day in date mode, per trade otherwise
    const wrSeries = _chartDayMode
      ? days.map((_, i) => {
          if (i < WR_WINDOW - 1) return null;
          const wDays = days.slice(i - WR_WINDOW + 1, i + 1);
          return wDays.filter(d => d.rSum > 0).length / WR_WINDOW * 100;
        })
      : _chartTrades.map((_, i) => {
          if (i < WR_WINDOW - 1) return null;
          const window = _chartTrades.slice(i - WR_WINDOW + 1, i + 1);
          return window.filter(isWinner).length / WR_WINDOW * 100;
        });

    _wrSeries = wrSeries;  // store for hover tooltip
    // Scale: 0% → 100%, mapped to full chart height
    const toYwr = pct => pad.t + ch - (pct / 100) * ch;

    // 50% reference line (dashed)
    const y50 = toYwr(50);
    wrCtx.strokeStyle = cBlue + '44';
    wrCtx.lineWidth   = 1;
    wrCtx.setLineDash([4, 4]);
    wrCtx.beginPath();
    wrCtx.moveTo(pad.l, y50);
    wrCtx.lineTo(pad.l + cw, y50);
    wrCtx.stroke();
    wrCtx.setLineDash([]);

    // WR label at 50% line
    wrCtx.fillStyle = cBlue + '88';
    wrCtx.font = '8px DM Mono, monospace';
    wrCtx.textAlign = 'right';
    wrCtx.fillText('50%', pad.l - 4, y50 + 3);

    // Gradient fill under WR curve
    const wrGrd = wrCtx.createLinearGradient(0, pad.t, 0, pad.t + ch);
    wrGrd.addColorStop(0, cBlue + '30');
    wrGrd.addColorStop(1, cBlue + '04');

    // Draw filled area + line
    wrCtx.beginPath();
    let started = false;
    wrSeries.forEach((pct, i) => {
      if (pct === null) return;
      const x = toXi(i), y = toYwr(pct);
      if (!started) { wrCtx.moveTo(x, y); started = true; }
      else wrCtx.lineTo(x, y);
    });
    // Close path for fill
    const lastIdx = wrSeries.length - 1;
    wrCtx.lineTo(toXi(lastIdx), pad.t + ch);
    // Find first valid index
    const firstValid = wrSeries.findIndex(p => p !== null);
    wrCtx.lineTo(toXi(firstValid), pad.t + ch);
    wrCtx.closePath();
    wrCtx.fillStyle = wrGrd;
    wrCtx.fill();

    // Draw line on top
    wrCtx.beginPath();
    started = false;
    wrSeries.forEach((pct, i) => {
      if (pct === null) return;
      const x = toXi(i), y = toYwr(pct);
      if (!started) { wrCtx.moveTo(x, y); started = true; }
      else wrCtx.lineTo(x, y);
    });
    wrCtx.strokeStyle = cBlue;
    wrCtx.lineWidth   = 1.5;
    wrCtx.stroke();

    // Last WR value label
    const lastPct = wrSeries[wrSeries.length - 1];
    if (lastPct !== null) {
      const lx = toXi(wrSeries.length - 1);
      const ly = toYwr(lastPct);
      wrCtx.beginPath();
      wrCtx.arc(lx, ly, 3, 0, Math.PI * 2);
      wrCtx.fillStyle = cBlue;
      wrCtx.fill();
      wrCtx.fillStyle = cBlue;
      wrCtx.font = 'bold 8px DM Mono, monospace';
      wrCtx.textAlign = lx > W * 0.8 ? 'right' : 'left';
      wrCtx.fillText(lastPct.toFixed(0) + '%', lx + (lx > W * 0.8 ? -6 : 6), ly - 5);
    }
  }

  // ── Wire crossCanvas events (fresh closures every draw) ──
  const cc = document.getElementById('crossCanvas');
  bindManagedEvent(cc, '_managedMouseDown', 'mousedown', e => _onChartMouseDown(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad));
  bindManagedEvent(cc, '_managedMouseMove', 'mousemove', e => _onChartMouseMove(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad));
  bindManagedEvent(cc, '_managedMouseUp', 'mouseup', e => _onChartMouseUp(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad));
  bindManagedEvent(cc, '_managedMouseLeave', 'mouseleave', e => _onChartMouseLeave(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad));
}

// ═══════════════════════════════════════════════════
// DRAG-SELECT STATE
// ═══════════════════════════════════════════════════
const _drag = {
  active:   false,   // currently dragging
  startX:   0,       // mousedown X (canvas-relative)
  currentX: 0,       // current mouse X
  startIdx: -1,      // day index at drag start
  moved:    false,   // did we move enough to be a drag (not a click)?
};
const DRAG_THRESHOLD = 6; // px before it becomes a drag

// ── mousedown ──
function _onChartMouseDown(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad) {
  if (e.button !== 0) return; // left button only
  const cc   = getByIdSafe('crossCanvas');
  if (!cc) return;
  const rect = cc.getBoundingClientRect();
  const mx   = e.clientX - rect.left;
  const cw   = rect.width - pad.l - pad.r;
  const n    = equitySeries.length;
  const frac = Math.max(0, Math.min(1, (mx - pad.l) / cw));
  const idx  = Math.round(frac * (n - 1));

  _drag.active   = true;
  _drag.startX   = mx;
  _drag.currentX = mx;
  _drag.startIdx = idx;
  _drag.moved    = false;
  e.preventDefault();
}

// ── mousemove ──
function _onChartMouseMove(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad) {
  const cc   = getByIdSafe('crossCanvas');
  if (!cc) return;
  const rect = cc.getBoundingClientRect();
  const mx   = e.clientX - rect.left;

  if (_drag.active) {
    _drag.currentX = mx;
    const dist = Math.abs(mx - _drag.startX);
    if (dist > DRAG_THRESHOLD) {
      _drag.moved = true;
      cc.classList.add('selecting');
      // Hide tooltip while dragging
      const tt = document.getElementById('eq-tooltip');
      if (tt) tt.classList.remove('visible');
      // Draw selection rectangle
      _drawSelectionRect(equitySeries, ddSeries, toXi, toYeq, toYdd, pad, rect);
    } else {
      // Tiny movement — show hover tooltip as normal
      _onChartHover(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad);
    }
  } else {
    _onChartHover(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad);
  }
}

// ── Draw selection rectangle on crossCanvas ──
function _drawSelectionRect(equitySeries, ddSeries, toXi, toYeq, toYdd, pad, rect) {
  const cc  = getByIdSafe('crossCanvas');
  const ctx = cc?.getContext?.('2d');
  if (!cc || !ctx) return;
  const cW  = rect.width;
  const cH  = rect.height;
  const ch  = cH - pad.t - pad.b;

  ctx.clearRect(0, 0, cW, cH);

  // Recompute snap indices
  const n    = equitySeries.length;
  const cw   = cW - pad.l - pad.r;
  const fracA = Math.max(0, Math.min(1, (_drag.startX   - pad.l) / cw));
  const fracB = Math.max(0, Math.min(1, (_drag.currentX - pad.l) / cw));
  const idxA = Math.round(fracA * (n - 1));
  const idxB = Math.round(fracB * (n - 1));
  const iMin = Math.min(idxA, idxB);
  const iMax = Math.max(idxA, idxB);

  const xA = toXi(iMin);
  const xB = toXi(iMax);

  // Filled rect
  ctx.fillStyle = tcRgba('--gold', 0.08);
  ctx.fillRect(xA, pad.t, xB - xA, ch);

  // Border lines
  ctx.strokeStyle = tcRgba('--gold', 0.55);
  ctx.lineWidth   = 1.5;
  ctx.setLineDash([]);
  ctx.beginPath();
  ctx.moveTo(xA, pad.t); ctx.lineTo(xA, pad.t + ch);
  ctx.moveTo(xB, pad.t); ctx.lineTo(xB, pad.t + ch);
  ctx.stroke();

  // Dots on both endpoints
  [iMin, iMax].forEach(idx => {
    const x  = toXi(idx);
    const ye = toYeq(equitySeries[idx]);
    ctx.beginPath(); ctx.arc(x, ye, 4, 0, Math.PI * 2);
    ctx.fillStyle = tc('--gold'); ctx.fill();
    ctx.strokeStyle = tc('--bg1'); ctx.lineWidth = 1.5; ctx.stroke();
  });

  // Count label at top center
  let nTrades, nDays;
  if (_chartDayMode) {
    nDays   = iMax - iMin + 1;
    nTrades = _chartDays.slice(iMin, iMax + 1).reduce((s, d) => s + d.trades.length, 0);
  } else {
    nTrades = iMax - iMin + 1;
    nDays   = new Set(_chartTrades.slice(iMin, iMax + 1).map(t => t.date)).size;
  }
  const midX    = (xA + xB) / 2;
  ctx.fillStyle = tc('--gold');
  ctx.font      = `bold ${tc('--typo-eq-marker-size')} DM Mono, monospace`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(`${nDays} day${nDays > 1 ? 's' : ''} · ${nTrades} trade${nTrades > 1 ? 's' : ''}`, midX, pad.t - 5);

  // Delta R at bottom
  const deltaR = equitySeries[iMax] - equitySeries[iMin];
  const dLabel = (deltaR >= 0 ? '+' : '') + deltaR.toFixed(2) + 'R';
  ctx.fillStyle = deltaR >= 0 ? tc('--g') : tc('--r');
  ctx.fillText(dLabel, midX, pad.t + ch + 11);
}

// ── mouseup ──
function _onChartMouseUp(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad) {
  if (!_drag.active) return;
  const cc   = getByIdSafe('crossCanvas');
  if (!cc) return;
  const rect = cc.getBoundingClientRect();
  const mx   = e.clientX - rect.left;
  _drag.currentX = mx;
  _drag.active   = false;
  cc.classList.remove('selecting');

  if (!_drag.moved) {
    // It was a click, not a drag → use original click logic
    const cw   = rect.width - pad.l - pad.r;
    const n    = equitySeries.length;
    const frac = Math.max(0, Math.min(1, (mx - pad.l) / cw));
    const idx  = Math.round(frac * (n - 1));
    _onChartClick(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad, idx);
    return;
  }

  // Compute final indices
  const cw   = rect.width - pad.l - pad.r;
  const n    = equitySeries.length;
  const fracA = Math.max(0, Math.min(1, (_drag.startX - pad.l)   / cw));
  const fracB = Math.max(0, Math.min(1, (_drag.currentX - pad.l) / cw));
  const idxA  = Math.round(fracA * (n - 1));
  const idxB  = Math.round(fracB * (n - 1));
  const iMin  = Math.min(idxA, idxB);
  const iMax  = Math.max(idxA, idxB);

  // Commit the persistent marker (replaces the temporary drag rect)
  const ctx2 = cc.getContext?.('2d');
  if (!ctx2) return;
  ctx2.clearRect(0, 0, rect.width, rect.height);
  _drawPersistentRangeMarker(iMin, iMax, toXi, toYeq, equitySeries, pad, rect);

  // Clear any day selection
  _selectedDayIdx = null;

  openRangePanel(iMin, iMax);
}

// ── mouseleave ──
function _onChartMouseLeave(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad) {
  if (_drag.active) {
    // Fire mouseup logic on leave
    _drag.active = false;
    const cc = getByIdSafe('crossCanvas');
    if (!cc) return;
    cc.classList.remove('selecting');
    if (_drag.moved) {
      const rect  = cc.getBoundingClientRect();
      const cw    = rect.width - pad.l - pad.r;
      const n     = equitySeries.length;
      const fracB = Math.max(0, Math.min(1, (_drag.currentX - pad.l) / cw));
      const idxB  = Math.round(fracB * (n - 1));
      const fracA = Math.max(0, Math.min(1, (_drag.startX - pad.l) / cw));
      const idxA  = Math.round(fracA * (n - 1));
      const iMin  = Math.min(idxA, idxB);
      const iMax  = Math.max(idxA, idxB);
      const ctx2  = cc.getContext?.('2d');
      if (!ctx2) return;
      ctx2.clearRect(0, 0, rect.width, rect.height);
      _drawPersistentRangeMarker(iMin, iMax, toXi, toYeq, equitySeries, pad, rect);
      _selectedDayIdx = null;
      openRangePanel(iMin, iMax);
    }
  }
  _onChartLeave();
}

// ── Original click handler (called from mouseup when not a drag) ──
function _onChartClick(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad, idx) {
  const cc   = getByIdSafe('crossCanvas');
  if (!cc) return;
  if (idx === undefined) {
    // Legacy path: compute idx from event
    const rect = cc.getBoundingClientRect();
    const mx   = e.clientX - rect.left;
    const cw   = rect.width - pad.l - pad.r;
    const n    = equitySeries.length;
    const frac = Math.max(0, Math.min(1, (mx - pad.l) / cw));
    idx = Math.round(frac * (n - 1));
  }
  // Resolve clicked item — day object in date mode, trade in trade mode
  let _clickDay, _clickTrade = null;
  if (_chartDayMode) {
    _clickDay = _chartDays[idx];
    if (!_clickDay) return;
  } else {
    if (!_chartTrades[idx]) return;
    _clickTrade = _chartTrades[idx];
    _clickDay   = _chartDays.find(d => d.date === _clickTrade.date)
               || { date: _clickTrade.date, trades: [_clickTrade], rSum: computeEffectiveRR(_clickTrade, appState.ui.tpConfig) };
  }

  // Close range panel if open
  closeRangePanel(true); // silent close

  // Toggle: click same point again → deselect
  if (_selectedDayIdx === idx) {
    _selectedDayIdx = null;
    closeDayPanel();
    const ctx = cc.getContext?.('2d');
    if (!ctx) return;
    const r   = cc.getBoundingClientRect();
    ctx.clearRect(0, 0, r.width, r.height);
    return;
  }
  _selectedDayIdx = idx;
  // Open the day panel — highlight the specific trade only in trade mode
  openDayPanel(_clickDay, _clickTrade);
  const r2  = cc.getBoundingClientRect();
  const ch2 = r2.height - pad.t - pad.b;
  const ctx = cc.getContext?.('2d');
  if (!ctx) return;
  ctx.clearRect(0, 0, r2.width, r2.height);
  _drawDayHighlight(idx, toXi, toYeq, toYdd, equitySeries, ddSeries, pad, ch2);
}

// ── Open range panel for days[iMin..iMax] ──
function openRangePanel(iMin, iMax) {
  if (_chartDayMode ? !_chartDays.length : !_chartTrades.length) return;

  // iMin/iMax are point indices — trade indices in trade mode, day indices in date mode
  const tpConfig = appState.ui.tpConfig;
  const allTrades = _chartDayMode
    ? _chartDays.slice(iMin, iMax + 1).flatMap(d => d.trades)
    : _chartTrades.slice(iMin, iMax + 1);
  const totalR    = allTrades.reduce((s, t) => s + computeEffectiveRR(t, tpConfig), 0);
  const nWins     = allTrades.filter(isWinner).length;
  const wr        = allTrades.length ? (nWins / allTrades.length * 100) : 0;
  const dateFrom2 = allTrades[0]?.date || '—';
  const dateTo2   = allTrades[allTrades.length - 1]?.date || '—';

  // Group by day for the selection widget display
  const dayMap = new Map();
  allTrades.forEach(t => {
    if (!dayMap.has(t.date)) dayMap.set(t.date, []);
    dayMap.get(t.date).push(t);
  });
  const selectedDays = [...dayMap.entries()].sort(([a],[b]) => a<b?-1:1).map(([date,trades]) => ({
    date, trades, rSum: trades.reduce((s,t) => s+computeEffectiveRR(t, tpConfig), 0)
  }));

  // Store persistent range so redraws can restore the marker
  _selRange = { iMin, iMax };

  updateSelectionWidget({
    type: 'range', days: selectedDays, trades: allTrades,
    totalR, nWins, wr, dateFrom: dateFrom2, dateTo: dateTo2,
  });
}

function closeRangePanel(silent) {
  if (!silent) {
    _selRange = null;
    _clearSelectionCanvas();
    updateSelectionWidget(null);
  }
}

// ══════════════════════════════════════════════════════
// SELECTION WIDGET
// ══════════════════════════════════════════════════════

function updateSelectionWidget(sel) {
  _activeSelection = sel;
  const empty    = document.getElementById('sel-empty');
  const tableWrap= document.getElementById('sel-table-wrap');
  const tbody    = document.getElementById('sel-tbody');
  const badge    = document.getElementById('sel-badge');
  const kpis     = document.getElementById('sel-kpis');
  const clearBtn = document.getElementById('sel-clear-btn');
  const card     = document.getElementById('w-selection-card');
  if (!empty || !tableWrap || !tbody) return;

  if (!sel) {
    // Clear state
    setVisible(empty, true);
    setVisible(tableWrap, false);
    if (badge)    setVisible(badge, false);
    if (kpis)     setVisible(kpis, false);
    if (clearBtn) setVisible(clearBtn, false);
    return;
  }

  const { type, days, trades, totalR, nWins, wr, dateFrom, dateTo } = sel;
  const isRange = type === 'range';
  const nLoss   = trades.filter(isLoser).length;
  const avgR    = trades.length ? totalR / trades.length : 0;
  const rClass  = totalR > 0 ? 'pos' : totalR < 0 ? 'neg' : 'neu';

  // Badge
  if (badge) {
    setVisible(badge, true);
    badge.className = 'sel-badge' + (isRange ? ' range' : '');
    badge.textContent = isRange
      ? `Range  ${dateFrom} → ${dateTo}  ·  ${days.length} day${days.length > 1 ? 's' : ''}`
      : `Day  ${dateFrom}`;
  }

  // KPI strip
  if (kpis) {
    setVisible(kpis, true);
    kpis.innerHTML = [
      { label: 'Trades', val: trades.length, cls: '' },
      { label: 'Win Rate', val: wr.toFixed(1) + '%', cls: wr >= 50 ? 'pos' : 'neg' },
      { label: 'Total R', val: (totalR >= 0 ? '+' : '') + totalR.toFixed(2) + 'R', cls: rClass },
      { label: 'Avg R',   val: (avgR  >= 0 ? '+' : '') + avgR.toFixed(3)  + 'R', cls: avgR > 0 ? 'pos' : avgR < 0 ? 'neg' : 'neu' },
      { label: 'W / L',   val: `${nWins} / ${nLoss}`, cls: '' },
    ].map(k => `
      <div class="sel-kpi">
        <span class="sel-kpi-label">${k.label}</span>
        <span class="sel-kpi-val ${k.cls}">${k.val}</span>
      </div>`).join('');
  }

    if (clearBtn) setVisible(clearBtn, true);

  // Table
  setVisible(empty, false);
  setVisible(tableWrap, true);

  const _ht = sel.highlightTrade || null;  // trade to highlight

  if (isRange) {
    // Group by day with separator rows
    tbody.innerHTML = days.map(day => {
      const dayR     = day.rSum;
      const dayRSign = dayR >= 0 ? '+' : '';
      const dayClass = dayR > 0 ? 'pos' : dayR < 0 ? 'neg' : '';
      const dayRows  = day.trades.map(t => _selTradeRow(t)).join('');
      return `<tr class="sel-day-sep">
        <td colspan="10">${day.date}
          <span style="color:var(--${dayClass||'dim'});font-weight:700;margin-left:8px">${dayRSign}${dayR.toFixed(2)}R</span>
          <span style="color:var(--dim);margin-left:6px">${day.trades.length} trade${day.trades.length > 1 ? 's' : ''}</span>
        </td>
      </tr>${dayRows}`;
    }).join('');
  } else {
    // Single day — no separator; highlight the specific clicked trade if any
    tbody.innerHTML = trades.map(t => _selTradeRow(t, _ht && t === _ht)).join('');
  }

  // Pulse the card border to signal update
  if (card) {
    card.classList.remove('sel-pulse');
    void card.offsetWidth; // reflow to restart animation
    card.classList.add('sel-pulse');
  }
}

function _getSelectionTradesInDisplayedOrder() {
  const rows = [...document.querySelectorAll('#sel-tbody tr[data-trade-id]')];
  const trades = Array.isArray(_activeSelection?.trades) ? _activeSelection.trades : [];
  if (!rows.length || !trades.length) return trades;
  const byId = new Map(trades.map(t => [_getTradeLightboxId(t), t]));
  return rows.map(row => byId.get(row.dataset.tradeId)).filter(Boolean);
}

// Helper: build one <tr> for the selection table
function _selTradeRow(t, highlighted) {
  const _rEff   = t.effectiveR ?? computeEffectiveRR(t, appState.ui.tpConfig);
  const rSign   = _rEff >= 0 ? '+' : '';
  const outcome = t.outcome || '?';
  const ocClass = { TP: 'oc-tp', SL: 'oc-sl', 'BE-TP': 'oc-betp', 'BE-SL': 'oc-besl' };
  const rowBg   = {
    'TP':    getWinColorAlpha(.25),
    'SL':    getLossColorAlpha(.27),
    'BE-TP': 'rgba(41,98,255,.22)',
    'BE-SL': 'rgba(180,120,240,.22)',
  }[outcome] || '';
  const h4arr  = Array.isArray(t.h4)       ? t.h4       : (t.h4       ? [t.h4]       : []);
  const obsArr = Array.isArray(t.obstacles) ? t.obstacles : (t.obstacles ? [t.obstacles] : []);
  const h4html  = h4arr.length  ? h4arr.map(x => `<span class="dpt-tag" style="color:var(--body)">${x}</span>`).join('')  : '<span style="color:var(--dim)">—</span>';
  const obshtml = obsArr.length ? obsArr.map(x => `<span class="dpt-tag" style="color:var(--body)">${x}</span>`).join('') : '<span style="color:var(--dim)">—</span>';
  const dir = t.direction || '';
  const dirCol = dir === 'Achat' ? 'var(--g)' : dir === 'Vente' ? 'var(--r)' : 'var(--dim)';
  const dirHtml = dir
    ? `<span style="font-family:'DM Mono',monospace;font-size:var(--typo-micro-size,9px);font-weight:700;letter-spacing:.5px;color:${dirCol}">${dir.toUpperCase()}</span>`
    : '<span style="color:var(--dim)">—</span>';
  const hlStyle = highlighted
    ? `outline:1px solid var(--gold);outline-offset:-1px;background:color-mix(in srgb,var(--gold) 12%,${rowBg || 'transparent'});`
    : `background:${rowBg}`;
  const safePair   = (t.pair || '').replace(/"/g, '&quot;');
  const safeDate   = (t.date || '').replace(/"/g, '&quot;');
  const safeTradeId = _getTradeLightboxId(t).replace(/"/g, '&quot;');
  const safeH4b    = (t.imgH4Before || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;');
  const safeM15b   = (t.imgM15      || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;');
  const safeM15a   = (t.imgM15After || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;');
  const safeH4bOrig  = (t.imgH4BeforeOrig || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;');
  const safeM15bOrig = (t.imgM15Orig      || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;');
  const safeM15aOrig = (t.imgM15AfterOrig || '').trim().replace(/'/g, "\\'").replace(/"/g, '&quot;');
  const _selBtn    = (url, step, emoji, title) => url
    ? `<button class="trade-media-btn" data-action="open-img-lightbox"
         data-scope="#sel-tbody"
         data-img-url="${url}" data-img-step="${step}"
         data-trade-id="${safeTradeId}"
         data-trade-pair="${safePair}" data-trade-date="${safeDate}"
         data-trade-h4before="${safeH4b}" data-trade-m15before="${safeM15b}" data-trade-m15after="${safeM15a}"
         data-trade-h4before-orig="${safeH4bOrig}" data-trade-m15before-orig="${safeM15bOrig}" data-trade-m15after-orig="${safeM15aOrig}"
         title="${title}">${emoji}</button>`
    : '';
  const imgBtns    = `<div class="trade-media-group">
    ${_selBtn(safeH4b,'h4Before','📷',_getTradeMediaStepLabel('h4Before'))}${_selBtn(safeM15b,'m15Before','📷',_getTradeMediaStepLabel('m15Before'))}${_selBtn(safeM15a,'m15After','📸',_getTradeMediaStepLabel('m15After'))}
  </div>`;
  const notionUrl  = (t.notionUrl || '').trim();
  const notionBtn  = notionUrl
    ? `<button class="trade-media-btn trade-link-btn" data-action="open-notion-overlay" data-notion-url="${notionUrl.replace(/"/g, '&quot;')}" title="Open in Notion">🔗</button>`
    : '';
  return `<tr data-trade-id="${safeTradeId}" style="${hlStyle}">
    <td class="mono" style="color:var(--dim)">${_escapeHtml(t.date || '—')}</td>
    <td><div style="display:flex;align-items:center;gap:4px">${notionBtn}<span class="dpt-pair">${_escapeHtml(t.pair || '—')}</span></div></td>
    <td><span class="${ocClass[outcome] || ''}" style="font-weight:600">${_escapeHtml(outcome)}</span></td>
    <td class="r" style="color:${_rEff > 0 ? 'var(--g)' : _rEff < 0 ? 'var(--r)' : 'var(--gold)'};font-weight:600">${rSign}${_rEff.toFixed(1)}R</td>
    <td>${dirHtml}</td>
    <td style="font-size:11px;color:var(--body)">${t.setup || '—'}</td>
    <td style="font-size:11px;color:var(--body)">${t.session || '—'}</td>
    <td>${h4html}</td>
    <td>${obshtml}</td>
    <td style="padding:0 4px;text-align:center">${imgBtns}</td>
  </tr>`;
}

// ── Clear equity chart selection and the widget ──
function clearEquitySelection() {
  _clearSelectionCanvas();
  _selectedDayIdx  = null;
  _drag.active     = false;
  _selRange        = null;
  updateSelectionWidget(null);
}

// ── Internal: clear just the crossCanvas overlay ──
function _clearSelectionCanvas() {
  const cc = getByIdSafe('crossCanvas');
  if (!cc) return;
  const ctx = cc.getContext?.('2d');
  if (!ctx) return;
  const r   = cc.getBoundingClientRect();
  ctx.clearRect(0, 0, r.width || cc.offsetWidth, r.height || cc.offsetHeight);
}

function openDayPanel(day, highlightTrade) {
  const allTrades = day.trades || [];
  const tpConfig = appState.ui.tpConfig;
  const totalR    = day.rSum ?? allTrades.reduce((s, t) => s + computeEffectiveRR(t, tpConfig), 0);
  const nWins     = allTrades.filter(isWinner).length;
  const wr        = allTrades.length ? (nWins / allTrades.length * 100) : 0;
  _selRange = null;
  updateSelectionWidget({
    type: 'day', days: [day], trades: allTrades,
    totalR, nWins, wr, dateFrom: day.date, dateTo: day.date,
    highlightTrade,  // the specific trade that was clicked on the chart
  });
}

function closeDayPanel() {
  _selectedDayIdx = null;
  _clearSelectionCanvas();
  updateSelectionWidget(null);
}

function _onChartLeave() {
  const tt = getByIdSafe('eq-tooltip');
  if (tt) tt.classList.remove('visible');
  const cc = getByIdSafe('crossCanvas');
  if (!cc) return;
  const ctx = cc.getContext?.('2d');
  if (!ctx) return;
  const r   = cc.getBoundingClientRect();
  ctx.clearRect(0, 0, r.width || cc.offsetWidth, r.height || cc.offsetHeight);

  // Re-draw persistent markers after hover clears the canvas
  const _selValid = _selectedDayIdx !== null &&
    (_chartDayMode ? _chartDays[_selectedDayIdx] : _chartTrades[_selectedDayIdx]);
  if (_selValid && _chartPad) {
    const filtered = getFiltered();
    drawCharts(filtered);
  } else if (_selRange !== null && _chartEquitySeries.length && _chartPad) {
    // Fast path: restore just the range marker without full redraw
    const n    = _chartEquitySeries.length;
    const pad  = _chartPad;
    const cw   = _chartW - pad.l - pad.r;
    const ch   = _chartH - pad.t - pad.b;
    const toXi  = i => pad.l + (i / (n - 1 || 1)) * cw;
    const toYeq = v => pad.t + ch - ((v - _chartEqMin) / (_chartEqRange || 1)) * ch;
    const { iMin, iMax } = _selRange;
    if (iMin >= 0 && iMax < n) {
      _drawPersistentRangeMarker(iMin, iMax, toXi, toYeq, _chartEquitySeries, pad, r);
    }
  }
}

// ── Draw a persistent (committed) range marker on crossCanvas ──
function _drawPersistentRangeMarker(iMin, iMax, toXi, toYeq, equitySeries, pad, rect) {
  const cc  = getByIdSafe('crossCanvas');
  if (!cc) return;
  const ctx = cc.getContext?.('2d');
  if (!ctx) return;
  const cH  = rect.height;
  const ch  = cH - pad.t - pad.b;
  const yTop = pad.t;
  const yBot = pad.t + ch;

  const xA = toXi(iMin);
  const xB = toXi(iMax);

  // ── Filled rect — gold, identical to drag selection ──
  ctx.fillStyle = tcRgba('--gold', 0.08);
  ctx.fillRect(xA, yTop, xB - xA, ch);

  // ── Border lines — gold, identical to drag selection ──
  ctx.strokeStyle = tcRgba('--gold', 0.55);
  ctx.lineWidth   = 1.5;
  ctx.setLineDash([]);
  ctx.beginPath();
  ctx.moveTo(xA, yTop); ctx.lineTo(xA, yBot);
  ctx.moveTo(xB, yTop); ctx.lineTo(xB, yBot);
  ctx.stroke();

  // ── Equity dots at endpoints — gold, identical to drag selection ──
  [iMin, iMax].forEach(idx => {
    const x  = toXi(idx);
    const ye = toYeq(equitySeries[idx]);
    ctx.beginPath(); ctx.arc(x, ye, 4, 0, Math.PI * 2);
    ctx.fillStyle = tc('--gold'); ctx.fill();
    ctx.strokeStyle = tc('--bg1'); ctx.lineWidth = 1.5; ctx.stroke();
  });

  // ── Labels ──
  let nTrades, nDays;
  if (_chartDayMode) {
    nDays   = iMax - iMin + 1;
    nTrades = _chartDays.slice(iMin, iMax + 1).reduce((s, d) => s + d.trades.length, 0);
  } else {
    nTrades = iMax - iMin + 1;
    nDays   = new Set(equitySeries.slice(iMin, iMax + 1).map((_, i) => (_chartTrades[iMin + i] || {}).date)).size;
  }
  const deltaR  = equitySeries[iMax] - equitySeries[iMin];
  const dSign  = deltaR >= 0 ? '+' : '';
  const midX   = (xA + xB) / 2;

  ctx.font         = `bold ${tc('--typo-eq-marker-size')} DM Mono, monospace`;
  ctx.textAlign    = 'center';
  ctx.textBaseline = 'middle';

  // nDays + nTrades at top — same position as during drag
  ctx.fillStyle = tc('--gold');
  ctx.fillText(`${nDays} day${nDays > 1 ? 's' : ''} · ${nTrades} trade${nTrades > 1 ? 's' : ''}`, midX, yTop - 5);

  // deltaR at bottom
  const dLabel = `${dSign}${deltaR.toFixed(2)}R`;
  ctx.fillStyle = deltaR >= 0 ? tc('--g') : tc('--r');
  ctx.fillText(dLabel, midX, yBot + 11);
}

// ── Draw a selected-day ring on crossCanvas ──
function _drawDayHighlight(idx, toXi, toYeq, toYdd, equitySeries, ddSeries, pad, ch) {
  const cc  = getByIdSafe('crossCanvas');
  if (!cc) return;
  const ctx = cc.getContext?.('2d');
  if (!ctx) return;
  // ctx already has dpr scale from _initCanvases — draw in CSS-pixel coords directly
  const xLine = toXi(idx);

  // Subtle vertical band
  ctx.strokeStyle = tcRgba('--white', 0.12);
  ctx.lineWidth   = 12;
  ctx.beginPath(); ctx.moveTo(xLine, pad.t); ctx.lineTo(xLine, pad.t + ch); ctx.stroke();
  // Thin accent line
  ctx.strokeStyle = tcRgba('--white', 0.4);
  ctx.lineWidth   = 1; ctx.setLineDash([2, 3]);
  ctx.beginPath(); ctx.moveTo(xLine, pad.t); ctx.lineTo(xLine, pad.t + ch); ctx.stroke();
  ctx.setLineDash([]);

  // Equity ring
  ctx.beginPath(); ctx.arc(xLine, toYeq(equitySeries[idx]), 5, 0, Math.PI * 2);
  ctx.fillStyle = tc('--gold'); ctx.fill();
  ctx.strokeStyle = tc('--bg1'); ctx.lineWidth = 2; ctx.stroke();

  // DD ring
  if (ddVisible && ddSeries[idx] < -0.001) {
    ctx.beginPath(); ctx.arc(xLine, toYdd(ddSeries[idx]), 5, 0, Math.PI * 2);
    ctx.fillStyle = tc('--r'); ctx.fill();
    ctx.strokeStyle = tc('--bg1'); ctx.lineWidth = 2; ctx.stroke();
  }
}

// ── Hover: crosshair + tooltip ──
function _onChartHover(e, equitySeries, ddSeries, toXi, toYeq, toYdd, pad) {
  const cc   = getByIdSafe('crossCanvas');
  const tt   = getByIdSafe('eq-tooltip');
  if (!cc || !tt) return;

  // Use the canvas CSS bounding rect for mouse coords (not backing buffer)
  const rect = cc.getBoundingClientRect();
  const mx   = e.clientX - rect.left;
  const cW   = rect.width;
  const cH   = rect.height;
  const cw   = cW - pad.l - pad.r;
  const ch   = cH - pad.t - pad.b;
  const n    = equitySeries.length;

  const frac = Math.max(0, Math.min(1, (mx - pad.l) / cw));
  const idx  = Math.round(frac * (n - 1));
  if (idx < 0 || idx >= n) { _onChartLeave(); return; }

  // Resolve hover item — day in date mode, trade in trade mode
  let trade = null, day = null;
  if (_chartDayMode) {
    day = _chartDays[idx];
    if (!day) { _onChartLeave(); return; }
  } else {
    if (!_chartTrades[idx]) { _onChartLeave(); return; }
    trade = _chartTrades[idx];
    day   = _chartDays.find(d => d.date === trade.date) || { date: trade.date, trades: [trade], rSum: computeEffectiveRR(trade, appState.ui.tpConfig) };
  }
  const eqVal = equitySeries[idx];
  const ddVal = ddSeries[idx];
  const xLine = toXi(idx);

  // ── Draw crosshair ──
  const ctx = cc.getContext?.('2d');
  if (!ctx) return;
  // Clear in CSS-pixel space (scale already applied in _initCanvases)
  ctx.clearRect(0, 0, cW, cH);

  // Re-draw persistent range marker under crosshair
  if (_selRange !== null) {
    const { iMin, iMax } = _selRange;
    if (iMin >= 0 && iMax < n) {
      _drawPersistentRangeMarker(iMin, iMax, toXi, toYeq, equitySeries, pad, rect);
    }
  }

  // Re-draw selected highlight under crosshair
  if (_selectedDayIdx !== null && _selectedDayIdx !== idx) {
    _drawDayHighlight(_selectedDayIdx, toXi, toYeq, toYdd, equitySeries, ddSeries, pad, ch);
  }

  // Vertical hairline
  ctx.strokeStyle = tc('--line2'); ctx.lineWidth = 1; ctx.setLineDash([3, 3]);
  ctx.beginPath(); ctx.moveTo(xLine, pad.t); ctx.lineTo(xLine, pad.t + ch); ctx.stroke();
  ctx.setLineDash([]);

  // Equity dot
  ctx.beginPath(); ctx.arc(xLine, toYeq(eqVal), 4, 0, Math.PI * 2);
  ctx.fillStyle = tc('--gold'); ctx.fill();
  ctx.strokeStyle = tc('--bg1'); ctx.lineWidth = 1.5; ctx.stroke();

  // DD dot
  if (ddVisible && ddVal < -0.001) {
    ctx.beginPath(); ctx.arc(xLine, toYdd(ddVal), 4, 0, Math.PI * 2);
    ctx.fillStyle = tc('--r'); ctx.fill();
    ctx.strokeStyle = tc('--bg1'); ctx.lineWidth = 1.5; ctx.stroke();
  }

  // ── Tooltip content ──
  const nTrades = day.trades.length;
  if (_chartDayMode) {
    _setText('eq-tt-date', day.date + `  ·  ${nTrades} trade${nTrades > 1 ? 's' : ''}`);
  } else {
    _setText('eq-tt-date', trade.date + (trade.hour !== null && trade.hour !== undefined ? `  ·  ${String(trade.hour).padStart(2,'0')}h` : '') + `  ·  ${trade.pair || ''}  ${trade.outcome}`);
  }
  _setText('eq-tt-equity', (eqVal >= 0 ? '+' : '') + eqVal.toFixed(2) + 'R');
  const ddRow = document.getElementById('eq-tt-dd-row');
  if (ddRow) {
    setVisible(ddRow, ddVisible && ddVal < -0.001);
    _setText('eq-tt-dd', ddVal.toFixed(2) + 'R');
  }
  const wrRow = document.getElementById('eq-tt-wr-row');
  if (wrRow) {
    const wrVal = (wrVisible && _wrSeries.length > idx) ? _wrSeries[idx] : null;
    setVisible(wrRow, wrVisible && wrVal !== null);
    if (wrVal !== null) {
      _setText('eq-tt-wr', wrVal.toFixed(1) + '%');
      _setText('eq-tt-wr-n', WR_WINDOW + 't');
    }
  }

  // Day P&L row
  let dayLine = document.getElementById('eq-tt-day-r');
  if (!dayLine) {
    dayLine = document.createElement('div');
    dayLine.id = 'eq-tt-day-r';
    dayLine.className = 'eq-tt-row';
    dayLine.classList.add('eq-tt-row-day');
    dayLine.innerHTML = `<span class="eq-tt-label eq-tt-label-fill">Day P&L</span><span id="eq-tt-day-rval" class="eq-tt-val"></span>`;
    tt.appendChild(dayLine);
  }
  const rvalEl = getByIdSafe('eq-tt-day-rval');
  if (rvalEl) {
    rvalEl.textContent = (day.rSum >= 0 ? '+' : '') + day.rSum.toFixed(2) + 'R';
    rvalEl.classList.remove('is-positive', 'is-negative', 'is-neutral');
    rvalEl.classList.add(day.rSum > 0 ? 'is-positive' : day.rSum < 0 ? 'is-negative' : 'is-neutral');
  }

  // Hint
  let hintEl = document.getElementById('eq-tt-hint');
  if (!hintEl) {
    hintEl = document.createElement('div');
    hintEl.id = 'eq-tt-hint';
    hintEl.className = 'eq-tt-hint';
    tt.appendChild(hintEl);
  }
  hintEl.textContent = _chartDayMode && nTrades > 1
    ? `click · ${nTrades} trades`
    : 'click for day details';

  tt.classList.add('visible');

  // ── Position tooltip (relative to equity-wrap, not fixed) ──
  const wrapEl = getByIdSafe('equity-chart-wrap');
  if (!wrapEl) return;
  const wrapRect = wrapEl.getBoundingClientRect();
  const relX     = e.clientX - wrapRect.left;
  const relY     = e.clientY - wrapRect.top;
  const ttW      = tt.offsetWidth  || 150;
  const ttH      = tt.offsetHeight || 90;
  const wW       = wrapRect.width;
  const wH       = wrapRect.height;
  let tx = relX + 14;
  let ty = relY - ttH / 2;
  if (tx + ttW > wW - 4) tx = relX - ttW - 12;
  if (ty < 4)             ty = 4;
  if (ty + ttH > wH - 4) ty = wH - ttH - 4;
  tt.style.left = tx + 'px';
  tt.style.top  = ty + 'px';
}

// ── Click: show day panel ──
// ── Toggle DD overlay ──
function toggleDrawdown() {
  ddVisible = !ddVisible;
  const btn        = document.getElementById('dd-toggle-btn');
  const icon       = document.getElementById('dd-toggle-icon');
  const legendItem = document.getElementById('dd-legend-item');
  btn?.classList.toggle('active', ddVisible);
  if (icon) icon.textContent = ddVisible ? '▼' : '▶';
  if (legendItem) legendItem.style.opacity = ddVisible ? '1' : '0.3';
  const filtered = getFiltered();
  drawCharts(filtered);
}

// ── Toggle peak + current cumul labels on the equity line ──
function toggleCumulMarkers() {
  cumulMarkersVisible = !cumulMarkersVisible;
  const btn  = document.getElementById('cumul-toggle-btn');
  const icon = document.getElementById('cumul-toggle-icon');
  // active-gold matches the markers' gold accent (peak label color);
  // visually distinct from DD's red `active` and WR's blue `active-blue`.
  btn?.classList.toggle('active-gold', cumulMarkersVisible);
  if (icon) icon.textContent = cumulMarkersVisible ? '▼' : '▶';
  drawCharts(getFiltered());
}

function toggleWinRate() {
  wrVisible = !wrVisible;
  const btn        = document.getElementById('wr-toggle-btn');
  const icon       = document.getElementById('wr-toggle-icon');
  const legendItem = document.getElementById('wr-legend-item');
  btn?.classList.toggle('active-blue', wrVisible);
  if (icon) icon.textContent = wrVisible ? '▼' : '▶';
  if (legendItem) legendItem.style.opacity = wrVisible ? '1' : '0.3';
  // sync select style with active state
  const sel = document.getElementById('wr-window-sel');
  if (sel) sel.style.color = wrVisible ? 'var(--b)' : 'var(--dim)';
  drawCharts(getFiltered());
}

function setWRWindow(val) {
  WR_WINDOW = parseInt(val) || 20;
  if (wrVisible) drawCharts(getFiltered());
}

function toggleEquityMode() {
  equityMode = equityMode === 'trade' ? 'date' : 'trade';
  const btn = getByIdSafe('eq-mode-btn');
  if (btn) {
    btn.classList.toggle('active-gold', equityMode === 'date');
    const label = btn.querySelector('span');
    if (label) label.textContent = equityMode === 'date' ? 'Dates' : 'Trades';
  }
  clearEquitySelection();
  drawCharts(getFiltered());
}

// ══════════════════════════════════════════════════════
// DONUT CANVAS — responsive, reads container size
// ══════════════════════════════════════════════════════
function drawDonut(stats) {
  const canvas = document.getElementById('donutCanvas');
  const wrap   = document.querySelector('.donut-canvas-wrap');
  const outer  = document.querySelector('.donut-wrap');
  const leg    = document.getElementById('donut-legend');
  if (!canvas || !wrap || !outer || !leg) return;

  if (!stats || !stats.n) {
    leg.innerHTML = '';
    renderCanvasEmptyState('.donut-wrap', ['donutCanvas']);
    return;
  }
  clearCanvasEmptyState('.donut-wrap');

  // ── Measure available space ──
  const outerRect = outer.getBoundingClientRect();
  const availW = outerRect.width  || 200;
  const availH = outerRect.height || 140;

  // ── Render legend FIRST so we can measure its height ──
  // Legend font scales with widget height (not donut size) so we can size the
  // donut based on the legend's final measured height.
  const legFont = availH < 180 ? '9.5px' : '11px';
  const pctFont = availH < 180 ? '8.5px' : '9.5px';

  // Colors and data need to be computed before legend markup
  const cG   = tc('--g');
  const cA   = tc('--gold') || tc('--a');
  const cR   = tc('--r');
  const cBg1 = tc('--bg1');

  const mixHex = (a, b) => {
    const pa = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(a);
    const pb = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(b);
    if (!pa || !pb) return a;
    return `rgb(${Math.round((parseInt(pa[1],16)+parseInt(pb[1],16))/2)},${Math.round((parseInt(pa[2],16)+parseInt(pb[2],16))/2)},${Math.round((parseInt(pa[3],16)+parseInt(pb[3],16))/2)})`;
  };
  const cBETP = tc('--oc-betp');
  const cBESL = tc('--oc-besl');

  const data = [
    { label:'TP',    n: (stats||{}).cnt_tp||0, color: cG    },
    { label:'BE-TP', n: (stats||{}).be_tp ||0, color: cBETP },
    { label:'BE-SL', n: (stats||{}).be_sl ||0, color: cBESL },
    { label:'SL',    n: (stats||{}).cnt_sl||0, color: cR    },
  ].filter(d => d.n > 0);

  const total = data.reduce((s, d) => s + d.n, 0) || 1;

  leg.innerHTML = data.map(d => `
    <div class="dl-row">
      <div class="dl-dot" style="background:${d.color}"></div>
      <span class="dl-label" style="font-size:${legFont}">${d.label}</span>
      <span class="dl-val"   style="font-size:${legFont}">${d.n}</span>
      <span class="dl-pct"   style="font-size:${pctFont}">${(d.n/total*100).toFixed(0)}%</span>
    </div>`).join('');

  // Measure rendered legend height (it's absolutely positioned at the bottom)
  const legendH = leg.offsetHeight || 60;
  const gap     = 8;

  // ── Size the donut responsively ──
  // Donut + legend are stacked in a flex column inside .donut-wrap-centered,
  // so the donut needs to fit ONCE above the legend (not twice — the previous
  // formula assumed the donut was anchored to the widget centre and wasted
  // the upper half on short widgets). Padding (16px) covers the wrap's
  // 8px padding × 2 plus the inter-item gap.
  const maxW    = availW - 16;
  const maxH    = availH - legendH - 16;
  const maxSide = Math.min(maxW, maxH, 260);
  const S       = Math.max(60, maxSide);  // minimum 60px

  // Apply size to the canvas-wrap
  wrap.style.width  = S + 'px';
  wrap.style.height = S + 'px';

  // Size the canvas backing store for sharpness
  canvas.width  = Math.round(S * devicePixelRatio);
  canvas.height = Math.round(S * devicePixelRatio);
  canvas.style.width  = S + 'px';
  canvas.style.height = S + 'px';

  const ctx = canvas.getContext('2d');
  ctx.resetTransform();
  ctx.scale(devicePixelRatio, devicePixelRatio);
  ctx.clearRect(0, 0, S, S);

  // ── Geometry — scale with S ──
  const cx  = S / 2;
  const cy  = S / 2;
  const r   = S * 0.38;   // outer radius
  const iR  = S * 0.22;   // inner (hole) radius

  // Store sector geometry for hit-testing (hover + click)
  _donutSectors = [];
  let angle = -Math.PI / 2;
  data.forEach(d => {
    const sweep = (d.n / total) * Math.PI * 2;
    _donutSectors.push({ label: d.label, color: d.color, start: angle, end: angle + sweep, n: d.n });
    angle += sweep;
  });
  _donutGeom = { cx, cy, r, iR, S, cBg1 };

  _drawDonutSectors(ctx, _donutSectors, _donutGeom, stats, null);
}

// ── Donut rendering helper (supports hover highlight) ──
let _donutSectors = [];
let _donutGeom = null;
let _donutHoverZone = null; // 'win' | 'loss' | null

function _isWinSector(label) { return label === 'TP' || label === 'BE-TP'; }

function _drawDonutSectors(ctx, sectors, geom, stats, hoverZone) {
  const { cx, cy, r, iR, S, cBg1 } = geom;
  const isCenter = hoverZone === 'center';
  ctx.resetTransform();
  ctx.scale(devicePixelRatio, devicePixelRatio);
  ctx.clearRect(0, 0, S, S);

  sectors.forEach(d => {
    const highlighted = !isCenter && hoverZone === d.label;
    const dimmed = hoverZone && !isCenter && hoverZone !== d.label;

    ctx.beginPath();
    ctx.moveTo(cx, cy);
    const drawR = highlighted ? r * 1.06 : r;
    ctx.arc(cx, cy, drawR, d.start, d.end);
    ctx.fillStyle = d.color;
    ctx.globalAlpha = (dimmed || isCenter) ? 0.4 : 1;
    ctx.fill();
    ctx.globalAlpha = 1;
  });

  // Donut hole — scale up when center is hovered
  const holeR = isCenter ? iR * 1.15 : iR;
  ctx.beginPath();
  ctx.arc(cx, cy, holeR, 0, Math.PI * 2);
  ctx.fillStyle = cBg1 || '#111';
  ctx.fill();

  // Subtle ring glow when center hovered
  if (isCenter) {
    ctx.beginPath();
    ctx.arc(cx, cy, holeR, 0, Math.PI * 2);
    ctx.strokeStyle = tc('--gold') || '#c8a84e';
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = 0.5;
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  // Center label: win rate
  if (stats && stats.n > 0) {
    const wr = (stats.w / stats.n * 100).toFixed(0) + '%';
    ctx.fillStyle = isCenter ? (tc('--gold') || '#c8a84e') : tc('--white');
    const fontSize = isCenter ? Math.max(10, Math.round(S * 0.15)) : Math.max(9, Math.round(S * 0.13));
    ctx.font = `700 ${fontSize}px Anybody, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(wr, cx, cy);
  }
}

function _donutHitTest(e) {
  const canvas = document.getElementById('donutCanvas');
  if (!canvas || !_donutGeom || !_donutSectors.length) return null;
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  const { cx, cy, r, iR } = _donutGeom;
  const scaleX = _donutGeom.S / rect.width;
  const scaleY = _donutGeom.S / rect.height;
  const sx = x * scaleX, sy = y * scaleY;
  const dx = sx - cx, dy = sy - cy;
  const dist = Math.sqrt(dx * dx + dy * dy);
  if (dist > r * 1.08) return null;
  if (dist < iR) return 'center';
  const angle = Math.atan2(dy, dx);
  for (const sec of _donutSectors) {
    let start = sec.start, end = sec.end;
    let a = angle;
    if (a < start) a += Math.PI * 2;
    if (a >= start && a < end) return sec.label;
    if (end > Math.PI && angle + Math.PI * 2 >= start && angle + Math.PI * 2 < end) return sec.label;
  }
  return null;
}

// ── Donut hover ──
document.addEventListener('mousemove', e => {
  if (!e.target.closest('#donutCanvas')) {
    if (_donutHoverZone) {
      _donutHoverZone = null;
      const canvas = document.getElementById('donutCanvas');
      if (canvas && _donutGeom) {
        canvas.style.cursor = '';
        _drawDonutSectors(canvas.getContext('2d'), _donutSectors, _donutGeom, calcStats(getFiltered()), null);
      }
    }
    return;
  }
  const zone = _donutHitTest(e);
  if (zone !== _donutHoverZone) {
    _donutHoverZone = zone;
    const canvas = document.getElementById('donutCanvas');
    if (canvas && _donutGeom) {
      canvas.style.cursor = zone ? 'pointer' : '';
      _drawDonutSectors(canvas.getContext('2d'), _donutSectors, _donutGeom, calcStats(getFiltered()), zone);
    }
  }
});

// ── Donut click: open drawer per sector (or all from center) ──
document.addEventListener('click', e => {
  const canvas = e.target.closest('#donutCanvas');
  if (!canvas) return;
  const zone = _donutHitTest(e);
  if (!zone) return;
  const filtered = getFiltered();
  let trades, label;
  if (zone === 'center') {
    trades = filtered;
    label = 'All Trades';
  } else {
    // Each sector label maps directly to an outcome value
    trades = filtered.filter(t => t.outcome === zone);
    label = zone;
  }
  if (trades.length) openWidgetDrawer(label, `${trades.length} trade${trades.length > 1 ? 's' : ''}`, trades);
});

// ══════════════════════════════════════════════════════
// MONTHLY CANVAS
// ══════════════════════════════════════════════════════
function drawMonthly(trades) {
  const canvas = getByIdSafe('monthlyCanvas');
  const wrap = canvas?.parentElement;
  if (!canvas || !wrap) return;
  if (!trades.length) {
    renderCanvasEmptyState('.monthly-wrap', ['monthlyCanvas']);
    return;
  }
  clearCanvasEmptyState('.monthly-wrap');
  const rect = wrap.getBoundingClientRect();
  const W = rect.width  || wrap.offsetWidth  || 400;
  const H = rect.height || wrap.offsetHeight || 200;
  if (W < 10 || H < 10) return;

  // Position canvas to fill wrap exactly (same pattern as equity)
  canvas.style.width  = W + 'px';
  canvas.style.height = H + 'px';
  canvas.style.left   = '0px';
  canvas.style.top    = '0px';
  canvas.width  = Math.round(W * devicePixelRatio);
  canvas.height = Math.round(H * devicePixelRatio);
  const ctx = canvas.getContext?.('2d');
  if (!ctx) return;
  ctx.resetTransform();
  ctx.scale(devicePixelRatio,devicePixelRatio);
  ctx.clearRect(0,0,W,H);

  // Live theme colors
  const cG      = tc('--g');
  const cA      = tc('--gold') || tc('--a');
  const cR      = tc('--r');
  const cAccent = tc('--gold') || tc('--a');
  const cDim    = tc('--dim');

  // Monthly typography CSS vars — read via tc() so the auto typo-mode stack
  // scale applies to bar/label/grid sizes inside this widget render.
  const _cs = getComputedStyle(document.documentElement);
  const _fsBar     = tc('--fs-monthly-bar')     || '9px';
  const _fsLabel   = tc('--fs-monthly-label')   || '8.5px';
  const _fsGrid    = tc('--fs-monthly-grid')    || '8px';
  const _fsTip     = _cs.getPropertyValue('--fs-monthly-tooltip').trim() || '9px';

  const cBETP = tc('--oc-betp');
  const cBESL = tc('--oc-besl');

  // Tooltip element
  const tip = getByIdSafe('monthly-tooltip');

  if(!trades.length) {
    setVisible(tip, false);
    bindManagedEvent(canvas, '_managedMouseMove', 'mousemove', null);
    bindManagedEvent(canvas, '_managedMouseLeave', 'mouseleave', null);
    bindManagedEvent(canvas, '_managedClick', 'click', null);
    return;
  }

  // ── Build monthly stats ──
  const tpConfig = appState.ui.tpConfig;
  const monthly = {};
  trades.forEach(t => {
    if(!monthly[t.month]) monthly[t.month] = { r:0, n:0, tp:0, betp:0, sl:0, besl:0, wins:0, losses:0 };
    const d = monthly[t.month];
    const r = computeEffectiveRR(t, tpConfig);
    d.r += r; d.n++;
    if(t.outcome==='TP')    { d.tp   += r; d.wins++; }
    if(t.outcome==='BE-TP') { d.betp += r; d.wins++; }
    if(t.outcome==='SL')    { d.sl   += r; d.losses++; }
    if(t.outcome==='BE-SL') { d.besl += r; d.losses++; }
  });
  const months = Object.keys(monthly).sort();
  const N = months.length;
  if(!N) return;

  const maxN = Math.max(...months.map(m=>monthly[m].n));

  // Compute the avg label early and measure it so pad.l can fit it whatever the
  // current font size (themable) and value length. The label is split on two
  // lines ("avg" / value) to keep pad.l compact; we measure the wider of the
  // two parts. Right-anchored at pad.l - 4 → pad.l >= max(parts) + 4 + margin.
  const isVolume = appState.ui.monthlyMode === 'volume';
  const _avgVal = isVolume
    ? months.reduce((s,m)=>s+monthly[m].n,0) / N
    : months.reduce((s,m)=>s+monthly[m].r,0) / N;
  const _avgValStr = isVolume
    ? (_avgVal.toFixed(1)+' trades')
    : ((_avgVal>=0?'+':'')+_avgVal.toFixed(1)+'R');
  ctx.font = `${_fsGrid} DM Mono`;
  const _avgLblW = Math.ceil(Math.max(
    ctx.measureText('avg').width,
    ctx.measureText(_avgValStr).width
  ));
  const pad = {t:14, r:10, b:20, l: Math.max(42, _avgLblW + 8)};
  const cW = W - pad.l - pad.r;
  const cH = H - pad.t - pad.b;
  const xS = cW / N;
  const bw = Math.max(6, xS * 0.72);

  let allVals;
  if(appState.ui.monthlyMode === 'stacked') {
    allVals = months.flatMap(m => [monthly[m].tp+monthly[m].betp, monthly[m].sl+monthly[m].besl]);
  } else if(isVolume) {
    allVals = months.map(m => monthly[m].n);
  } else {
    allVals = months.map(m => monthly[m].r);
  }
  const valMn = Math.min(0, ...allVals);
  const valMx = Math.max(0, ...allVals);

  // Asymmetric Y scaling: give more canvas space to positive bars
  // Positive side gets 70% of height, negative gets 30% (capped)
  const posMax = Math.max(0, valMx) || 1;
  const negMax = Math.abs(Math.min(0, valMn)) || 0;
  const totalRange = posMax + negMax || 1;
  const posRatio = negMax > 0 ? Math.max(0.55, posMax / totalRange) : 1;
  const negRatio = 1 - posRatio;
  const cHpos = cH * posRatio;
  const cHneg = cH * negRatio;
  const y0 = pad.t + cHpos; // zero line position

  const toYz = v => {
    if (v >= 0) return y0 - (v / (posMax || 1)) * cHpos;
    return y0 + (Math.abs(v) / (negMax || 1)) * cHneg;
  };

  const range = Math.max(posMax, negMax) || 1;
  const toX  = i => pad.l + i*xS + xS/2;

  // ── Grid lines ──
  const gridVals = [];
  if (negMax > 0) gridVals.push(-negMax, -negMax*0.5);
  gridVals.push(0);
  if (posMax > 0) gridVals.push(posMax*0.5, posMax);
  ctx.setLineDash([3,4]);
  ctx.lineWidth = 0.5;
  gridVals.forEach(v => {
    const y = toYz(v);
    if(y < pad.t || y > H-pad.b) return;
    ctx.strokeStyle = v===0 ? tc('--line2') : tc('--line');
    ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(W-pad.r, y); ctx.stroke();
    ctx.fillStyle = cDim;
    ctx.font = `${_fsGrid} DM Mono`; ctx.textAlign = 'right';
    const gridLbl = isVolume ? Math.round(v).toString() : ((v>=0?'+':'')+v.toFixed(1));
    ctx.fillText(gridLbl, pad.l-4, y+3);
  });
  ctx.setLineDash([]);

  // ── Average monthly R / volume line ──
  const avgVal = isVolume
    ? months.reduce((s,m)=>s+monthly[m].n,0) / N
    : months.reduce((s,m)=>s+monthly[m].r,0) / N;
  const yAvg = toYz(avgVal);
  if(yAvg >= pad.t && yAvg <= H-pad.b) {
    ctx.setLineDash([5,5]);
    ctx.strokeStyle = tc('--line2');
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(pad.l, yAvg); ctx.lineTo(W-pad.r, yAvg); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = cDim;
    ctx.font = `${_fsGrid} DM Mono`; ctx.textAlign = 'center';
    // Split label on two lines ("avg" above, value below the dashed line) so
    // pad.l stays compact. Both lines centered on the same x so the shorter
    // ("avg") sits centered above the longer (value). Reuses _avgLblW + _avgValStr.
    const _avgLblCenterX = pad.l - 4 - _avgLblW / 2;
    ctx.fillText('avg', _avgLblCenterX, yAvg - 2);
    ctx.fillText(_avgValStr, _avgLblCenterX, yAvg + 9);
  }

  // ── Draw bars ──
  months.forEach((m, i) => {
    const d = monthly[m];
    const x = toX(i);
    const nAlpha = 0.45 + 0.55 * (d.n / maxN);

    if(isVolume) {
      // Volume: stack losses (red) over wins (green), positive axis only
      const wins = d.wins, losses = d.losses;
      if(wins > 0) {
        const yTop = toYz(wins); const yBot = y0;
        ctx.globalAlpha = nAlpha;
        ctx.fillStyle = cG;
        ctx.fillRect(x-bw/2, yTop, bw, Math.abs(yBot-yTop) || 1);
        ctx.globalAlpha = 1;
      }
      if(losses > 0) {
        const yTop = toYz(wins + losses); const yBot = toYz(wins);
        ctx.globalAlpha = nAlpha;
        ctx.fillStyle = cR;
        ctx.fillRect(x-bw/2, yTop, bw, Math.abs(yBot-yTop) || 1);
        ctx.globalAlpha = 1;
      }
    } else if(appState.ui.monthlyMode === 'stacked') {
      const posTotal = d.tp + d.betp;
      const negTotal = d.sl + d.besl;

      if(d.tp > 0) {
        const yTop = toYz(posTotal); const yBot = toYz(d.betp > 0 ? d.betp : 0);
        ctx.globalAlpha = nAlpha;
        ctx.fillStyle = cG;
        ctx.fillRect(x-bw/2, yTop, bw, Math.abs(yBot-yTop) || 1);
        ctx.globalAlpha = 1;
      }
      if(d.betp > 0) {
        const yTop = toYz(d.betp); const yBot = y0;
        ctx.globalAlpha = nAlpha;
        ctx.fillStyle = cBETP;
        ctx.fillRect(x-bw/2, yTop, bw, Math.abs(yBot-yTop) || 1);
        ctx.globalAlpha = 1;
      }
      if(negTotal < 0) {
        if(d.besl < 0) {
          const yTop = y0; const yBot = toYz(d.besl);
          ctx.globalAlpha = nAlpha * 0.7;
          ctx.fillStyle = cBESL;
          ctx.fillRect(x-bw/2, yTop, bw, Math.abs(yBot-yTop) || 1);
          ctx.globalAlpha = 1;
        }
        if(d.sl < 0) {
          const yTop = toYz(d.besl); const yBot = toYz(negTotal);
          ctx.globalAlpha = nAlpha;
          ctx.fillStyle = cR;
          ctx.fillRect(x-bw/2, yTop, bw, Math.abs(yBot-yTop) || 1);
          ctx.globalAlpha = 1;
        }
      }
    } else {
      const v = d.r;
      const yTop = v>=0 ? toYz(v) : y0;
      const yBot = v>=0 ? y0 : toYz(v);
      ctx.globalAlpha = nAlpha;
      ctx.fillStyle = v >= 0 ? cG : cR;
      ctx.fillRect(x-bw/2, yTop, bw, Math.abs(yBot-yTop) || 1);
      ctx.globalAlpha = 1;
    }

    // Top value label
    if(isVolume) {
      const barH = Math.abs(toYz(d.n) - y0);
      if(barH > 10 && N <= 24) {
        ctx.fillStyle = tcRgba('--a', 0.9);
        ctx.font = `bold ${_fsBar} DM Mono`; ctx.textAlign = 'center';
        ctx.fillText(String(d.n), x, toYz(d.n) - 3);
      }
    } else if (appState.ui.monthlyMode === 'stacked') {
      // Stacked mode: label each signed portion at its own edge so positive
      // and negative labels don't collide at the zero line.
      const posTotal = d.tp + d.betp;
      const negTotal = d.sl + d.besl; // negative number
      ctx.font = `bold ${_fsBar} DM Mono`;
      ctx.textAlign = 'center';
      if (N <= 24 && posTotal > 0) {
        const barH = Math.abs(toYz(posTotal) - y0);
        if (barH > 10) {
          ctx.fillStyle = tcRgba('--g', 0.85);
          ctx.fillText('+' + posTotal.toFixed(1) + 'R', x, toYz(posTotal) - 3);
        }
      }
      if (N <= 24 && negTotal < 0) {
        const barH = Math.abs(toYz(negTotal) - y0);
        if (barH > 10) {
          ctx.fillStyle = tcRgba('--r', 0.85);
          ctx.fillText('−' + Math.abs(negTotal).toFixed(1) + 'R', x, toYz(negTotal) + 10);
        }
      }
    } else {
      const barH = Math.abs(toYz(monthly[m].r) - y0);
      if(barH > 10 && N <= 24) {
        ctx.fillStyle = monthly[m].r >= 0 ? tcRgba('--g', 0.85) : tcRgba('--r', 0.85);
        ctx.font = `bold ${_fsBar} DM Mono`; ctx.textAlign = 'center';
        const labelY = monthly[m].r >= 0 ? toYz(monthly[m].r) - 3 : toYz(monthly[m].r) + 10;
        ctx.fillText((monthly[m].r>=0?'+':'−')+Math.abs(monthly[m].r).toFixed(1) + 'R', x, labelY);
      }
    }
  });

  // ── Selected-bar gold border (hover mode) ──
  if (appState.ui.monthlySelectedMonth !== null) {
    const si = months.indexOf(appState.ui.monthlySelectedMonth);
    if (si >= 0) {
      const sx = toX(si);
      const d  = monthly[appState.ui.monthlySelectedMonth];
      const posTotal = isVolume
        ? d.n
        : (appState.ui.monthlyMode === 'stacked' ? d.tp + d.betp : d.r);
      const negTotal = isVolume
        ? 0
        : (appState.ui.monthlyMode === 'stacked' ? d.sl + d.besl : 0);
      const yTop = posTotal > 0 ? toYz(posTotal) : (negTotal < 0 ? y0 : y0 - 1);
      const yBot = negTotal < 0 ? toYz(negTotal) : (posTotal > 0 ? y0 : y0 + 1);
      const rH   = Math.abs(yBot - yTop) || 2;
      ctx.strokeStyle = cA;
      ctx.lineWidth   = 2;
      ctx.strokeRect(sx - bw / 2 - 1, yTop - 1, bw + 2, rH + 2);
    }
  }

  // ── 3-month rolling average line (only when mode includes rolling) ──
  if(N >= 3 && (_monthlyCurve === 'rolling' || _monthlyCurve === 'both')) {
    const rollField = isVolume ? 'n' : 'r';
    ctx.beginPath();
    ctx.strokeStyle = cAccent;
    ctx.lineWidth = 1.8;
    ctx.setLineDash([]);
    let started = false;
    const rollPoints = [];
    for(let i = 2; i < N; i++) {
      const rollV = (monthly[months[i]][rollField] + monthly[months[i-1]][rollField] + monthly[months[i-2]][rollField]) / 3;
      const x = toX(i); const y = toYz(rollV);
      rollPoints.push({ x, y, v: rollV });
      if(!started) { ctx.moveTo(x, y); started=true; } else { ctx.lineTo(x, y); }
    }
    ctx.stroke();
    for (const p of rollPoints) {
      ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI*2);
      ctx.fillStyle = cAccent; ctx.fill();
    }

    // Per-point value labels — displayed above each point, collision-skip
    // logic thins them out on dense charts so neighbouring labels don't
    // overlap. Format mirrors the y-axis convention (volume: integer count,
    // R mode: signed R with tabular one decimal).
    if (N <= 36) {
      ctx.font = `bold ${_fsBar} DM Mono`;
      ctx.textAlign = 'center';
      ctx.fillStyle = cAccent;
      const minGap = isVolume ? 14 : 18;
      let lastDrawnX = -Infinity;
      for (const p of rollPoints) {
        if (p.x - lastDrawnX < minGap) continue;
        const text = isVolume
          ? p.v.toFixed(1)
          : (p.v >= 0 ? '+' : '−') + Math.abs(p.v).toFixed(2) + 'R';
        ctx.fillText(text, p.x, p.y - 7);
        lastDrawnX = p.x;
      }
    }
  }

  // ── Secondary curve: cumulative R (or trade count) ──
  // (rolling avg already drawn above when _monthlyCurve includes it)
  if (_monthlyCurve === 'cumul' || _monthlyCurve === 'both') {
    // Build cumulative series (count in volume mode, else R)
    const cumulField = isVolume ? 'n' : 'r';
    const cumulSeries = [];
    let cumEq = 0;
    months.forEach(m => { cumEq += monthly[m][cumulField]; cumulSeries.push(cumEq); });

    // Map onto canvas height independently (full height, own min/max)
    const cMin = Math.min(0, ...cumulSeries);
    const cMax = Math.max(0, ...cumulSeries);
    const cRange = (cMax - cMin) || 1;
    // Map to full canvas height (pad.t → H - pad.b)
    const toYc = v => pad.t + cH - ((v - cMin) / cRange) * cH;

    // Draw cumulative line — dashed teal
    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = tc('--t');
    ctx.lineWidth = 2;
    ctx.setLineDash([6, 3]);
    cumulSeries.forEach((v, i) => {
      i === 0 ? ctx.moveTo(toX(i), toYc(v)) : ctx.lineTo(toX(i), toYc(v));
    });
    ctx.stroke();
    ctx.setLineDash([]);

    // Fill under curve (subtle)
    ctx.beginPath();
    ctx.moveTo(toX(0), toYc(cumulSeries[0]));
    cumulSeries.forEach((v, i) => ctx.lineTo(toX(i), toYc(v)));
    ctx.lineTo(toX(N - 1), H - pad.b);
    ctx.lineTo(toX(0), H - pad.b);
    ctx.closePath();
    ctx.fillStyle = tc('--t') + '22';
    ctx.fill();

    // Dots
    cumulSeries.forEach((v, i) => {
      ctx.beginPath(); ctx.arc(toX(i), toYc(v), 3, 0, Math.PI * 2);
      ctx.fillStyle = tc('--t'); ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.3)'; ctx.lineWidth = 1; ctx.stroke();
    });

    // Per-point value labels — mirrors the 3M-avg path. Collision-skip so
    // adjacent dots don't overlap. Skipped on very dense series (N > 36)
    // where right-axis labels + end label carry the reading.
    if (N <= 36) {
      ctx.font = `bold ${_fsBar} DM Mono`;
      ctx.textAlign = 'center';
      ctx.fillStyle = tc('--t');
      const minGap = isVolume ? 14 : 22;
      let lastDrawnX = -Infinity;
      cumulSeries.forEach((v, i) => {
        const px = toX(i);
        if (px - lastDrawnX < minGap) return;
        const text = isVolume
          ? Math.round(v).toString()
          : (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(1) + 'R';
        ctx.fillText(text, px, toYc(v) - 7);
        lastDrawnX = px;
      });
    }

    ctx.restore();
  }


  // ── X-axis labels ──
  ctx.fillStyle = cDim;
  ctx.font = `${_fsLabel} DM Mono`; ctx.textAlign = 'center';
  months.forEach((m,i) => {
    if(N <= 24 || i%2===0) ctx.fillText(m.slice(2), toX(i), H-pad.b+12);
  });

  // ── Tooltip interaction ──
  const mStats = months.map(m => {
    const d = monthly[m];
    const wins = d.wins, losses = d.losses, n = d.n;
    const wr = n > 0 ? (wins/n*100) : 0;
    const ev = n > 0 ? d.r/n : 0;
    const grossW = d.tp + d.betp;
    const grossL = Math.abs(d.sl + d.besl);
    const pf = grossL > 0 ? grossW/grossL : 9.99;
    const mTrades = trades.filter(t=>t.month===m);
    let maxL=0, cur=0, curR=0, maxLossR=0;
    // BE neutres are transparent — they neither extend nor break a loss run.
    mTrades.forEach(t=>{
      if (isLoser(t)) { cur++; curR += computeEffectiveRR(t, tpConfig); if (cur > maxL) maxL = cur; if (curR < maxLossR) maxLossR = curR; }
      else if (!isBE(t)) { cur = 0; curR = 0; }
    });
    return { m, n, wins, losses, wr, ev, r:d.r, pf, maxL, maxLossR };
  });

  bindManagedEvent(canvas, '_managedMouseMove', 'mousemove', function(e) {
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    let hit = -1;
    for(let i=0;i<N;i++) {
      const x = toX(i);
      if(Math.abs(mx-x) <= bw/2+2) { hit=i; break; }
    }
    if(hit < 0) { setVisible(tip, false); canvas.style.cursor='default'; return; }
    canvas.style.cursor = 'pointer';
    const s = mStats[hit];
    const rColor  = s.r  >= 0 ? tc('--g') : tc('--r');
    const evColor = _kpiTooltipColor(s.ev, 'avgr');
    const wrColor = _kpiTooltipColor(s.wr, 'wr');
    const accCol  = tc('--gold') || tc('--a');
    tip.innerHTML = `
      <div class="mtt-month">${s.m}</div>
      <div class="mtt-row"><span class="mtt-k">Trades</span><span class="mtt-v mtt-v-white">${s.n}</span></div>
      <div class="mtt-row"><span class="mtt-k">Win Rate</span><span class="mtt-v" style="color:${wrColor}">${s.wr.toFixed(1)}%</span></div>
      <div class="mtt-row"><span class="mtt-k">Expectancy</span><span class="mtt-v" style="color:${evColor}">${s.ev>=0?'+':''}${s.ev.toFixed(3)}R</span></div>
      <div class="mtt-row"><span class="mtt-k">Total R</span><span class="mtt-v" style="color:${rColor}">${s.r>=0?'+':''}${s.r.toFixed(2)}R</span></div>
      <div class="mtt-row"><span class="mtt-k">Prof. Factor</span><span class="mtt-v" style="color:${accCol}">${s.pf>=9.99?'∞':s.pf.toFixed(2)}</span></div>
      <div class="mtt-row"><span class="mtt-k">Max L-Streak</span><span class="mtt-v mtt-v-neg">${s.maxL}${s.maxLossR < 0 ? ' / '+s.maxLossR.toFixed(1)+'R' : ''}</span></div>
    `;
    setVisible(tip, true);
    const tipW = 170, tipH = 150;
    let tx = toX(hit) + bw/2 + 8;
    let ty = Math.min(my - 10, H - tipH);
    if(tx + tipW > W) tx = toX(hit) - bw/2 - tipW - 8;
    if(ty < 0) ty = 4;
    tip.style.left = tx+'px';
    tip.style.top  = ty+'px';
  });
  bindManagedEvent(canvas, '_managedMouseLeave', 'mouseleave', function() { setVisible(tip, false); canvas.style.cursor='default'; });

  // ── Click: open shared drawer for the clicked month ──
  bindManagedEvent(canvas, '_managedClick', 'click', function(e) {
    const rect = canvas.getBoundingClientRect();
    const mx   = e.clientX - rect.left;
    for (let i = 0; i < N; i++) {
      if (Math.abs(mx - toX(i)) <= bw / 2 + 2) {
        const month = months[i];
        const monthTrades = trades.filter(t => t.month === month);
        if (!monthTrades.length) return;
        const s = mStats[i];
        appState.ui.monthlySelectedMonth = month;
        drawMonthly(trades);
        openWidgetDrawer(month, `${s.n} trade${s.n>1?'s':''} · ${s.wins}W ${s.losses}L`, monthTrades);
        return;
      }
    }
  });
}

// ══════════════════════════════════════════════════════
// HEATMAP: SESSION × DAY
// ══════════════════════════════════════════════════════
function _heatmapAxisKind(key = '') {
  const norm = String(key || '').trim().toLowerCase();
  if (['session', 'sessionutc', 'sessionformule'].includes(norm)) return 'session';
  if (['day', 'jour', 'jourformule'].includes(norm)) return 'day';
  if (norm === 'pair') return 'pair';
  return norm;
}

function _orderHeatmapAxisValues(values, axisKey = '') {
  const kind = _heatmapAxisKind(axisKey);
  const list = [...new Set((values || []).filter(Boolean))];
  if (kind === 'session') {
    return SESSION_ORDER.filter(v => list.includes(v))
      .concat(list.filter(v => !SESSION_ORDER.includes(v)).sort());
  }
  if (kind === 'day') {
    return DAY_ORDER.filter(v => list.includes(v))
      .concat(list.filter(v => !DAY_ORDER.includes(v)).sort());
  }
  // Default: numeric ascending when every value is numeric ("2" before "10"),
  // alphabetical otherwise. Custom heatmaps with numeric axes (e.g. Hour, RR
  // Max) ended up lexicographically sorted before this branch.
  const allNumeric = list.length > 0 && list.every(v => v !== '' && Number.isFinite(Number(v)));
  return allNumeric
    ? list.sort((a, b) => Number(a) - Number(b))
    : list.sort();
}

function _formatHeatmapAxisLabel(value, axisKey = '', short = false) {
  const kind = _heatmapAxisKind(axisKey);
  if (kind === 'session') return (short ? SESSION_SHORT[value] : null) || value;
  if (kind === 'day') return (short ? DAY_EN[value] : DAY_FULL[value]) || value;
  return value;
}

function _renderSharedHeatmapGrid({
  container,
  containerId = '',
  trades = [],
  rowKey = '',
  colKey = '',
  metric = 'ev',
  threshold = 0,
  hardMode = false,
  getRowValues,
  getColValues,
  getRowLabel,
  getColLabel,
  getCellTitle,
  getCellTrades,
  onCellContextMenu,
  rowLabelWidth = 72,
}) {
  if (!container) return;
  if (!trades.length) {
    if (containerId) renderWidgetEmptyState(containerId);
    else container.innerHTML = '';
    return;
  }

  const rowSet = new Set();
  const colSet = new Set();
  const data = {};
  const tpConfig = appState.ui.tpConfig;
  const useTotal = barMode === 'total';

  trades.forEach(t => {
    const rows = (getRowValues ? getRowValues(t) : []).filter(Boolean);
    const cols = (getColValues ? getColValues(t) : []).filter(Boolean);
    if (!rows.length || !cols.length) return;
    const r = computeEffectiveRR(t, tpConfig);
    rows.forEach(rowVal => {
      rowSet.add(rowVal);
      cols.forEach(colVal => {
        colSet.add(colVal);
        const k = `${rowVal}|${colVal}`;
        if (!data[k]) data[k] = { r: 0, n: 0, wins: 0, tpR: 0, slR: 0, betpR: 0, beslR: 0 };
        data[k].r += r;
        data[k].n++;
        if (isWinner(t, tpConfig)) data[k].wins++;
        if (t.outcome === 'TP') data[k].tpR += r;
        else if (t.outcome === 'SL') data[k].slR += r;
        else if (t.outcome === 'BE-TP') data[k].betpR += r;
        else if (t.outcome === 'BE-SL') data[k].beslR += r;
      });
    });
  });

  const rows = _orderHeatmapAxisValues([...rowSet], rowKey);
  const cols = _orderHeatmapAxisValues([...colSet], colKey);
  if (!rows.length || !cols.length) {
    if (containerId) renderWidgetEmptyState(containerId);
    else container.innerHTML = '';
    return;
  }

  const valFn = v => metric === 'ev' ? (useTotal ? v.r : v.r / v.n)
    : metric === 'wr' ? v.wins / v.n * 100
    : v.n;
  const fmtFn = v => metric === 'ev' ? (v >= 0 ? '+' : '') + v.toFixed(useTotal ? 1 : 2) + 'R'
    : metric === 'wr' ? v.toFixed(0) + '%'
    : String(v);

  let mn = Infinity, mx = -Infinity;
  rows.forEach(rowVal => cols.forEach(colVal => {
    const v = data[`${rowVal}|${colVal}`];
    if (v && v.n >= 2) {
      const val = valFn(v);
      mn = Math.min(mn, val);
      mx = Math.max(mx, val);
    }
  }));
  if (mn === Infinity) { mn = 0; mx = 1; }
  const range = Math.max(mx, Math.abs(mn)) || 1;

  const GAP = 3;
  const PAD = 4;
  const availH = container.clientHeight || 200;
  const nRows = rows.length + 1;
  const rawCellH = Math.floor((availH - GAP * (nRows - 1) - PAD * 2) / nRows);
  const cellH = Math.max(rawCellH, 22);
  const headerH = Math.max(Math.floor(cellH * 0.7), 18);
  const fontSize = Math.max(7, Math.min(12, Math.floor(cellH * 0.32)));
  const lblFontSz = Math.max(8, Math.min(12, Math.floor(cellH * 0.32)));
  const rowLabels = rows.map(rowVal => String(getRowLabel ? getRowLabel(rowVal) : rowVal || ''));
  const colLabels = cols.map(colVal => String(getColLabel ? getColLabel(colVal) : colVal || ''));
  const longestRowLabelLen = rowLabels.reduce((max, label) => Math.max(max, label.length), 0);
  const estimatedRowLabelWidth = Math.ceil(longestRowLabelLen * lblFontSz * 0.62) + 18;
  const resolvedRowLabelWidth = Math.max(
    rowLabelWidth,
    Math.min(Math.max(estimatedRowLabelWidth, 120), 280)
  );

  const toRgbStr = h => {
    const r = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h);
    return r ? `${parseInt(r[1], 16)},${parseInt(r[2], 16)},${parseInt(r[3], 16)}` : '180,180,180';
  };
  const cG = tc('--g');
  const cR = tc('--r');
  const cBg1 = tc('--bg1');

  container.classList.add('heatmap-grid');
  container.style.cssText = `
    display:grid;
    grid-template-columns:minmax(${rowLabelWidth}px, ${resolvedRowLabelWidth}px) repeat(${cols.length}, minmax(${Math.max(cellH, 42)}px, 1fr));
    grid-template-rows:minmax(${headerH}px, auto) repeat(${rows.length}, minmax(${cellH}px, auto));
    gap:${GAP}px;padding:${PAD}px;
    height:100%;overflow:auto;min-width:0;box-sizing:border-box;
  `;
  container.innerHTML = '';

  container.appendChild(document.createElement('div'));

  cols.forEach((colVal, idx) => {
    const el = document.createElement('div');
    el.style.cssText = `display:flex;align-items:flex-end;justify-content:center;font-family:'DM Mono',monospace;font-size:${lblFontSz}px;color:var(--dim);padding:0 2px 3px;white-space:normal;overflow:visible;text-overflow:clip;overflow-wrap:anywhere;word-break:break-word;line-height:1.2;text-align:center;min-width:${Math.max(cellH, 42)}px`;
    el.textContent = colLabels[idx];
    container.appendChild(el);
  });

  rows.forEach((rowVal, idx) => {
    const rowLabel = document.createElement('div');
    rowLabel.style.cssText = `display:flex;align-items:center;justify-content:flex-end;font-family:'DM Mono',monospace;font-size:${lblFontSz}px;font-weight:600;color:var(--body);padding-right:6px;white-space:normal;overflow:visible;text-overflow:clip;overflow-wrap:anywhere;word-break:break-word;line-height:1.2;text-align:right;min-height:${cellH}px`;
    rowLabel.textContent = rowLabels[idx];
    container.appendChild(rowLabel);

    cols.forEach(colVal => {
      const v = data[`${rowVal}|${colVal}`];
      const cell = document.createElement('div');
      cell.style.cssText = `border-radius:3px;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:'DM Mono',monospace;font-size:${fontSize}px;font-weight:600;cursor:default;overflow:hidden;line-height:1.2;min-height:${cellH}px`;
      cell.classList.add('hm-cell');

      if (threshold > 0 && v && v.n < threshold) cell.classList.add('cell-low-n');

      if (v && v.n >= 2) {
        const val = valFn(v);
        let alpha, pos;
        if (metric === 'wr') {
          if (!hardMode) {
            pos = true;
            const span = (mx - mn) || 1;
            alpha = Math.min(((val - mn) / span) * 0.75 + 0.18, 0.95);
          } else {
            const WR_MID = 40;
            pos = val >= WR_MID;
            const dev = val - WR_MID;
            const maxDev = pos ? (100 - WR_MID) : WR_MID;
            alpha = pos ? Math.min(Math.abs(dev / (maxDev || 1)) * 0.85 + 0.30, 0.95) : 0.30;
          }
        } else {
          pos = metric === 'n' ? true : val >= 0;
          alpha = Math.min(Math.abs(val / range) * (pos ? 0.85 : 0.65) + 0.25, 0.95);
        }
        const hexCol = pos ? cG : cR;
        cell.style.background = `rgba(${toRgbStr(hexCol)},${alpha})`;
        cell.style.color = alpha > 0.55 ? cBg1 : (pos ? cG : cR);
        cell.textContent = fmtFn(val);

        const avgR = v.r / v.n;
        const wrPct = (v.wins / v.n * 100).toFixed(0);
        const netTP = v.tpR + v.betpR;
        const netSL = v.slR + v.beslR;
        const title = getCellTitle ? getCellTitle(rowVal, colVal) : `${rowVal} × ${colVal}`;
        const netRows = `<span class="utip-label">Net TP</span><span></span><span class="utip-value utip-value-pos utip-align-right">${netTP >= 0 ? '+' : ''}${netTP.toFixed(1)}R</span>
             <span class="utip-label">Net SL</span><span></span><span class="utip-value utip-value-neg utip-align-right">${netSL.toFixed(1)}R</span>`;
        const valueColorAttr = metric === 'wr'
          ? ` style="color:${_kpiTooltipColor(val, 'wr')}"`
          : (metric === 'ev' && !useTotal)
            ? ` style="color:${_kpiTooltipColor(val, 'avgr')}"`
            : '';
        const valueClass = (metric === 'wr' || (metric === 'ev' && !useTotal))
          ? _utipNeutralClass()
          : _utipValueClass(pos);
        const tipHtml = `<div class="utip-header">${_escapeHtml(title)}</div>
          <div class="utip-grid">
            <span class="utip-label">Value</span><span></span><span class="${valueClass}"${valueColorAttr}>${fmtFn(val)}</span>
            <span class="utip-label">Trades</span><span></span><span class="${_utipNeutralClass()}">×${v.n}</span>
            <span class="utip-label">Win Rate</span><span></span><span class="${_utipNeutralClass()}" style="color:${_kpiTooltipColor(+wrPct, 'wr')}">${wrPct}%</span>
            <span class="utip-label">Avg R</span><span></span><span class="${_utipNeutralClass()}" style="color:${_kpiTooltipColor(avgR, 'avgr')}">${(avgR >= 0 ? '+' : '') + avgR.toFixed(3)}R</span>
            <span class="utip-label">Total R</span><span></span><span class="${_utipNeutralClass()}">${(v.r >= 0 ? '+' : '') + v.r.toFixed(1)}R</span>
            ${netRows}
          </div>`;
        bindManagedEvent(cell, '_managedMouseEnter', 'mouseenter', e => showUtip(e, tipHtml));
        bindManagedEvent(cell, '_managedMouseMove', 'mousemove', e => _posUtip(e.clientX, e.clientY));
        bindManagedEvent(cell, '_managedMouseLeave', 'mouseleave', hideUtip);
        cell.style.cursor = 'pointer';
        bindManagedEvent(cell, '_managedClick', 'click', () => {
          const cellTrades = getCellTrades ? getCellTrades(rowVal, colVal) : [];
          if (!cellTrades.length) return;
          document.querySelectorAll(`#${CSS.escape(container.id)} .wd-cell-active`).forEach(el => el.classList.remove('wd-cell-active'));
          cell.classList.add('wd-cell-active');
          openWidgetDrawer(title, `${v.n} trades`, cellTrades);
        });
        if (typeof onCellContextMenu === 'function') {
          bindManagedEvent(cell, '_managedCtxMenu', 'contextmenu', e => {
            e.preventDefault();
            onCellContextMenu(e, rowVal, colVal, title);
          });
        }
      } else {
        cell.style.background = 'var(--bg3)';
        cell.textContent = '—';
        cell.style.color = 'var(--mute)';
        const emptyTip = v ? `n=${v.n} (low confidence)` : 'No data';
        bindManagedEvent(cell, '_managedMouseEnter', 'mouseenter', e => showUtipText(e, emptyTip));
        bindManagedEvent(cell, '_managedMouseMove', 'mousemove', e => _posUtip(e.clientX, e.clientY));
        bindManagedEvent(cell, '_managedMouseLeave', 'mouseleave', hideUtip);
      }
      container.appendChild(cell);
    });
  });
}

function renderHeatmap(trades) {
  const container = document.getElementById('heatmap-container');
  if (!container) return;
  const metric = barMode === 'wr' ? 'wr' : barMode === 'n' ? 'n' : _sdMetric;
  _renderSharedHeatmapGrid({
    container,
    containerId: 'heatmap-container',
    trades,
    rowKey: 'session',
    colKey: 'day',
    metric,
    threshold: _heatmapThreshold,
    hardMode: _hmHardMode,
    getRowValues: t => [(t.sessionUtc || t.session || '')].filter(Boolean),
    getColValues: t => [t.day].filter(Boolean),
    getRowLabel: v => _formatHeatmapAxisLabel(v, 'session', true),
    getColLabel: v => _formatHeatmapAxisLabel(v, 'day', true),
    getCellTitle: (rowVal, colVal) => `${_formatHeatmapAxisLabel(rowVal, 'session', true)} × ${_formatHeatmapAxisLabel(colVal, 'day', true)}`,
    getCellTrades: (rowVal, colVal) => trades.filter(t => (t.sessionUtc || t.session) === rowVal && t.day === colVal),
    onCellContextMenu: (e, rowVal, colVal, title) => _showCellComboContextMenu('sessionDay', `${rowVal}|${colVal}`, title, e),
    rowLabelWidth: 72,
  });
}

// ══════════════════════════════════════════════════════
