// CSV DRAG & DROP IMPORT
// ══════════════════════════════════════════════════════
let csvDataActive = false;
let _cachedCSVTrades = null;   // last imported CSV trades, for re-injection on source switch

// ── Raw CSV state (enables column remapping for widgets) ──
let _lastCsvRawText  = null;   // raw CSV text of last import (used by remap re-parse)
let _lastCsvFilename = '';
let _lastCsvHeaders  = [];     // column headers of last imported CSV
let _lastCsvRows     = [];     // raw rows as {header: value} objects, for auto-detect column scan
// _csvColumnOverrides: { session: 'Ma Session', day: 'Jour', obstacles: 'Obs', h4: 'H4 Obs', setup: 'Continu', hour: 'Heure' }
let _csvColumnOverrides = {};
const CSV_OVR_KEY = 'fr_csv_col_overrides_v1';
function _loadCsvOverrides() {
  try {
    const raw = localStorage.getItem(CSV_OVR_KEY);
    _csvColumnOverrides = raw ? (JSON.parse(raw) || {}) : {};
  } catch (e) { _csvColumnOverrides = {}; }
  return _csvColumnOverrides;
}
function _saveCsvOverrides() {
  try { localStorage.setItem(CSV_OVR_KEY, JSON.stringify(_csvColumnOverrides || {})); }
  catch (e) {}
}
_loadCsvOverrides();

const NO_MAPPING_VALUE = '__NO_MAPPING__';
function _isNoMappingValue(value) {
  return value === NO_MAPPING_VALUE;
}

function _isH4ApiMode() {
  return localStorage.getItem(DS_KEY) === 'api' && _getCurrentHTFSource() === 'h4';
}

function _isDimDefaultNoMappedInCurrentContext(dimKey) {
  if (!_isH4ApiMode()) return false;
  return dimKey === 'obstacles' || dimKey === 'img_m15';
}

function _getEffectiveApiOverride(dimKey, source = null) {
  const overrides = _getAPIFieldOverrides(source);
  const explicit = overrides[dimKey];
  if (_isNoMappingValue(explicit)) return NO_MAPPING_VALUE;
  if (explicit) return explicit;
  if ((source || _getCurrentHTFSource()) === 'h4' && (dimKey === 'obstacles' || dimKey === 'img_m15')) {
    return NO_MAPPING_VALUE;
  }
  return '';
}

// ── Column lookup honoring user remap overrides ──
function _colForDim(headers, dimKey, ...defaults) {
  const override = _csvColumnOverrides && _csvColumnOverrides[dimKey];
  if (_isNoMappingValue(override)) return -1;
  if (override != null && override !== '') {
    const i = _colFirst(headers, override);
    if (i >= 0) return i;
  }
  if (defaults.length === 1) return _colFirst(headers, defaults[0]);
  return _colAny(headers, ...defaults);
}
function _hourColForDim(headers) {
  const override = _csvColumnOverrides && _csvColumnOverrides.hour;
  if (_isNoMappingValue(override)) return -1;
  if (override != null && override !== '') {
    const i = _colFirst(headers, override);
    if (i >= 0) return i;
  }
  return _findHourColumnIndex(headers);
}

