// CSV IMPORT — FULL REWRITE
// ══════════════════════════════════════════════════════

// ── Required columns (at least one alias must be present) ──
function openCsvOverlay() {
  const overlay = document.getElementById('csv-overlay');
  if (!overlay) return;
  // Idempotent: if already active, just focus the file input — don't re-stack.
  if (overlay.classList.contains('active')) {
    document.getElementById('csv-file-input')?.focus();
    return;
  }
  overlay.classList.add('active');
  _setText('csv-status', '');
  document.getElementById('csv-status')?.setAttribute('class', 'csv-status');
}
function closeCsvOverlay() {
  document.getElementById('csv-overlay')?.classList.remove('active');
  document.querySelectorAll('.csv-drop-box').forEach(b => b.classList.remove('dragover-box'));
}

// Drag events
document.addEventListener('DOMContentLoaded', () => {
  _SW.init();
  _handleNotionOAuthReturn();
  /* Silent cleanup of retired Partials Planner localStorage keys. */
  try {
    localStorage.removeItem('pp-custom-presets');
    localStorage.removeItem('pp-section-layout-v3');
  } catch (e) {}
  /* ── TP Management panel init (Phase 2.A) ── */
  _initTpmPanelListeners();
  _syncTpmRadios();
  _updateTpmBadge();
  _renderTpmModeBody();
  /* Element-anchored info tooltips (Partial Optimizer + Optimal RR header `?`).
     Switched to position:fixed to escape .chart-card overflow:hidden clipping. */
  try { _initInfoPopPositioners(); } catch (e) { console.warn('[infoPop] init failed:', e.message); }
  // Phase 3.A.final: first render of the Feature Requirements block. Subsequent
  // refreshes happen inside updateAttentionButton on every dashboard render.
  try { renderFeatureRequirementsBlock(); } catch (e) {}

  /* ── Sidebar collapse toggle ── */
  {
    const layout = document.querySelector('.layout');
    const toggle = document.getElementById('sidebar-toggle');
    const STORAGE_KEY = 'sidebarCollapsed';
    const sidebarW = () => getComputedStyle(document.documentElement).getPropertyValue('--sidebar-w').trim();
    let _sidebarToggleEndTimer = null;

    const positionToggle = (collapsed) => {
      toggle.style.left = collapsed ? '0px' : sidebarW();
    };

    const set = (collapsed) => {
      // Suspend the grid ResizeObserver work during the 300ms CSS transition
      // on .layout grid-template-columns. Without this, RO fires once per
      // animation frame × ~30 widgets, each call running _applyAutoTypoScale
      // synchronously — that's the visible freeze. We do ONE final
      // _applyAutoTypoScale + _redrawAll after the transition settles.
      _isSidebarToggling = true;
      if (_sidebarToggleEndTimer) clearTimeout(_sidebarToggleEndTimer);
      layout.classList.toggle('sidebar-collapsed', collapsed);
      positionToggle(collapsed);
      try { localStorage.setItem(STORAGE_KEY, collapsed ? '1' : '0'); } catch {}
      // 350ms = 300ms transition + 50ms buffer. Re-clicking inside the window
      // resets the timer so the final redraw runs after the last click.
      _sidebarToggleEndTimer = setTimeout(() => {
        _isSidebarToggling = false;
        _sidebarToggleEndTimer = null;
        if (typeof _applyAutoTypoScale === 'function') _applyAutoTypoScale();
        if (typeof _redrawAll === 'function') _redrawAll();
      }, 350);
    };

    toggle.addEventListener('click', () => set(!layout.classList.contains('sidebar-collapsed')));

    // restore persisted state
    try { if (localStorage.getItem(STORAGE_KEY) === '1') set(true); else positionToggle(false); } catch { positionToggle(false); }

    // reposition on resize (sidebar-w changes per breakpoint)
    window.addEventListener('resize', () => {
      if (!layout.classList.contains('sidebar-collapsed')) positionToggle(false);
    });
  }

  buildTypographyControls();
  _syncGhostUI();

  // Sidebar filter-group display order — apply saved order to the static
  // native filter-groups (customs are already rendered in order by
  // renderCustomFilterChips), then wire up the drag-to-reorder Sortables.
  // Sortables start disabled; toggleEditMode enables them.
  try { _applyNativeFilterOrder(); } catch (e) {}
  try { _initFilterSortables(); } catch (e) {}
  try { _initPresetSortable(); } catch (e) {}
  try { _installContextStripObserver(); } catch (e) {}
  // Sync heatmap threshold buttons with persisted values
  document.querySelectorAll('#sd-threshold-btns .cc-tab').forEach(b => {
    b.classList.toggle('active', parseInt(b.dataset.threshold, 10) === _heatmapThreshold);
  });
  document.querySelectorAll('#ps-threshold-btns .cc-tab').forEach(b => {
    b.classList.toggle('active', parseInt(b.dataset.threshold, 10) === _hourHeatmapThreshold);
  });
  // Restore colorblind-mode preference and wire the toggle. Class lives on
  // <html> (documentElement) so :root.colorblind-mode wins in the cascade
  // and tc() reads the override when drawing canvas charts.
  {
    const cbEl = document.getElementById('colorblind-toggle');
    let cbOn = false;
    try { cbOn = localStorage.getItem('colorblind_mode') === '1'; } catch (e) {}
    if (cbOn) {
      document.documentElement.classList.add('colorblind-mode');
      if (cbEl) cbEl.checked = true;
    }
    cbEl?.addEventListener('change', function () {
      document.documentElement.classList.toggle('colorblind-mode', this.checked);
      try { localStorage.setItem('colorblind_mode', this.checked ? '1' : '0'); } catch (e) {}
      if (typeof render === 'function') render();
    });
  }
  const overlay = document.getElementById('csv-overlay');
  const box     = document.getElementById('csv-drop-box');
  if (!overlay || !box) return;

  overlay.addEventListener('dragover', e => {
    e.preventDefault();
    overlay.classList.add('dragover');
    box.classList.add('dragover-box');
  });
  overlay.addEventListener('dragleave', e => {
    if (!overlay.contains(e.relatedTarget)) {
      overlay.classList.remove('dragover');
      box.classList.remove('dragover-box');
    }
  });
  overlay.addEventListener('drop', e => {
    e.preventDefault();
    overlay.classList.remove('dragover');
    box.classList.remove('dragover-box');
    const file = e.dataTransfer?.files?.[0];
    if (file) handleCsvFile(file);
  });
  box.addEventListener('click', e => {
    const nonClick = ['INPUT','BUTTON','LABEL','A'];
    if (!nonClick.includes(e.target.tagName)) {
      document.getElementById('csv-file-input').click();
    }
  });
});

document.addEventListener('dragenter', e => {
  if (e.dataTransfer?.types?.includes('Files')) openCsvOverlay();
});

function csvStatus(msg, type = 'info') {
  const el = document.getElementById('csv-status');
  if (!el) return;
  el.textContent = msg;
  el.className = 'csv-status ' + type;
}

function handleCsvFile(file) {
  if (!file) return;
  const ext = file.name.split('.').pop().toLowerCase();
  if (ext !== 'csv' && file.type !== 'text/csv' && !file.type.includes('text')) {
    csvStatus('⚠ Unsupported format — .csv file required', 'err');
    return;
  }
  if (file.size > 10 * 1024 * 1024) {
    csvStatus('⚠ File too large (max 10 MB)', 'err');
    return;
  }
  csvStatus('⏳ Reading file…', 'info');
  const reader = new FileReader();
  reader.onload  = e => processCsvText(e.target.result, file.name);
  reader.onerror = () => csvStatus('⚠ Unable to read file', 'err');
  reader.readAsText(file, 'UTF-8');
}

/** Notion exports occasionally wrap each CSV line in outer quotes with internal
 *  `""` escapes (RFC 4180 mis-applied). Detect that shape strictly and unwrap
 *  so downstream parsers see normal CSV. Conservative: only acts when BOTH
 *  anchors AND at least one internal `""` sequence are present, to avoid
 *  false positives on legit single-quoted single-column lines. */
function _unwrapOverQuotedLine(line) {
  if (typeof line !== 'string') return line;
  const t = line.trim();
  if (t.length <= 2) return line;
  if (!t.startsWith('"') || !t.endsWith('"')) return line;
  if (!t.includes('""')) return line;
  return t.slice(1, -1).replace(/""/g, '"');
}

function processCsvText(text, filename, opts = {}) {
  try {
    // Strip UTF-8 BOM at text level FIRST — it precedes the leading " on Notion
    // exports, so the over-wrap detection below would miss it otherwise.
    if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);

    // Detect Notion-style over-wrapped lines (whole line bracketed by " with ""
    // escapes). Normalize every line when present so the format-detection and
    // CSV parsers below see standard RFC 4180.
    const firstLineRaw = text.split(/\r?\n/)[0] || '';
    const trimmedFirst = firstLineRaw.trim();
    const isOverWrapped = trimmedFirst.startsWith('"')
                       && trimmedFirst.endsWith('"')
                       && trimmedFirst.includes('""')
                       && trimmedFirst.length > 2;
    if (isOverWrapped) {
      text = text.split(/\r?\n/).map(_unwrapOverQuotedLine).join('\n');
    }

    // ── Detect format ──
    const isFlippingMarket = text.includes('Résultat TP 1') || text.includes('Resultat TP 1') || (text.includes('M15 Type') && text.includes('Obstacles M15'));
    const isProTemplate = !isFlippingMarket && text.includes('Position Result') && text.includes('H4 Obstacles') && text.includes('Session');
    const isBeginner    = !isFlippingMarket && !isProTemplate && text.includes('Position Result');
    if (!isFlippingMarket && !isProTemplate && !isBeginner) {
      csvStatus(
        '⚠ Format not recognized\n' +
        'Header must contain "Résultat TP 1" (Flipping Market) or "Position Result" (Pro / Beginner)',
        'err'
      );
      return;
    }
    const result = isFlippingMarket ? parseFlippingMarketCSV(text) : isProTemplate ? parseProTemplateCSV(text) : parseBeginnerCSV(text);

    if (!result.ok) {
      csvStatus(result.error, 'err');
      return;
    }
    const { trades, warnings } = result;
    const fmt = isFlippingMarket ? ' [Flipping Market M15]' : isProTemplate ? ' [Pro Template]' : ' [Beginner]';
    if (result.partialOk) {
      // Degraded import: surface the missing required cols + invite remap.
      const missingList = result.missingRequired.join(', ');
      const ingestedMsg = trades.length
        ? `${trades.length} trade${trades.length > 1 ? 's' : ''} ingested with partial data${fmt}`
        : `0 trades ingested${fmt}`;
      const warningsTail = warnings.length ? '\n' + warnings.join('\n') : '';
      csvStatus(
        `⚠ ${result.missingRequired.length} required column${result.missingRequired.length > 1 ? 's' : ''} missing (${missingList}) — open Mapping to remap\n${ingestedMsg}${warningsTail}`,
        'warn'
      );
    } else if (warnings.length) {
      csvStatus(`✓ ${trades.length} trades imported${fmt}\n` + warnings.join('\n'), 'ok');
    } else {
      csvStatus(`✓ ${trades.length} trades imported${fmt}`, 'ok');
    }
    _csvFormat = isFlippingMarket ? 'flipping' : isProTemplate ? 'pro' : 'beginner';

    // Cache the raw text + headers so the user can later remap columns without re-uploading.
    _lastCsvRawText  = text;
    _lastCsvFilename = filename || '';
    try {
      const allLines = text.replace(/\r\n/g, '\n').split('\n').filter(l => l.trim());
      const firstLine = allLines[0] || '';
      _lastCsvHeaders = splitCsvLine(firstLine, ',').map(h => h.trim().replace(/^["']|["']$/g, '').replace(/^\uFEFF/, ''));
      // Capture raw rows as {header: value} objects so the auto-detect scan
      // can read the original CSV regardless of which props are declared.
      _lastCsvRows = allLines.slice(1).map(line => {
        const cols = splitCsvLine(line, ',').map(c => c.trim().replace(/^["']|["']$/g, ''));
        const row = {};
        _lastCsvHeaders.forEach((h, i) => { row[h] = cols[i] ?? ''; });
        return row;
      });
    } catch (e) { _lastCsvHeaders = []; _lastCsvRows = []; }

    if (opts.preserveState && opts.savedState) {
      // Remap re-parse: inject without resetting filters/layout
      _injectTrades(trades, 'CSV', opts.savedState);
      _cachedCSVTrades = trades.filter(t => t.pair && t.pair.trim()).slice();
      csvDataActive = true;
    } else {
      injectParsedTrades(trades, filename, _csvFormat);
      try { triggerDataHubFirstImportPulse(); } catch (e) {}
      // Persist the raw CSV so the dashboard can restore CSV mode on reload.
      // Sidebar filter state + TPM config are already persisted separately.
      // Wrap in try/catch: raw CSV can be multi-MB and hit QuotaExceededError.
      try {
        localStorage.setItem(CSV_CACHE_KEY, JSON.stringify({
          rawText: text,
          filename: filename || '',
          format: _csvFormat,
          savedAt: Date.now(),
        }));
      } catch (qe) {
        // Quota fallback: drop the raw text, keep metadata only. Next reload
        // will fall through to demo mode cleanly (the restore path checks
        // for rawText presence).
        try {
          localStorage.setItem(CSV_CACHE_KEY, JSON.stringify({
            rawText: '',
            filename: filename || '',
            format: _csvFormat,
            savedAt: Date.now(),
            _quotaExceeded: true,
          }));
        } catch (e2) { /* give up silently */ }
      }
      // Default behavior: CLOSE the Data Hub panel after a successful fresh
      // import so the dashboard widgets become immediately visible. The
      // Health/guide view was relevant during setup; once data is in, it's
      // noise. The user can re-open the hub manually if they need Mapping
      // or Health. Silent no-op if the hub wasn't open.
      // Phase 2 EXCEPTION: in degraded mode (partialOk), open the Data Hub
      // on Mapping instead so the user can immediately fix the missing
      // required columns. toggleJournalPanel handles both fresh-open and
      // already-open-on-other-tab cases.
      if (result.partialOk) {
        try { toggleJournalPanel(); } catch (e) {}
      } else if (typeof dataHubOpen !== 'undefined' && dataHubOpen) {
        try { toggleDataHub(); } catch (e) {}
      }
      // Also close the Guide panel (independent of Data Hub) and route the
      // user to Global Overview. Users land on the Guide when they click the
      // CSV source button before importing; after a successful import the
      // Guide is stale context. Skipped for opts.preserveState (column-remap
      // re-parses) — those must leave the user's current section alone.
      try { _closeGuidePanel(); } catch (e) {}
      try { if (typeof setSection === 'function') setSection('global'); } catch (e) {}
      // Belt-and-braces: ensure widgets reflect the new trade set. injectParsedTrades
      // already triggers a render, but a trailing call guarantees the CONTEXT strip
      // counter + chip badges reconcile with the freshly loaded trades.
      if (typeof render === 'function') { try { render(); } catch (e) {} }
    }
  } catch (err) {
    csvStatus('⚠ Parse error: ' + err.message, 'err');
  }
}

// ── Re-parse the cached CSV text after a column-override change.
// Preserves filter state, layout, and data-source indicator so remapping
// feels in-place rather than a fresh import. ──
function _reparseCsvWithOverrides() {
  if (!_lastCsvRawText) return false;
  const savedState = _saveFilterState();
  processCsvText(_lastCsvRawText, _lastCsvFilename, { preserveState: true, savedState });
  return true;
}

// ── CSV validation helpers ──
// Returns labels of every required column whose index is -1
function _checkMissingCols(required) {
  return required.filter(c => c.index === -1).map(c => c.label);
}
// Formats a multi-line error message listing each missing column
function _missingColsError(missing, formatName) {
  return `⚠ Missing required columns (${formatName}):\n` +
    missing.map(m => '  • ' + m).join('\n');
}

// ── Flipping Market M15 parser (journal principal + export Notion) ──
// TODO(Phase 3): detect optional beManagement column (currently API-only).
function parseFlippingMarketCSV(text) {
  const raw   = text.replace(/\r\n/g,'\n').replace(/\r/g,'\n');
  const lines = raw.split('\n').filter(l=>l.trim());
  if (lines.length<2) return {ok:false,error:'\u26a0 Empty file'};
  const headers = splitCsvLine(lines[0],',').map(h=>h.trim().replace(/^["']|["']$/g,''));

  // Required dims routed through _colForDim so user overrides set via the
  // Mapping panel take precedence over the format default.
  const iDate       = _colForDim(headers,'date','date');
  const iResultat   = _colForDim(headers,'outcome','résultat tp 1','resultat tp 1','position result');
  const iRR         = _colForDim(headers,'r','rr tp 1');
  const iPair       = _colForDim(headers,'pair','pair','actif');
  const iSetup      = _colForDim(headers,'setup','m15 confirmation / continuation','m15 confirmation / continu','m15 type');
  const iSetupDetail= _colForDim(headers,'setupDetail','m15 type détail','m15 type detail','m15 type détails','m15 type details','m15 type d\xe9tail','m15 type d\xe9tails');
  const iSession    = _colForDim(headers,'session','session');
  const iJour       = _colForDim(headers,'day','jour','day');
  const iRRMax      = _colForDim(headers,'rrMax','rr max','rr max atteint');
  // Multi TP (Phase 3): override-only, no format default. null when not mapped or empty.
  const iTp1Rr      = _colForDim(headers,'tp1_rr','rr tp 1');
  const iTp2Rr      = _colForDim(headers,'tp2_rr','rr tp 2','rr tp -27');
  const iTp3Rr      = _colForDim(headers,'tp3_rr','rr tp 3','rr trailing');
  const iObsM15     = _colForDim(headers,'obstacles','obstacles m15','m15 obstacles');
  const iObsH4      = _colForDim(headers,'h4','obstacles h4','h4 obstacles');
  const iBE         = _colForDim(headers,'beManagement','be management','gestion be');
  const iType       = _colForDim(headers,'positionType','type de trade');
  const iBadFeeling = _colForDim(headers,'badFeeling','bad feeling');
  const iOrdre      = _colForDim(headers,'direction','order','ordre');
  const iNotionUrl  = _colForDim(headers, 'notionUrl', 'notion url', 'url notion', 'page url', 'notion', 'url');
  const iHour       = _hourColForDim(headers);
  // Screenshot/image columns: Notion "M15 Before" / "H4 Before" / "M15 After" —
  // either a Files property exported as plain URL, or a simple URL property
  // (TV share link). All 3 are user-remappable via the Mapping panel under
  // dim keys img_m15 / img_h4_before / img_m15_after; defaults preserve the
  // legacy auto-detection for unmapped CSVs.
  const iImgM15     = (() => {
    const override = _csvColumnOverrides && _csvColumnOverrides.img_m15;
    if (override != null && override !== '') {
      const idx = _colFirst(headers, override);
      if (idx >= 0) return idx;
    }
    // Prefer explicit screenshot column names, including 'TV M15 Before' (TV-URL
    // convention), then fall back to standalone 'M15' / 'M15 Before' header.
    const named = _colAny(headers,'tv m15 before','url m15 before','screenshot m15','m15 screenshot','image m15','m15 image','photo m15','m15 photo','m15 before');
    if (named >= 0) return named;
    // Exact standalone 'M15' or 'M15 Before' header (must not already be claimed by m15 type columns)
    const idx = headers.findIndex(h => { const v = h.trim().toLowerCase(); return v === 'm15' || v === 'm15 before'; });
    return (idx >= 0 && idx !== iSetup && idx !== iSetupDetail) ? idx : -1;
  })();
  const iImgH4Before = _colForDim(headers, 'img_h4_before', 'tv h4 before', 'h4 before', 'url h4 before', 'h4before', 'screenshot h4', 'h4 screenshot', 'image h4', 'h4 image');
  const iImgM15After = _colForDim(headers, 'img_m15_after', 'tv m15 after', 'm15 after', 'url m15 after', 'm15after', 'm15 after screenshot', 'screenshot m15 after');

  const missing = _checkMissingCols([
    { label: 'Résultat TP 1', index: iResultat },
    { label: 'RR TP 1',       index: iRR },
    { label: 'Date',           index: iDate },
  ]);
  // Phase 2: degraded import. When required cols are missing we still parse
  // (skipping rows that can't be reconstructed without them), cache the
  // headers, and let processCsvText steer the user to the Mapping panel
  // instead of bailing hard. partialOk:true tells the caller to surface a
  // warn-level status + auto-open Data Hub on Mapping.
  const partialOk = missing.length > 0;

  const trades = [], warnings = [];
  let skippedOutcome = 0, skippedDate = 0;

  for (let i=1;i<lines.length;i++) {
    const line=lines[i].trim(); if(!line) continue;
    const cols=splitCsvLine(line,',');
    const get=idx=>(idx<0||idx>=cols.length)?'':cols[idx].trim().replace(/^["']|["']$/g,'');

    const typeRaw = get(iType) || '';
    const typeVal = typeRaw.toLowerCase();
    const isInvalide = typeVal.includes('invalide');
    const isBad      = _isBadFeeling(get(iBadFeeling));

    const rawOutcome = get(iResultat);
    const outcome=_mapOutcome(rawOutcome);
    if (!outcome) { skippedOutcome++; continue; }

    const date=_parseDate(get(iDate));
    if (!date||date.length<7) { skippedDate++; continue; }

    trades.push({
      date, month:date.slice(0,7),
      pair:        get(iPair)|| '',
      setup:       get(iSetup)||'',
      setupDetail: get(iSetupDetail)||'',
      session:     _normSession(get(iSession)),
      day:         get(iJour)||'',             // already French in journal
      obstacles:   _parseObs(get(iObsM15)),
      h4:          _parseObs(get(iObsH4)),
      beManagement: iBE >= 0 ? _parseObs(get(iBE)) : [],
      outcome,
      outcomeRaw:    rawOutcome,
      r:           _mapR(outcome, get(iRR)),
      rrMax:       iRRMax >= 0 ? _parseNumeric(get(iRRMax)) : null,
      tp1_rr:      iTp1Rr >= 0 ? _parseNumeric(get(iTp1Rr)) : null,
      tp2_rr:      iTp2Rr >= 0 ? _parseNumeric(get(iTp2Rr)) : null,
      tp3_rr:      iTp3Rr >= 0 ? _parseNumeric(get(iTp3Rr)) : null,
      direction:   get(iOrdre)||'',
      tradeType:   typeRaw ? typeRaw.split(',').map(s => s.trim()).filter(Boolean) : [],
      badFeeling:  isBad,
      invalide:    isInvalide,
      hour:        iHour >= 0 ? _parseHourValue(get(iHour)) : null,
      // Route image cells through _normalizeTvImageUrl: TV /x/<ID>/ share URLs
      // are rewritten to the deterministic S3 PNG path; anything else (Notion
      // signed S3, direct image URLs, custom hosts) passes through untouched.
      // The *Orig pair stores the original TV page URL (or '') for lightbox
      // fallback when the snapshot PNG 404s.
      ...(() => {
        const a = _normalizeTvImageUrl(iImgM15     >= 0 ? get(iImgM15)     : '');
        const b = _normalizeTvImageUrl(iImgH4Before >= 0 ? get(iImgH4Before) : '');
        const c = _normalizeTvImageUrl(iImgM15After >= 0 ? get(iImgM15After) : '');
        return {
          imgM15:      a.url, imgM15Orig:      a.origLink,
          imgH4Before: b.url, imgH4BeforeOrig: b.origLink,
          imgM15After: c.url, imgM15AfterOrig: c.origLink,
        };
      })(),
      notionUrl:   iNotionUrl  >= 0 ? get(iNotionUrl)  : '',
      extras:      _collectCustomExtrasFromCSV(headers, get),
      _rawRowIndex: i - 1,
    });
  }

  if (skippedOutcome > 0) warnings.push(`${skippedOutcome} row${skippedOutcome > 1 ? 's' : ''} skipped: missing outcome value`);
  if (skippedDate > 0)    warnings.push(`${skippedDate} row${skippedDate > 1 ? 's' : ''} skipped: missing or invalid date`);
  if (partialOk) {
    return { ok: true, trades, warnings, partialOk: true, missingRequired: missing };
  }
  if (!trades.length) return { ok: false, error: '⚠ No valid trades found in file' };
  return { ok: true, trades, warnings };
}


// ── Pro Template parser ──
// TODO(Phase 3): detect optional beManagement column (currently API-only).
function parseProTemplateCSV(text) {
  const raw   = text.replace(/\r\n/g,'\n').replace(/\r/g,'\n');
  const lines = raw.split('\n').filter(l=>l.trim());
  if (lines.length<2) return {ok:false,error:'\u26a0 Empty file'};
  const headers=splitCsvLine(lines[0],',').map(h=>h.trim().replace(/^["']|["']$/g,''));
  const iPair   =_colForDim(headers,'pair','pair');
  // Required dims routed through _colForDim so user overrides set via the
  // Mapping panel take precedence over the format default.
  const iResult =_colForDim(headers,'outcome','position result');
  const iDate   =_colForDim(headers,'date','date');
  const iRR     =_colForDim(headers,'r','rr tp 1');
  const iType   =_colForDim(headers,'positionType','position type');
  const iRRMax  =_colForDim(headers,'rrMax','rr max','rr max atteint');
  // Multi TP (Phase 3): override-only, no format default. null when not mapped or empty.
  const iTp1Rr  =_colForDim(headers,'tp1_rr','rr tp 1');
  const iTp2Rr  =_colForDim(headers,'tp2_rr','rr tp 2','rr tp -27');
  const iTp3Rr  =_colForDim(headers,'tp3_rr','rr tp 3','rr trailing');
  const iSetup  =_colForDim(headers,'setup','m15 confirmation / continuation','m15 confirmation / continu','m15 type detailed');
  const iSetupDetail=_colForDim(headers,'setupDetail','m15 type detailed');
  const iSess   =_colForDim(headers,'session','session');
  const iDay    =_colForDim(headers,'day','day');
  const iObsM15 =_colForDim(headers,'obstacles','m15 obstacles');
  const iObsH4  =_colForDim(headers,'h4','h4 obstacles');
  const iBE     =_colForDim(headers,'beManagement','be management','gestion be');
  const iBad    =_colForDim(headers,'badFeeling','bad feeling');
  const iOrder  =_colForDim(headers,'direction','order');
  const iNotionUrl=_colForDim(headers, 'notionUrl', 'notion url', 'url notion', 'page url', 'notion', 'url');
  const iHour   = _hourColForDim(headers);
  // Screenshot/image columns: remappable via Mapping panel. Explicit aliases only —
  // unlike Flipping Market we do NOT fall back to a standalone 'M15' header,
  // because Pro Template exports commonly include a Notion Files column named
  // 'M15' whose cells are filenames (e.g. "Capture_decran_....png") rather than
  // URLs — picking it would produce broken <img> links.
  const iImgM15     = _colForDim(headers, 'img_m15', 'tv m15 before', 'm15 before', 'url m15 before', 'screenshot m15', 'm15 screenshot', 'image m15', 'm15 image', 'photo m15', 'm15 photo');
  const iImgH4Before= _colForDim(headers, 'img_h4_before', 'tv h4 before', 'h4 before', 'url h4 before', 'h4before', 'screenshot h4', 'h4 screenshot', 'image h4', 'h4 image');
  const iImgM15After= _colForDim(headers, 'img_m15_after', 'tv m15 after', 'm15 after', 'url m15 after', 'm15after', 'm15 after screenshot', 'screenshot m15 after');
  const missing = _checkMissingCols([
    { label: 'Position Result', index: iResult },
    { label: 'RR TP 1',         index: iRR },
    { label: 'Date',             index: iDate },
  ]);
  // Phase 2: degraded import — see parseFlippingMarketCSV for rationale.
  const partialOk = missing.length > 0;

  const trades = [], warnings = [];
  let skippedOutcome = 0, skippedDate = 0;
  for (let i=1;i<lines.length;i++) {
    const cols=splitCsvLine(lines[i],',');
    const get=idx=>(idx<0||idx>=cols.length)?'':cols[idx].trim().replace(/^["']|["']$/g,'');
    const isInvalide = iType>=0 && get(iType).toLowerCase()==='invalid';
    const rawOutcome = get(iResult);
    const outcome=_mapOutcome(rawOutcome);
    if (!outcome) { skippedOutcome++; continue; }
    const date=_parseDate(get(iDate));
    if (!date||date.length<7) { skippedDate++; continue; }
    trades.push({
      date,month:date.slice(0,7),
      pair:     get(iPair).trim()|| '',
      setup:    get(iSetup),
      setupDetail: iSetupDetail >= 0 ? get(iSetupDetail) : '',
      session:  _normSession(get(iSess)),
      day:      _normDay(get(iDay)),
      obstacles:_parseObs(get(iObsM15)),
      h4:       _parseObs(get(iObsH4)),
      beManagement: iBE >= 0 ? _parseObs(get(iBE)) : [],
      outcome,  outcomeRaw: rawOutcome, r:_mapR(outcome,get(iRR)), rrMax: iRRMax >= 0 ? _parseNumeric(get(iRRMax)) : null, direction:get(iOrder),
      tp1_rr: iTp1Rr >= 0 ? _parseNumeric(get(iTp1Rr)) : null,
      tp2_rr: iTp2Rr >= 0 ? _parseNumeric(get(iTp2Rr)) : null,
      tp3_rr: iTp3Rr >= 0 ? _parseNumeric(get(iTp3Rr)) : null,
      badFeeling: _isBadFeeling(get(iBad)),
      invalide:   isInvalide,
      hour:       iHour >= 0 ? _parseHourValue(get(iHour)) : null,
      notionUrl:  iNotionUrl >= 0 ? get(iNotionUrl) : '',
      // TV-share URL normalization: see parser comment above _TV_SHARE_RE.
      ...(() => {
        const a = _normalizeTvImageUrl(iImgM15     >= 0 ? get(iImgM15)     : '');
        const b = _normalizeTvImageUrl(iImgH4Before >= 0 ? get(iImgH4Before) : '');
        const c = _normalizeTvImageUrl(iImgM15After >= 0 ? get(iImgM15After) : '');
        return {
          imgM15:      a.url, imgM15Orig:      a.origLink,
          imgH4Before: b.url, imgH4BeforeOrig: b.origLink,
          imgM15After: c.url, imgM15AfterOrig: c.origLink,
        };
      })(),
      extras:     _collectCustomExtrasFromCSV(headers, get),
      _rawRowIndex: i - 1,
    });
  }
  if (skippedOutcome > 0) warnings.push(`${skippedOutcome} row${skippedOutcome > 1 ? 's' : ''} skipped: missing outcome value`);
  if (skippedDate > 0)    warnings.push(`${skippedDate} row${skippedDate > 1 ? 's' : ''} skipped: missing or invalid date`);
  if (partialOk) {
    return { ok: true, trades, warnings, partialOk: true, missingRequired: missing };
  }
  if (!trades.length) return { ok: false, error: '⚠ No valid trades found in file' };
  return { ok: true, trades, warnings };
}



// ── Beginner parser ──
// TODO(Phase 3): detect optional beManagement column (currently API-only).
function parseBeginnerCSV(text) {
  const raw   = text.replace(/\r\n/g,'\n').replace(/\r/g,'\n');
  const lines = raw.split('\n').filter(l=>l.trim());
  if (lines.length<2) return {ok:false,error:'\u26a0 Empty file'};
  const headers=splitCsvLine(lines[0],',').map(h=>h.trim().replace(/^["']|["']$/g,'').replace(/^\uFEFF/,''));
  const iPair  =_colForDim(headers,'pair','pair');
  // Required dims routed through _colForDim so user overrides set via the
  // Mapping panel take precedence over the format default.
  const iResult=_colForDim(headers,'outcome','position result');
  const iDate  =_colForDim(headers,'date','date');
  const iRR    =_colForDim(headers,'r','rr tp 1');
  const iType  =_colForDim(headers,'positionType','position type');
  const iRRMax =_colForDim(headers,'rrMax','rr max','rr max atteint');
  // Multi TP (Phase 3): override-only, no format default. null when not mapped or empty.
  const iTp1Rr =_colForDim(headers,'tp1_rr','rr tp 1');
  const iTp2Rr =_colForDim(headers,'tp2_rr','rr tp 2','rr tp -27');
  const iTp3Rr =_colForDim(headers,'tp3_rr','rr tp 3','rr trailing');
  const iSetup =_colForDim(headers,'setup','m15 confirmation / continuation','m15 confirmation / continu','m15 type detailed');
  const iSetupDetail=_colForDim(headers,'setupDetail','m15 type detailed');
  const iDay   =_colForDim(headers,'day','day');
  const iSession=_colForDim(headers,'session','session');
  const iObs   =_colForDim(headers,'obstacles','m15 obstacles');
  const iObsH4 =_colForDim(headers,'h4','h4 obstacles');
  const iBE    =_colForDim(headers,'beManagement','be management','gestion be');
  const iBad   =_colForDim(headers,'badFeeling','bad feeling');
  const iOrder =_colForDim(headers,'direction','order');
  const iNotionUrl=_colForDim(headers, 'notionUrl', 'notion url', 'url notion', 'page url', 'notion', 'url');
  const iHour  = _hourColForDim(headers);
  // Screenshot/image columns: explicit aliases only (same policy as Pro Template).
  const iImgM15     = _colForDim(headers, 'img_m15', 'tv m15 before', 'm15 before', 'url m15 before', 'screenshot m15', 'm15 screenshot', 'image m15', 'm15 image', 'photo m15', 'm15 photo');
  const iImgH4Before= _colForDim(headers, 'img_h4_before', 'tv h4 before', 'h4 before', 'url h4 before', 'h4before', 'screenshot h4', 'h4 screenshot', 'image h4', 'h4 image');
  const iImgM15After= _colForDim(headers, 'img_m15_after', 'tv m15 after', 'm15 after', 'url m15 after', 'm15after', 'm15 after screenshot', 'screenshot m15 after');
  const missing = _checkMissingCols([
    { label: 'Position Result', index: iResult },
    { label: 'Pair',             index: iPair },
    { label: 'Date',             index: iDate },
  ]);
  // Phase 2: degraded import — see parseFlippingMarketCSV for rationale.
  const partialOk = missing.length > 0;

  const trades = [], warnings = [];
  let skippedOutcome = 0, skippedDate = 0;
  for (let i=1;i<lines.length;i++) {
    const cols=splitCsvLine(lines[i],',');
    const get=idx=>(idx<0||idx>=cols.length)?'':cols[idx].trim().replace(/^["']|["']$/g,'');
    const isInvalide = iType>=0 && get(iType).toLowerCase()==='invalid';
    const rv=get(iResult).trim();
    if (rv==='.'||rv==='') { skippedOutcome++; continue; }
    const outcome=_mapOutcome(rv);
    if (!outcome) { skippedOutcome++; continue; }
    const date=_parseDate(get(iDate));
    if (!date||date.length<7) { skippedDate++; continue; }
    trades.push({
      date,month:date.slice(0,7),
      pair:    get(iPair).trim()|| '',
      setup:   get(iSetup),
      setupDetail: iSetupDetail >= 0 ? get(iSetupDetail) : '',
      session: _normSession(get(iSession)),
      day:     _normDay(get(iDay)),
      obstacles:_parseObs(get(iObs)),
      h4:       iObsH4 >= 0 ? _parseObs(get(iObsH4)) : [],
      beManagement: iBE >= 0 ? _parseObs(get(iBE)) : [],
      outcome, outcomeRaw: rv, r:_mapR(outcome,get(iRR)), rrMax: iRRMax >= 0 ? _parseNumeric(get(iRRMax)) : null, direction:get(iOrder),
      tp1_rr: iTp1Rr >= 0 ? _parseNumeric(get(iTp1Rr)) : null,
      tp2_rr: iTp2Rr >= 0 ? _parseNumeric(get(iTp2Rr)) : null,
      tp3_rr: iTp3Rr >= 0 ? _parseNumeric(get(iTp3Rr)) : null,
      badFeeling: _isBadFeeling(get(iBad)),
      invalide:   isInvalide,
      hour:      iHour >= 0 ? _parseHourValue(get(iHour)) : null,
      notionUrl:  iNotionUrl >= 0 ? get(iNotionUrl) : '',
      // TV-share URL normalization: see _TV_SHARE_RE / _normalizeTvImageUrl.
      ...(() => {
        const a = _normalizeTvImageUrl(iImgM15     >= 0 ? get(iImgM15)     : '');
        const b = _normalizeTvImageUrl(iImgH4Before >= 0 ? get(iImgH4Before) : '');
        const c = _normalizeTvImageUrl(iImgM15After >= 0 ? get(iImgM15After) : '');
        return {
          imgM15:      a.url, imgM15Orig:      a.origLink,
          imgH4Before: b.url, imgH4BeforeOrig: b.origLink,
          imgM15After: c.url, imgM15AfterOrig: c.origLink,
        };
      })(),
      extras:    _collectCustomExtrasFromCSV(headers, get),
      _rawRowIndex: i - 1,
    });
  }
  if (skippedOutcome > 0) warnings.push(`${skippedOutcome} row${skippedOutcome > 1 ? 's' : ''} skipped: missing outcome value`);
  if (skippedDate > 0)    warnings.push(`${skippedDate} row${skippedDate > 1 ? 's' : ''} skipped: missing or invalid date`);
  if (partialOk) {
    return { ok: true, trades, warnings, partialOk: true, missingRequired: missing };
  }
  if (!trades.length) return { ok: false, error: '⚠ No valid trades found in file' };
  return { ok: true, trades, warnings };
}

function splitCsvLine(line, delim) {
  const cols = [];
  let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      // Handle escaped double-quote ""
      if (inQ && line[i + 1] === '"') {
        cur += '"'; i++;
      } else {
        inQ = !inQ;
      }
    } else if (ch === delim && !inQ) {
      cols.push(cur); cur = '';
    } else {
      cur += ch;
    }
  }
  cols.push(cur);
  return cols;
}

function injectParsedTrades(parsed, filename, csvFormat) {
  // Replace the appState.trades.items array
  const validTrades = parsed.filter(t => t.pair && t.pair.trim());

  // Clear all filters first
  clearChipFilters();
  appState.filters.exclusions.m15Exclude = [...BASE_M15_EXCLUDE];
  appState.filters.exclusions.h4Exclude  = [];
  appState.filters.exclusions.sessionExclude = [...BASE_SESSION_EXCLUDE];
  appState.presets.activeId = null;
  syncPresetSelectionState(null);
  // Reset temporal filter
  appState.filters.temporal.tf.mode = 'global'; appState.filters.temporal.tf.year = null; appState.filters.temporal.tf.quarter = null; appState.filters.temporal.tf.month = null; appState.filters.temporal.tf.compare = false;
  appState.filters.temporal.dateFrom = null; appState.filters.temporal.dateTo = null;
  const chk = document.getElementById('tf-compare-chk');
  if (chk) chk.checked = false;

  // Cache for re-injection when switching back to CSV mode
  _cachedCSVTrades = validTrades.slice();

  // Inject into appState.trades.items
  appState.trades.items.length = 0;
  validTrades.forEach(t => appState.trades.items.push(t));
  appState.trades.totalOverride = appState.trades.items.length;

  // Update dynamic dimension arrays from data
  rebuildDimensions();

  // Rebuild temporal filter selects from new data
  tfPopulateSelects();
  tfSetMode('global');

  // Update UI indicators
  csvDataActive = true;
  const _tm=document.getElementById('tab-section-global');
  if(_tm)_tm.classList.add('active');

  csvStatus(`✓ ${validTrades.length} trades imported`, 'ok');

  // Dismiss the full-screen empty-state overlay before the first post-import
  // render paints. Without this the overlay (#empty-state, z-index: 300)
  // stays stacked above the dashboard even though widgets have populated.
  // _injectTrades (API/Demo paths) does this itself; CSV first-import went
  // through injectParsedTrades which bypassed it.
  hideEmptyState();
  // Route to Global Overview using the app's section-switching API — this
  // toggles the .active class on the view-tab buttons AND triggers
  // _applySectionFilter so the grid reflects the section. The bare
  // classList.add above is kept for legacy parity but is now redundant.
  if (typeof setSection === 'function') setSection('global');

  render();

  // Apply saved or default layout after render (applyLayout defined later in script)
  requestAnimationFrame(() => {
    if (typeof _applySerializedLayout !== 'function') return;
    const savedKey = localStorage.getItem(_htfKey(LS_KEY_ACTIVE));
    let savedLayout = null;
    try {
      savedLayout = savedKey ? JSON.parse(localStorage.getItem(_htfKey(LS_KEY_PREFIX + savedKey)) || 'null') : null;
    } catch (e) {
      console.warn('[layout restore import]', e.message);
      savedLayout = null;
    }
    _applySerializedLayout(savedLayout || DEFAULT_LAYOUT);
  });
  setTimeout(closeCsvOverlay, 1200);
  // Sync data source state to CSV after a successful import
  localStorage.setItem(DS_KEY, 'csv');
  updateSourceUI('csv');
  // Refresh the Data & Integrations switch list so the CSV virtual row
  // flips to is-active immediately when the panel is open during import
  // (otherwise it stays stale until the next panel interaction).
  try { if (typeof _syncJournalProfileUI === 'function') _syncJournalProfileUI(); } catch (e) {}
}

// Dynamic dimension rebuild after CSV import
function rebuildDimensions() {
  const uniqueVals = key => [...new Set(appState.trades.items.map(t => t[key]).filter(Boolean))].sort();
  const uniqueObs  = () => [...new Set(appState.trades.items.flatMap(t => t.obstacles))].filter(Boolean).sort();

  // Rebuild SETUPS, SESSIONS, DAYS, PAIRS, ALL_OBS from data
  const newSetups   = uniqueVals('setup').filter(Boolean);
  const newSessions = uniqueVals('session').filter(Boolean);
  const newDays     = uniqueVals('day').filter(Boolean);
  const newPairs    = uniqueVals('pair').filter(Boolean);
  const newObs      = uniqueObs();

  SETUPS.length   = 0; newSetups.forEach(v=>SETUPS.push(v));
  SESSIONS.length = 0; newSessions.forEach(v=>SESSIONS.push(v));
  DAYS.length     = 0; newDays.forEach(v=>DAYS.push(v));
  PAIRS.length    = 0; newPairs.forEach(v=>PAIRS.push(v));
  ALL_OBS.length  = 0; newObs.forEach(v=>ALL_OBS.push(v));
  const newH4Obs = [...new Set(appState.trades.items.flatMap(t => t.h4 || []))].filter(Boolean).sort();
  ALL_H4OBS.length = 0; newH4Obs.forEach(v=>ALL_H4OBS.push(v));
  const newTradeTypes = [...new Set(appState.trades.items.flatMap(t => t.tradeType || []).filter(v => !!v))].sort();
  ALL_TRADE_TYPES.length = 0; newTradeTypes.forEach(v=>ALL_TRADE_TYPES.push(v));
  const newBeMgmt = [...new Set(appState.trades.items.flatMap(t => t.beManagement || []))].filter(Boolean).sort();
  ALL_BE_MGMT.length = 0; newBeMgmt.forEach(v=>ALL_BE_MGMT.push(v));
  const newOutcomes = [...new Set(appState.trades.items.map(t => t.outcome).filter(Boolean))].sort();
  ALL_OUTCOMES.length = 0; newOutcomes.forEach(v => ALL_OUTCOMES.push(v));
  const newDirections = [...new Set(appState.trades.items.map(t => t.direction).filter(Boolean))].sort();
  ALL_DIRECTIONS.length = 0; newDirections.forEach(v => ALL_DIRECTIONS.push(v));

  _dimVersion++;
}

// (appState.trades.totalOverride applied directly inside updateStats below)


// ══════════════════════════════════════════════════════
// THEME ENGINE
// ══════════════════════════════════════════════════════

const THEME_STORAGE_KEY  = 'flipping_dashboard_theme';
const BAR_COLOR_MODE_KEY  = 'flipping_bar_color_mode';
const TYPO_MODE_KEY       = 'flipping_typo_mode';

// 'quality' = threshold-based on avg R | 'binary' = positive/negative
let barColorMode = localStorage.getItem(BAR_COLOR_MODE_KEY) || 'binary';

// 'manual' = sliders set per-typo sizes globally | 'auto' = scale per widget
let typoMode = localStorage.getItem(TYPO_MODE_KEY) || 'manual';

// Minimum effective font size in auto mode. We never shrink a typo var below
// max( min(base, FLOOR), base * scale ). When base is already ≤ FLOOR (e.g.
// --typo-nano-size 7px) the per-var floor stays at the base — we never grow
// above what the slider was asking for; we just refuse to shrink past it.
const TYPO_AUTO_FLOOR_PX = 9;

// Compute the per-widget scale from its current grid size vs DEFAULT_LAYOUT
// reference. Both axes ≥ ref → grow follows HEIGHT only (height is what the
// content needs to "breathe"; widening alone just gives the bar tracks more
// room). Any axis < ref → shrink uses min() so content still fits.
function _computeWidgetScale(curW, curH, refW, refH) {
  const w = curW / refW;
  const h = curH / refH;
  return (w >= 1 && h >= 1) ? h : Math.min(w, h);
}

// All --typo-/--fs-/--pp- vars that affect WIDGET CONTENT (not topbar/sidebar/ui chrome).
// In auto mode, these are overridden per-widget on the .grid-stack-item element so
// children inherit a scaled value via CSS cascade. Chart-internal text (read via
// tc(...)) scales via the _withWidgetScale stack instead — see tc() and the stack.
const WIDGET_SCOPED_TYPO_VARS = [
  // Global widget text
  '--typo-base-size', '--typo-widget-title-size', '--typo-widget-sub-size',
  '--typo-kpi-val-size', '--typo-kpi-lbl-size', '--typo-kpi-value-size',
  // Tables
  '--typo-table-hd-size', '--typo-table-body-size',
  // Generic chart axis/value (used by some bar widgets)
  '--typo-chart-axis-size', '--typo-chart-val-size',
  // Panels / controls / micro / nano (only widget-internal — chrome panels live outside .grid-stack-item)
  '--typo-panel-size', '--typo-ctrl-size', '--typo-micro-size', '--typo-nano-size',
  // Calendar
  '--fs-cal-header', '--fs-cal-value', '--fs-cal-stats', '--fs-cal-day', '--fs-cal-summary',
  // Partials Planner
  '--pp-hero-r-size', '--pp-hero-delta-size', '--pp-editor-title-size', '--pp-placeholder-title-size',
  // Equity / Drawdown
  '--typo-eq-axis-size', '--typo-eq-xaxis-size', '--typo-dd-axis-size',
  '--typo-dd-label-size', '--typo-eq-marker-size',
  // Performance bars
  '--typo-bar-setup-label-size',   '--typo-bar-setup-val-size',
  '--typo-bar-pair-label-size',    '--typo-bar-pair-val-size',
  '--typo-bar-session-label-size', '--typo-bar-session-val-size',
  '--typo-bar-day-label-size',     '--typo-bar-day-val-size',
  '--typo-bar-m15-label-size',     '--typo-bar-m15-val-size',
  '--typo-bar-h4-label-size',      '--typo-bar-h4-val-size',
  '--typo-bar-hour-label-size',    '--typo-bar-hour-val-size',
  // Streak / Recovery / MC / ORR
  '--typo-streak-tick-size', '--typo-streak-legend-size',
  '--typo-recovery-tick-size', '--typo-recovery-title-size', '--typo-recovery-annot-size',
  '--typo-mc-tick-size',
  '--typo-orr-tick-size', '--typo-orr-annot-size',
  // Trade Log
  '--typo-tl-pair-size', '--typo-tl-setup-size', '--typo-tl-session-size',
  '--typo-tl-day-size', '--typo-tl-obs-size',
  // Monthly P&L
  '--fs-monthly-bar', '--fs-monthly-label', '--fs-monthly-grid',
  // Legacy --fs-* aliases (kept in sync by sliders)
  '--fs-kpi', '--fs-stat', '--fs-body', '--fs-title', '--fs-large',
  '--fs-medium', '--fs-small', '--fs-ui', '--fs-micro',
];

// Stack used to scope tc(...) reads to a widget context. When non-empty, tc()
// scales widget-typo vars by the top-of-stack scale. Updated by _withWidgetScale.
const _widgetScaleStack = [];

// Run `fn` with tc(...) calls scaled to the widget identified by `widgetId`.
// In manual mode, no scaling — just runs fn. In auto mode, computes scale =
// min(curW/refW, curH/refH) using DEFAULT_LAYOUT as reference.
function _withWidgetScale(widgetId, fn) {
  const handle = _pushWidgetScale(widgetId);
  try { return fn(); } finally { _popWidgetScale(handle); }
}

// Push/pop variants kept for API compatibility but now no-ops: with the CSS
// `zoom` strategy, chart-internal text sizes flow through zoom uniformly.
// Pushing a scale here would double-scale tc() reads, so we skip it. The
// wrapper functions in renderCharts/renderPanels still call _pushWidgetScale
// — they just don't do anything useful anymore. Left in place so a future
// per-element scaling strategy can re-enable easily.
function _pushWidgetScale(_widgetId) { return null; }
function _popWidgetScale(handle) {
  if (handle != null) _widgetScaleStack.pop();
}

// Apply per-widget zoom factor to .grid-stack-item elements based on each
// widget's current size vs its DEFAULT_LAYOUT reference. Setting --widget-scale
// drives a CSS `zoom: var(--widget-scale)` rule on .grid-stack-item-content
// (see dashboard.css), which scales EVERYTHING inside — typography, charts,
// padding, gaps — uniformly. This works for widgets whose CSS uses both
// var(--typo-*) and hardcoded px font-sizes (e.g. Partial Optimizer).
// Cleared in manual mode. Called on resize, drag, layout switch.
//
// Two grids are scaled independently:
//  - #gs-container          → main dashboard widgets (scale = own grid size)
//  - #ms-grid-container     → mini grid sidebar tiles (scale = own tile size)
// Each tile in the mini grid scales based on ITS OWN size in the sidebar, NOT
// the matching main widget's size — they're separate editing contexts.
const TYPO_AUTO_MIN_SCALE = 0.6;  // floor below which content gets unreadable
function _applyAutoTypoScaleForGrid(rootSelector) {
  const items = document.querySelectorAll(`${rootSelector} .grid-stack-item`);
  if (typoMode !== 'auto') {
    items.forEach(el => el.style.removeProperty('--widget-scale'));
    return;
  }
  items.forEach(el => {
    const id  = el.getAttribute('gs-id');
    const ref = id ? DEFAULT_LAYOUT[id] : null;
    const n   = el.gridstackNode;
    if (!ref || !n) {
      el.style.removeProperty('--widget-scale');
      return;
    }
    const raw    = _computeWidgetScale(n.w, n.h, ref.w, ref.h);
    const scale  = Math.max(TYPO_AUTO_MIN_SCALE, raw);
    el.style.setProperty('--widget-scale', scale.toFixed(4));
  });
}
function _applyAutoTypoScale() {
  _applyAutoTypoScaleForGrid('#gs-container');
  _applyAutoTypoScaleForGrid('#ms-grid-container');
  _applyAutoTypoScaleForInternalBlocks();
}

// Partial Optimizer + Monte Carlo each lay out their own draggable/resizable
// blocks via an internal CSS grid. For these widgets the user expects the
// typography of each block to follow the BLOCK's size — not the main widget's.
// We apply per-block --widget-scale here; the corresponding CSS rules below
// (`.po-block`, `.mc2-section-block`) zoom on that variable, while the main
// widget's own .grid-stack-item-content zoom is overridden to 1.
function _applyAutoTypoScaleForInternalBlocks() {
  // Helper: clear or set per-block --widget-scale
  const apply = (selector, getRect, getDefault) => {
    document.querySelectorAll(selector).forEach(block => {
      const key = block.dataset.poSection || block.dataset.mc2Section;
      const cur = getRect(key);
      const def = getDefault(key);
      if (typoMode !== 'auto' || !cur || !def) {
        block.style.removeProperty('--widget-scale');
        return;
      }
      const raw   = _computeWidgetScale(cur.w, cur.h, def.w, def.h);
      const scale = Math.max(TYPO_AUTO_MIN_SCALE, raw);
      block.style.setProperty('--widget-scale', scale.toFixed(4));
    });
  };

  // Partial Optimizer
  if (typeof _poInternalGetLayout === 'function' && typeof _PO_DEFAULT_INTERNAL_LAYOUT !== 'undefined') {
    let layout = null;
    try { layout = _poInternalGetLayout(); } catch {}
    apply(
      '.po-block[data-po-section]',
      key => (layout && key) ? layout[key] : null,
      key => key ? _PO_DEFAULT_INTERNAL_LAYOUT[key] : null,
    );
  }

  // Monte Carlo
  if (typeof _mc2GetSectionLayout === 'function' && typeof _MC2_DEFAULT_SECTION_LAYOUT !== 'undefined') {
    let layout = null;
    try { layout = _mc2GetSectionLayout(); } catch {}
    apply(
      '.mc2-section-block[data-mc2-section]',
      key => (layout && key) ? layout[key] : null,
      key => key ? _MC2_DEFAULT_SECTION_LAYOUT[key] : null,
    );
  }
}

function _setTypoMode(mode) {
  if (mode !== 'manual' && mode !== 'auto') return;
  typoMode = mode;
  try { localStorage.setItem(TYPO_MODE_KEY, mode); } catch {}
  document.querySelectorAll('input[name="typoMode"]').forEach(r => { r.checked = (r.value === mode); });
  // Grey out the sliders below while Auto is on
  const typoBox = document.getElementById('tp-typography');
  if (typoBox) typoBox.classList.toggle('is-auto-locked', mode === 'auto');
  _applyAutoTypoScale();
  // Trigger chart redraw so canvases pick up the new effective sizes
  if (typeof _redrawAll === 'function') _redrawAll();
}

function _initTypoModeUI() {
  document.querySelectorAll('input[name="typoMode"]').forEach(r => {
    r.checked = (r.value === typoMode);
    r.addEventListener('change', e => {
      if (e.target.checked) _setTypoMode(e.target.value);
    });
  });
  const typoBox = document.getElementById('tp-typography');
  if (typoBox) typoBox.classList.toggle('is-auto-locked', typoMode === 'auto');
}

// ── Bar hover tooltip (uses unified utip system) ──
function _buildBarTipHTML(label, n, oc) {
  const [tpN, tpR, slN, slR, betpN, betpR, beslN, beslR] = oc.split(',').map(Number);
  const wr = n > 0 ? ((tpN + betpN) / n * 100).toFixed(0) : 0;
  const fmt = v => (v >= 0 ? '+' : '') + v.toFixed(2) + 'R';
  // Each row hides itself when its count is 0. Net TP / Net SL / Total Net
  // breakdown is shown only when BOTH sides have data AND at least one side
  // has multiple components to aggregate (TP+BE-TP or SL+BE-SL); otherwise
  // the breakdown would just duplicate the visible grid rows, so collapse to
  // a single "Net Result" line summing whatever rows are visible.
  const showTP   = tpN > 0;
  const showSL   = slN > 0;
  const showBETP = betpN > 0;
  const showBESL = beslN > 0;
  const hasWinSide   = showTP   || showBETP;
  const hasLoseSide  = showSL   || showBESL;
  const winSideMulti  = showTP && showBETP;
  const loseSideMulti = showSL && showBESL;
  const showBreakdown = hasWinSide && hasLoseSide && (winSideMulti || loseSideMulti);
  const gridRows = `${showTP ? `
      <span style="color:var(--g)">TP</span><span style="color:var(--g);text-align:right">×${tpN}</span><span style="color:var(--g);text-align:right">${fmt(tpR)}</span>` : ''}${showSL ? `
      <span style="color:var(--r)">SL</span><span style="color:var(--r);text-align:right">×${slN}</span><span style="color:var(--r);text-align:right">${fmt(slR)}</span>` : ''}${showBETP ? `
      <span style="color:var(--oc-betp)">BE-TP</span><span style="color:var(--oc-betp);text-align:right">×${betpN}</span><span style="color:var(--oc-betp);text-align:right">${fmt(betpR)}</span>` : ''}${showBESL ? `
      <span style="color:var(--oc-besl)">BE-SL</span><span style="color:var(--oc-besl);text-align:right">×${beslN}</span><span style="color:var(--oc-besl);text-align:right">${fmt(beslR)}</span>` : ''}`;
  return `
    <div class="utip-header">${label} <span class="utip-header-sub">×${n}</span></div>
    <div class="utip-grid">${gridRows}
    </div>
    <div class="utip-divider"></div>
    <div class="utip-row">
      <span class="utip-label">Win Rate</span>
      <span style="color:${_kpiTooltipColor(+wr, 'wr')};font-weight:700">${wr}%</span>
    </div>
    ${(() => {
      const avgR = n > 0 ? (tpR + slR + betpR + beslR) / n : 0;
      return `<div class="utip-row">
      <span class="utip-label">Avg R</span>
      <span style="color:${_kpiTooltipColor(avgR, 'avgr')};font-weight:700">${fmt(avgR)}</span>
    </div>`;
    })()}
    ${(() => {
      if (!showBreakdown) {
        const net = tpR + slR + betpR + beslR;
        return `<div class="utip-row">
      <span class="utip-label">Net Result</span>
      <span style="color:${net >= 0 ? 'var(--g)' : 'var(--r)'};font-weight:700">${fmt(net)}</span>
    </div>`;
      } else {
        const netTP  = tpR + betpR;
        const netSL  = slR + beslR;
        const total  = netTP + netSL;
        return `<div class="utip-row">
      <span class="utip-label">Net TP</span>
      <span style="color:${netTP >= 0 ? 'var(--g)' : 'var(--r)'}">${fmt(netTP)}</span>
    </div>
    <div class="utip-row">
      <span class="utip-label">Net SL</span>
      <span style="color:${netSL >= 0 ? 'var(--g)' : 'var(--r)'}">${fmt(netSL)}</span>
    </div>
    <div class="utip-row">
      <span class="utip-label">Total Net</span>
      <span style="color:${total >= 0 ? 'var(--g)' : 'var(--r)'};font-weight:700">${fmt(total)}</span>
    </div>`;
      }
    })()}`;
}
function _showBarTip(e) {
  const row = e.target.closest('.bar-row');
  if (!row) return;
  const oc = row.dataset.barOc;
  if (!oc) return;
  showUtip(e, _buildBarTipHTML(row.dataset.barLabel || '—', parseInt(row.dataset.barN) || 0, oc));
}
function _hideBarTip() { hideUtip(); }

// Global delegated listeners for bar hover tooltip
document.addEventListener('mouseover', e => {
  // Always-on tooltip for obstacle bars
  if (e.target.closest?.('.tip-always')) { _showBarTip(e); return; }
  // Tooltip for regular bar rows
  if (!e.target.closest?.('.bar-list')) return;
  _showBarTip(e);
});
document.addEventListener('mousemove', e => {
  if (_utip && _utip.classList.contains('visible')) _posUtip(e.clientX, e.clientY);
});
document.addEventListener('mouseout', e => {
  if (!_utip || !_utip.classList.contains('visible')) return;
  const fromAlways = e.target.closest?.('.tip-always');
  const fromBarRow = e.target.closest?.('.bar-row');
  if (fromAlways && !e.relatedTarget?.closest?.('.tip-always')) { hideUtip(); return; }
  // Hide when leaving a specific bar (unless moving to another bar — then the
  // mouseover updates the tooltip). Previous logic checked `.bar-list` which
  // only triggered when leaving the whole container, leaving the tooltip
  // stuck while hovering gaps between bars.
  if (fromBarRow && !e.relatedTarget?.closest?.('.bar-row')) hideUtip();
});

// ── Delegated click handler: opens shared drawer on bar-row click ──
document.addEventListener('click', e => {
  const row = e.target.closest('.bar-row');
  if (!row) return;
  // Find the container (direct parent must have an ID like 'bars-*')
  const list = row.parentElement;
  if (!list || !list.id) return;
  _openDrawerFromBarRow(list.id, row);
});

/* Filter currently-visible trades to those matching the clicked bar and open the drawer */
function _openDrawerFromBarRow(containerId, row) {
  const rawKey = row.dataset.barRawkey || row.dataset.barLabel;
  if (!rawKey) return;
  const label    = row.dataset.barLabel || rawKey;
  const filtered = getFiltered();
  const chartId = _getBarChartIdFromContainerId(containerId);
  if (!chartId) return;
  const trades = _getTradesForBarChartSelection(chartId, rawKey, filtered);
  if (!trades || !trades.length) return;

  // Highlight the clicked bar-row with a gold border
  document.querySelectorAll('.bar-row.lb-active').forEach(r => r.classList.remove('lb-active'));
  row.classList.add('lb-active');

  openWidgetDrawer(label, null, trades);
}

// ── Right-click context menu on bar charts: Include / Exclude ──
// Maps container IDs to chip filter keys (sidebar filters, NOT preset additional filters)
const _BAR_CONTAINER_TO_CHIP = {
  'bars-setup': 'setup', 'bars-session': 'session', 'bars-pair': 'pair',
  'bars-day': 'day', 'bars-obs': 'obstacles', 'bars-h4obs': 'h4obs',
  'bars-hour': 'hour',
};

document.addEventListener('contextmenu', e => {
  const row = e.target.closest('.bar-row');
  if (!row) return;
  const list = row.parentElement;
  if (!list || !list.id) return;
  const chipKey = _BAR_CONTAINER_TO_CHIP[list.id];
  if (!chipKey) return;
  const rawKey = row.dataset.barRawkey || row.dataset.barLabel;
  if (!rawKey) return;
  e.preventDefault();
  _showBarContextMenu(chipKey, rawKey, row.dataset.barLabel || rawKey, e);
});

function _showBarContextMenu(chipKey, rawKey, displayLabel, event) {
  _closeBarContextMenu();
  const entry = appState.filters.chips[chipKey];
  if (!entry) return;

  const isIncluded = entry.included.has(rawKey);
  const isExcluded = entry.excluded.has(rawKey);

  const menu = document.createElement('div');
  menu.id = 'bar-ctx-menu';
  menu.className = 'layout-slot-menu';
  menu.innerHTML = `
    <div style="padding:4px 12px 3px;font-size:9px;color:var(--dim);letter-spacing:.5px;text-transform:uppercase">${_escapeHtml(displayLabel)}</div>
    <div class="layout-slot-menu-sep"></div>
    <button class="layout-slot-menu-item bcm-include${isIncluded ? ' bcm-active' : ''}" type="button" data-act="include">
      <span class="lsm-icon">＋</span><span>${isIncluded ? 'Remove Include' : 'Include'}</span>
    </button>
    <button class="layout-slot-menu-item bcm-exclude${isExcluded ? ' bcm-active' : ''}" type="button" data-act="exclude">
      <span class="lsm-icon">−</span><span>${isExcluded ? 'Remove Exclude' : 'Exclude'}</span>
    </button>
  `;
  document.body.appendChild(menu);

  // Position near the click
  const mw = menu.offsetWidth, mh = menu.offsetHeight;
  let left = event.clientX, top = event.clientY;
  if (left + mw > window.innerWidth - 8) left = window.innerWidth - mw - 8;
  if (top + mh > window.innerHeight - 8) top = event.clientY - mh - 4;
  menu.style.left = Math.max(8, left) + 'px';
  menu.style.top  = Math.max(8, top)  + 'px';

  menu.addEventListener('click', ev => {
    const btn = ev.target.closest('.layout-slot-menu-item');
    if (!btn) return;
    const act = btn.dataset.act;
    _closeBarContextMenu();
    invalidateFilterCache();

    if (act === 'include') {
      if (isIncluded) {
        entry.included.delete(rawKey);
        entry.includedFromPreset?.delete(rawKey);
      } else {
        entry.excluded.delete(rawKey);
        entry.excludedFromPreset?.delete(rawKey);
        entry.included.add(rawKey);
        if (entry.mode === 'neutral') entry.mode = 'include';
      }
    } else if (act === 'exclude') {
      if (isExcluded) {
        entry.excluded.delete(rawKey);
        entry.excludedFromPreset?.delete(rawKey);
      } else {
        entry.included.delete(rawKey);
        entry.includedFromPreset?.delete(rawKey);
        entry.excluded.add(rawKey);
        if (entry.mode === 'neutral') entry.mode = 'exclude';
      }
    }
    _syncChipModeButtons(chipKey);
    // Phase 3 : bar context menu mute un chip live → sync slot preset actif.
    _syncLiveSlotFromActiveChips();
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
    render();
  });

  // Close on outside click / Escape
  const closeHandler = ev => {
    if (!ev.target.closest('#bar-ctx-menu')) { _closeBarContextMenu(); cleanup(); }
  };
  const escHandler = ev => {
    if (ev.key === 'Escape') { _closeBarContextMenu(); cleanup(); }
  };
  const cleanup = () => {
    document.removeEventListener('click', closeHandler, true);
    document.removeEventListener('keydown', escHandler);
    window.removeEventListener('scroll', _closeBarContextMenu, true);
  };
  setTimeout(() => {
    document.addEventListener('click', closeHandler, true);
    document.addEventListener('keydown', escHandler);
    window.addEventListener('scroll', _closeBarContextMenu, true);
  }, 0);
}

function _closeBarContextMenu() {
  document.getElementById('bar-ctx-menu')?.remove();
}

// Cell-combo context menu for heatmaps (Pair × Session, Session × Day).
// comboType: 'sessionDay' | 'pairSession'. comboKey: "A|B" string.
function _showCellComboContextMenu(comboType, comboKey, cellLabel, event) {
  _closeBarContextMenu();
  const entry = appState.filters.comboFilters?.[comboType];
  if (!entry) return;

  const isIncluded = entry.included.has(comboKey);
  const isExcluded = entry.excluded.has(comboKey);

  const menu = document.createElement('div');
  menu.id = 'bar-ctx-menu';
  menu.className = 'layout-slot-menu';
  menu.innerHTML = `
    <div style="padding:4px 12px 3px;font-size:9px;color:var(--dim);letter-spacing:.5px;text-transform:uppercase">${_escapeHtml(cellLabel)}</div>
    <div class="layout-slot-menu-sep"></div>
    <button class="layout-slot-menu-item bcm-include${isIncluded ? ' bcm-active' : ''}" type="button" data-act="include">
      <span class="lsm-icon">＋</span><span>${isIncluded ? 'Remove Include' : 'Include'}</span>
    </button>
    <button class="layout-slot-menu-item bcm-exclude${isExcluded ? ' bcm-active' : ''}" type="button" data-act="exclude">
      <span class="lsm-icon">−</span><span>${isExcluded ? 'Remove Exclude' : 'Exclude'}</span>
    </button>
  `;
  document.body.appendChild(menu);

  const mw = menu.offsetWidth, mh = menu.offsetHeight;
  let left = event.clientX, top = event.clientY;
  if (left + mw > window.innerWidth - 8) left = window.innerWidth - mw - 8;
  if (top + mh > window.innerHeight - 8) top = event.clientY - mh - 4;
  menu.style.left = Math.max(8, left) + 'px';
  menu.style.top  = Math.max(8, top)  + 'px';

  menu.addEventListener('click', ev => {
    const btn = ev.target.closest('.layout-slot-menu-item');
    if (!btn) return;
    const act = btn.dataset.act;
    _closeBarContextMenu();
    invalidateFilterCache();
    if (act === 'include') {
      if (isIncluded) entry.included.delete(comboKey);
      else { entry.excluded.delete(comboKey); entry.included.add(comboKey); }
    } else if (act === 'exclude') {
      if (isExcluded) entry.excluded.delete(comboKey);
      else { entry.included.delete(comboKey); entry.excluded.add(comboKey); }
    }
    _syncLiveSlotFromActiveChips();
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
    render();
  });

  const closeHandler = ev => {
    if (!ev.target.closest('#bar-ctx-menu')) { _closeBarContextMenu(); cleanup(); }
  };
  const escHandler = ev => {
    if (ev.key === 'Escape') { _closeBarContextMenu(); cleanup(); }
  };
  const cleanup = () => {
    document.removeEventListener('click', closeHandler, true);
    document.removeEventListener('keydown', escHandler);
    window.removeEventListener('scroll', _closeBarContextMenu, true);
  };
  setTimeout(() => {
    document.addEventListener('click', closeHandler, true);
    document.addEventListener('keydown', escHandler);
    window.addEventListener('scroll', _closeBarContextMenu, true);
  }, 0);
}

// Multi-dimension version used by heatmap cells (Pair × Session, Session × Day).
// `dims` = array of { chipKey, rawKey, displayLabel, dimLabel }
function _showHeatmapContextMenu(dims, cellLabel, event) {
  _closeBarContextMenu();
  if (!dims || !dims.length) return;

  // _resolveChipEntry routes 'custom:<key>' chipKeys to appState.filters.customChips
  // while leaving native chip keys on appState.filters.chips — enables future
  // Phase 2 widgets grouped by a custom prop to invoke this menu transparently.
  const dimStates = dims.map(d => {
    const entry = _resolveChipEntry(d.chipKey);
    return entry ? {
      ...d,
      entry,
      isIncluded: entry.included.has(d.rawKey),
      isExcluded: entry.excluded.has(d.rawKey),
    } : null;
  }).filter(Boolean);
  if (!dimStates.length) return;

  const menu = document.createElement('div');
  menu.id = 'bar-ctx-menu';
  menu.className = 'layout-slot-menu';
  let html = `<div style="padding:4px 12px 3px;font-size:9px;color:var(--dim);letter-spacing:.5px;text-transform:uppercase">${_escapeHtml(cellLabel)}</div>`;
  dimStates.forEach((ds, i) => {
    html += '<div class="layout-slot-menu-sep"></div>';
    html += `<div style="padding:3px 12px 2px;font-size:9px;color:var(--mute)">${_escapeHtml(ds.dimLabel || ds.chipKey)}: ${_escapeHtml(ds.displayLabel)}</div>`;
    html += `<button class="layout-slot-menu-item bcm-include${ds.isIncluded ? ' bcm-active' : ''}" type="button" data-dim="${i}" data-act="include">
      <span class="lsm-icon">＋</span><span>${ds.isIncluded ? 'Remove Include' : 'Include'}</span>
    </button>`;
    html += `<button class="layout-slot-menu-item bcm-exclude${ds.isExcluded ? ' bcm-active' : ''}" type="button" data-dim="${i}" data-act="exclude">
      <span class="lsm-icon">−</span><span>${ds.isExcluded ? 'Remove Exclude' : 'Exclude'}</span>
    </button>`;
  });
  menu.innerHTML = html;
  document.body.appendChild(menu);

  const mw = menu.offsetWidth, mh = menu.offsetHeight;
  let left = event.clientX, top = event.clientY;
  if (left + mw > window.innerWidth - 8) left = window.innerWidth - mw - 8;
  if (top + mh > window.innerHeight - 8) top = event.clientY - mh - 4;
  menu.style.left = Math.max(8, left) + 'px';
  menu.style.top  = Math.max(8, top)  + 'px';

  menu.addEventListener('click', ev => {
    const btn = ev.target.closest('.layout-slot-menu-item');
    if (!btn) return;
    const act = btn.dataset.act;
    const di = parseInt(btn.dataset.dim, 10);
    const ds = dimStates[di];
    if (!ds) return;
    _closeBarContextMenu();
    invalidateFilterCache();
    const { entry, rawKey, isIncluded, isExcluded } = ds;
    if (act === 'include') {
      if (isIncluded) { entry.included.delete(rawKey); entry.includedFromPreset?.delete(rawKey); }
      else {
        entry.excluded.delete(rawKey);
        entry.excludedFromPreset?.delete(rawKey);
        entry.included.add(rawKey);
        if (entry.mode === 'neutral') entry.mode = 'include';
      }
    } else if (act === 'exclude') {
      if (isExcluded) { entry.excluded.delete(rawKey); entry.excludedFromPreset?.delete(rawKey); }
      else {
        entry.included.delete(rawKey);
        entry.includedFromPreset?.delete(rawKey);
        entry.excluded.add(rawKey);
        if (entry.mode === 'neutral') entry.mode = 'exclude';
      }
    }
    _syncChipModeButtons(ds.chipKey);
    // Phase 3 : multi-dim context menu mute un chip live → sync slot actif.
    _syncLiveSlotFromActiveChips();
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    if (typeof openTunePanel === 'number') buildTunePanel(openTunePanel);
    render();
  });

  const closeHandler = ev => {
    if (!ev.target.closest('#bar-ctx-menu')) { _closeBarContextMenu(); cleanup(); }
  };
  const escHandler = ev => {
    if (ev.key === 'Escape') { _closeBarContextMenu(); cleanup(); }
  };
  const cleanup = () => {
    document.removeEventListener('click', closeHandler, true);
    document.removeEventListener('keydown', escHandler);
    window.removeEventListener('scroll', _closeBarContextMenu, true);
  };
  setTimeout(() => {
    document.addEventListener('click', closeHandler, true);
    document.addEventListener('keydown', escHandler);
    window.addEventListener('scroll', _closeBarContextMenu, true);
  }, 0);
}

function _initBarModeUI() {
  document.getElementById('bmt-total')?.classList.toggle('active', barMode === 'total');
  document.getElementById('bmt-ev')   ?.classList.toggle('active', barMode === 'ev');
  document.getElementById('bmt-wr')   ?.classList.toggle('active', barMode === 'wr');
  document.getElementById('mob-bmt-total')?.classList.toggle('active', barMode === 'total');
  document.getElementById('mob-bmt-ev')   ?.classList.toggle('active', barMode === 'ev');
}

function _initBarViewUI() {
  document.getElementById('bvt-global')?.classList.toggle('active', barView === 'global');
  document.getElementById('bvt-split') ?.classList.toggle('active', barView === 'split');
  document.getElementById('mob-bvt-global')?.classList.toggle('active', barView === 'global');
  document.getElementById('mob-bvt-split') ?.classList.toggle('active', barView === 'split');
}

function setBarColorMode(mode) {
  barColorMode = mode;
  localStorage.setItem(BAR_COLOR_MODE_KEY, mode);
  // Update radio UI
  document.querySelectorAll('input[name="barColorMode"]').forEach(r => {
    r.checked = (r.value === mode);
  });
  // Re-render all bar charts
  const filtered = getFiltered();
  const absMax = 1.8;
  renderBars('bars-setup',   groupByEV(filtered, t => setupDetailMode ? (t.setupDetail||t.setup) : t.setup, k => setupDetailMode ? k : (SETUP_SHORT[k]||k)), absMax, false, 'setup');
  renderBars('bars-session', groupByEV(filtered, t => t.session, k => SESSION_SHORT[k] || k), absMax, false, 'session');
  renderBars('bars-pair',    groupByEV(filtered, t => t.pair),   absMax, false, 'pair');
  renderDayBars(filtered);
  renderObsBars(filtered);
  renderH4ObsBars(filtered);
  renderHourBars(filtered);
  if (_isMobile()) {
    drawMobilePair(filtered);
    drawMobileSetup(filtered);
    drawMobileObs(filtered);
    drawMobileMonthly2(filtered);
  }
}

function _initBarColorModeUI() {
  document.querySelectorAll('input[name="barColorMode"]').forEach(r => {
    r.checked = (r.value === barColorMode);
  });
}

