// Current live theme (clone of default, may be overwritten by localStorage)
let currentTheme = { ...THEME_DEFAULT };

// ══ USER THEMES — up to 5 named custom slots, mirrors the preset CRUD pattern ══
const USER_THEMES_MAX = 5;
const USER_THEMES_LS_KEY = 'flipping_user_themes';
const ACTIVE_THEME_META_KEY = 'flipping_active_theme_meta';
const BUILTIN_OVERRIDES_KEY = 'flipping_builtin_overrides';
let USER_THEMES = [];
let _activeUserThemeId = null;

function _persistActiveThemeMeta() {
  try {
    localStorage.setItem(ACTIVE_THEME_META_KEY, JSON.stringify({
      builtinIndex: _activeBuiltinThemeIndex,
      userId: _activeUserThemeId,
    }));
  } catch(e) {}
}

function _loadBuiltinOverrides() {
  try {
    const raw = localStorage.getItem(BUILTIN_OVERRIDES_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return (parsed && typeof parsed === 'object') ? parsed : {};
  } catch(e) { return {}; }
}
function _loadBuiltinOverride(i) {
  const all = _loadBuiltinOverrides();
  return (all && all[i] && typeof all[i] === 'object') ? all[i] : null;
}
function _saveBuiltinOverride(i, theme) {
  try {
    const all = _loadBuiltinOverrides();
    all[i] = theme;
    localStorage.setItem(BUILTIN_OVERRIDES_KEY, JSON.stringify(all));
  } catch(e) {}
}
function _clearBuiltinOverride(i) {
  try {
    const all = _loadBuiltinOverrides();
    if (all[i]) { delete all[i]; localStorage.setItem(BUILTIN_OVERRIDES_KEY, JSON.stringify(all)); }
  } catch(e) {}
}
let _activeBuiltinThemeIndex = null;

function loadUserThemes() {
  try {
    const raw = localStorage.getItem(USER_THEMES_LS_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return;
    USER_THEMES = parsed
      .filter(t => t && typeof t.id === 'number' && typeof t.name === 'string' && t.theme && typeof t.theme === 'object')
      .slice(0, USER_THEMES_MAX)
      .map(t => ({
        id: t.id,
        name: String(t.name).slice(0, 40),
        // Merge defaults so new vars are injected into old stored themes
        theme: { ...THEME_DEFAULT, ...t.theme },
        createdAt: t.createdAt || new Date().toISOString(),
      }));
    USER_THEMES.sort((a, b) => a.id - b.id);
    try { localStorage.setItem(USER_THEMES_LS_KEY, JSON.stringify(USER_THEMES)); } catch(e) {}
  } catch(e) { console.warn('[user-themes] load failed:', e.message); }
}

function saveUserThemes() {
  try { localStorage.setItem(USER_THEMES_LS_KEY, JSON.stringify(USER_THEMES)); } catch(e) {}
}

function _nextUserThemeId() {
  const used = new Set(USER_THEMES.map(t => t.id));
  for (let i = 0; i < USER_THEMES_MAX; i++) {
    if (!used.has(i)) return i;
  }
  return -1;
}

// ── Apply theme to :root ──
function applyThemeToCss(theme) {
  const root = document.documentElement;
  Object.entries(theme).forEach(([k, v]) => {
    root.style.setProperty(k, v);
  });
  // Derive alpha variants automatically
  const hexToRgb = h => {
    const r = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h.trim());
    return r ? `${parseInt(r[1],16)},${parseInt(r[2],16)},${parseInt(r[3],16)}` : null;
  };
  const derive = (key, alphas) => {
    const rgb = hexToRgb(theme[key]);
    if (!rgb) return;
    alphas.forEach(([suffix, a]) => root.style.setProperty(key+suffix, `rgba(${rgb},${a})`));
  };
  derive('--gold', [['2','.10'],['3','.20']]);
  derive('--g',    [['2','.08'],['3','.15']]);
  derive('--r',    [['2','.08'],['3','.16']]);
  derive('--a',    [['2','.09'],['3','.18']]);
  derive('--b',    [['2','.10']]);
  derive('--t',    [['2','.10']]);

  // sel / sel-border from gold
  const goldRgb = hexToRgb(theme['--gold']);
  if (goldRgb) {
    root.style.setProperty('--sel', `rgba(${goldRgb},.13)`);
    root.style.setProperty('--sel-border', `rgba(${goldRgb},.50)`);
  }
  // --mute from bg
  const bgRgb = hexToRgb(theme['--bg4'] || theme['--bg3']);
  if (bgRgb) root.style.setProperty('--mute', theme['--bg4'] || theme['--bg3']);

  updatePreviewBar(theme);
  updatePresetHighlight(theme);

  // Re-render everything (canvas + bars + table all pick up new CSS vars)
  if (typeof render === 'function') {
    render();
  }
}

function updatePreviewBar(theme) {
  const bar = document.getElementById('tp-preview');
  if (!bar) return;
  bar.style.background =
    `linear-gradient(90deg, ${theme['--gold']} 0%, ${theme['--g']} 33%, ${theme['--r']} 66%, ${theme['--bg4']} 100%)`;
}

// ── Build the panel UI ──
function buildThemePanel() {
  buildPresets();
  _initBarColorModeUI();
  _initBarModeUI();
  _initBarViewUI();
  _initNotionModeUI();
  _initTypoModeUI();
  buildColorSection('tp-bg-colors',        Object.entries(THEME_META).filter(([,m])=>m.group==='backgrounds'));
  buildColorSection('tp-border-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='borders'));
  buildColorSection('tp-text-colors',      Object.entries(THEME_META).filter(([,m])=>m.group==='text'));
  buildColorSection('tp-accent-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='accent'));
  buildColorSection('tp-state-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='states'));
  buildColorSection('tp-chart-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='chart'));
  buildColorSection('tp-component-colors', Object.entries(THEME_META).filter(([,m])=>m.group==='component'));
  buildTypographyControls();
  updatePreviewBar(currentTheme);
}

function buildPresets() {
  const cont = document.getElementById('tp-presets');
  if (!cont) return;
  cont.innerHTML = THEME_PRESETS.map((p, i) =>
    `<div class="tp-preset-swatch" id="tppreset-${i}" data-action="apply-theme-preset" data-theme-preset="${i}"
      style="background:${p.bg}">
      <div class="tp-swatch-dots">
        ${p.dots.map(c=>`<div class="tp-swatch-dot" style="background:${c}"></div>`).join('')}
      </div>
      <div class="tp-swatch-label">${p.name}</div>
    </div>`
  ).join('');
  updatePresetHighlight(currentTheme);
  buildUserThemes();
}

function buildUserThemes() {
  const cont = document.getElementById('tp-user-themes');
  if (!cont) return;
  if (!USER_THEMES.length) {
    cont.innerHTML = '';
    return;
  }
  cont.innerHTML = USER_THEMES.map(t => {
    const theme = t.theme || {};
    const dots = [theme['--gold'] || '#888', theme['--g'] || '#888', theme['--r'] || '#888'];
    const bg = theme['--bg'] || '#111';
    const nameSafe = _escAttr(t.name);
    return `<div class="tp-preset-swatch is-user" id="usertheme-${t.id}"
         data-action="apply-user-theme" data-user-theme="${t.id}"
         title="Right-click for options"
         style="background:${bg}">
      <div class="tp-swatch-dots">
        <div class="tp-swatch-dot" style="background:${dots[0]}"></div>
        <div class="tp-swatch-dot" style="background:${dots[1]}"></div>
        <div class="tp-swatch-dot" style="background:${dots[2]}"></div>
      </div>
      <div class="tp-swatch-label">${nameSafe}</div>
    </div>`;
  }).join('');
  updateUserThemeHighlight();
}

function _showUserThemeContextMenu(id, x, y) {
  const existing = document.getElementById('po-ctx-menu');
  if (existing) existing.remove();
  const menu = document.createElement('div');
  menu.className = 'po-ctx-menu';
  menu.id = 'po-ctx-menu';
  menu.style.left = x + 'px';
  menu.style.top  = y + 'px';

  const itemRename = document.createElement('div');
  itemRename.className = 'po-ctx-menu-item';
  itemRename.textContent = '✎ Rename';
  itemRename.addEventListener('mousedown', (e) => {
    e.preventDefault();
    e.stopPropagation();
    menu.remove();
    renameUserTheme(id);
  });
  menu.appendChild(itemRename);

  const itemDel = document.createElement('div');
  itemDel.className = 'po-ctx-menu-item po-ctx-menu-item--danger';
  itemDel.textContent = '✕ Delete';
  itemDel.addEventListener('mousedown', (e) => {
    e.preventDefault();
    e.stopPropagation();
    menu.remove();
    deleteUserTheme(id);
  });
  menu.appendChild(itemDel);

  document.body.appendChild(menu);
  setTimeout(() => {
    const closeMenu = (ev) => {
      if (ev.target.closest('#po-ctx-menu')) return;
      menu.remove();
      document.removeEventListener('mousedown', closeMenu);
      document.removeEventListener('contextmenu', closeMenu);
    };
    document.addEventListener('mousedown', closeMenu);
    document.addEventListener('contextmenu', closeMenu);
  }, 0);
}

function updateUserThemeHighlight() {
  document.querySelectorAll('#tp-user-themes .tp-preset-swatch').forEach(el => {
    el.classList.remove('active');
  });
  if (_activeUserThemeId !== null && _activeUserThemeId !== undefined) {
    const el = document.getElementById(`usertheme-${_activeUserThemeId}`);
    if (el) el.classList.add('active');
  }
}

function createUserTheme() {
  const id = _nextUserThemeId();
  if (id < 0) {
    showThemeToast(`Maximum ${USER_THEMES_MAX} custom themes allowed`, true);
    return;
  }
  const newTheme = {
    id,
    name: `My Theme ${id + 1}`,
    theme: { ...currentTheme },
    createdAt: new Date().toISOString(),
  };
  USER_THEMES.push(newTheme);
  USER_THEMES.sort((a, b) => a.id - b.id);
  saveUserThemes();
  buildUserThemes();
  showThemeToast(`"${newTheme.name}" created ✓`);
}

function applyUserTheme(id) {
  const t = USER_THEMES.find(x => x.id === id);
  if (!t) return;
  currentTheme = { ...THEME_DEFAULT, ...t.theme };
  // Update active-theme trackers BEFORE rebuilding rows so _baselineColor() uses the new slot
  _activeUserThemeId = id;
  _activeBuiltinThemeIndex = null;
  _persistActiveThemeMeta();
  applyThemeToCss(currentTheme);
  buildColorSection('tp-bg-colors',        Object.entries(THEME_META).filter(([,m])=>m.group==='backgrounds'));
  buildColorSection('tp-border-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='borders'));
  buildColorSection('tp-text-colors',      Object.entries(THEME_META).filter(([,m])=>m.group==='text'));
  buildColorSection('tp-accent-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='accent'));
  buildColorSection('tp-state-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='states'));
  buildColorSection('tp-chart-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='chart'));
  buildColorSection('tp-component-colors', Object.entries(THEME_META).filter(([,m])=>m.group==='component'));
  try { localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme)); } catch(e) {}
  updateUserThemeHighlight();
  updatePresetHighlight(currentTheme);
  updateSaveButtonLabel();
  showThemeToast(`"${t.name}" applied ✓`);
}

function renameUserTheme(id) {
  const t = USER_THEMES.find(x => x.id === id);
  if (!t) return;
  const newName = prompt('Rename theme:', t.name);
  if (!newName || !newName.trim()) return;
  t.name = newName.trim().slice(0, 40);
  saveUserThemes();
  buildUserThemes();
  updateSaveButtonLabel();
}

function deleteUserTheme(id) {
  const t = USER_THEMES.find(x => x.id === id);
  if (!t) return;
  _showUserThemeDeleteConfirm(id, t.name);
}

function _deleteUserThemeCommit(id) {
  const t = USER_THEMES.find(x => x.id === id);
  if (!t) return;
  USER_THEMES = USER_THEMES.filter(x => x.id !== id);
  if (_activeUserThemeId === id) _activeUserThemeId = null;
  saveUserThemes();
  buildUserThemes();
  updateSaveButtonLabel();
  showThemeToast('Theme deleted ✓');
}

function _showUserThemeDeleteConfirm(id, name) {
  document.getElementById('po-delete-backdrop')?.remove();
  const backdrop = document.createElement('div');
  backdrop.id = 'po-delete-backdrop';
  backdrop.className = 'layout-confirm-backdrop';
  backdrop.innerHTML = `
    <div class="layout-confirm-modal" role="dialog" aria-modal="true">
      <div class="layout-confirm-head">
        <span class="layout-confirm-icon">⚠</span>
        <span class="layout-confirm-title">Delete theme</span>
      </div>
      <div class="layout-confirm-body">
        <div class="layout-confirm-sub">Are you sure you want to delete <span class="layout-confirm-name">"${_escapeHtml(name)}"</span>?</div>
        <div class="layout-confirm-sub" style="margin-top:4px;opacity:.6">This action cannot be undone.</div>
      </div>
      <div class="layout-confirm-actions">
        <button class="lt-btn layout-confirm-cancel" type="button">Cancel</button>
        <button class="lt-btn layout-confirm-ok layout-confirm-ok--danger" type="button">Delete</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  const close = () => { backdrop.remove(); document.removeEventListener('keydown', onKey); };
  const commit = () => { close(); _deleteUserThemeCommit(id); };
  backdrop.addEventListener('click', e => { if (e.target === backdrop) close(); });
  backdrop.querySelector('.layout-confirm-cancel').addEventListener('click', close);
  backdrop.querySelector('.layout-confirm-ok').addEventListener('click', commit);
  const onKey = e => {
    if (e.key === 'Escape') close();
    else if (e.key === 'Enter') commit();
  };
  document.addEventListener('keydown', onKey);
}

function exportUserTheme(id) {
  const t = USER_THEMES.find(x => x.id === id);
  if (!t) return;
  const payload = { name: t.name, theme: t.theme, exportedAt: new Date().toISOString() };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${t.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase() || 'theme'}.theme.json`;
  a.click();
  URL.revokeObjectURL(a.href);
}

function overwriteCurrentUserTheme() {
  if (_activeUserThemeId === null || _activeUserThemeId === undefined) {
    showThemeToast('No active custom theme to overwrite', true);
    return;
  }
  const t = USER_THEMES.find(x => x.id === _activeUserThemeId);
  if (!t) return;
  t.theme = { ...currentTheme };
  saveUserThemes();
  buildUserThemes();
  showThemeToast(`"${t.name}" updated ✓`);
}

function clearUserThemes() {
  USER_THEMES = [];
  _activeUserThemeId = null;
  saveUserThemes();
  buildUserThemes();
  updateSaveButtonLabel();
}

function updateSaveButtonLabel() {
  const btn = document.querySelector('[data-action="save-theme"]');
  const actions = document.getElementById('tp-user-theme-actions');
  const hasActive = _activeUserThemeId !== null && _activeUserThemeId !== undefined;
  const t = hasActive ? USER_THEMES.find(x => x.id === _activeUserThemeId) : null;
  if (btn) btn.textContent = t ? `💾 Save to "${t.name}"` : '💾 Save theme';
  if (actions) {
    actions.hidden = !t;
    actions.style.display = t ? '' : 'none';
  }
}

function updatePresetHighlight(/* theme */) {
  // Mirror updateUserThemeHighlight's pattern: trust the explicit tracker
  // (`_activeBuiltinThemeIndex`) instead of comparing every color of the
  // merged theme against each preset. The previous match-by-value approach
  // failed silently when the user had ANY saved override for the active
  // preset — the merged `currentTheme` no longer equalled `p.theme` exactly,
  // so the swatch dropped its `active` class and the user perceived the
  // click as "didn't work" (e.g. "I can't apply Equity Desk anymore").
  THEME_PRESETS.forEach((p, i) => {
    const el = document.getElementById('tppreset-'+i);
    if (!el) return;
    el.classList.toggle('active', i === _activeBuiltinThemeIndex);
  });
}

// Baseline value a color should revert to: the active theme's *saved* value.
// user slot > builtin override > builtin preset > THEME_DEFAULT.
function _baselineColor(varName) {
  if (_activeUserThemeId !== null && _activeUserThemeId !== undefined) {
    const t = USER_THEMES.find(x => x.id === _activeUserThemeId);
    if (t && t.theme && t.theme[varName] !== undefined) return t.theme[varName];
  }
  if (_activeBuiltinThemeIndex !== null && _activeBuiltinThemeIndex !== undefined) {
    const override = _loadBuiltinOverride(_activeBuiltinThemeIndex);
    if (override && override[varName] !== undefined) return override[varName];
    const preset = THEME_PRESETS[_activeBuiltinThemeIndex];
    if (preset && preset.theme && preset.theme[varName] !== undefined) return preset.theme[varName];
  }
  return THEME_DEFAULT[varName];
}

function buildColorSection(containerId, entries) {
  const cont = document.getElementById(containerId);
  if (!cont) return;
  cont.innerHTML = entries.map(([varName, meta]) => {
    const rawVal = currentTheme[varName] || '#000000';
    const val = /^#[0-9a-fA-F]{6}$/.test(rawVal) ? rawVal : '#000000';
    const safe = varName.replace(/--/g,'tp_').replace(/-/g,'_');
    const base = _baselineColor(varName);
    const isDefault = rawVal === base;
    return `<div class="tp-color-row">
      <span class="tp-color-label">${meta.label}</span>
      <input class="tp-color-hex" id="${safe}_hex" type="text" maxlength="7"
        value="${rawVal.toUpperCase()}" data-theme-input="hex" data-theme-var="${varName}" data-theme-safe="${safe}">
      <input class="tp-color-picker" id="${safe}_pick" type="color" value="${val}" data-theme-input="picker" data-theme-var="${varName}" data-theme-safe="${safe}">
      <button type="button" class="tp-color-reset${isDefault ? ' is-default' : ''}"
        data-action="reset-color" data-theme-var="${varName}" data-theme-safe="${safe}"
        title="Reset to ${base ? String(base).toUpperCase() : 'n/a'}"
        ${base ? '' : 'disabled'}>↺</button>
    </div>`;
  }).join('');
}

function resetColor(varName, safe) {
  const base = _baselineColor(varName);
  if (base === undefined) return;
  currentTheme[varName] = base;
  const hex = document.getElementById(safe+'_hex');
  const pick = document.getElementById(safe+'_pick');
  if (hex)  hex.value  = String(base).toUpperCase();
  if (pick && /^#[0-9a-fA-F]{6}$/.test(base)) pick.value = base;
  applyThemeToCss(currentTheme);
  const btn = document.querySelector(`.tp-color-reset[data-theme-safe="${safe}"]`);
  if (btn) btn.classList.add('is-default');
}

function _updateResetBtnState(varName, safe) {
  const btn = document.querySelector(`.tp-color-reset[data-theme-safe="${safe}"]`);
  if (!btn) return;
  btn.classList.toggle('is-default', currentTheme[varName] === _baselineColor(varName));
}

function onPickerInput(varName, safe) {
  const val = document.getElementById(safe+'_pick').value;
  document.getElementById(safe+'_hex').value = val.toUpperCase();
  currentTheme[varName] = val;
  applyThemeToCss(currentTheme);
  _updateResetBtnState(varName, safe);
}

function onHexInput(varName, safe) {
  const raw = document.getElementById(safe+'_hex').value.trim();
  const hex = raw.startsWith('#') ? raw : '#'+raw;
  if (!/^#[0-9a-fA-F]{6}$/.test(hex)) return;
  const picker = document.getElementById(safe+'_pick');
  if (picker) picker.value = hex;
  currentTheme[varName] = hex;
  applyThemeToCss(currentTheme);
  _updateResetBtnState(varName, safe);
}

function applyPresetTheme(i) {
  const preset = THEME_PRESETS[i];
  if (!preset) return;
  // Base on THEME_DEFAULT, override with preset colors, then apply saved user override if any.
  // Defensive filter: drop override keys whose value is invalid (non-hex, null, undefined)
  // — protects against contaminated overrides accumulated from past schema-mismatched saves
  // (the "click Equity Desk → reverts to TradingView" bug came from such a contaminated slot,
  // where a prior Save while currentTheme was out-of-sync with _activeBuiltinThemeIndex
  // wrote a wrong preset's colors into this slot).
  const rawOverride = _loadBuiltinOverride(i) || {};
  let override = {};
  Object.entries(rawOverride).forEach(([k, v]) => {
    if (typeof v === 'string' && /^#[0-9a-fA-F]{6}$/.test(v.trim())) override[k] = v;
    else if (typeof v === 'string' && v.trim()) override[k] = v;  // non-hex CSS values (e.g. font-size px) pass through
  });
  // Contamination detection: if the override would force --bg (the most
  // distinctive theme color) to match a DIFFERENT built-in preset's --bg, we
  // have an override that was accidentally saved with another preset's colors.
  // Drop the override and re-apply the pristine preset — otherwise the user's
  // click visibly snaps back to whichever preset shares that --bg.
  if (override['--bg'] && override['--bg'] !== preset.theme['--bg']) {
    const otherPreset = THEME_PRESETS.find((p, j) => j !== i && p.theme['--bg'] === override['--bg']);
    if (otherPreset) {
      _clearBuiltinOverride(i);
      override = {};
    }
  }
  currentTheme = { ...THEME_DEFAULT, ...preset.theme, ...override };
  // Update active-theme trackers BEFORE rebuilding rows so _baselineColor() uses the new preset
  _activeUserThemeId = null;
  _activeBuiltinThemeIndex = i;
  _persistActiveThemeMeta();
  applyThemeToCss(currentTheme);
  // Persist currentTheme so THEME_STORAGE_KEY stays in sync with the active preset.
  // applyUserTheme already does this for user themes; preset themes were missing the
  // mirror — without it, a subsequent Save would snapshot the freshly-applied colors
  // back into THE NEW preset's override slot only IF currentTheme was correct, but
  // any boot path that loads THEME_STORAGE_KEY (e.g. on next reload) would then revert
  // to the stale TradingView snapshot.
  try { localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme)); } catch(e) {}
  // Rebuild color rows to reflect new values
  buildColorSection('tp-bg-colors',        Object.entries(THEME_META).filter(([,m])=>m.group==='backgrounds'));
  buildColorSection('tp-border-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='borders'));
  buildColorSection('tp-text-colors',      Object.entries(THEME_META).filter(([,m])=>m.group==='text'));
  buildColorSection('tp-accent-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='accent'));
  buildColorSection('tp-state-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='states'));
  buildColorSection('tp-chart-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='chart'));
  buildColorSection('tp-component-colors', Object.entries(THEME_META).filter(([,m])=>m.group==='component'));
  buildTypographyControls();
  updateUserThemeHighlight();
  updateSaveButtonLabel();
}

// ── Settings panel ──
let accountPanelOpen = false;
let _accountPanelEscHandler = null;
let _accountPanelClickOutsideHandler = null;
let _accountRecoveryMode = false;
let _accountView = 'signed_out';

function _getDefaultAccountView() {
  if (_accountRecoveryMode) return 'reset_password';
  return window._SW?.getUser?.() ? 'signed_in' : 'signed_out';
}

function _setAccountAlert(text = '', tone = 'muted') {
  const alertEl = document.getElementById('account-alert');
  const textEl = document.getElementById('account-alert-text');
  if (!alertEl || !textEl) return;
  if (!text) {
    alertEl.setAttribute('hidden', '');
    alertEl.removeAttribute('data-tone');
    textEl.textContent = '';
    return;
  }
  alertEl.removeAttribute('hidden');
  alertEl.dataset.tone = tone;
  textEl.textContent = text;
}

function _clearAccountForms() {
  [
    'sw-email-input',
    'sw-password-input',
    'sw-forgot-email-input',
    'sw-currentpassword-input',
    'sw-newpassword-input',
    'sw-confirmpassword-input',
    'sw-recovery-newpassword-input',
    'sw-recovery-confirmpassword-input',
  ].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
}

function _togglePasswordVisibility(toggleEl) {
  const targetId = toggleEl?.dataset?.target;
  const input = targetId ? document.getElementById(targetId) : null;
  if (!input) return;
  const isHidden = input.type === 'password';
  input.type = isHidden ? 'text' : 'password';
  toggleEl.setAttribute('aria-pressed', isHidden ? 'true' : 'false');
  toggleEl.setAttribute('aria-label', isHidden ? 'Hide password' : 'Show password');
}

function _setAccountStatus(text, tone = 'muted') {
  const summaryEl = document.getElementById('account-section-summary');
  if (summaryEl) summaryEl.textContent = `● ${text}`;
  if (summaryEl) summaryEl.dataset.tone = tone;
}

function _renderLocalModeBadge() {
  const badge = document.getElementById('local-mode-badge');
  if (!badge) return;
  const hasUser = !!window._SW?.getUser?.();
  if (hasUser) {
    badge.classList.remove('is-visible');
    badge.setAttribute('hidden', '');
    return;
  }
  badge.removeAttribute('hidden');
  requestAnimationFrame(() => badge.classList.add('is-visible'));
}

function _setAccountView(nextView, options = {}) {
  const { preserveAlert = false, clearForms = false } = options;
  _accountView = nextView;
  if (!preserveAlert) _setAccountAlert();
  if (clearForms) _clearAccountForms();
  _renderAccountPanelAuthState();
}

async function _verifyAccountPassword(email, password) {
  if (!window.supabase) return { error: { message: 'Supabase not loaded' } };
  const verifier = window.supabase.createClient(_SB_URL, _SB_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const result = await verifier.auth.signInWithPassword({ email, password });
  try { await verifier.auth.signOut(); } catch (_) {}
  return result;
}

function _renderAccountPanelAuthState() {
  const user = window._SW?.getUser?.() ?? null;
  _renderLocalModeBadge();
  const resolvedView = _accountRecoveryMode ? 'reset_password' : _accountView;
  let activeView = resolvedView;
  if (!user) {
    if (_accountRecoveryMode) activeView = 'reset_password';
    else if (resolvedView === 'forgot_password') activeView = 'forgot_password';
    else activeView = 'signed_out';
  } else if (user && (resolvedView === 'signed_out' || resolvedView === 'forgot_password')) {
    activeView = 'signed_in';
  }

  _accountView = activeView;

  const viewIds = {
    signed_out: 'account-view-signed-out',
    signed_in: 'account-view-signed-in',
    edit_profile: 'account-view-edit-profile',
    forgot_password: 'account-view-forgot-password',
    reset_password: 'account-view-reset-password',
    change_password: 'account-view-change-password',
  };

  Object.entries(viewIds).forEach(([view, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (view === activeView) el.removeAttribute('hidden');
    else el.setAttribute('hidden', '');
  });

  const identityEmail = document.getElementById('account-identity-email');
  if (identityEmail) identityEmail.textContent = user?.email || '—';

  if (activeView === 'signed_in' || activeView === 'change_password') {
    _setAccountStatus('Connected', 'success');
  } else if (activeView === 'reset_password') {
    _setAccountStatus('Password recovery', 'warning');
  } else {
    _setAccountStatus('Local only', 'muted');
  }
  // Topbar Sign-In button — visible only for signed-out users so they always
  // have a one-click path back to the auth panel after dismissing it.
  const signinBtn = document.getElementById('topbar-signin-btn');
  if (signinBtn) signinBtn.style.display = user ? 'none' : 'inline-flex';
  _syncJournalProfileUI();
}

function toggleAccountPanel() {
  accountPanelOpen = !accountPanelOpen;
  const panel = document.getElementById('account-panel');
  const btn = document.getElementById('account-toggle-btn');
  panel?.classList.toggle('open', accountPanelOpen);
  btn?.classList.toggle('open', accountPanelOpen);
  if (accountPanelOpen) {
    _accountView = _getDefaultAccountView();
    _journalProfileManagerOpen = false;
    _journalProfileEditorOpen = false;
    _journalProfileEditorMode = 'create';
    _journalProfileEditingId = '';
    _journalProfileRowMenuOpenId = '';
    _journalProfileSwitcherOpen = false;
    // Signed-out users land on the Account tab so the sign-in form is the
    // first thing they see — covers both auto-open at boot and the topbar
    // Sign-In button click. Signed-in users keep their last-used tab.
    if (!window._SW?.getUser?.() && _settingsActiveTab !== 'account') {
      _setSettingsActiveTab('account');
    }
    _renderAccountPanelAuthState();
    // Refresh the Notion integration badge when opening the panel on the
    // Integrations tab — without this, the tab restored from localStorage
    // shows "Checking…" until the user manually re-clicks the tab button.
    if (_settingsActiveTab === 'integrations') {
      try { _checkNotionIntegrationStatus(); } catch (e) {}
    }
    setTimeout(() => {
      _accountPanelClickOutsideHandler = (e) => {
        if (!accountPanelOpen) return;
        const path = (e.composedPath && e.composedPath()) || [];
        const panel = document.getElementById('account-panel');
        const toggle = document.getElementById('account-toggle-btn');
        if (panel && path.includes(panel)) return;
        if (toggle && path.includes(toggle)) return;
        toggleAccountPanel();
      };
      _accountPanelEscHandler = (e) => {
        if (e.key === 'Escape' && accountPanelOpen) toggleAccountPanel();
      };
      document.addEventListener('click', _accountPanelClickOutsideHandler);
      document.addEventListener('keydown', _accountPanelEscHandler);
    }, 0);
  } else {
    _journalProfileManagerOpen = false;
    _journalProfileEditorOpen = false;
    _journalProfileEditorMode = 'create';
    _journalProfileEditingId = '';
    _journalProfileRowMenuOpenId = '';
    _journalProfileSwitcherOpen = false;
    if (_accountPanelClickOutsideHandler) {
      document.removeEventListener('click', _accountPanelClickOutsideHandler);
      _accountPanelClickOutsideHandler = null;
    }
    if (_accountPanelEscHandler) {
      document.removeEventListener('keydown', _accountPanelEscHandler);
      _accountPanelEscHandler = null;
    }
  }
}
document.addEventListener('click', e => {
  if (!_journalProfileSwitcherOpen) return;
  if (!_journalProfileRowMenuOpenId) return;
  if (e.target.closest('.journal-profile-row-menu')) return;
  if (e.target.closest('[data-action="journal-profile-row-menu-toggle"]')) return;
  _journalProfileRowMenuOpenId = '';
  _syncJournalProfileUI();
});
document.addEventListener('click', e => {
  if (!_notionIntegrationManageOpen) return;
  // Scope the in-wrap check to Notion's own card so a click inside the CSV
  // card's manage menu doesn't keep Notion's menu open as a side-effect.
  if (e.target.closest('.notion-integration-card .int-manage-wrap')) return;
  if (e.target.closest('[data-action="notion-integration-manage-toggle"]')) return;
  _notionIntegrationManageOpen = false;
  _syncJournalProfileUI();
});
document.addEventListener('click', e => {
  if (!_csvIntegrationManageOpen) return;
  if (e.target.closest('.csv-integration-card .int-manage-wrap')) return;
  if (e.target.closest('[data-action="csv-integration-manage-toggle"]')) return;
  _csvIntegrationManageOpen = false;
  _syncJournalProfileUI();
});

async function _handleAccountLogin() {
  const email = document.getElementById('sw-email-input')?.value.trim();
  const password = document.getElementById('sw-password-input')?.value || '';
  if (!email || !password) {
    _setAccountAlert('Enter your email and password.', 'danger');
    return;
  }
  _setAccountAlert('Logging in…', 'warning');
  const { error } = await _SW.signIn(email, password);
  if (error) {
    _setAccountAlert(
      error.message.includes('Invalid login') ? 'Invalid email or password.' : error.message,
      'danger'
    );
  }
}

async function _handleAccountSignup() {
  const email = document.getElementById('sw-email-input')?.value.trim();
  const password = document.getElementById('sw-password-input')?.value || '';
  if (!email || !password) {
    _setAccountAlert('Enter your email and password.', 'danger');
    return;
  }
  _setAccountAlert('Creating account…', 'warning');
  const { data, error } = await _SW.signUp(email, password);
  if (error) {
    _setAccountAlert(error.message, 'danger');
    return;
  }
  // Supabase's anti-enumeration idiom for "email already exists" when
  // "Confirm email" is on: data.user is returned but `identities` is empty.
  // Show the same success copy as a real new signup to avoid leaking the
  // existence of the account — but skip the misleading "check your email"
  // line since no email gets sent in that case.
  if (data?.user && Array.isArray(data.user.identities) && data.user.identities.length === 0) {
    _setAccountAlert('If this email is available, a confirmation link has been sent.', 'success');
    return;
  }
  // Expected path with "Confirm email" enabled in Supabase: user is created
  // but no session is established until the email link is clicked.
  if (data?.user && !data?.session) {
    _setAccountAlert('Account created — check your email to confirm before signing in.', 'success');
    return;
  }
  // Fallback: user + session both returned means "Confirm email" is OFF in
  // the Supabase project. Flag this loud so the operator (Max) notices the
  // project setting drifted — users would otherwise be auto-signed-in
  // without ever validating their email.
  if (data?.session) {
    console.warn('[Auth] signUp returned an active session — Supabase "Confirm email" is OFF. Enable it in Authentication → Providers → Email.');
    _setAccountAlert('Account created and signed in (email confirmation is disabled).', 'warning');
    return;
  }
  _setAccountAlert('Account created — check your email to confirm before signing in.', 'success');
}

async function _handleAccountSendResetLink() {
  const email = document.getElementById('sw-forgot-email-input')?.value.trim();
  if (!email) {
    _setAccountAlert('Enter your email first.', 'danger');
    return;
  }
  _setAccountAlert('Sending reset link…', 'warning');
  const { error } = await _SW.resetPassword(email);
  _setAccountAlert(error ? error.message : 'Reset link sent. Check your inbox.', error ? 'danger' : 'success');
}

async function _handleAccountUpdatePassword() {
  if (_accountView === 'reset_password') {
    const pwd = document.getElementById('sw-recovery-newpassword-input')?.value || '';
    const confirmPwd = document.getElementById('sw-recovery-confirmpassword-input')?.value || '';
    if (!pwd || pwd.length < 6) {
      _setAccountAlert('Password must be at least 6 characters.', 'danger');
      return;
    }
    if (pwd !== confirmPwd) {
      _setAccountAlert('New password and confirmation must match.', 'danger');
      return;
    }
    _setAccountAlert('Saving new password…', 'warning');
    const { error } = await _SW.updatePassword(pwd);
    if (error) {
      _setAccountAlert(error.message, 'danger');
      return;
    }
    _accountRecoveryMode = false;
    _setAccountAlert('Password updated. You can now sign in.', 'success');
    _setAccountView(_getDefaultAccountView(), { preserveAlert: true, clearForms: true });
    return;
  }

  const user = _SW.getUser();
  const currentPwd = document.getElementById('sw-currentpassword-input')?.value || '';
  const newPwd = document.getElementById('sw-newpassword-input')?.value || '';
  const confirmPwd = document.getElementById('sw-confirmpassword-input')?.value || '';
  if (!user?.email) {
    _setAccountView('signed_out', { clearForms: true });
    return;
  }
  if (!currentPwd) {
    _setAccountAlert('Enter your current password first.', 'danger');
    return;
  }
  if (!newPwd || newPwd.length < 6) {
    _setAccountAlert('New password must be at least 6 characters.', 'danger');
    return;
  }
  if (newPwd !== confirmPwd) {
    _setAccountAlert('New password and confirmation must match.', 'danger');
    return;
  }
  _setAccountAlert('Verifying current password…', 'warning');
  const { error: signInError } = await _verifyAccountPassword(user.email, currentPwd);
  if (signInError) {
    _setAccountAlert('Current password is incorrect.', 'danger');
    return;
  }
  _setAccountAlert('Saving new password…', 'warning');
  let { error } = await _SW.updatePassword(newPwd);
  if (error?.message && /Auth session missing/i.test(error.message)) {
    _setAccountAlert('Refreshing your session…', 'warning');
    const { error: refreshError } = await _SW.refreshSession(user.email, currentPwd);
    if (refreshError) {
      _setAccountAlert(refreshError.message, 'danger');
      return;
    }
    ({ error } = await _SW.updatePassword(newPwd));
  }
  if (error) {
    _setAccountAlert(error.message, 'danger');
    return;
  }
  _setAccountAlert('Password updated.', 'success');
  _setAccountView('signed_in', { preserveAlert: true, clearForms: true });
}

function _handleDeleteAccount() {
  document.getElementById('account-delete-backdrop')?.remove();
  const user = _SW.getUser?.();
  const email = user?.email || '';
  const backdrop = document.createElement('div');
  backdrop.id = 'account-delete-backdrop';
  backdrop.className = 'layout-confirm-backdrop';
  backdrop.innerHTML = `
    <div class="layout-confirm-modal" role="dialog" aria-modal="true">
      <div class="layout-confirm-head">
        <span class="layout-confirm-icon">⚠</span>
        <span class="layout-confirm-title">Delete account</span>
      </div>
      <div class="layout-confirm-body">
        ${email ? `<div class="layout-confirm-sub"><span class="layout-confirm-name">${_escapeHtml(email)}</span></div>` : ''}
        <div class="layout-confirm-sub" style="margin-top:4px">This will permanently delete your account and all associated data.</div>
        <div class="layout-confirm-sub" style="margin-top:4px;opacity:.6">This action cannot be undone.</div>
      </div>
      <div class="layout-confirm-actions">
        <button class="lt-btn layout-confirm-cancel" type="button">Cancel</button>
        <button class="lt-btn layout-confirm-ok layout-confirm-ok--danger" type="button">Delete account</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  const close = () => { backdrop.remove(); document.removeEventListener('keydown', onKey); };
  const commit = async () => {
    close();
    if (!user?.id) return;
    _setAccountAlert('Deleting account…', 'warning');
    try {
      const resp = await fetch(`${NOTION_OAUTH_BACKEND}/api/account/delete`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user_id: user.id }),
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    } catch (e) {
      console.warn('[Account] delete endpoint unavailable, proceeding with local cleanup:', e.message);
    }
    await _SW.signOut();
    _accountRecoveryMode = false;
    _wipeLocalStateAndReload();
  };
  backdrop.addEventListener('click', e => { if (e.target === backdrop) close(); });
  backdrop.querySelector('.layout-confirm-cancel').addEventListener('click', close);
  backdrop.querySelector('.layout-confirm-ok').addEventListener('click', commit);
  const onKey = e => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', onKey);
}
// Wipe every piece of local dashboard state (LS profiles, layouts, presets,
// cached trades, custom widgets, screenshots, mappings, …) + sessionStorage,
// then reload. Used by sign-out / delete-account so the dashboard comes back
// up in its brand-new-install state (Demo mode, no profiles, integrations
// shown as disconnected) — the auth session has already been killed by the
// caller, so `sb-*` keys can also be cleared. Remote Supabase data is left
// untouched on logout (user may sign back in) — delete-account handles its
// own remote cleanup upstream.
function _wipeLocalStateAndReload() {
  try { localStorage.clear(); } catch (e) {}
  try { sessionStorage.clear(); } catch (e) {}
  window.location.reload();
}

async function _handleAccountLogout() {
  _setAccountAlert('Logging out…', 'warning');
  await _SW.signOut();
  _accountRecoveryMode = false;
  _wipeLocalStateAndReload();
}

// Factory Reset — wipe everything (LS, sessionStorage, Supabase user_data,
// journal_profiles, notion_connections, notion-trades Storage blobs), sign
// out the auth session, and reload so the dashboard comes back up in its
// brand-new-install state (Demo mode, no profiles, default layout).
function _handleFactoryReset() {
  document.getElementById('account-factory-reset-backdrop')?.remove();
  const backdrop = document.createElement('div');
  backdrop.id = 'account-factory-reset-backdrop';
  backdrop.className = 'layout-confirm-backdrop';
  backdrop.innerHTML = `
    <div class="layout-confirm-modal" role="dialog" aria-modal="true">
      <div class="layout-confirm-head">
        <span class="layout-confirm-icon">⚠</span>
        <span class="layout-confirm-title">Factory Reset</span>
      </div>
      <div class="layout-confirm-body">
        <div class="layout-confirm-sub">This will wipe every piece of dashboard data tied to your account:</div>
        <div class="layout-confirm-sub" style="margin-top:6px;opacity:.8">
          • Notion integrations + journal profiles<br>
          • Layouts, presets, filters, custom widgets<br>
          • All cached trades + screenshots<br>
          • Cross-device sync state
        </div>
        <div class="layout-confirm-sub" style="margin-top:8px">You'll stay signed in. The dashboard reloads in its brand-new state — empty profiles, default layout, demo data.</div>
        <div class="layout-confirm-sub" style="margin-top:4px;opacity:.6">Your account itself stays untouched. This action cannot be undone.</div>
      </div>
      <div class="layout-confirm-actions">
        <button class="lt-btn layout-confirm-cancel" type="button">Cancel</button>
        <button class="lt-btn layout-confirm-ok layout-confirm-ok--danger" type="button">Factory Reset</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  const close = () => { backdrop.remove(); document.removeEventListener('keydown', onKey); };
  const commit = async () => {
    close();
    _setAccountAlert('Factory Reset in progress…', 'warning');
    // Supabase-side wipe (only runs when there's an auth session — local-only
    // users skip straight to the LS clear). Errors are non-blocking.
    try {
      const summary = await _SW.factoryReset();
      console.log('[FactoryReset] Supabase summary:', summary);
    } catch (e) {
      console.warn('[FactoryReset] Supabase wipe failed:', e?.message || e);
    }
    // Local wipe — preserve the Supabase auth token keys so the user stays
    // signed in across the reload. The Supabase JS client persists the
    // session at `sb-<projectRef>-auth-token` (+ a few helper keys); a blanket
    // localStorage.clear() would knock the user back to the sign-in page,
    // breaking the "stay logged in after Factory Reset" promise. Whitelist
    // anything starting with `sb-` (v2 convention) — narrow enough to spare
    // only the auth bag, broad enough to cover future helper keys.
    try {
      const keysToRemove = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!k) continue;
        if (k.startsWith('sb-')) continue;
        keysToRemove.push(k);
      }
      for (const k of keysToRemove) {
        try { localStorage.removeItem(k); } catch (e) {}
      }
    } catch (e) {}
    try { sessionStorage.clear(); } catch (e) {}
    // Reload — fresh module state + boot pipeline lands on Demo mode with
    // the auth session intact (account section still shows "Connected").
    window.location.reload();
  };
  backdrop.addEventListener('click', e => { if (e.target === backdrop) close(); });
  backdrop.querySelector('.layout-confirm-cancel').addEventListener('click', close);
  backdrop.querySelector('.layout-confirm-ok').addEventListener('click', commit);
  const onKey = e => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', onKey);
}

let settingsPanelOpen = false;
function toggleSettingsPanel() {
  settingsPanelOpen = !settingsPanelOpen;
  document.getElementById('settings-panel').classList.toggle('open', settingsPanelOpen);
  document.getElementById('settings-toggle-btn').classList.toggle('open', settingsPanelOpen);
  // Closing Settings also closes its Notion Properties sub-panel — keeps the
  // floating-panel surface consistent with how the user dismisses Settings.
  if (!settingsPanelOpen && typeof toggleNotionPropsPanel === 'function') {
    toggleNotionPropsPanel(true);
  }
}
document.addEventListener('click', e => {
  if (!settingsPanelOpen) return;
  const btn   = document.getElementById('settings-toggle-btn');
  const panel = document.getElementById('settings-panel');
  if (!btn?.contains(e.target) && !panel?.contains(e.target)) {
    settingsPanelOpen = false;
    panel?.classList.remove('open');
    btn?.classList.remove('open');
  }
});

