function _syncCreateWidgetTypeButtons() {
  document.querySelectorAll('.np-widget-creator-btn[data-cw-type]').forEach(btn => {
    const type = btn.getAttribute('data-cw-type');
    const isActive = !!_cwCreateFlowState.open && _cwCreateFlowState.type === type;
    const label = type === 'heatmap' ? 'Heatmap' : type === 'table' ? 'Table' : 'Bar Chart';
    btn.classList.toggle('is-active', isActive);
    btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    btn.innerHTML = `${_CW_TYPE_ICONS[type] || ''}<span class="cw-type-label">${isActive ? '✓ ' : ''}${label}</span>`;
  });
}

// ── Data Setup hero card ───────────────────────────────────────────────
// Populates the at-a-glance health card sitting above the tabs in the
// Data Hub panel. Reads from getActiveJournalProfile() + JOURNAL_DIMS
// coverage + FEATURE_REQS to compute trades / mapped / locked counts +
// coverage ring percentage. Safe no-op when the hero DOM is absent.
function _updateDataSetupHero() {
  const hero = document.getElementById('dsh-hero');
  if (!hero) return;
  const mode = localStorage.getItem(DS_KEY) || 'demo';
  const isAPI  = mode === 'api';
  const isDemo = mode === 'demo';
  const isCSV  = mode === 'csv';
  const profile = isAPI ? getActiveJournalProfile() : null;

  // ── Name + meta + connection dot ────────────────────────────────────
  const nameEl = document.getElementById('dsh-name');
  const metaEl = document.getElementById('dsh-meta');
  const dotEl  = document.getElementById('dsh-dot');
  if (isDemo) {
    if (nameEl) nameEl.textContent = 'Demo';
    if (metaEl) metaEl.textContent = 'Sample dataset · read-only';
    if (dotEl) dotEl.className = 'dsh-dot is-offline';
  } else if (isCSV) {
    const fmt = (typeof FORMAT_LABEL !== 'undefined' && _csvFormat) ? (FORMAT_LABEL[_csvFormat] || _csvFormat) : 'CSV';
    if (nameEl) nameEl.textContent = fmt;
    if (metaEl) metaEl.textContent = `CSV · ${(_lastCsvHeaders || []).length} columns`;
    if (dotEl) dotEl.className = 'dsh-dot is-offline';
  } else if (profile) {
    if (nameEl) nameEl.textContent = String(profile.name || '').trim() || 'Untitled Journal';
    const sync = profile.notionSyncState;
    let syncLabel = 'not synced';
    if (sync === 'synced')      syncLabel = `synced ${_formatNotionSyncAgoCompact ? _formatNotionSyncAgoCompact(profile.notionLastSync) : 'recently'}`;
    else if (sync === 'syncing')      syncLabel = 'syncing…';
    else if (sync === 'error')        syncLabel = 'sync failed';
    else if (sync === 'disconnected') syncLabel = 'disconnected';
    // Connection label resolved via the integrations registry so new types
    // (mt5 / ctrader / …) automatically get the right display name.
    const conn = getIntegration(profile).label;
    const dbTitle = String(profile.notionDatabaseTitle || '').trim();
    if (metaEl) {
      const line1 = `${_escapeHtml(conn)} · ${_escapeHtml(syncLabel)}`;
      metaEl.innerHTML = dbTitle
        ? `<span class="dsh-meta-line">${line1}</span><span class="dsh-meta-line dsh-meta-db">${_escapeHtml(dbTitle)}</span>`
        : `<span class="dsh-meta-line">${line1}</span>`;
    }
    if (dotEl) {
      const stateClass = sync === 'synced' ? 'is-live'
                       : sync === 'syncing' ? 'is-syncing'
                       : sync === 'error' || sync === 'disconnected' ? 'is-error'
                       : 'is-offline';
      dotEl.className = `dsh-dot ${stateClass}`;
    }
  } else {
    if (nameEl) nameEl.textContent = 'No source';
    if (metaEl) metaEl.textContent = 'Connect a Notion DB to start';
    if (dotEl) dotEl.className = 'dsh-dot is-offline';
  }

  // ── Trade count ─────────────────────────────────────────────────────
  const items = (appState.trades && appState.trades.items) || [];
  const tradesEl = document.getElementById('dsh-stat-trades');
  if (tradesEl) tradesEl.textContent = String(items.length);

  // ── Mapped count (excluding overrideOnly + multi-tp tier when not active) ─
  // Match the same logic the Mapping tab uses: a dim counts as "mapped" iff
  // its sample shows at least 1 populated trade OR (in CSV mode) a resolved
  // header exists. We exclude `overrideOnly` dims to keep the denominator
  // honest (those are opt-in extras, not part of the canonical 23).
  let totalDims = 0, mappedDims = 0;
  try {
    // Pre-compute the per-profile override map + auto-mapped set so we can
    // skip template-auto no-mapping dims from the coverage denominator (they
    // are irrelevant for the active template — see _renderMappingSectionsHtml).
    const apiOverridesForCov = (isAPI && typeof _getAPIFieldOverrides === 'function') ? (_getAPIFieldOverrides() || {}) : {};
    const autoMappedForCov   = (isAPI && typeof _getAutoMappedDims === 'function')    ? _getAutoMappedDims() : new Set();
    for (const dim of JOURNAL_DIMS) {
      if (dim.overrideOnly === true) continue;
      // Multi-TP is bonus territory — always excluded from the coverage
      // denominator regardless of the active TP mode. Users who have no
      // multi-TP properties in their journal shouldn't see their coverage
      // pulled down by tp1/tp2/tp3 they intentionally don't track.
      if (dim.tier === 'multi-tp') continue;
      // Skip ANY no-mapping dim (auto OR user manual) so the ring matches
      // what the Mapping panel actually shows (Optional 11/11, not 11/14).
      if (isAPI && typeof _isNoMappingValue === 'function' && _isNoMappingValue(apiOverridesForCov[dim.key])) continue;
      totalDims++;
      if (isCSV) {
        if (typeof _resolvedHeaderFor === 'function' && _resolvedHeaderFor(dim.key)) mappedDims++;
      } else if (isAPI) {
        // Match Mapping section semantics: a dim counts as mapped iff it has
        // a valid override (user OR template auto) OR — when no override is
        // set — the canonical name is auto-detected via populated trades.
        // A mapped column with zero populated trades still counts as mapped;
        // the per-widget empty state handles the no-data case. This keeps the
        // hero ring in lockstep with section counts (no more 15/16 when every
        // section reads 3/3 + 10/10 + 3/3).
        const ov = apiOverridesForCov[dim.key];
        if (ov) {
          mappedDims++;
        } else if (typeof _inspectDimInTrades === 'function') {
          const r = _inspectDimInTrades(dim.key);
          if (r && r.populated > 0) mappedDims++;
        }
      }
    }
  } catch (e) {
    // _inspectDimInTrades / _resolvedHeaderFor may not exist or throw on
    // edge cases (empty appState during boot). Fall back to placeholders.
  }
  const mappedEl = document.getElementById('dsh-stat-mapped');
  if (mappedEl) mappedEl.textContent = totalDims ? `${mappedDims}/${totalDims}` : '—';

  // ── Locked features count (from FEATURE_REQS) ───────────────────────
  // Multi-TP is bonus — never contributes to the locked count even when
  // the user has Multi TP mode selected with missing tp dims. Only
  // Personalised-TP gates a "locked" pill here.
  let lockedCount = 0;
  try {
    if (typeof FEATURE_REQS !== 'undefined') {
      const cfg = appState.ui?.tpConfig || {};
      if (cfg.mode === 'personalised' && FEATURE_REQS['personalised-tp']) {
        const { complete } = (typeof _getPersonalisedMappingStatus === 'function') ? _getPersonalisedMappingStatus() : { complete: true };
        if (!complete) lockedCount++;
      }
    }
  } catch (e) {}
  const lockedEl = document.getElementById('dsh-stat-locked');
  const lockedWrap = document.getElementById('dsh-stat-locked-wrap');
  if (lockedEl) lockedEl.textContent = String(lockedCount);
  if (lockedWrap) {
    lockedWrap.classList.toggle('is-bad', lockedCount > 0);
    // Hide the locked stat entirely when there's nothing locked — keeps the
    // hero clean for users on Single TP mode with no locked features.
    lockedWrap.hidden = lockedCount === 0;
  }

  // ── Coverage ring + label ───────────────────────────────────────────
  const pct = totalDims ? Math.round((mappedDims / totalDims) * 100) : 0;
  const ringFill = hero.querySelector('.dsh-ring-fill');
  const ringLabel = document.getElementById('dsh-ring-label');
  if (ringFill) {
    const C = 263.9; // 2πr for r=42
    const offset = C * (1 - pct / 100);
    ringFill.setAttribute('stroke-dashoffset', String(offset));
  }
  if (ringLabel) ringLabel.textContent = totalDims ? `${pct}%` : '—';

  // ── Custom fields + widgets counts ──────────────────────────────────
  // Profile-scoped via `loadCustomProps()` / `_loadCustomWidgetDefs()`,
  // so the hero reflects what the *active* profile has declared rather
  // than a global count (avoids confusing users juggling multiple
  // Notion profiles with different schema overlays).
  let customCount = 0, widgetCount = 0;
  try {
    if (typeof loadCustomProps === 'function') {
      const props = loadCustomProps();
      customCount = Array.isArray(props) ? props.length : 0;
    }
  } catch (e) {}
  try {
    if (typeof _loadCustomWidgetDefs === 'function') {
      const widgets = _loadCustomWidgetDefs();
      widgetCount = Array.isArray(widgets) ? widgets.length : 0;
    }
  } catch (e) {}
  const customEl  = document.getElementById('dsh-stat-custom');
  const widgetsEl = document.getElementById('dsh-stat-widgets');
  if (customEl)  customEl.textContent  = String(customCount);
  if (widgetsEl) widgetsEl.textContent = String(widgetCount);
}

function toggleDataHub(forceTab = null) {
  const btn = document.getElementById('data-hub-btn');
  const panel = document.getElementById('data-hub-panel');
  if (!btn || !panel) return;
  dataHubOpen = !dataHubOpen;
  panel.classList.toggle('open', dataHubOpen);
  btn.classList.toggle('open', dataHubOpen);
  btn.setAttribute('aria-expanded', dataHubOpen ? 'true' : 'false');

  if (dataHubOpen) {
    switchDataHubTab(forceTab || 'mapping');
    btn.classList.remove('is-first-import');
    try { updateAttentionButton(getHiddenWidgetsList()); } catch (e) {}
    try { updateJournalPanel(); } catch (e) {}
    try { _renderNotionPropsPanel(); } catch (e) {}
    try { _updateDataSetupHero(); } catch (e) {}
  } else {
    _closeAllRemapPickers();
    _closeGuidePanel();
    _closePropertyForm();
    _closeCreateWidgetBuilder();
    if (_npPendingDeleteId !== null) { _npPendingDeleteId = null; _renderCustomPropsList(); }
    // Phase 3 — reset Mapping accordion state so the next open re-applies
    // the "expand tiers with missing fields" default to a fresh session,
    // instead of carrying over a one-off collapse from the previous one.
    _resetOpenMappingTiers();
  }
}

function switchDataHubTab(tabName) {
  // Phase 2: 'health' merged into 'mapping' — keep the legacy name as an
  // alias so any persisted state or external caller passing 'health' lands
  // on the right tab instead of being silently ignored.
  if (tabName === 'health') tabName = 'mapping';
  if (!['mapping', 'custom', 'create-widget'].includes(tabName)) return;
  dataHubActiveTab = tabName;
  document.querySelectorAll('.dhp-tab').forEach(t => {
    const isActive = t.dataset.tab === tabName;
    t.classList.toggle('is-active', isActive);
    t.setAttribute('aria-selected', isActive ? 'true' : 'false');
  });
  document.querySelectorAll('.dhp-tab-panel').forEach(p => {
    p.classList.toggle('is-active', p.id === `dhp-panel-${tabName}`);
  });
  _closeAllRemapPickers();
  if (tabName !== 'custom') {
    _closePropertyForm();
    if (_npPendingDeleteId !== null) { _npPendingDeleteId = null; _renderCustomPropsList(); }
  }
  // Render the list of created widgets each time the Create Widget tab gets
  // shown, so additions/deletions made elsewhere stay in sync.
  if (tabName === 'create-widget' && typeof _renderCreateWidgetList === 'function') {
    _renderCreateWidgetList();
    _syncCreateWidgetTypeButtons();
  }
}

// Mirror the (hidden at <=1280px) #dhb-badge state onto the Data Hub
// button's title so users hovering the icon-only button still see what
// the hidden badge would show.
function _syncDataHubBtnTitle() {
  const btn   = document.getElementById('data-hub-btn');
  const badge = document.getElementById('dhb-badge');
  const txtEl = document.getElementById('dhb-badge-text');
  if (!btn || !badge) return;

  const state = badge.getAttribute('data-state') || 'idle';
  const text  = txtEl?.textContent?.trim() || '';

  const stateTip = {
    ok:   text || 'connected',
    warn: text ? `${text} — needs attention` : 'needs attention',
    idle: text.toLowerCase() === 'setup' ? 'setup required' : (text || 'idle'),
  }[state] || text;

  btn.setAttribute('title', `Data Setup — ${stateTip}`);
}

function updateDataHubBadge() {
  const badge = document.getElementById('dhb-badge');
  const badgeText = document.getElementById('dhb-badge-text');
  // Phase 2: the Health tab badge was retired alongside the Health tab.
  // Its missing-count signal now lives on the Mapping tab badge, since
  // Mapping is where the diagnostic and fix actions both happen.
  const tabMappingBadge = document.getElementById('dhp-tab-mapping-badge');
  if (!badge || !badgeText) return;

  const mode = localStorage.getItem(DS_KEY) || 'demo';
  const hidden = getHiddenWidgetsList() || [];
  const missingCount = hidden.length;

  if (mode === 'demo') {
    badge.dataset.state = 'ok';
    badgeText.textContent = 'Demo';
  } else if (missingCount === 0) {
    badge.dataset.state = 'ok';
    badgeText.textContent = 'OK';
  } else {
    badge.dataset.state = 'warn';
    badgeText.textContent = `${missingCount} to fix`;
  }

  if (tabMappingBadge) {
    if (missingCount > 0) {
      tabMappingBadge.textContent = String(missingCount);
      tabMappingBadge.classList.add('is-visible');
    } else {
      tabMappingBadge.classList.remove('is-visible');
    }
  }

  const tabCustomBadge = document.getElementById('dhp-tab-custom-badge');
  if (tabCustomBadge) {
    const count = (typeof loadCustomProps === 'function') ? loadCustomProps().length : 0;
    if (count > 0) {
      tabCustomBadge.textContent = String(count);
      tabCustomBadge.classList.add('is-visible');
    } else {
      tabCustomBadge.classList.remove('is-visible');
    }
  }

  _syncDataHubBtnTitle();
}

function triggerDataHubFirstImportPulse() {
  if (localStorage.getItem(DATA_HUB_ONBOARDED_KEY) === '1') return;
  const btn = document.getElementById('data-hub-btn');
  if (!btn) return;
  btn.classList.add('is-first-import');
  localStorage.setItem(DATA_HUB_ONBOARDED_KEY, '1');
  setTimeout(() => {
    document.getElementById('data-hub-btn')?.classList.remove('is-first-import');
  }, 10000);
}

document.addEventListener('mousedown', e => {
  if (!dataHubOpen) return;
  const btn = document.getElementById('data-hub-btn');
  const panel = document.getElementById('data-hub-panel');
  const guidePanel = document.getElementById('logo-guide-panel');
  if (!btn?.contains(e.target) && !panel?.contains(e.target) && !guidePanel?.contains(e.target)) {
    dataHubOpen = false;
    panel?.classList.remove('open');
    btn?.classList.remove('open');
    btn?.setAttribute('aria-expanded', 'false');
    _closeAllRemapPickers();
    _closeGuidePanel();
    _closePropertyForm();
    _closeCreateWidgetBuilder();
  }
});

document.addEventListener('input', e => {
  const searchEl = e.target.closest?.('#cw-create-search');
  if (!searchEl) return;
  _cwCreateFlowState.searchQuery = searchEl.value || '';
  _renderCreateWidgetBuilder();
});

// Per-dim extractor used by the API/Demo "inspection" view. Each function
// returns a human-readable sample string, or '' when the trade lacks the field.
const _JOURNAL_DIM_EXTRACTORS = {
  outcome:      t => t.outcome || '',
  r:            t => (t.r != null && Number.isFinite(Number(t.r))) ? String(t.r) : '',
  date:         t => t.date || '',
  pair:         t => t.pair || '',
  setup:        t => t.setup || '',
  setupDetail:  t => t.setupDetail || '',
  session:      t => t.session || '',
  day:          t => t.day || '',
  obstacles:    t => (Array.isArray(t.obstacles) && t.obstacles.length) ? t.obstacles.join(', ') : '',
  h4:           t => (Array.isArray(t.h4) && t.h4.length) ? t.h4.join(', ') : '',
  beManagement: t => (Array.isArray(t.beManagement) && t.beManagement.length) ? t.beManagement.join(', ') : '',
  hour:         t => (t.hour != null && Number.isFinite(Number(t.hour))) ? `${t.hour}h` : '',
  positionType: t => t.positionType || t.tradeType || '',
  direction:    t => t.direction || '',
  rrMax:        t => (t.rrMax != null && Number.isFinite(Number(t.rrMax))) ? String(t.rrMax) : '',
  // Multi TP realized-R fields (Phase 3.A). Mirrors rrMax — a missing entry
  // here makes _inspectDimInTrades short-circuit and the Mapping tab show
  // "no values detected" even when the data is correctly mapped.
  tp1_rr:       t => (t.tp1_rr != null && Number.isFinite(Number(t.tp1_rr))) ? String(t.tp1_rr) : '',
  tp2_rr:       t => (t.tp2_rr != null && Number.isFinite(Number(t.tp2_rr))) ? String(t.tp2_rr) : '',
  tp3_rr:       t => (t.tp3_rr != null && Number.isFinite(Number(t.tp3_rr))) ? String(t.tp3_rr) : '',
  badFeeling:   t => (t.badFeeling === true ? 'yes' : (t.badFeeling === false ? 'no' : '')),
  notionUrl:    t => t.notionUrl || '',
  // Screenshot URL fields. _normalizeAPITrade and CSV parsers both store the
  // resolved URL on these camelCase keys (TV share links are pre-rewritten to
  // the deterministic S3 PNG path; the *Orig pair preserves the original).
  img_m15:       t => t.imgM15 || '',
  img_h4_before: t => t.imgH4Before || '',
  img_m15_after: t => t.imgM15After || '',
};

// Scan the current in-memory trade set for a non-empty value on `dimKey`.
// Returns { sample, populated } — sample is the first non-empty value found.
function _inspectDimInTrades(dimKey) {
  const items = (appState.trades && appState.trades.items) || [];
  const extract = _JOURNAL_DIM_EXTRACTORS[dimKey];
  if (!extract || !items.length) return { sample: null, populated: 0 };
  let sample = null;
  let populated = 0;
  for (const t of items) {
    const v = extract(t);
    if (v && String(v).trim()) {
      populated++;
      if (sample === null) sample = String(v).trim();
    }
  }
  return { sample, populated };
}

function _renderOutcomeValueReportHTML(rawCache, source = null) {
  const report = _getOutcomeValueReport(rawCache, source);
  if (!report.detected.length) return '';
  const mapping = report.mapping || {};
  const autoMapped = report.autoMapped || {};
  const needsReview = report.needsReview || {};
  const rows = report.detected
    .map(([value, count]) => {
      const category = mapping[value] || 'Other';
      const options = OUTCOME_VALUE_CATEGORIES.map(cat =>
        `<option value="${_escapeHtml(cat)}"${cat === category ? ' selected' : ''}>${_escapeHtml(cat)}</option>`
      ).join('');
      const isUnmapped = !Object.prototype.hasOwnProperty.call(mapping, value);
      const suggestion = _suggestOutcomeCategory(value);
      const statusHtml = (Object.prototype.hasOwnProperty.call(autoMapped, value) || (suggestion && suggestion === category))
        ? '<span class="outcome-map-status is-auto">Auto-mapped</span>'
        : (Object.prototype.hasOwnProperty.call(needsReview, value)
            ? '<span class="outcome-map-status is-review">Needs review</span>'
            : '');
      return `<div class="outcome-map-row${isUnmapped ? ' is-unmapped' : ''}">
                <span class="outcome-map-value" title="${_escapeHtml(value)}">${_escapeHtml(value)}</span>
                <span class="outcome-map-count">×${count}</span>
                <span class="outcome-map-arrow">→</span>
                <select class="outcome-map-select" data-action="set-outcome-value-mapping" data-value="${_escapeHtml(value)}" aria-label="Map ${_escapeHtml(value)} outcome value">
                  ${options}
                </select>
                ${statusHtml}
              </div>`;
    }).join('');
  const unmappedHtml = report.unmapped.length
    ? `<div class="outcome-map-unmapped">
        <div class="outcome-map-subtitle">Unmapped values detected</div>
        <div class="outcome-map-unmapped-list">${report.unmapped.map(([value]) => `<span>${_escapeHtml(value)}</span>`).join('')}</div>
      </div>`
    : '';
  return `<div class="outcome-map-card">
            <div class="outcome-map-title">Detected Position Result values</div>
            <div class="outcome-map-list">${rows}</div>
            ${unmappedHtml}
          </div>`;
}

// Renders one Mapping row (a `<tr>` in the table) for a given dim. `st` is
// the status descriptor built by the caller (CSV branch / API+Demo branch).
// When `st.reportHtml` is set, an extra full-width `<tr>` follows the main one
// (used by the Position Result row to surface the outcome-value report).
function _renderMappingTableRow(dim, st) {
  const dimLabel = _getJournalDimLabel(dim);
  // REQUIRED tag dropped — required dims live inside the dedicated "Required"
  // tier accordion, so the per-row badge was redundant.
  const requiredBadge = '';
  const shownEsc = (st.shownIsRaw ? st.shown : _escapeHtml(st.shown || ''));
  const suffix = st.suffix || '';
  const pencil = st.pencilHtml || '';
  // Suppress the trailing value for is-missing — the chip reads cleanly as
  // "🔴 Label", matching the collapsed accordion summary's missing chip.
  // Every other status (ok/remapped/no-mapping) shows "— value · coverage".
  const valueBlock = (st.status !== 'is-missing')
    ? `<span class="ljp-chip-sep" aria-hidden="true">—</span><span class="ljp-chip-value">${shownEsc}</span>${suffix}`
    : '';
  // Status dot — pure CSS circle (no emoji) so baseline alignment is exact
  // and colour comes from theme tokens. is-no-mapping is now treated as a
  // user-mapped state (blue, same as is-remapped).
  // Five grid items per row → invisible columns shared across the list via
  // CSS subgrid: Dot · Label · Value · Coverage · Action. Empty rows still
  // emit empty placeholder spans so column widths line up across all rows.
  const coverage = st.coverageHtml || '';
  const mainRow = `<div class="ljp-mapping-row ${st.status}${st.rowClass ? ' ' + st.rowClass : ''}" data-dim-key="${_escapeHtml(dim.key)}">
    <span class="ljp-status-dot ${st.status}" aria-label="${_escapeHtml(st.statusTxt || '')}"></span>
    <span class="ljp-chip-label-col">
      <span class="ljp-chip-label">${_escapeHtml(dimLabel)}</span>${requiredBadge}
    </span>
    <span class="ljp-chip-value-col">${valueBlock}</span>
    <span class="ljp-chip-coverage-col">${coverage}</span>
    <span class="ljp-chip-action-col">${pencil}</span>
  </div>`;
  return st.reportHtml
    ? mainRow + `<div class="ljp-mapping-report-row">${st.reportHtml}</div>`
    : mainRow;
}

// Builds the full set of tier-grouped Mapping tables. `getStatusForDim(dim)`
// returns the per-row status descriptor (see _renderMappingTableRow), or
// `null` to skip the dim entirely (e.g. overrideOnly dims in non-API modes).
// Tracks which Mapping-tab tier accordions are open across re-renders. Null
// until first render (triggers "expand tiers with missing fields" default);
// then a Set of tier keys reflecting the user's interactive state. The toggle
// listener on `#ljp-list` keeps it in sync with `<details>` events so the
// renderer can rebuild innerHTML without losing user choice.
let _openMappingTiers = null;
// Parallel tracking for the nested Missing/Mapped sub-accordions. Keys are
// `"${tier}:${group}"`. Null sentinel → apply defaults (Missing open, Mapped
// closed unless it's the only group present).
let _openMappingGroups = null;
// Per-tier reveal state for the "no-mapping" hidden footer. Tier keys present
// in this Set are currently expanded. Default closed.
let _openHiddenSections = new Set();

// Reset the open state — called when the Data Hub closes so the next open
// re-applies defaults (tiers with missing fields expanded; Missing group
// expanded inside each) to a fresh session.
function _resetOpenMappingTiers() {
  _openMappingTiers = null;
  _openMappingGroups = null;
  _openHiddenSections = new Set();
}

function _renderMappingSectionsHtml(getStatusForDim) {
  // Preserve user-driven accordion state across re-renders without
  // depending on `toggle` events (which queue on `<details>` and may
  // not fire before the next innerHTML rewrite — see HTML spec on
  // ToggleEvent.bubbles / task source). Instead we snapshot which
  // accordions currently carry the `[open]` attribute directly from
  // the DOM right before rewriting.
  //
  // `_openMappingTiers === null` is a *sentinel* meaning "intentionally
  // unset — apply defaults" (set by _resetOpenMappingTiers on panel
  // close, or by initial module load). When null we SKIP the DOM
  // snapshot entirely so defaults can apply, even if stale `<details>`
  // elements still linger in DOM (closing the Data Hub hides but
  // doesn't wipe the panel's innerHTML).
  const useDefaults = _openMappingTiers === null;
  if (useDefaults) {
    _openMappingTiers = new Set();
    _openMappingGroups = new Set();
  } else {
    const list = document.getElementById('ljp-list');
    const existingAccs = list ? list.querySelectorAll('.ljp-tier-acc[data-tier]') : [];
    if (existingAccs.length > 0) {
      _openMappingTiers = new Set();
      existingAccs.forEach(acc => {
        if (acc.hasAttribute('open')) _openMappingTiers.add(acc.dataset.tier);
      });
    }
    const existingGroups = list ? list.querySelectorAll('.ljp-mapping-group[data-tier][data-group]') : [];
    if (existingGroups.length > 0) {
      _openMappingGroups = new Set();
      existingGroups.forEach(g => {
        if (g.hasAttribute('open')) _openMappingGroups.add(`${g.dataset.tier}:${g.dataset.group}`);
      });
    }
  }

  return MAPPING_TIER_SECTIONS.map(sect => {
    const sectDims = JOURNAL_DIMS.filter(d => d.tier === sect.tier);
    if (!sectDims.length) return '';

    // Walk the tier's dims twice — once to compute status + collect stats,
    // then again to render rows in the *desired display order*: missing
    // fields first (so they're at the top when the accordion expands),
    // followed by mapped fields, each group alphabetical by label.
    let mapped = 0, total = 0;
    const missingDims = [];
    const otherDims = [];
    const hiddenDims = [];  // is-no-mapping (USER manual): revealed via footer toggle
    for (const dim of sectDims) {
      const st = getStatusForDim(dim);
      if (!st) continue;
      // Template-auto no-mapping → fully invisible. The dim is irrelevant
      // for this template (e.g. session/hour/M15 obstacles on an H4 profile)
      // so we don't render it, don't count it, don't expose a toggle for it.
      // Reset all overrides will resurrect it if the user changes template.
      if (st.status === 'is-auto-no-mapping') continue;
      total++;
      if (st.status === 'is-ok' || st.status === 'is-remapped' || st.status === 'is-auto-mapped') {
        mapped++;
        otherDims.push({ dim, st, label: _getJournalDimLabel ? _getJournalDimLabel(dim) : (dim.label || dim.key) });
      } else if (st.status === 'is-missing') {
        missingDims.push({ dim, st, label: _getJournalDimLabel ? _getJournalDimLabel(dim) : (dim.label || dim.key) });
      } else if (st.status === 'is-no-mapping') {
        // User manually set "No Mapping" via pencil — footer toggle reveals
        // it so the user can revert without losing other overrides.
        hiddenDims.push({ dim, st, label: _getJournalDimLabel ? _getJournalDimLabel(dim) : (dim.label || dim.key) });
      } else {
        otherDims.push({ dim, st, label: _getJournalDimLabel ? _getJournalDimLabel(dim) : (dim.label || dim.key) });
      }
    }
    const byLabelAsc = (a, b) => a.label.localeCompare(b.label, undefined, { sensitivity: 'base' });
    missingDims.sort(byLabelAsc);
    otherDims.sort(byLabelAsc);
    const missingLabels = missingDims.map(x => x.label);

    // Each group (Missing / Mapped) is its own nested <details> with its own
    // chip list (own subgrid alignment). Defaults: Missing open; Mapped
    // closed unless it's the only group present (no missing → just show the
    // mapped list expanded so the user sees something).
    const missingHtml = missingDims.map(({ dim, st }) => _renderMappingTableRow(dim, st)).filter(Boolean).join('');
    const otherHtml   = otherDims.map(({ dim, st })   => _renderMappingTableRow(dim, st)).filter(Boolean).join('');
    const hiddenHtml  = hiddenDims.map(({ dim, st })  => _renderMappingTableRow(dim, st)).filter(Boolean).join('');

    const renderGroup = (groupKey, groupLabel, klass, rowsHtml, defaultOpen) => {
      if (!rowsHtml) return '';
      const stateKey = `${sect.tier}:${groupKey}`;
      const isGroupOpen = useDefaults ? defaultOpen : _openMappingGroups.has(stateKey);
      return `<details class="ljp-mapping-group ${klass}"${isGroupOpen ? ' open' : ''} data-tier="${_escapeHtml(sect.tier)}" data-group="${_escapeHtml(groupKey)}">
        <summary class="ljp-mapping-group-summary">
          <span class="ljp-tier-chev" aria-hidden="true"></span>
          <span class="ljp-tier-group-label">${_escapeHtml(groupLabel)}</span>
          <span class="ljp-tier-group-rule"></span>
        </summary>
        <div class="ljp-mapping-list" role="list">${rowsHtml}</div>
      </details>`;
    };

    // No-mapping rows live in a discreet footer toggle inside the tier body
    // — closed by default (the dim is irrelevant for the active template, no
    // reason to push it into the user's face). Re-open state is tracked in
    // `_openHiddenSections` so re-renders preserve user intent.
    const renderHiddenFooter = (tierKey, rowsHtml, n) => {
      if (!rowsHtml || n === 0) return '';
      const isOpen = _openHiddenSections.has(tierKey);
      const wordField = n === 1 ? 'field' : 'fields';
      const label = isOpen ? `Hide ${n} no-mapping ${wordField}` : `Show ${n} no-mapping ${wordField}`;
      return `<div class="ljp-mapping-hidden-section${isOpen ? ' is-open' : ''}" data-tier="${_escapeHtml(tierKey)}">
        <button class="ljp-mapping-hidden-toggle" data-action="toggle-hidden" data-tier="${_escapeHtml(tierKey)}">${_escapeHtml(label)}</button>
        <div class="ljp-mapping-hidden-rows ljp-mapping-list" role="list">${rowsHtml}</div>
      </div>`;
    };

    const hasMissingGroup = missingDims.length > 0;
    const hasMappedGroup  = otherDims.length   > 0;
    const onlyMapped = !hasMissingGroup && hasMappedGroup;

    const groupsHtml =
        renderGroup('missing', 'Missing', 'is-missing-group', missingHtml, /* defaultOpen */ true)
      + renderGroup('mapped',  'Mapped',  'is-mapped-group',  otherHtml,   /* defaultOpen */ onlyMapped)
      + renderHiddenFooter(sect.tier, hiddenHtml, hiddenDims.length);
    if (!groupsHtml) return '';

    // Multi-TP is bonus territory — never marked as missing/incomplete in
    // the accordion visuals. Required/Optional/Screenshots can still flash
    // red/orange when fields are missing; Multi-TP stays neutral so users
    // who don't track tp1/tp2/tp3 properties don't see false-positive
    // warnings on a feature they haven't opted into.
    const isMultiTpTier = sect.tier === 'multi-tp';
    const hasMissing = !isMultiTpTier && missingLabels.length > 0;
    const isOpen = _openMappingTiers.has(sect.tier);

    // Mini progress bar + count chip — same visual language as the Phase 1
    // hero ring (mapped vs total) so the summary reads at a glance.
    const pct = total ? Math.round((mapped / total) * 100) : 0;
    const fillClass = (total && mapped === total) ? ' is-full' : '';
    const countClass = isMultiTpTier
      ? 'is-bonus'
      : ((mapped === total) ? 'is-full' : (mapped === 0 ? 'is-bad' : 'is-partial'));
    const tierBar = `<div class="ljp-tier-bar"><div class="ljp-tier-bar-fill${fillClass}" style="width:${pct}%"></div></div>`;
    const tierCount = `<span class="ljp-tier-count ${countClass}">${mapped} / ${total}</span>`;

    // Strip the trailing " properties" / " mode (advanced)" suffix so the
    // accordion summary stays compact ("Required" instead of "Required
    // properties"). Keep the full title as the table aria-label for a11y.
    const shortTitle = sect.title
      .replace(/\s+properties$/i, '')
      .replace(/\s+mode\s*\(advanced\)$/i, '');

    const note = sect.note ? `<div class="csv-doc-multi-tp-note">${sect.note}</div>` : '';

    return `<details class="ljp-tier-acc${hasMissing ? ' has-missing' : ''}"${isOpen ? ' open' : ''} data-tier="${_escapeHtml(sect.tier)}">
      <summary class="ljp-tier-summary">
        <div class="ljp-tier-summary-main">
          <span class="ljp-tier-chev" aria-hidden="true"></span>
          <span class="ljp-tier-name">${_escapeHtml(shortTitle)}</span>
          ${tierBar}
          ${tierCount}
        </div>
      </summary>
      <div class="ljp-tier-body" aria-label="${_escapeHtml(sect.title)}">
        ${note}
        ${groupsHtml}
      </div>
    </details>`;
  }).filter(Boolean).join('');
}


function updateJournalPanel() {
  const panel = document.getElementById('data-hub-panel');
  const list  = document.getElementById('ljp-list');
  const fmtEl = document.getElementById('ljp-format');
  const subEl = document.getElementById('ljp-sub');
  const resetBtn = document.getElementById('ljp-reset-btn');
  if (!panel || !list || !fmtEl) return;

  // Skip wasted work when the Data Hub isn't open (re-rendered on next open).
  if (!panel.classList.contains('open')) return;

  // Refresh the Data Setup hero card on every panel update so trade counts,
  // mapped fields, locked features, and sync state stay accurate without
  // needing dedicated wiring at every mutation site.
  try { _updateDataSetupHero(); } catch (e) {}

  // Preserve an open remap picker across re-renders: every render() path
  // eventually calls updateJournalPanel() which rebuilds the list innerHTML.
  // Without this, clicking the pencil would destroy the picker a few ms
  // later when the next render arrives. We snapshot the open picker's
  // dim/scope, let the list rebuild, then reopen it on the fresh button.
  const openPencil = list.querySelector('.ljp-pencil-btn.open');
  const reopenDimKey = openPencil?.getAttribute('data-dim-key') || null;
  const reopenScope  = openPencil?.getAttribute('data-scope')  || null;
  const _reopenIfNeeded = () => {
    if (!reopenDimKey) return;
    const selector = `.ljp-pencil-btn[data-dim-key="${reopenDimKey}"]` +
                     (reopenScope ? `[data-scope="${reopenScope}"]` : '');
    const freshBtn = list.querySelector(selector);
    if (freshBtn) openRemapPicker(freshBtn);
  };

  // ── CSV mode: interactive mapping with remap pickers (existing behavior) ──
  // Gate on the active data source mode (DS_KEY) — _lastCsvHeaders / _csvFormat
  // persist after a switch to API/Demo so the user can switch back without
  // re-importing, but the panel must reflect the CURRENT mode, not the last
  // CSV that was loaded.
  if (localStorage.getItem(DS_KEY) === 'csv' && _lastCsvHeaders && _lastCsvHeaders.length && _csvFormat) {
    if (subEl) subEl.textContent = 'Which CSV column feeds each widget dimension.';
    if (resetBtn) resetBtn.style.display = '';
    fmtEl.innerHTML = `Format · <strong>${_escapeHtml(FORMAT_LABEL[_csvFormat] || _csvFormat)}</strong> · ${_lastCsvHeaders.length} columns`;
    const pencilSvg = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 1 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>';
    const getStatus = (dim) => {
      const declaredDefault = dim.defaults[_csvFormat];
      const isOverrideOnly  = dim.overrideOnly === true;
      const override = _csvColumnOverrides[dim.key];
      const resolved = _resolvedHeaderFor(dim.key);
      const ok = !!resolved;
      let status, statusTxt, shown, defaultNote = '';
      if (_isNoMappingValue(override)) {
        status = 'is-no-mapping'; statusTxt = 'no mapping'; shown = '— No Mapping —';
      } else if (isOverrideOnly) {
        status = override ? 'is-remapped' : 'is-missing';
        statusTxt = override ? 'remapped' : 'not mapped';
        shown = override || '— not mapped —';
      } else {
        status = override ? 'is-remapped' : (ok ? 'is-ok' : 'is-missing');
        statusTxt = override ? 'remapped' : (ok ? 'found' : 'missing');
        shown = override ? override : (resolved || declaredDefault);
        defaultNote = override ? ` <span class="ljp-mapping-default">(default: ${_escapeHtml(declaredDefault)})</span>` : '';
      }
      const outcomeReport = (dim.key === 'outcome' && Array.isArray(_lastCsvRows) && _lastCsvRows.length)
        ? _renderOutcomeValueReportHTML(_lastCsvRows, 'csv')
        : '';
      const pencil = `<button class="ljp-pencil-btn" data-action="open-remap-picker" data-dim-key="${_escapeHtml(dim.key)}" data-scope="journal" aria-label="Remap CSV column">${pencilSvg}</button>`;
      return { status, statusTxt, shown, suffix: defaultNote, coverageHtml: '', pencilHtml: pencil, reportHtml: outcomeReport };
    };
    list.innerHTML = _renderMappingSectionsHtml(getStatus);
    _reopenIfNeeded();
    return;
  }

  // ── API / Demo / no-CSV mode: inspection view ──
  // Walks the current in-memory trade set (built by _normalizeAPITrade for
  // Notion Live or by loadBuiltinCSV for Demo) and shows, for each dimension,
  // how many trades populated it + a sample value. In API mode the user can
  // also remap dimensions to any field present on the raw Notion payload.
  const items = (appState.trades && appState.trades.items) || [];
  const mode  = localStorage.getItem(DS_KEY) || 'demo';
  const isAPI = mode === 'api';
  const apiOverrides = isAPI ? _getAPIFieldOverrides() : {};
  const hasAPIOverrides = Object.keys(apiOverrides).length > 0;
  const rawCache = isAPI ? _getRawAPICache() : null;
  const rawReady = !!(rawCache && rawCache.length);
  // Pencil is always shown in API mode so the affordance is visible; the
  // picker itself handles the "raw cache not yet populated" case.
  const canRemap = isAPI;

  // Reset button toggles between CSV / API scope + visibility
  if (resetBtn) {
    if (isAPI) {
      resetBtn.style.display = hasAPIOverrides ? '' : 'none';
      resetBtn.textContent = '↺ Re-apply template defaults';
      resetBtn.dataset.action = 'reapply-template-defaults';
    } else {
      resetBtn.style.display = 'none';
      resetBtn.textContent = '↺ Reset all overrides';
      resetBtn.dataset.action = 'reset-csv-overrides';
    }
  }

  // ── No trades: show remap UI when we have raw API data, otherwise empty ─────
  // When Notion trades are fetched but 0 survive _normalizeAPITrade (field name
  // mismatch), items is empty but rawCache has the real data. In this case we
  // MUST still render the remap pickers — that is the only way the user can fix
  // the mapping. After they set an override, _reapplyAPIOverrides re-normalizes
  // from the raw cache automatically. Do NOT return early.
  if (!items.length && !(isAPI && rawReady)) {
    if (subEl) subEl.textContent = 'Which field feeds each widget dimension.';
    list.innerHTML = '<div class="csv-remap-empty">No data loaded.</div>';
    fmtEl.innerHTML = '';
    return;
  }

  const sourceLabel = mode === 'api'  ? 'Notion Live API'
                    : mode === 'demo' ? 'Demo dataset'
                    : 'Loaded data';
  if (subEl) {
    subEl.textContent = isAPI
      ? 'Which Notion API field feeds each widget dimension. Click ✎ to remap.'
      : 'Which field feeds each widget dimension (read-only).';
  }
  const isFetching = !!appState.settings?.dataSource?.loading;
  const fieldCount = isAPI
    ? (rawReady
        ? ` · ${_listAPIKeys(rawCache).length} fields available`
        : (isFetching
            ? ' · <em style="opacity:.65">loading fields…</em>'
            : ' · <em style="opacity:.65">fields unavailable — sync from Profiles</em>'))
    : '';
  const tradeCountLabel = items.length
    ? `${items.length} trades`
    : `<span style="color:var(--r);font-weight:600">0 trades matched</span> — map fields below`;
  fmtEl.innerHTML = `Source · <strong>${_escapeHtml(sourceLabel)}</strong> · ${tradeCountLabel}${fieldCount}`;

  const pencilSvg = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 1 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>';
  // Snapshot the auto-mapped dim set once per render to avoid N LS reads.
  // Empty in CSV/Demo mode (template auto-mapping only runs in Notion path).
  const autoMappedDims = isAPI ? _getAutoMappedDims() : new Set();
  const getStatus = (dim) => {
    const isOverrideOnly = dim.overrideOnly === true;
    // Demo has no user columns to map against — hide overrideOnly rows
    // entirely rather than render a dead "missing / no pencil" line.
    if (isOverrideOnly && !isAPI) return null;
    const { sample, populated } = _inspectDimInTrades(dim.key);
    const override = isAPI ? _getEffectiveApiOverride(dim.key) : apiOverrides[dim.key];
    const ok = populated > 0;
    const isAuto = autoMappedDims.has(dim.key);
    let status, statusTxt, shown, coverage;
    if (_isNoMappingValue(override)) {
      status = isAuto ? 'is-auto-no-mapping' : 'is-no-mapping';
      statusTxt = isAuto ? 'no mapping (auto)' : 'no mapping';
      shown = '— No Mapping —'; coverage = 'disabled';
    } else if (isOverrideOnly) {
      status = override ? (isAuto ? 'is-auto-mapped' : 'is-remapped') : 'is-missing';
      statusTxt = override ? (isAuto ? 'auto-mapped' : 'remapped') : 'not mapped';
      shown = sample || '— not mapped —';
      coverage = items.length ? (ok ? `${populated}/${items.length} trades` : 'awaiting mapping') : 'awaiting mapping';
    } else {
      status = override ? (isAuto ? 'is-auto-mapped' : 'is-remapped') : (ok ? 'is-ok' : 'is-missing');
      statusTxt = override ? (isAuto ? 'auto-mapped' : 'remapped') : (ok ? 'found' : 'missing');
      shown = sample || '—';
      coverage = items.length ? (ok ? `${populated}/${items.length} trades` : 'no values detected') : 'no trades yet';
    }
    const overrideNote = (override && !_isNoMappingValue(override))
      ? ` <span class="ljp-mapping-default">(field: <span class="ljp-field-name">${_escapeHtml(override)}</span>)</span>`
      : '';
    // Coverage ("100/100 trades") lives in its own grid column so the
    // counts align vertically across rows — easier to scan completeness.
    // Partial coverage (populated < total) gets an orange tint so the
    // user spots non-exact counts at a glance, AND becomes a clickable
    // button that opens the drawer with the missing trades listed.
    const isPartialCoverage = ok && items.length > 0 && populated < items.length;
    const missingCount = isPartialCoverage ? (items.length - populated) : 0;
    const coverageHtml = isPartialCoverage
      ? `<button type="button" class="ljp-mapping-coverage is-partial is-clickable" data-action="open-mapping-missing-trades" data-dim-key="${_escapeHtml(dim.key)}" title="Show the ${missingCount} trade${missingCount > 1 ? 's' : ''} without a value for this property">${_escapeHtml(coverage)}</button>`
      : `<span class="ljp-mapping-coverage">${_escapeHtml(coverage)}</span>`;
    // Outcome value-mapping UI: render whenever we're in API mode and the
    // dim is Position Result. `_renderOutcomeValueReportHTML` self-gates on
    // empty detected values, and `_getOutcomeValueReport` falls back to the
    // parsed-trades cache (outcomeRaw) when the in-memory raw cache is empty,
    // so the UI survives a page refresh without requiring a Sync first.
    const outcomeReport = (isAPI && dim.key === 'outcome')
      ? _renderOutcomeValueReportHTML(rawCache)
      : '';
    const pencilHtml = canRemap
      ? `<button class="ljp-pencil-btn" data-action="open-remap-picker" data-dim-key="${_escapeHtml(dim.key)}" data-scope="api-journal" aria-label="Remap API field">${pencilSvg}</button>`
      : '';
    return {
      status, statusTxt, shown,
      suffix: overrideNote,
      coverageHtml,
      pencilHtml, reportHtml: outcomeReport,
      rowClass: canRemap ? '' : 'is-readonly',
    };
  };
  // Detected-template banner — only appears in API mode when the
  // first-connect fingerprint matched one of the 5 shipped Flipping Market
  // templates. Hidden silently when no detection (CSV mode, Demo, manual
  // mapping, or an unknown schema).
  const detTpl = isAPI ? _getDetectedTemplate() : null;
  const bannerHtml = (detTpl && TEMPLATE_LABELS[detTpl]) ? `
    <div class="ljp-template-banner">
      <span class="ljp-template-banner-dot" aria-hidden="true"></span>
      <span class="ljp-template-banner-label">Auto-detected: <strong>${_escapeHtml(TEMPLATE_LABELS[detTpl])}</strong></span>
      <span class="ljp-template-banner-meta">canonical mapping applied</span>
    </div>` : '';
  list.innerHTML = bannerHtml + _renderMappingSectionsHtml(getStatus);

  _reopenIfNeeded();
}

function _getTradeFieldValueForWidgetProp(trade, key) {
  if (!trade) return null;
  if (key === 'hour') {
    return (trade.hour != null && Number.isFinite(Number(trade.hour))) ? `${trade.hour}h` : '';
  }
  const raw = (trade?.extras && Object.prototype.hasOwnProperty.call(trade.extras, key))
    ? trade.extras[key]
    : trade[key];
  if (Array.isArray(raw)) return raw.filter(v => v != null && String(v).trim() !== '').join(', ');
  return raw;
}

function _sampleAndCoverageFromTrades(key) {
  const items = Array.isArray(appState.trades?.items) ? appState.trades.items : [];
  let sampleValue = '';
  let coverageCount = 0;
  for (const t of items) {
    const raw = _getTradeFieldValueForWidgetProp(t, key);
    const str = raw == null ? '' : String(raw).trim();
    if (!str) continue;
    coverageCount++;
    if (!sampleValue) sampleValue = str.substring(0, 80);
  }
  return { sampleValue: sampleValue || '—', coverageCount, totalCount: items.length };
}

function _inferWidgetPropertyType(values, headerName = '') {
  const vals = (values || [])
    .map(v => (v == null ? '' : String(v).trim()))
    .filter(Boolean);
  if (!vals.length) return 'unknown';

  const header = String(headerName || '').trim().toLowerCase();
  const urlishHeader = /(url|link|screenshot|image|photo|file|media|attachment|notion)/i.test(header);
  const noteishHeader = /(note|notes|comment|comments|journal|description|desc|summary|analysis|review)/i.test(header);
  const dateishHeader = /(date|day|time|created|updated|month|year)/i.test(header);

  const isUrlLike = v => /^(https?:\/\/|www\.)/i.test(v)
    || /\.(png|jpe?g|gif|webp|svg|pdf|heic|mp4|mov)(\?.*)?$/i.test(v);
  if (urlishHeader || vals.every(isUrlLike)) return 'url/file';

  const isDateLike = v => {
    if (dateishHeader && /^\d{1,2}h$/.test(v.toLowerCase())) return false;
    return !Number.isNaN(Date.parse(v));
  };
  if (vals.every(isDateLike)) return 'date';

  const isNumberLike = v => {
    const n = Number(v.replace(',', '.'));
    return Number.isFinite(n) && v !== '';
  };
  if (vals.every(isNumberLike)) return 'number';

  const boolish = new Set(['true','false','1','0','yes','no','oui','non','x','✓']);
  if (vals.every(v => boolish.has(v.toLowerCase()))) return 'boolean';

  const inferred = _detectColumnType(vals);
  if (inferred === 'multi-select') return 'multi-select';
  if (inferred === 'date') return 'date';
  if (inferred === 'number') return 'number';
  if (noteishHeader) return 'text';
  return 'text';
}

function _isRecommendedWidgetProperty(headerName, inferredType, sampleValue = '') {
  const header = String(headerName || '').trim().toLowerCase();
  const sample = String(sampleValue || '').trim();
  if (inferredType === 'url/file') return false;
  if (/(screenshot|image|photo|file|media|attachment|url|link)/i.test(header)) return false;
  if (/(note|notes|comment|comments|description|summary|analysis|review)/i.test(header)) return false;
  if (sample.length > 120) return false;
  return true;
}

function _humanizeWidgetPropertyLabel(rawKey) {
  const key = String(rawKey || '').trim();
  if (!key) return '';
  return key
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, ch => ch.toUpperCase());
}

function _flattenApiWidgetValue(raw) {
  if (raw === null || raw === undefined) return '';
  if (Array.isArray(raw)) {
    return raw.map(_flattenApiWidgetValue).filter(Boolean).join(', ');
  }
  if (typeof raw === 'object') {
    // Notion formula / rollup wrappers — recurse into the inner discriminated
    // union so the type-tagged value is unwrapped:
    //   { type: 'formula', formula: { type: 'string', string: 'foo' } }
    //   { type: 'rollup',  rollup:  { type: 'number', number: 42 } }
    if (raw.formula && typeof raw.formula === 'object') return _flattenApiWidgetValue(raw.formula);
    if (raw.rollup  && typeof raw.rollup  === 'object') return _flattenApiWidgetValue(raw.rollup);
    // Notion formula/rollup leaf values keyed by their primitive type
    // (string/number/boolean/date). Checked BEFORE the generic `name`/`text`
    // handlers because a formula's inner shape never carries those keys but
    // does carry `string` / `number` / etc. directly.
    if (typeof raw.string === 'string')  return raw.string.trim();
    if (typeof raw.number === 'number'   && Number.isFinite(raw.number))  return String(raw.number);
    if (typeof raw.boolean === 'boolean') return raw.boolean ? 'true' : 'false';
    if (raw.date && typeof raw.date === 'object' && typeof raw.date.start === 'string') return raw.date.start;
    if ('name' in raw) return _flattenApiWidgetValue(raw.name);
    if ('plain_text' in raw) return _flattenApiWidgetValue(raw.plain_text);
    if ('text' in raw) return _flattenApiWidgetValue(raw.text);
    if ('value' in raw) return _flattenApiWidgetValue(raw.value);
    if (typeof raw.start === 'string') return raw.start;
    if (typeof raw.url === 'string') return raw.url;
    return '';
  }
  return String(raw).trim();
}

function _cleanOutcomeRawValue(raw) {
  return String(raw ?? '')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
function _flattenApiWidgetValues(raw) {
  if (raw === null || raw === undefined) return [];
  if (Array.isArray(raw)) {
    return raw.flatMap(_flattenApiWidgetValues).map(_cleanOutcomeRawValue).filter(Boolean);
  }
  if (typeof raw === 'object') {
    if ('name' in raw) return _flattenApiWidgetValues(raw.name);
    if ('plain_text' in raw) return _flattenApiWidgetValues(raw.plain_text);
    if ('text' in raw) return _flattenApiWidgetValues(raw.text);
    if ('value' in raw) return _flattenApiWidgetValues(raw.value);
    if (typeof raw.start === 'string') return [_cleanOutcomeRawValue(raw.start)].filter(Boolean);
    if (typeof raw.url === 'string') return [_cleanOutcomeRawValue(raw.url)].filter(Boolean);
    return [];
  }
  const value = _cleanOutcomeRawValue(raw);
  return value ? [value] : [];
}
function _normalizeOutcomeFieldKey(raw) {
  return String(raw || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '');
}
function _findOutcomeRawField(row, source = null) {
  if (!row || typeof row !== 'object') return '';
  if (source === 'csv') return _resolvedHeaderFor('outcome') || '';
  const activeSource = source || _getCurrentHTFSource();
  const override = (typeof _getEffectiveApiOverride === 'function') ? _getEffectiveApiOverride('outcome', activeSource) : '';
  if (override && !_isNoMappingValue(override) && Object.prototype.hasOwnProperty.call(row, override)) return override;

  const candidates = ['positionResult', 'resultatTp1', 'resultatTP1', 'Position Result'];
  for (const key of candidates) {
    if (Object.prototype.hasOwnProperty.call(row, key) && _flattenApiWidgetValues(row[key]).length) return key;
  }
  const preferred = Object.keys(row).find(key => {
    const norm = _normalizeOutcomeFieldKey(key);
    if (!/(position.*result|resultat|result|outcome)/.test(norm)) return false;
    return _flattenApiWidgetValues(row[key]).length > 0;
  });
  return preferred || '';
}
function _findOutcomeRawFieldInRows(rows, source = null) {
  const arr = Array.isArray(rows) ? rows : [];
  if (source === 'csv') return _resolvedHeaderFor('outcome') || '';
  const activeSource = source || _getCurrentHTFSource();
  const override = (typeof _getEffectiveApiOverride === 'function') ? _getEffectiveApiOverride('outcome', activeSource) : '';
  if (override && !_isNoMappingValue(override)) return override;

  const candidates = ['positionResult', 'resultatTp1', 'resultatTP1', 'Position Result'];
  for (const key of candidates) {
    if (arr.some(row => row && Object.prototype.hasOwnProperty.call(row, key) && _flattenApiWidgetValues(row[key]).length)) return key;
  }
  const keyOrder = [];
  const seen = new Set();
  arr.slice(0, 50).forEach(row => {
    if (!row || typeof row !== 'object') return;
    Object.keys(row).forEach(key => {
      if (!seen.has(key)) { seen.add(key); keyOrder.push(key); }
    });
  });
  return keyOrder.find(key => {
    const norm = _normalizeOutcomeFieldKey(key);
    if (!/(position.*result|resultat|result|outcome)/.test(norm)) return false;
    return arr.some(row => row && Object.prototype.hasOwnProperty.call(row, key) && _flattenApiWidgetValues(row[key]).length);
  }) || '';
}
function _resolveOutcomeRawValues(row, source = null, resolvedField = '') {
  if (!row || typeof row !== 'object') return [];
  if (source === 'csv') {
    const header = resolvedField || _resolvedHeaderFor('outcome');
    return header && Object.prototype.hasOwnProperty.call(row, header)
      ? _flattenApiWidgetValues(row[header])
      : [];
  }
  const field = resolvedField || _findOutcomeRawField(row, source);
  return field && Object.prototype.hasOwnProperty.call(row, field)
    ? _flattenApiWidgetValues(row[field])
    : [];
}

function _getOutcomeValueReport(rawRows = null, source = null) {
  const rows = Array.isArray(rawRows) ? rawRows : ((typeof _getRawAPICache === 'function') ? _getRawAPICache(source) : []);
  const counts = {};
  const unmappedCounts = {};
  const mapping = _loadOutcomeValueMapping();
  let skippedEmpty = 0;
  const outcomeField = _findOutcomeRawFieldInRows(rows, source);
  if (rows && rows.length && outcomeField) {
    for (const row of rows) {
      const values = _resolveOutcomeRawValues(row, source, outcomeField);
      if (!values.length) {
        skippedEmpty++;
        continue;
      }
      values.forEach(value => { counts[value] = (counts[value] || 0) + 1; });
    }
  } else {
    // Fallback: raw Notion cache wiped (page refresh — _persistRawAPIToSession
    // is a no-op by design, signed image URLs blow the LS quota). Walk the
    // parsed trades cache instead: `outcomeRaw` is persisted in the storage
    // key arrays so it survives across refreshes. Keeps the Position Result
    // value-mapping UI alive without forcing the user to click Sync first.
    const items = (appState && appState.trades && appState.trades.items) || [];
    for (const t of items) {
      const raw = String((t && t.outcomeRaw) || '').trim();
      if (!raw) { skippedEmpty++; continue; }
      counts[raw] = (counts[raw] || 0) + 1;
    }
  }
  const autoMapState = _applyOutcomeAutoMapping(Object.keys(counts), mapping);
  const effectiveMapping = autoMapState.mapping;
  Object.keys(counts).forEach(value => {
    if (!Object.prototype.hasOwnProperty.call(effectiveMapping, value)) {
      unmappedCounts[value] = counts[value];
    }
  });
  const normalizedUnique = [...new Set(Object.keys(counts).map(_normalizeOutcomeValueForAutoMap))].filter(Boolean).sort();
  debugLog('[OutcomeValueMapping] source field:', outcomeField || '(none)');
  debugLog('[OutcomeValueMapping] raw detected values:', { ...counts });
  debugLog('[OutcomeValueMapping] normalized unique values:', normalizedUnique);
  debugLog('[OutcomeValueMapping] skipped empty count:', skippedEmpty);
  debugLog('[OutcomeValueMapping] detected values:', { ...counts });
  debugLog('[OutcomeValueMapping] unmapped values:', { ...unmappedCounts });
  return {
    detected: Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
    unmapped: Object.entries(unmappedCounts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
    mapping: effectiveMapping,
    autoMapped: autoMapState.autoMapped,
    needsReview: autoMapState.needsReview,
  };
}

function _setOutcomeValueMapping(rawValue, category) {
  const value = String(rawValue || '').trim();
  const cat = _isValidOutcomeCategory(category) ? category : 'Other';
  if (!value) return;
  const mapping = _loadOutcomeValueMapping();
  mapping[value] = cat;
  _saveOutcomeValueMapping(mapping);

  const mode = localStorage.getItem(DS_KEY) || 'demo';
  if (mode === 'api') {
    _reapplyAPIOverrides();
  } else if (mode === 'csv') {
    _reparseCsvWithOverrides();
  } else {
    appState.trades.items.forEach(t => {
      const raw = t?.outcomeRaw || t?.outcome;
      if (String(raw || '').trim() === value) {
        t.outcome = _internalOutcomeForCategory(cat);
        t.r = _mapR(t.outcome, t.r);
      }
    });
    rebuildDimensions();
    render();
  }
  updateJournalPanel();
}

function _findApiKey(rawRows, ...candidates) {
  if (!Array.isArray(rawRows) || !rawRows.length) return null;
  const wanted = candidates.map(c => String(c || '').trim().toLowerCase()).filter(Boolean);
  if (!wanted.length) return null;
  const available = new Map();
  for (const row of rawRows.slice(0, 50)) {
    if (!row || typeof row !== 'object') continue;
    Object.keys(row).forEach(k => {
      const norm = String(k).trim().toLowerCase();
      if (!available.has(norm)) available.set(norm, k);
    });
  }
  for (const cand of wanted) {
    if (available.has(cand)) return available.get(cand);
  }
  return null;
}

const _WIDGET_API_DIM_CANDIDATES = {
  pair: ['pair', 'Pair', 'paire', 'Paire'],
  setup: ['M15 Confirmation / Continuation', 'M15 Confirmation / Continu', 'confirmation', 'Confirmation / Continunation', 'm15Type', 'M15 Type'],
  setupDetail: ['m15TypeDetail', 'M15 Type Detailed', 'm15TypeDetails', 'm15TypeDétail'],
  session: ['session', 'Session', 'sessionFormule', 'Session Formula'],
  day: ['jour', 'Jour'],
  obstacles: ['obstaclesM15', 'M15 Obstacles'],
  h4: ['obstaclesH4', 'H4 Obstacles'],
  beManagement: ['beManagement', 'BE Management'],
  outcome: ['positionResult', 'resultatTp1', 'resultatTP1', 'Position Result'],
  r: ['rrTp1', 'RR TP 1'],
  rrMax: ['rrMax', 'rrMaxAtteint', 'RR Max', 'RR Max ', 'RR max atteint'],
  direction: ['order', 'Order'],
  positionType: ['positionType', 'Position Type', 'tradeType'],
  badFeeling: ['badFeeling'],
  notionUrl: ['notionUrl', 'notionURL', 'pageUrl', 'pageURL', 'id'],
  hour: ['timeUtc1', 'timeUtcPlus1', 'Hour', 'Time (UTC+1)', 'Hour +1'],
  img_m15: ['imgM15', 'm15Before', 'm15Image', 'imageM15'],
  img_h4_before: ['imgH4Before', 'h4Before', 'h4Image', 'imageH4'],
  img_m15_after: ['imgM15After', 'm15After', 'm15AfterImage', 'imgH4After', 'h4After'],
  tp1_rr: ['rrTp1'],
  tp2_rr: ['rrTpMinus27', 'rrTp2'],
  tp3_rr: ['rrTpH4_0', 'rrTp3', 'rrTrailing'],
};

function _resolvedSourceFieldForDim(dimKey, ctx) {
  if (!ctx) return null;
  if (ctx.mode === 'csv') return _resolvedHeaderFor(dimKey);
  if (ctx.mode === 'api') {
    const override = _getEffectiveApiOverride(dimKey);
    if (_isNoMappingValue(override)) return null;
    if (override) return override;
    const candidates = _WIDGET_API_DIM_CANDIDATES[dimKey] || [dimKey];
    return _findApiKey(ctx.rawRows, ...candidates);
  }
  if (ctx.mode === 'demo') return dimKey;
  return null;
}

function getActiveDataSourceContext() {
  const mode = localStorage.getItem(DS_KEY) || 'demo';
  if (mode === 'csv') {
    return {
      mode: 'csv',
      label: 'CSV',
      customSectionTitle: 'CSV / Custom Fields',
      rawRows: Array.isArray(_lastCsvRows) ? _lastCsvRows : [],
      availableColumns: (Array.isArray(_lastCsvHeaders) ? _lastCsvHeaders : []).filter(Boolean).map(h => ({
        key: h,
        label: h,
      })),
    };
  }
  if (mode === 'api') {
    const rawRows = (typeof _getRawAPICache === 'function') ? _getRawAPICache() : [];
    const keys = typeof _listAPIKeys === 'function' ? _listAPIKeys(rawRows) : [];
    return {
      mode: 'api',
      label: 'API',
      customSectionTitle: 'API / Notion Fields',
      rawRows,
      availableColumns: keys.map(k => ({
        key: k,
        label: k,
      })),
    };
  }
  const rawRows = Array.isArray(appState?.trades?.items) ? appState.trades.items : [];
  const seen = new Set();
  const availableColumns = [];
  rawRows.slice(0, 50).forEach(row => {
    if (!row || typeof row !== 'object') return;
    Object.keys(row).forEach(k => {
      if (k === 'extras' || k === '_rawRowIndex') return;
      if (seen.has(k)) return;
      seen.add(k);
      availableColumns.push({ key: k, label: _humanizeWidgetPropertyLabel(k) });
    });
    if (row.extras && typeof row.extras === 'object') {
      Object.keys(row.extras).forEach(k => {
        if (seen.has(k)) return;
        seen.add(k);
        availableColumns.push({ key: k, label: _humanizeWidgetPropertyLabel(k) });
      });
    }
  });
  return {
    mode: 'demo',
    label: 'DEMO',
    customSectionTitle: 'Demo Fields',
    rawRows,
    availableColumns,
  };
}

function _getSourceColumnStats(ctx, colKey, headerLabel = '') {
  const rows = Array.isArray(ctx?.rawRows) ? ctx.rawRows : [];
  const totalCount = rows.length;
  const values = [];
  let sampleValue = '';
  let coverageCount = 0;
  for (const row of rows) {
    let raw;
    if (ctx.mode === 'csv') raw = row?.[colKey];
    else if (ctx.mode === 'api') raw = row?.[colKey];
    else raw = _getTradeFieldValueForWidgetProp(row, colKey);
    const str = ctx.mode === 'api' ? _flattenApiWidgetValue(raw) : (raw == null ? '' : String(raw).trim());
    if (!str) continue;
    coverageCount++;
    values.push(str);
    if (!sampleValue) sampleValue = str.substring(0, 80);
  }
  let inferredType = _inferWidgetPropertyType(values, headerLabel || colKey);
  if (ctx.mode === 'api' && rows.length) {
    const sampleRaw = rows.find(r => r && r[colKey] != null)?.[colKey];
    if (Array.isArray(sampleRaw)) inferredType = 'multi-select';
    else if (typeof sampleRaw === 'boolean') inferredType = 'boolean';
    else if (sampleRaw && typeof sampleRaw === 'object' && typeof sampleRaw.start === 'string') inferredType = 'date';
    else if (sampleRaw && typeof sampleRaw === 'object' && typeof sampleRaw.url === 'string') inferredType = 'url/file';
  }
  return {
    sampleValue: sampleValue || '—',
    coverageCount,
    totalCount,
    inferredType,
    isRecommended: _isRecommendedWidgetProperty(headerLabel || colKey, inferredType, sampleValue),
  };
}

function getApiAvailableProperties(apiTrades) {
  const ctx = {
    mode: 'api',
    label: 'API',
    customSectionTitle: 'API / Notion Fields',
    rawRows: Array.isArray(apiTrades) ? apiTrades : [],
    availableColumns: (typeof _listAPIKeys === 'function' ? _listAPIKeys(apiTrades) : []).map(k => ({
      key: k,
      label: k,
    })),
  };
  // When raw cache is empty (typical post-blob-load on a new device, OR any
  // post-refresh state since the raw cache lives in memory only), the per-
  // property coverageCount is always 0 → the existing filter would strip
  // every property and show an empty Create Widget list. Bypass the filter
  // in that case so the user still sees the property names (sourced from
  // the synced apiFieldNames_v1_<id> via _listAPIKeys fallback) — they can
  // create the widget, and the data populates at the next Sync click via
  // the existing eager bake flow (_eagerBakeAfterWidgetCreate + sync paths).
  const hasRaw = ctx.rawRows.length > 0;
  return (ctx.availableColumns || []).map(column => {
    const stats = _getSourceColumnStats(ctx, column.key, column.label);
    return {
      id: `api:${column.key}`,
      key: column.key,
      label: column.label,
      source: 'api',
      csvColumnName: column.key,
      mappedFieldKey: null,
      sampleValue: stats.sampleValue,
      coverageCount: stats.coverageCount,
      totalCount: stats.totalCount,
      inferredType: stats.inferredType,
      isRecommended: stats.isRecommended,
      sourceBadge: 'API',
    };
  }).filter(prop => !hasRaw || prop.coverageCount > 0);
}

function getAvailableWidgetProperties() {
  const ctx = getActiveDataSourceContext();
  const items = Array.isArray(appState.trades?.items) ? appState.trades.items : [];
  const mapped = [];
  const claimedSourceKeys = new Set();
  for (const dim of JOURNAL_DIMS) {
    const resolvedSourceField = _resolvedSourceFieldForDim(dim.key, ctx);
    const tradeStats = _sampleAndCoverageFromTrades(dim.key);
    const sourceStats = resolvedSourceField ? _getSourceColumnStats(ctx, resolvedSourceField, _getJournalDimLabel(dim)) : null;
    const coverageCount = Math.max(tradeStats.coverageCount, sourceStats?.coverageCount || 0);
    const totalCount = Math.max(tradeStats.totalCount, sourceStats?.totalCount || items.length);
    if (!coverageCount && !resolvedSourceField) continue;
    if (resolvedSourceField) claimedSourceKeys.add(String(resolvedSourceField).trim().toLowerCase());
    const sampleValue = (tradeStats.sampleValue && tradeStats.sampleValue !== '—')
      ? tradeStats.sampleValue
      : (sourceStats?.sampleValue || '—');
    const inferredType = sourceStats?.inferredType || _inferWidgetPropertyType(
      sampleValue && sampleValue !== '—' ? [sampleValue] : [],
      resolvedSourceField || dim.label
    );
    mapped.push({
      id: `mapped:${dim.key}`,
      key: dim.key,
      label: _getJournalDimLabel(dim),
      source: 'mapped',
      csvColumnName: resolvedSourceField || null,
      mappedFieldKey: dim.key,
      sampleValue,
      coverageCount,
      totalCount,
      inferredType,
      isRecommended: _isRecommendedWidgetProperty(resolvedSourceField || dim.label, inferredType, sampleValue),
      sourceBadge: 'MAPPED',
    });
  }

  const sourceFields = (ctx.mode === 'api')
    ? getApiAvailableProperties(ctx.rawRows)
    : (ctx.availableColumns || []).map(column => {
        const stats = _getSourceColumnStats(ctx, column.key, column.label);
        return {
          id: `${ctx.mode}:${column.key}`,
          key: column.key,
          label: column.label,
          source: ctx.mode,
          csvColumnName: column.key,
          mappedFieldKey: null,
          sampleValue: stats.sampleValue,
          coverageCount: stats.coverageCount,
          totalCount: stats.totalCount,
          inferredType: stats.inferredType,
          isRecommended: stats.isRecommended,
          sourceBadge: ctx.label,
        };
      }).filter(prop => prop.coverageCount > 0);

  const filteredSourceFields = sourceFields.filter(prop => {
    const normalized = String(prop.key || '').trim().toLowerCase();
    return normalized && !claimedSourceKeys.has(normalized);
  });

  return {
    context: ctx,
    totalCount: Array.isArray(ctx.rawRows) && ctx.rawRows.length ? ctx.rawRows.length : items.length,
    mappedFields: mapped.sort((a, b) => a.label.localeCompare(b.label)),
    sourceFields: filteredSourceFields.sort((a, b) => {
      if (a.isRecommended !== b.isRecommended) return a.isRecommended ? -1 : 1;
      return a.label.localeCompare(b.label);
    }),
  };
}

function _renderCreateWidgetBuilder() {
  const host = document.getElementById('cw-inline-builder-host');
  if (!host) return;
  _syncCreateWidgetTypeButtons();
  // The search input lives inside `host` and is swapped out by innerHTML on
  // every re-render — without restoring focus the user loses the caret after
  // every keystroke. Snapshot focus + caret position now so we can re-apply
  // after the swap below.
  const _prevSearch = document.getElementById('cw-create-search');
  const _searchHadFocus = !!_prevSearch && document.activeElement === _prevSearch;
  const _searchCaret = _searchHadFocus
    ? { start: _prevSearch.selectionStart, end: _prevSearch.selectionEnd }
    : null;
  if (!_cwCreateFlowState.open || !['bars', 'heatmap', 'table'].includes(_cwCreateFlowState.type)) {
    host.innerHTML = '';
    return;
  }
  const { context, mappedFields, sourceFields } = getAvailableWidgetProperties();
  const isHeatmap = _cwCreateFlowState.type === 'heatmap';
  const isTable   = _cwCreateFlowState.type === 'table';
  const query = String(_cwCreateFlowState.searchQuery || '').trim().toLowerCase();
  const filter = _cwCreateFlowState.sourceFilter || 'all';

  const applyFilter = (items) => items.filter(opt => {
    if (filter === 'mapped' && opt.source !== 'mapped') return false;
    if (filter === 'source' && opt.source !== context.mode) return false;
    if (!query) return true;
    const hay = [
      opt.label,
      opt.sampleValue,
      opt.csvColumnName,
      opt.mappedFieldKey,
      opt.inferredType,
    ].filter(Boolean).join(' ').toLowerCase();
    return hay.includes(query);
  });
  const filteredMapped = applyFilter(mappedFields);
  const filteredSource = applyFilter(sourceFields);
  const hasResults = filteredMapped.length || filteredSource.length;
  const allOptions = [...mappedFields, ...sourceFields];
  const xSelected = allOptions.find(opt => opt.id === _cwCreateFlowState.xSelectedId) || null;
  const ySelected = allOptions.find(opt => opt.id === _cwCreateFlowState.ySelectedId) || null;
  const canAddHeatmap = !!(xSelected && ySelected && xSelected.id !== ySelected.id);

  if (!mappedFields.length && !sourceFields.length) {
    host.innerHTML = `
      <div class="cw-inline-builder is-open">
        <div class="cw-create-empty">
          <span class="cw-create-empty-title">No mapped or detected fields yet</span>
          <span class="cw-create-empty-copy">Import data or configure mappings first to unlock widget creation.</span>
        </div>
      </div>`;
    return;
  }

  const sections = [
    { label: 'Mapped Fields', items: filteredMapped },
    { label: context.customSectionTitle, items: filteredSource },
  ].filter(section => section.items.length);

  const filterBtn = (value, label) => `
    <button type="button"
            class="cw-inline-filter${filter === value ? ' is-active' : ''}"
            data-action="cw-create-set-filter"
            data-cw-filter="${value}">${label}</button>`;

  const content = hasResults
    ? sections.map(section => `
        <section class="cw-inline-section">
          <div class="cw-inline-section-title">${_escapeHtml(section.label)}</div>
          <div class="cw-inline-list" role="list">
            ${section.items.map(opt => {
              const isSelected = _cwCreateFlowState.selectedId === opt.id;
              const isX = _cwCreateFlowState.xSelectedId === opt.id;
              const isY = _cwCreateFlowState.ySelectedId === opt.id;
              const rowStateClass = isHeatmap
                ? `${isX ? ' is-selected-x' : ''}${isY ? ' is-selected-y' : ''}${isX && isY ? ' is-selected-both' : ''}`
                : `${isSelected ? ' is-selected' : ''}`;
              const badge = opt.isRecommended
                ? `<span class="cw-inline-badge">${_escapeHtml(opt.sourceBadge || (opt.source === 'mapped' ? 'MAPPED' : context.label))}</span>`
                : `<span class="cw-inline-badge cw-inline-badge--muted">Not recommended</span>`;
              const actionButtons = isHeatmap
                ? `
                    <button type="button"
                            class="cw-inline-axis-btn${isX ? ' is-active' : ''}"
                            data-action="cw-create-set-x"
                            data-cw-id="${_escapeAttr(opt.id)}">${isX ? 'X Axis' : 'Set X'}</button>
                    <button type="button"
                            class="cw-inline-axis-btn${isY ? ' is-active' : ''}"
                            data-action="cw-create-set-y"
                            data-cw-id="${_escapeAttr(opt.id)}">${isY ? 'Y Axis' : 'Set Y'}</button>`
                : `<button type="button"
                           class="cw-inline-continue"
                           data-action="cw-create-continue-inline"
                           data-cw-id="${_escapeAttr(opt.id)}">Add +</button>`;
              return `
                <div class="cw-inline-row${rowStateClass}">
                  <button type="button"
                          class="cw-inline-row-mainbtn"
                          data-action="cw-create-select-field"
                          data-cw-id="${_escapeAttr(opt.id)}"
                          aria-pressed="${isHeatmap ? (isX || isY ? 'true' : 'false') : (isSelected ? 'true' : 'false')}">
                    <span class="cw-inline-row-main">
                      <span class="cw-inline-row-label">${_escapeHtml(opt.label)}</span>
                      <span class="cw-inline-row-meta">
                        <span>${_escapeHtml(String(opt.sampleValue || '—'))}</span>
                        <span class="cw-inline-row-sep">·</span>
                        <span>${opt.coverageCount}/${opt.totalCount} trades</span>
                        <span class="cw-inline-row-sep">·</span>
                        <span>${_escapeHtml(opt.inferredType)}</span>
                      </span>
                    </span>
                  </button>
                  <div class="cw-inline-row-side">
                    ${badge}
                    ${actionButtons}
                  </div>
                </div>`;
            }).join('')}
          </div>
        </section>`).join('')
    : `
      <div class="cw-create-empty">
        <span class="cw-create-empty-title">No properties match this search</span>
        <span class="cw-create-empty-copy">Try another keyword or switch the field filter.</span>
      </div>`;

  const builderTitle = isHeatmap ? 'Heatmap Setup'
                      : isTable   ? 'Table Setup'
                      : 'Bar Chart Setup';
  const builderSubtitle = isHeatmap ? 'Select X and Y axes'
                        : isTable   ? 'Select a categorical property'
                        : 'Select property';
  host.innerHTML = `
    <div class="cw-inline-builder is-open">
      <div class="cw-inline-head">
        <div class="cw-inline-head-copy">
          <span class="cw-inline-title">${builderTitle}</span>
          <span class="cw-inline-subtitle">${builderSubtitle}</span>
        </div>
      </div>
      <div class="cw-inline-toolbar">
        <label class="cw-inline-search-wrap">
          <input type="text"
                 id="cw-create-search"
                 class="cw-inline-search"
                 value="${_escapeAttr(_cwCreateFlowState.searchQuery || '')}"
                 placeholder="Search property..."
                 autocomplete="off"
                 spellcheck="false">
        </label>
        <div class="cw-inline-filters" role="tablist" aria-label="Property source filter">
          ${filterBtn('all', 'All')}
          ${filterBtn('mapped', 'Mapped')}
          ${filterBtn('source', context.label)}
        </div>
      </div>
      ${isHeatmap ? `
      <div class="cw-inline-heatmap-summary">
        <div class="cw-inline-heatmap-summary-copy">
          <span class="cw-inline-heatmap-summary-title">${canAddHeatmap ? `${_escapeHtml(xSelected.label)} × ${_escapeHtml(ySelected.label)}` : 'Heatmap'}</span>
          <span class="cw-inline-heatmap-summary-meta">
            <span class="cw-inline-axis-chip${xSelected ? ' is-set' : ''}">X: ${_escapeHtml(xSelected?.label || 'Not selected')}</span>
            <span class="cw-inline-axis-chip${ySelected ? ' is-set' : ''}">Y: ${_escapeHtml(ySelected?.label || 'Not selected')}</span>
          </span>
        </div>
        ${canAddHeatmap ? `<button type="button" class="cw-inline-continue" data-action="cw-create-continue">Add +</button>` : ''}
      </div>` : ''}
      <div class="cw-inline-body">${content}</div>
      <div class="cw-inline-actions">
        <div class="cw-inline-actions-hint">${isHeatmap
          ? (canAddHeatmap ? 'Add + is ready for the selected X/Y axes.' : 'Choose both X Axis and Y Axis to continue.')
          : (_cwCreateFlowState.selectedId ? 'Add + is available on the selected property.' : 'Select a property to continue.')}</div>
        <button type="button" class="cw-create-secondary" data-action="cw-create-close">Cancel</button>
      </div>
    </div>`;
  if (_searchHadFocus) {
    const _newSearch = document.getElementById('cw-create-search');
    if (_newSearch) {
      _newSearch.focus();
      try { _newSearch.setSelectionRange(_searchCaret.start, _searchCaret.end); } catch (_) {}
    }
  }
}

function _openCreateWidgetModal(type) {
  if (!['bars', 'heatmap', 'table'].includes(type)) return;
  if (_cwCreateFlowState.open && _cwCreateFlowState.type === type) {
    _closeCreateWidgetBuilder();
    return;
  }
  _cwCreateFlowState.open = true;
  _cwCreateFlowState.type = type;
  _cwCreateFlowState.selectedId = '';
  _cwCreateFlowState.selectedLabel = '';
  _cwCreateFlowState.xSelectedId = '';
  _cwCreateFlowState.ySelectedId = '';
  _cwCreateFlowState.searchQuery = '';
  _cwCreateFlowState.sourceFilter = 'all';
  _renderCreateWidgetBuilder();
  if (_cwCreateFlowEscHandler) document.removeEventListener('keydown', _cwCreateFlowEscHandler);
  _cwCreateFlowEscHandler = (e) => { if (e.key === 'Escape') _closeCreateWidgetBuilder(); };
  document.addEventListener('keydown', _cwCreateFlowEscHandler);
  requestAnimationFrame(() => {
    document.getElementById('cw-create-search')?.focus();
  });
}

function _closeCreateWidgetBuilder() {
  _cwCreateFlowState.open = false;
  _cwCreateFlowState.type = null;
  _cwCreateFlowState.selectedId = '';
  _cwCreateFlowState.selectedLabel = '';
  _cwCreateFlowState.xSelectedId = '';
  _cwCreateFlowState.ySelectedId = '';
  _cwCreateFlowState.searchQuery = '';
  _cwCreateFlowState.sourceFilter = 'all';
  _renderCreateWidgetBuilder();
  if (_cwCreateFlowEscHandler) {
    document.removeEventListener('keydown', _cwCreateFlowEscHandler);
    _cwCreateFlowEscHandler = null;
  }
}

function _selectCreateWidgetField(optionId) {
  if (!_cwCreateFlowState.open || !optionId) return;
  if (_cwCreateFlowState.type === 'heatmap') return;
  const { mappedFields, sourceFields } = getAvailableWidgetProperties();
  const match = [...mappedFields, ...sourceFields].find(opt => opt.id === optionId);
  if (!match) return;
  _cwCreateFlowState.selectedId = match.id;
  _cwCreateFlowState.selectedLabel = match.label;
  _renderCreateWidgetBuilder();
}

function _getCreateWidgetSelectionById(optionId) {
  if (!optionId) return null;
  const { mappedFields, sourceFields } = getAvailableWidgetProperties();
  return [...mappedFields, ...sourceFields].find(opt => opt.id === optionId) || null;
}

function _setCreateWidgetHeatmapAxis(axis, optionId) {
  if (!_cwCreateFlowState.open || _cwCreateFlowState.type !== 'heatmap' || !['x', 'y'].includes(axis)) return;
  const match = _getCreateWidgetSelectionById(optionId);
  if (!match) return;
  const thisKey  = axis === 'x' ? 'xSelectedId' : 'ySelectedId';
  const otherKey = axis === 'x' ? 'ySelectedId' : 'xSelectedId';
  const currentThis  = _cwCreateFlowState[thisKey];
  const currentOther = _cwCreateFlowState[otherKey];
  // Toggle off when re-clicking the same axis.
  if (currentThis === match.id) {
    _cwCreateFlowState[thisKey] = '';
  } else if (currentOther === match.id) {
    // Promoting the OTHER axis's property onto this one → swap, so the
    // previously-selected partner moves into the now-vacated slot instead of
    // being silently discarded.
    _cwCreateFlowState[thisKey]  = match.id;
    _cwCreateFlowState[otherKey] = currentThis;
  } else {
    _cwCreateFlowState[thisKey] = match.id;
  }
  _renderCreateWidgetBuilder();
}

function _setCreateWidgetSourceFilter(value) {
  if (!['all', 'mapped', 'source'].includes(value)) return;
  _cwCreateFlowState.sourceFilter = value;
  _renderCreateWidgetBuilder();
}

function _getCreateWidgetSelection() {
  return _getCreateWidgetSelectionById(_cwCreateFlowState.selectedId);
}

function _handleCreateWidgetContinue() {
  if (_cwCreateFlowState.type === 'bars') {
    if (!_cwCreateFlowState.selectedId) return;
    const selected = _getCreateWidgetSelection();
    if (!selected) return;
    _createCustomBarsWidget({
      field: selected.key,
      label: selected.label,
      propertySource: selected.source,
      inferredType: selected.inferredType,
      createdFrom: 'widget-builder',
    });
  } else if (_cwCreateFlowState.type === 'table') {
    if (!_cwCreateFlowState.selectedId) return;
    const selected = _getCreateWidgetSelection();
    if (!selected) return;
    _createCustomTableWidget({
      field: selected.key,
      label: selected.label,
      propertySource: selected.source,
      inferredType: selected.inferredType,
      createdFrom: 'widget-builder',
    });
  } else if (_cwCreateFlowState.type === 'heatmap') {
    const xSelected = _getCreateWidgetSelectionById(_cwCreateFlowState.xSelectedId);
    const ySelected = _getCreateWidgetSelectionById(_cwCreateFlowState.ySelectedId);
    if (!xSelected || !ySelected || xSelected.id === ySelected.id) return;
    // Heatmap axis convention: rowKey renders vertically (Y axis), colKey
    // renders horizontally (X axis). _renderSharedHeatmapGrid maps
    // def.field → rowKey and def.field2 → colKey, so the user's X pick
    // must land in field2 (and Y in field) to match the visual axes.
    // Label kept as "X × Y" — user-facing reading order.
    _createCustomHeatmapWidget({
      field: ySelected.key,
      field2: xSelected.key,
      label: `${xSelected.label} × ${ySelected.label}`,
      fieldLabel: ySelected.label,
      field2Label: xSelected.label,
      fieldSource: ySelected.source,
      field2Source: xSelected.source,
      propertySource: xSelected.source === ySelected.source ? xSelected.source : 'mixed',
      inferredType: ySelected.inferredType,
      createdFrom: 'widget-builder',
    });
  }
  _closeCreateWidgetBuilder();
  if (typeof _renderCreateWidgetList === 'function') _renderCreateWidgetList();
}

// Render the list of widgets created from this section, scoped per-profile.
// Each row shows the type icon, label, and a delete affordance. The host
// (`#cw-list-host`) lives just below the inline builder so additions appear
// in place. Clicking the trash button removes the widget via _destroyCustomWidget
// (same code path as the dashboard's per-widget delete confirm).
function _renderCreateWidgetList() {
  const host = document.getElementById('cw-list-host');
  if (!host) return;
  const defs = (typeof _loadCustomWidgetDefs === 'function') ? _loadCustomWidgetDefs() : [];
  if (!defs.length) {
    host.innerHTML = `
      <div class="cw-list-empty">No custom widgets yet. Use the buttons above to create your first one.</div>`;
    return;
  }
  // Sort: newest first if a created-at timestamp exists, otherwise leave
  // creation order (which is append-on-add for legacy defs).
  const sorted = defs.slice().sort((a, b) => {
    const aTime = Number(a?.createdAt || 0);
    const bTime = Number(b?.createdAt || 0);
    return bTime - aTime;
  });
  const rows = sorted.map(def => {
    const isHeatmap = def.type === 'heatmap';
    const isTable   = def.type === 'table';
    const icon = isHeatmap ? '▦' : isTable ? '⊞' : '▮';
    const label = _escHTML(def.label || def.field || def.id);
    // Heatmap row shows "X × Y" — field2 holds the X-axis dim (colKey) and
    // field holds the Y-axis dim (rowKey), per the create-widget convention.
    const sub   = isHeatmap
      ? `${_escHTML(def.field2Label || def.field2 || '?')} × ${_escHTML(def.fieldLabel || def.field || '?')}`
      : _escHTML(def.fieldLabel || def.field || '?');
    const typeBadge = isHeatmap ? 'Heatmap' : isTable ? 'Table' : 'Bar Chart';
    const typeClass = isHeatmap ? 'cw-list-type-heatmap' : isTable ? 'cw-list-type-table' : 'cw-list-type-bars';
    return `
      <div class="cw-list-item" data-cw-id="${_escapeAttr(def.id)}">
        <span class="cw-list-icon" aria-hidden="true">${icon}</span>
        <div class="cw-list-main">
          <div class="cw-list-label">${label}</div>
          <div class="cw-list-sub">${sub}</div>
        </div>
        <span class="cw-list-type-badge ${typeClass}">${typeBadge}</span>
        <button type="button"
                class="cw-list-delete-btn"
                data-action="cw-list-delete"
                data-cw-id="${_escapeAttr(def.id)}"
                title="Delete this widget">✕</button>
      </div>`;
  }).join('');
  host.innerHTML = `
    <div class="cw-list-header">
      <span class="cw-list-title">Your widgets</span>
      <span class="cw-list-count">${sorted.length} created</span>
    </div>
    <div class="cw-list-body">${rows}</div>`;
}

// ── Remap picker (inline dropdown attached to a pencil click) ──
function _closeAllRemapPickers() {
  // Mapping-tab pickers are hosted inside a follow-up `<tr>` so the dropdown
  // can span the full row width. Remove the row, not just the inner picker.
  document.querySelectorAll('.ljp-mapping-picker-row').forEach(el => el.remove());
  document.querySelectorAll('.csv-remap-picker').forEach(el => el.remove());
  document.querySelectorAll('.lap-pencil-btn.open, .ljp-pencil-btn.open').forEach(b => b.classList.remove('open'));
}
function openRemapPicker(triggerBtn) {
  if (!triggerBtn) return;
  const dimKey = triggerBtn.getAttribute('data-dim-key');
  const scope  = triggerBtn.getAttribute('data-scope') || 'journal';
  if (!dimKey) return;

  // Toggle: if the same picker is open, close it. Two host shapes:
  //  - Mapping tab (this rewrite): trigger sits in a flat chip `.ljp-mapping-row`
  //    (a `<div>`), picker lives in a follow-up `<div class="ljp-mapping-picker-row">`
  //    sibling injected right after it. Existence is detected via the sibling.
  //  - Health tab / other legacy callers: trigger sits in a `<li class="lap-item">`
  //    or `<li class="ljp-item">` (this layout is preserved for backwards compat
  //    even though the Mapping tab itself no longer renders `.ljp-item`).
  const chipRowHost  = triggerBtn.closest('.ljp-mapping-row');
  const existingHost = chipRowHost || triggerBtn.closest('.lap-item, .ljp-item');
  const existing = chipRowHost
    ? (chipRowHost.nextElementSibling?.classList.contains('ljp-mapping-picker-row')
        ? chipRowHost.nextElementSibling
        : null)
    : existingHost?.querySelector('.csv-remap-picker');
  _closeAllRemapPickers();
  if (existing) return;

  const picker = document.createElement('div');
  picker.className = 'csv-remap-picker';

  // Scope decides which pool of candidates to show and which action to dispatch.
  const isAPI = scope === 'api-journal';
  let candidates, currentOverride, activeFallback, hint, pickAction, emptyHtml;
  if (isAPI) {
    const raw = _getRawAPICache();
    candidates = _listAPIKeys(raw || []);
    currentOverride = _getEffectiveApiOverride(dimKey);
    activeFallback = '';
    hint = 'Pick a Notion API field for this dimension';
    pickAction = 'pick-api-field';
    // Empty-state: render an inline refresh affordance so the user can trigger
    // a fetch without leaving the Data Hub (previously the copy told them to
    // click the top-bar Notion Live tab, which side-closes the Data Hub).
    // States: loading → disabled label; error → error text + retry; idle → load.
    const isLoading = !!appState.settings?.dataSource?.loading;
    const errMsg    = !isLoading && _lastAPIFetchError ? _lastAPIFetchError : null;
    const label     = isLoading ? 'Loading…' : (errMsg ? 'Retry' : 'Load fields');
    const msg       = isLoading ? 'Loading API fields…'
                    : (errMsg ? `Failed to load — ${_escapeHtml(errMsg)}`
                              : 'Fields unavailable.');
    emptyHtml = `<div class="csv-remap-empty">
        <div class="csv-remap-empty-msg${errMsg ? ' is-error' : ''}">${msg}</div>
        <button class="csv-remap-option csv-remap-refresh-btn" data-action="refresh-api-fields" data-dim-key="${_escapeHtml(dimKey)}"${isLoading ? ' disabled aria-disabled="true"' : ''}>
          <span>${label}</span>
        </button>
      </div>`;
  } else {
    candidates = (_lastCsvHeaders || []).filter(h => h && h.trim());
    currentOverride = _csvColumnOverrides[dimKey] || '';
    activeFallback = _resolvedHeaderFor(dimKey);
    hint = 'Pick a CSV column for this dimension';
    pickAction = 'pick-remap-column';
    emptyHtml = `<div class="csv-remap-empty">No CSV columns available.</div>`;
  }

  // CSV branch: precompute non-empty-value count per header and sort the
  // picker by density (most populated → first). Notion exports frequently
  // include empty separator columns ("--------H4--------", "Paire" vs
  // "Pair", "--Automatic Field-", etc.) — without a hint the user picks
  // the first match by name and ends up with an empty source. A count
  // badge shows beside each option; columns with 0 values are dimmed and
  // labelled "empty" so they're still pickable but visibly inadvisable.
  let csvColCounts = null;
  if (!isAPI) {
    csvColCounts = {};
    const rows = _lastCsvRows || [];
    for (const h of candidates) csvColCounts[h] = 0;
    for (const row of rows) {
      for (const h of candidates) {
        const v = row[h];
        if (v != null && String(v).trim() !== '') csvColCounts[h]++;
      }
    }
    candidates = candidates.slice().sort((a, b) =>
      (csvColCounts[b] - csvColCounts[a]) || a.localeCompare(b)
    );
  }

  const hintHeader = `<div class="csv-remap-picker-hint">${hint}</div>`;
  const noMappingBtn = `<button class="csv-remap-option${_isNoMappingValue(currentOverride) ? ' active' : ''}" data-action="${pickAction}" data-dim-key="${_escapeHtml(dimKey)}" data-header="${NO_MAPPING_VALUE}">
              <span class="csv-remap-option-label">No Mapping</span>
              ${_isNoMappingValue(currentOverride) ? '<span class="csv-remap-option-tag">current</span>' : ''}
            </button>`;
  const opts = candidates.map(h => {
    const isActive = (currentOverride && h === currentOverride) ||
                     (!currentOverride && activeFallback && h === activeFallback);
    const count = csvColCounts ? csvColCounts[h] : null;
    const isEmptyCol = count === 0;
    const countBadge = count != null
      ? `<span class="csv-remap-option-count${isEmptyCol ? ' is-empty' : ''}">${isEmptyCol ? 'empty' : count}</span>`
      : '';
    return `<button class="csv-remap-option${isActive ? ' active' : ''}${isEmptyCol ? ' is-empty-col' : ''}" data-action="${pickAction}" data-dim-key="${_escapeHtml(dimKey)}" data-header="${_escapeHtml(h)}">
              <span class="csv-remap-option-label">${_escapeHtml(h)}</span>
              ${countBadge}
              ${isActive ? '<span class="csv-remap-option-tag">current</span>' : ''}
            </button>`;
  }).join('');
  const clearBtn = currentOverride
    ? `<button class="csv-remap-option" data-action="${pickAction}" data-dim-key="${_escapeHtml(dimKey)}" data-header=""><span>— Use default / auto-detect —</span></button>`
    : '';
  picker.innerHTML = hintHeader + noMappingBtn + (candidates.length ? opts : emptyHtml) + clearBtn;
  if (chipRowHost) {
    // Inject the picker as a follow-up div sibling so the dropdown spans the
    // full row width of the flat chip list.
    const pickerRow = document.createElement('div');
    pickerRow.className = 'ljp-mapping-picker-row';
    pickerRow.appendChild(picker);
    chipRowHost.parentNode?.insertBefore(pickerRow, chipRowHost.nextSibling);
  } else {
    existingHost?.appendChild(picker);
  }
  triggerBtn.classList.add('open');
  // Ensure the newly-opened picker is fully visible inside its scroll container.
  requestAnimationFrame(() => {
    try { picker.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch (e) {}
  });
}
function pickRemapColumn(optEl) {
  if (!optEl) return;
  const dimKey     = optEl.getAttribute('data-dim-key');
  const headerName = optEl.getAttribute('data-header') || '';
  _closeAllRemapPickers();
  _applyCsvColumnOverride(dimKey, headerName);
}

// User-initiated refresh from the Mapping-tab picker empty state. Triggers
// _fetchAPICacheSilently and immediately re-renders the picker to reflect the
// in-flight "Loading…" label. The fetch's .finally calls updateJournalPanel,
// whose _reopenIfNeeded rebuilds the picker with populated fields (success)
// or the error + Retry state (failure — see _lastAPIFetchError).
function _refreshAPIFieldsFromPicker(btnEl) {
  if (!btnEl) return;
  if (appState.settings?.dataSource?.loading) return;
  const dimKey = btnEl.getAttribute('data-dim-key');
  // Kick off fetch. Notion profiles route through loadFromAPI → _loadNotionTrades;
  // legacy API profiles use _fetchAPICacheSilently directly.
  if (getActiveJournalProfile()?.connectionType === 'notion') {
    loadFromAPI({ force: true });
  } else {
    _fetchAPICacheSilently({ force: true });
  }
  // Immediate feedback: re-render the picker right now so the button flips
  // to the disabled "Loading…" state without waiting for the fetch tick.
  // The trigger may sit either in the Mapping-tab follow-up picker row
  // (table layout) or in a legacy lap-item / ljp-item list row.
  const pickerRow = btnEl.closest('.ljp-mapping-picker-row');
  const prevMappingRow = pickerRow?.previousElementSibling;
  const existingHost = btnEl.closest('.lap-item, .ljp-item');
  const triggerBtn = prevMappingRow?.querySelector(`.ljp-pencil-btn[data-dim-key="${dimKey}"][data-scope="api-journal"]`)
    || existingHost?.querySelector(`.ljp-pencil-btn[data-dim-key="${dimKey}"][data-scope="api-journal"], .lap-pencil-btn[data-dim-key="${dimKey}"][data-scope="api-journal"]`);
  if (triggerBtn) {
    // openRemapPicker toggles; force-close-then-reopen ensures a fresh render
    // with the current loading flag reflected.
    _closeAllRemapPickers();
    openRemapPicker(triggerBtn);
  }
}

// Apply / clear an API field override, then re-normalize from the raw cache
// so the change is reflected immediately without re-fetching Notion.
function pickAPIField(optEl) {
  if (!optEl) return;
  const dimKey    = optEl.getAttribute('data-dim-key');
  const fieldName = optEl.getAttribute('data-header') || '';
  if (!dimKey) return;
  _closeAllRemapPickers();
  const overrides = _getAPIFieldOverrides();
  if (fieldName) overrides[dimKey] = fieldName;
  else           delete overrides[dimKey];
  _saveAPIFieldOverrides(overrides);
  // The user just made a deliberate choice for this dim — strip the
  // "auto-mapped" tag so the row flips from green (is-auto-mapped) to blue
  // (is-remapped) on next render. Tags for sibling dims stay intact.
  _removeAutoMappedDim(dimKey);
  _reapplyAPIOverrides();
  updateJournalPanel();
}

function _escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

// ── Panel open/close ──
let themePanelOpen = false;
function toggleThemePanel() {
  themePanelOpen = !themePanelOpen;
  const panel = document.getElementById('theme-panel');
  // Resetting any drag offset BEFORE removing `.open` lets the CSS slide-out
  // (translateX(100%)) animate from the panel's current position; the next
  // open then snaps back to the default top-right anchor.
  if (!themePanelOpen) {
    panel.style.transform = '';
    panel.style.transition = '';
    panel.classList.remove('is-dragging');
  }
  panel.classList.toggle('open', themePanelOpen);
  document.getElementById('theme-toggle-btn').classList.toggle('open', themePanelOpen);
  if (themePanelOpen) _initThemePanelDragOnce();
}

// Drag-to-move the theme panel by its header. Bound once on first open;
// pointerdown on the header (not on the close button) starts the drag.
// The offset is held only while the panel is open — toggleThemePanel(close)
// clears the inline transform so reopens land at the default position.
let _themePanelDragBound = false;
function _initThemePanelDragOnce() {
  if (_themePanelDragBound) return;
  const panel  = document.getElementById('theme-panel');
  const header = panel?.querySelector('.tp-header');
  if (!panel || !header) return;
  _themePanelDragBound = true;
  // Horizontal-only drag: panel slides on the X axis (escape-from-the-right
  // behavior); vertical drift is intentionally suppressed to keep the panel
  // top-anchored.
  let startX = 0, baseDX = 0, pointerId = null;
  const parseTranslateX = (str) => {
    const m = /translate(?:X)?\(\s*(-?\d+(?:\.\d+)?)px/.exec(str || '');
    return m ? parseFloat(m[1]) : 0;
  };
  header.addEventListener('pointerdown', (e) => {
    // Skip drags initiated on the close button or any interactive child.
    if (e.target.closest('.tp-close, button, input, select, textarea')) return;
    if (e.button !== 0) return;
    pointerId = e.pointerId;
    startX = e.clientX;
    baseDX = parseTranslateX(panel.style.transform);
    panel.classList.add('is-dragging');
    panel.style.transition = 'none';
    try { header.setPointerCapture(pointerId); } catch (_) {}
    e.preventDefault();
  });
  header.addEventListener('pointermove', (e) => {
    if (e.pointerId !== pointerId) return;
    const dx = baseDX + (e.clientX - startX);
    panel.style.transform = `translateX(${dx}px)`;
  });
  const endDrag = (e) => {
    if (e.pointerId !== pointerId) return;
    pointerId = null;
    panel.classList.remove('is-dragging');
    // Restore the CSS-defined transition so the next close animates correctly.
    panel.style.transition = '';
    try { header.releasePointerCapture(e.pointerId); } catch (_) {}
  };
  header.addEventListener('pointerup', endDrag);
  header.addEventListener('pointercancel', endDrag);
}

// ══════════════════════════════════════════════════════════════
// TP MANAGEMENT PANEL  —  Phase 2.A
// Right-edge slide-in modal, Escape + click-outside close, mode
// selector (Fixed active; Multi/Personalised placeholders).
// State lives in appState.ui.tpConfig; persistence via _saveTpConfig.
// ══════════════════════════════════════════════════════════════
const TPM_MODE_LABELS = { fixed: 'TP: Single', multi: 'TP: Multi', personalised: 'TP: Custom' };
let tpmPanelOpen = false;
let _tpmPanelEscHandler = null;
let _tpmPanelClickOutsideHandler = null;

function toggleTpmPanel() {
  tpmPanelOpen = !tpmPanelOpen;
  const panel = document.getElementById('tpm-panel');
  const btn   = document.getElementById('tpm-toggle-btn');
  if (!panel) return;
  panel.classList.toggle('open', tpmPanelOpen);
  btn?.classList.toggle('open', tpmPanelOpen);

  if (tpmPanelOpen) {
    // Sync radio selection with current state on every open.
    _syncTpmRadios();
    _renderTpmModeBody();
    // Defer handler attach so the click that opened us doesn't immediately close.
    setTimeout(() => {
      _tpmPanelClickOutsideHandler = (e) => {
        if (!tpmPanelOpen) return;
        // Use composedPath() captured at dispatch time: e.target may be
        // detached from the DOM if a click inside the panel (e.g. tpCount
        // button) triggered a body re-render mid-bubble. closest() on a
        // detached element walks only the detached subtree and misses the
        // real #tpm-panel ancestor → false positive → panel closes spuriously.
        const path = (e.composedPath && e.composedPath()) || [];
        const panel = document.getElementById('tpm-panel');
        const toggle = document.getElementById('tpm-toggle-btn');
        if (panel && path.includes(panel)) return;
        if (toggle && path.includes(toggle)) return;
        toggleTpmPanel();
      };
      _tpmPanelEscHandler = (e) => {
        if (e.key === 'Escape' && tpmPanelOpen) toggleTpmPanel();
      };
      document.addEventListener('click', _tpmPanelClickOutsideHandler);
      document.addEventListener('keydown', _tpmPanelEscHandler);
    }, 0);
  } else {
    if (_tpmPanelClickOutsideHandler) { document.removeEventListener('click', _tpmPanelClickOutsideHandler); _tpmPanelClickOutsideHandler = null; }
    if (_tpmPanelEscHandler)          { document.removeEventListener('keydown', _tpmPanelEscHandler);        _tpmPanelEscHandler = null; }
  }
}

function _syncTpmRadios() {
  const mode = appState.ui.tpConfig?.mode || 'fixed';
  document.querySelectorAll('#tpm-mode-list input[name="tpmMode"]').forEach(input => {
    input.checked = (input.value === mode);
  });
  _syncTpmBeRadios();
}

function _syncTpmBeRadios() {
  const beMode = appState.ui.beMode || 'be-fallback';
  document.querySelectorAll('#tpm-be-list input[name="tpmBeMode"]').forEach(input => {
    input.checked = (input.value === beMode);
  });
}

// Apply a new BE Management mode globally. Persists to localStorage,
// invalidates the filter cache (so getFiltered re-derives), invalidates
// classification (via _hashTpConfig including beMode), and triggers a render.
function _setBeMode(mode) {
  if (mode !== 'be-fallback' && mode !== 'flipping-be') return;
  if (appState.ui.beMode === mode) return;
  appState.ui.beMode = mode;
  try { localStorage.setItem('flipping_be_mode', mode); } catch {}
  invalidateFilterCache();
  _syncTpmBeRadios();
  _updateTpmBadge();
  // Force PO recompute next render — its hash includes beMode below.
  if (window._poState) window._poState.lastTradesHash = '';
  if (typeof render === 'function') render();
}
window._setBeMode = _setBeMode;

function _setTpMode(mode) {
  if (!TPM_MODE_LABELS[mode]) return;
  const cfg = appState.ui.tpConfig
    || { mode: 'fixed', multi: _defaultMultiConfig(), personalised: _defaultPersonalisedConfig() };
  cfg.mode = mode;
  // Guarantee valid sub-configs are always present. The validators REQUIRE the
  // matching sub-config when mode === 'X', and always-present shape keeps the
  // UI renderers simple (no null-guarding at every read site).
  if (!_isValidMultiConfig(cfg.multi)) cfg.multi = _defaultMultiConfig();
  if (!_isValidPersonalisedConfig(cfg.personalised)) cfg.personalised = _defaultPersonalisedConfig();
  appState.ui.tpConfig = cfg;
  // Mutex with ORR bubble: Multi-TP and Personalised express their own TP
  // scheme; an active rrMinFilter bubble would render as a separate "RR ≥ X R"
  // badge alongside the TPM badge, which the user finds confusing. Clear it
  // here so the two never coexist. Fixed mode is the natural pair to the bubble
  // (the bubble IS the fixed TP) and is left alone.
  if ((mode === 'multi' || mode === 'personalised') && appState.ui.rrMinFilter !== null) {
    appState.ui.rrMinFilter = null;
    try {
      const slot = getPresetLiveSlot(appState.presets?.activeId);
      if (slot) slot.rrMinFilter = null;
      if (typeof savePresetLiveFilters === 'function') savePresetLiveFilters();
    } catch (_e) {}
    if (typeof invalidateFilterCache === 'function') invalidateFilterCache();
    if (typeof _rrSyncActiveFilterBadge === 'function') _rrSyncActiveFilterBadge();
  }
  _saveTpConfig(cfg);
  _updateTpmBadge();
  _renderTpmModeBody();
}

function _updateTpmBadge() {
  const mode = appState.ui.tpConfig?.mode || 'fixed';
  const label = TPM_MODE_LABELS[mode] || TPM_MODE_LABELS.fixed;
  const desktop = document.getElementById('tpm-badge');
  const desktopText = document.getElementById('tpm-badge-text');
  const mobile  = document.getElementById('tpm-badge-mob');
  const mobileText = document.getElementById('tpm-badge-mob-text');
  if (desktopText) desktopText.textContent = label;
  if (mobileText)  mobileText.textContent  = label;
  if (desktop) desktop.setAttribute('data-mode', mode);
  if (mobile)  mobile.setAttribute('data-mode', mode);
  // Title carries the full label so hover surfaces "TP: Fixed/Multi/Custom"
  // when the inline text is hidden at narrow widths (CSS rule on
  // .dhb-badge-text under <=1280px). The "Switch TP Management mode" hint
  // is appended so the click affordance stays discoverable.
  const fullTitle = `${label} — Switch TP Management mode`;
  if (desktop) desktop.title = fullTitle;
  if (mobile)  mobile.title  = fullTitle;
  // Keep the mode-switcher dropdown in sync: options are the two INACTIVE
  // modes. Re-rendered on every mode change so switching via any entry
  // point (badge dropdown, modal, programmatic) leaves the menu coherent.
  _renderTpmDropdownOptions();
}

// ── TPM badge mode-switcher dropdown (Phase 3.B) ──
// Bubble popup anchored below the tpm-badge. Lists all 3 modes with the
// active one shown inert (tinted background + ✓). Locked modes carry a
// lock icon + amber hint and route clicks to the Data Hub Mapping tab;
// unlocked selections route through _setTpMode. Position is adaptive —
// _positionTpmDropdown centers below the badge and flips to edge-anchored
// when that would clip the viewport.
let tpmDropdownOpen = false;
let _tpmDropdownOutsideHandler = null;
let _tpmDropdownKeyHandler = null;

// Short hint copy for locked modes — shown under the label in amber.
// Keep in sync with the Feature Requirements block in the Health tab so
// users see the same language in both places.
const _TPM_LOCKED_HINTS = {
  multi:        'tp1_rr / tp2_rr not mapped',
  personalised: 'rrMax not mapped',
};

function _renderTpmDropdownOptions() {
  const menu = document.getElementById('tpm-mode-menu');
  if (!menu) return;
  const active = appState.ui.tpConfig?.mode || 'fixed';
  const multiOk  = _isMultiMappingComplete(appState.ui.tpConfig?.multi);
  const customOk = _isPersonalisedRrMaxMapped();
  const modes = ['fixed', 'multi', 'personalised'];
  const lockedOf = (m) =>
    (m === 'multi' && !multiOk) || (m === 'personalised' && !customOk);

  menu.innerHTML = modes.map(m => {
    const isActive = (m === active);
    const isLocked = lockedOf(m);
    const cls = ['tpm-mode-card'];
    if (isActive) cls.push('is-active');
    if (isLocked) cls.push('is-locked');
    // aria-disabled="false" on locked: still actionable (opens mapping tab)
    // but visually distinct via lock icon + amber hint. Active is inert
    // via the click handler short-circuit, not via aria-disabled — arrow
    // navigation should still land on it.
    const hint = isLocked && !isActive
      ? `<span class="tpm-mode-hint">${_escapeHtml(_TPM_LOCKED_HINTS[m] || '')}</span>`
      : '';
    const check = isActive
      ? `<span class="tpm-mode-check" aria-hidden="true">✓</span>`
      : '';
    const lock  = (isLocked && !isActive)
      ? `<span class="tpm-mode-lock" aria-label="Mapping required">
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor"
               stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">
            <rect x="4" y="11" width="16" height="10" rx="2"/>
            <path d="M8 11V7a4 4 0 0 1 8 0v4"/>
          </svg>
        </span>`
      : '';
    return `<div class="${cls.join(' ')}" role="menuitem" tabindex="-1"
                 data-action="select-tpm-mode" data-mode="${m}"
                 aria-disabled="${isLocked ? 'false' : 'false'}">
      <span class="tpm-mode-dot" aria-hidden="true"></span>
      <div class="tpm-mode-text">
        <span class="tpm-mode-label">${_escapeHtml(TPM_MODE_LABELS[m])}</span>
        ${hint}
      </div>
      ${check}${lock}
    </div>`;
  }).join('');
}

// Adaptive alignment. Center the bubble below the badge; when centering
// would clip the viewport, flip to right- or left-edge anchoring and
// reposition the tail so it still sits under the badge center. Called
// after the bubble is in DOM (offsetWidth needs layout).
function _positionTpmDropdown() {
  const menu = document.getElementById('tpm-mode-menu');
  const wrap = menu?.parentElement;
  if (!menu || !wrap) return;

  // Reset any inline alignment so measurement is clean.
  menu.style.left  = '';
  menu.style.right = '';
  menu.style.removeProperty('--tpm-tail-x');

  const wrapRect   = wrap.getBoundingClientRect();
  const BW         = wrapRect.width;
  const badgeCenter = wrapRect.left + BW / 2;
  const bubbleW    = menu.offsetWidth;
  const viewportW  = document.documentElement.clientWidth;
  const margin     = 8;

  const idealLeft  = badgeCenter - bubbleW / 2;
  const idealRight = badgeCenter + bubbleW / 2;

  if (idealRight > viewportW - margin) {
    // Right-edge anchor: bubble's right aligns with wrap's right.
    menu.style.right = '0px';
    menu.style.left  = 'auto';
    const tailX = bubbleW - BW / 2;
    menu.style.setProperty('--tpm-tail-x', `${tailX}px`);
  } else if (idealLeft < margin) {
    // Left-edge anchor: bubble's left aligns with wrap's left.
    menu.style.left  = '0px';
    menu.style.right = 'auto';
    menu.style.setProperty('--tpm-tail-x', `${BW / 2}px`);
  } else {
    // Centered: bubble's center aligns with badge center.
    menu.style.left  = `${(BW - bubbleW) / 2}px`;
    menu.style.right = 'auto';
    menu.style.setProperty('--tpm-tail-x', '50%');
  }
}

function _closeTpmDropdown() {
  if (!tpmDropdownOpen) return;
  tpmDropdownOpen = false;
  document.getElementById('tpm-mode-menu')?.classList.remove('open');
  const badge = document.getElementById('tpm-badge');
  badge?.setAttribute('aria-expanded', 'false');
  badge?.classList.remove('tpm-badge-open');
  if (_tpmDropdownOutsideHandler) {
    document.removeEventListener('mousedown', _tpmDropdownOutsideHandler);
    _tpmDropdownOutsideHandler = null;
  }
  if (_tpmDropdownKeyHandler) {
    document.removeEventListener('keydown', _tpmDropdownKeyHandler);
    _tpmDropdownKeyHandler = null;
  }
}

function toggleTpmDropdown() {
  if (tpmDropdownOpen) { _closeTpmDropdown(); return; }
  const menu  = document.getElementById('tpm-mode-menu');
  const badge = document.getElementById('tpm-badge');
  if (!menu || !badge) return;
  _renderTpmDropdownOptions();
  menu.classList.add('open');
  badge.setAttribute('aria-expanded', 'true');
  badge.classList.add('tpm-badge-open');
  tpmDropdownOpen = true;

  // Measure + position after the bubble is in layout. The menu is now
  // display:flex, so offsetWidth reflects the rendered width.
  _positionTpmDropdown();

  // Focus the first NON-active card so arrow-nav starts on something the
  // user can actually activate (falls back to any card if all happen to
  // be the active one — can't).
  const firstFocus = menu.querySelector('.tpm-mode-card:not(.is-active)')
                  || menu.querySelector('.tpm-mode-card');
  if (firstFocus) firstFocus.focus();

  // Defer outside-click attach so the current click doesn't instantly close.
  setTimeout(() => {
    _tpmDropdownOutsideHandler = (e) => {
      if (!tpmDropdownOpen) return;
      const path = (e.composedPath && e.composedPath()) || [];
      if (path.includes(menu) || path.includes(badge)) return;
      _closeTpmDropdown();
    };
    _tpmDropdownKeyHandler = (e) => {
      if (!tpmDropdownOpen) return;
      if (e.key === 'Escape') {
        e.preventDefault();
        _closeTpmDropdown();
        badge.focus();
        return;
      }
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        const cards = [...menu.querySelectorAll('.tpm-mode-card')];
        if (!cards.length) return;
        const idx = cards.indexOf(document.activeElement);
        const next = e.key === 'ArrowDown'
          ? cards[(idx + 1 + cards.length) % cards.length]
          : cards[(idx - 1 + cards.length) % cards.length];
        next?.focus();
      }
    };
    document.addEventListener('mousedown', _tpmDropdownOutsideHandler);
    document.addEventListener('keydown', _tpmDropdownKeyHandler);
  }, 0);
}

function _selectTpmModeFromDropdown(mode) {
  if (!TPM_MODE_LABELS[mode]) return;
  // Clicking the already-active mode is inert — the card is rendered with
  // the data-action so keyboard Enter routes here too, so we short-circuit
  // rather than rely on markup to suppress it. No close, no switch.
  const current = appState.ui.tpConfig?.mode || 'fixed';
  if (mode === current) return;

  // Close the dropdown regardless of whether the switch proceeds.
  _closeTpmDropdown();

  if (mode === 'fixed') { _setTpMode('fixed'); return; }

  // Mapping-gated modes: if prerequisites aren't met, route to Data Hub
  // Mapping tab instead of silently switching. Reuses the same pattern as
  // the 'open-data-hub-mapping' action (line ~1210).
  const openMappingTab = () => {
    if (tpmPanelOpen) toggleTpmPanel();
    if (!dataHubOpen) toggleDataHub('mapping');
    else switchDataHubTab('mapping');
  };

  if (mode === 'multi') {
    if (_isMultiMappingComplete(appState.ui.tpConfig?.multi)) {
      _setTpMode('multi');
    } else {
      openMappingTab();
    }
    return;
  }

  if (mode === 'personalised') {
    if (_isPersonalisedRrMaxMapped()) {
      _setTpMode('personalised');
    } else {
      openMappingTab();
    }
  }
}

function _renderTpmModeBody() {
  const body = document.getElementById('tpm-mode-body');
  if (!body) return;
  const mode = appState.ui.tpConfig?.mode || 'fixed';
  if (mode === 'fixed') {
    // No body for Fixed mode — the card description already covers it.
    body.innerHTML = '';
  } else if (mode === 'multi') {
    _renderTpmMultiBody();
  } else if (mode === 'personalised') {
    _renderTpmPersonalisedBody();
  } else {
    body.innerHTML = '';
  }
}

// ── Feature Requirements registry (Phase 3.A.final, architecture Option α) ──
// Parallel to MISSING_DATA_META. Keyed by feature id, lists required dims per
// feature. Rendered in the Health tab as a separate "Feature requirements"
// block that does NOT contribute to missingCount / the warn badge — widget
// health and feature mapping stay fully decoupled.
//   requiredDims(tpConfig) returns the dim keys required under the active
//   mode configuration, letting features with variable requirements (like
//   Multi TP with tpCount=2 or 3) surface the right set.
//   openAction is the data-action fired when the Configure button is clicked.
const FEATURE_REQS = {
  'multi-tp': {
    label: 'Multi TP mode',
    requiredDims: (tpConfig) => {
      const n = tpConfig?.multi?.tpCount === 3 ? 3 : 2;
      return n === 3 ? ['tp1_rr', 'tp2_rr', 'tp3_rr'] : ['tp1_rr', 'tp2_rr'];
    },
    openAction: 'open-tpm-multi',
  },
  'personalised-tp': {
    label: 'Personalised TP mode',
    requiredDims: () => ['rrMax'],
    openAction: 'open-tpm-personalised',
  },
};

// Returns the current mapping status for the Multi TP required fields.
// "Mapped" = user set an override pointing to a column/field in the active data
// source. We do NOT verify the override resolves to real data — that's surfaced
// downstream (null tp_N_rr values trigger Phase 3.B warnings).
// Used by _renderTpmMultiBody (Phase 3.A.3) and the Feature Requirements block
// in the Health tab (Phase 3.A.final).
function _getMultiMappingStatus(tpCount) {
  const n = (tpCount === 3) ? 3 : 2;
  const dimKeys = n === 3 ? ['tp1_rr', 'tp2_rr', 'tp3_rr'] : ['tp1_rr', 'tp2_rr'];
  const dsMode = localStorage.getItem(DS_KEY) || 'demo';
  const apiOverrides = (dsMode === 'api') ? _getAPIFieldOverrides() : {};
  const csvOverrides = (dsMode !== 'api' && _lastCsvHeaders && _lastCsvHeaders.length)
    ? (_csvColumnOverrides || {})
    : {};
  const items = (appState.trades && appState.trades.items) || [];
  const _hasData = (dim) => items.some(t => t && t[dim] != null && Number.isFinite(t[dim]));
  const rows = dimKeys.map(dim => {
    const label = JOURNAL_DIMS.find(d => d.key === dim)?.label || dim;
    let mapped = null;
    if (dsMode === 'api') {
      mapped = _isNoMappingValue(apiOverrides[dim]) ? null : (apiOverrides[dim] || (_hasData(dim) ? '(auto-detected)' : null));
    } else if (_lastCsvHeaders && _lastCsvHeaders.length) {
      mapped = _isNoMappingValue(csvOverrides[dim]) ? null : (csvOverrides[dim] || _resolvedHeaderFor(dim) || null);
    } else {
      mapped = _hasData(dim) ? '(auto-detected)' : null;
    }
    return { dim, label, mapped };
  });
  return { complete: rows.every(r => !!r.mapped), rows, dsMode };
}

// Boolean wrapper used by computeEffectiveRR. Accepts the multi sub-config and
// reports whether every required tp_N_rr field is mapped for the active tpCount.
function _isMultiMappingComplete(multiCfg) {
  if (!multiCfg) return false;
  const n = multiCfg.tpCount === 3 ? 3 : 2;
  return _getMultiMappingStatus(n).complete;
}

// Whether the rrMax dim is mapped in the current data source. Used by the
// Phase 4 Bug 6 diagnostic to distinguish "rrMax not mapped" (config-level
// failure → global banner + empty widgets) from "this one trade missing a
// rrMax value" (per-trade edge case → silent fallback inside the calc).
function _isPersonalisedRrMaxMapped() {
  const dsMode = localStorage.getItem(DS_KEY) || 'demo';
  if (dsMode === 'api') {
    const o = _getAPIFieldOverrides();
    if (_isNoMappingValue(o.rrMax)) return false;
    if (o.rrMax) return true;
    // API has no format default — without an override, consider mapped only
    // if we actually observe rrMax data (covers auto-detected paths).
    return (appState.trades?.items || []).some(t => t && t.rrMax != null && Number.isFinite(t.rrMax));
  }
  // CSV / demo: format defaults resolve rrMax for the 3 templates + demo
  // ships with rm. Check override first, then CSV resolution, then data.
  if (_csvColumnOverrides && _isNoMappingValue(_csvColumnOverrides.rrMax)) return false;
  if (_csvColumnOverrides && _csvColumnOverrides.rrMax) return true;
  if (_lastCsvHeaders && _lastCsvHeaders.length) {
    if (typeof _dimResolvesInCsv === 'function' && _dimResolvesInCsv('rrMax')) return true;
  }
  return (appState.trades?.items || []).some(t => t && t.rrMax != null && Number.isFinite(t.rrMax));
}

// Per-mode messages, keyed by diagnostic code. Short + actionable.
const TPM_DIAGNOSTIC_MESSAGES = {
  'multi-mapping':         'Multi TP requires tp1_rr / tp2_rr fields mapped to your journal.',
  'multi-sum':             'Multi TP partials must sum to 100%.',
  'personalised-no-rrmax': 'Personalised TP requires RR Max field mapped to your journal.',
  'personalised-sum':      'Personalised TP partials must sum to 100%.',
};

// Returns null when the active tpConfig is fully computable against the current
// dataset / mapping, or { code, message, openAction } when a CONFIG-LEVEL
// failure should surface as a global banner (and widgets render empty rather
// than Fixed-fallback values). Per-trade edge cases (e.g. missing rrMax on
// one trade, below-all-targets winners) stay silent inside computeEffectiveRR.
function _tpmConfigDiagnostic(tpConfig) {
  const mode = tpConfig?.mode;
  if (mode === 'multi') {
    const m = tpConfig.multi;
    if (!_isMultiMappingComplete(m)) {
      return { code: 'multi-mapping', message: TPM_DIAGNOSTIC_MESSAGES['multi-mapping'], openAction: 'open-tpm-multi' };
    }
    const sum = (m.partials.tp1 || 0) + (m.partials.tp2 || 0) + (m.tpCount === 3 ? (m.partials.tp3 || 0) : 0);
    if (Math.abs(sum - 100) > 0.01) {
      return { code: 'multi-sum', message: TPM_DIAGNOSTIC_MESSAGES['multi-sum'], openAction: 'open-tpm-multi' };
    }
    return null;
  }
  if (mode === 'personalised') {
    const p = tpConfig.personalised;
    if (!_isValidPersonalisedConfig(p)) {
      // Pathological shape — treat as sum issue for the user-facing message
      // (same Configure CTA opens Personalised, same fix path).
      return { code: 'personalised-sum', message: TPM_DIAGNOSTIC_MESSAGES['personalised-sum'], openAction: 'open-tpm-personalised' };
    }
    if (!_isPersonalisedRrMaxMapped()) {
      return { code: 'personalised-no-rrmax', message: TPM_DIAGNOSTIC_MESSAGES['personalised-no-rrmax'], openAction: 'open-tpm-personalised' };
    }
    const sum = (p.partials.tp1 || 0) + (p.partials.tp2 || 0) + (p.tpCount === 3 ? (p.partials.tp3 || 0) : 0);
    if (Math.abs(sum - 100) > 0.01) {
      return { code: 'personalised-sum', message: TPM_DIAGNOSTIC_MESSAGES['personalised-sum'], openAction: 'open-tpm-personalised' };
    }
    return null;
  }
  return null; // fixed mode: always computable
}

// Populates the banner copy + wires the Configure button's data-action to the
// diagnostic's openAction, then un-hides the element. No-op when the banner
// element isn't in the DOM (e.g. early init paths before index.html parses).
function _showTpmInvalidBanner(diag) {
  const banner = document.getElementById('tpm-invalid-banner');
  const copy = document.getElementById('tpm-invalid-banner-copy');
  const btn = document.getElementById('tpm-invalid-banner-btn');
  if (!banner || !copy || !btn) return;
  copy.textContent = diag.message;
  btn.setAttribute('data-action', diag.openAction);
  banner.hidden = false;
}
function _hideTpmInvalidBanner() {
  const banner = document.getElementById('tpm-invalid-banner');
  if (banner && !banner.hidden) banner.hidden = true;
}

// Renders the "Feature requirements" block inside the Data Hub Health tab.
// Reads FEATURE_REQS + current mapping state + appState.ui.tpConfig, returns
// nothing (mutates DOM). Safe to call when the host element is absent (e.g.
// before DOMContentLoaded). Hooked into updateAttentionButton so it stays in
// sync with any mapping change.
function renderFeatureRequirementsBlock() {
  const host = document.getElementById('dhp-feature-reqs');
  if (!host) return;
  const cfg = appState.ui.tpConfig || {};
  const items = [];
  // Multi TP row
  {
    const feat = FEATURE_REQS['multi-tp'];
    const required = feat.requiredDims(cfg);
    const tpCount = cfg.multi?.tpCount === 3 ? 3 : 2;
    const { rows, complete } = _getMultiMappingStatus(tpCount);
    const mapped = rows.filter(r => !!r.mapped).length;
    const total = required.length;
    items.push({
      id: 'multi-tp',
      label: feat.label,
      status: `${mapped} of ${total} fields mapped`,
      tone: complete ? 'ok' : 'warn',
      openAction: feat.openAction,
    });
  }
  // Personalised TP row (Phase 4.A)
  {
    const feat = FEATURE_REQS['personalised-tp'];
    const required = feat.requiredDims(cfg);
    const { complete } = _getPersonalisedMappingStatus();
    const mapped = complete ? 1 : 0;
    const total = required.length;
    items.push({
      id: 'personalised-tp',
      label: feat.label,
      status: `${mapped} of ${total} fields mapped`,
      tone: complete ? 'ok' : 'warn',
      openAction: feat.openAction,
    });
  }
  if (!items.length) { host.innerHTML = ''; return; }
  host.innerHTML = `
    <div class="dhp-feature-reqs-title">Feature requirements</div>
    <ul class="dhp-feature-reqs-list">
      ${items.map(it => `
        <li class="dhp-feature-req-item is-${it.tone}">
          <span class="dhp-feature-req-label">${_escapeHtml(it.label)}</span>
          <span class="dhp-feature-req-status">${_escapeHtml(it.status)}</span>
          <button type="button" class="dhp-feature-req-btn" data-action="${_escapeHtml(it.openAction)}">Configure</button>
        </li>
      `).join('')}
    </ul>`;
}

// Compact mapping status shown when every required field is mapped.
// Renders a single ✓ badge to the right of the "Mapping status" label,
// with a custom CSS tooltip revealing the detailed field → source mappings
// on hover / focus. When mapping is incomplete, _renderTpmMappingStatusDetailed
// is used instead (unchanged legacy layout).
function _renderTpmMappingStatusCollapsed(rows) {
  const tipRows = rows.map(r => `
    <div class="tpm-status-tip-row">
      <span class="tpm-status-tip-key">${_escapeHtml(r.label)}</span>
      <span class="tpm-status-tip-val">${_escapeHtml(r.mapped || '')}</span>
    </div>`).join('');
  return `
    <div class="tpm-field tpm-field--row">
      <span class="tpm-field-label">Mapping status</span>
      <span class="tpm-status-badge-wrap">
        <span class="tpm-status-badge" tabindex="0"
              role="img" aria-label="All fields mapped">
          <span class="tpm-status-badge-icon" aria-hidden="true">✓</span>
          <span class="tpm-status-badge-text">All mapped</span>
        </span>
        <div class="tpm-status-tip" role="tooltip">
          <p class="tpm-status-tip-title">Mapped fields</p>
          ${tipRows}
        </div>
      </span>
    </div>`;
}

function _renderTpmMappingStatusDetailed(rows) {
  return `
    <div class="tpm-field">
      <div class="tpm-field-label">Mapping status</div>
      <ul class="tpm-status-list">
        ${rows.map(r => `
          <li class="tpm-status-row ${r.mapped ? 'is-ok' : 'is-missing'}">
            <span class="tpm-status-icon" aria-hidden="true">${r.mapped ? '✓' : '✗'}</span>
            <span class="tpm-status-label">${_escapeHtml(r.label)}</span>
            <span class="tpm-status-source">${r.mapped ? _escapeHtml(r.mapped) : 'Not mapped'}</span>
          </li>
        `).join('')}
      </ul>
    </div>`;
}

function _renderTpmMultiBody() {
  const body = document.getElementById('tpm-mode-body');
  if (!body) return;
  const cfg = appState.ui.tpConfig?.multi || _defaultMultiConfig();
  const tpCount = cfg.tpCount === 3 ? 3 : 2;
  const { complete, rows } = _getMultiMappingStatus(tpCount);

  const selectorHtml = `
    <div class="tpm-field">
      <div class="tpm-field-label">Number of TPs</div>
      <div class="tpm-tp-mode" role="tablist" aria-label="Number of TPs">
        <button type="button" class="tpm-tp-mode-btn${tpCount === 2 ? ' is-active' : ''}" data-tpm-tp-count="2" role="tab" aria-selected="${tpCount === 2}">2 TPs</button>
        <button type="button" class="tpm-tp-mode-btn${tpCount === 3 ? ' is-active' : ''}" data-tpm-tp-count="3" role="tab" aria-selected="${tpCount === 3}">3 TPs</button>
      </div>
    </div>`;

  const statusHtml = complete
    ? _renderTpmMappingStatusCollapsed(rows)
    : _renderTpmMappingStatusDetailed(rows);

  const gateHtml = complete ? '' : `
    <div class="tpm-gate">
      <p class="tpm-gate-copy">Map the required fields in Data Setup to enable Multi TP mode.</p>
      <button type="button" class="tpm-cta-btn" data-action="open-data-hub-mapping">Configure in Data Setup</button>
    </div>`;

  // Partials section only shown when every required field is mapped.
  // Soft validation (sum === 100) is surfaced via the live helper — invalid
  // states are saved to localStorage as-is (Phase 3.B falls back to trade.r
  // with a dev warning when consumed with invalid partials).
  const partialsHtml = complete ? _renderTpmMultiPartials(cfg, tpCount) : '';

  body.innerHTML = statusHtml + selectorHtml + gateHtml + partialsHtml;
}

function _renderTpmMultiPartials(multiCfg, tpCount) {
  const partials = (multiCfg && multiCfg.partials) || { tp1: 0, tp2: 0, tp3: 0 };
  const n = tpCount === 3 ? 3 : 2;
  let rows = '';
  for (let i = 1; i <= n; i++) {
    const key = `tp${i}`;
    const val = Number.isFinite(partials[key]) ? partials[key] : 0;
    rows += `
      <div class="tpm-plan-row tpm-plan-row--2col">
        <div class="tpm-plan-tp-pill">TP${i}</div>
        <div class="tpm-input-wrap">
          <input type="number" class="tpm-input" data-tpm-partial-key="${key}"
                 min="0" max="100" step="1" value="${val}" aria-label="TP${i} size %">
          <span class="tpm-suffix">%</span>
        </div>
      </div>`;
  }
  const sum = _tpmPartialsSum(partials, n);
  const tone = sum === 100 ? 'ok' : 'warn';
  const text = sum === 100 ? 'Sizes sum: 100% ✓' : `Sizes sum: ${_formatTpmSum(sum)}% — must equal 100%`;
  return `
    <div class="tpm-field">
      <div class="tpm-field-label">Partials</div>
      <div class="tpm-plan-frame">
        <div class="tpm-plan-head tpm-plan-head--2col">
          <div class="tpm-plan-head-cell"></div>
          <div class="tpm-plan-head-cell">Partial %</div>
        </div>
        ${rows}
        <div class="tpm-plan-footer">
          <div class="tpm-plan-helper" id="tpm-sum-helper" data-tone="${tone}">${text}</div>
        </div>
      </div>
    </div>`;
}

// Rounds to 2 decimals to avoid floating-point artifacts in the display
// without silently truncating meaningful precision at the partials level.
function _formatTpmSum(sum) {
  if (Number.isInteger(sum)) return String(sum);
  return (Math.round(sum * 100) / 100).toString();
}
function _tpmPartialsSum(partials, n) {
  let s = 0;
  for (let i = 1; i <= n; i++) s += Number(partials['tp' + i]) || 0;
  return Math.round(s * 100) / 100;
}

// Debounced persistence for partials inputs. Helper text updates synchronously
// (no debounce on feedback); localStorage write is deferred 300ms to batch
// rapid keystrokes without sacrificing responsiveness.
let _tpmPartialInputTimer = null;
function _handleTpmPartialInput(inputEl) {
  const key = inputEl.getAttribute('data-tpm-partial-key');
  if (!['tp1', 'tp2', 'tp3'].includes(key)) return;
  const cfg = appState.ui.tpConfig;
  if (!cfg || cfg.mode !== 'multi' || !_isValidMultiConfig(cfg.multi)) return;
  // Coerce to a finite number; empty / invalid input is treated as 0 so the
  // sum helper still reflects reality. We intentionally do NOT clamp to 0-100
  // — the field itself has min/max for browser-level hints but persistence is
  // lenient (see soft-validation decision).
  const raw = parseFloat(inputEl.value);
  const num = Number.isFinite(raw) ? raw : 0;
  cfg.multi.partials[key] = num;

  // Live visual update (synchronous)
  _updateTpmSumHelper();

  // Debounced write
  clearTimeout(_tpmPartialInputTimer);
  _tpmPartialInputTimer = setTimeout(() => {
    _saveTpConfig(cfg);
  }, 300);
}

function _updateTpmSumHelper() {
  const helper = document.getElementById('tpm-sum-helper');
  if (!helper) return;
  const cfg = appState.ui.tpConfig;
  if (!cfg?.multi) return;
  const n = cfg.multi.tpCount === 3 ? 3 : 2;
  const sum = _tpmPartialsSum(cfg.multi.partials || {}, n);
  helper.setAttribute('data-tone', sum === 100 ? 'ok' : 'warn');
  helper.textContent = sum === 100
    ? 'Sizes sum: 100% ✓'
    : `Sizes sum: ${_formatTpmSum(sum)}% — must equal 100%`;
}

function _setTpCount(count) {
  if (count !== 2 && count !== 3) return;
  const cfg = appState.ui.tpConfig;
  if (!cfg || cfg.mode !== 'multi') return;
  if (!_isValidMultiConfig(cfg.multi)) cfg.multi = _defaultMultiConfig();
  if (cfg.multi.tpCount === count) return;
  cfg.multi.tpCount = count;
  _saveTpConfig(cfg);
  _renderTpmMultiBody();
}

// ── Personalised TP mode: mapping, UI, handlers (Phase 4.A) ──
// Mirrors _getMultiMappingStatus / _renderTpmMultiBody / _setTpCount / the
// partials input handler, but targets rrMax (single dim) and adds a second
// input cluster for TP RR targets. All selectors reuse .tpm-* namespace.

// Uses in-memory data presence as the mapping signal. rrMax has format defaults
// across all 3 CSV parsers and may be populated via API override — a boolean
// "is any rrMax populated" is the only universally reliable check.
function _getPersonalisedMappingStatus() {
  const trades = Array.isArray(appState.trades?.items) ? appState.trades.items : [];
  const hasData = trades.some(t => t && t.rrMax != null && Number.isFinite(t.rrMax));
  const label = JOURNAL_DIMS.find(d => d.key === 'rrMax')?.label || 'RR Max';
  const dsMode = localStorage.getItem(DS_KEY) || 'demo';
  let source = null;
  if (hasData) {
    if (dsMode === 'api') {
      const o = _getAPIFieldOverrides();
      source = _isNoMappingValue(o.rrMax) ? 'No Mapping' : (o.rrMax || 'auto-detected');
    } else if (_lastCsvHeaders && _lastCsvHeaders.length) {
      source = (_csvColumnOverrides && _isNoMappingValue(_csvColumnOverrides.rrMax))
        ? 'No Mapping'
        : ((_csvColumnOverrides && _csvColumnOverrides.rrMax) || _resolvedHeaderFor('rrMax') || 'auto-detected');
    } else {
      source = 'built-in';
    }
  }
  return { complete: hasData, row: { dim: 'rrMax', label, mapped: source }, dsMode };
}

function _renderTpmPersonalisedBody() {
  const body = document.getElementById('tpm-mode-body');
  if (!body) return;
  const cfg = appState.ui.tpConfig?.personalised || _defaultPersonalisedConfig();
  const tpCount = cfg.tpCount === 3 ? 3 : 2;
  const { complete, row } = _getPersonalisedMappingStatus();

  const selectorHtml = `
    <div class="tpm-field">
      <div class="tpm-field-label">Number of TPs</div>
      <div class="tpm-tp-mode" role="tablist" aria-label="Number of TPs">
        <button type="button" class="tpm-tp-mode-btn${tpCount === 2 ? ' is-active' : ''}" data-tpm-ps-tp-count="2" role="tab" aria-selected="${tpCount === 2}">2 TPs</button>
        <button type="button" class="tpm-tp-mode-btn${tpCount === 3 ? ' is-active' : ''}" data-tpm-ps-tp-count="3" role="tab" aria-selected="${tpCount === 3}">3 TPs</button>
      </div>
    </div>`;

  const statusHtml = complete
    ? _renderTpmMappingStatusCollapsed([row])
    : _renderTpmMappingStatusDetailed([row]);

  const gateHtml = complete ? '' : `
    <div class="tpm-gate">
      <p class="tpm-gate-copy">Map RR Max in Data Setup to enable Personalised TP mode.</p>
      <button type="button" class="tpm-cta-btn" data-action="open-data-hub-mapping">Configure in Data Setup</button>
    </div>`;

  const warningHtml = complete ? `
    <div class="tpm-ps-warning" role="note">
      <span class="tpm-ps-warning-icon" aria-hidden="true">⚠</span>
      <span class="tpm-ps-warning-copy">This mode assumes price progression is monotonic. Cases where price hits TP2 then reverses to stop before TP1 cannot be detected from RR max alone.</span>
    </div>` : '';

  const planHtml = complete ? _renderTpmPersonalisedPlan(cfg, tpCount) : '';

  body.innerHTML = statusHtml + selectorHtml + gateHtml + warningHtml + planHtml;
}

// Unified Target + Partial% table (replaces the old stacked Targets / Partials
// sections). 3 columns: TP pill / Target (R) / Partial %. Data-attributes are
// identical to the legacy layout so the body-level input listener keeps
// dispatching via _handleTpmPersonalisedInput without change.
function _renderTpmPersonalisedPlan(psCfg, tpCount) {
  const targets = (psCfg && psCfg.targets) || { tp1: 1, tp2: 2, tp3: 3 };
  const partials = (psCfg && psCfg.partials) || { tp1: 0, tp2: 0, tp3: 0 };
  const n = tpCount === 3 ? 3 : 2;
  let rows = '';
  for (let i = 1; i <= n; i++) {
    const key = `tp${i}`;
    const tgt = Number.isFinite(targets[key]) ? targets[key] : 0;
    const prt = Number.isFinite(partials[key]) ? partials[key] : 0;
    rows += `
      <div class="tpm-plan-row">
        <div class="tpm-plan-tp-pill">TP${i}</div>
        <div class="tpm-input-wrap">
          <input type="number" class="tpm-input" data-tpm-ps-target-key="${key}"
                 min="0.1" step="0.1" value="${tgt}" aria-label="TP${i} target (R)">
          <span class="tpm-suffix">R</span>
        </div>
        <div class="tpm-input-wrap">
          <input type="number" class="tpm-input" data-tpm-ps-partial-key="${key}"
                 min="0" max="100" step="1" value="${prt}" aria-label="TP${i} size %">
          <span class="tpm-suffix">%</span>
        </div>
      </div>`;
  }
  const sum = _tpmPartialsSum(partials, n);
  const tone = sum === 100 ? 'ok' : 'warn';
  const text = sum === 100 ? 'Sizes sum: 100% ✓' : `Sizes sum: ${_formatTpmSum(sum)}% — must equal 100%`;
  return `
    <div class="tpm-field">
      <div class="tpm-field-label">TP Plan</div>
      <div class="tpm-plan-frame" id="tpm-ps-plan-frame">
        <div class="tpm-plan-head">
          <div class="tpm-plan-head-cell"></div>
          <div class="tpm-plan-head-cell">Target</div>
          <div class="tpm-plan-head-cell">Partial %</div>
        </div>
        ${rows}
        <div class="tpm-plan-footer">
          <div class="tpm-plan-helper" id="tpm-ps-sum-helper" data-tone="${tone}">${text}</div>
        </div>
      </div>
    </div>`;
}

function _updateTpmPsSumHelper() {
  const helper = document.getElementById('tpm-ps-sum-helper');
  if (!helper) return;
  const cfg = appState.ui.tpConfig;
  if (!cfg?.personalised) return;
  const n = cfg.personalised.tpCount === 3 ? 3 : 2;
  const sum = _tpmPartialsSum(cfg.personalised.partials || {}, n);
  helper.setAttribute('data-tone', sum === 100 ? 'ok' : 'warn');
  helper.textContent = sum === 100
    ? 'Sizes sum: 100% ✓'
    : `Sizes sum: ${_formatTpmSum(sum)}% — must equal 100%`;
}

// Debounced persistence for personalised targets + partials. Same pattern as
// _handleTpmPartialInput: live visual update is synchronous, LS write is
// deferred 300ms to batch rapid keystrokes.
let _tpmPsInputTimer = null;
function _handleTpmPersonalisedInput(inputEl) {
  const cfg = appState.ui.tpConfig;
  if (!cfg || cfg.mode !== 'personalised' || !_isValidPersonalisedConfig(cfg.personalised)) return;
  const targetKey = inputEl.getAttribute('data-tpm-ps-target-key');
  const partialKey = inputEl.getAttribute('data-tpm-ps-partial-key');
  const raw = parseFloat(inputEl.value);
  const num = Number.isFinite(raw) ? raw : 0;
  if (targetKey && ['tp1', 'tp2', 'tp3'].includes(targetKey)) {
    cfg.personalised.targets[targetKey] = num;
  } else if (partialKey && ['tp1', 'tp2', 'tp3'].includes(partialKey)) {
    cfg.personalised.partials[partialKey] = num;
    _updateTpmPsSumHelper();
  } else {
    return;
  }
  clearTimeout(_tpmPsInputTimer);
  _tpmPsInputTimer = setTimeout(() => { _saveTpConfig(cfg); }, 300);
}

function _setTpCountPersonalised(count) {
  if (count !== 2 && count !== 3) return;
  const cfg = appState.ui.tpConfig;
  if (!cfg || cfg.mode !== 'personalised') return;
  if (!_isValidPersonalisedConfig(cfg.personalised)) cfg.personalised = _defaultPersonalisedConfig();
  if (cfg.personalised.tpCount === count) return;
  cfg.personalised.tpCount = count;
  _saveTpConfig(cfg);
  _renderTpmPersonalisedBody();
}

function _initTpmPanelListeners() {
  const list = document.getElementById('tpm-mode-list');
  if (!list) return;
  list.addEventListener('change', (e) => {
    const input = e.target.closest('input[name="tpmMode"]');
    if (input) _setTpMode(input.value);
  });
  // Same pattern for the BE Management radios — a `change` listener lets the
  // browser drive the visual checked state natively, while our handler runs
  // afterwards and only re-syncs the dot for safety. Switching to data-action
  // click dispatch broke the visual sync because stopPropagation interfered
  // with the native radio state propagation.
  const beList = document.getElementById('tpm-be-list');
  beList?.addEventListener('change', (e) => {
    const input = e.target.closest('input[name="tpmBeMode"]');
    if (input) _setBeMode(input.value);
  });
  // Body-level delegation (Phase 3.A.3): the body re-renders on mode/tpCount
  // changes so per-control listeners would leak or require re-binding. One
  // listener on the stable container covers every dynamic Multi + Personalised
  // UI control. Data-attribute dispatch distinguishes the two modes.
  const body = document.getElementById('tpm-mode-body');
  body?.addEventListener('click', (e) => {
    const multiCountBtn = e.target.closest('.tpm-tp-mode-btn[data-tpm-tp-count]');
    if (multiCountBtn) {
      const n = parseInt(multiCountBtn.getAttribute('data-tpm-tp-count'), 10);
      if (n === 2 || n === 3) _setTpCount(n);
      return;
    }
    const psCountBtn = e.target.closest('.tpm-tp-mode-btn[data-tpm-ps-tp-count]');
    if (psCountBtn) {
      const n = parseInt(psCountBtn.getAttribute('data-tpm-ps-tp-count'), 10);
      if (n === 2 || n === 3) _setTpCountPersonalised(n);
      return;
    }
  });
  // Multi partials (Phase 3.A.final) + Personalised targets / partials (Phase 4.A).
  body?.addEventListener('input', (e) => {
    const multiInput = e.target.closest('.tpm-input[data-tpm-partial-key]');
    if (multiInput) { _handleTpmPartialInput(multiInput); return; }
    const psInput = e.target.closest('.tpm-input[data-tpm-ps-target-key], .tpm-input[data-tpm-ps-partial-key]');
    if (psInput) { _handleTpmPersonalisedInput(psInput); return; }
  });
}

// ══════════════════════════════════════════════════════════════
// NOTION PROPERTIES PANEL UI  —  Phase 1 (sub-task 2)
// Renders & manages the floating side-panel triggered from the
// Settings panel. Read/write goes through the customProps module
// at the top of this file (no direct localStorage here).
// ══════════════════════════════════════════════════════════════
let _npFormState = null; // { mode: 'add'|'edit', editingId, keyTouched }
let _npFormEscHandler = null;

// Backward-compat stub: legacy callers now route to the unified Data Hub.
function toggleNotionPropsPanel(forceClose = false) {
  if (forceClose) {
    if (dataHubOpen) toggleDataHub();
    return;
  }
  if (!dataHubOpen) toggleDataHub('custom');
  else switchDataHubTab('custom');
}

/** Re-render the full list + counter + add-button disabled state. */
function _renderCustomPropsList() {
  const listEl = document.getElementById('np-list');
  const counterEl = document.getElementById('np-counter');
  const addBtn = document.getElementById('np-add-btn');
  if (!listEl || !counterEl || !addBtn) return;
  const props = loadCustomProps();
  if (!props.length) {
    listEl.innerHTML = `<div class="np-empty">No custom properties yet.<br>Click <strong>+ Add property</strong> to declare your first Notion property.</div>`;
    counterEl.textContent = '';
    counterEl.classList.remove('np-counter--warn');
  } else {
    listEl.innerHTML = props.map(p => _npItemHTML(p, _npCoverageForProp(p))).join('');
    counterEl.textContent = `${props.length} / ${CUSTOM_PROPS_MAX} properties`;
    counterEl.classList.toggle('np-counter--warn', props.length >= CUSTOM_PROPS_WARN);
    listEl.querySelectorAll('.np-item').forEach(_bindNotionPropDragHandlers);
  }
  addBtn.toggleAttribute('disabled', props.length >= CUSTOM_PROPS_MAX);
}

function _npItemHTML(p, cov) {
  const safeName = _escHTML(p.name);
  const safeKey  = _escHTML(p.key);
  const onLabel  = p.showInFilters ? '◉ filter' : '○ hidden';
  const pending  = _npPendingDeleteId === p.id;
  const editing  = _npFormState?.mode === 'edit' && _npFormState.editingId === p.id;
  const covHtml  = (cov && cov.total > 0)
    ? `<span class="np-coverage${cov.covered < cov.total ? ' is-partial' : ''}">${cov.covered}/${cov.total} trades</span>`
    : '';
  const popover = pending
    ? `<div class="np-del-popover" role="dialog" aria-label="Confirm delete">
         <span class="np-del-popover-text">Delete?</span>
         <button class="np-del-cancel-btn" data-action="notion-prop-delete-cancel" data-prop-id="${p.id}" type="button">Cancel</button>
         <button class="np-del-confirm-btn" data-action="notion-prop-delete-confirm" data-prop-id="${p.id}" type="button">Delete</button>
       </div>`
    : '';
  const inlineForm = editing
    ? `<div class="np-form-inline-slot" data-for-prop-id="${p.id}">${_buildPropertyFormHTML(p, true)}</div>`
    : '';
  return `
    <div class="np-item${pending ? ' is-pending-delete' : ''}${editing ? ' is-editing' : ''}" draggable="${pending || editing ? 'false' : 'true'}" data-prop-id="${p.id}">
      <span class="np-handle" title="Drag to reorder">⋮⋮</span>
      <div class="np-name">
        <span>${safeName}</span>
        <span class="np-name-key">${safeKey}</span>
        ${covHtml}
      </div>
      <span class="np-type ${_npTypeClass(p.type)}">${_escHTML(p.type)}</span>
      <button class="np-visibility" data-action="notion-prop-toggle-visibility" data-prop-id="${p.id}" data-on="${p.showInFilters}" title="Show in sidebar filters">${onLabel}</button>
      <button class="np-action-btn${editing ? ' active' : ''}" data-action="notion-prop-edit" data-prop-id="${p.id}" title="Edit" aria-expanded="${editing}">✎</button>
      <button class="np-action-btn np-action-btn--del${pending ? ' active' : ''}" data-action="notion-prop-delete" data-prop-id="${p.id}" title="Delete" aria-expanded="${pending}">✕</button>
      ${popover}
    </div>
    ${inlineForm}`;
}

function _npCoverageForProp(p) {
  const items = Array.isArray(appState.trades?.items) ? appState.trades.items : [];
  let covered = 0;
  for (const t of items) {
    // Refacto Total 2026-05-24 — step 3: single deterministic reader against
    // the immutable notionSourceName.
    const v = t.extras?.[p?.notionSourceName];
    if (v == null || v === '' || (Array.isArray(v) && !v.length)) continue;
    covered++;
  }
  return { covered, total: items.length };
}

function _escHTML(s) {
  return String(s ?? '').replace(/[&<>"']/g, ch => (
    { '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[ch]
  ));
}

// Maps a custom-prop type to the `is-*` modifier class used by both the Guide
// pills and the Custom-fields badges — keeps type-coloring consistent.
function _npTypeClass(type) {
  switch (type) {
    case 'number':       return 'is-number';
    case 'date':         return 'is-date';
    case 'select':       return 'is-select';
    case 'multi-select': return 'is-multiselect';
    case 'checkbox':     return 'is-checkbox';
    case 'formula':      return 'is-formula';
    default:             return '';
  }
}

// `seedOverride` is used by the "+ Add" buttons in the Detected section to
// pre-fill name/key/type from a discovered column. Treats the suggested key
// as user-touched so auto-suggest doesn't clobber it on the first name edit.
// When `detectedColKey` is set, the form renders inline under that detected
// item — otherwise it lands in the default top slot (#np-form-host).
function _openAddPropertyForm(seedOverride = null, detectedColKey = null) {
  if (loadCustomProps().length >= CUSTOM_PROPS_MAX) return;
  const seed = seedOverride
    ? { name: seedOverride.name || '', key: seedOverride.key || '', type: seedOverride.type || 'text', showInFilters: seedOverride.showInFilters !== false }
    : { name: '', key: '', type: 'text', showInFilters: true };
  _npFormState = { mode: 'add', editingId: null, keyTouched: !!seedOverride, detectedColKey };
  _renderPropertyForm(seed);
}

function _openEditPropertyForm(id) {
  // Toggle: a second click on the same item's pencil closes the form.
  if (_npFormState?.mode === 'edit' && _npFormState.editingId === id) {
    _closePropertyForm();
    return;
  }
  const prop = loadCustomProps().find(p => p.id === id);
  if (!prop) return;
  _npFormState = { mode: 'edit', editingId: id, keyTouched: true };
  _renderPropertyForm(prop);
}

function _closePropertyForm() {
  const wasEdit = _npFormState?.mode === 'edit';
  const wasDetectedAdd = _npFormState?.mode === 'add' && !!_npFormState.detectedColKey;
  _npFormState = null;
  const host = document.getElementById('np-form-host');
  if (host) host.innerHTML = '';
  if (_npFormEscHandler) {
    document.removeEventListener('keydown', _npFormEscHandler);
    _npFormEscHandler = null;
  }
  // Inline forms live next to their source item — re-render the relevant
  // surface so the slot disappears.
  if (wasEdit) _renderCustomPropsList();
  if (wasDetectedAdd) _renderDetectedColumns();
}

/** Builds the form markup. Edit mode hides the "Show in Filters" toggle —
 *  visibility is controlled exclusively from the list item's quick action. */
function _buildPropertyFormHTML(seed, isEdit) {
  const title = isEdit ? 'Edit property' : 'New property';
  const types = CUSTOM_PROP_TYPES.map(t =>
    `<option value="${t}"${t === seed.type ? ' selected' : ''}>${t}</option>`
  ).join('');
  const showInFiltersField = isEdit ? '' : `
    <label class="np-form-toggle">
      <input type="checkbox" id="np-f-show" ${seed.showInFilters ? 'checked' : ''}>
      <span>Show in sidebar Filters</span>
    </label>`;
  return `
    <div class="np-form${isEdit ? ' np-form--inline' : ''}" id="np-form">
      <div class="np-form-title">${title}</div>
      <div class="np-field">
        <label class="np-field-label" for="np-f-name">Name</label>
        <input class="np-input" id="np-f-name" type="text" maxlength="60" value="${_escHTML(seed.name)}" placeholder="Risk %, Emotion, Confluence…" autocomplete="off">
        <div class="np-error" id="np-f-name-err"></div>
      </div>
      <div class="np-field">
        <label class="np-field-label" for="np-f-key">Key</label>
        <input class="np-input np-input--key" id="np-f-key" type="text" maxlength="40" value="${_escHTML(seed.key)}" placeholder="riskPercent" autocomplete="off" spellcheck="false">
        <div class="np-error" id="np-f-key-err"></div>
      </div>
      <div class="np-field">
        <label class="np-field-label" for="np-f-type">Type</label>
        <select class="np-select" id="np-f-type">${types}</select>
        <div class="np-error" id="np-f-type-err"></div>
      </div>
      ${showInFiltersField}
      <div class="np-form-actions">
        <button type="button" class="np-form-btn" data-action="notion-prop-cancel-form">Cancel</button>
        <button type="button" class="np-form-btn np-form-btn--save" data-action="notion-prop-save-form">${isEdit ? 'Save' : 'Add'}</button>
      </div>
    </div>`;
}

function _bindPropertyFormInputs() {
  const nameEl = document.getElementById('np-f-name');
  const keyEl  = document.getElementById('np-f-key');
  if (!nameEl) return;
  // Auto-suggest key from name typing — only while the user hasn't touched the key field.
  nameEl.addEventListener('input', () => {
    if (!_npFormState || _npFormState.keyTouched) return;
    if (keyEl) keyEl.value = suggestCustomPropKey(nameEl.value);
  });
  keyEl?.addEventListener('input', () => {
    if (_npFormState) _npFormState.keyTouched = true;
  });
  // Escape key closes the form (scoped — bound at open, cleaned at close).
  if (_npFormEscHandler) document.removeEventListener('keydown', _npFormEscHandler);
  _npFormEscHandler = (e) => { if (e.key === 'Escape') _closePropertyForm(); };
  document.addEventListener('keydown', _npFormEscHandler);
  nameEl.focus();
}

/** Render the form — targets the right surface depending on the flow:
 *   - edit mode           → inline under the edited item
 *   - add from detected   → inline under the detected column
 *   - plain add            → top slot `#np-form-host` */
function _renderPropertyForm(seed) {
  const mode = _npFormState?.mode;
  const detectedColKey = _npFormState?.detectedColKey || null;
  if (mode === 'edit') {
    _renderCustomPropsList();
    _bindPropertyFormInputs();
    requestAnimationFrame(() => {
      try { document.getElementById('np-form')?.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch (e) {}
    });
    return;
  }
  if (mode === 'add' && detectedColKey) {
    _renderDetectedColumns();
    _bindPropertyFormInputs();
    requestAnimationFrame(() => {
      try { document.getElementById('np-form')?.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch (e) {}
    });
    return;
  }
  const host = document.getElementById('np-form-host');
  if (!host) return;
  host.innerHTML = _buildPropertyFormHTML(seed, false);
  _bindPropertyFormInputs();
}

function _handleSavePropertyForm() {
  if (!_npFormState) return;
  const name = document.getElementById('np-f-name')?.value ?? '';
  const key  = document.getElementById('np-f-key')?.value ?? '';
  const type = document.getElementById('np-f-type')?.value ?? 'text';
  const showInFiltersInput = document.getElementById('np-f-show');
  // Reset previous errors
  ['name','key','type'].forEach(f => {
    document.getElementById('np-f-' + f)?.classList.remove('np-input--err','np-select--err');
    const errEl = document.getElementById('np-f-' + f + '-err');
    if (errEl) errEl.textContent = '';
  });
  let result;
  if (_npFormState.mode === 'add') {
    // "+ Add from Detected" path: detectedColKey holds the immutable Notion
    // property name as it appears in the raw Notion response. Pass it through
    // as notionSourceName so a later rename of the friendly `name` doesn't
    // break the extras lookup. Manual Add path (detectedColKey null) falls
    // back to name.trim() inside addCustomProp.
    result = addCustomProp({
      name, key, type,
      showInFilters: showInFiltersInput ? showInFiltersInput.checked : true,
      notionSourceName: _npFormState.detectedColKey || null,
    });
  } else {
    result = updateCustomProp(_npFormState.editingId, { name, key, type });
  }
  if (!result.ok) {
    _showFormError(result.field || 'name', result.error || 'Invalid input.');
    return;
  }
  _closePropertyForm();
  _renderNotionPropsPanel();
}

function _showFormError(field, message) {
  const inputEl = document.getElementById('np-f-' + field);
  const errEl   = document.getElementById('np-f-' + field + '-err');
  if (inputEl) inputEl.classList.add(inputEl.tagName === 'SELECT' ? 'np-select--err' : 'np-input--err');
  if (errEl)   errEl.textContent = message;
}

// Inline two-step delete confirm — mirrors the `.po-delete-confirm` pattern
// used by the Partial Planner preset tune panel. First click arms the item;
// second click on Cancel dismisses, click on Delete commits.
let _npPendingDeleteId = null;

function _handleDeleteProperty(id) {
  const prop = loadCustomProps().find(p => p.id === id);
  if (!prop) return;
  // Toggle: if already armed on this same item, a second ✕ click dismisses.
  _npPendingDeleteId = (_npPendingDeleteId === id) ? null : id;
  _renderCustomPropsList();
}

function _handleDeleteCancel(id) {
  if (_npPendingDeleteId === id) _npPendingDeleteId = null;
  _renderCustomPropsList();
}

function _handleDeleteConfirm(id) {
  const prop = loadCustomProps().find(p => p.id === id);
  if (!prop) { _npPendingDeleteId = null; _renderCustomPropsList(); return; }
  if (_npFormState?.editingId === id) _closePropertyForm();
  _npPendingDeleteId = null;
  deleteCustomProp(id);
  _renderNotionPropsPanel();
}

// Outside-click dismiss for the delete popover.
document.addEventListener('mousedown', e => {
  if (_npPendingDeleteId === null) return;
  const pendingItem = document.querySelector(`.np-item.is-pending-delete[data-prop-id="${_npPendingDeleteId}"]`);
  if (!pendingItem) return;
  const popover = pendingItem.querySelector('.np-del-popover');
  const delBtn  = pendingItem.querySelector('.np-action-btn--del');
  // A click on the ✕ itself toggles via its own case handler — let it through.
  if (popover?.contains(e.target) || delBtn?.contains(e.target)) return;
  _npPendingDeleteId = null;
  _renderCustomPropsList();
});

function _handleToggleVisibility(id) {
  const prop = loadCustomProps().find(p => p.id === id);
  if (!prop) return;
  updateCustomProp(id, { showInFilters: !prop.showInFilters });
  _renderNotionPropsPanel();
}

// ── HTML5 drag-and-drop reorder ──
let _npDragSrcId = null;
function _bindNotionPropDragHandlers(item) {
  item.addEventListener('dragstart', e => {
    _npDragSrcId = item.dataset.propId;
    item.classList.add('dragging');
    try { e.dataTransfer.setData('text/plain', _npDragSrcId); e.dataTransfer.effectAllowed = 'move'; } catch {}
  });
  item.addEventListener('dragend', () => {
    item.classList.remove('dragging');
    document.querySelectorAll('.np-item.drag-over-top, .np-item.drag-over-bottom')
      .forEach(el => el.classList.remove('drag-over-top','drag-over-bottom'));
    _npDragSrcId = null;
  });
  item.addEventListener('dragover', e => {
    if (!_npDragSrcId || _npDragSrcId === item.dataset.propId) return;
    e.preventDefault();
    const rect = item.getBoundingClientRect();
    const before = (e.clientY - rect.top) < rect.height / 2;
    item.classList.toggle('drag-over-top', before);
    item.classList.toggle('drag-over-bottom', !before);
  });
  item.addEventListener('dragleave', () => {
    item.classList.remove('drag-over-top','drag-over-bottom');
  });
  item.addEventListener('drop', e => {
    e.preventDefault();
    if (!_npDragSrcId || _npDragSrcId === item.dataset.propId) return;
    const rect = item.getBoundingClientRect();
    const before = (e.clientY - rect.top) < rect.height / 2;
    const props = loadCustomProps();
    const targetIdx = props.findIndex(p => p.id === item.dataset.propId);
    if (targetIdx === -1) return;
    const newIdx = before ? targetIdx : targetIdx + 1;
    const srcIdx = props.findIndex(p => p.id === _npDragSrcId);
    // Account for the index shift when moving downward.
    const adjusted = (srcIdx < newIdx) ? newIdx - 1 : newIdx;
    reorderCustomProp(_npDragSrcId, adjusted);
    _renderNotionPropsPanel();
  });
}

// ══════════════════════════════════════════════════════════════
// AUTO-DETECT COLUMNS  —  sub-task 2.5
// Surfaces dataset columns the user hasn't declared yet, with a
// best-guess type. Read sources by mode:
//   demo → keys of the first normalized trade
//   csv  → _lastCsvHeaders captured at parse time
//   api  → _getRawAPICache() (typed Notion objects), with a
//          fallback to scanning normalized trades when raw missing
// ══════════════════════════════════════════════════════════════

// Anything in this set is suppressed from the "Detected" suggestions.
// Includes: validator-reserved keys, every canonical normalized trade
// field, every CSV header variant seen across the 3 parsers (FR + EN),
// and demo short-keys. Comparison is case-insensitive after trimming.
const _NATIVE_DETECTION_BLACKLIST = new Set([
  // — Internal / pipeline-computed fields (never user-declarable) —
  '_notionid','_rawrowindex','effectiver','effectiveclass','_effectiveclassmode',
  // — Reserved validator keys (mirror of _RESERVED_PROP_KEYS) —
  'outcome','setup','session','day','pair','direction','obstacles','h4obs','tradetype','bemanagement','hour',
  'd','m','p','s','sd','ss','su','w','o','h4','be','oc','r','rm','dir','tt','bad','inv','h','tier','flip','h4s','m15s','tp','notion','notionurl',
  // — Canonical normalized trade fields exposed on every t —
  'date','month','outcome','direction','badfeeling','invalide','setupdetail','sessionutc','timeutc1','rrmax','imgm15','imgh4before','imgm15after','extras','h4',
  // — Demo loader extras —
  'img15','img4h','imgaft',
  // — CSV headers (Flipping Market FR, Pro Template EN, Beginner) —
  'pair','actif','m15 type','m15 type détail','m15 type detail','m15 type détails','m15 type details',
  'session','jour','résultat tp 1','resultat tp 1','rr tp 1','rr max','rr max ','rr max atteint','rr max atteint ',
  'obstacles m15','obstacles h4','type de trade','bad feeling','ordre','order',
  'notion url','url notion','page url','url',
  'position result','position type','h4 obstacles','m15 obstacles',
  'm15 confirmation / continu','m15 confirmation / continunation','confirmation','confirmation / continunation',
  'time (utc+1)','hour +1','time utc+1',
  'm15 before','h4 before','m15 after','m15after','h4before',
  'h4 after','h4after',
  'tv m15 before','tv h4 before','tv m15 after','tv h4 after',   // TradingView share URL convention
  'screenshot m15','m15 screenshot','image m15','m15 image','photo m15','m15 photo',
  'screenshot h4','h4 screenshot','image h4','h4 image',
  'screenshot h4 after','h4 after screenshot','image h4 after','h4 image after',
  'screenshot m15 after','m15 after screenshot',
  'm15',           // standalone screenshot column
  'session utc','session formule','session formula','sessionformule','sessionformuleutc',
  'date',
  'rrtp1','rrmaxatteint',
]);

// Session-only — cleared on reload by design (no localStorage).
let _detectedColDismissed = new Set();

// Normalized name comparison: lowercase + strip whitespace/_/-. Used to
// dedupe a detected column against an already-declared property by name OR key.
function _normalizeForMatch(s) {
  return String(s ?? '').trim().toLowerCase().replace(/[\s_-]+/g, '');
}

// Map a Notion property `type` string onto our 6 supported types.
// Also accepts formula / rollup result sub-types (`'string'` | `'boolean'`)
// when callers have introspected the wrapper to extract the effective type.
function _notionTypeToCustom(t) {
  switch (t) {
    case 'select':       return 'select';
    case 'status':       return 'select';        // status is select-shaped (single named value)
    case 'multi_select': return 'multi-select';
    case 'number':       return 'number';
    case 'checkbox':     return 'checkbox';
    case 'boolean':      return 'checkbox';      // formula/rollup boolean result
    case 'date':         return 'date';
    case 'rich_text':
    case 'title':
    case 'string':       return 'text';          // formula/rollup string result
    default:             return 'text';   // url / email / phone / relation / people / files …
  }
}

// Heuristic type inference from string values (CSV/demo path). API path
// supplies `apiType` and short-circuits to the direct mapping.
function _detectColumnType(values, apiType = null) {
  if (apiType) return _notionTypeToCustom(apiType);
  const vals = (values || []).filter(v => v != null && v !== '');
  if (!vals.length) return 'text';

  const isNumberLike = v => {
    if (typeof v === 'number') return Number.isFinite(v);
    const n = Number(String(v).replace(',', '.'));
    return Number.isFinite(n) && String(v).trim() !== '';
  };
  if (vals.every(isNumberLike)) return 'number';

  const BOOLISH = new Set(['true','false','1','0','yes','no','oui','non','x','✓']);
  if (vals.every(v => BOOLISH.has(String(v).trim().toLowerCase()))) return 'checkbox';

  // Multi-select tightened per brief: only ", " or "|" as separators,
  // every segment under 40 chars, and uniques < 50% of dataset. This
  // keeps free-text "Notes" columns (sentences with commas) out.
  const looksLikeTagList = v => {
    const s = String(v);
    if (!(s.includes(', ') || s.includes('|'))) return false;
    const parts = s.split(/, |\|/).map(x => x.trim()).filter(Boolean);
    if (parts.length < 2) return false;
    return parts.every(p => p.length < 40);
  };
  const stringVals = vals.map(v => String(v));
  const uniques = new Set(stringVals.map(v => v.trim().toLowerCase())).size;
  const uniqRatio = uniques / vals.length;

  if (stringVals.some(looksLikeTagList) && uniqRatio < 0.5) return 'multi-select';
  if (uniques <= 20 && uniqRatio <= 0.5) return 'select';
  return 'text';
}

// Persistent cache of the API-mode detected fields list. The raw Notion cache
// is in-memory only (signed image URLs blow the localStorage quota — see
// _persistRawAPIToSession), so without this lightweight snapshot the Detected
// section is empty on every page reload until the user clicks Sync. We persist
// just the {key, name, type, sampleCount} tuples (~3 KB for ~30 props).
const DETECTED_FIELDS_LS_PREFIX = 'flipping_detected_fields_v1_';
function _detectedFieldsLSKey(src) {
  return getProfileScopedKey(DETECTED_FIELDS_LS_PREFIX + src);
}
function _persistDetectedFields(fields, src) {
  try {
    const key = _detectedFieldsLSKey(src);
    if (!fields || !fields.length) {
      try { localStorage.removeItem(key); } catch {}
      return;
    }
    safeSetLocalStorage(key, JSON.stringify(fields), {
      kind: 'detectedFields',
      activeProfileId: getActiveJournalProfile()?.id || '',
      activeHtfSource: src,
    });
  } catch (e) {}
}
function _loadDetectedFields(src) {
  try {
    const raw = localStorage.getItem(_detectedFieldsLSKey(src));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : null;
  } catch (e) { return null; }
}

// Walk the active dataset and return column candidates. Each entry:
//   { key: rawHeaderOrNotionKey, name: rawHeaderOrNotionKey, type, sampleCount }
// Filters: native blacklist, already-declared (by key OR name normalized
// match), session-dismissed, and empty columns (zero non-null values).
function _scanDatasetColumns() {
  const mode = localStorage.getItem(DS_KEY) || 'demo';
  const declared = loadCustomProps();
  const declaredMatch = new Set();
  for (const p of declared) {
    declaredMatch.add(_normalizeForMatch(p.key));
    declaredMatch.add(_normalizeForMatch(p.name));
  }
  const isExcluded = (header) => {
    const norm = String(header).trim().toLowerCase();
    if (_NATIVE_DETECTION_BLACKLIST.has(norm)) return true;
    if (_detectedColDismissed.has(header)) return true;
    if (declaredMatch.has(_normalizeForMatch(header))) return true;
    return false;
  };

  // ── Mode: API (raw Notion shape preferred) ──
  if (mode === 'api') {
    const currentSrc = _getCurrentHTFSource();
    const raw = (typeof _getRawAPICache === 'function') ? _getRawAPICache() : null;
    if (raw && raw.length) {
      // Merge keys across the first 20 trades to be safe with sparse props.
      const headerOrder = [];
      const seen = new Set();
      const sample = raw.slice(0, 20);
      for (const t of sample) {
        const props = t?.properties || t || {};
        for (const k of Object.keys(props)) {
          if (!seen.has(k)) { seen.add(k); headerOrder.push(k); }
        }
      }
      // Dedupe normalized variants: the Vercel proxy emits both the original
      // Notion property name AND a JS-friendly camelCase alias (e.g. "M15 Pros"
      // and "m15Pros"). Keep the longer/human-readable variant per normalized
      // group; without this dedup the Detected list shows each property twice.
      const winnerByNorm = new Map();
      for (const k of headerOrder) {
        if (isExcluded(k)) continue;
        const norm = _normalizeForMatch(k);
        const existing = winnerByNorm.get(norm);
        if (!existing || k.length > existing.length) winnerByNorm.set(norm, k);
      }
      const winners = new Set(winnerByNorm.values());
      const out = [];
      for (const k of headerOrder) {
        if (!winners.has(k)) continue;
        // ── Type detection ──
        // Path A (Notion native shape): propObj is `{ type, ... }`. Peek into
        // formula/rollup wrappers for the inner result sub-type so a number
        // formula maps to `number`, a boolean to `checkbox`, etc.
        // Path B (flat proxy shape): propObj is the raw value already. Fall
        // back to heuristic detection on a value sample via _detectColumnType.
        let apiType = null;
        let innerType = null;
        const valueSample = [];
        for (const t of sample) {
          const props = t?.properties || t || {};
          const propObj = props[k];
          if (propObj === null || propObj === undefined) continue;
          if (typeof propObj === 'object' && !Array.isArray(propObj) && propObj.type) {
            if (!apiType) apiType = propObj.type;
            if (apiType === 'formula' && !innerType && propObj.formula?.type) {
              innerType = propObj.formula.type;
            }
            if (apiType === 'rollup' && !innerType && propObj.rollup?.type) {
              innerType = propObj.rollup.type;
            }
          } else if (propObj !== '') {
            valueSample.push(propObj);
          }
        }
        let customType;
        if (apiType) {
          const effective = (apiType === 'formula' || apiType === 'rollup')
            ? (innerType || 'text')
            : apiType;
          customType = _notionTypeToCustom(effective);
        } else if (valueSample.every(v => Array.isArray(v) && v.length > 0) && valueSample.length) {
          customType = 'multi-select';
        } else {
          customType = _detectColumnType(valueSample);
        }
        // Empty-column check: prefer the typed extractor when shape is native,
        // otherwise treat any truthy raw value as non-empty (flat scalars).
        const syntheticProp = { key: k, type: customType };
        let nonEmpty = 0;
        for (const t of raw) {
          const props = t?.properties || t || {};
          const v = apiType
            ? _extractApiValueForProp(props, syntheticProp)
            : props[k];
          if (v !== null && v !== undefined && v !== '' && !(Array.isArray(v) && v.length === 0)) nonEmpty++;
        }
        if (nonEmpty === 0) continue;
        out.push({ key: k, name: k, type: customType, sampleCount: nonEmpty });
      }
      if (out.length) {
        // Persist the lightweight detected list so the next reload can restore
        // it without waiting for a fresh API sync. Raw cache lives in memory
        // only (see _persistRawAPIToSession comment) — without this snapshot
        // the Detected section is empty until the user re-syncs.
        _persistDetectedFields(out, currentSrc);
        return out;
      }
      // fall through to fallback path
    }
    // Raw cache empty (cold reload after memory wipe): restore from the
    // persisted snapshot so the Detected list survives a refresh without
    // forcing the user to resync. Re-apply the live exclusion filter so
    // newly-declared / dismissed entries don't reappear from the cache.
    const cached = _loadDetectedFields(currentSrc);
    if (cached && cached.length) {
      return cached.filter(f => !isExcluded(f.key));
    }
    // Fallback: scan normalized trade objects (no raw Notion types available).
    return _scanFromNormalizedTrades(isExcluded);
  }

  // ── Mode: CSV (use captured headers + raw rows) ──
  // Reads from _lastCsvRows (raw row objects), NOT from t.extras — extras only
  // gets populated for declared keys, so a fresh CSV before any declaration
  // would otherwise show an empty Detected list despite real columns.
  if (mode === 'csv') {
    const headers = (Array.isArray(_lastCsvHeaders) ? _lastCsvHeaders : []).filter(Boolean);
    if (!headers.length) return [];
    const rows = Array.isArray(_lastCsvRows) ? _lastCsvRows : [];
    const out = [];
    for (const h of headers) {
      if (isExcluded(h)) continue;
      const values = rows
        .map(r => r?.[h])
        .filter(v => v !== null && v !== undefined && v !== '');
      if (!values.length) continue;
      out.push({ key: h, name: h, type: _detectColumnType(values), sampleCount: values.length });
    }
    return out;
  }

  // ── Mode: Demo (scan first trade keys) ──
  return _scanFromNormalizedTrades(isExcluded);
}

// Common path for demo + API-fallback: collect non-blacklisted keys present
// on the normalized trade items. Type inferred via heuristic (no API hint).
function _scanFromNormalizedTrades(isExcluded) {
  const items = appState.trades.items || [];
  if (!items.length) return [];
  // Merge keys from first 20 trades + their extras to catch sparse props.
  const headerOrder = [];
  const seen = new Set();
  const sample = items.slice(0, 20);
  const collect = (k) => { if (!seen.has(k)) { seen.add(k); headerOrder.push(k); } };
  for (const t of sample) {
    if (t && typeof t === 'object') {
      for (const k of Object.keys(t)) if (k !== 'extras') collect(k);
      if (t.extras && typeof t.extras === 'object') {
        for (const k of Object.keys(t.extras)) collect(k);
      }
    }
  }
  const out = [];
  for (const k of headerOrder) {
    if (isExcluded(k)) continue;
    const values = [];
    for (const t of items) {
      const v = (t?.extras && Object.prototype.hasOwnProperty.call(t.extras, k))
        ? t.extras[k]
        : t?.[k];
      if (v !== null && v !== undefined && v !== '') values.push(v);
    }
    if (!values.length) continue;
    out.push({ key: k, name: k, type: _detectColumnType(values), sampleCount: values.length });
  }
  return out;
}

/** Render the "Detected in your data" section. Shows:
 *   - Demo mode + 0 results → contextual hint to load CSV / connect API
 *   - CSV/API + 0 results   → section hidden (no noise)
 *   - >0 results            → header + count + items list */
function _renderDetectedColumns() {
  const host = document.getElementById('np-detected');
  if (!host) return;
  const mode = localStorage.getItem(DS_KEY) || 'demo';
  // Sort alphabetically by display name (case-insensitive, locale-aware) so
  // the Detected list is easy to scan. Sort at the consumer level rather than
  // inside _scanDatasetColumns so the underlying detection order (which mirrors
  // the source iteration) stays available to anyone else who wants it raw.
  const cols = _scanDatasetColumns().slice().sort((a, b) =>
    String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' })
  );
  const refreshBtn = `<button class="np-refresh-btn" data-action="notion-prop-refresh" title="Re-scan the data and restore any dismissed detected columns">↺ Refresh</button>`;
  if (!cols.length) {
    host.classList.add('has-content');
    const body = (mode === 'demo')
      ? `<div class="np-detected-empty-demo">Load your own CSV or connect your Notion database to discover additional properties.</div>`
      : `<div class="np-detected-empty-demo">No new properties detected. Click ↺ Refresh to re-scan.</div>`;
    host.innerHTML = `
      <div class="np-detected-header">
        <span class="np-detected-title">Detected in your data</span>
        ${refreshBtn}
      </div>
      ${body}`;
    return;
  }
  host.classList.add('has-content');
  const pendingAddKey = (_npFormState?.mode === 'add' && _npFormState.detectedColKey) || null;
  host.innerHTML = `
    <div class="np-detected-header">
      <span class="np-detected-title">Detected in your data</span>
      <span class="np-detected-count">(${cols.length} available)</span>
      ${refreshBtn}
    </div>
    <div class="np-detected-list">
      ${cols.map(c => {
        const safeKey  = _escHTML(c.key);
        const safeName = _escHTML(c.name);
        const isActive = pendingAddKey === c.key;
        const inlineForm = isActive
          ? `<div class="np-form-inline-slot np-form-inline-slot--detected" data-for-col-key="${safeKey}">${_buildPropertyFormHTML({
              name: c.name,
              key: suggestCustomPropKey(c.name),
              type: c.type,
              showInFilters: true,
            }, false)}</div>`
          : '';
        return `
          <div class="np-detected-item${isActive ? ' is-adding' : ''}">
            <span class="np-detected-name" title="${safeKey}">${safeName}</span>
            <span class="np-detected-type-badge ${_npTypeClass(c.type)}">${_escHTML(c.type)}</span>
            <button class="np-detected-add${isActive ? ' active' : ''}" data-action="notion-prop-add-from-detected" data-col-key="${safeKey}" aria-expanded="${isActive}">${isActive ? '× Cancel' : '+ Add'}</button>
            <button class="np-detected-ignore" data-action="notion-prop-ignore-detected" data-col-key="${safeKey}" title="Hide until reload">✕</button>
          </div>
          ${inlineForm}`;
      }).join('')}
    </div>`;
}

// Wrapper that keeps both surfaces in sync. Replaces the old standalone
// _renderCustomPropsList() callsites.
function _renderNotionPropsPanel() {
  _renderCustomPropsList();
  _renderDetectedColumns();
  // Sidebar chip section must stay in sync with the declared-props list —
  // add/edit/delete/reorder/toggle-visibility all flow through this wrapper.
  renderCustomFilterChips();
}

function _handleAddFromDetected(colKey) {
  // Toggle: a second click on the same detected item's "+ Add" closes the form.
  if (_npFormState?.mode === 'add' && _npFormState.detectedColKey === colKey) {
    _closePropertyForm();
    return;
  }
  const cols = _scanDatasetColumns();
  const col = cols.find(c => c.key === colKey);
  if (!col) return;
  _openAddPropertyForm({
    name: col.name,
    key: suggestCustomPropKey(col.name),
    type: col.type,
    showInFilters: true,
  }, colKey);
}

function _handleIgnoreDetected(colKey) {
  _detectedColDismissed.add(colKey);
  _renderDetectedColumns();
}

// Clears the in-session dismissed list and re-renders everything — used when
// a user wants to recover from an accidental delete/ignore and see every
// discoverable property again.
function _handleRefreshCustomProps() {
  _detectedColDismissed.clear();
  _renderNotionPropsPanel();
}

// ══════════════════════════════════════════════════════════════
// CUSTOM FILTER CHIPS (sidebar)  —  sub-task 3
// Surfaces user-declared Notion properties (select / multi-select
// / checkbox with showInFilters=true) as chips in the sidebar,
// alongside the native filter groups. Chips are visual-only here;
// the filter pipeline is branched in sub-task 4.
// ══════════════════════════════════════════════════════════════

/** Render the "Custom fields" section in the sidebar. Strict order:
 *    1. Init appState.filters.customChips[key] for every qualifying prop
 *    2. Inject DOM (header + filter-groups)
 *    3. Populate each group via buildChips (or empty / too-many fallback)
 *  — so _resolveChipEntry never sees a key whose state slot is missing. */
// ══════════════════════════════════════════════════════
// Sidebar filter-group display order (drag-to-reorder)
// ══════════════════════════════════════════════════════
// User can drag-reorder the filter-groups in the sidebar when Layout Edit
// mode is active. Two independent zones: natives (in #filters-panel-dims)
// and customs (in #filters-custom-section). Each zone has its own ordered
// list of keys. Canonical SB_DIMS is NEVER mutated — preset snapshots,
// compare, export all continue to read it in its declared order.
const FILTERS_DISPLAY_ORDER_KEY = 'filters_display_order_v1';

const _CANONICAL_NATIVE_KEYS = ['outcome','setup','session','day','pair','direction','obstacles','h4obs','tradeType','beManagement','badFeeling'];

function _loadFilterDisplayOrder() {
  try {
    const raw = localStorage.getItem(FILTERS_DISPLAY_ORDER_KEY);
    if (!raw) return { natives: [], customs: [] };
    const p = JSON.parse(raw);
    return {
      natives: Array.isArray(p?.natives) ? p.natives : [],
      customs: Array.isArray(p?.customs) ? p.customs : [],
    };
  } catch (e) { return { natives: [], customs: [] }; }
}

/** Resolve the effective native-dim display order: saved keys first (drop
 *  unknown), then any canonical keys not yet in the saved list appended at
 *  the tail. Always returns a valid permutation of _CANONICAL_NATIVE_KEYS. */
function getSidebarDisplayOrderNatives() {
  const saved = _loadFilterDisplayOrder().natives;
  const known = new Set(_CANONICAL_NATIVE_KEYS);
  const seen = new Set();
  const out = [];
  for (const k of saved) {
    if (known.has(k) && !seen.has(k)) { out.push(k); seen.add(k); }
  }
  for (const k of _CANONICAL_NATIVE_KEYS) {
    if (!seen.has(k)) { out.push(k); seen.add(k); }
  }
  return out;
}

/** Same for customs. Takes the list of currently-declared keys so that a
 *  deleted prop drops silently and a newly-declared one appends at the end. */
function getSidebarDisplayOrderCustoms(declaredKeys) {
  const saved = _loadFilterDisplayOrder().customs;
  const known = new Set(declaredKeys || []);
  const seen = new Set();
  const out = [];
  for (const k of saved) {
    if (known.has(k) && !seen.has(k)) { out.push(k); seen.add(k); }
  }
  for (const k of (declaredKeys || [])) {
    if (!seen.has(k)) { out.push(k); seen.add(k); }
  }
  return out;
}

/** Re-append the 9 static native .filter-group nodes inside
 *  #filters-panel-dims in the user-chosen order. Moves existing nodes
 *  (no clone) so event listeners + in-flight state are preserved. */
function _applyNativeFilterOrder() {
  const host = document.getElementById('filters-panel-dims');
  if (!host) return;
  const order = getSidebarDisplayOrderNatives();
  const byKey = new Map();
  host.querySelectorAll(':scope > .filter-group[data-dim-key]').forEach(el => {
    byKey.set(el.dataset.dimKey, el);
  });
  // Append in order. Nodes already present get moved to the new position.
  order.forEach(k => {
    const el = byKey.get(k);
    if (el) host.appendChild(el);
  });
  // The #filters-custom-section wrapper lives inside #filters-panel-dims
  // too — keep it pinned to the end so customs always render after natives.
  const customWrap = document.getElementById('filters-custom-section');
  if (customWrap && customWrap.parentElement === host) host.appendChild(customWrap);
}

let _filtersNativeSortable = null;
let _filtersCustomSortable = null;

function _persistFilterOrderFromDOM() {
  const natHost = document.getElementById('filters-panel-dims');
  const custHost = document.getElementById('filters-custom-section');
  const natives = natHost
    ? Array.from(natHost.querySelectorAll(':scope > .filter-group[data-dim-key]'))
        .map(el => el.dataset.dimKey)
        .filter(Boolean)
    : [];
  const customs = custHost
    ? Array.from(custHost.querySelectorAll(':scope > .filter-group[data-custom-key]'))
        .map(el => el.dataset.customKey)
        .filter(Boolean)
    : [];
  try {
    localStorage.setItem(FILTERS_DISPLAY_ORDER_KEY, JSON.stringify({ natives, customs }));
  } catch (e) {}
  // Reflect the new order in any open tune panel.
  if (typeof openTunePanel === 'number') {
    try { buildTunePanel(openTunePanel); } catch (e) {}
  }
}

function _initFilterSortables() {
  if (typeof Sortable === 'undefined') return;   // CDN blocked → graceful no-op
  if (window.innerWidth < 768) return;           // mobile sidebar is collapsed
  const natEl = document.getElementById('filters-panel-dims');
  const custEl = document.getElementById('filters-custom-section');
  if (natEl && !_filtersNativeSortable) {
    _filtersNativeSortable = Sortable.create(natEl, {
      handle: '.fg-head',
      animation: 150,
      disabled: !_editMode,
      draggable: '.filter-group[data-dim-key]',
      ghostClass: 'sortable-ghost',
      chosenClass: 'sortable-chosen',
      onEnd: _persistFilterOrderFromDOM,
    });
  }
  if (custEl && !_filtersCustomSortable) {
    _filtersCustomSortable = Sortable.create(custEl, {
      handle: '.fg-head',
      animation: 150,
      disabled: !_editMode,
      draggable: '.filter-group[data-custom-key]',
      ghostClass: 'sortable-ghost',
      chosenClass: 'sortable-chosen',
      onEnd: _persistFilterOrderFromDOM,
    });
  }
}

function _syncFilterSortablesEnabled() {
  if (_filtersNativeSortable) _filtersNativeSortable.option('disabled', !_editMode);
  if (_filtersCustomSortable) _filtersCustomSortable.option('disabled', !_editMode);
  if (_presetSortable)        _presetSortable.option('disabled', !_editMode);
}

let _presetSortable = null;

// Persist DOM order → PRESETS[i].order, sort, save, re-render.
function _persistPresetOrderFromDOM() {
  const listEl = document.getElementById('preset-list');
  if (!listEl) return;
  const rows = listEl.querySelectorAll('.preset-row[data-preset-id]');
  rows.forEach((row, idx) => {
    const pid = parseInt(row.dataset.presetId, 10);
    const preset = PRESETS.find(p => p.id === pid);
    if (preset) preset.order = idx;
  });
  PRESETS.sort((a, b) => a.order - b.order);
  savePresetsList();
  renderPresetList();
  if (typeof renderMobilePresetControls === 'function') renderMobilePresetControls();
  refreshPresetCompareDropdowns();
}

function _initPresetSortable() {
  if (typeof Sortable === 'undefined') return;
  if (window.innerWidth < 768) return;
  const listEl = document.getElementById('preset-list');
  if (!listEl || _presetSortable) return;
  _presetSortable = Sortable.create(listEl, {
    handle: '.preset-btn-wrap',
    animation: 150,
    disabled: !_editMode,
    draggable: '.preset-row[data-preset-id]',
    filter: '.preset-row-add',
    ghostClass: 'sortable-ghost',
    chosenClass: 'sortable-chosen',
    onEnd: _persistPresetOrderFromDOM,
  });
}

function renderCustomFilterChips() {
  const host = document.getElementById('filters-custom-section');
  if (!host) return;
  const all = loadCustomProps().filter(p =>
    p.showInFilters && ['select', 'multi-select', 'checkbox'].includes(p.type)
  );
  // Reorder per user-chosen display order (drag-to-reorder). Unknown keys
  // fall back to their declared order at the tail; removed keys drop silently.
  const order = getSidebarDisplayOrderCustoms(all.map(p => p.key));
  const byKey = Object.fromEntries(all.map(p => [p.key, p]));
  const props = order.map(k => byKey[k]).filter(Boolean);
  if (!props.length) {
    host.classList.remove('has-content');
    host.innerHTML = '';
    return;
  }

  // 1. STATE INIT — must precede any DOM rendering / buildChips call.
  for (const p of props) {
    if (!appState.filters.customChips[p.key]) {
      appState.filters.customChips[p.key] = {
        mode: 'neutral',
        included: new Set(),
        excluded: new Set(),
        includedFromPreset: new Set(),
        excludedFromPreset: new Set(),
        matchMode: 'any',
      };
    }
  }

  // 2. DOM INJECTION
  host.classList.add('has-content');
  host.innerHTML = `
    <div class="filters-custom-header">Custom fields</div>
    ${props.map(_npSidebarGroupHTML).join('')}
  `;

  // 3. CHIPS POPULATION via buildChips (reuses native DOM & classes).
  for (const p of props) {
    const scan = _scanUniqueValuesFor(p);
    const containerId = 'chips-custom-' + p.key;
    const container = document.getElementById(containerId);
    if (!container) continue;
    if (scan.overLimit) {
      container.outerHTML = `<div class="filter-group-toomany">${scan.total} values — too many to display as chips, refine your data.</div>`;
      continue;
    }
    if (!scan.values.length) {
      container.outerHTML = `<div class="filter-group-empty">No values found in current dataset.</div>`;
      continue;
    }
    const labelFn = (p.type === 'checkbox')
      ? v => (v === 'true' ? 'True' : v === 'false' ? 'False' : v)
      : null;
    buildChips(containerId, scan.values, 'custom:' + p.key, labelFn);
  }
}

function _npSidebarGroupHTML(p) {
  const safeKey  = _escHTML(p.key);
  const safeName = _escHTML(p.name);
  const mm = appState.filters.customChips?.[p.key]?.matchMode || 'any';
  const matchModeBtn = (p.type === 'multi-select')
    ? `<button class="fg-matchmode-btn" data-action="toggle-custom-matchmode" data-key="${safeKey}" data-mode="${mm}" title="any: at least one value matches. all: every selected value must match.">${mm}</button>`
    : '';
  return `
    <div class="filter-group" data-custom-key="${safeKey}">
      <div class="fg-head">
        <span class="fg-label fg-label--no-dot">${safeName}${matchModeBtn}</span>
        <span class="fg-count" id="cnt-custom-${safeKey}">0</span>
      </div>
      <div class="chip-mode-row">
        <button class="chip-mode-btn active" data-action="set-chip-mode" data-key="custom:${safeKey}" data-mode="neutral">Neutral</button>
        <button class="chip-mode-btn"        data-action="set-chip-mode" data-key="custom:${safeKey}" data-mode="exclude">Exclude</button>
        <button class="chip-mode-btn"        data-action="set-chip-mode" data-key="custom:${safeKey}" data-mode="include">Include</button>
      </div>
      <div class="chips" id="chips-custom-${safeKey}"></div>
    </div>`;
}

/** Walk the current dataset and collect unique values for a declared prop.
 *  Returns {values, total, overLimit}. Scalar fields (select/checkbox) read
 *  t.extras[key] directly; multi-select flattens arrays. Caps at 100 uniques
 *  to protect sidebar perf on messy datasets. */
function _scanUniqueValuesFor(prop) {
  const items = appState.trades.items || [];
  const set = new Set();
  const addValue = v => {
    if (v === null || v === undefined || v === '') return;
    if (prop.type === 'multi-select') {
      if (Array.isArray(v)) v.forEach(x => { if (x !== null && x !== undefined && x !== '') set.add(String(x)); });
    } else if (prop.type === 'checkbox') {
      set.add(String(Boolean(v)));
    } else {
      set.add(String(v));
    }
  };
  // Refacto Total 2026-05-24 — step 3: read extras under the prop's immutable
  // notionSourceName. Single deterministic key — the eager bake writes here
  // for every detected Notion prop on every sync.
  for (const t of items) {
    addValue(t?.extras?.[prop?.notionSourceName]);
  }

  const total = set.size;
  if (total > 100) return { values: [], total, overLimit: true };
  // checkbox: stable [false, true] order; numeric values: ascending
  // numeric order ("2" before "10"); everything else alphabetical.
  let values;
  if (prop.type === 'checkbox') {
    const preferred = ['false', 'true'];
    values = preferred.filter(v => set.has(v)).concat([...set].filter(v => !preferred.includes(v)));
  } else {
    const arr = [...set];
    const allNumeric = arr.length > 0 && arr.every(v => v !== '' && Number.isFinite(Number(v)));
    values = allNumeric
      ? arr.sort((a, b) => Number(a) - Number(b))
      : arr.sort((a, b) => a.localeCompare(b));
  }
  return { values, total, overLimit: false };
}

/** Flip matchMode for a multi-select custom prop. The filter pipeline
 *  (filterCustomChips) consumes entry.matchMode, so the cache MUST be
 *  invalidated and the dashboard re-rendered. */
function _handleToggleCustomMatchMode(rawKey) {
  const entry = appState.filters.customChips?.[rawKey];
  if (!entry) return;
  entry.matchMode = (entry.matchMode === 'all') ? 'any' : 'all';
  const btn = document.querySelector(`.fg-matchmode-btn[data-key="${rawKey}"]`);
  if (btn) {
    btn.dataset.mode = entry.matchMode;
    btn.textContent = entry.matchMode;
  }
  // matchMode change on a live entry is a live-slot mutation — persist it so
  // the preset's slot reflects the new any/all semantic after reload.
  if (typeof _syncLiveSlotFromActiveChips === 'function') _syncLiveSlotFromActiveChips();
  if (typeof invalidateFilterCache === 'function') invalidateFilterCache();
  if (typeof render === 'function') render();
}

// ── Save / Reset / Export / Import ──
function saveTheme() {
  if (_activeUserThemeId !== null && _activeUserThemeId !== undefined) {
    overwriteCurrentUserTheme();
    try { localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme)); } catch(e) {}
    return;
  }
  if (_activeBuiltinThemeIndex !== null && _activeBuiltinThemeIndex !== undefined) {
    // Persist ONLY the differences from the pristine preset. Storing the full
    // currentTheme has historically caused contamination: if currentTheme was
    // ever out-of-sync with _activeBuiltinThemeIndex (e.g. boot loaded one
    // theme from THEME_STORAGE_KEY while meta said a different preset was
    // active), the snapshot would write a foreign preset's colors into THIS
    // slot — and the next click on this preset would visibly snap to that
    // foreign preset. Diff-only saves prevent that.
    const _activePreset = THEME_PRESETS[_activeBuiltinThemeIndex];
    const _diff = {};
    Object.entries(currentTheme).forEach(([k, v]) => {
      const baseline = (_activePreset?.theme?.[k] !== undefined) ? _activePreset.theme[k] : THEME_DEFAULT[k];
      if (v !== baseline) _diff[k] = v;
    });
    _saveBuiltinOverride(_activeBuiltinThemeIndex, _diff);
    try { localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme)); } catch(e) {}
    // Rebuild rows so reset-button baselines reflect the newly-saved state.
    buildColorSection('tp-bg-colors',        Object.entries(THEME_META).filter(([,m])=>m.group==='backgrounds'));
    buildColorSection('tp-border-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='borders'));
    buildColorSection('tp-text-colors',      Object.entries(THEME_META).filter(([,m])=>m.group==='text'));
    buildColorSection('tp-accent-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='accent'));
    buildColorSection('tp-state-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='states'));
    buildColorSection('tp-chart-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='chart'));
    buildColorSection('tp-component-colors', Object.entries(THEME_META).filter(([,m])=>m.group==='component'));
    const preset = THEME_PRESETS[_activeBuiltinThemeIndex];
    showThemeToast(`"${preset?.name || 'Theme'}" saved ✓`);
    return;
  }
  try {
    localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme));
    showThemeToast('Theme saved ✓');
  } catch(e) { showThemeToast('Save failed (storage unavailable)', true); }
}

function resetTheme() {
  // Active user theme → revert any unsaved edits back to the stored slot values.
  if (_activeUserThemeId !== null && _activeUserThemeId !== undefined) {
    const t = USER_THEMES.find(x => x.id === _activeUserThemeId);
    if (t) {
      currentTheme = { ...THEME_DEFAULT, ...t.theme };
      applyThemeToCss(currentTheme);
      buildColorSection('tp-bg-colors',        Object.entries(THEME_META).filter(([,m])=>m.group==='backgrounds'));
      buildColorSection('tp-border-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='borders'));
      buildColorSection('tp-text-colors',      Object.entries(THEME_META).filter(([,m])=>m.group==='text'));
      buildColorSection('tp-accent-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='accent'));
      buildColorSection('tp-state-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='states'));
      buildColorSection('tp-chart-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='chart'));
      buildColorSection('tp-component-colors', Object.entries(THEME_META).filter(([,m])=>m.group==='component'));
      buildTypographyControls();
      try { localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme)); } catch(e) {}
      showThemeToast(`"${t.name}" reverted ✓`);
      return;
    }
  }
  // Active built-in preset → drop any saved customization, re-apply its pristine definition.
  if (_activeBuiltinThemeIndex !== null && _activeBuiltinThemeIndex !== undefined) {
    const preset = THEME_PRESETS[_activeBuiltinThemeIndex];
    if (preset) {
      _clearBuiltinOverride(_activeBuiltinThemeIndex);
      applyPresetTheme(_activeBuiltinThemeIndex);
      try { localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme)); } catch(e) {}
      showThemeToast(`"${preset.name}" reset to default ✓`);
      return;
    }
  }
  // Fallback — no active tracking, go to engine default.
  currentTheme = { ...THEME_DEFAULT };
  _activeUserThemeId = null;
  _activeBuiltinThemeIndex = null;
  _persistActiveThemeMeta();
  applyThemeToCss(currentTheme);
  buildColorSection('tp-bg-colors',        Object.entries(THEME_META).filter(([,m])=>m.group==='backgrounds'));
  buildColorSection('tp-border-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='borders'));
  buildColorSection('tp-text-colors',      Object.entries(THEME_META).filter(([,m])=>m.group==='text'));
  buildColorSection('tp-accent-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='accent'));
  buildColorSection('tp-state-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='states'));
  buildColorSection('tp-chart-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='chart'));
  buildColorSection('tp-component-colors', Object.entries(THEME_META).filter(([,m])=>m.group==='component'));
  buildTypographyControls();
  try { localStorage.removeItem(THEME_STORAGE_KEY); } catch(e) {}
  showThemeToast('Reset to default ✓');
}

function _detectActiveBuiltinPreset() {
  // Prefer persisted active-theme meta (survives modifications — lets reset
  // on a customized built-in return to THAT preset's pristine values).
  try {
    const raw = localStorage.getItem(ACTIVE_THEME_META_KEY);
    if (raw) {
      const meta = JSON.parse(raw);
      if (typeof meta?.userId === 'number' && USER_THEMES.some(t => t.id === meta.userId)) {
        _activeUserThemeId = meta.userId;
        _activeBuiltinThemeIndex = null;
        return;
      }
      if (typeof meta?.builtinIndex === 'number' && meta.builtinIndex >= 0 && meta.builtinIndex < THEME_PRESETS.length) {
        _activeBuiltinThemeIndex = meta.builtinIndex;
        _activeUserThemeId = null;
        return;
      }
    }
  } catch(e) {}
  // Fallback: exact-match detection against pristine presets.
  for (let i = 0; i < THEME_PRESETS.length; i++) {
    const p = THEME_PRESETS[i];
    const match = Object.entries(p.theme).every(([k,v]) => currentTheme[k] === v);
    if (match) { _activeBuiltinThemeIndex = i; return; }
  }
  _activeBuiltinThemeIndex = null;
}

function exportTheme() {
  let name = 'Custom';
  let basedOn = null;
  if (_activeUserThemeId !== null && _activeUserThemeId !== undefined) {
    const t = USER_THEMES.find(x => x.id === _activeUserThemeId);
    if (t) name = t.name;
  } else if (_activeBuiltinThemeIndex !== null && _activeBuiltinThemeIndex !== undefined) {
    const p = THEME_PRESETS[_activeBuiltinThemeIndex];
    if (p) { name = p.name; basedOn = p.name; }
  }
  const payload = {
    name,
    theme: { ...currentTheme },
    basedOn,
    exportedAt: new Date().toISOString(),
    version: 2,
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], {type:'application/json'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  const safeName = String(name).replace(/[^a-z0-9]+/gi,'-').toLowerCase() || 'theme';
  a.download = `${safeName}.theme.json`;
  a.click();
  URL.revokeObjectURL(a.href);
}

function _isSafeCssValue(val) {
  if (typeof val !== 'string') return false;
  if (val.length > 200) return false;
  // Resolve CSS unicode escapes (\HH or \HHHHHH, optionally followed by whitespace)
  // before blacklist match, so that e.g. "\75 rl(..." cannot bypass the "url(" check.
  // Per CSS spec, escapes are 1-6 hex chars, optionally followed by a single whitespace.
  let normalized;
  try {
    normalized = val.replace(/\\([0-9a-fA-F]{1,6})\s?/g, (_, hex) => {
      const cp = parseInt(hex, 16);
      // Guard against invalid codepoints (surrogates, out-of-range)
      if (!Number.isFinite(cp) || cp < 0 || cp > 0x10FFFF) return '';
      try { return String.fromCodePoint(cp); } catch { return ''; }
    });
  } catch {
    return false; // any unexpected error → fail closed
  }
  return !/url\s*\(|expression\s*\(|javascript\s*:|data\s*:/i.test(normalized);
}

function importTheme(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const data = JSON.parse(e.target.result);
      const theme = data.theme || data;
      // Validate: must have at least --bg and --gold
      if (!theme['--bg'] || !theme['--gold']) throw new Error('Missing required keys');
      const sanitized = {};
      for (const [k, v] of Object.entries(theme)) {
        if (_isSafeCssValue(v)) sanitized[k] = v;
        else console.warn('[importTheme] rejected unsafe CSS value for', k);
      }
      currentTheme = { ...THEME_DEFAULT, ...sanitized };
      applyThemeToCss(currentTheme);
      buildColorSection('tp-bg-colors',        Object.entries(THEME_META).filter(([,m])=>m.group==='backgrounds'));
      buildColorSection('tp-border-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='borders'));
      buildColorSection('tp-text-colors',      Object.entries(THEME_META).filter(([,m])=>m.group==='text'));
      buildColorSection('tp-accent-colors',    Object.entries(THEME_META).filter(([,m])=>m.group==='accent'));
      buildColorSection('tp-state-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='states'));
      buildColorSection('tp-chart-colors',     Object.entries(THEME_META).filter(([,m])=>m.group==='chart'));
      buildColorSection('tp-component-colors', Object.entries(THEME_META).filter(([,m])=>m.group==='component'));
      buildTypographyControls();
      showThemeToast('Theme imported ✓');
      if (USER_THEMES.length < USER_THEMES_MAX) {
        if (confirm(`Save "${data.name || 'Imported'}" as a new custom theme?`)) {
          const id = _nextUserThemeId();
          USER_THEMES.push({
            id,
            name: String(data.name || 'Imported').slice(0, 40),
            theme: { ...theme },
            createdAt: new Date().toISOString(),
          });
          USER_THEMES.sort((a, b) => a.id - b.id);
          saveUserThemes();
          buildUserThemes();
        }
      }
    } catch(err) {
      showThemeToast('Invalid theme file', true);
    }
  };
  reader.readAsText(file);
  input.value = '';
}

function loadSavedTheme() {
  // Fresh-user default theme. Dawn is the warm-cream light theme — chosen
  // as the brand-new-user landing experience. Existing users keep whatever
  // they have in LS untouched. To change the default, edit the .name lookup.
  const DEFAULT_PRESET = THEME_PRESETS.find(p => p.name === 'Dawn')
    || THEME_PRESETS.find(p => p.name === 'TradingView'); // belt-and-suspenders fallback
  const DEFAULT_THEME = DEFAULT_PRESET.theme;
  try {
    const saved = localStorage.getItem(THEME_STORAGE_KEY);
    if (!saved) {
      currentTheme = { ...THEME_DEFAULT, ...DEFAULT_THEME };
      try { localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme)); } catch(e) {}
      applyThemeToCss(currentTheme);
      return false;
    }
    const theme = JSON.parse(saved);
    currentTheme = { ...THEME_DEFAULT, ...theme };
    // Persist the merged version only if it differs — avoids a redundant
    // ~4.5KB write on every boot when no new theme vars were introduced.
    try {
      const serialized = JSON.stringify(currentTheme);
      if (serialized !== saved) localStorage.setItem(THEME_STORAGE_KEY, serialized);
    } catch(e) {}
    applyThemeToCss(currentTheme);
    return true;
  } catch(e) {
    currentTheme = { ...THEME_DEFAULT, ...DEFAULT_THEME };
    try { localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify(currentTheme)); } catch(e) {}
    applyThemeToCss(currentTheme);
    return false;
  }
}

// Toast notification
let _toastTimer = null;
function showThemeToast(msg, isErr=false) {
  let toast = document.getElementById('theme-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'theme-toast';
    document.body.appendChild(toast);
  }
  toast.textContent = msg;
  toast.style.background = isErr ? 'color-mix(in srgb,var(--r) 90%,#000)' : 'color-mix(in srgb,var(--gold) 90%,#000)';
  toast.style.color = '#fff';
  toast.style.border = isErr ? '1px solid color-mix(in srgb,var(--r) 60%,transparent)' : '1px solid color-mix(in srgb,var(--gold) 60%,transparent)';
  toast.style.opacity = '1';
  clearTimeout(_toastTimer);
  _toastTimer = setTimeout(() => { toast.style.opacity = '0'; }, 2200);
}

// ── Profile-scope migration (v3) ──
// Pre-v3: layout / presets / hidden widgets / filter snapshots were stored
// under global localStorage keys (e.g. `flipping_presets`, `gs_layout_default`).
// All data sources (Demo + each Notion profile) shared the same slot, so
// switching profiles never gave the user independent layouts/presets.
//
// v3: _htfKey() now wraps getProfileScopedKey(), producing per-profile keys
// like `flipping_presets_<profileId>` or `gs_layout_default_<profileId>_h4`.
// The legacy keys are unreachable through normal app flow but still take
// localStorage space; this one-shot pass wipes them so they don't:
//   - confuse manual debugging (orphaned keys)
//   - eat quota for users near 5MB ceiling
// Reset behaviour is intentional — agreed with user (see ROADMAP / DECISIONS).
function _runProfileScopeMigrationV3() {
  const FLAG = 'flipping_profile_scope_migration_v3';
  try {
    if (localStorage.getItem(FLAG)) return;
  } catch (e) { return; }
  // Prefixes that uniquely identify the pre-v3 (global) keys. Post-v3 keys
  // also start with these prefixes BUT only run after this migration sets
  // the flag, so the wipe runs exactly once before any scoped key exists.
  const prefixes = [
    'gs_layout_',
    'gs_active_preset',
    'gs_hidden_widgets',
    'gs_custom_slots',
    'flipping_presets',
    'flipping_preset_snapshots_v2',
    'presetLiveFilters_v1',
    'flipping_preset_overrides',
  ];
  const toDelete = [];
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (!key) continue;
      if (prefixes.some(p => key === p || key.startsWith(p))) {
        toDelete.push(key);
      }
    }
    toDelete.forEach(k => { try { localStorage.removeItem(k); } catch (e) {} });
    localStorage.setItem(FLAG, '1');
    console.log('[profile-scope-migration-v3] wiped', toDelete.length, 'legacy keys');
  } catch (e) {
    console.warn('[profile-scope-migration-v3] failed:', e?.message);
  }
}

// Custom widgets were stored under the global `flipping_custom_widgets` key
// before this revision. Per-profile scoping needs to copy that legacy payload
// into the currently-active profile's slot exactly once, so existing users
// don't lose their widgets on first post-update boot.
function _runCustomWidgetsProfileScopeMigration() {
  const FLAG = 'flipping_custom_widgets_profile_migration_v1';
  try {
    if (localStorage.getItem(FLAG)) return;
    const legacyRaw = localStorage.getItem(CUSTOM_WIDGETS_LS_KEY);
    const scopedKey = getProfileScopedKey(CUSTOM_WIDGETS_LS_KEY);
    // If the scoped slot is already populated (e.g. somehow set ahead of time)
    // or the legacy payload is missing, skip the copy but still set the flag
    // so we don't re-check on every boot.
    if (legacyRaw && scopedKey !== CUSTOM_WIDGETS_LS_KEY && !localStorage.getItem(scopedKey)) {
      localStorage.setItem(scopedKey, legacyRaw);
      console.log('[custom-widgets-profile-migration-v1] copied', legacyRaw.length, 'bytes to', scopedKey);
    }
    // Drop the legacy global so it doesn't drift from the now-scoped truth.
    try { localStorage.removeItem(CUSTOM_WIDGETS_LS_KEY); } catch (e) {}
    localStorage.setItem(FLAG, '1');
  } catch (e) {
    console.warn('[custom-widgets-profile-migration-v1] failed:', e?.message);
  }
}

// Pre-scope cleanup for `flipping_notion_properties`: the legacy key was
// global, leaking the same "Added filters" list across every Notion profile.
// Per-profile semantics introduced this revision intentionally reset every
// profile to an empty list (no copy/migration of the legacy payload — the
// user expectation is a fresh, profile-scoped slate). One-shot guard avoids
// re-wiping freshly-written scoped slots on subsequent boots.
function _runCustomPropsProfileScopeMigration() {
  const FLAG = 'flipping_notion_properties_profile_migration_v1';
  try {
    if (localStorage.getItem(FLAG)) return;
    try { localStorage.removeItem(CUSTOM_PROPS_LS_KEY); } catch (e) {}
    localStorage.setItem(FLAG, '1');
  } catch (e) {
    console.warn('[custom-props-profile-migration-v1] failed:', e?.message);
  }
}

// One-shot migration to recover Notion profiles whose parsed-trades cache was
// written before the screenshot pipeline fix (2026-05-22): _rawUrl couldn't
// extract URLs from Notion Files & Media properties (returned '[object
// Object]'), so cached parsed trades have empty imgM15 / imgH4Before /
// imgM15After fields. The cache-hit boot path injects those stale trades
// as-is without re-normalising, leaving screenshots silently broken until a
// manual Sync. Purging the parsed cache here forces the boot path to either
// re-normalise from the in-memory raw cache (if present) or fall through to
// a fresh Notion sync — both paths use the new _rawUrl + the F&M-preferred
// auto-detect. Guard via a one-shot LS flag so the migration runs exactly
// once per machine. No data loss — raw caches are untouched.
function _runScreenshotPipelineV2Migration() {
  const FLAG = 'flipping_screenshot_pipeline_v2_migration';
  try {
    if (localStorage.getItem(FLAG)) return;
    const profiles = (typeof getJournalProfiles === 'function') ? getJournalProfiles() : [];
    let purged = 0;
    for (const p of profiles) {
      if (p?.connectionType !== 'notion' || !p?.notionDatabaseId) continue;
      if (typeof _invalidateNormalizedTradesCache === 'function') {
        _invalidateNormalizedTradesCache(p.id, 'screenshot-pipeline-v2-migration');
        purged++;
      }
    }
    localStorage.setItem(FLAG, '1');
    if (purged) console.log('[screenshot-pipeline-v2] purged', purged, 'parsed cache(s) — boot will re-derive');
  } catch (e) {
    console.warn('[screenshot-pipeline-v2-migration] failed:', e?.message);
  }
}

window.addEventListener('load', () => {
  // One-shot migration MUST run before any preset / layout load so the new
  // per-profile scoping reads from clean slots.
  _runProfileScopeMigrationV3();
  // Copy legacy global custom widget defs into the active profile's slot
  // before any _loadCustomWidgetDefs() reader fires.
  _runCustomWidgetsProfileScopeMigration();
  // One-shot purge of the legacy global custom-props slot so every profile
  // starts from a fresh per-profile slate.
  _runCustomPropsProfileScopeMigration();
  // One-shot purge of stale parsed-trades caches written before the screenshot
  // pipeline fix (2026-05-22). Forces the next boot for each Notion profile
  // to either re-normalise from raw or fetch fresh data with the new code.
  _runScreenshotPipelineV2Migration();

  // Load custom presets BEFORE static chrome rendering so the preset list
  // reflects user-created presets (and respects deletes/renames).
  loadPresetsList();
  loadUserThemes();
  renderStaticDashboardChrome();

  // Load saved theme before first render
  loadSavedTheme();
  _detectActiveBuiltinPreset();
  // Build theme panel UI
  buildThemePanel();
  updateSaveButtonLabel();

  // Init temporal filter (populates selects from actual data)
  tfInit();

  initPresetOverrides();
  loadPresetOverrides();  // restore saved tune panel overrides
  // v2 presets: init snapshots + load from LS, then run one-shot migration if
  // the schema is still v1. Migration reads PRESETS + presetOverrides (both
  // already loaded above) and materializes per-preset snapshots.
  initPresetSnapshots();
  loadPresetSnapshots();
  _migrateToV2();
  // 2026-05-24: re-rinse P0's snapshot for existing v2 users — _migrateToV2
  // baked BASE_M15_EXCLUDE into P0 before noBaseExclusions:true became the
  // default. One-shot, idempotent.
  _migrateRawBaselineToTrulyRaw_v1();
  // 2026-05-24: legacy donut custom widgets dropped in favor of sortable tables.
  // One-shot, idempotent — purges any def with type='donut' from LS.
  _migrateDropLegacyDonuts_v1();
  // Per-preset live filters (Phase 3 refonte). Load AFTER migration so the
  // presets list is stable; _ensureLiveSlotsInitialized backfills any missing
  // slots (including the 'null' pseudo-preset for no-preset-active context).
  loadPresetLiveFilters();
  _ensureLiveSlotsInitialized();
  // Hydrate appState.ui.tpConfig from the active preset's live slot now that
  // both snapshots and live filters are loaded. Per-preset TPM architecture:
  // before this point, appState.ui.tpConfig holds the fixed default seeded at
  // module load; from here on, it mirrors the active preset's live tpConfig.
  {
    const _bootSlot = getPresetLiveSlot(appState.presets?.activeId ?? null);
    if (_isValidTpConfigShape(_bootSlot.tpConfig)) {
      appState.ui.tpConfig = JSON.parse(JSON.stringify(_bootSlot.tpConfig));
    }
  }
  refreshPresetCompareDropdowns();  // sync compare tool to current PRESETS list
  initDataSource();
  // Restore the previously-active preset for this profile slot. Must run
  // after initDataSource because _injectTrades resets activeId to null on
  // first load (line 6884). Falls back to RAW Baseline (P0) when nothing
  // is persisted yet — fresh profiles (Demo / new Notion / post-v3 migration)
  // therefore land on a named preset right away.
  _restoreActivePresetForCurrentSlot();
  // Seed the Data Hub button tooltip from the initial badge state so the
  // icon-only variant (<=1280px) is immediately informative, before the
  // user ever opens the Data Hub panel.
  try { updateDataHubBadge(); } catch (e) {}
  // Show comparison UI if compare is active
  tfUpdateCompareUI();

  // Restore saved dashboard section tab (Global Overview / Optimal RR Analysis / Partial Planers)
  {
    const saved = localStorage.getItem('dashboard_section');
    if (saved && ['global','optimal-rr','partials'].includes(saved)) {
      setSection(saved);
    }
  }

  // Sync active-preset badge on boot: if the persisted tpConfig matches a
  // saved PP preset, show the header badge + highlight the chip. Runs after
  // renderStaticDashboardChrome so #tpm-active-preset-topbar-btn exists.
  try { _ppSyncActivePresetBadge(); } catch (e) {}

  window.addEventListener('resize', _debounce(() => {
    if (!_gsReady) return;
    const filtered = getFiltered();
    const stats = calcStats(filtered);
    if(stats) { drawCharts(filtered); drawMonthly(filtered); drawDonut(stats); }
    _fitAllStatsOverviewMicros();
  }, 120));
});

// ══ SB_DIMS: dimension configs for preset tune panels ══
const SB_DIMS = [
  { key:'outcome',      label:'TP Result',     items: ALL_OUTCOMES,    field: t => [t.outcome] },
  { key:'setup',        label:'Setup',         items: SETUPS,          field: t => [t.setup] },
  { key:'session',      label:'Session',       items: SESSIONS,        field: t => [t.session] },
  { key:'day',          label:'Day',           items: DAYS,            field: t => [t.day] },
  { key:'pair',         label:'Pair',          items: PAIRS,           field: t => [t.pair] },
  { key:'direction',    label:'Order',         items: ALL_DIRECTIONS,  field: t => [t.direction] },
  { key:'obstacles',    label:'M15 Obs',       items: ALL_OBS,         field: t => t.obstacles },
  { key:'h4obs',        label:'H4 Obs',        items: ALL_H4OBS,       field: t => t.h4 || [] },
  { key:'tradeType',    label:'Trade Type',    items: ALL_TRADE_TYPES, field: t => t.tradeType || [] },
  { key:'beManagement', label:'BE Management', items: ALL_BE_MGMT,     field: t => t.beManagement || [] },
  { key:'badFeeling',   label:'Bad Feeling',   items: ['Yes','No'],    field: t => [t.badFeeling ? 'Yes' : 'No'] },
];

// ══ PRESET OVERRIDES: per-preset Include + Exclude state (both can mix) ══
// presetOverrides[id][dim.key] = { mode: 'neutral'|'include'|'exclude', included: Set, excluded: Set }
// `mode` is the currently active bucket for chip clicks:
//   - 'neutral'  → dim has no filter (both Sets empty). Clicking a chip auto-switches to 'include'.
//   - 'include'  → chip clicks toggle the value in the `included` Set.
//   - 'exclude'  → chip clicks toggle the value in the `excluded` Set.
// The mode auto-reverts to 'neutral' whenever both Sets become empty.
// Clicking the NEUTRE mode button clears both Sets for the dim.
// Initialized lazily after SB_DIMS is defined (see initPresetOverrides() called at bottom)
const presetOverrides = {};


const LS_OVERRIDES_KEY='flipping_preset_overrides';
function savePresetOverrides() {
  try {
    const s = {};
    for (let id = 0; id < PRESET_MAX; id++) {
      if (!presetOverrides[id]) continue;
      s[id] = {};
      SB_DIMS.forEach(d => {
        const o = presetOverrides[id][d.key];
        s[id][d.key] = { mode: o.mode, included: [...o.included], excluded: [...o.excluded] };
      });
      // Per-preset customChips overrides (sub-task 5). Sets→Arrays via helper;
      // neutral entries dropped to keep the persisted blob compact.
      const cc = _serializeCustomChips(presetOverrides[id].customChips || {});
      if (Object.keys(cc).length) s[id].customChips = cc;
    }
    localStorage.setItem(_htfKey(LS_OVERRIDES_KEY), JSON.stringify(s));
  } catch(e) {}
}
function loadPresetOverrides() {
  try {
    const raw = localStorage.getItem(_htfKey(LS_OVERRIDES_KEY));
    if (!raw) return;
    const saved = JSON.parse(raw);
    const coerceMode = (m, included, excluded) => {
      if (included.size === 0 && excluded.size === 0) return 'neutral';
      if (m === 'include' || m === 'exclude') return m;
      return 'neutral';
    };
    Object.entries(saved).forEach(([id, dims]) => {
      const n = parseInt(id);
      if (!presetOverrides[n]) return;
      Object.entries(dims).forEach(([k, v]) => {
        // customChips slot is restored separately below — skip it in the
        // SB_DIMS loop so it doesn't get coerced as a chip dim.
        if (k === 'customChips') return;
        if (!presetOverrides[n][k]) return;
        let included, excluded, mode;
        // Legacy-compat: old format { mode: 'ignore'|'include'|'exclude', vals: [] }
        if ('vals' in v) {
          included = new Set();
          excluded = new Set();
          if (v.mode === 'include') (v.vals || []).forEach(x => included.add(x));
          else if (v.mode === 'exclude') (v.vals || []).forEach(x => excluded.add(x));
          mode = coerceMode(v.mode, included, excluded);
        } else {
          included = new Set(v.included || []);
          excluded = new Set(v.excluded || []);
          mode = coerceMode(v.mode, included, excluded);
        }
        presetOverrides[n][k] = { mode, included, excluded };
      });
      // Per-preset customChips overrides — orphan keys silently dropped via
      // _deserializeCustomChips' allowedKeys filter (sub-task 5).
      const allowedKeys = new Set(
        (typeof loadCustomProps === 'function' ? loadCustomProps() : []).map(p => p.key)
      );
      presetOverrides[n].customChips = _deserializeCustomChips(dims.customChips || {}, allowedKeys);
    });
  } catch(e) {}
}

function initPresetOverrides() {
  // Allocate an override slot for every possible preset id (0..PRESET_MAX-1),
  // not only the currently-loaded ones. This makes create/delete idempotent —
  // a freshly-created preset always finds a clean slot waiting for it.
  for (let id = 0; id < PRESET_MAX; id++) {
    presetOverrides[id] = {};
    SB_DIMS.forEach(d => {
      presetOverrides[id][d.key] = { mode: 'neutral', included: new Set(), excluded: new Set() };
    });
    // Surface H (sub-task 5): always allocate the customChips slot so callers
    // can read presetOverrides[id].customChips without null-guarding.
    presetOverrides[id].customChips = {};
  }
}

// ══ PRESET SNAPSHOTS (v2, refactor Filters ↔ Presets) ══
// Per-preset frozen snapshot of the filter state. When a preset is applied,
// these values are hydrated into appState.filters.chips with fromPreset:true.
// Shape: presetSnapshots[id] = {
//   chips:       { [dimKey]: { included: [], excluded: [] } },
//   customChips: { [propKey]: { mode, matchMode, included: [], excluded: [] } }
// }
const presetSnapshots = {};

function _blankSnapshotChips() {
  const chips = {};
  // Natives — same list of dim keys as appState.filters.chips.
  ['outcome','setup','session','day','pair','direction','obstacles','h4obs','tradeType','beManagement','hour','badFeeling'].forEach(k => {
    chips[k] = { included: [], excluded: [] };
  });
  return chips;
}

function _blankSnapshot() {
  return {
    chips: _blankSnapshotChips(),
    customChips: {},
    tpConfig: _defaultTpConfig(),
  };
}

function initPresetSnapshots() {
  for (let id = 0; id < PRESET_MAX; id++) presetSnapshots[id] = _blankSnapshot();
}

function loadPresetSnapshots() {
  try {
    const raw = localStorage.getItem(_htfKey(PRESET_SNAPSHOTS_LS_KEY));
    if (!raw) return;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return;
    for (const [idStr, snap] of Object.entries(parsed)) {
      const id = parseInt(idStr, 10);
      if (!Number.isFinite(id) || id < 0 || id >= PRESET_MAX) continue;
      const dst = _blankSnapshot();
      if (snap && snap.chips && typeof snap.chips === 'object') {
        for (const k of Object.keys(dst.chips)) {
          const src = snap.chips[k] || {};
          dst.chips[k].included = Array.isArray(src.included) ? src.included.slice() : [];
          dst.chips[k].excluded = Array.isArray(src.excluded) ? src.excluded.slice() : [];
        }
      }
      if (snap && snap.customChips && typeof snap.customChips === 'object') {
        for (const [k, v] of Object.entries(snap.customChips)) {
          if (!v || typeof v !== 'object') continue;
          dst.customChips[k] = {
            mode: (v.mode === 'include' || v.mode === 'exclude') ? v.mode : 'neutral',
            matchMode: v.matchMode === 'all' ? 'all' : 'any',
            included: Array.isArray(v.included) ? v.included.slice() : [],
            excluded: Array.isArray(v.excluded) ? v.excluded.slice() : [],
          };
        }
      }
      // tpConfig migration: use stored value if shape-valid, else keep the
      // fixed default already in dst from _blankSnapshot.
      if (snap && _isValidTpConfigShape(snap.tpConfig)) {
        dst.tpConfig = JSON.parse(JSON.stringify(snap.tpConfig));
      }
      presetSnapshots[id] = dst;
    }
  } catch (e) { console.warn('[snapshots] load failed:', e.message); }
}

function savePresetSnapshots() {
  try {
    const out = {};
    for (let id = 0; id < PRESET_MAX; id++) {
      const snap = presetSnapshots[id];
      if (!snap) continue;
      // Compact: drop fully-empty snapshots to keep the blob small.
      const chipsOut = {};
      let hasAny = false;
      for (const [k, v] of Object.entries(snap.chips || {})) {
        if ((v.included && v.included.length) || (v.excluded && v.excluded.length)) {
          chipsOut[k] = { included: v.included.slice(), excluded: v.excluded.slice() };
          hasAny = true;
        }
      }
      const customOut = {};
      for (const [k, v] of Object.entries(snap.customChips || {})) {
        if (!v) continue;
        const hasVals = (v.included?.length || 0) + (v.excluded?.length || 0) > 0;
        if (!hasVals) continue;
        customOut[k] = {
          mode: v.mode || 'neutral',
          matchMode: v.matchMode || 'any',
          included: (v.included || []).slice(),
          excluded: (v.excluded || []).slice(),
        };
        hasAny = true;
      }
      // tpConfig: include only when valid AND non-default (matches the
      // "compact: skip empty" pattern). Non-default tpConfig is itself
      // content, so it flips hasAny.
      let tpcOut = null;
      if (_isValidTpConfigShape(snap.tpConfig)) {
        if (JSON.stringify(snap.tpConfig) !== JSON.stringify(_defaultTpConfig())) {
          tpcOut = JSON.parse(JSON.stringify(snap.tpConfig));
          hasAny = true;
        }
      }
      if (hasAny) {
        out[id] = { chips: chipsOut, customChips: customOut };
        if (tpcOut) out[id].tpConfig = tpcOut;
      }
    }
    localStorage.setItem(_htfKey(PRESET_SNAPSHOTS_LS_KEY), JSON.stringify(out));
  } catch (e) { console.warn('[snapshots] save failed:', e.message); }
}

// ══════════════════════════════════════════════════════
//  PRESET LIVE FILTERS — filtres non-sauvegardés (sans glow) par preset.
//  Sœur jumelle de presetSnapshots : même forme snapshot + un slot
//  comboFilters pour les filtres heatmap (sessionDay / pairSession).
//  La clé 'null' (string) = pseudo-preset "aucun preset actif" — permet
//  à l'utilisateur de naviguer entre presets sans perdre ses filtres
//  travaillés hors contexte preset.
// ══════════════════════════════════════════════════════

const PRESET_LIVE_FILTERS_LS_KEY = 'presetLiveFilters_v1';

// Runtime map. Clés : number 0..PRESET_MAX-1, ou string 'null'.
const presetLiveFilters = {};

function _liveKey(id) { return id === null ? 'null' : id; }

/** Slot vide, même forme que _blankSnapshot() plus le bloc comboFilters qui
 *  vit uniquement en live (combo filters ne sont pas persistés dans les
 *  snapshots — voir commentaire dans commitLiveFiltersToActivePreset). */
function _blankLiveSlot() {
  const slot = _blankSnapshot();
  slot.comboFilters = {
    sessionDay:  { included: [], excluded: [] },
    pairSession: { included: [], excluded: [] },
  };
  // Per-preset ORR bubble selection. Hydrated on applyPreset, persisted on
  // every _rrFilterBubbleClick / _rrClearFilter so reloads + preset switches
  // restore the right bubble.
  slot.rrMinFilter = null;
  // tpConfig is inherited from _blankSnapshot (per-preset architecture).
  // PR-C: Partial Optimizer preset slots (P1/P2/P3). Each slot stores only the
  // model params (tpFinal + legs); stats are recomputed on the current filtered
  // dataset on every render. null = empty slot.
  slot.poPresetSlots = { P1: null, P2: null, P3: null };
  return slot;
}

function getPresetLiveSlot(id) {
  const k = _liveKey(id);
  if (!presetLiveFilters[k]) presetLiveFilters[k] = _blankLiveSlot();
  if (!presetLiveFilters[k].comboFilters) {
    presetLiveFilters[k].comboFilters = {
      sessionDay:  { included: [], excluded: [] },
      pairSession: { included: [], excluded: [] },
    };
  }
  if (typeof presetLiveFilters[k].rrMinFilter === 'undefined') {
    presetLiveFilters[k].rrMinFilter = null;
  }
  // Migration: legacy slots may not have tpConfig. Default to fixed mode.
  if (!_isValidTpConfigShape(presetLiveFilters[k].tpConfig)) {
    presetLiveFilters[k].tpConfig = _defaultTpConfig();
  }
  // PR-C migration: legacy slots have no poPresetSlots. Default to all empty.
  if (!presetLiveFilters[k].poPresetSlots
      || typeof presetLiveFilters[k].poPresetSlots !== 'object') {
    presetLiveFilters[k].poPresetSlots = { P1: null, P2: null, P3: null };
  } else {
    // Ensure all 3 keys exist (forward-compat in case future code adds slots).
    for (const key of ['P1', 'P2', 'P3']) {
      if (!(key in presetLiveFilters[k].poPresetSlots)) {
        presetLiveFilters[k].poPresetSlots[key] = null;
      }
    }
  }
  return presetLiveFilters[k];
}

function loadPresetLiveFilters() {
  try {
    const raw = localStorage.getItem(_htfKey(PRESET_LIVE_FILTERS_LS_KEY));
    if (!raw) return;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return;
    for (const [k, slot] of Object.entries(parsed)) {
      const dst = _blankLiveSlot();
      if (slot && slot.chips && typeof slot.chips === 'object') {
        for (const dk of Object.keys(dst.chips)) {
          const src = slot.chips[dk] || {};
          dst.chips[dk].included = Array.isArray(src.included) ? src.included.slice() : [];
          dst.chips[dk].excluded = Array.isArray(src.excluded) ? src.excluded.slice() : [];
          dst.chips[dk].removedFromIncluded = Array.isArray(src.removedFromIncluded) ? src.removedFromIncluded.slice() : [];
          dst.chips[dk].removedFromExcluded = Array.isArray(src.removedFromExcluded) ? src.removedFromExcluded.slice() : [];
        }
      }
      if (slot && slot.customChips && typeof slot.customChips === 'object') {
        for (const [ck, cv] of Object.entries(slot.customChips)) {
          if (!cv || typeof cv !== 'object') continue;
          dst.customChips[ck] = {
            mode: (cv.mode === 'include' || cv.mode === 'exclude') ? cv.mode : 'neutral',
            matchMode: cv.matchMode === 'all' ? 'all' : 'any',
            included: Array.isArray(cv.included) ? cv.included.slice() : [],
            excluded: Array.isArray(cv.excluded) ? cv.excluded.slice() : [],
          };
        }
      }
      if (slot && slot.comboFilters && typeof slot.comboFilters === 'object') {
        for (const ck of ['sessionDay', 'pairSession']) {
          const src = slot.comboFilters[ck] || {};
          dst.comboFilters[ck].included = Array.isArray(src.included) ? src.included.slice() : [];
          dst.comboFilters[ck].excluded = Array.isArray(src.excluded) ? src.excluded.slice() : [];
        }
      }
      dst.rrMinFilter = (slot && typeof slot.rrMinFilter === 'number') ? slot.rrMinFilter : null;
      // tpConfig migration: use stored value if shape-valid, else keep the
      // fixed default already in dst from _blankLiveSlot/_blankSnapshot.
      if (slot && _isValidTpConfigShape(slot.tpConfig)) {
        dst.tpConfig = JSON.parse(JSON.stringify(slot.tpConfig));
      }
      // PR-C: hydrate poPresetSlots (P1/P2/P3) from storage. Validate shape per slot.
      if (slot && slot.poPresetSlots && typeof slot.poPresetSlots === 'object') {
        for (const key of ['P1', 'P2', 'P3']) {
          const s = slot.poPresetSlots[key];
          if (s && typeof s === 'object'
              && Number.isFinite(s.tpFinal)
              && Array.isArray(s.legs) && s.legs.length >= 1 && s.legs.length <= 3
              && typeof s.type === 'string'
              && typeof s.name === 'string') {
            // Deep-validate each leg
            const legsValid = s.legs.every(l =>
              l && typeof l === 'object'
              && Number.isFinite(l.lv) && Number.isFinite(l.pct)
            );
            if (legsValid) {
              dst.poPresetSlots[key] = {
                tpFinal: s.tpFinal,
                legs: s.legs.map(l => ({ lv: l.lv, pct: l.pct })),
                type: s.type,
                name: s.name,
              };
            }
          }
        }
      }
      presetLiveFilters[k] = dst;
    }
  } catch (e) { console.warn('[presetLiveFilters] load failed:', e.message); }
}

function savePresetLiveFilters() {
  try {
    const out = {};
    for (const [k, slot] of Object.entries(presetLiveFilters)) {
      const chipsOut = {};
      let hasAny = false;
      for (const [dk, dim] of Object.entries(slot.chips || {})) {
        const rmInc = dim.removedFromIncluded || [];
        const rmExc = dim.removedFromExcluded || [];
        if ((dim.included?.length || 0) + (dim.excluded?.length || 0) + rmInc.length + rmExc.length === 0) continue;
        chipsOut[dk] = { included: dim.included.slice(), excluded: dim.excluded.slice() };
        if (rmInc.length) chipsOut[dk].removedFromIncluded = rmInc.slice();
        if (rmExc.length) chipsOut[dk].removedFromExcluded = rmExc.slice();
        hasAny = true;
      }
      const customOut = {};
      for (const [ck, cv] of Object.entries(slot.customChips || {})) {
        if ((cv.included?.length || 0) + (cv.excluded?.length || 0) === 0) continue;
        customOut[ck] = {
          mode: cv.mode || 'neutral',
          matchMode: cv.matchMode || 'any',
          included: cv.included.slice(),
          excluded: cv.excluded.slice(),
        };
        hasAny = true;
      }
      const cfOut = {};
      for (const ck of ['sessionDay', 'pairSession']) {
        const cf = slot.comboFilters && slot.comboFilters[ck];
        if (!cf) continue;
        if ((cf.included?.length || 0) + (cf.excluded?.length || 0) === 0) continue;
        cfOut[ck] = { included: cf.included.slice(), excluded: cf.excluded.slice() };
        hasAny = true;
      }
      const rrMin = (typeof slot.rrMinFilter === 'number') ? slot.rrMinFilter : null;
      if (rrMin !== null) hasAny = true;
      // tpConfig: include only when valid AND non-default (per-preset TPM).
      let tpcOut = null;
      if (_isValidTpConfigShape(slot.tpConfig)) {
        if (JSON.stringify(slot.tpConfig) !== JSON.stringify(_defaultTpConfig())) {
          tpcOut = JSON.parse(JSON.stringify(slot.tpConfig));
          hasAny = true;
        }
      }
      // PR-C: serialize poPresetSlots only if at least one slot is non-null.
      let poSlotsOut = null;
      if (slot.poPresetSlots && typeof slot.poPresetSlots === 'object') {
        const anySlot = ['P1', 'P2', 'P3'].some(k2 => slot.poPresetSlots[k2] !== null);
        if (anySlot) {
          poSlotsOut = {
            P1: slot.poPresetSlots.P1 ? JSON.parse(JSON.stringify(slot.poPresetSlots.P1)) : null,
            P2: slot.poPresetSlots.P2 ? JSON.parse(JSON.stringify(slot.poPresetSlots.P2)) : null,
            P3: slot.poPresetSlots.P3 ? JSON.parse(JSON.stringify(slot.poPresetSlots.P3)) : null,
          };
          hasAny = true;
        }
      }
      if (hasAny) {
        out[k] = { chips: chipsOut, customChips: customOut, comboFilters: cfOut, rrMinFilter: rrMin };
        if (tpcOut) out[k].tpConfig = tpcOut;
        if (poSlotsOut) out[k].poPresetSlots = poSlotsOut;
      }
    }
    localStorage.setItem(_htfKey(PRESET_LIVE_FILTERS_LS_KEY), JSON.stringify(out));
  } catch (e) { console.warn('[presetLiveFilters] save failed:', e.message); }
}

/** Première initialisation ou backfill. Garantit qu'un slot existe pour
 *  chaque preset courant + pour le pseudo-preset null. Appelée au boot
 *  juste après loadPresetLiveFilters. */
function _ensureLiveSlotsInitialized() {
  const hadKey = !!localStorage.getItem(_htfKey(PRESET_LIVE_FILTERS_LS_KEY));
  PRESETS.forEach(p => {
    if (!presetLiveFilters[p.id]) presetLiveFilters[p.id] = _blankLiveSlot();
  });
  if (!presetLiveFilters['null']) presetLiveFilters['null'] = _blankLiveSlot();
  if (!hadKey) savePresetLiveFilters();
}

/** One-shot v1→v2 migration. Reads the legacy preset hard-exclusion fields
 *  (m15Exclude/h4Exclude/sessionExclude/dayExclude/dayInclude/setupInclude/
 *  sessionInclude/pairInclude) and the legacy presetOverrides[id] per-dim
 *  Sets + customChips, and materializes them into presetSnapshots[id].
 *  Idempotent: guarded by SCHEMA_VERSION_KEY == '2'. Runs AFTER
 *  loadPresetsList() + loadPresetOverrides(). Does NOT touch PRESETS
 *  fields here — that cleanup happens in Step 2 when applyPreset switches
 *  to reading from snapshots. Keeping the legacy fields populated during
 *  Step 1 means the app behaves exactly like v1. */
function _migrateToV2() {
  const current = localStorage.getItem(SCHEMA_VERSION_KEY);
  if (current === String(SCHEMA_VERSION_CURRENT)) return false;

  // For each preset, build a snapshot from the merged v1 state.
  for (const p of PRESETS) {
    const id = p.id;
    if (!Number.isFinite(id) || id < 0 || id >= PRESET_MAX) continue;
    const snap = _blankSnapshot();

    // 1) Preset hard fields → per-dim chip values.
    //    For non-noBaseExclusions presets, BASE_M15_EXCLUDE/BASE_SESSION_EXCLUDE
    //    were silently layered in v1. Fold them into the snapshot so v2 gets
    //    the same behavior without any runtime prepending.
    const withBase = !p.noBaseExclusions;
    const m15Ex = (withBase ? BASE_M15_EXCLUDE : []).concat(p.m15Exclude || []);
    const sessEx = (withBase ? BASE_SESSION_EXCLUDE : []).concat(p.sessionExclude || []);
    const h4Ex   = (p.h4Exclude || []);
    const dayEx  = (p.dayExclude || []);

    m15Ex.forEach(v => snap.chips.obstacles.excluded.push(v));
    h4Ex.forEach(v => snap.chips.h4obs.excluded.push(v));
    sessEx.forEach(v => snap.chips.session.excluded.push(v));
    dayEx.forEach(v => snap.chips.day.excluded.push(v));
    (p.dayInclude || []).forEach(v => snap.chips.day.included.push(v));
    (p.setupInclude || []).forEach(v => snap.chips.setup.included.push(v));
    (p.sessionInclude || []).forEach(v => snap.chips.session.included.push(v));
    (p.pairInclude || []).forEach(v => snap.chips.pair.included.push(v));

    // 2) Tune-panel overrides → per-dim chip values (merge, preserve order).
    const ov = presetOverrides[id];
    if (ov) {
      SB_DIMS.forEach(d => {
        const s = ov[d.key];
        if (!s) return;
        const dst = snap.chips[d.key];
        if (!dst) return;
        [...s.included].forEach(v => dst.included.push(v));
        [...s.excluded].forEach(v => dst.excluded.push(v));
      });
      // Custom chips (user-declared Notion props).
      for (const [k, e] of Object.entries(ov.customChips || {})) {
        if (!e) continue;
        const inc = [...(e.included || [])];
        const exc = [...(e.excluded || [])];
        if (!inc.length && !exc.length) continue;
        snap.customChips[k] = {
          mode: e.mode || 'neutral',
          matchMode: e.matchMode || 'any',
          included: inc,
          excluded: exc,
        };
      }
    }

    // 3) Dedup within each dim (BASE_* + p.m15Exclude might overlap).
    for (const k of Object.keys(snap.chips)) {
      snap.chips[k].included = [...new Set(snap.chips[k].included)];
      snap.chips[k].excluded = [...new Set(snap.chips[k].excluded)];
    }

    presetSnapshots[id] = snap;
  }

  // Post-migration hygiene: strip the legacy hard-exclusion fields from every
  // PRESETS entry so they can't drift and get rendered anywhere. snapshot is
  // now the single source of truth.
  for (const p of PRESETS) {
    delete p.m15Exclude;
    delete p.h4Exclude;
    delete p.sessionExclude;
    delete p.dayExclude;
    delete p.dayInclude;
    delete p.setupInclude;
    delete p.sessionInclude;
    delete p.pairInclude;
    p.noBaseExclusions = true;
    p.clear = true;
  }
  savePresetsList();
  savePresetSnapshots();
  localStorage.setItem(SCHEMA_VERSION_KEY, String(SCHEMA_VERSION_CURRENT));
  return true;
}

// One-shot migration: switch from the old hard-exclude (Invalide and BadFeeling
// silently dropped at the dataset level) to the new chip-based filtering.
// For existing users: pre-exclude `Invalide` (Trade Type) and `Yes` (Bad Feeling)
// in the live chip state so the historical behavior is preserved.
// For new users: leave both at neutral so all data is visible by default.
// Idempotent — runs at most once per browser thanks to the localStorage flag.
function _migrateInvalideBadFeelingV1() {
  const FLAG = 'flipping_invalide_bf_migration_v1';
  if (localStorage.getItem(FLAG)) return false;

  let mutated = false;
  const isExistingUser = !!(
    localStorage.getItem('flipping_presets') ||
    localStorage.getItem('flipping_sidebar_state') ||
    localStorage.getItem(_htfKey(PRESET_SNAPSHOTS_LS_KEY)) ||
    localStorage.getItem('flipping_preset_snapshots')
  );

  // Strip any deprecated `badFeeling` chip dim from preset snapshots that may
  // have been written by a previous (rejected) refactor. Safe no-op otherwise.
  for (let id = 0; id < PRESET_MAX; id++) {
    const snap = presetSnapshots[id];
    if (snap && snap.chips && snap.chips.badFeeling) delete snap.chips.badFeeling;
  }
  savePresetSnapshots();

  if (isExistingUser) {
    // Find the actual "Invalide" value in the dataset (casing may vary).
    const allTypes = new Set();
    appState.trades.items.forEach(t => (t.tradeType || []).forEach(tt => allTypes.add(tt)));
    const invalideValue = [...allTypes].find(v => typeof v === 'string' && v.toLowerCase().includes('invalide'));

    if (invalideValue) {
      const tt = appState.filters.chips.tradeType;
      if (!tt.excluded.has(invalideValue)) {
        tt.excluded.add(invalideValue);
        if (tt.mode === 'neutral') tt.mode = 'exclude';
        mutated = true;
      }
    }

    const bf = appState.filters.chips.badFeeling;
    if (bf && !bf.excluded.has('Yes')) {
      bf.excluded.add('Yes');
      if (bf.mode === 'neutral') bf.mode = 'exclude';
      mutated = true;
    }
  }

  localStorage.setItem(FLAG, '1');
  return mutated;
}

// One-shot migration 2026-05-24: P0 RAW Baseline is now truly raw (no base
// exclusions). Existing users whose snapshot was materialised by _migrateToV2
// have BASE_M15_EXCLUDE / BASE_SESSION_EXCLUDE baked into P0's chips — strip
// them so the baseline shows every trade. Idempotent via LS flag.
function _migrateRawBaselineToTrulyRaw_v1() {
  const FLAG = 'flipping_raw_baseline_truly_raw_v1';
  if (localStorage.getItem(FLAG)) return false;
  const snap = presetSnapshots[0];
  if (snap && snap.chips) {
    const baseM15 = new Set(BASE_M15_EXCLUDE);
    const baseSess = new Set(BASE_SESSION_EXCLUDE);
    const obs = snap.chips.obstacles;
    if (obs && Array.isArray(obs.excluded) && obs.excluded.length) {
      obs.excluded = obs.excluded.filter(v => !baseM15.has(v));
    }
    const sess = snap.chips.session;
    if (sess && Array.isArray(sess.excluded) && sess.excluded.length && baseSess.size) {
      sess.excluded = sess.excluded.filter(v => !baseSess.has(v));
    }
    savePresetSnapshots();
  }
  // Force P0 in PRESETS to carry noBaseExclusions:true (legacy v1→v2 migrations
  // set this on every preset but a manually corrupted state could be missing it).
  const p0 = PRESETS.find(p => p.id === 0);
  if (p0 && p0.noBaseExclusions !== true) {
    p0.noBaseExclusions = true;
    p0.description = 'Every trade — no filters applied';
    savePresetsList();
  }
  localStorage.setItem(FLAG, '1');
  return true;
}

// One-shot migration: drop legacy custom widget defs with type='donut'.
// The donut widget was retired 2026-05-24 in favor of a sortable table that
// surfaces #Trades / Win Rate / Avg R / PF / Total R per category.
// Idempotent via LS flag — runs once, never resurrects donut entries even
// if the user manually edits LS.
function _migrateDropLegacyDonuts_v1() {
  const FLAG = 'flipping_drop_legacy_donuts_v1';
  if (localStorage.getItem(FLAG)) return false;
  try {
    const defs = (typeof _loadCustomWidgetDefs === 'function') ? _loadCustomWidgetDefs() : [];
    const filtered = defs.filter(d => d?.type !== 'donut');
    if (filtered.length !== defs.length) {
      _saveCustomWidgetDefs(filtered);
      debugLog(`[migrate] dropped ${defs.length - filtered.length} legacy donut widget(s)`);
    }
  } catch (e) {
    console.warn('[migrate] drop-legacy-donuts failed:', e?.message || e);
  }
  localStorage.setItem(FLAG, '1');
  return true;
}

// ══ TUNE PANEL OPEN/CLOSE ══
let openTunePanel = null;
// Tracks which preset's delete confirmation is currently shown inside its
// tune panel header. Only one can be open at a time. Read by buildTunePanel().
let _poPendingDeleteId = null;

// Inline-edit BOTH .preset-name and .preset-desc spans inside the sidebar
// preset row (the "blue card") at the same time. Driven by the ✎ button in
// the tune panel header (data-action="po-edit-preset") or by the custom
// right-click menu. Shift+Enter inserts a newline; Enter alone commits both;
// Escape cancels; clicking outside both textareas commits.
function _poEditPreset(id) {
  const row = document.getElementById('preset-row-' + id);
  if (!row) return;
  const nameEl = row.querySelector('.preset-name');
  const descEl = row.querySelector('.preset-desc');
  if (!nameEl || !descEl) return;
  // Already editing? Bail.
  if (nameEl.querySelector('textarea') || descEl.querySelector('textarea')) return;
  const preset = PRESETS.find(p => p.id === id);
  if (!preset) return;
  const pencilEl = document.querySelector(`.po-pencil-btn[data-poid="${id}"]`);
  if (pencilEl) pencilEl.classList.add('active');

  const makeTextarea = (host, value) => {
    const ta = document.createElement('textarea');
    ta.className = 'preset-edit-textarea';
    ta.value = value;
    ta.rows = 1;
    host.textContent = '';
    host.appendChild(ta);
    const resize = () => {
      ta.style.height = 'auto';
      ta.style.height = ta.scrollHeight + 'px';
    };
    resize();
    ta.addEventListener('input', resize);
    // Don't let textarea interactions bubble up to the row's click handler
    // (which would try to apply the preset).
    ta.addEventListener('click', (e) => e.stopPropagation());
    ta.addEventListener('mousedown', (e) => e.stopPropagation());
    return ta;
  };

  const taName = makeTextarea(nameEl, preset.label || '');
  const taDesc = makeTextarea(descEl, preset.description || '');

  taName.focus();
  taName.setSelectionRange(taName.value.length, taName.value.length);

  let committed = false;
  const reopenTunePanel = () => {
    const panel = document.getElementById('po-panel-' + id);
    const btn   = document.getElementById('tune-' + id);
    if (panel && btn) {
      buildTunePanel(id);
      panel.classList.add('open');
      btn.classList.add('open');
      openTunePanel = id;
      if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    }
  };

  const cleanup = () => {
    document.removeEventListener('mousedown', outsideHandler, true);
  };

  const commit = () => {
    if (committed) return;
    committed = true;
    if (pencilEl) pencilEl.classList.remove('active');
    cleanup();
    const newLabel = taName.value.trim();
    const newDesc  = taDesc.value.trim();
    // Preserve the original label if user cleared it (labels must be non-empty).
    if (newLabel) preset.label = newLabel;
    preset.description = newDesc;
    savePresetsList();
    renderPresetList();
    refreshPresetCompareDropdowns();
    renderMobilePresetControls();
    // renderPresetList() rebuilds the sidebar including this row's tune panel.
    // Re-open it so the user keeps their context.
    reopenTunePanel();
  };

  const cancel = () => {
    if (committed) return;
    committed = true;
    if (pencilEl) pencilEl.classList.remove('active');
    cleanup();
    // Re-render the sidebar to drop the textareas without saving.
    renderPresetList();
    reopenTunePanel();
  };

  const onKeydown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      commit();
    } else if (e.key === 'Escape') {
      e.preventDefault();
      cancel();
    }
    // Shift+Enter falls through → textarea inserts a newline.
  };
  taName.addEventListener('keydown', onKeydown);
  taDesc.addEventListener('keydown', onKeydown);

  // Outside click → commit. Bound on capture so we run before the row's
  // own click handler (which would try to apply the preset).
  function outsideHandler(e) {
    if (committed) return;
    if (e.target === taName || e.target === taDesc) return;
    if (taName.contains(e.target) || taDesc.contains(e.target)) return;
    commit();
  }
  // Defer one tick so the click that opened this editor doesn't close it.
  setTimeout(() => {
    document.addEventListener('mousedown', outsideHandler, true);
  }, 0);
}

// ── Custom right-click menu on .preset-name / .preset-desc ──
function _poShowPresetContextMenu(id, x, y) {
  // Only one context menu in the DOM at a time.
  const existing = document.getElementById('po-ctx-menu');
  if (existing) existing.remove();
  const menu = document.createElement('div');
  menu.className = 'po-ctx-menu';
  menu.id = 'po-ctx-menu';
  menu.style.left = x + 'px';
  menu.style.top  = y + 'px';
  const itemEdit = document.createElement('div');
  itemEdit.className = 'po-ctx-menu-item';
  itemEdit.textContent = '✎ Rename';
  itemEdit.addEventListener('mousedown', (e) => {
    e.preventDefault();
    e.stopPropagation();
    menu.remove();
    _poEditPreset(id);
  });
  menu.appendChild(itemEdit);

  const itemDel = document.createElement('div');
  itemDel.className = 'po-ctx-menu-item po-ctx-menu-item--danger';
  itemDel.textContent = '✕ Delete';
  itemDel.addEventListener('mousedown', (e) => {
    e.preventDefault();
    e.stopPropagation();
    menu.remove();
    _poShowDeleteConfirmDialog(id);
  });
  menu.appendChild(itemDel);
  document.body.appendChild(menu);
  // Defer dismiss listener so the contextmenu event that opened it doesn't
  // immediately close it.
  setTimeout(() => {
    const closeMenu = (ev) => {
      if (ev.target.closest('#po-ctx-menu')) return;
      menu.remove();
      document.removeEventListener('mousedown', closeMenu);
      document.removeEventListener('contextmenu', closeMenu);
    };
    document.addEventListener('mousedown', closeMenu);
    document.addEventListener('contextmenu', closeMenu);
  }, 0);
}

function handlePoFieldContextMenu(e) {
  // User theme swatches — right-click opens Rename/Delete menu
  const userSwatch = e.target.closest('#tp-user-themes .tp-preset-swatch.is-user');
  if (userSwatch) {
    const mUT = userSwatch.id.match(/^usertheme-(\d+)$/);
    if (mUT) {
      e.preventDefault();
      _showUserThemeContextMenu(parseInt(mUT[1], 10), e.clientX, e.clientY);
      return;
    }
  }
  const target = e.target.closest('.preset-name, .preset-desc');
  if (!target) return;
  // If a textarea is already inside, fall back to the native menu.
  if (target.querySelector('textarea')) return;
  const row = target.closest('.preset-row');
  if (!row) return;
  const m = row.id.match(/^preset-row-(\d+)$/);
  if (!m) return;
  const id = parseInt(m[1], 10);
  e.preventDefault();
  _poShowPresetContextMenu(id, e.clientX, e.clientY);
}

function poOpenDeleteConfirm(id) {
  _poPendingDeleteId = id;
  buildTunePanel(id);
}
// Dismiss the inline confirm without rebuilding the whole panel — direct DOM
// removal is more robust than calling buildTunePanel(), which would re-render
// the dims and could race with in-flight handlers (e.g. the _poEditPreset
// outside-mousedown capture listener).
function _poDismissDeleteConfirm(id) {
  if (_poPendingDeleteId === id) _poPendingDeleteId = null;
  const panel = document.getElementById('po-panel-' + id);
  if (!panel) return;
  const confirmEl = panel.querySelector('.po-delete-confirm');
  if (confirmEl) confirmEl.remove();
  const delBtn = panel.querySelector('.po-delete-btn');
  if (delBtn) delBtn.classList.remove('active');
}
function _poShowDeleteConfirmDialog(id) {
  const preset = PRESETS.find(p => p.id === id);
  if (!preset) return;
  const name = preset.name || preset.label || 'Preset ' + id;

  document.getElementById('po-delete-backdrop')?.remove();

  const backdrop = document.createElement('div');
  backdrop.id = 'po-delete-backdrop';
  backdrop.className = 'layout-confirm-backdrop';
  backdrop.innerHTML = `
    <div class="layout-confirm-modal" role="dialog" aria-modal="true">
      <div class="layout-confirm-head">
        <span class="layout-confirm-icon">⚠</span>
        <span class="layout-confirm-title">Delete preset</span>
      </div>
      <div class="layout-confirm-body">
        <div class="layout-confirm-sub">Are you sure you want to delete <span class="layout-confirm-name">"${_escapeHtml(name)}"</span>?</div>
        <div class="layout-confirm-sub" style="margin-top:4px;opacity:.6">This action cannot be undone.</div>
      </div>
      <div class="layout-confirm-actions">
        <button class="lt-btn layout-confirm-cancel" type="button">Cancel</button>
        <button class="lt-btn layout-confirm-ok layout-confirm-ok--danger" type="button">Delete</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);

  const close = () => { backdrop.remove(); document.removeEventListener('keydown', onKey); };
  const commit = () => { close(); poConfirmDeletePreset(id); };
  backdrop.addEventListener('click', e => { if (e.target === backdrop) close(); });
  backdrop.querySelector('.layout-confirm-cancel').addEventListener('click', close);
  backdrop.querySelector('.layout-confirm-ok').addEventListener('click', commit);
  const onKey = e => {
    if (e.key === 'Escape') close();
    else if (e.key === 'Enter') commit();
  };
  document.addEventListener('keydown', onKey);
}

function poConfirmDeletePreset(id) {
  _poPendingDeleteId = null;
  // deletePreset() normally shows a confirm() — but our inline confirm has
  // already taken its place. Mirror its body without the browser dialog.
  const preset = PRESETS.find(p => p.id === id);
  if (!preset) return;
  PRESETS = PRESETS.filter(p => p.id !== id);
  if (presetOverrides[id]) {
    SB_DIMS.forEach(d => {
      presetOverrides[id][d.key] = { mode: 'neutral', included: new Set(), excluded: new Set() };
    });
  }
  if (appState.presets.activeId === id) {
    appState.presets.activeId = null;
  }
  savePresetsList();
  savePresetOverrides();
  renderPresetList();
  refreshPresetCompareDropdowns();
  renderMobilePresetControls();
  render();
}

function toggleTunePanel(id, e) {
  e.stopPropagation();
  const panel = document.getElementById('po-panel-' + id);
  const btn   = document.getElementById('tune-' + id);
  if (!panel) return;
  const isOpen = panel.classList.contains('open');
  // If some OTHER preset panel is currently open, normalize its modes (drop
  // any sticky INCLUDE/EXCLUDE click-mode feedback that no longer has values)
  // before we close it — sticky modes only persist while the panel is open.
  if (typeof openTunePanel === 'number' && openTunePanel !== id) {
    if (normalizePoModes(openTunePanel)) {
      savePresetOverrides();
    }
  }
  // Close all panels
  document.querySelectorAll('.preset-override-panel.open').forEach(p => p.classList.remove('open'));
  document.querySelectorAll('.preset-tune-btn.open').forEach(b => b.classList.remove('open'));
  if (!isOpen) {
    // Opening the tune panel of a preset implies intent to edit it. Auto-
    // activate so live chips / Update / Reset all behave consistently. The
    // old inactive-preset path silently committed chip clicks straight into
    // presetSnapshots[id] and Reset wiped the snapshot wholesale — neither
    // is what the user expects. applyPreset is a no-op when id already matches.
    if (appState.presets.activeId !== id) {
      applyPreset(id);
    }
    buildTunePanel(id);
    panel.classList.add('open');
    btn.classList.add('open');
    openTunePanel = id;
  } else {
    // Closing THIS panel: normalize its sticky modes too.
    if (normalizePoModes(id)) {
      savePresetOverrides();
    }
    openTunePanel = null;
    // Silent reset: closing the panel implicitly cancels any pending delete
    // confirm for this preset (no rebuild needed — the panel is hidden).
    if (_poPendingDeleteId === id) _poPendingDeleteId = null;
  }
  // Swap the sidebar live-filter indicator between dot (panel closed) and
  // +N count (panel open). Must run AFTER the .open class mutations above.
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
}

// v2: sticky click-mode for tune panels targeting inactive presets. Active
// preset borrows its mode from appState.filters.chips[key].mode.
const _inactiveTuneMode = {};

/** Unified view of a preset's dim-state for the tune panel.
 *  - Active preset: returns the live appState.filters.chips[dim] entry.
 *  - Inactive preset: synthesizes from presetSnapshots[id]. Every snapshot
 *    value is treated as preset-flagged (glow) — for an inactive preset, all
 *    chips are "saved", there are no live overrides to distinguish.
 *  Returned entry is a READ view. Writes go through _tuneWriteChip / _tuneSetMode. */
function _tuneReadDim(id, dimKey) {
  if (appState.presets.activeId === id) {
    const e = appState.filters.chips[dimKey];
    if (e) _ensureFromPresetSets(e);
    return e;
  }
  const snap = presetSnapshots[id] || _blankSnapshot();
  const dim = snap.chips[dimKey] || { included: [], excluded: [] };
  const included = new Set(dim.included);
  const excluded = new Set(dim.excluded);
  const fallbackMode = included.size ? 'include' : excluded.size ? 'exclude' : 'neutral';
  return {
    mode: (_inactiveTuneMode[id] && _inactiveTuneMode[id][dimKey]) || fallbackMode,
    included,
    excluded,
    includedFromPreset: new Set(included),
    excludedFromPreset: new Set(excluded),
  };
}

function buildTunePanel(id) {
  const panel = document.getElementById('po-panel-' + id);
  if (!panel) return;

  // Render dims in the user's drag-chosen display order (sidebar parity).
  // Canonical SB_DIMS is still used for lookup — only iteration order changes.
  const _SB_DIMS_BY_KEY = Object.fromEntries(SB_DIMS.map(d => [d.key, d]));
  const _dimsInOrder = getSidebarDisplayOrderNatives()
    .map(k => _SB_DIMS_BY_KEY[k])
    .filter(Boolean);

  // Snapshot the current open/closed state of each dim's body so re-renders
  // triggered by chip/mode clicks do NOT clobber what the user manually opened
  // or closed. On the very first render for this preset, fall back to
  // auto-opening dims that already have values.
  const isFirstRender = !panel.querySelector('.po-dim-body');
  const openDimKeys = new Set();
  if (isFirstRender) {
    _dimsInOrder.forEach(dim => {
      const s = _tuneReadDim(id, dim.key);
      if (s.included.size > 0 || s.excluded.size > 0) openDimKeys.add(dim.key);
    });
  } else {
    _dimsInOrder.forEach(dim => {
      const body = panel.querySelector('#pobody-' + id + '-' + dim.key);
      if (body && body.classList.contains('open')) openDimKeys.add(dim.key);
    });
  }

  const _poDeleteOpen = _poPendingDeleteId === id;
  let html = `<div class="po-header">
    <div class="po-header-left">
      <button class="po-reset-btn po-pencil-btn" data-action="po-edit-preset" data-poid="${id}" title="Edit title and subtitle">✎</button>
      <button class="po-delete-btn${_poDeleteOpen ? ' active' : ''}" data-action="po-delete-preset" data-poid="${id}" title="Delete this preset">✕</button>
    </div>
    <div class="po-header-right">
      <button class="po-reset-btn po-screenshot-btn" data-action="po-screenshot" data-poid="${id}" title="Copy preset image to clipboard">📷</button>
      <button class="po-reset-btn" data-action="po-reset" data-poid="${id}">↺ Reset</button>
    </div>
  </div>${_poDeleteOpen ? `<div class="po-delete-confirm">
    <span class="po-delete-confirm-text">Delete this preset?</span>
    <div class="po-delete-confirm-actions">
      <button class="po-reset-btn" data-action="po-delete-cancel" data-poid="${id}">Cancel</button>
      <button class="po-reset-btn po-confirm-del-btn" data-action="po-delete-confirm" data-poid="${id}">Confirm</button>
    </div>
  </div>` : ''}<div class="po-dims">`;

  _dimsInOrder.forEach(dim => {
    const s = _tuneReadDim(id, dim.key);
    const bothEmpty = s.included.size === 0 && s.excluded.size === 0;
    const activeFlags = {
      neutral: bothEmpty && s.mode === 'neutral',
      include: s.included.size > 0 || s.mode === 'include',
      exclude: s.excluded.size > 0 || s.mode === 'exclude',
    };
    const modeLabel = { neutral: 'neutre', exclude: 'exclude', include: 'include' };
    const iHTML = ['neutral','exclude','include'].map(m =>
      `<button class="po-mode-btn m-${m}${activeFlags[m] ? ' active' : ''}"
        data-action="po-set-mode" data-poid="${id}" data-pokey="${dim.key}" data-pomode="${m}">${modeLabel[m]}</button>`
    ).join('');

    const chipsHTML = dim.items.map(item => {
      let cls = 'po-chip';
      const isInc = s.included.has(item);
      const isExc = s.excluded.has(item);
      const incFP = s.includedFromPreset && s.includedFromPreset.has(item);
      const excFP = s.excludedFromPreset && s.excludedFromPreset.has(item);
      if (isInc)      cls += ' sel-include';
      else if (isExc) cls += ' sel-exclude';
      // Glow on chips flagged fromPreset. Tombstone (fromPreset without main)
      // renders as a muted/strikethrough chip — belongs to the preset but
      // has been stripped by the user.
      if (isInc && incFP) cls += ' is-from-preset';
      if (isExc && excFP) cls += ' is-from-preset';
      if (!isInc && !isExc && (incFP || excFP)) cls += ' is-tombstoned';
      const label = SETUP_SHORT[item]||SESSION_SHORT[item]||DAY_EN[item]||item;
      const safeItem = item.replace(/'/g,"&#39;").replace(/"/g,'&quot;');
      return `<span class="${cls}" data-action="po-chip-toggle" data-pokey="${dim.key}" data-poid="${id}" data-poitem="${safeItem}">${label}</span>`;
    }).join('');

    const bodyOpen = openDimKeys.has(dim.key) ? ' open' : '';
    // Two per-dim pills on .po-dim-label:
    //   +N (gold) — chips added but not saved (live additions)
    //   −N (rm)  — chips in the snapshot but disabled (tombstones)
    // The +N is meaningful only on the active preset; the −N tracks the
    // global tombstone state which only the active preset can produce.
    const addedN = _getLiveCountForDim(id, dim.key, false);
    const isActivePreset = appState.presets?.activeId === id;
    const removedN = isActivePreset ? _getTombstoneCountForDim(dim.key, false) : 0;
    const liveBadgeHTML =
        (addedN   > 0 ? `<span class="live-dim-badge" title="${addedN} unsaved live filter${addedN > 1 ? 's' : ''}">+${addedN}</span>` : '')
      + (removedN > 0 ? `<span class="live-dim-badge live-dim-badge-rm" title="${removedN} preset filter${removedN > 1 ? 's' : ''} disabled">−${removedN}</span>` : '');
    html += `<div class="po-dim" id="podim-${id}-${dim.key}">
      <div class="po-dim-head" data-action="po-toggle-dim" data-poid="${id}" data-pokey="${dim.key}">
        <span class="po-dim-label">${dim.label}${liveBadgeHTML}</span>
        <div class="po-mode-row">${iHTML}</div>
      </div>
      <div class="po-dim-body${bodyOpen}" id="pobody-${id}-${dim.key}">${chipsHTML}</div>
    </div>`;
  });

  // Live stats
  const preview = getPoPreview(id);
  html += `</div><div class="po-stats" id="po-stats-${id}">
    <span>n: <span class="po-stat-v">${preview.n}</span></span>
    <span>WR: <span class="po-stat-v">${preview.wr}</span></span>
    <span>Avg R: <span class="po-stat-v">${preview.ev}</span></span>
    <span>Total R: <span class="po-stat-v">${preview.tot}</span></span>
  </div>`;

  panel.innerHTML = html;
}

// ── Screenshot preset panel with all filter dims open ──
async function _screenshotPresetPanel(id, btn) {
  const panel = document.getElementById('po-panel-' + id);
  if (!panel || typeof domtoimage === 'undefined') return;

  // Capture target: the full .preset-row (header + panel) instead of just
  // the panel — so the captured image includes the preset name/description box.
  const presetRow = document.getElementById('preset-row-' + id);
  if (!presetRow) return;

  const origText = btn ? btn.textContent : '';
  if (btn) { btn.textContent = '⏳'; btn.disabled = true; }

  // 1. Open ALL dim bodies for the capture
  const dimBodies = [...panel.querySelectorAll('.po-dim-body')];
  const wasOpen = dimBodies.map(b => b.classList.contains('open'));
  dimBodies.forEach(b => b.classList.add('open'));

  // 1.bis Hide the action bar (edit / delete / screenshot / reset buttons)
  // for the capture only. It's noise in the screenshot — the user wants the
  // preset definition (header + chips), not the editing UI.
  const actionBar = panel.querySelector('.po-header');
  let actionBarPrevDisplay = '';
  if (actionBar) {
    actionBarPrevDisplay = actionBar.style.display;
    actionBar.style.display = 'none';
  }

  // 2. Promote live (unsaved) chips to the "saved" visual style for the
  //    capture. Without this, live chips render dashed/lighter (the normal
  //    in-panel cue for "not yet saved") and the screenshot looks fragmented
  //    instead of representing the preset + live filters as a cohesive set.
  //    Also hide the per-dim +N "unsaved" pills for the same reason — the
  //    captured image treats live filters as part of the preset. All state
  //    is restored in the finally block below.
  const liveSelChips = [...panel.querySelectorAll(
    '.po-chip.sel-include:not(.is-from-preset), .po-chip.sel-exclude:not(.is-from-preset)'
  )];
  liveSelChips.forEach(c => c.classList.add('is-from-preset'));
  const liveDimBadges = [...panel.querySelectorAll('.live-dim-badge')];
  liveDimBadges.forEach(b => { b.dataset.prevDisplay = b.style.display; b.style.display = 'none'; });

  // Small layout flush
  await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));

  const bgColor = getComputedStyle(document.documentElement).getPropertyValue('--bg1').trim() || '#0d1222';
  const scale = 2;
  const fullWidth  = Math.max(presetRow.scrollWidth,  presetRow.offsetWidth);
  const fullHeight = Math.max(presetRow.scrollHeight, presetRow.offsetHeight);

  try {
    const blob = await domtoimage.toBlob(presetRow, {
      bgcolor: bgColor,
      width:   fullWidth  * scale,
      height:  fullHeight * scale,
      style: {
        transform: 'scale(' + scale + ')',
        transformOrigin: 'top left',
        width:  fullWidth  + 'px',
        height: fullHeight + 'px',
        overflow: 'visible',
      },
    });
    if (!blob) throw new Error('Image generation failed');
    if (navigator.clipboard && window.ClipboardItem) {
      await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
      if (btn) btn.textContent = '✓';
    } else {
      const url = URL.createObjectURL(blob);
      window.open(url, '_blank', 'noopener,noreferrer');
      setTimeout(() => URL.revokeObjectURL(url), 60000);
    }
  } catch (err) {
    console.error('Preset screenshot failed:', err);
    if (btn) btn.textContent = '✕';
  } finally {
    // Restore original open/closed state + strip the temp is-from-preset
    // class off live chips + restore the +N pills we hid for capture +
    // restore the action bar.
    dimBodies.forEach((b, i) => { if (!wasOpen[i]) b.classList.remove('open'); });
    liveSelChips.forEach(c => c.classList.remove('is-from-preset'));
    liveDimBadges.forEach(b => {
      b.style.display = b.dataset.prevDisplay || '';
      delete b.dataset.prevDisplay;
    });
    if (actionBar) actionBar.style.display = actionBarPrevDisplay;
    setTimeout(() => { if (btn) { btn.textContent = origText; btn.disabled = false; } }, 1500);
  }
}

function getPoPreview(id) {
  const p = PRESETS.find(x => x.id === id);
  if (!p) return { n:'—',wr:'—',ev:'—',tot:'—' };
  // v2: live preview = preset snapshot applied to the current dataset mode
  // (BE include/exclude). Reflects the saved chips + any live chips flagged
  // as not-yet-saved if this preset is the active one.
  let base = appState.trades.items.slice();
  if (appState.presets.activeId === id) {
    // Active preset — use the live chip state so live chips appear in preview.
    base = filterChips(base);
    base = filterCustomChips(base);
  } else {
    base = _filterTradesBySnapshot(base, presetSnapshots[id]);
  }
  if (!base.length) return { n:0, wr:'—', ev:'—', tot:'—' };
  const tpConfig = appState.ui.tpConfig;
  const wins = base.filter(isWinner).length;
  const tot  = base.reduce((s,t)=>s+computeEffectiveRR(t, tpConfig),0);
  return {
    n: base.length,
    wr: (wins/base.length*100).toFixed(1)+'%',
    ev: (tot>=0?'+':'')+(tot/base.length).toFixed(3)+'R',
    tot: (tot>=0?'+':'')+tot.toFixed(1)+'R',
  };
}

/** Set the click-mode (or clear) for a dim in the tune panel. Routes to
 *  appState.filters.chips (active preset) or presetSnapshots (inactive). */
function setPoMode(id, dimKey, mode) {
  if (mode !== 'neutral' && mode !== 'include' && mode !== 'exclude') return;
  const isActive = appState.presets.activeId === id;

  // Keep the dim body expanded across the buildTunePanel re-render.
  const body = document.getElementById('pobody-'+id+'-'+dimKey);
  if (body && !body.classList.contains('open')) body.classList.add('open');

  if (mode === 'neutral') {
    // Destructive: clear the dim (both live and preset values).
    if (isActive) {
      const entry = appState.filters.chips[dimKey];
      if (entry) {
        _ensureFromPresetSets(entry);
        entry.included.clear();
        entry.excluded.clear();
        entry.includedFromPreset.clear();
        entry.excludedFromPreset.clear();
        entry.mode = 'neutral';
      }
      invalidateFilterCache();
    } else {
      const snap = presetSnapshots[id] || (presetSnapshots[id] = _blankSnapshot());
      if (snap.chips[dimKey]) { snap.chips[dimKey].included = []; snap.chips[dimKey].excluded = []; }
      if (_inactiveTuneMode[id]) _inactiveTuneMode[id][dimKey] = 'neutral';
      savePresetSnapshots();
    }
    buildTunePanel(id);
    if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
    if (isActive) render();
    return;
  }
  // include / exclude → just update the sticky click-mode. Non-destructive.
  if (isActive) {
    const entry = appState.filters.chips[dimKey];
    if (entry) entry.mode = mode;
  } else {
    if (!_inactiveTuneMode[id]) _inactiveTuneMode[id] = {};
    _inactiveTuneMode[id][dimKey] = mode;
  }
  buildTunePanel(id);
}

function handlePoChip(el) {
  const id = parseInt(el.dataset.poid);
  const dimKey = el.dataset.pokey;
  const item = el.dataset.poitem;
  togglePoChip(id, dimKey, item);
}

/** 3-state chip click in the tune panel.
 *  - Active preset: mutates appState.filters.chips (live change, drops fromPreset flag).
 *  - Inactive preset: mutates presetSnapshots[id] and persists. */
function togglePoChip(id, dimKey, item) {
  const isActive = appState.presets.activeId === id;

  if (isActive) {
    const entry = appState.filters.chips[dimKey];
    if (!entry) return;
    _ensureFromPresetSets(entry);
    // Tombstone click → restore to snapshot bucket with glow intact.
    const tombBucket = _chipTombstoneBucket(dimKey, item);
    if (tombBucket) {
      _restoreTombstone(entry, tombBucket, item);
      invalidateFilterCache();
      _syncChipModeButtons(dimKey);
      _syncLiveSlotFromActiveChips();
      buildTunePanel(id);
      if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
      render();
      return;
    }
    // Default to 'exclude' when no mode is set yet — matches the sidebar
    // Filters section behavior (_lastChipMode = 'exclude' at startup).
    if (entry.mode === 'neutral') entry.mode = 'exclude';
    const activeBucket = entry.mode === 'include' ? 'included' : 'excluded';
    const otherBucket  = entry.mode === 'include' ? 'excluded' : 'included';
    const inActive = entry[activeBucket].has(item);
    const inOther  = entry[otherBucket].has(item);
    if (inActive) {
      _setChipValue(entry, activeBucket, item, 'remove');
    } else if (inOther) {
      // Flip buckets. Any fromPreset flag in the "other" bucket stays —
      // becomes a tombstone there while main lives in the active bucket.
      _setChipValue(entry, otherBucket, item, 'remove');
      _setChipValue(entry, activeBucket, item, 'add', false);
    } else {
      // Fresh add — live only.
      _setChipValue(entry, activeBucket, item, 'add', false);
    }
    invalidateFilterCache();
    _syncChipModeButtons(dimKey);
    _syncLiveSlotFromActiveChips();
  } else {
    // Unreachable under normal UX — toggleTunePanel auto-activates the
    // preset before opening its tune panel. Guarded no-op to prevent the
    // previous silent-snapshot-mutation path.
    console.warn('[togglePoChip] called on inactive preset — no-op');
    return;
  }

  buildTunePanel(id);
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
  if (isActive) render();
}

function togglePoDimBody(id, dimKey) {
  const body = document.getElementById('pobody-'+id+'-'+dimKey);
  if (!body) return;
  const wasOpen = body.classList.contains('open');
  body.classList.toggle('open');
  const justClosed = wasOpen && !body.classList.contains('open');
  if (!justClosed) return;
  // When the user collapses an empty dim, drop any sticky click-mode feedback.
  const s = _tuneReadDim(id, dimKey);
  if (s.included.size === 0 && s.excluded.size === 0 && s.mode !== 'neutral') {
    if (appState.presets.activeId === id) {
      const entry = appState.filters.chips[dimKey];
      if (entry) entry.mode = 'neutral';
    } else if (_inactiveTuneMode[id]) {
      _inactiveTuneMode[id][dimKey] = 'neutral';
    }
    buildTunePanel(id);
  }
}

/** Normalize click-modes for the active preset's chip entries: drop sticky
 *  INCLUDE/EXCLUDE feedback if the corresponding Set is empty. Called when
 *  the tune panel is closed. For inactive presets, resets the transient
 *  click-mode map. Returns true if anything changed. */
function normalizePoModes(id) {
  const isActive = appState.presets.activeId === id;
  let changed = false;
  if (isActive) {
    SB_DIMS.forEach(dim => {
      const s = appState.filters.chips[dim.key];
      if (!s) return;
      let target = s.mode;
      if (s.included.size === 0 && s.excluded.size === 0)      target = 'neutral';
      else if (s.included.size > 0 && s.excluded.size === 0)   target = 'include';
      else if (s.included.size === 0 && s.excluded.size > 0)   target = 'exclude';
      if (target !== s.mode) { s.mode = target; changed = true; }
    });
  } else if (_inactiveTuneMode[id]) {
    delete _inactiveTuneMode[id];
    changed = true;
  }
  return changed;
}

/** ↺ Reset action. Active preset: drop live chips (keep preset-flagged). This
 *  reverts the preset to its saved snapshot. Inactive preset: wipe the snapshot
 *  entirely (legacy semantic — the preset returns to empty state). */
function resetTunePanel(id) {
  const isActive = appState.presets.activeId === id;
  if (isActive) {
    // Full revert to the snapshot: wipe every chip (preset + live) then
    // re-hydrate from presetSnapshots[id]. This matters when the user has
    // *removed* a preset chip via click — toggleFilter strips the fromPreset
    // flag, so "remove only live" would leave that chip gone. Hydrating
    // from the snapshot brings it back with its glow intact.
    _removeAllPresetChips();
    _removeAllLiveChips();
    _hydrateChipsFromSnapshot(presetSnapshots[id]);
    invalidateFilterCache();
    Object.keys(appState.filters.chips).forEach(key => _syncChipModeButtons(key));
    // Mirror the cleared live state into presetLiveFilters[activeId] so the
    // per-dim +N pills (tune panel + sidebar groups + custom fields) refresh
    // to zero. Without this, _getLiveCountForDim still reads stale entries.
    _syncLiveSlotFromActiveChips();
  } else {
    // Unreachable under normal UX — toggleTunePanel auto-activates the
    // preset before opening its tune panel. Guarded no-op to prevent the
    // previous destructive behavior (presetSnapshots[id] = _blankSnapshot()).
    console.warn('[resetTunePanel] called on inactive preset — no-op');
    return;
  }
  buildTunePanel(id);
  if (typeof refreshLiveFilterIndicator === 'function') refreshLiveFilterIndicator();
  if (isActive) render();
}

/** Update the "live filters" visual indicator on the active preset's sidebar
 *  row + mobile pill. Two changes:
 *   - `.has-live-filters` class on preset-row / mob-preset-pill → triggers halo CSS
 *   - `.preset-live-badge` span with `+N` count inside
 *  Both removed when count is 0 or no preset is active. Cheap to run on every
 *  chip mutation — only touches the DOM that needs it. */
function refreshLiveFilterIndicator() {
  // Phase 3 : halo + badge par preset, calculés individuellement depuis
  // presetLiveFilters[id]. L'actif reçoit son halo via la règle CSS
  // `.has-live-filters .preset-btn.active`, les non-actifs une variante
  // plus discrète via `.has-live-filters .preset-btn:not(.active)`.

  document.querySelectorAll('.preset-row').forEach(row => {
    const btn = row.querySelector('.preset-btn');
    const tuneBtn = row.querySelector('.preset-tune-btn');
    const id = btn ? parseInt(btn.dataset.preset, 10) : NaN;
    if (!Number.isFinite(id)) return;

    const addedN   = _getLiveFilterCountForPreset(id);
    const removedN = _getTombstoneCountForPreset(id);
    const shouldShow = addedN > 0 || removedN > 0;
    row.classList.toggle('has-live-filters', shouldShow);

    // Legacy placement: older DOM may still carry a badge directly under the
    // row (pre-refactor position). Strip it before re-rendering on the tune-btn.
    const stray = row.querySelector(':scope > .preset-live-badge, :scope > .preset-btn-wrap > .preset-live-badge');
    if (stray && (!tuneBtn || !tuneBtn.contains(stray))) stray.remove();

    if (!tuneBtn) return;
    const isOpen = tuneBtn.classList.contains('open');
    const isActivePreset = appState.presets.activeId === id;

    // ── Added badge (+N) — gold, existing ──
    let addedBadge = tuneBtn.querySelector('.preset-live-badge:not(.preset-live-badge-rm)');
    if (addedN > 0) {
      if (!addedBadge) {
        addedBadge = document.createElement('span');
        addedBadge.className = 'preset-live-badge';
        tuneBtn.appendChild(addedBadge);
      }
      addedBadge.classList.toggle('is-count', isOpen);
      addedBadge.classList.toggle('is-dot', !isOpen);
      addedBadge.textContent = isOpen ? '+' + addedN : '';
      addedBadge.title = '';
      addedBadge.dataset.presetId = String(id);
      addedBadge.onmouseenter = (ev) => {
        if (isActivePreset) {
          const html = _buildDivergenceTooltipHtml(id);
          if (html) showUtip(ev, html);
          else showUtipText(ev, `${addedN} unsaved live filter${addedN > 1 ? 's' : ''}`);
        } else {
          showUtipText(ev, `${addedN} unsaved live filter${addedN > 1 ? 's' : ''}`);
        }
      };
      addedBadge.onmousemove = (ev) => {
        if (isActivePreset) {
          const html = _buildDivergenceTooltipHtml(id);
          if (html) showUtip(ev, html);
        }
      };
      addedBadge.onmouseleave = () => hideUtip();
    } else if (addedBadge) {
      addedBadge.onmouseenter = addedBadge.onmouseleave = addedBadge.onmousemove = null;
      addedBadge.remove();
    }

    // ── Removed badge (−N) — red, new. Anchored just left of the +N when
    //    both are present (is-paired), or in the +N's slot when alone. ──
    let removedBadge = tuneBtn.querySelector('.preset-live-badge.preset-live-badge-rm');
    if (removedN > 0) {
      if (!removedBadge) {
        removedBadge = document.createElement('span');
        removedBadge.className = 'preset-live-badge preset-live-badge-rm';
        tuneBtn.appendChild(removedBadge);
      }
      removedBadge.classList.toggle('is-count', isOpen);
      removedBadge.classList.toggle('is-dot', !isOpen);
      removedBadge.classList.toggle('is-paired', addedN > 0);
      removedBadge.textContent = isOpen ? '−' + removedN : '';
      removedBadge.title = '';
      removedBadge.onmouseenter = (ev) => {
        showUtipText(ev, `${removedN} preset filter${removedN > 1 ? 's' : ''} disabled`);
      };
      removedBadge.onmouseleave = () => hideUtip();
    } else if (removedBadge) {
      removedBadge.onmouseenter = removedBadge.onmouseleave = null;
      removedBadge.remove();
    }
  });

  // Sidebar per-dim pills. For each native or custom .filter-group in the
  // sidebar, inject a small +N badge inside its .fg-label when the active
  // preset has live (unsaved) values on that dim. Supports native dims (
  // data-key = setup/session/…) and custom props (data-key = custom:<k>).
  const activeId = appState.presets?.activeId ?? null;
  document.querySelectorAll(
    '#filters-panel-dims .filter-group, #filters-custom-section .filter-group'
  ).forEach(group => {
    const modeBtn = group.querySelector('.chip-mode-btn[data-key]');
    const label = group.querySelector('.fg-label');
    if (!modeBtn || !label) return;
    const rawKey = modeBtn.dataset.key;
    const isCustom = rawKey.startsWith('custom:');
    const dimKey = isCustom ? rawKey.slice(7) : rawKey;

    // Two badges per dim: ADDED (chips not in snapshot) and REMOVED (chips
    // in snapshot but disabled — tombstones). Symmetric pills mirror the
    // shaded chip + the "+N" pattern the user already had.
    const addedN   = _getLiveCountForDim(activeId, dimKey, isCustom);
    const removedN = (activeId !== null) ? _getTombstoneCountForDim(dimKey, isCustom) : 0;

    let addedBadge   = label.querySelector('.live-dim-badge:not(.live-dim-badge-rm)');
    let removedBadge = label.querySelector('.live-dim-badge.live-dim-badge-rm');

    if (addedN > 0) {
      if (!addedBadge) {
        addedBadge = document.createElement('span');
        addedBadge.className = 'live-dim-badge';
        label.appendChild(addedBadge);
      }
      addedBadge.textContent = '+' + addedN;
      addedBadge.title = `${addedN} unsaved live filter${addedN > 1 ? 's' : ''} on this property`;
    } else if (addedBadge) {
      addedBadge.remove();
    }

    if (removedN > 0) {
      if (!removedBadge) {
        removedBadge = document.createElement('span');
        removedBadge.className = 'live-dim-badge live-dim-badge-rm';
        label.appendChild(removedBadge);
      }
      removedBadge.textContent = '−' + removedN;
      removedBadge.title = `${removedN} preset filter${removedN > 1 ? 's' : ''} disabled on this property`;
    } else if (removedBadge) {
      removedBadge.remove();
    }
  });

  // Mobile pills — même logique avec deux badges (added + removed).
  document.querySelectorAll('.mob-preset-pill').forEach(pill => {
    const raw = pill.dataset.preset;
    const id = raw === '' ? null : parseInt(raw, 10);
    const addedN   = _getLiveFilterCountForPreset(id);
    const removedN = (typeof id === 'number') ? _getTombstoneCountForPreset(id) : 0;
    const shouldShow = addedN > 0 || removedN > 0;
    pill.classList.toggle('has-live-filters', shouldShow);

    let addedBadge = pill.querySelector('.preset-live-badge:not(.preset-live-badge-rm)');
    if (addedN > 0) {
      if (!addedBadge) {
        addedBadge = document.createElement('span');
        addedBadge.className = 'preset-live-badge';
        addedBadge.title = 'Unsaved live filters on this preset';
        pill.appendChild(addedBadge);
      }
      addedBadge.textContent = '+' + addedN;
    } else if (addedBadge) {
      addedBadge.remove();
    }

    let removedBadge = pill.querySelector('.preset-live-badge.preset-live-badge-rm');
    if (removedN > 0) {
      if (!removedBadge) {
        removedBadge = document.createElement('span');
        removedBadge.className = 'preset-live-badge preset-live-badge-rm';
        removedBadge.title = 'Preset filters disabled';
        pill.appendChild(removedBadge);
      }
      // Mobile pills always render in count mode (no "is-dot" miniature),
      // so is-paired marker is enough for the CSS shift.
      removedBadge.classList.add('is-count');
      removedBadge.classList.toggle('is-paired', addedN > 0);
      removedBadge.textContent = '−' + removedN;
    } else if (removedBadge) {
      removedBadge.remove();
    }
  });
}

/** Count live entries for a single dim (native or custom) on a given preset.
 *  Used to paint the small per-dim pills inside the sidebar filter groups
 *  and the tune panel's `.po-dim-head` rows. Returns 0 when the preset has
 *  no live slot, or the dim has no entry, or the entry is empty. */
function _getLiveCountForDim(presetId, dimKey, isCustom) {
  const slot = presetLiveFilters[_liveKey(presetId)];
  if (!slot) return 0;
  const bucket = isCustom ? slot.customChips : slot.chips;
  const v = bucket && bucket[dimKey];
  if (!v) return 0;
  return (v.included?.length || 0) + (v.excluded?.length || 0);
}

/** Count tombstones on a dim — values that belong to the active preset's
 *  snapshot but have been stripped from the applied state. Symmetric counter
 *  to `_getLiveCountForDim`: that one counts ADDED filters, this counts
 *  REMOVED preset filters. Used by the sidebar's `.fg-label` and the tune
 *  panel's `.po-dim-label` to show a `−N` pill alongside the `+N` one when
 *  the user has disabled saved chips. */
function _getTombstoneCountForDim(dimKey, isCustom) {
  const bucket = isCustom ? appState.filters?.customChips : appState.filters?.chips;
  const entry = bucket?.[dimKey];
  if (!entry) return 0;
  if (typeof _ensureFromPresetSets === 'function') _ensureFromPresetSets(entry);
  let n = 0;
  if (entry.includedFromPreset) {
    for (const v of entry.includedFromPreset) {
      if (!entry.included?.has(v) && !entry.excluded?.has(v)) n++;
    }
  }
  if (entry.excludedFromPreset) {
    for (const v of entry.excludedFromPreset) {
      if (!entry.included?.has(v) && !entry.excluded?.has(v)) n++;
    }
  }
  return n;
}

/** Count live entries stored in the slot for a given preset id (or null).
 *  Includes chips (9 dims), customChips, and comboFilters. */
function _getLiveFilterCountForPreset(id) {
  const slot = presetLiveFilters[_liveKey(id)];
  if (!slot) return 0;
  let n = 0;
  for (const v of Object.values(slot.chips || {})) {
    n += (v.included?.length || 0) + (v.excluded?.length || 0);
  }
  for (const v of Object.values(slot.customChips || {})) {
    n += (v.included?.length || 0) + (v.excluded?.length || 0);
  }
  for (const v of Object.values(slot.comboFilters || {})) {
    n += (v.included?.length || 0) + (v.excluded?.length || 0);
  }
  return n;
}

/** Sum of tombstones across all dims for a preset. Only the ACTIVE preset
 *  can carry tombstones (they live in appState.filters.chips, not in the
 *  per-preset slot). Inactive presets always return 0. */
function _getTombstoneCountForPreset(id) {
  if (typeof id !== 'number') return 0;
  if (appState.presets?.activeId !== id) return 0;
  let n = 0;
  for (const dimKey of Object.keys(appState.filters?.chips || {})) {
    n += _getTombstoneCountForDim(dimKey, false);
  }
  for (const dimKey of Object.keys(appState.filters?.customChips || {})) {
    n += _getTombstoneCountForDim(dimKey, true);
  }
  return n;
}
// ══════════════════════════════════════════════════════
let currentView = 'main';
function switchView(v) {
  currentView = v;
  document.body.classList.toggle('share-view-active', v === 'share');

  const layout    = document.querySelector('.layout');
  const shareView = document.getElementById('share-view');

  // Tab active states: section tabs (Global Overview / Optimal RR / Partial
  // Planers) act as the "main view" — exactly one is active when v==='main',
  // reflecting appState.ui.activeSection. The Share tab is active in share
  // view. Notion Live is a background-refresh button that never activates.
  const sectionTabs = document.querySelectorAll('.view-tab[data-section]');
  if (v === 'main') {
    const activeSec = appState.ui.activeSection || 'global';
    sectionTabs.forEach(t => t.classList.toggle('active', t.dataset.section === activeSec));
  } else {
    sectionTabs.forEach(t => t.classList.remove('active'));
  }
  document.getElementById('tab-share')?.classList.toggle('active', v === 'share');

  if (v === 'share') {
    if (layout)    setVisible(layout, false);
    if (shareView) setVisible(shareView, true);
    initShareGridstack();
    renderShareView();
  } else {
    if (layout)    setVisible(layout, true);
    if (shareView) setVisible(shareView, false);
    if (v === 'main') render();
  }
}

// Live per-section layouts being edited. Drag/resize updates this object.
// Saving to a slot serializes this object. Loading a slot replaces it.
// Initialised after the layout consts are declared (see below SECTION_LAYOUTS).
let _liveSectionLayouts = null;

function setSection(section) {
  appState.ui.activeSection = section;

  // Persist choice — applied once the grid is ready (post-init) if it isn't yet.
  try { localStorage.setItem('dashboard_section', section); } catch(e) {}

  // If we're currently in the Share view, clicking a section tab should take
  // the user back to the main dashboard. switchView('main') also updates the
  // active-tab state and re-renders.
  if (currentView !== 'main') {
    switchView('main');
  } else {
    // Already in main view — just update which section tab is highlighted.
    document.querySelectorAll('.view-tab[data-section]').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.section === section);
    });
  }

  // Defer if grid isn't ready yet — initGridstack() will replay via _applySectionFilter.
  if (!_grid || !_gsReady) return;

  _applySectionFilter(section);

  // Lazy init for the Partial Optimizer when entering its section. The render
  // is also called from renderPanels() on every full render — this just
  // ensures the widget paints immediately on section entry.
  if (section === 'partials' && typeof _poRender === 'function') {
    requestAnimationFrame(() => _withWidgetScale('w-partial-optimizer', () => _poRender()));
  }
}

// Apply a section filter to the grid. Each section (Global Overview,
// Optimal RR Analysis, Partial Planers) uses fixed coordinates from the
// live section layouts. Widgets outside the active section are removed
// from the GridStack engine (their DOM is kept).
function _applySectionFilter(section, { skipSync = false } = {}) {
  if (!_grid) return;
  const gsContainer = document.getElementById('gs-container');
  if (!gsContainer) return;

  const layout = _liveSectionLayouts[section];
  if (!layout) return;

  const allItems = [...gsContainer.querySelectorAll('.grid-stack-item')];
  const itemSection = (item) =>
    item.querySelector('.gs-widget[data-section]')?.dataset.section || null;

  // ── Snapshot the outgoing section's grid state before touching anything ──
  // Skip when a fresh layout was just loaded into _liveSectionLayouts
  // (e.g. layoutLoadPreset) — syncing would overwrite the new data.
  if (!skipSync) _syncGridToLive();

  const visible = [];
  const hidden  = [];
  allItems.forEach(item => {
    const sec = itemSection(item);
    if (!sec) return;
    const id = item.getAttribute('gs-id');
    // User-hidden widgets are detached from the grid in *every* section so
    // they never reserve a grid slot. Treat them like cross-section items.
    if (id && _isWidgetHidden(id)) { hidden.push(item); return; }
    (sec === section ? visible : hidden).push(item);
  });

  // Enable float during the transition to prevent GridStack from
  // auto-compacting widgets while we remove/add between sections.
  _grid.float(true);
  _grid.batchUpdate();
  try {
    // Remove hidden items first (before adding visible) to avoid collisions.
    hidden.forEach(item => {
      if (item.gridstackNode) {
        _grid.removeWidget(item, false);
      }
      item.style.display = 'none';
    });

    // Re-add visible items that were removed in a prior filter pass.
    visible.forEach(item => {
      item.style.display = '';
      const id = item.getAttribute('gs-id');
      let d = layout[id];
      if (!d) {
        if (!String(id || '').startsWith('w-cust-')) return;
        // Custom widget with no layout entry — place it at the bottom of the grid.
        let maxY = 0;
        Object.values(layout).forEach(pos => {
          const bot = (pos.y || 0) + (pos.h || 0);
          if (bot > maxY) maxY = bot;
        });
        d = { x: 0, y: maxY, w: 6, h: 39, minW: 2, minH: 14 };
        layout[id] = d;
      }
      if (!item.gridstackNode) {
        item.setAttribute('gs-x', d.x);
        item.setAttribute('gs-y', d.y);
        item.setAttribute('gs-w', d.w);
        item.setAttribute('gs-h', d.h);
        _grid.makeWidget(item);
      }
    });

    // Apply exact fixed coordinates for every visible widget in this section.
    visible.forEach(item => {
      const id = item.getAttribute('gs-id');
      const d = layout[id];
      if (d) {
        if (String(id || '').startsWith('w-cust-')) {
          debugLog('[layout-restore] applying grid position for', id, d);
        }
        _grid.update(item, { x: d.x, y: d.y, w: d.w, h: d.h });
      }
    });
  } finally {
    _grid.commit();
  }
  // Restore float:false so normal drag/drop compacts as expected.
  _grid.float(false);

  requestAnimationFrame(() => requestAnimationFrame(() => {
    _applyAutoTypoScale();
    if (typeof _redrawAll === 'function') _redrawAll();
  }));
}

// ══════════════════════════════════════════════════════
// FILTER CONTEXT STRIP
// ══════════════════════════════════════════════════════
// Unified display: Context label + preset pill + BE-excluded tag + Show-all
// toggle + consolidated container (counter + active-filter chips). The
// chips reuse the .af-pill* class family verbatim — same shape, padding,
// colors, and include/exclude distinction as the previous Row 2 bar.
const CONTEXT_EXPANDED_LS_KEY = 'flipping_context_expanded';
let _contextStripExpanded = (() => {
  try { return localStorage.getItem(CONTEXT_EXPANDED_LS_KEY) === 'true'; }
  catch (e) { return false; }
})();

function updateContextStrip() {
  const strip = document.getElementById('filter-context-strip');
  if (!strip) return;
  strip.innerHTML = '<span class="fcs-label">Context</span>';

  const activePresetDef = typeof appState.presets.activeId === 'number'
    ? PRESETS.find(x => x.id === appState.presets.activeId)
    : null;

  // 1. Preset pill
  if (activePresetDef) {
    strip.insertAdjacentHTML('beforeend',
      `<span class="fcs-item fcs-preset">${_escapeHtml(activePresetDef.label)}</span>`);
  }

  // 3. Counter — always-visible peer sitting between the BE tag and the
  //    Show-all toggle. Never hidden by the toggle.
  const total    = appState.trades.items.length;
  const filtered = (typeof getFiltered === 'function') ? getFiltered().length : total;
  const excluded = total - filtered;
  const counter  = document.createElement('span');
  counter.className = 'fcs-item fcs-counter';
  counter.innerHTML = (excluded > 0)
    ? `<span class="fcs-counter-value">${total}</span>`
      + `<span class="fcs-counter-arrow">→</span>`
      + `<span class="fcs-counter-value">${filtered}</span>`
      + `<span class="fcs-counter-meta">−${excluded} exclus</span>`
    : `<span class="fcs-counter-value">${total}</span>`
      + `<span class="fcs-counter-meta">trades</span>`;
  strip.appendChild(counter);

  // 4. Show-all toggle button (visibility driven by .has-filters below)
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'fcs-expand-btn';
  btn.dataset.action = 'toggle-context-strip';
  strip.appendChild(btn);

  // 5. Consolidated container — chips only, toggled by .is-expanded
  const cons = document.createElement('span');
  cons.className = 'fcs-consolidated';
  cons.id = 'fcs-consolidated';
  strip.appendChild(cons);

  // 5a. Chip pills — identical styling to the former Row 2 bar (no `×`).
  const keyLabels = { setup:'Setup', session:'Session', day:'Day', pair:'Pair', obstacles:'M15 Obs', h4obs:'H4 Obs', tradeType:'Type', beManagement:'BE Mgmt', hour:'Hour', badFeeling:'Bad Feeling' };
  const keyVariants = {
    setup: 'af-pill-setup',
    session: 'af-pill-session',
    day: 'af-pill-day',
    pair: 'af-pill-pair',
    obstacles: 'af-pill-obstacles',
    h4obs: 'af-pill-h4obs',
    tradeType: 'af-pill-tradeType',
    beManagement: 'af-pill-bemgmt',
    badFeeling: 'af-pill-badfeeling',
  };
  const presetBadge = '<span class="af-pill-badge-preset" title="From active preset">P</span>';
  const lbl = (txt) => `<span class="af-pill-label">${_escapeHtml(txt)}</span> `;

  let chipCount = 0;
  const mkChip = (base, key, val, fromPreset, mode, human) => {
    const sign = mode === 'included' ? '+' : '−';
    const pill = document.createElement('div');
    pill.className = base + (mode === 'included' ? ' af-pill-inc' : ' af-pill-exc') + (fromPreset ? ' af-pill-from-preset' : '');
    pill.tabIndex = 0;
    pill.dataset.action = 'remove-active-filter';
    pill.dataset.key = key;
    pill.dataset.val = val;
    pill.title = 'Click to remove this filter';
    pill.innerHTML = lbl(human) + sign + _escapeHtml(String(val)) + (fromPreset ? ' ' + presetBadge : '');
    cons.appendChild(pill);
    chipCount++;
  };

  // Native chips
  Object.entries(appState.filters.chips).forEach(([key, entry]) => {
    _ensureFromPresetSets(entry);
    const base = `af-pill ${keyVariants[key] || ''}`.trim();
    const human = keyLabels[key] || key;
    entry.included.forEach(v => mkChip(base, key, v, entry.includedFromPreset.has(v), 'included', human));
    entry.excluded.forEach(v => mkChip(base, key, v, entry.excludedFromPreset.has(v), 'excluded', human));
  });

  // Custom chips
  const customProps = (typeof loadCustomProps === 'function') ? loadCustomProps() : [];
  const propByKey = Object.create(null);
  for (const cp of customProps) propByKey[cp.key] = cp;
  Object.entries(appState.filters.customChips || {}).forEach(([key, entry]) => {
    if (!entry || (!entry.included?.size && !entry.excluded?.size)) return;
    _ensureFromPresetSets(entry);
    const human = propByKey[key]?.name || key;
    const filterKey = 'custom:' + key;
    const base = 'af-pill af-pill-custom';
    entry.included.forEach(v => mkChip(base, filterKey, v, entry.includedFromPreset.has(v), 'included', human));
    entry.excluded.forEach(v => mkChip(base, filterKey, v, entry.excludedFromPreset.has(v), 'excluded', human));
  });

  // Combo filters (heatmap cells)
  const comboLabelMap = {
    sessionDay:  { label: 'Sess × Day',  fmt: k => { const [s, d] = k.split('|'); return `${SESSION_SHORT[s]||s} × ${DAY_EN[d]||d}`; } },
    pairSession: { label: 'Pair × Sess', fmt: k => { const [p, s] = k.split('|'); return `${p} × ${SESSION_SHORT[s]||s}`; } },
  };
  Object.entries(appState.filters.comboFilters || {}).forEach(([ck, entry]) => {
    const meta = comboLabelMap[ck];
    if (!meta) return;
    const make = (val, mode) => {
      const sign = mode === 'included' ? '+' : '−';
      const pill = document.createElement('div');
      pill.className = 'af-pill' + (mode === 'included' ? ' af-pill-inc' : ' af-pill-exc');
      pill.tabIndex = 0;
      pill.dataset.action = 'remove-combo-filter';
      pill.dataset.combo = ck;
      pill.dataset.val = val;
      pill.title = 'Click to remove this filter';
      pill.innerHTML = lbl(meta.label) + sign + _escapeHtml(meta.fmt(val));
      cons.appendChild(pill);
      chipCount++;
    };
    entry.included.forEach(v => make(v, 'included'));
    entry.excluded.forEach(v => make(v, 'excluded'));
  });

  // 5. Flags driving toggle visibility and wrap behavior.
  if (chipCount > 0) strip.classList.add('has-filters');
  else strip.classList.remove('has-filters');
  strip.classList.toggle('is-expanded', _contextStripExpanded);

  _syncContextStripBtnLabel(strip);
}

function _toggleContextStrip() {
  _contextStripExpanded = !_contextStripExpanded;
  try { localStorage.setItem(CONTEXT_EXPANDED_LS_KEY, String(_contextStripExpanded)); } catch (e) {}
  const strip = document.getElementById('filter-context-strip');
  if (!strip) return;
  strip.classList.toggle('is-expanded', _contextStripExpanded);
  _syncContextStripBtnLabel(strip);
  // Let layout settle, then update the sticky offset var so view-tabs sit
  // below the newly wrapped strip.
  requestAnimationFrame(_syncContextHeightVar);
}

// Keep --context-h in sync with the actual strip height (it grows when the
// user expands, and also when the browser wraps the single-row layout into
// multiple rows because many filters are active). view-tabs' sticky top
// reads this var, so recomputing it keeps the tabs under the strip.
function _syncContextHeightVar() {
  const strip = document.getElementById('filter-context-strip');
  if (!strip) return;
  // Avoid feedback loop: when collapsed, the strip's own height is
  // driven by --context-h, so measuring it and writing it back would
  // freeze whatever value was last set (including a previous expanded
  // height). Temporarily clear the inline var, measure the natural
  // collapsed height, then write it back.
  const expanded = strip.classList.contains('is-expanded');
  if (!expanded) {
    document.documentElement.style.removeProperty('--context-h');
  }
  const h = strip.getBoundingClientRect().height;
  document.documentElement.style.setProperty('--context-h', h + 'px');
}

function _installContextStripObserver() {
  const strip = document.getElementById('filter-context-strip');
  if (!strip || window._contextStripRO) return;
  window._contextStripRO = new ResizeObserver(() => _syncContextHeightVar());
  window._contextStripRO.observe(strip);
  _syncContextHeightVar();
}
function _syncContextStripBtnLabel(strip) {
  const btn = strip.querySelector('.fcs-expand-btn');
  if (!btn) return;
  const expanded = strip.classList.contains('is-expanded');
  btn.innerHTML = expanded ? '⌃ Hide' : '⌄ Show all';
  btn.title = expanded ? 'Hide active filters' : 'Show active filters';
}



// ════════════════════════════════════════════════════════
//  LAYOUT MANAGER  —  Gridstack-based drag/resize/presets
