// Custom layout slots: max 4 user-saved layouts, stored in localStorage
const LS_KEY_SLOTS       = 'gs_custom_slots';
const LAYOUT_SLOTS_MAX   = 4;

// ──────────────────────────────────────────────────────────────
// HIDDEN WIDGETS — global list (NOT per-preset). When a widget is
// hidden, it's detached from GridStack via removeWidget(item, false)
// (DOM preserved, no grid hole) and tagged with display:none. Last-
// known {w,h} is stored so unhide can re-add it at its previous size
// at the bottom row of the active section's grid. Persisted in
// localStorage so the hide state survives reload + preset switches.
// Reset (↺) does NOT clear this list — that's intentional per spec.
// ──────────────────────────────────────────────────────────────
const LS_KEY_HIDDEN = 'gs_hidden_widgets';
let _hiddenWidgets = {};

function _loadHiddenWidgets() {
  try {
    const raw = localStorage.getItem(_htfKey(LS_KEY_HIDDEN));
    const obj = raw ? JSON.parse(raw) : {};
    _hiddenWidgets = (obj && typeof obj === 'object' && !Array.isArray(obj)) ? obj : {};
  } catch { _hiddenWidgets = {}; }
}

function _saveHiddenWidgets() {
  try { localStorage.setItem(_htfKey(LS_KEY_HIDDEN), JSON.stringify(_hiddenWidgets)); } catch {}
}

function _isWidgetHidden(id) {
  return !!(id && _hiddenWidgets && _hiddenWidgets[id]);
}

// Detach a widget from the GridStack while preserving its DOM node + gs-id.
// We snapshot its current size into _hiddenWidgets[id] so unhide knows what
// dimensions to restore. Works whether the widget is in the active section
// (live gridstackNode) or in a parked section (display:none + no node).
function _hideWidget(id) {
  if (!_grid || !id || _isWidgetHidden(id)) return;
  const item = document.querySelector(`#gs-container .grid-stack-item[gs-id="${id}"]`);
  if (!item) return;

  const n = item.gridstackNode;
  let w, h;
  if (n) {
    w = n.w; h = n.h;
  } else {
    const sec = item.querySelector('.gs-widget[data-section]')?.dataset.section;
    const layoutEntry = sec && _liveSectionLayouts[sec] ? _liveSectionLayouts[sec][id] : null;
    w = layoutEntry?.w || 6;
    h = layoutEntry?.h || 20;
  }
  _hiddenWidgets[id] = { w, h };
  _saveHiddenWidgets();

  if (n) _grid.removeWidget(item, false);
  item.style.display = 'none';

  if (typeof _renderHidePopoverList === 'function') _renderHidePopoverList();
  requestAnimationFrame(() => { if (typeof _redrawAll === 'function') _redrawAll(); });
}

// Re-attach a previously hidden widget at the bottom of its section's grid.
// If the widget belongs to the active section, we make + update it live.
// Otherwise we update _liveSectionLayouts[sec] with a bottom position so
// the widget reappears at the bottom the next time the user navigates back.
function _unhideWidget(id) {
  if (!_grid || !id || !_isWidgetHidden(id)) return;
  const item = document.querySelector(`#gs-container .grid-stack-item[gs-id="${id}"]`);
  const stored = _hiddenWidgets[id] || { w: 6, h: 20 };
  delete _hiddenWidgets[id];
  _saveHiddenWidgets();
  if (!item) {
    if (typeof _renderHidePopoverList === 'function') _renderHidePopoverList();
    return;
  }

  const sec = item.querySelector('.gs-widget[data-section]')?.dataset.section;
  const activeSec = appState?.ui?.activeSection || 'global';

  // Compute the bottom row of the *target* section. For the active section
  // we read live gridstack nodes (which reflect any drag/resize since load).
  // For non-active sections we read _liveSectionLayouts[sec] (the persisted
  // positions, since those widgets aren't in the live grid right now).
  let maxBottom = 0;
  if (sec === activeSec && _grid) {
    _grid.getGridItems().forEach(it => {
      const node = it.gridstackNode;
      if (!node) return;
      const bottom = (node.y || 0) + (node.h || 0);
      if (bottom > maxBottom) maxBottom = bottom;
    });
  } else if (sec && _liveSectionLayouts[sec]) {
    Object.entries(_liveSectionLayouts[sec]).forEach(([wid, d]) => {
      if (wid === id || _isWidgetHidden(wid)) return;
      const bottom = (d.y || 0) + (d.h || 0);
      if (bottom > maxBottom) maxBottom = bottom;
    });
  }

  if (sec === activeSec) {
    // Live re-attach. Float ON during the operation so GridStack respects the
    // exact bottom-row coordinates (otherwise float:false would compact upward).
    item.style.display = '';
    item.setAttribute('gs-x', 0);
    item.setAttribute('gs-y', maxBottom);
    item.setAttribute('gs-w', stored.w);
    item.setAttribute('gs-h', stored.h);
    _grid.float(true);
    _grid.batchUpdate();
    try {
      if (!item.gridstackNode) _grid.makeWidget(item);
      _grid.update(item, { x: 0, y: maxBottom, w: stored.w, h: stored.h });
    } finally {
      _grid.commit();
    }
    _grid.float(false);
  }

  // Mirror the new position into _liveSectionLayouts so it persists across
  // section switches + autosaves (active slot + named preset).
  if (sec && _liveSectionLayouts[sec]) {
    const cur = _liveSectionLayouts[sec][id] || {};
    _liveSectionLayouts[sec][id] = {
      ...cur,
      x: 0, y: maxBottom, w: stored.w, h: stored.h,
      minW: cur.minW || 3, minH: cur.minH || 10,
    };
  }
  if (typeof _saveActiveSlotLive === 'function') _saveActiveSlotLive();

  if (typeof _renderHidePopoverList === 'function') _renderHidePopoverList();
  requestAnimationFrame(() => { if (typeof _redrawAll === 'function') _redrawAll(); });
}

function _toggleHideWidget(id) {
  if (_isWidgetHidden(id)) _unhideWidget(id);
  else _hideWidget(id);
}

// Scroll the dashboard to a widget. If the widget belongs to a non-active
// section, switch to that section first then scroll. The popover and the
// layout-edit mode are intentionally left open — the user can keep managing
// visibility / editing the layout right after locating a widget. No-op when
// the widget is currently hidden (locate button is disabled in that case).
function _locateWidget(id) {
  if (!id || _isWidgetHidden(id)) return;
  const item = document.querySelector(`#gs-container .grid-stack-item[gs-id="${id}"]`);
  if (!item) return;
  const sec = item.querySelector('.gs-widget[data-section]')?.dataset.section;
  const activeSec = appState?.ui?.activeSection || 'global';

  const doScroll = () => {
    const target = document.querySelector(`#gs-container .grid-stack-item[gs-id="${id}"]`);
    if (!target) return;
    target.scrollIntoView({ block: 'center', behavior: 'smooth' });
    // Brief flash so the user can spot it after the scroll lands.
    target.classList.add('gs-locate-flash');
    setTimeout(() => target.classList.remove('gs-locate-flash'), 1400);
  };

  if (sec && sec !== activeSec && typeof setSection === 'function') {
    setSection(sec);
    // Wait two frames for the section filter + grid update to settle.
    requestAnimationFrame(() => requestAnimationFrame(doScroll));
  } else {
    doScroll();
  }
}

function _unhideAllWidgets() {
  const ids = Object.keys(_hiddenWidgets || {});
  if (!ids.length) return;
  ids.forEach(id => _unhideWidget(id));
}

// Visual-only counterpart for profile/HTF switching. Resets display:'' on
// every currently-hidden grid item so _applySectionFilter can re-evaluate
// visibility against the NEW scope's _hiddenWidgets (which the caller is
// about to load). Does NOT call _unhideWidget per id because that path
// invokes _saveHiddenWidgets / _saveActiveSlotLive, which would clobber the
// new scope's persisted state. Use _unhideAllWidgets for user-driven
// "Show all" actions; use this helper for cross-scope resets.
function _visuallyUnhideAllWidgets() {
  if (!_grid) return;
  const container = document.getElementById('gs-container');
  if (!container) return;
  container.querySelectorAll('.grid-stack-item').forEach(item => {
    if (item.style.display === 'none') item.style.display = '';
  });
}

// ── Hide popover (anchored below the toolbar Hide button) ──
function _toggleHidePopover() {
  const existing = document.getElementById('layout-hide-popover');
  if (existing) {
    existing.remove();
    document.removeEventListener('click', _onHidePopoverOutsideClick, true);
    return;
  }
  const anchor = document.querySelector('[data-action="layout-hide-toggle"]');
  if (!anchor) return;
  const pop = document.createElement('div');
  pop.id = 'layout-hide-popover';
  pop.className = 'layout-hide-popover';
  document.body.appendChild(pop);
  _renderHidePopoverList();
  _positionHidePopover(pop, anchor);
  setTimeout(() => document.addEventListener('click', _onHidePopoverOutsideClick, true), 0);
}

function _positionHidePopover(pop, anchor) {
  const r = anchor.getBoundingClientRect();
  pop.style.position = 'fixed';
  pop.style.top   = `${Math.round(r.bottom + 6)}px`;
  pop.style.right = `${Math.round(window.innerWidth - r.right)}px`;
}

function _onHidePopoverOutsideClick(e) {
  const pop = document.getElementById('layout-hide-popover');
  if (!pop) {
    document.removeEventListener('click', _onHidePopoverOutsideClick, true);
    return;
  }
  if (pop.contains(e.target)) return;
  if (e.target.closest && e.target.closest('[data-action="layout-hide-toggle"]')) return;
  pop.remove();
  document.removeEventListener('click', _onHidePopoverOutsideClick, true);
}

// Widget ids that the active profile's template considers fully excluded —
// not "hidden by default with an unhide path", but conceptually nonexistent.
// Derived from TEMPLATE_LAYOUTS[choice].hiddenWidgets: those entries do
// double duty as both "hide on creation" (read by _applyTemplateLayoutsForProfile
// to seed gs_hidden_widgets_<id>) AND "filter out of every widget-picker UI"
// (read here). The two consumers below — _collectAllManagedWidgets (hide
// popover) and _msGetSectionWidgetIds (mini-sidebar parking) — skip these
// ids so the user can't accidentally bring an excluded widget back. Empty
// set when there's no active profile or templateChoice='m15' (M15 keeps
// every widget visible by default).
function _getTemplateExcludedWidgetIds() {
  try {
    const profile = (typeof getActiveJournalProfile === 'function') ? getActiveJournalProfile() : null;
    const choice = profile?.templateChoice;
    const tpl = (typeof TEMPLATE_LAYOUTS !== 'undefined') ? TEMPLATE_LAYOUTS[choice] : null;
    return new Set(Object.keys(tpl?.hiddenWidgets || {}));
  } catch { return new Set(); }
}

// Collect every managed widget across all 3 sections — id, label (from the
// .cc-title text), the section it belongs to, and its (x, y) layout coords
// (used to sort the popover in dashboard reading order). Used by the popover.
// Template-excluded widgets (per _getTemplateExcludedWidgetIds) are skipped
// so the unhide popover never lists them on profiles whose template treats
// the widget as nonexistent (e.g. w-m15 on an H4 profile).
function _collectAllManagedWidgets() {
  const out = [];
  const excluded = _getTemplateExcludedWidgetIds();
  document.querySelectorAll('#gs-container .grid-stack-item').forEach(item => {
    const id = item.getAttribute('gs-id');
    if (!id || excluded.has(id)) return;
    const widgetEl = item.querySelector('.gs-widget[data-section]');
    const section  = widgetEl?.dataset.section || '—';
    const titleEl  = item.querySelector('.cc-title');
    const label    = (titleEl ? titleEl.textContent : id).trim() || id;

    // Layout coords: prefer the live gridstackNode (active section, reflects
    // the latest drag/resize). Fall back to _liveSectionLayouts for widgets
    // in non-active sections OR hidden widgets — both have a node = null but
    // their last-known position is preserved in the section layout map.
    // Unknown coords sink to the bottom of the sort.
    let x, y;
    const node = item.gridstackNode;
    if (node) {
      x = node.x; y = node.y;
    } else {
      const stored = _liveSectionLayouts?.[section]?.[id];
      if (stored && Number.isFinite(stored.x) && Number.isFinite(stored.y)) {
        x = stored.x; y = stored.y;
      } else {
        x = Number.POSITIVE_INFINITY; y = Number.POSITIVE_INFINITY;
      }
    }

    out.push({ id, label, section, x, y });
  });
  return out;
}

const _SECTION_LABEL_MAP = {
  'global':     'Global',
  'optimal-rr': 'Optimal RR',
  'partials':   'Partials',
};

// Section ordering matches the on-screen tab order: Global → Optimal RR →
// Partials. Used to group the popover so widgets show up in the same vertical
// order as the dashboard reads them.
const _SECTION_ORDER = { 'global': 0, 'optimal-rr': 1, 'partials': 2 };

// Comparator: dashboard reading order — section first, then top-to-bottom,
// then left-to-right within the same row.
function _layoutOrderCmp(a, b) {
  const sa = _SECTION_ORDER[a.section] ?? 99;
  const sb = _SECTION_ORDER[b.section] ?? 99;
  if (sa !== sb) return sa - sb;
  if (a.y !== b.y) return a.y - b.y;
  return a.x - b.x;
}

function _renderHidePopoverList() {
  const pop = document.getElementById('layout-hide-popover');
  if (!pop) return;
  const items = _collectAllManagedWidgets();
  // Split into hidden + visible groups. Hidden FIRST so the popover surfaces
  // what's currently in the abnormal state. Within each group, sort by
  // dashboard reading order (section → top-to-bottom → left-to-right) so the
  // popover mirrors how the user scans the live dashboard.
  const hiddenItems  = items.filter(x =>  _isWidgetHidden(x.id)).sort(_layoutOrderCmp);
  const visibleItems = items.filter(x => !_isWidgetHidden(x.id)).sort(_layoutOrderCmp);
  const total  = items.length;
  const nHidden = hiddenItems.length;

  const rowHTML = it => {
    const isHidden = _isWidgetHidden(it.id);
    const sectLabel = _SECTION_LABEL_MAP[it.section] || it.section;
    const id = _escapeAttr(it.id);
    // Two-part row:
    //   • Checkbox (in its own <label>) toggles visibility — the only way to hide/show
    //   • Locate button scrolls the dashboard to the widget (no toggle on text)
    // For hidden widgets the locate button is disabled — the widget isn't
    // visible in the grid so there's nothing to scroll to.
    const locateTitle = isHidden ? 'Show this widget first to locate it' : 'Scroll to this widget on the dashboard';
    const toggleTitle = isHidden ? 'Click to show this widget' : 'Click to hide this widget';
    return `
      <div class="lhp-row${isHidden ? ' lhp-row-is-hidden' : ''}">
        <label class="lhp-row-toggle" title="${toggleTitle}">
          <input type="checkbox" data-action="layout-hide-toggle-row" data-gs-id="${id}" ${isHidden ? '' : 'checked'} />
          <span class="lhp-row-check" aria-hidden="true"></span>
        </label>
        <button type="button" class="lhp-row-locate" data-action="layout-locate-widget" data-gs-id="${id}" ${isHidden ? 'disabled' : ''} title="${locateTitle}">
          <span class="lhp-row-label">${_escapeHtml(it.label)}</span>
          <span class="lhp-row-section">${_escapeHtml(sectLabel)}</span>
        </button>
      </div>
    `;
  };

  let body = '';
  if (nHidden) {
    body += `<div class="lhp-section-header lhp-section-hidden">Hidden · ${nHidden}</div>`;
    body += hiddenItems.map(rowHTML).join('');
  }
  if (visibleItems.length) {
    body += `<div class="lhp-section-header lhp-section-visible">Visible · ${visibleItems.length}</div>`;
    body += visibleItems.map(rowHTML).join('');
  }
  if (!body) body = '<div class="lhp-empty">No widgets</div>';

  pop.innerHTML = `
    <div class="lhp-head">
      <span class="lhp-title">Manage widget visibility</span>
      <span class="lhp-count">${total - nHidden}/${total} shown</span>
    </div>
    <div class="lhp-body">${body}</div>
    <div class="lhp-foot">
      <button class="lhp-foot-btn" data-action="layout-hide-show-all" ${nHidden ? '' : 'disabled'}>Show all</button>
    </div>
  `;
}

// ── Per-widget hide confirmation popup (anchored to the eye-off button) ──
// Positioning model: position: absolute with document coordinates so the
// popup scrolls naturally with the widget (no listener needed). The popup's
// stacking-context z-index is intentionally LOWER than the sticky header
// (.view-tabs at 1000, #filter-context-strip at 1001, .topbar at 1002 in
// edit mode — see dashboard.css:1041-1043), so when the widget scrolls
// upward the popup slides UNDER the header instead of overlapping it.
function _openHideConfirm(id, anchorEl) {
  if (!id) return;
  _closeDeleteConfirm();
  _closeHideConfirm();
  if (!anchorEl) return;
  const pop = document.createElement('div');
  pop.id = 'gs-hide-confirm-popup';
  pop.className = 'gs-hide-confirm-popup';
  pop.innerHTML = `
    <div class="gs-hide-confirm-msg">Hide this widget?</div>
    <div class="gs-hide-confirm-actions">
      <button class="gs-hide-confirm-btn gs-hide-confirm-cancel" data-action="layout-hide-cancel">Cancel</button>
      <button class="gs-hide-confirm-btn gs-hide-confirm-ok" data-action="layout-hide-confirm" data-gs-id="${_escapeAttr(id)}">Hide</button>
    </div>
  `;
  document.body.appendChild(pop);
  _positionWidgetConfirmPopup(anchorEl, pop, 6);

  setTimeout(() => document.addEventListener('click', _onHideConfirmOutsideClick, true), 0);
}

function _closeHideConfirm() {
  const pop = document.getElementById('gs-hide-confirm-popup');
  if (pop) pop.remove();
  document.removeEventListener('click', _onHideConfirmOutsideClick, true);
}

function _onHideConfirmOutsideClick(e) {
  const pop = document.getElementById('gs-hide-confirm-popup');
  if (!pop) { document.removeEventListener('click', _onHideConfirmOutsideClick, true); return; }
  if (pop.contains(e.target)) return;
  if (e.target.closest && e.target.closest('[data-action="layout-hide-widget-confirm"]')) return;
  _closeHideConfirm();
}

function _openDeleteConfirm(cwId, anchorEl) {
  if (!cwId) return;
  _closeHideConfirm();
  _closeDeleteConfirm();
  if (!anchorEl) return;
  const pop = document.createElement('div');
  pop.id = 'gs-delete-confirm-popup';
  pop.className = 'gs-hide-confirm-popup gs-delete-confirm-popup';
  pop.innerHTML = `
    <div class="gs-hide-confirm-msg">Delete widget?</div>
    <div class="gs-hide-confirm-actions">
      <button class="gs-hide-confirm-btn gs-hide-confirm-cancel" data-action="layout-delete-cancel">Cancel</button>
      <button class="gs-hide-confirm-btn gs-hide-confirm-ok gs-delete-confirm-ok" data-action="layout-delete-confirm" data-cw-id="${_escapeAttr(cwId)}">Delete widget</button>
    </div>
  `;
  document.body.appendChild(pop);
  _positionWidgetConfirmPopup(anchorEl, pop, 6);

  setTimeout(() => document.addEventListener('click', _onDeleteConfirmOutsideClick, true), 0);
}

function _closeDeleteConfirm() {
  const pop = document.getElementById('gs-delete-confirm-popup');
  if (pop) pop.remove();
  document.removeEventListener('click', _onDeleteConfirmOutsideClick, true);
}

function _onDeleteConfirmOutsideClick(e) {
  const pop = document.getElementById('gs-delete-confirm-popup');
  if (!pop) { document.removeEventListener('click', _onDeleteConfirmOutsideClick, true); return; }
  if (pop.contains(e.target)) return;
  if (e.target.closest && e.target.closest('[data-action="layout-delete-widget-confirm"]')) return;
  _closeDeleteConfirm();
}

// ── Re-apply template defaults → "Resync needed" inline confirm ────────────
// Surfaces under the #ljp-reset-btn when _reapplyTemplateMapping aborts
// because raw cache is empty (post-refresh, no sync) or partial (post-
// refresh + incremental sync only). Clicking Yes fires a Full resync on
// the active profile; user re-clicks Re-apply after the sync completes.
// Reuses .gs-hide-confirm-popup styling so the DA stays coherent.
function _openReapplyResyncConfirm() {
  const anchorEl = document.getElementById('ljp-reset-btn');
  if (!anchorEl) return;
  _closeReapplyResyncConfirm();
  const pop = document.createElement('div');
  pop.id = 'ds-reapply-resync-popup';
  pop.className = 'gs-hide-confirm-popup ds-reapply-resync-popup';
  pop.innerHTML = `
    <div class="ds-reapply-resync-title">Resync needed</div>
    <div class="ds-reapply-resync-row">
      <span class="ds-reapply-resync-prompt">Resync ?</span>
      <div class="gs-hide-confirm-actions">
        <button class="gs-hide-confirm-btn gs-hide-confirm-cancel" data-action="reapply-resync-cancel" type="button">No</button>
        <button class="gs-hide-confirm-btn gs-hide-confirm-ok ds-reapply-resync-ok" data-action="reapply-resync-confirm" type="button">Yes</button>
      </div>
    </div>
  `;
  document.body.appendChild(pop);
  // Position directly below the Reapply button (or above if no room).
  const a = anchorEl.getBoundingClientRect();
  const p = pop.getBoundingClientRect();
  const sx = window.scrollX || window.pageXOffset || 0;
  const sy = window.scrollY || window.pageYOffset || 0;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const margin = 8, gap = 6;
  const canBelow = a.bottom + gap + p.height <= vh - margin;
  let top = canBelow ? a.bottom + gap : a.top - p.height - gap;
  let left = a.left;
  left = Math.min(Math.max(margin, left), vw - p.width - margin);
  top  = Math.min(Math.max(margin, top),  vh - p.height - margin);
  pop.style.position = 'absolute';
  pop.style.left = `${Math.round(left + sx)}px`;
  pop.style.top  = `${Math.round(top  + sy)}px`;
  setTimeout(() => document.addEventListener('click', _onReapplyResyncOutsideClick, true), 0);
}

function _closeReapplyResyncConfirm() {
  const pop = document.getElementById('ds-reapply-resync-popup');
  if (pop) pop.remove();
  document.removeEventListener('click', _onReapplyResyncOutsideClick, true);
}

function _onReapplyResyncOutsideClick(e) {
  const pop = document.getElementById('ds-reapply-resync-popup');
  if (!pop) { document.removeEventListener('click', _onReapplyResyncOutsideClick, true); return; }
  if (pop.contains(e.target)) return;
  if (e.target.closest && e.target.closest('[data-action="reapply-template-defaults"]')) return;
  _closeReapplyResyncConfirm();
}

// ──────────────────────────────────────────────────────────────────────────
// JOURNAL-PROFILE DELETE CONFIRM — inline "Sure? Yes No" in place of the
// Delete source menu item. Mirrors the _npPendingDeleteId pattern used for
// Notion custom property delete — no detached popover, no z-index dance
// with the Data Setup panel. The menu row simply morphs.
// ──────────────────────────────────────────────────────────────────────────
function _armJournalProfileDelete(id) {
  if (!id) return;
  // Toggle: clicking Delete source again on the already-armed row disarms.
  _journalProfileRowDeleteArmedId = (_journalProfileRowDeleteArmedId === id) ? '' : id;
  _syncJournalProfileUI();
}

function _disarmJournalProfileDelete() {
  if (!_journalProfileRowDeleteArmedId) return;
  _journalProfileRowDeleteArmedId = '';
  _syncJournalProfileUI();
}

// Outside-click disarm — any mousedown that isn't on the armed row or the
// trigger button clears the armed state. Capture phase so it fires before
// other handlers might re-render and lose the target ref.
document.addEventListener('mousedown', e => {
  if (!_journalProfileRowDeleteArmedId) return;
  if (e.target.closest && e.target.closest('.jp-del-armed')) return;
  if (e.target.closest && e.target.closest('[data-action="journal-profile-row-delete"]')) return;
  _disarmJournalProfileDelete();
});

function _positionWidgetConfirmPopup(anchorEl, pop, gap = 6) {
  if (!anchorEl || !pop) return;
  const anchorRect = anchorEl.getBoundingClientRect();
  const popupRect = pop.getBoundingClientRect();
  const sx = window.scrollX || window.pageXOffset || 0;
  const sy = window.scrollY || window.pageYOffset || 0;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const margin = 8;

  const canPlaceRight = anchorRect.right + gap + popupRect.width <= vw - margin;
  const canPlaceBelow = anchorRect.bottom + gap + popupRect.height <= vh - margin;

  let left = canPlaceRight
    ? anchorRect.right + gap
    : anchorRect.left - popupRect.width - gap;
  let top = canPlaceBelow
    ? anchorRect.bottom + gap
    : anchorRect.top - popupRect.height - gap;

  left = Math.min(Math.max(margin, left), vw - popupRect.width - margin);
  top = Math.min(Math.max(margin, top), vh - popupRect.height - margin);

  pop.style.position = 'absolute';
  pop.style.left = `${Math.round(left + sx)}px`;
  pop.style.top = `${Math.round(top + sy)}px`;
}

// ──────────────────────────────────────────────────────────────────────────
// MAGNETIC SNAP — works on any GridStack instance (main grid + mini grid).
// After a drag/resize ends, scan side-by-side neighbours (touching x edges
// with y-overlap) and if either of their top/bottom edges is within the
// threshold, jump to align exactly. Keeps adjacent widgets visually crisp
// without forcing the user to land them pixel-perfect.
// Threshold = 2 grid units; on the live dashboard (cellHeight 10px) that's
// 20px, on the mini (cellHeight 2px) it's 4px. Tight enough that a user who
// genuinely wants a slight height offset can keep it (≥ 3 units), loose
// enough that a near-miss aligns automatically.
// ──────────────────────────────────────────────────────────────────────────
const _MAGNET_SNAP_THRESHOLD = 2;

function _applyMagnetSnap(grid, item) {
  if (!grid || !item || !item.gridstackNode) return;
  const me = item.gridstackNode;
  const others = grid.getGridItems().filter(it => it !== item && it.gridstackNode);

  let bestTop = null;     // { delta, target }
  let bestBottom = null;

  for (const other of others) {
    const o = other.gridstackNode;
    // Side-by-side: x edges touch
    const touchesRight = (me.x + me.w) === o.x;
    const touchesLeft  = (o.x + o.w) === me.x;
    if (!touchesRight && !touchesLeft) continue;
    // Need actual y overlap (not just touching)
    const yOverlap = Math.min(me.y + me.h, o.y + o.h) - Math.max(me.y, o.y);
    if (yOverlap <= 0) continue;

    // Top edge candidate
    const dyTop = o.y - me.y;
    if (dyTop !== 0 && Math.abs(dyTop) <= _MAGNET_SNAP_THRESHOLD) {
      if (!bestTop || Math.abs(dyTop) < Math.abs(bestTop.delta)) {
        bestTop = { delta: dyTop, target: o.y };
      }
    }
    // Bottom edge candidate
    const meBottom = me.y + me.h;
    const oBottom  = o.y + o.h;
    const dyBottom = oBottom - meBottom;
    if (dyBottom !== 0 && Math.abs(dyBottom) <= _MAGNET_SNAP_THRESHOLD) {
      if (!bestBottom || Math.abs(dyBottom) < Math.abs(bestBottom.delta)) {
        bestBottom = { delta: dyBottom, target: oBottom };
      }
    }
  }

  if (!bestTop && !bestBottom) return;

  let newY = me.y, newH = me.h;
  if (bestTop) {
    const meBottom = newY + newH;
    newY = bestTop.target;
    newH = meBottom - newY;
  }
  if (bestBottom) newH = bestBottom.target - newY;
  if (newH <= 0 || (newY === me.y && newH === me.h)) return;

  // Respect minH if the snap would shrink below it.
  const minH = me.minH || 1;
  if (newH < minH) return;

  grid.update(item, { y: newY, h: newH });
}

// ══════════════════════════════════════════════════════════════════════════
// MINI GRID — sidebar with a scaled-down editable copy of the active section
// ══════════════════════════════════════════════════════════════════════════
// User opens this from the layout-edit toolbar (Mini-grid button). They can
// drag/resize tiles, drop tiles into a parking zone (hide), or drag from
// parking back into the grid (unhide / add). Apply commits the layout to
// _liveSectionLayouts + the active preset autosave. Cancel discards.
//
// The mini uses its own GridStack instance (_msState.grid) on a separate
// container so it never collides with the live dashboard grid (_grid).
// Aspect ratio is preserved by using the same 12-column grid + a small
// cellHeight (2px) so 1 mini-row maps to 5 real rows visually.

let _msState = null;       // null when sidebar is closed
const _MS_CELL_HEIGHT = 2; // mini cell height (real grid is 10) — 5x scale-down
const _MS_COLUMN_COUNT = 12;

// Widget archetype → SVG sigil. Minimalist: 6 patterns cover all widgets.
function _msGetWidgetIcon(id) {
  const KIND_BY_ID = {
    'w-setup':'bars', 'w-pair':'bars', 'w-session':'bars', 'w-day':'bars',
    'w-hour':'bars',  'w-m15':'bars',  'w-h4':'bars',      'w-pair-session':'bars',
    'w-heatmap':'heatmap', 'w-calendar':'heatmap',
    'w-equity':'line', 'w-recovery':'line', 'w-streak-analytics':'line',
    'w-optimal-rr':'line', 'w-montecarlo':'line',
    'w-outcome':'donut',
    'w-stats':'cells', 'w-tradelog':'cells',
    'w-selection':'mixed', 'w-monthly':'mixed', 'w-partial-optimizer':'mixed',
  };
  let kind = KIND_BY_ID[id] || 'mixed';
  if (!KIND_BY_ID[id] && id && id.startsWith('w-cust-')) {
    const cwDef = _loadCustomWidgetDefs().find(d => d.id === id);
    if (cwDef) kind = cwDef.type === 'heatmap' ? 'heatmap' : 'bars';
  }
  const ICONS = {
    bars:    '<svg viewBox="0 0 24 16" preserveAspectRatio="xMidYMid meet"><rect x="2" y="9" width="3" height="6"/><rect x="7" y="5" width="3" height="10"/><rect x="12" y="2" width="3" height="13"/><rect x="17" y="7" width="3" height="8"/></svg>',
    heatmap: '<svg viewBox="0 0 24 16" preserveAspectRatio="xMidYMid meet"><rect x="1" y="1" width="6" height="4"/><rect x="9" y="1" width="6" height="4" opacity=".5"/><rect x="17" y="1" width="6" height="4" opacity=".7"/><rect x="1" y="6" width="6" height="4" opacity=".4"/><rect x="9" y="6" width="6" height="4"/><rect x="17" y="6" width="6" height="4" opacity=".6"/><rect x="1" y="11" width="6" height="4" opacity=".6"/><rect x="9" y="11" width="6" height="4" opacity=".4"/><rect x="17" y="11" width="6" height="4" opacity=".8"/></svg>',
    line:    '<svg viewBox="0 0 24 16" preserveAspectRatio="xMidYMid meet"><polyline points="1,13 5,10 9,11 13,7 17,8 23,3" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>',
    donut:   '<svg viewBox="0 0 24 16" preserveAspectRatio="xMidYMid meet"><circle cx="12" cy="8" r="5" fill="none" stroke="currentColor" stroke-width="2.5"/><circle cx="12" cy="8" r="2"/></svg>',
    cells:   '<svg viewBox="0 0 24 16" preserveAspectRatio="xMidYMid meet"><rect x="1" y="2" width="22" height="3"/><rect x="1" y="6" width="22" height="3" opacity=".6"/><rect x="1" y="10" width="22" height="3" opacity=".4"/></svg>',
    mixed:   '<svg viewBox="0 0 24 16" preserveAspectRatio="xMidYMid meet"><rect x="2" y="9" width="3" height="6"/><polyline points="7,12 11,9 15,10 21,5" fill="none" stroke="currentColor" stroke-width="1.2"/></svg>',
  };
  return `<span class="ms-tile-icon ms-icon-${kind}">${ICONS[kind]}</span>`;
}

// "Unmapped" = the widget's required field is absent in every trade of the
// full dataset. Mirrors the buildRules logic in hideEmptyWidgets() — we just
// reuse it instead of duplicating, by sampling once at sidebar open time.
function _msComputeUnmappedSet() {
  const out = new Set();
  const items = appState?.trades?.items || [];
  if (!items.length) return out;
  let hSetup=false,hSession=false,hDay=false,hObs=false,hH4=false,hHour=false,hNotion=false;
  for (const t of items) {
    if (!hSetup   && t.setup    && t.setup.trim())              hSetup=true;
    if (!hSession && t.session  && t.session.trim())            hSession=true;
    if (!hDay     && t.day      && t.day.trim())                hDay=true;
    if (!hObs     && t.obstacles && t.obstacles.length > 0)     hObs=true;
    if (!hH4      && t.h4       && t.h4.length > 0)             hH4=true;
    if (!hHour    && t.hour != null)                            hHour=true;
    if (!hNotion  && t.notionUrl && String(t.notionUrl).trim()) hNotion=true;
    if (hSetup&&hSession&&hDay&&hObs&&hH4&&hHour&&hNotion) break;
  }
  const flags = {
    'w-setup': hSetup, 'w-session': hSession, 'w-day': hDay,
    'w-heatmap': hSession && hDay, 'w-m15': hObs, 'w-h4': hH4,
    'w-hour': hHour, 'w-pair-session': hSession, 'w-notion': hNotion,
  };
  Object.keys(flags).forEach(id => {
    if (!flags[id] && !_isWidgetSuppressedByNoMapping(id)) out.add(id);
  });
  return out;
}

// Section's full widget catalog: every widget that BELONGS to this section
// (per data-section in HTML), regardless of whether it's currently in the
// layout. Drives the parking zone.
function _msGetSectionWidgetIds(section) {
  const out = [];
  const excluded = _getTemplateExcludedWidgetIds();
  document.querySelectorAll('#gs-container .grid-stack-item').forEach(item => {
    const sec = item.querySelector('.gs-widget[data-section]')?.dataset.section;
    const id  = item.getAttribute('gs-id');
    if (sec === section && id && !excluded.has(id)) out.push(id);
  });
  return out;
}

function _msGetWidgetLabel(id) {
  const item = document.querySelector(`#gs-container .grid-stack-item[gs-id="${CSS.escape(id)}"]`);
  const titleEl = item?.querySelector('.cc-title');
  return (titleEl ? titleEl.textContent : id).trim() || id;
}

function _msTileHTML(id) {
  const label = _msGetWidgetLabel(id);
  const unmapped = _msState?.unmapped?.has(id);
  return `
    <div class="ms-tile${unmapped ? ' ms-tile-unmapped' : ''}" data-gs-id="${_escapeAttr(id)}" title="${_escapeAttr(label)}${unmapped ? ' — required data not mapped' : ''}">
      ${_msGetWidgetIcon(id)}
      <span class="ms-tile-label">${_escapeHtml(label)}</span>
      <button type="button" class="ms-tile-remove" data-action="ms-tile-remove" data-gs-id="${_escapeAttr(id)}" title="Send to parking">×</button>
    </div>
  `;
}

// Open the sidebar with a snapshot of the active section's current layout.
// We read directly from `_grid.getGridItems()` to capture the *live* positions
// — `_liveSectionLayouts[sec]` can drift stale after programmatic mutations
// (hide/unhide, makeWidget, update) that don't trigger _syncGridToLive.
// Falling back to _liveSectionLayouts only for entries the live grid doesn't
// have (i.e. widgets currently hidden by the user).
function _msOpenSidebar() {
  if (_msState?.open) return;
  const section = appState?.ui?.activeSection || 'global';
  // Build the live layout: prefer current grid nodes for items in the active
  // section; fall back to the persisted layout for hidden / off-section items.
  const liveLayout = JSON.parse(JSON.stringify(_liveSectionLayouts?.[section] || {}));
  if (_grid && typeof _grid.getGridItems === 'function') {
    _grid.getGridItems().forEach(item => {
      const n = item.gridstackNode;
      const id = item.getAttribute('gs-id');
      if (!n || !id) return;
      const sec = item.querySelector('.gs-widget[data-section]')?.dataset.section;
      if (sec !== section) return;
      const prev = liveLayout[id] || {};
      liveLayout[id] = {
        ...prev,
        x: n.x, y: n.y, w: n.w, h: n.h,
        minW: prev.minW || n.minW || 3,
        minH: prev.minH || n.minH || 10,
      };
    });
  }
  const pristineLayout = JSON.parse(JSON.stringify(liveLayout));
  const pristineHidden = JSON.parse(JSON.stringify(_hiddenWidgets || {}));

  _msState = {
    open: true,
    section,
    pristineLayout,
    pristineHidden,
    grid: null,
    unmapped: _msComputeUnmappedSet(),
    // Working state — what we'll commit on Apply
    pendingLayout: JSON.parse(JSON.stringify(pristineLayout)),
    pendingHidden: JSON.parse(JSON.stringify(pristineHidden)),
  };

  _msBuildSidebarDOM();
  _msInitGrid();
  _msRebuildParking();

  // Push the dashboard left so the sidebar doesn't cover content. We use a
  // body class so layout-edit-mode awareness is preserved.
  document.body.classList.add('ms-sidebar-open');
}

function _msCloseSidebar(apply) {
  if (!_msState?.open) return;
  if (apply) {
    _msApplyChanges();
  } else if (_msState.previewApplied) {
    // Preview was triggered earlier and mutated the live dashboard in-memory
    // without persisting. On Cancel we must restore pristine state so the
    // dashboard returns to exactly how it looked before the sidebar opened.
    _liveSectionLayouts[_msState.section] = JSON.parse(JSON.stringify(_msState.pristineLayout));
    _hiddenWidgets = JSON.parse(JSON.stringify(_msState.pristineHidden));
    if (typeof _saveHiddenWidgets === 'function') _saveHiddenWidgets();
    if (typeof _applySectionFilter === 'function') {
      _applySectionFilter(_msState.section, { skipSync: true });
    }
    if (typeof _saveActiveSlotLive === 'function') _saveActiveSlotLive();
  }
  // Always destroy the mini grid + sidebar DOM
  try { _msState.grid?.destroy(false); } catch {}
  document.getElementById('ms-sidebar')?.remove();
  document.body.classList.remove('ms-sidebar-open');
  _msState = null;
}

// Preview — apply the pending layout to the live dashboard without writing
// to localStorage. The user sees the result on the actual widgets, can keep
// iterating in the mini, and either Apply (commits + persists) or Cancel
// (reverts to pristine snapshot taken when the sidebar opened).
function _msPreview() {
  if (!_msState?.open) return;
  const sec = _msState.section;

  // Mutate _liveSectionLayouts[sec] from pendingLayout (positions/sizes)
  const merged = { ...(_liveSectionLayouts[sec] || {}) };
  Object.entries(_msState.pendingLayout).forEach(([id, d]) => {
    merged[id] = { ...(merged[id] || {}), x: d.x, y: d.y, w: d.w, h: d.h, minW: d.minW, minH: d.minH };
  });
  _liveSectionLayouts[sec] = merged;

  // Mutate _hiddenWidgets from pendingHidden — IN-MEMORY only.
  // Skip _saveHiddenWidgets() so localStorage stays at pristine state.
  _hiddenWidgets = { ..._msState.pendingHidden };

  // Re-render the live grid to reflect the preview layout.
  if (typeof _applySectionFilter === 'function') {
    _applySectionFilter(sec, { skipSync: true });
  }

  _msState.previewApplied = true;
  if (typeof _showToast === 'function') {
    _showToast('Preview applied — Apply to save · Cancel to revert', 'info');
  }
}

function _msBuildSidebarDOM() {
  const sectLabel = _SECTION_LABEL_MAP[_msState.section] || _msState.section;
  const wrap = document.createElement('aside');
  wrap.id = 'ms-sidebar';
  wrap.className = 'ms-sidebar';
  wrap.innerHTML = `
    <header class="ms-sidebar-head">
      <div class="ms-sidebar-title">
        <span class="ms-sidebar-eyebrow">Mini grid</span>
        <span class="ms-sidebar-section">${_escapeHtml(sectLabel)}</span>
      </div>
      <div class="ms-sidebar-actions">
        <button class="ms-btn ms-btn-preview" data-action="ms-preview" title="Apply to the dashboard live without saving — Cancel reverts">Preview</button>
        <button class="ms-btn ms-btn-cancel" data-action="ms-cancel">Cancel</button>
        <button class="ms-btn ms-btn-apply" data-action="ms-apply">Apply</button>
      </div>
    </header>
    <div class="ms-grid-wrap">
      <div id="ms-grid-container" class="grid-stack ms-grid"></div>
    </div>
    <div class="ms-parking-wrap">
      <div class="ms-parking-head">
        <span class="ms-parking-title">Hidden</span>
        <span class="ms-parking-hint">Drag onto the grid to show · drag a tile here to hide</span>
      </div>
      <div id="ms-parking" class="ms-parking"></div>
    </div>
  `;
  document.body.appendChild(wrap);
}

// Tear down and recreate the mini GridStack on its current pending state.
// Used after a drag-back from Hidden: GridStack's acceptWidgets path leaves
// the new widget without registered resize handles, so subsequent removeWidget
// or drag-out attempts fail silently and the widget gets stuck. Reiniting on
// a fresh GridStack instance is the only path that reliably restores a working
// state (load() registers handles correctly; addWidget on a corrupted instance
// does not). pendingLayout / pendingHidden survive on _msState so the new grid
// reads the same data the destroyed one had.
//
// We swap the container DOM rather than calling destroy() — destroy(true)
// throws "removeChild: not a child" when the corrupted state has missing
// handle refs, AND a subsequent load() into the same container silently
// adds zero widgets even when serialized has 18. A fresh container avoids
// both problems. _isReiniting flag tells the 'removed' listener to ignore
// the events that fire during teardown so we don't mass-park everything.
function _msReinitGridFresh() {
  if (!_msState?.grid || _msState._isReiniting) return;
  _msState._isReiniting = true;
  _msSyncPendingFromGrid();
  const oldContainer = document.getElementById('ms-grid-container');
  if (oldContainer && oldContainer.parentNode) {
    const parent = oldContainer.parentNode;
    const fresh = document.createElement('div');
    fresh.id = 'ms-grid-container';
    fresh.className = 'grid-stack ms-grid';
    parent.replaceChild(fresh, oldContainer);
  }
  _msState.grid = null;
  _msInitGrid();
  _msRebuildParking();
  _msState._isReiniting = false;
}

// Initialize the mini GridStack with the section's currently-visible widgets.
// We init on an EMPTY container (no gs-x/y attrs in markup) and add widgets
// programmatically with explicit positions inside a float(true) + batchUpdate.
// This avoids GridStack's startup collision-resolution swapping vertically-
// stacked widgets that share an x — a real bug we saw on the first attempt
// where w-equity and w-tradelog ended up in opposite order in the mini.
function _msInitGrid() {
  const container = document.getElementById('ms-grid-container');
  if (!container) return;

  _msState.grid = GridStack.init({
    column:        _MS_COLUMN_COUNT,
    cellHeight:    _MS_CELL_HEIGHT,
    margin:        2,
    float:         true,                  // floating during load to keep exact y
    animate:       true,
    disableDrag:   false,
    disableResize: false,
    oneColumnModePossible: false,
    acceptWidgets: '.ms-parked',
    // Drag-OUT to the Hidden zone: dropping a tile onto #ms-parking removes
    // it from the mini grid (the 'removed' event handler below records it
    // into pendingHidden so the dashboard ends up hiding it on Apply).
    removable:     '#ms-parking',
    removableOptions: { accept: '.grid-stack-item', decline: '.no-remove' },
    resizable:     { handles: 'se,sw,ne,nw,e,w,n,s' },
  }, '#ms-grid-container');

  // Use grid.load() — the canonical API for restoring a serialized layout.
  // It places widgets at their EXACT positions (no collision-resolution swaps
  // that addWidget triggers when widgets share an x and stack vertically).
  // We pre-sort by (y, x) so GridStack's load processes widgets top-to-bottom,
  // left-to-right — preventing earlier-iterated widgets from claiming positions
  // intended for later-iterated ones (the cause of the equity/monthly/tradelog
  // swap we observed when iterating in object-insertion order).
  const layout = _msState.pendingLayout;
  const serialized = Object.entries(layout)
    .filter(([id]) => !_msState.pendingHidden[id])
    .map(([id, d]) => ({
      id,
      x: d.x ?? 0, y: d.y ?? 0, w: d.w ?? 4, h: d.h ?? 20,
      minW: d.minW || 3, minH: d.minH || 10,
      content: _msTileHTML(id),
    }))
    .sort((a, b) => (a.y - b.y) || (a.x - b.x));
  _msState.grid.load(serialized);
  // Some GridStack builds don't propagate `id` to the gs-id attr, so write it
  // explicitly so getAttribute('gs-id') works downstream (Apply, drag-out, etc.)
  _msState.grid.getGridItems().forEach(item => {
    const node = item.gridstackNode;
    const nid = node?.id;
    if (nid && !item.getAttribute('gs-id')) item.setAttribute('gs-id', nid);
    item.classList.add('ms-tile-host');
  });
  // Float OFF so user drags compact normally (still no swap-on-load though).
  _msState.grid.float(false);

  // Mini grid is now populated — apply per-tile zoom (auto typo mode only).
  _applyAutoTypoScale();

  // 'added' fires for two situations:
  //   1) Initial load (load() inside this same _msInitGrid call) — every tile
  //      we feed in fires 'added'. The tile already has the right HTML and
  //      pendingHidden already excludes it, so the handler is essentially
  //      idempotent.
  //   2) Drag-drop from the Hidden zone — the parked .ms-parked div lands on
  //      the grid and GridStack converts it into a grid-stack-item. We must
  //      remove its hidden flag and refresh the Hidden list.
  // Robust id extraction: GridStack may store the id as node.id (after load),
  // or only on the element's gs-id / data-gs-id attribute (after drag-drop).
  _msState.grid.on('added', (_e, items) => {
    if (!Array.isArray(items)) return;
    let didUnhide = false;
    items.forEach(node => {
      const item = node.el;
      if (!item) return;
      const id = node.id
        || item.getAttribute('gs-id')
        || item.getAttribute('data-gs-id')
        || item.dataset?.gsId;
      if (!id) return;
      // Make sure both attributes are set so subsequent code paths find it.
      if (!item.getAttribute('gs-id')) item.setAttribute('gs-id', id);
      if (!item.getAttribute('data-gs-id')) item.setAttribute('data-gs-id', id);
      // Ensure proper grid-stack-item-content wrapper holds our tile HTML.
      let content = item.querySelector('.grid-stack-item-content');
      if (!content) {
        content = document.createElement('div');
        content.className = 'grid-stack-item-content';
        // Move any direct children inside the wrapper (drag-drop case).
        while (item.firstChild && item.firstChild !== content) {
          item.removeChild(item.firstChild);
        }
        item.appendChild(content);
      }
      // Always replace with the canonical tile HTML — drag-drop brings the
      // .ms-parked markup (icon + label, no remove button), we want the full
      // .ms-tile structure with the × button.
      content.innerHTML = _msTileHTML(id);
      item.classList.add('ms-tile-host');
      // Drag-drop from Hidden brings the .ms-parked / .ms-parked-unmapped
      // classes onto the new grid-stack-item. CSS uses descendant selectors
      // (.ms-parked .ms-tile-icon, etc.) so the tile would render with the
      // red "hidden" cue even though it's now visible. Strip them here.
      item.classList.remove('ms-parked', 'ms-parked-unmapped');
      // Unhide in pending state. If id wasn't previously hidden this is a
      // no-op (case 1 — initial load).
      if (_msState.pendingHidden[id]) {
        delete _msState.pendingHidden[id];
        didUnhide = true;
      }
    });
    _msSyncPendingFromGrid();
    if (didUnhide) {
      _msRebuildParking();
      // GridStack's `acceptWidgets` drop path leaves the new widget in a
      // half-initialized state — resize handles aren't registered, internal
      // refs are stale — so the next removeWidget / drag-out fails silently
      // and the widget gets stuck in the grid. Force a clean reinit so the
      // user can hide / move it again. Deferred so this fires after GridStack
      // finishes its current event chain.
      setTimeout(_msReinitGridFresh, 0);
    }
  });

  _msState.grid.on('change', () => _msSyncPendingFromGrid());

  // Magnetic snap on drag/resize stop — aligns side-by-side neighbours when
  // their edges land within the threshold. Sync after so pendingLayout
  // captures the post-snap position.
  _msState.grid.on('resizestop dragstop', (_e, el) => {
    _applyMagnetSnap(_msState.grid, el);
    _msSyncPendingFromGrid();
    // Recompute mini-tile zoom: each tile scales based on ITS OWN size in
    // the sidebar grid (not the matching main widget). Resizing a tile in
    // the sidebar updates only that tile's --widget-scale.
    _applyAutoTypoScale();
  });

  // 'removed' fires when a tile is dropped onto the Hidden zone (via the
  // `removable` config above). Snapshot its size, mark it hidden in pending
  // state, refresh the Hidden list. The DOM element is gone after this event.
  // Skipped during _msReinitGridFresh — destroy(true) fires 'removed' for
  // every item and we don't want to flag them all as user-hidden.
  _msState.grid.on('removed', (_e, items) => {
    if (_msState?._isReiniting) return;
    if (!Array.isArray(items)) return;
    items.forEach(node => {
      const id = node?.id || node?.el?.getAttribute('gs-id');
      if (!id) return;
      _msState.pendingHidden[id] = {
        w: node.w || _msState.pendingLayout[id]?.w || 4,
        h: node.h || _msState.pendingLayout[id]?.h || 20,
      };
    });
    _msSyncPendingFromGrid();
    _msRebuildParking();
  });
}

// Read the live mini grid state into pendingLayout. Sizes/positions only —
// hidden state is tracked separately via add/remove events.
function _msSyncPendingFromGrid() {
  if (!_msState?.grid) return;
  _msState.grid.getGridItems().forEach(item => {
    const n = item.gridstackNode;
    const id = item.getAttribute('gs-id');
    if (!n || !id) return;
    const prev = _msState.pendingLayout[id] || {};
    _msState.pendingLayout[id] = {
      ...prev,
      x: n.x, y: n.y, w: n.w, h: n.h,
      minW: prev.minW ?? n.minW ?? 3,
      minH: prev.minH ?? n.minH ?? 10,
    };
  });
}

// Rebuild the parking zone — every widget of this section that is NOT
// currently in the mini grid (= hidden in pendingHidden, or absent from
// pendingLayout). Sets up GridStack drag-in via setupDragIn.
function _msRebuildParking() {
  const parking = document.getElementById('ms-parking');
  if (!parking) return;
  const sectionIds = _msGetSectionWidgetIds(_msState.section);
  const inGrid = new Set(_msState.grid?.getGridItems().map(it => it.getAttribute('gs-id')) || []);
  const parkedIds = sectionIds.filter(id => !inGrid.has(id));

  parking.innerHTML = parkedIds.length
    ? parkedIds.map(id => {
        // every parked tile signals "hidden from dashboard" — we keep the
        // .ms-parked class for drag selectors but render a hidden visual cue.
        const label = _msGetWidgetLabel(id);
        const unmapped = _msState.unmapped.has(id);
        // Default size for re-add — fall back to widget's last-known size in
        // pendingLayout (preserves drag/resize done before hiding it), then
        // the section's default layout entry.
        const lastKnown = _msState.pendingLayout[id];
        const def = lastKnown || (SECTION_LAYOUTS[_msState.section] && SECTION_LAYOUTS[_msState.section][id]) || { w: 4, h: 20 };
        // gs-id (no data- prefix) is what GridStack reads when this element
        // is dropped into the grid via acceptWidgets — without it, the new
        // grid-stack-item has no id and our 'added' handler can't unhide it.
        // We keep data-gs-id as well for the click-action handlers.
        return `
          <div class="ms-parked${unmapped ? ' ms-parked-unmapped' : ''}"
               gs-id="${_escapeAttr(id)}"
               data-gs-id="${_escapeAttr(id)}"
               gs-w="${def.w}" gs-h="${def.h}"
               gs-min-w="${def.minW || 3}" gs-min-h="${def.minH || 10}"
               title="${_escapeAttr(label)}${unmapped ? ' — required data not mapped' : ''}">
            ${_msGetWidgetIcon(id)}
            <span class="ms-parked-label">${_escapeHtml(label)}</span>
          </div>
        `;
      }).join('')
    : '<div class="ms-parking-empty">No hidden widgets — all visible on the dashboard</div>';

  // Wire GridStack drag-in for the freshly rendered parked tiles.
  if (typeof GridStack !== 'undefined' && typeof GridStack.setupDragIn === 'function') {
    GridStack.setupDragIn('#ms-parking .ms-parked', { appendTo: 'body', helper: 'clone' });
  }
}

// Apply: write mini-grid changes to the live dashboard layout + hidden list.
function _msApplyChanges() {
  if (!_msState) return;
  const sec = _msState.section;
  // 1. Update _liveSectionLayouts[sec] from pendingLayout (positions+sizes)
  const merged = { ...(_liveSectionLayouts[sec] || {}) };
  Object.entries(_msState.pendingLayout).forEach(([id, d]) => {
    merged[id] = { ...(merged[id] || {}), x: d.x, y: d.y, w: d.w, h: d.h, minW: d.minW, minH: d.minH };
  });
  _liveSectionLayouts[sec] = merged;

  // 2. Update _hiddenWidgets from pendingHidden
  _hiddenWidgets = { ..._msState.pendingHidden };
  if (typeof _saveHiddenWidgets === 'function') _saveHiddenWidgets();

  // 3. Re-apply the section so the live grid reflects the new state
  if (typeof _applySectionFilter === 'function') {
    _applySectionFilter(sec, { skipSync: true });
  }

  // 4. Persist the layout to the active autosave + named preset
  if (typeof _saveActiveSlotLive === 'function') _saveActiveSlotLive();

  // 5. Sync the Hide popover if it happens to be open
  if (typeof _renderHidePopoverList === 'function') _renderHidePopoverList();

  if (typeof _showToast === 'function') _showToast('Layout applied from mini grid', 'ok');
}

// Send a tile to the parking zone (= hide it in pending state).
function _msTileRemove(id) {
  if (!_msState?.grid || !id) return;
  const item = _msState.grid.getGridItems().find(it => it.getAttribute('gs-id') === id);
  if (!item) return;
  // Snapshot size before removal
  const n = item.gridstackNode;
  if (n) _msState.pendingHidden[id] = { w: n.w, h: n.h };
  _msState.grid.removeWidget(item, true);
  _msSyncPendingFromGrid();
  _msRebuildParking();
}

function _getCustomSlots() {
  try {
    const raw = localStorage.getItem(_htfKey(LS_KEY_SLOTS));
    const arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr.slice(0, LAYOUT_SLOTS_MAX) : [];
  } catch { return []; }
}

function _setCustomSlots(slots) {
  localStorage.setItem(_htfKey(LS_KEY_SLOTS), JSON.stringify(slots.slice(0, LAYOUT_SLOTS_MAX)));
}

function _addCustomSlot(name) {
  const slots = _getCustomSlots();
  const idx = slots.indexOf(name);
  if (idx !== -1) return { ok: true, slots };        // already exists — overwrite content
  if (slots.length >= LAYOUT_SLOTS_MAX) return { ok: false, slots };
  slots.push(name);
  _setCustomSlots(slots);
  return { ok: true, slots };
}

function _removeCustomSlot(name) {
  const slots = _getCustomSlots().filter(s => s !== name);
  _setCustomSlots(slots);
  localStorage.removeItem(_htfKey(LS_KEY_PREFIX + name));
}

// Detect legacy flat-layout slots (pre-refactor). Returns true if the parsed
// object has widget ids at the top level instead of section keys.
function _isLegacySlot(obj) {
  if (!obj || typeof obj !== 'object') return false;
  const sectionKeys = ['global', 'optimal-rr', 'partials'];
  return !sectionKeys.some(k => k in obj);
}

// Convert a legacy flat layout into the new section-keyed shape.
function _migrateLegacySlot(flat) {
  const out = { global: {}, 'optimal-rr': {}, partials: {} };
  for (const id in flat) {
    if (id in GLOBAL_OVERVIEW_LAYOUT)      out.global[id]       = flat[id];
    else if (id in OPTIMAL_RR_LAYOUT)      out['optimal-rr'][id] = flat[id];
    else if (id in PARTIAL_PLANNERS_LAYOUT) out.partials[id]     = flat[id];
  }
  return out;
}

// Snapshot current custom-widget (w-cust-*) positions from the live grid
// and _liveSectionLayouts.global. Called before overwriting _liveSectionLayouts
// so custom widgets survive a reset or "load default" operation.
function _snapshotCustomLayouts() {
  const customs = {};
  const cur = _liveSectionLayouts?.global || {};
  Object.entries(cur).forEach(([id, d]) => {
    if (String(id).startsWith('w-cust-')) customs[id] = { ...d };
  });
  if (_grid) {
    const gsContainer = document.getElementById('gs-container');
    gsContainer?.querySelectorAll('.grid-stack-item').forEach(item => {
      const n  = item.gridstackNode;
      const id = item.getAttribute('gs-id');
      if (n && id && String(id).startsWith('w-cust-')) {
        customs[id] = {
          x: n.x, y: n.y, w: n.w, h: n.h,
          minW: n.minW ?? customs[id]?.minW ?? 2,
          minH: n.minH ?? customs[id]?.minH ?? 14,
        };
      }
    });
  }
  return customs;
}

// Compute factory-default positions for all custom widgets (w-cust-*), stacked
// vertically below the native global layout in creation order.
// Used by layoutReset() so custom widgets are also reset to a sensible default.
function _defaultCustomWidgetLayouts() {
  const defs = _loadCustomWidgetDefs();
  const result = {};
  let startY = 0;
  Object.values(GLOBAL_OVERVIEW_LAYOUT).forEach(pos => {
    const bot = (pos.y || 0) + (pos.h || 0);
    if (bot > startY) startY = bot;
  });
  defs.forEach((def, i) => {
    result[def.id] = { x: 0, y: startY + i * 39, w: 6, h: 39, minW: 2, minH: 14 };
  });
  return result;
}

// Flush the current GridStack node positions into _liveSectionLayouts
// for the active section. This captures ALL widgets (not just the one
// the user dragged) so that compaction side-effects are persisted too.
function _syncGridToLive() {
  if (!_grid) return;
  const sec = appState.ui.activeSection || 'global';
  const live = _liveSectionLayouts[sec];
  if (!live) return;
  const gsContainer = document.getElementById('gs-container');
  if (!gsContainer) return;
  gsContainer.querySelectorAll('.grid-stack-item').forEach(item => {
    const n  = item.gridstackNode;
    const id = item.getAttribute('gs-id');
    if (n && id && live[id]) {
      live[id] = { ...live[id], x: n.x, y: n.y, w: n.w, h: n.h };
    } else if (n && id && String(id).startsWith('w-cust-')) {
      live[id] = { x: n.x, y: n.y, w: n.w, h: n.h, minW: n.minW ?? 2, minH: n.minH ?? 14 };
    }
  });
}

function _getSavedDynamicWidgetGrid(id) {
  if (!id) return null;
  const liveItem = document.querySelector(`#gs-container .grid-stack-item[gs-id="${CSS.escape(id)}"]`);
  const node = liveItem?.gridstackNode;
  if (node) {
    return {
      x: node.x, y: node.y, w: node.w, h: node.h,
      minW: node.minW ?? (_liveSectionLayouts?.global?.[id]?.minW) ?? 2,
      minH: node.minH ?? (_liveSectionLayouts?.global?.[id]?.minH) ?? 14,
    };
  }
  const live = _liveSectionLayouts?.global?.[id];
  if (!live) return null;
  return {
    x: live.x, y: live.y, w: live.w, h: live.h,
    minW: live.minW ?? 2,
    minH: live.minH ?? 14,
  };
}

function _serializeDynamicWidgets() {
  return _loadCustomWidgetDefs().map(rawDef => {
    const def = _normalizeCustomWidgetDef(rawDef);
    const grid = _getSavedDynamicWidgetGrid(def.id);
    const isHeatmap = def.type === 'heatmap';
    return {
      id: def.id,
      type: isHeatmap ? 'heatmap' : 'bar',
      createdFrom: def.createdFrom || 'widget-builder',
      label: def.label || def.propertyLabel || '',
      propertySource: def.propertySource || def.fieldSource || 'mapped',
      propertyKey: def.propertyKey || def.field || '',
      propertyLabel: def.propertyLabel || def.fieldLabel || def.label || '',
      xPropertyKey: isHeatmap ? (def.field || '') : null,
      xPropertyLabel: isHeatmap ? (def.fieldLabel || def.propertyLabel || def.label || def.field || '') : null,
      yPropertyKey: isHeatmap ? (def.field2 || '') : null,
      yPropertyLabel: isHeatmap ? (def.field2Label || def.field2 || '') : null,
      settings: def.settings ? JSON.parse(JSON.stringify(def.settings)) : null,
      hidden: _isWidgetHidden(def.id),
      grid,
      definition: JSON.parse(JSON.stringify(def)),
    };
  });
}

function _restoreDynamicWidgetDefFromPayload(entry) {
  if (!entry || typeof entry !== 'object') return null;
  if (entry.definition && typeof entry.definition === 'object') {
    return _normalizeCustomWidgetDef(entry.definition);
  }
  const rawType = String(entry.type || '').trim().toLowerCase();
  if (rawType === 'heatmap') {
    return _normalizeCustomWidgetDef({
      id: entry.id,
      type: 'heatmap',
      field: entry.xPropertyKey || entry.field || '',
      field2: entry.yPropertyKey || entry.field2 || '',
      label: entry.label || `${entry.xPropertyLabel || entry.xPropertyKey || entry.field || ''} × ${entry.yPropertyLabel || entry.yPropertyKey || entry.field2 || ''}`.trim(),
      fieldLabel: entry.xPropertyLabel || entry.fieldLabel || entry.propertyLabel || entry.xPropertyKey || entry.field || '',
      field2Label: entry.yPropertyLabel || entry.field2Label || entry.yPropertyKey || entry.field2 || '',
      propertyKey: entry.propertyKey || entry.xPropertyKey || entry.field || '',
      propertyLabel: entry.propertyLabel || entry.xPropertyLabel || entry.label || '',
      fieldSource: entry.fieldSource || entry.propertySource || 'mapped',
      field2Source: entry.field2Source || entry.propertySource || 'mapped',
      propertySource: entry.propertySource || 'mapped',
      inferredType: entry.inferredType || 'text',
      createdFrom: entry.createdFrom || 'widget-builder',
      settings: entry.settings || {},
    });
  }
  return _normalizeCustomWidgetDef({
    id: entry.id,
    type: 'bars',
    field: entry.propertyKey || entry.field || '',
    label: entry.label || entry.propertyLabel || entry.propertyKey || entry.field || '',
    propertyKey: entry.propertyKey || entry.field || '',
    propertyLabel: entry.propertyLabel || entry.label || entry.propertyKey || entry.field || '',
    fieldSource: entry.fieldSource || entry.propertySource || 'mapped',
    propertySource: entry.propertySource || 'mapped',
    inferredType: entry.inferredType || 'text',
    createdFrom: entry.createdFrom || 'widget-builder',
  });
}

// Serialize the three live section layouts into a single slot payload.
function _serializeSectionLayouts() {
  return {
    global:       { ..._liveSectionLayouts.global },
    'optimal-rr': { ..._liveSectionLayouts['optimal-rr'] },
    partials:     { ..._liveSectionLayouts.partials },
    hiddenWidgets: { ...(_hiddenWidgets || {}) },
    dynamicWidgets: _serializeDynamicWidgets(),
  };
}

// Save the live layouts to a named slot (or 'active' for the autosave).
// Pass skipSync:true when _liveSectionLayouts was just set programmatically
// and is already correct — avoids _syncGridToLive overwriting it with
// stale grid-node positions that haven't been applied to the DOM yet.
function _saveSectionSlot(key, { skipSync = false } = {}) {
  if (!skipSync) _syncGridToLive();
  const payload = _serializeSectionLayouts();
  const savedItems = {
    global: payload.global,
    'optimal-rr': payload['optimal-rr'],
    partials: payload.partials,
    hiddenWidgets: payload.hiddenWidgets,
  };
  debugLog('[layout-save] items', savedItems);
  debugLog('[layout-save] dynamic widgets', payload.dynamicWidgets);
  localStorage.setItem(_htfKey(LS_KEY_PREFIX + key), JSON.stringify(payload));
  if (key !== 'active') localStorage.setItem(_htfKey(LS_KEY_ACTIVE), key);
}

// Autosave the active slot + named preset slot (called after every drag/resize).
// The checkpoint slot (LS_KEY_CKPT_PREFIX) is only written on explicit Save — Reset uses it.
function _saveActiveSlotLive() {
  _saveSectionSlot('active');
  const name = _activePresetName;
  if (name) _saveSectionSlot(name); // preserve live state per-preset across switches
  if (!_suppressDirty) {
    _dirtyPresets[name] = true;
    _updatePresetButtons();
  }
}

// Load a slot payload into the live layouts. Accepts both new and legacy shapes.
function _loadSectionSlot(raw) {
  let parsed;
  try { parsed = JSON.parse(raw); } catch { return false; }
  if (!parsed) return false;
  const data = _isLegacySlot(parsed) ? _migrateLegacySlot(parsed) : parsed;
  debugLog('[layout-restore] saved layout', data);
  debugLog('[layout-restore] dynamic widgets before create', data.dynamicWidgets || []);
  const globalData = { ...GLOBAL_OVERVIEW_LAYOUT, ...(data.global || {}) };
  if (Array.isArray(data.dynamicWidgets)) {
    const restoredDefs = data.dynamicWidgets
      .map(_restoreDynamicWidgetDefFromPayload)
      .filter(Boolean);
    // Merge with current defs: update defs that exist in the saved layout, keep those
    // that were created after the layout was saved. This prevents new custom widgets
    // from disappearing when switching to an older preset.
    const currentDefs = _loadCustomWidgetDefs();
    const restoredById = Object.fromEntries(restoredDefs.map(d => [d.id, d]));
    const merged = currentDefs.map(d => restoredById[d.id] ?? d);
    restoredDefs.forEach(d => { if (!merged.find(m => m.id === d.id)) merged.push(d); });
    _saveCustomWidgetDefs(merged);
    data.dynamicWidgets.forEach(entry => {
      const grid = entry?.grid;
      const id = entry?.id;
      if (!id || !grid || typeof grid !== 'object') return;
      debugLog('[layout-restore] applying grid position for', id, grid);
      globalData[id] = {
        ...(globalData[id] || {}),
        x: grid.x ?? globalData[id]?.x ?? 0,
        y: grid.y ?? globalData[id]?.y ?? 0,
        w: grid.w ?? globalData[id]?.w ?? 6,
        h: grid.h ?? globalData[id]?.h ?? 39,
        minW: grid.minW ?? globalData[id]?.minW ?? 2,
        minH: grid.minH ?? globalData[id]?.minH ?? 14,
      };
    });
  }
  // Note: data.hiddenWidgets is intentionally IGNORED here. Hidden widgets
  // live in their own profile-scoped key (gs_hidden_widgets via _htfKey),
  // which is the single source of truth. The embedded copy in the layout
  // payload was historically a redundant snapshot; reading it back caused a
  // destructive overwrite on profile/HTF switches (the layout's stale snapshot
  // would clobber the dedicated key, hiding the user's actual hidden-widget
  // state). _reloadProfileScopedState calls _loadHiddenWidgets right after
  // _loadSectionSlot, which loads the correct per-profile state directly.

  // Silent migration: strip the retired Partials Planner widget from any
  // saved partials-section payload so the orphan id can't reach GridStack.
  const partialsData = { ...(data.partials || {}) };
  delete partialsData['w-partials-planner'];

  _liveSectionLayouts = {
    global:       globalData,
    'optimal-rr': { ...OPTIMAL_RR_LAYOUT,           ...(data['optimal-rr'] || {}) },
    partials:     { ...PARTIAL_PLANNERS_LAYOUT,     ...partialsData },
  };
  return true;
}

const DEFAULT_SHARE_LAYOUT = {
  'sv-w-date':   { x:0, y:0,  w:12, h:4,  minW:4, minH:3 },
  'sv-w-stats':  { x:0, y:4,  w:12, h:9,  minW:4, minH:6 },
  'sv-w-equity': { x:0, y:13, w:7,  h:14, minW:4, minH:8 },
  'sv-w-cal':    { x:7, y:13, w:5,  h:14, minW:4, minH:8 },
  'sv-w-pair':   { x:0, y:27, w:6,  h:12, minW:4, minH:8 },
  'sv-w-setup':  { x:6, y:27, w:6,  h:12, minW:4, minH:8 },
};

let _grid = null;
let _svGrid = null;
let _editMode = false;
let _activePresetName = 'default';
let _dirtyPresets  = {};     // per-preset dirty flags: { 'Layout 1': true, ... }
let _suppressDirty = false; // true during programmatic layout ops — prevents auto-dirty
// Guard: true once GridStack has finished moving widgets into its containers.
// render() calls during _buildGridDOM() can crash because elements are mid-move.
var _gsReady = false;
var _svGsReady = false;
// Flag: true while the sidebar collapse/expand CSS transition is animating
// (.layout grid-template-columns, 300ms ease). The ResizeObserver in _initGrid
// observes every .grid-stack-item-content; without this guard it fires once
// per animation frame during the transition, each call running
// _applyAutoTypoScale (loops every widget) + scheduling _debouncedRedrawAll.
// We suspend RO work during the transition and do ONE final redraw after.
let _isSidebarToggling = false;

// ── Inject custom widget .gs-widget elements into #main-panel before _buildGridDOM ──
// Called once at initGridstack time. Each def generates one .gs-widget that
// _buildGridDOM then wraps in .grid-stack-item like any native widget.
function _injectCustomWidgetHTML() {
  const main = document.getElementById('main-panel');
  if (!main) return;
  const defs = _loadCustomWidgetDefs();
  defs.forEach(def => {
    if (main.querySelector(`[data-gs-id="${CSS.escape(def.id)}"]`)) return;
    const widget = document.createElement('div');
    widget.className = 'chart-card gs-widget cw-widget';
    widget.setAttribute('data-gs-id', def.id);
    widget.setAttribute('data-section', 'global');
    widget.setAttribute('data-cw-id', def.id);
    if (def.type === 'bars') {
      widget.innerHTML = `
        <div class="cc-head">
          <span class="cc-title">${_escapeHtml(def.label)}</span>
        </div>
        ${_renderCustomBarSortToolbarHTML(def.id)}
        <div class="bar-list" id="bars-${_escapeAttr(def.id)}"></div>`;
    } else if (def.type === 'table') {
      widget.innerHTML = `
        <div class="cc-head cc-head-spaced">
          <span class="cc-title">${_escapeHtml(def.label)}</span>
          ${_renderCustomTableToolbarHTML(def)}
        </div>
        <div class="cw-table-host" id="cw-table-host-${_escapeAttr(def.id)}"></div>`;
    } else {
      widget.innerHTML = `
        <div class="cc-head">
          <span class="cc-title">${_escapeHtml(def.label)}</span>
          ${_renderSharedHeatmapToolbarHTML('sd', def)}
        </div>
        <div id="heatmap-${_escapeAttr(def.id)}" class="cw-hm-wrap"></div>`;
    }
    main.appendChild(widget);
  });
}

// Inject a single new custom widget into the live grid (after initGridstack).
// Used when the user creates a widget from the mapping panel without a page reload.
function _injectNewCustomWidget(def) {
  if (!_grid) return;
  const gsContainer = document.getElementById('gs-container');
  if (!gsContainer) return;
  if (document.querySelector(`#gs-container .grid-stack-item[gs-id="${CSS.escape(def.id)}"]`)) return;

  // Build the same widget element structure _buildGridDOM would produce
  const widget = document.createElement('div');
  widget.className = 'chart-card gs-widget cw-widget';
  widget.setAttribute('data-gs-id', def.id);
  widget.setAttribute('data-section', 'global');
  widget.setAttribute('data-cw-id', def.id);
  if (def.type === 'bars') {
    widget.innerHTML = `
      <div class="cc-head">
        <span class="cc-title">${_escapeHtml(def.label)}</span>
      </div>
      ${_renderCustomBarSortToolbarHTML(def.id)}
      <div class="bar-list" id="bars-${_escapeAttr(def.id)}"></div>`;
  } else if (def.type === 'table') {
    widget.innerHTML = `
      <div class="cc-head cc-head-spaced">
        <span class="cc-title">${_escapeHtml(def.label)}</span>
        ${_renderCustomTableToolbarHTML(def)}
      </div>
      <div class="cw-table-host" id="cw-table-host-${_escapeAttr(def.id)}"></div>`;
  } else {
    widget.innerHTML = `
      <div class="cc-head">
        <span class="cc-title">${_escapeHtml(def.label)}</span>
        ${_renderSharedHeatmapToolbarHTML('sd', def)}
      </div>
      <div id="heatmap-${_escapeAttr(def.id)}" class="cw-hm-wrap"></div>`;
  }

  const item = document.createElement('div');
  item.className = 'grid-stack-item';
  item.setAttribute('gs-id', def.id);

  const content = document.createElement('div');
  content.className = 'grid-stack-item-content';

  const handle = document.createElement('div');
  handle.className = 'gs-drag-handle';
  handle.innerHTML = '⠿⠿⠿';
  handle.title = 'Drag to move';

  const hideBtn = document.createElement('button');
  hideBtn.type = 'button';
  hideBtn.className = 'gs-hide-btn';
  hideBtn.title = 'Hide this widget';
  hideBtn.setAttribute('data-action', 'layout-hide-widget-confirm');
  hideBtn.setAttribute('data-gs-id', def.id);
  hideBtn.innerHTML = '<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>';
  const deleteBtn = document.createElement('div');
  deleteBtn.innerHTML = _buildCustomWidgetDeleteButtonHTML(def.id);

  content.appendChild(handle);
  content.appendChild(hideBtn);
  content.appendChild(deleteBtn.firstElementChild);
  content.appendChild(widget);
  item.appendChild(content);
  gsContainer.appendChild(item);

  // Compute bottom of global section
  let maxBottom = 0;
  _grid.getGridItems().forEach(it => {
    const n = it.gridstackNode;
    if (!n) return;
    const sec = it.querySelector('.gs-widget[data-section]')?.dataset.section;
    if (sec !== 'global') return;
    const bot = (n.y || 0) + (n.h || 0);
    if (bot > maxBottom) maxBottom = bot;
  });

  const dw = 6, dh = 39;
  item.setAttribute('gs-x', 0);
  item.setAttribute('gs-y', maxBottom);
  item.setAttribute('gs-w', dw);
  item.setAttribute('gs-h', dh);
  item.setAttribute('gs-min-w', 2);
  item.setAttribute('gs-min-h', 14);

  const activeSec = appState?.ui?.activeSection || 'global';
  if (activeSec === 'global') {
    _grid.float(true);
    _grid.batchUpdate();
    try {
      _grid.makeWidget(item);
      _grid.update(item, { x: 0, y: maxBottom, w: dw, h: dh });
    } finally { _grid.commit(); }
    _grid.float(false);
  } else {
    item.style.display = 'none';
  }

  // Mirror into live layouts
  if (!_liveSectionLayouts.global) _liveSectionLayouts.global = {};
  _liveSectionLayouts.global[def.id] = { x: 0, y: maxBottom, w: dw, h: dh, minW: 2, minH: 14 };
  if (typeof _saveActiveSlotLive === 'function') _saveActiveSlotLive();

  // Render content immediately
  const filtered = getFiltered();
  if (def.type === 'bars')         renderCustomBars(def, filtered);
  else if (def.type === 'heatmap') renderCustomHeatmap(def, filtered);
  else if (def.type === 'table')   renderCustomTable(def, filtered);

  if (typeof _renderHidePopoverList === 'function') _renderHidePopoverList();
}

// Companion to _injectNewCustomWidget for the cross-device profile-switch
// path (Task #3.6). When a custom widget's definition arrives via M1 sync
// (syncFromRemote pulls flipping_custom_widgets_<id> into LS) but the widget
// was never CREATED on this device, _injectNewCustomWidget was never called
// and no grid-stack-item DOM exists. The layout from the synced blob holds
// the widget's position, but the grid renders nothing because the gs-id has
// no corresponding DOM element. The user had to refresh the whole page to
// hit initGridstack → _injectCustomWidgetHTML → _buildGridDOM which rebuilds
// everything from scratch.
//
// Difference from _injectNewCustomWidget: this function reads the saved
// position from _liveSectionLayouts.global (rather than computing a fresh
// max-bottom). It also skips the _liveSectionLayouts mutation and
// _saveActiveSlotLive call — those would only matter for a brand-new widget
// the user just created, not for one that already has a known position.
function _ensureCustomWidgetInGrid(def) {
  if (!_grid || !def?.id) return false;
  const gsContainer = document.getElementById('gs-container');
  if (!gsContainer) return false;
  if (document.querySelector(`#gs-container .grid-stack-item[gs-id="${CSS.escape(def.id)}"]`)) return false;
  const layoutGlobal = (_liveSectionLayouts && _liveSectionLayouts.global) || {};
  const pos = layoutGlobal[def.id];
  if (!pos) {
    // No saved position — the widget was synced (def in LS) but the layout
    // upload from the creating device hadn't completed yet, or the layout
    // got reset since. Skip silently. The user can re-add a position by
    // dragging the widget into the grid via the mini-sidebar later.
    return false;
  }
  // Build the widget content (same structure as _injectNewCustomWidget).
  const widget = document.createElement('div');
  widget.className = 'chart-card gs-widget cw-widget';
  widget.setAttribute('data-gs-id', def.id);
  widget.setAttribute('data-section', 'global');
  widget.setAttribute('data-cw-id', def.id);
  if (def.type === 'bars') {
    widget.innerHTML = `
      <div class="cc-head">
        <span class="cc-title">${_escapeHtml(def.label)}</span>
      </div>
      ${_renderCustomBarSortToolbarHTML(def.id)}
      <div class="bar-list" id="bars-${_escapeAttr(def.id)}"></div>`;
  } else if (def.type === 'table') {
    widget.innerHTML = `
      <div class="cc-head cc-head-spaced">
        <span class="cc-title">${_escapeHtml(def.label)}</span>
        ${_renderCustomTableToolbarHTML(def)}
      </div>
      <div class="cw-table-host" id="cw-table-host-${_escapeAttr(def.id)}"></div>`;
  } else {
    widget.innerHTML = `
      <div class="cc-head">
        <span class="cc-title">${_escapeHtml(def.label)}</span>
        ${_renderSharedHeatmapToolbarHTML('sd', def)}
      </div>
      <div id="heatmap-${_escapeAttr(def.id)}" class="cw-hm-wrap"></div>`;
  }
  // Build the grid-stack-item wrapper.
  const item = document.createElement('div');
  item.className = 'grid-stack-item';
  item.setAttribute('gs-id', def.id);
  const content = document.createElement('div');
  content.className = 'grid-stack-item-content';
  const handle = document.createElement('div');
  handle.className = 'gs-drag-handle';
  handle.innerHTML = '⠿⠿⠿';
  handle.title = 'Drag to move';
  const hideBtn = document.createElement('button');
  hideBtn.type = 'button';
  hideBtn.className = 'gs-hide-btn';
  hideBtn.title = 'Hide this widget';
  hideBtn.setAttribute('data-action', 'layout-hide-widget-confirm');
  hideBtn.setAttribute('data-gs-id', def.id);
  hideBtn.innerHTML = '<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>';
  const deleteWrap = document.createElement('div');
  deleteWrap.innerHTML = _buildCustomWidgetDeleteButtonHTML(def.id);
  content.appendChild(handle);
  content.appendChild(hideBtn);
  if (deleteWrap.firstElementChild) content.appendChild(deleteWrap.firstElementChild);
  content.appendChild(widget);
  item.appendChild(content);
  // Apply the SAVED position (vs maxBottom in _injectNewCustomWidget).
  item.setAttribute('gs-x', pos.x ?? 0);
  item.setAttribute('gs-y', pos.y ?? 0);
  item.setAttribute('gs-w', pos.w ?? 6);
  item.setAttribute('gs-h', pos.h ?? 39);
  item.setAttribute('gs-min-w', pos.minW ?? 2);
  item.setAttribute('gs-min-h', pos.minH ?? 14);
  gsContainer.appendChild(item);
  // Hide if widget is in the current hidden set (matches initGridstack /
  // _applySectionFilter behavior).
  if (typeof _isWidgetHidden === 'function' && _isWidgetHidden(def.id)) {
    item.style.display = 'none';
    return true; // DOM created but not registered with grid (matches hidden semantics)
  }
  // Register with GridStack only if the active section is 'global' (custom
  // widgets always live in 'global' currently). Other sections leave the item
  // detached, matching the existing pattern in _injectNewCustomWidget /
  // _applySectionFilter.
  const activeSec = appState?.ui?.activeSection || 'global';
  if (activeSec === 'global') {
    try {
      _grid.batchUpdate();
      try { _grid.makeWidget(item); } finally { _grid.commit(); }
    } catch (e) {
      console.warn('[CustomWidget] makeWidget failed for', def.id, e?.message || e);
    }
  } else {
    item.style.display = 'none';
  }
  // Render content immediately so the widget shows data on first paint.
  try {
    const filtered = (typeof getFiltered === 'function') ? getFiltered() : [];
    if (def.type === 'bars' && typeof renderCustomBars === 'function') renderCustomBars(def, filtered);
    else if (def.type === 'heatmap' && typeof renderCustomHeatmap === 'function') renderCustomHeatmap(def, filtered);
    else if (def.type === 'table' && typeof renderCustomTable === 'function') renderCustomTable(def, filtered);
  } catch (e) {
    console.warn('[CustomWidget] initial render failed for', def.id, e?.message || e);
  }
  return true;
}

// Remove a custom widget from DOM, grid, layout, and defs storage.
function _destroyCustomWidget(id) {
  _closeDeleteConfirm();
  _closeHideConfirm();
  delete barSortState[id];
  // Remove from defs
  _removeCustomWidgetDef(id);

  // Remove from hidden state
  if (_hiddenWidgets && _hiddenWidgets[id]) {
    delete _hiddenWidgets[id];
    _saveHiddenWidgets();
  }

  // Remove from live layouts
  if (_liveSectionLayouts) {
    Object.values(_liveSectionLayouts).forEach(layout => { delete layout[id]; });
  }

  // Remove from grid + DOM
  if (_grid) {
    const item = document.querySelector(`#gs-container .grid-stack-item[gs-id="${CSS.escape(id)}"]`);
    if (item) {
      if (item.gridstackNode) _grid.removeWidget(item, true);
      else item.remove();
    }
  }

  if (typeof _saveActiveSlotLive === 'function') _saveActiveSlotLive();
  if (typeof _renderHidePopoverList === 'function') _renderHidePopoverList();
}

// ── Build Gridstack DOM from flat .gs-widget elements ──
function _buildGridDOM() {
  const main = document.getElementById('main-panel');

  // Collect all .gs-widget elements in order
  const widgets = [...main.querySelectorAll('.gs-widget')];

  // Build the grid-stack container
  const gsDiv = document.createElement('div');
  gsDiv.className = 'grid-stack';
  gsDiv.id = 'gs-container';

  widgets.forEach(el => {
    const id = el.dataset.gsId;
    const d  = DEFAULT_LAYOUT[id] || { x:0, y:0, w:12, h:20, minW:3, minH:10 };

    const item = document.createElement('div');
    item.className = 'grid-stack-item';
    item.setAttribute('gs-id',    id);
    item.setAttribute('gs-x',     d.x);
    item.setAttribute('gs-y',     d.y);
    item.setAttribute('gs-w',     d.w);
    item.setAttribute('gs-h',     d.h);
    item.setAttribute('gs-min-w', d.minW || 3);
    item.setAttribute('gs-min-h', d.minH || 10);

    const content = document.createElement('div');
    content.className = 'grid-stack-item-content';

    const handle = document.createElement('div');
    handle.className = 'gs-drag-handle';
    handle.innerHTML = '⠿⠿⠿';
    handle.title = 'Drag to move';

    // Per-widget hide button (eye-off icon). Only visible in edit mode via CSS.
    // Positioned top-right of the card, with horizontal clearance from the NE
    // resize handle (14px-wide at top:0/right:0) — see .gs-hide-btn rules.
    const hideBtn = document.createElement('button');
    hideBtn.type = 'button';
    hideBtn.className = 'gs-hide-btn';
    hideBtn.title = 'Hide this widget';
    hideBtn.setAttribute('data-action', 'layout-hide-widget-confirm');
    hideBtn.setAttribute('data-gs-id', id);
    hideBtn.innerHTML = '<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>';

    content.appendChild(handle);
    content.appendChild(hideBtn);
    if (el.matches('.cw-widget[data-cw-id]')) {
      const cwId = el.getAttribute('data-cw-id');
      const deleteWrap = document.createElement('div');
      deleteWrap.innerHTML = _buildCustomWidgetDeleteButtonHTML(cwId);
      content.appendChild(deleteWrap.firstElementChild);
    }
    content.appendChild(el);  // move the actual widget inside
    item.appendChild(content);
    gsDiv.appendChild(item);
  });

  // Rebuild main
  main.innerHTML = '';

  // Layout toolbar is a popover anchored below the Layout Edit button.
  document.getElementById('layout-toolbar')?.remove();
  const toolbar = document.createElement('div');
  toolbar.id = 'layout-toolbar';
  toolbar.className = 'layout-toolbar layout-toolbar-popover';
  toolbar.innerHTML = _buildToolbarHTML();
  const editWrap = document.getElementById('layout-edit-wrap');
  if (editWrap) {
    editWrap.appendChild(toolbar);
  } else {
    main.appendChild(toolbar);
  }

  main.appendChild(gsDiv);
}

function _buildShareGridDOM() {
  // Share view uses a static CSS grid layout on #sv-export itself.
  // No GridStack wrapping — widgets remain as direct children with their
  // original IDs so the grid-template rules in dashboard.css apply directly.
  // This function is intentionally a no-op; kept for call-site compatibility.
}

function _buildToolbarHTML() {
  const slots = _getCustomSlots();
  const defaultBtn = `<button class="lt-preset-btn" data-action="layout-load-preset" data-name="default">default</button>`;
  const slotBtns = slots.map(name =>
    `<button class="lt-preset-btn lt-preset-slot" data-action="layout-load-preset" data-name="${_escapeAttr(name)}" title="Right-click to rename or delete">${_escapeHtml(name)}</button>`
  ).join('');
  const canAdd = slots.length < LAYOUT_SLOTS_MAX;
  const newBtn = canAdd
    ? `<button class="lt-btn lt-new" data-action="layout-new" title="Create a new layout slot">+ New layout</button>`
    : `<button class="lt-btn lt-new" disabled title="Max ${LAYOUT_SLOTS_MAX} layouts — delete one first">+ New layout</button>`;

  return `
    <span class="layout-toolbar-label">Layout</span>
    ${defaultBtn}
    ${slotBtns}
    <div class="lt-sep"></div>
    ${newBtn}
    <div class="lt-sep"></div>
    <button class="lt-btn lt-save" data-action="layout-save">💾 Save</button>
    <button class="lt-btn lt-export" data-action="layout-export-json">⬇ Export JSON</button>
    <label class="lt-btn lt-import" title="Import a previously exported layout JSON" data-action="layout-import-trigger">
      ⬆ Import JSON
      <input id="lt-import-file" class="lt-import-input" type="file" accept=".json,application/json">
    </label>
    <div class="lt-sep"></div>
    <button class="lt-btn lt-hide" data-action="layout-hide-toggle" title="Manage widget visibility">👁 Hide</button>
    <button class="lt-btn lt-mini" data-action="ms-toggle" title="Open mini grid editor — drag/resize/add/remove in a sidebar">▦ Mini grid</button>
    <button class="lt-btn lt-reset" data-action="layout-reset" title="Reset the active layout to defaults">↺ Reset</button>
  `;
}

function _escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function _escapeAttr(s) { return _escapeHtml(s); }

// ── Initialise Gridstack ──
function initGridstack() {
  // Load the global hidden-widget list before _buildGridDOM so the per-widget
  // eye-off buttons render in the right initial state. _applySectionFilter
  // (called below) reads _isWidgetHidden(id) to skip these from the visible
  // grid on first paint — no flash of "all visible".
  _loadHiddenWidgets();
  const saved = localStorage.getItem(_htfKey(LS_KEY_PREFIX + 'active'));
  const name  = localStorage.getItem(_htfKey(LS_KEY_ACTIVE)) || 'default';
  if (saved) {
    if (_loadSectionSlot(saved)) {
      _activePresetName = name;
    }
  } else if (!_liveSectionLayouts) {
    _liveSectionLayouts = {
      global:       { ...GLOBAL_OVERVIEW_LAYOUT },
      'optimal-rr': { ...OPTIMAL_RR_LAYOUT },
      partials:     { ...PARTIAL_PLANNERS_LAYOUT },
    };
  }
  // Defensive cache invalidation before reading custom widget defs (Task #3.8):
  // some earlier boot code paths could have called _loadCustomWidgetDefs() with
  // an unresolved profile context (eg before activeJournalProfileId_v1 was
  // hydrated from Supabase) and cached an empty/wrong array. _injectCustomWidgetHTML
  // would then create no widget content, _buildGridDOM would wrap nothing,
  // and the user's custom widget would silently disappear after a hard refresh
  // until they re-Sync or re-create. Forcing a fresh LS read here guarantees
  // _injectCustomWidgetHTML sees the current profile's defs.
  _customWidgetDefsCache = null;
  _injectCustomWidgetHTML(); // inject user-created widgets before DOM is wrapped
  _buildGridDOM();

  _grid = GridStack.init({
    column:          COLUMN_COUNT,
    cellHeight:      ROW_HEIGHT_PX,
    margin:          5,
    draggable:       { handle: '.gs-drag-handle' },
    resizable:       { handles: 'all' },
    float:           false,
    animate:         true,
    disableDrag:     true,
    disableResize:   true,
    oneColumnModePossible: false,
  }, '#gs-container');

  _updatePresetButtons();

  // After any drag/resize, flush layout then redraw charts.
  // Drag persistence is now allowed on ALL sections.
  _grid.on('resizestop dragstop', (_e, _el) => {
    // Magnetic snap before redraw: aligns side-by-side neighbours whose edges
    // land within the threshold. Synchronous — must happen before _syncGridToLive
    // so the persisted layout reflects the snapped position.
    if (_el) _applyMagnetSnap(_grid, _el);
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        _applyAutoTypoScale();
        _redrawAll();
        _syncGridToLive();
        _saveActiveSlotLive();
      });
    });
  });

  // ResizeObserver on every grid-stack-item-content for continuous resize redraws
  // Only observe widgets that contain canvases — avoids firing on every bar-list resize
  const _canvasWidgetIds = ['w-equity','w-monthly','w-outcome','w-streak-analytics','w-r-dist','w-montecarlo'];
  const _debouncedRedrawAll = _debounce(_redrawAll, 100);
  const ro = new ResizeObserver(() => {
    // Suspended during sidebar collapse/expand: the .layout grid-template-columns
    // transition resizes every widget on every animation frame; without this guard,
    // _applyAutoTypoScale would run synchronously dozens of times during the 300ms
    // animation and freeze the UI. The sidebar toggle does one final redraw after
    // the transition settles.
    if (_isSidebarToggling) return;
    // Per-widget --typo-* override updates synchronously for live drag feedback;
    // chart redraws are debounced because they're expensive.
    _applyAutoTypoScale();
    _debouncedRedrawAll();
  });
  document.querySelectorAll('.grid-stack-item-content').forEach(el => {
    const widget = el.querySelector('[data-gs-id]') || el.closest('[data-gs-id]');
    const gsId   = widget?.getAttribute('data-gs-id') || '';
    // Observe all widgets but with higher debounce — canvases need redraw on resize
    ro.observe(el);
  });

  // Also observe the monthly wrap specifically (it's deep in the DOM)
  const mw = document.querySelector('.monthly-wrap');
  if (mw) ro.observe(mw);

  // Observe pair-session container for live resize redraws
  const psContainer = document.getElementById('pair-session-container');
  if (psContainer) ro.observe(psContainer.closest('.grid-stack-item-content') || psContainer);

  // Mark ready — render() calls are now safe
  _gsReady = true;

  // Apply the saved section layout immediately — synchronously, NOT inside a
  // requestAnimationFrame. RAF is throttled (or entirely paused) when the tab
  // is hidden/unfocused on first load, which would leave the grid stuck on
  // DEFAULT_LAYOUT until the user triggers something (e.g. re-clicks the
  // preset). skipSync: true — _liveSectionLayouts already holds the saved
  // slot loaded above; without this flag, _syncGridToLive would overwrite it
  // with the DEFAULT_LAYOUT positions that _buildGridDOM just wrote.
  _applySectionFilter(appState.ui.activeSection || 'global', { skipSync: true });

  // Safety net (Task #3.8): re-run _ensureCustomWidgetInGrid for every custom
  // widget def. If _injectCustomWidgetHTML missed any (eg cache was stale at
  // read time, or a def was added between _customWidgetDefsCache invalidation
  // and _injectCustomWidgetHTML), this catches them and creates the DOM at
  // the saved layout position. Idempotent — skips any widget already in the
  // grid. Belt-and-suspenders against the "widget vanishes after hard refresh"
  // class of bugs.
  if (typeof _loadCustomWidgetDefs === 'function' && typeof _ensureCustomWidgetInGrid === 'function') {
    try {
      _customWidgetDefsCache = null; // force fresh LS read
      for (const def of _loadCustomWidgetDefs()) {
        _ensureCustomWidgetInGrid(def);
      }
    } catch (e) {
      console.warn('[CustomWidget] initGridstack ensure DOM loop failed:', e?.message || e);
    }
  }

  // Full render after GridStack has settled — redraws canvases AND all HTML
  // widgets (the initial render() at window.load runs before GridStack moves
  // elements, so canvas sizes are 0 at that point — this second pass fixes
  // everything). Kept in RAF because canvas resize measurements need layout
  // to have flushed; if RAF is throttled, render() will run when the tab
  // becomes visible, which is fine.
  requestAnimationFrame(() => requestAnimationFrame(() => {
    _applyAutoTypoScale();
    render();
    // Boot fade-in: now that the saved layout is applied and the first full
    // render has run, reveal #main-panel. The CSS transition handles the fade.
    document.body.classList.remove('is-booting');
  }));
}

// Safety net: if anything in the boot path throws and initGridstack never
// reaches its final render, drop the booting class anyway so the user isn't
// stuck staring at a hidden main panel. 2s is well past the normal init time.
setTimeout(() => {
  if (document.body.classList.contains('is-booting')) {
    document.body.classList.remove('is-booting');
  }
}, 2000);

function initShareGridstack() {
  if (_svGsReady) return;

  // Share view is a static CSS grid — no GridStack instance.
  // Keep _svGrid null so edit-mode toggles are no-ops for this view.
  _svGrid = null;

  const exportRoot = document.getElementById('sv-export');
  if (!exportRoot) return;

  // Redraw on container resize so the equity canvas reflows with the layout.
  const ro = new ResizeObserver(_debounce(() => {
    // Suppress while exporting: the capture pipeline intentionally mutates
    // widget heights/overflow, which would otherwise retrigger a full share
    // re-render mid-export and flip hidden micro-charts back on.
    if (_svExporting) return;
    if (currentView === 'share') renderShareView();
  }, 100));
  ro.observe(exportRoot);
  exportRoot.querySelectorAll('.sv-gs-widget').forEach(el => ro.observe(el));

  _svGsReady = true;
}

// ── Toggle Edit Mode ──
function toggleEditMode() {
  _editMode = !_editMode;
  const btns    = document.querySelectorAll('.layout-edit-btn');
  const toolbar = document.getElementById('layout-toolbar');
  const gs      = document.getElementById('gs-container');
  const svGs    = document.getElementById('sv-gs-container');

  btns.forEach(btn => btn.classList.toggle('active', _editMode));
  toolbar?.classList.toggle('visible', _editMode);
  gs?.classList.toggle('gs-editing', _editMode);
  svGs?.classList.toggle('gs-editing', _editMode);
  // Signal edit mode to the sidebar (not inside #gs-container) so the filter
  // reorder affordance (grab cursor + ⠿ handle) surfaces there too.
  document.body.classList.toggle('layout-edit-mode', _editMode);
  _syncFilterSortablesEnabled();

  // Update dot color via active class (icon-only button)

  if (_editMode) {
    _suppressDirty = true;
    _grid.enableMove(true);
    _grid.enableResize(true);
    _svGrid?.enableMove(true);
    _svGrid?.enableResize(true);
    _mc2ApplySectionLayout();
    _mc2InitSectionLayoutEdit();
    _poInternalApplyLayout();
    _poInternalInitEdit();
    // Release after 2 rAFs — matches the resizestop/dragstop double-rAF window so
    // any GridStack events fired by enableMove/enableResize don't set dirty.
    requestAnimationFrame(() => requestAnimationFrame(() => { _suppressDirty = false; }));
    _showToast(currentView === 'share'
      ? 'Share layout edit ON — drag ⠿ to move · corner to resize'
      : 'Edit mode ON — drag ⠿ to move · corner to resize');
  } else {
    _suppressDirty = true;
    _grid.enableMove(false);
    _grid.enableResize(false);
    _svGrid?.enableMove(false);
    _svGrid?.enableResize(false);
    _mc2ApplySectionLayout();
    _poInternalApplyLayout();
    _saveSectionSlot('active');
    _saveCurrentShareLayout();
    requestAnimationFrame(() => requestAnimationFrame(() => { _suppressDirty = false; }));
    _showToast(currentView === 'share' ? 'Share layout saved' : 'Edit mode OFF');
    // Full render after edit mode disables so all widgets are up to date
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (currentView === 'share') renderShareView();
      else render();
    }));
  }

  _updatePresetButtons();
}

