function buildTypographyControls() {
  const container = document.getElementById('tp-typography');
  if (!container) return;
  container.innerHTML = '';

  const computed = getComputedStyle(document.documentElement);

  TYPO_GROUPS.forEach(group => {
    const groupEl = document.createElement('div');
    groupEl.className = 'tp-typo-group';

    const groupLabel = document.createElement('div');
    groupLabel.className = 'tp-typo-group-label';
    groupLabel.textContent = group.label;
    groupEl.appendChild(groupLabel);

    const sub = document.createElement('div');
    sub.className = 'tp-typo-sub';

    group.sliders.forEach(sliderData => {
      const cssVars = Array.isArray(sliderData.cssVar) ? sliderData.cssVar : [sliderData.cssVar];
      const primaryVar = cssVars[0];
      const decimals = sliderData.decimals || 0;

      const fmtVal = (num) => sliderData.unit === 'px'
        ? num.toFixed(0) + 'px'
        : num.toFixed(decimals);
      const parseStored = (raw) => parseFloat(raw) || sliderData.min;

      const row = document.createElement('div');
      row.className = 'tp-row';

      const label = document.createElement('div');
      label.className = 'tp-row-label';
      label.textContent = sliderData.label;

      const input = document.createElement('input');
      input.type = 'range';
      input.min  = sliderData.min;
      input.max  = sliderData.max;
      input.step = sliderData.step || 1;

      const rawVal = computed.getPropertyValue(primaryVar).trim();
      const currentValue = parseStored(rawVal);
      input.value = currentValue;

      const valueDisplay = document.createElement('div');
      valueDisplay.className = 'tp-value';
      valueDisplay.textContent = fmtVal(currentValue);

      const resetBtn = document.createElement('button');
      resetBtn.type = 'button';
      resetBtn.className = 'tp-color-reset';
      resetBtn.textContent = '↺';

      const applyValue = (numericVal) => {
        const num = parseFloat(numericVal);
        const val = fmtVal(num);
        cssVars.forEach(v => {
          document.documentElement.style.setProperty(v, val);
          currentTheme[v] = val;
        });
        input.value = num;
        valueDisplay.textContent = val;
        if (primaryVar === '--typo-kpi-val-size') {
          document.documentElement.style.setProperty('--fs-kpi', val);
          currentTheme['--fs-kpi'] = val;
        }
        if (primaryVar === '--typo-topbar-val-size') {
          document.documentElement.style.setProperty('--fs-stat', val);
          currentTheme['--fs-stat'] = val;
        }
        if (primaryVar === '--typo-base-size') {
          document.documentElement.style.setProperty('--fs-body', val);
          currentTheme['--fs-body'] = val;
        }
        syncResetBtn();
        document.dispatchEvent(new CustomEvent('themeTypoChanged'));
      };

      // THEME_DEFAULT may alias a typo var to another (e.g. 'var(--typo-chart-axis-size)');
      // resolve chained var() references to a concrete numeric baseline.
      const resolveBaselineNumeric = () => {
        let val = _baselineColor(primaryVar);
        const seen = new Set();
        while (typeof val === 'string' && /^var\(/.test(val.trim())) {
          const m = val.match(/var\(\s*(--[\w-]+)/);
          if (!m || seen.has(m[1])) break;
          seen.add(m[1]);
          val = _baselineColor(m[1]);
        }
        return parseStored(val);
      };

      const syncResetBtn = () => {
        const baseNum = resolveBaselineNumeric();
        // Authoritative current value: prefer currentTheme, but if it's a var()
        // alias (or missing), read the live resolved value from computed style.
        const storedRaw = currentTheme[primaryVar];
        const liveRaw = getComputedStyle(document.documentElement).getPropertyValue(primaryVar).trim();
        const sourceRaw = (storedRaw && !/^var\(/.test(String(storedRaw).trim())) ? storedRaw : liveRaw;
        const curNum = parseFloat(sourceRaw);
        // Tolerance = half-step (sliders with step=1 snap fractional defaults
        // like 7.5px to integers and would otherwise report a false "modified").
        const tolerance = Math.max(parseFloat(sliderData.step || 1), 1e-6) * 0.5 + 1e-6;
        const isDefault = !isNaN(curNum) && Math.abs(baseNum - curNum) <= tolerance;
        resetBtn.classList.toggle('is-default', isDefault);
        resetBtn.title = `Reset to ${fmtVal(baseNum)}`;
      };

      input.addEventListener('input', e => applyValue(e.target.value));
      resetBtn.addEventListener('click', () => applyValue(resolveBaselineNumeric()));
      syncResetBtn();

      row.appendChild(label);
      row.appendChild(input);
      row.appendChild(valueDisplay);
      row.appendChild(resetBtn);
      sub.appendChild(row);
    });

    groupEl.appendChild(sub);
    container.appendChild(groupEl);
  });
}


// ── Apply a layout object {id: {x,y,w,h}} ──
function _applyLayout(layout) {
  if (!_grid) return;
  _grid.batchUpdate();
  _grid.getGridItems().forEach(item => {
    const id = item.getAttribute('gs-id');
    const d  = layout[id];
    if (d) _grid.update(item, { x: d.x, y: d.y, w: d.w, h: d.h });
  });
  _grid.commit();
  _applyAutoTypoScale();
  // Full render — let GridStack finalize pixel positions, then repopulate everything
  requestAnimationFrame(() => requestAnimationFrame(render));
}

function _applyShareLayout(layout, opts = {}) {
  if (!_svGrid) return;
  _svGrid.batchUpdate();
  _svGrid.getGridItems().forEach(item => {
    const id = item.getAttribute('gs-id');
    const d = layout[id];
    if (d) _svGrid.update(item, { x: d.x, y: d.y, w: d.w, h: d.h });
  });
  _svGrid.commit();
  if (opts.rerender !== false) {
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (currentView === 'share') renderShareView();
    }));
  }
}

// ── Serialize current layout from Gridstack ──
function _serializeLayout() {
  const out = {};
  _grid.getGridItems().forEach(item => {
    const id = item.getAttribute('gs-id');
    const n  = item.gridstackNode;
    if (id && n) out[id] = { x: n.x, y: n.y, w: n.w, h: n.h };
  });
  return out;
}

function _serializeShareLayout() {
  const out = {};
  if (!_svGrid) return out;
  _svGrid.getGridItems().forEach(item => {
    const id = item.getAttribute('gs-id');
    const n  = item.gridstackNode;
    if (id && n) out[id] = { x: n.x, y: n.y, w: n.w, h: n.h };
  });
  return out;
}

function _applySerializedLayout(data) {
  _applyLayout(data);
}

// ── Save layout to localStorage ──
function _saveCurrentLayout(key) {
  const layout = _serializeLayout();
  debugLog('[layout-save] items', layout);
  debugLog('[layout-save] dynamic widgets', _serializeDynamicWidgets());
  localStorage.setItem(_htfKey(LS_KEY_PREFIX + key), JSON.stringify(layout));
  if (key !== 'active') localStorage.setItem(_htfKey(LS_KEY_ACTIVE), key);
}

function _saveCurrentShareLayout() {
  if (!_svGrid) return;
  localStorage.setItem(SV_LS_KEY_ACTIVE, JSON.stringify(_serializeShareLayout()));
}

// ── Load a preset (default or custom slot) ──
function layoutLoadPreset(name) {
  _suppressDirty = true;
  try {
    if (name === 'default') {
      _activePresetName = 'default';
      localStorage.setItem(_htfKey(LS_KEY_ACTIVE), 'default');
      const savedDefault = localStorage.getItem(_htfKey(LS_KEY_PREFIX + 'default'));
      if (savedDefault && _loadSectionSlot(savedDefault)) {
        // Loaded user's saved default.
      } else {
        const customLayouts = _defaultCustomWidgetLayouts();
        _liveSectionLayouts = {
          global:       { ...GLOBAL_OVERVIEW_LAYOUT, ...customLayouts },
          'optimal-rr': { ...OPTIMAL_RR_LAYOUT },
          partials:     { ...PARTIAL_PLANNERS_LAYOUT },
        };
      }
      _applySectionFilter(appState.ui.activeSection || 'global', { skipSync: true });
      _saveSectionSlot('active');
    } else {
      const raw = localStorage.getItem(_htfKey(LS_KEY_PREFIX + name));
      if (!raw) { _showToast(`No layout: "${name}"`, 'warn'); return; }
      if (!_loadSectionSlot(raw)) { _showToast('Corrupt layout data', 'warn'); return; }
      _activePresetName = name;
      localStorage.setItem(_htfKey(LS_KEY_ACTIVE), name);
      _applySectionFilter(appState.ui.activeSection || 'global', { skipSync: true });
      _saveSectionSlot('active');
    }
  } finally {
    _suppressDirty = false;
  }
  // Dirty state is per-preset — _dirtyPresets is NOT cleared here.
  // Each preset remembers its own unsaved state across switches.
  _updatePresetButtons();
  _showToast(name === 'default' ? 'Layout: default' : `Layout: ${name}`);
}

// ── Create a new layout slot with an auto-generated name ──
// Snapshots the current live section layouts into the new slot. User can rename
// it afterwards via right-click on the slot button.
function layoutNew() {
  const slots = _getCustomSlots();
  if (slots.length >= LAYOUT_SLOTS_MAX) {
    _showToast(`Max ${LAYOUT_SLOTS_MAX} layouts — delete one first`, 'warn');
    return;
  }

  // Find the first unused "Layout N" name
  const used = new Set(slots.map(s => s.toLowerCase()));
  let n = 1;
  let name;
  do {
    name = `Layout ${n}`;
    n++;
  } while (used.has(name.toLowerCase()) && n < 100);

  const res = _addCustomSlot(name);
  if (!res.ok) { _showToast(`Max ${LAYOUT_SLOTS_MAX} layouts`, 'warn'); return; }

  // New layout starts as a copy of the default layout (factory defaults + current custom widgets).
  _suppressDirty = true;
  try {
    const customLayouts = _defaultCustomWidgetLayouts();
    _liveSectionLayouts = {
      global:       { ...GLOBAL_OVERVIEW_LAYOUT, ...customLayouts },
      'optimal-rr': { ...OPTIMAL_RR_LAYOUT },
      partials:     { ...PARTIAL_PLANNERS_LAYOUT },
    };
    _applySectionFilter(appState.ui.activeSection || 'global', { skipSync: true });
    _saveSectionSlot(name, { skipSync: true });
    // Write initial checkpoint so Reset has a target from day one.
    const payload = localStorage.getItem(_htfKey(LS_KEY_PREFIX + name));
    if (payload) localStorage.setItem(_htfKey(LS_KEY_CKPT_PREFIX + name), payload);
    _activePresetName = name;
    localStorage.setItem(_htfKey(LS_KEY_ACTIVE), name);
    delete _dirtyPresets[name];
  } finally {
    _suppressDirty = false;
  }
  _rebuildLayoutToolbar();
  // Double-rAF: clears any dirty that a pending async GridStack event may have set.
  requestAnimationFrame(() => requestAnimationFrame(() => {
    delete _dirtyPresets[name];
    _updatePresetButtons();
  }));
  _showToast(`Created: "${name}"`);
}

// ── Delete a custom slot (called after confirm) ──
function layoutDeleteSlot(name) {
  _removeCustomSlot(name);
  delete _dirtyPresets[name];
  localStorage.removeItem(_htfKey(LS_KEY_CKPT_PREFIX + name));
  if (_activePresetName === name) {
    _activePresetName = 'default';
    localStorage.setItem(_htfKey(LS_KEY_ACTIVE), 'default');
  }
  _rebuildLayoutToolbar();
  _showToast(`Deleted: "${name}"`);
}

// ── Rename a custom slot (preserves slot order and content) ──
function layoutRenameSlot(oldName, newName) {
  newName = (newName || '').trim().slice(0, 24);
  if (!newName) { _showToast('Name cannot be empty', 'warn'); return; }
  if (newName === oldName) return;
  if (newName.toLowerCase() === 'default') { _showToast('"default" is reserved', 'warn'); return; }
  const slots = _getCustomSlots();
  if (slots.includes(newName)) { _showToast(`"${newName}" already exists`, 'warn'); return; }
  const idx = slots.indexOf(oldName);
  if (idx === -1) return;
  // Move the layout data under the new key, preserve slot position
  const raw = localStorage.getItem(_htfKey(LS_KEY_PREFIX + oldName));
  if (raw) {
    localStorage.setItem(_htfKey(LS_KEY_PREFIX + newName), raw);
    localStorage.removeItem(_htfKey(LS_KEY_PREFIX + oldName));
  }
  slots[idx] = newName;
  _setCustomSlots(slots);
  // Migrate checkpoint and dirty flag to the new name.
  const ckpt = localStorage.getItem(_htfKey(LS_KEY_CKPT_PREFIX + oldName));
  if (ckpt) {
    localStorage.setItem(_htfKey(LS_KEY_CKPT_PREFIX + newName), ckpt);
    localStorage.removeItem(_htfKey(LS_KEY_CKPT_PREFIX + oldName));
  }
  if (_dirtyPresets[oldName]) {
    _dirtyPresets[newName] = true;
    delete _dirtyPresets[oldName];
  }
  if (_activePresetName === oldName) {
    _activePresetName = newName;
    localStorage.setItem(_htfKey(LS_KEY_ACTIVE), newName);
  }
  _rebuildLayoutToolbar();
  _showToast(`Renamed: "${newName}"`);
}

// ── Save the current layout to all views (active slot + named preset) ──
function layoutSave() {
  _syncGridToLive();
  _saveSectionSlot('active');
  const name = _activePresetName;
  if (name) {
    _saveSectionSlot(name);
    // Write the checkpoint — this is what Reset will restore to.
    const payload = localStorage.getItem(_htfKey(LS_KEY_PREFIX + name));
    if (payload) localStorage.setItem(_htfKey(LS_KEY_CKPT_PREFIX + name), payload);
  }
  delete _dirtyPresets[name];
  _updatePresetButtons();
  const label = (name && name !== 'default') ? `Saved: "${name}"` : 'Saved';
  _flashSaveBadge(label);
}

let _saveBadgeTimer = null;
function _flashSaveBadge(text = 'Saved') {
  const btn = document.querySelector('#layout-toolbar .lt-btn.lt-save');
  if (!btn) return;
  let badge = document.getElementById('lt-save-badge');
  if (!badge) {
    badge = document.createElement('span');
    badge.id = 'lt-save-badge';
    badge.className = 'lt-save-badge';
    document.body.appendChild(badge);
  }
  badge.textContent = `✓ ${text}`;
  const r = btn.getBoundingClientRect();
  badge.style.left = `${Math.round(r.left + r.width / 2)}px`;
  badge.style.top  = `${Math.round(r.bottom + 6)}px`;
  badge.classList.add('is-visible');
  clearTimeout(_saveBadgeTimer);
  _saveBadgeTimer = setTimeout(() => badge.classList.remove('is-visible'), 1800);
}

// ── Reset the active layout to the last manually saved state ──
// If the preset has no unsaved changes (no dirty badge), Reset does nothing.
// If the preset has a manual save, restores it; otherwise falls back to factory defaults.
function layoutReset() {
  const name = _activePresetName;
  if (!_dirtyPresets[name]) {
    _showToast('Nothing to reset — layout is already saved');
    return;
  }
  _suppressDirty = true;
  try {
    // "default" always resets to factory defaults — no checkpoint.
    // Named presets restore from their checkpoint (last manual Save); fall back to factory defaults.
    const isDefault = !name || name === 'default';
    const ckptRaw = !isDefault ? localStorage.getItem(_htfKey(LS_KEY_CKPT_PREFIX + name)) : null;
    let restored = false;
    if (ckptRaw) {
      try {
        const parsed = JSON.parse(ckptRaw);
        const data = _isLegacySlot(parsed) ? _migrateLegacySlot(parsed) : parsed;
        _liveSectionLayouts = {
          global:       { ...GLOBAL_OVERVIEW_LAYOUT, ...(data.global       || {}) },
          'optimal-rr': { ...OPTIMAL_RR_LAYOUT,      ...(data['optimal-rr'] || {}) },
          partials:     { ...PARTIAL_PLANNERS_LAYOUT, ...(data.partials     || {}) },
        };
        restored = true;
      } catch { /* corrupt checkpoint — fall through to factory defaults */ }
    }
    if (!restored) {
      const customLayouts = isDefault ? _defaultCustomWidgetLayouts() : _defaultCustomWidgetLayouts();
      _liveSectionLayouts = {
        global:       { ...GLOBAL_OVERVIEW_LAYOUT, ...customLayouts },
        'optimal-rr': { ...OPTIMAL_RR_LAYOUT },
        partials:     { ...PARTIAL_PLANNERS_LAYOUT },
      };
    }
    _saveSectionSlot('active', { skipSync: true });
    if (name) _saveSectionSlot(name, { skipSync: true });
    _applySectionFilter(appState.ui.activeSection || 'global', { skipSync: true });
    delete _dirtyPresets[name];
  } finally {
    _suppressDirty = false;
  }
  _showToast(name && name !== 'default' ? `Reset: "${name}"` : 'Reset to default');
  _updatePresetButtons();
  requestAnimationFrame(() => requestAnimationFrame(() => {
    delete _dirtyPresets[name];
    _updatePresetButtons();
  }));
}

// ── Export current layout as a downloadable JSON file ──
function layoutExportJSON() {
  const layout = _serializeSectionLayouts();
  const name   = (_activePresetName || 'layout').replace(/\s+/g, '_');
  const payload = JSON.stringify({ name, layout, schema: 'sections-v2' }, null, 2);
  const blob    = new Blob([payload], { type: 'application/json' });
  const url     = URL.createObjectURL(blob);
  const a       = document.createElement('a');
  a.href        = url;
  a.download    = `dashboard_layout_${name}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  _showToast(`Exported: dashboard_layout_${name}.json`);
}

// ── Import a layout JSON file and apply it ──
function layoutImportJSON(input) {
  const file = input?.files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const parsed = JSON.parse(e.target.result);
      const layout = parsed.layout || parsed;
      const name   = parsed.name || file.name.replace(/\.json$/i, '').replace(/_/g, ' ');
      if (typeof layout !== 'object' || Array.isArray(layout)) {
        _showToast('Invalid layout file', 'warn'); return;
      }
      if (!_loadSectionSlot(JSON.stringify(layout))) {
        _showToast('Could not load layout', 'warn'); return;
      }
      _activePresetName = name;
      // Apply layout to grid BEFORE saving — same ordering fix as layoutLoadPreset.
      _applySectionFilter(appState.ui.activeSection || 'global', { skipSync: true });
      _saveSectionSlot('active');
      delete _dirtyPresets[name];
      _updatePresetButtons();
      _showToast(`Imported: "${name}"`);
    } catch(err) {
      _showToast('Could not parse JSON file', 'warn');
    } finally {
      input.value = '';
    }
  };
  reader.readAsText(file);
}

// ── Highlight active preset button ──
function _updatePresetButtons() {
  document.querySelectorAll('.lt-preset-btn').forEach(btn => {
    const isActive = btn.dataset.name === _activePresetName;
    btn.classList.toggle('active', isActive);
    btn.classList.toggle('lt-modified', !!_dirtyPresets[btn.dataset.name]);
  });
  // Reset button is only useful when the active preset has unsaved changes.
  const resetBtn = document.querySelector('#layout-toolbar .lt-btn.lt-reset');
  if (resetBtn) {
    resetBtn.disabled = !_dirtyPresets[_activePresetName];
    const isDefault = !_activePresetName || _activePresetName === 'default';
    resetBtn.textContent = isDefault ? '↺ Factory' : '↺ Reset';
  }
}

// ── Rebuild toolbar HTML (called when slots change) ──
function _rebuildLayoutToolbar() {
  const toolbar = document.getElementById('layout-toolbar');
  if (!toolbar) return;
  toolbar.innerHTML = _buildToolbarHTML();
  _updatePresetButtons();
}

// ── Themed context menu shown on right-click of a slot ──
function _showLayoutSlotMenu(name, anchorRect) {
  _closeLayoutSlotMenu();

  const menu = document.createElement('div');
  menu.id = 'layout-slot-menu';
  menu.className = 'layout-slot-menu';
  menu.innerHTML = `
    <button class="layout-slot-menu-item" type="button" data-act="rename">
      <span class="lsm-icon">✎</span><span>Rename</span>
    </button>
    <div class="layout-slot-menu-sep"></div>
    <button class="layout-slot-menu-item lsm-danger" type="button" data-act="delete">
      <span class="lsm-icon">✕</span><span>Delete</span>
    </button>
  `;
  document.body.appendChild(menu);

  // Position: below the slot button, clamped to viewport
  const mw = menu.offsetWidth;
  const mh = menu.offsetHeight;
  let left = anchorRect.left;
  let top  = anchorRect.bottom + 4;
  if (left + mw > window.innerWidth - 8)  left = window.innerWidth - mw - 8;
  if (top  + mh > window.innerHeight - 8) top  = anchorRect.top - mh - 4;
  menu.style.left = Math.max(8, left) + 'px';
  menu.style.top  = Math.max(8, top)  + 'px';

  menu.addEventListener('click', e => {
    const btn = e.target.closest('.layout-slot-menu-item');
    if (!btn) return;
    const act = btn.dataset.act;
    _closeLayoutSlotMenu();
    if (act === 'rename') _showLayoutRenamePrompt(name);
    else if (act === 'delete') _showLayoutDeleteConfirm(name);
  });
}

function _closeLayoutSlotMenu() {
  document.getElementById('layout-slot-menu')?.remove();
}

// ── Themed prompt modal for slot rename ──
function _showLayoutRenamePrompt(oldName) {
  document.getElementById('layout-confirm-backdrop')?.remove();

  const backdrop = document.createElement('div');
  backdrop.id = 'layout-confirm-backdrop';
  backdrop.className = 'layout-confirm-backdrop';
  backdrop.innerHTML = `
    <div class="layout-confirm-modal layout-confirm-modal-rename" role="dialog" aria-modal="true">
      <div class="layout-confirm-head layout-confirm-head-neutral">
        <span class="layout-confirm-icon layout-confirm-icon-neutral">✎</span>
        <span class="layout-confirm-title">Rename layout</span>
      </div>
      <div class="layout-confirm-body">
        <div class="layout-confirm-sub" style="margin-bottom:8px">Current name: <span class="layout-confirm-name">"${_escapeHtml(oldName)}"</span></div>
        <input class="lt-preset-input layout-rename-input" id="layout-rename-input" type="text" maxlength="24" value="${_escapeAttr(oldName)}" />
      </div>
      <div class="layout-confirm-actions">
        <button class="lt-btn layout-confirm-cancel" type="button">Cancel</button>
        <button class="lt-btn lt-save layout-confirm-ok" type="button">Rename</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);

  const input = backdrop.querySelector('#layout-rename-input');
  input.focus();
  input.select();

  const close = () => { backdrop.remove(); document.removeEventListener('keydown', onKey); };
  const commit = () => { const v = input.value; close(); layoutRenameSlot(oldName, v); };
  backdrop.addEventListener('click', e => { if (e.target === backdrop) close(); });
  backdrop.querySelector('.layout-confirm-cancel').addEventListener('click', close);
  backdrop.querySelector('.layout-confirm-ok').addEventListener('click', commit);
  const onKey = e => {
    if (e.key === 'Escape') close();
    else if (e.key === 'Enter') commit();
  };
  document.addEventListener('keydown', onKey);
}

// ── Themed confirm modal for slot deletion ──
function _showLayoutDeleteConfirm(name) {
  document.getElementById('layout-confirm-backdrop')?.remove();

  const backdrop = document.createElement('div');
  backdrop.id = 'layout-confirm-backdrop';
  backdrop.className = 'layout-confirm-backdrop';
  backdrop.innerHTML = `
    <div class="layout-confirm-modal" role="dialog" aria-modal="true">
      <div class="layout-confirm-head">
        <span class="layout-confirm-icon">⚠</span>
        <span class="layout-confirm-title">Delete layout</span>
      </div>
      <div class="layout-confirm-body">
        Delete saved layout <span class="layout-confirm-name">"${_escapeHtml(name)}"</span>?
        <div class="layout-confirm-sub">This action cannot be undone.</div>
      </div>
      <div class="layout-confirm-actions">
        <button class="lt-btn layout-confirm-cancel" type="button">Cancel</button>
        <button class="lt-btn lt-reset layout-confirm-ok" type="button">Delete</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);

  const close = () => { backdrop.remove(); document.removeEventListener('keydown', onKey); };
  backdrop.addEventListener('click', e => { if (e.target === backdrop) close(); });
  backdrop.querySelector('.layout-confirm-cancel').addEventListener('click', close);
  backdrop.querySelector('.layout-confirm-ok').addEventListener('click', () => {
    close();
    layoutDeleteSlot(name);
  });
  const onKey = e => {
    if (e.key === 'Escape') close();
    else if (e.key === 'Enter') { close(); layoutDeleteSlot(name); }
  };
  document.addEventListener('keydown', onKey);
}

// ── Right-click delegation on the layout toolbar: show Rename/Delete menu ──
document.addEventListener('contextmenu', e => {
  const btn = e.target.closest('.lt-preset-slot');
  if (!btn) return;
  e.preventDefault();
  _showLayoutSlotMenu(btn.dataset.name, btn.getBoundingClientRect());
});

// Close the slot menu on outside click / scroll / Escape
document.addEventListener('click', e => {
  if (!e.target.closest('#layout-slot-menu')) _closeLayoutSlotMenu();
}, true);
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') _closeLayoutSlotMenu();
});
window.addEventListener('scroll', _closeLayoutSlotMenu, true);
window.addEventListener('resize', _closeLayoutSlotMenu);

// ── Redraw all canvas-based charts ──
function _redrawAll() {
  // Don't attempt redraws while GridStack is still moving widgets into containers
  if (!_gsReady) return;
  try {
    // Force a layout flush so getBoundingClientRect() returns accurate sizes
    // before any canvas tries to measure its container.
    document.getElementById('gs-container')?.getBoundingClientRect();
    const filtered = getFiltered();
    const stats    = calcStats(filtered);
    if (!stats) return;
    drawCharts(filtered);
    drawMonthly(filtered);
    drawDonut(stats);
    renderPairSession(filtered);
    // renderHeatmap reads container.clientHeight to size cells/fonts. On first
    // load the initial render() runs before GridStack writes final widget
    // heights, so clientHeight is 0 → fontSize falls back to 7 (tiny). Without
    // this re-render the heatmap stays tiny until a manual button click. The
    // ResizeObserver fires _redrawAll once layout settles, so reading
    // clientHeight here returns the real value and the heatmap renders normally.
    renderHeatmap(filtered);
    // Same auto-sizing concern as renderHeatmap: renderCalendar reads
    // grid.clientWidth/Height to compute cell + font sizes. Without this
    // re-render, the calendar stays at its initial (possibly tiny) sizing
    // until the user clicks a calendar control.
    renderCalendar(filtered);
    // Refit custom widgets too — the ResizeObserver fires _redrawAll on every
    // GridStack resize, and the custom donut/heatmap/bars all read
    // getBoundingClientRect() to size themselves. Without this call the
    // custom donut canvas stays frozen at its first-render dimensions and
    // doesn't grow/shrink like the built-in Outcome Breakdown.
    renderAllCustomWidgets(filtered);
    // Refit performance bar widgets to the new widget heights. We don't
    // re-render their HTML (children counts haven't changed) — just recompute
    // the row-height + font-size CSS vars from the current container size.
    ['bars-setup','bars-session','bars-pair','bars-day','bars-obs','bars-h4obs','bars-hour'].forEach(id => {
      const c = document.getElementById(id);
      if (c && c.children.length) _fitBarList(id, c.children.length);
    });
    _fitAllStatsOverviewMicros();
  } catch(e) { /* safety net */ }
}

// ── Debounce helper ──
function _debounce(fn, ms) {
  let t;
  return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };
}

// ── Toast notification ──
function _showToast(msg, type) {
  let toast = document.getElementById('layout-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'layout-toast';
    toast.style.cssText = `
      position:fixed; bottom:24px; right:24px; z-index:9999;
      padding:8px 14px; border-radius:4px;
      font-family:'DM Mono',monospace; font-size:11px;
      background:var(--bg1); border:1px solid var(--line2); color:var(--body);
      box-shadow:0 4px 18px rgba(0,0,0,.5); transition:opacity .25s;
      pointer-events:none;
    `;
    document.body.appendChild(toast);
  }
  toast.textContent = msg;
  toast.style.borderColor = type === 'warn' ? 'var(--r)' : 'color-mix(in srgb, var(--gold) 40%, transparent)';
  toast.style.color = type === 'warn' ? 'var(--r)' : 'var(--gold)';
  toast.style.opacity = '1';
  clearTimeout(toast._t);
  toast._t = setTimeout(() => toast.style.opacity = '0', 2200);
}

// ── Inject "Edit Layout" button in topbar ──
function _injectEditButton() {
  const topRight = document.querySelector('.topbar-right');
  if (!topRight) return;
  const wrap = document.createElement('div');
  wrap.id = 'layout-edit-wrap';
  wrap.className = 'layout-edit-wrap';
  const btn = document.createElement('button');
  btn.id        = 'layout-edit-btn';
  btn.className = 'layout-edit-btn';
  btn.title     = 'Toggle layout edit mode  [shortcut: E]';
  btn.dataset.action = 'toggle-layout-edit';
  btn.innerHTML = `<span class="lei-dot"></span><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/></svg>`;
  wrap.appendChild(btn);
  // Insert before theme button
  const moreWrap = topRight.querySelector('.topbar-more-wrap');
  topRight.insertBefore(wrap, moreWrap || null);
}

// ── Keyboard shortcut: E = toggle edit mode (only when no input focused) ──
document.addEventListener('keydown', e => {
  if (e.key === 'e' || e.key === 'E') {
    const tag = document.activeElement?.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
    toggleEditMode();
  }
});

// ── Bootstrap ──
// ══════════════════════════════════════════════════════
// MOBILE VIEW
// ══════════════════════════════════════════════════════
const _isMobile = () => window.innerWidth < 768;

// ── Mobile KPI update ──
function updateMobileStats(stats) {
  if (!_isMobile()) return;
  const s = document.getElementById;
  if (!stats) {
    ['mk-n','mk-wr','mk-ev','mk-tot','mk-pf','mk-dd','mk-ws','mk-ls','mk-be']
      .forEach(id => { const el = document.getElementById(id); if(el) el.textContent = '—'; });
    return;
  }
  const totN = appState.trades.totalOverride !== null ? appState.trades.totalOverride : appState.trades.items.length;
  const beTot = stats.be_tp + stats.be_sl;

  const set = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  set('mk-n',   stats.n);
  set('mk-n-s', `of ${totN} · ${stats.w}W ${stats.l}L`);
  set('mk-wr',  stats.wr.toFixed(1) + '%');
  set('mk-wr-s', `${stats.w}W / ${stats.l}L`);
  set('mk-ev',  (stats.ev >= 0 ? '+' : '') + stats.ev.toFixed(3) + 'R');
  set('mk-tot', (stats.totalR >= 0 ? '+' : '') + stats.totalR.toFixed(1) + 'R');
  set('mk-pf',  stats.pf >= 9.99 ? '∞' : stats.pf.toFixed(3));
  set('mk-pf-s', stats.pf >= 1.5 ? 'Positive ✓' : stats.pf >= 1 ? 'Borderline' : 'Negative ✗');
  set('mk-dd',  stats.maxDD.toFixed(1) + 'R');
  set('mk-ws',  stats.maxW);
  set('mk-ls',  stats.maxL);
  set('mk-be',  beTot);
  set('mk-be-s', (beTot / stats.n * 100).toFixed(0) + '% · TP:' + stats.be_tp + ' SL:' + stats.be_sl);

  // Dynamic colours
  const wrCell = document.querySelector('#mob-kpi-grid [data-kpi="win-rate"]');
  const wrVal  = document.getElementById('mk-wr');
  if (wrCell && wrVal) {
    const ok = stats.wr >= 50;
    wrCell.className = 'mob-kpi-cell ' + (ok ? 'c-green' : 'c-red');
    wrVal.className  = 'mob-kpi-value ' + (ok ? 'v-green' : 'v-red');
  }
  const totCell = document.querySelector('#mob-kpi-grid [data-kpi="total-r"]');
  const totVal  = document.getElementById('mk-tot');
  if (totCell && totVal) {
    const ok = stats.totalR >= 0;
    totCell.className = 'mob-kpi-cell ' + (ok ? 'c-green' : 'c-red');
    totVal.className  = 'mob-kpi-value ' + (ok ? 'v-green' : 'v-red');
  }

}

// ── Mobile equity chart ──
let _mobEqChart = null;
// Mobile equity crosshair state
let _mobEqTrades = [];
let _mobEqCrosshair = -1;

function _drawMobileEquityFrame(canvas, trades, crosshairIdx) {
  const ctx  = canvas?.getContext?.('2d');
  if (!canvas || !ctx) return;
  const W    = parseInt(canvas.style.width)  || canvas.width  / window.devicePixelRatio;
  const H    = parseInt(canvas.style.height) || canvas.height / window.devicePixelRatio;

  ctx.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0);
  ctx.clearRect(0, 0, W, H);

  if (!trades.length) return;

  const tpConfig = appState.ui.tpConfig;
  let eq = 0;
  const curve = trades.map(t => { eq += computeEffectiveRR(t, tpConfig); return eq; });
  const mn = Math.min(0, ...curve);
  const mx = Math.max(0, ...curve);
  const range = mx - mn || 1;
  const pad = { t: 16, b: 24, l: 42, r: 10 };
  const cW = W - pad.l - pad.r;
  const cH = H - pad.t - pad.b;

  const px = i => pad.l + (i / (curve.length - 1 || 1)) * cW;
  const py = v => pad.t + cH - ((v - mn) / range) * cH;

  // Zero line
  ctx.strokeStyle = tc('--line2');
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 4]);
  ctx.beginPath();
  ctx.moveTo(pad.l, py(0));
  ctx.lineTo(pad.l + cW, py(0));
  ctx.stroke();
  ctx.setLineDash([]);

  // Fill
  const grad = ctx.createLinearGradient(0, pad.t, 0, pad.t + cH);
  grad.addColorStop(0, 'rgba(38,166,154,0.22)');
  grad.addColorStop(1, 'rgba(38,166,154,0.02)');
  ctx.beginPath();
  curve.forEach((v, i) => i === 0 ? ctx.moveTo(px(i), py(v)) : ctx.lineTo(px(i), py(v)));
  ctx.lineTo(px(curve.length - 1), py(0));
  ctx.lineTo(px(0), py(0));
  ctx.closePath();
  ctx.fillStyle = grad;
  ctx.fill();

  // Line
  ctx.beginPath();
  ctx.strokeStyle = tc('--g');
  ctx.lineWidth = 1.5;
  curve.forEach((v, i) => i === 0 ? ctx.moveTo(px(i), py(v)) : ctx.lineTo(px(i), py(v)));
  ctx.stroke();

  // Y axis labels
  ctx.fillStyle = tc('--dim');
  ctx.font = '9px DM Mono, monospace';
  ctx.textAlign = 'right';
  [mn, mx].forEach(v => {
    ctx.fillText((v >= 0 ? '+' : '') + v.toFixed(1) + 'R', pad.l - 4, py(v) + 3);
  });

  // ── Crosshair ──
  if (crosshairIdx >= 0 && crosshairIdx < curve.length) {
    const ci  = crosshairIdx;
    const cx  = px(ci);
    const cy  = py(curve[ci]);
    const val = curve[ci];
    const t   = trades[ci];

    // Vertical line
    ctx.save();
    ctx.strokeStyle = tcRgba('--white', 0.35);
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(cx, pad.t);
    ctx.lineTo(cx, pad.t + cH);
    ctx.stroke();
    ctx.setLineDash([]);

    // Dot
    ctx.beginPath();
    ctx.arc(cx, cy, 4, 0, Math.PI * 2);
    ctx.fillStyle = tc('--g');
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.4)';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Tooltip
    const label   = `${t.date || ''}  ${val >= 0 ? '+' : ''}${val.toFixed(1)}R`;
    ctx.font      = 'bold 10px DM Mono, monospace';
    const tw      = ctx.measureText(label).width;
    const tPad    = 5;
    const tW      = tw + tPad * 2;
    const tH      = 18;
    let tx = cx - tW / 2;
    if (tx < pad.l) tx = pad.l;
    if (tx + tW > W - pad.r) tx = W - pad.r - tW;
    const ty = cy - tH - 8 < pad.t ? cy + 10 : cy - tH - 8;

    ctx.fillStyle = tcRgba('--bg4', 0.88);
    ctx.beginPath();
    ctx.roundRect(tx, ty, tW, tH, 3);
    ctx.fill();

    ctx.fillStyle = val >= 0 ? tc('--g') : tc('--r');
    ctx.textAlign = 'left';
    ctx.fillText(label, tx + tPad, ty + 13);
    ctx.restore();
  }
}

function drawMobileEquity(trades) {
  if (!_isMobile()) return;
  const canvas = document.getElementById('mobEquityCanvas');
  if (!canvas) return;
  const wrap = document.getElementById('mob-equity-wrap');
  if (!wrap) return;

  const W = wrap.offsetWidth || 340;
  const H = 200;
  canvas.width  = W * window.devicePixelRatio;
  canvas.height = H * window.devicePixelRatio;
  canvas.style.width  = W + 'px';
  canvas.style.height = H + 'px';

  _mobEqTrades = trades;
  _mobEqCrosshair = -1;
  _drawMobileEquityFrame(canvas, trades, -1);

  // Attach touch/mouse listeners once
  if (!canvas._mobListenersAttached) {
    canvas._mobListenersAttached = true;

    const getIdx = clientX => {
      const rect   = canvas.getBoundingClientRect();
      const W      = rect.width;
      const pad    = { l: 42, r: 10 };
      const cW     = W - pad.l - pad.r;
      const x      = clientX - rect.left - pad.l;
      const frac   = Math.max(0, Math.min(1, x / cW));
      return Math.round(frac * (_mobEqTrades.length - 1));
    };

    const onMove = e => {
      e.preventDefault();
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      _mobEqCrosshair = getIdx(clientX);
      _drawMobileEquityFrame(canvas, _mobEqTrades, _mobEqCrosshair);
    };
    const onEnd = () => {
      _mobEqCrosshair = -1;
      _drawMobileEquityFrame(canvas, _mobEqTrades, -1);
    };

    canvas.addEventListener('touchmove',  onMove, { passive: false });
    canvas.addEventListener('touchend',   onEnd);
    canvas.addEventListener('touchcancel',onEnd);
    canvas.addEventListener('mousemove',  onMove);
    canvas.addEventListener('mouseleave', onEnd);
  }
}

// ── Mobile donut — pure SVG, no canvas sizing issues ──
let _mobDonutChart = null;
function drawMobileDonut(stats) {
  if (!_isMobile()) return;
  const canvas = document.getElementById('mobDonutCanvas');
  const legend = document.getElementById('mob-donut-legend');
  if (!canvas || !legend) return;

  if (!stats) { canvas.innerHTML = ''; legend.innerHTML = ''; return; }

  const filtered = getFiltered();
  const tp    = filtered.filter(t => t.outcome === 'TP').length;
  const sl    = filtered.filter(t => t.outcome === 'SL').length;
  const betp  = filtered.filter(t => t.outcome === 'BE-TP').length;
  const besl  = filtered.filter(t => t.outcome === 'BE-SL').length;
  const total = filtered.length || 1;

  // Replace canvas with SVG donut
  const parent = canvas.parentElement;
  setVisible(canvas, false);

  // Remove old SVG if any
  let svgEl = parent.querySelector('svg.mob-donut-svg');
  if (!svgEl) {
    svgEl = document.createElementNS('http://www.w3.org/2000/svg','svg');
    svgEl.setAttribute('class','mob-donut-svg');
    svgEl.setAttribute('width','110');
    svgEl.setAttribute('height','110');
    svgEl.setAttribute('viewBox','0 0 110 110');
    parent.insertBefore(svgEl, canvas);
  }

  const cx=55, cy=55, R=48, r=30;
  const segments = [
    { v: tp,   col: tc('--g')            },
    { v: sl,   col: tc('--r')            },
    { v: betp, col: 'rgba(41,98,255,.9)'  },
    { v: besl, col: 'rgba(180,120,240,.9)'},
  ];

  let html = '';
  let angle = -Math.PI / 2;
  segments.forEach(seg => {
    if (!seg.v) return;
    const sweep = (seg.v / total) * 2 * Math.PI;
    const x1 = cx + R * Math.cos(angle), y1 = cy + R * Math.sin(angle);
    angle += sweep;
    const x2 = cx + R * Math.cos(angle), y2 = cy + R * Math.sin(angle);
    const ix1 = cx + r * Math.cos(angle - sweep), iy1 = cy + r * Math.sin(angle - sweep);
    const ix2 = cx + r * Math.cos(angle), iy2 = cy + r * Math.sin(angle);
    const lg = sweep > Math.PI ? 1 : 0;
    html += `<path d="M${x1.toFixed(2)},${y1.toFixed(2)} A${R},${R} 0 ${lg},1 ${x2.toFixed(2)},${y2.toFixed(2)} L${ix2.toFixed(2)},${iy2.toFixed(2)} A${r},${r} 0 ${lg},0 ${ix1.toFixed(2)},${iy1.toFixed(2)} Z" fill="${seg.col}" opacity="0.9"/>`;
  });
  const pct = Math.round(tp / total * 100);
  html += `<text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="middle" font-family="DM Mono,monospace" font-weight="bold" font-size="14" fill="#fff">${pct}%</text>`;
  svgEl.innerHTML = html;

  const items = [
    { label:'TP',    count:tp,   col:'var(--g)' },
    { label:'SL',    count:sl,   col:'var(--r)' },
    { label:'BE-TP', count:betp, col:'rgba(41,98,255,1)' },
    { label:'BE-SL', count:besl, col:'rgba(180,120,240,1)' },
  ];
  legend.innerHTML = items.map(it => `
    <div style="display:flex;align-items:center;gap:7px">
      <div style="width:8px;height:8px;border-radius:50%;background:${it.col};flex-shrink:0"></div>
      <span style="font-family:'DM Mono',monospace;font-size:10px;color:var(--body)">${it.label}</span>
      <span style="font-family:'DM Mono',monospace;font-size:10px;color:var(--dim);margin-left:auto">${it.count} (${(it.count/total*100).toFixed(0)}%)</span>
    </div>`).join('');
}

// ── Mobile Monthly P&L — pure HTML bars ──
let _mobMonthlyChart2 = null; // kept for compat
function drawMobileMonthly2(trades) {
  if (!_isMobile()) return;
  const wrap = document.getElementById('mob-monthly-wrap');
  if (!wrap) return;
  if (!trades.length) { wrap.innerHTML = ''; return; }

  const useTotal = barMode === 'total';
  const useN     = barMode === 'n';
  const tpConfig = appState.ui.tpConfig;
  const months = {};
  trades.forEach(t => {
    if (!t.month) return;
    if (!months[t.month]) months[t.month] = { r:0, n:0 };
    months[t.month].r += computeEffectiveRR(t, tpConfig); months[t.month].n++;
  });
  const keys = Object.keys(months).sort();
  if (!keys.length) { wrap.innerHTML = ''; return; }

  const vals = keys.map(k => {
    const d = months[k];
    return useN ? d.n : +(useTotal ? d.r : d.r/d.n).toFixed(useTotal?1:2);
  });
  const labels = keys.map(k => { const [y,m] = k.split('-'); return `${m}/${y.slice(2)}`; });

  const cG = tc('--g'), cR = tc('--r'), cA = tc('--gold'), cT = tc('--t');
  const getColBar = v => useN ? cA
    : barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : _kpiTooltipColor(v, 'avgr');
  const getColVal = v => useN ? cA
    : useTotal && barColorMode === 'binary'
      ? (v > 0 ? cG : v < 0 ? cR : cA)
      : _kpiTooltipColor(v, 'avgr');

  const posMax = useN ? Math.max(0, ...vals) : Math.max(0, ...vals);
  const negMax = useN ? 0 : Math.abs(Math.min(0, ...vals));
  const totalRange = posMax + negMax || 1;
  const posH = negMax > 0 ? Math.max(55, Math.round(posMax/totalRange*100)) : 80;
  const negH = 100 - posH;

  const bars = vals.map((v, i) => {
    const colBar = getColBar(v);
    const colVal = getColVal(v);
    const sign = useN ? String(v) : (v >= 0 ? '+' : '') + v.toFixed(useTotal?1:2) + 'R';
    if (v >= 0) {
      const pct = posMax > 0 ? (v/posMax*posH).toFixed(1) : '0';
      return `<div style="display:flex;flex-direction:column;align-items:center;flex:1;min-width:0;gap:1px">
        <div style="font-family:'DM Mono',monospace;font-size:var(--typo-micro-size,7px);color:${colVal};overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:center">${sign}</div>
        <div style="display:flex;flex-direction:column;justify-content:flex-end;height:${posH}px;width:100%">
          <div style="background:${colBar};width:100%;border-radius:2px 2px 0 0;height:${pct}px;min-height:2px"></div>
        </div>
        <div style="height:1px;background:var(--line2);width:100%"></div>
        <div style="height:${negH}px"></div>
        <div style="font-family:'DM Mono',monospace;font-size:var(--typo-micro-size,7px);color:var(--dim);text-align:center;overflow:hidden;width:100%;white-space:nowrap;text-overflow:ellipsis">${labels[i]}</div>
      </div>`;
    } else {
      const pct = negMax > 0 ? (Math.abs(v)/negMax*negH).toFixed(1) : '0';
      return `<div style="display:flex;flex-direction:column;align-items:center;flex:1;min-width:0;gap:1px">
        <div style="height:${posH}px"></div>
        <div style="height:1px;background:var(--line2);width:100%"></div>
        <div style="display:flex;flex-direction:column;justify-content:flex-start;height:${negH}px;width:100%">
          <div style="background:${colBar};width:100%;border-radius:0 0 2px 2px;height:${pct}px;min-height:2px"></div>
        </div>
        <div style="font-family:'DM Mono',monospace;font-size:var(--typo-micro-size,7px);color:${colVal};text-align:center">${sign}</div>
        <div style="font-family:'DM Mono',monospace;font-size:var(--typo-micro-size,7px);color:var(--dim);text-align:center;overflow:hidden;width:100%;white-space:nowrap;text-overflow:ellipsis">${labels[i]}</div>
      </div>`;
    }
  }).join('');

  wrap.innerHTML = `<div style="display:flex;align-items:flex-end;gap:2px;padding:8px 6px 6px;height:${posH+negH+32}px">${bars}</div>`;
}

// ── Mobile Pair — pure HTML horizontal bars ──
let _mobPairChart = null; // kept for compat
function drawMobilePair(trades) {
  if (!_isMobile()) return;
  const wrap = document.getElementById('mob-pair-wrap');
  if (!wrap) return;
  if (!trades.length) { wrap.innerHTML = ''; return; }

  const useTotal = barMode === 'total';
  const useN     = barMode === 'n';
  const tpConfig = appState.ui.tpConfig;
  const pairs = {};
  trades.forEach(t => {
    if (!t.pair) return;
    if (!pairs[t.pair]) pairs[t.pair] = { r:0, n:0 };
    pairs[t.pair].r += computeEffectiveRR(t, tpConfig); pairs[t.pair].n++;
  });
  const all = Object.entries(pairs).map(([p,v]) => ({ label:p, ev:v.r/v.n, totalR:v.r, n:v.n }));
  const valFn = d => useN ? d.n : useTotal ? d.totalR : d.ev;
  const sorted = all.sort((a,b) => valFn(b)-valFn(a));
  const absMax = useN ? (Math.max(...sorted.map(d => d.n)) || 1) : (Math.max(...sorted.map(d => Math.abs(valFn(d)))) || 1);
  const cG = tc('--g'), cR = tc('--r'), cA = tc('--gold'), cT = tc('--t');
  const getColBar = d => useN ? cA
    : barColorMode === 'binary'
      ? (d.ev>0?cG:d.ev<0?cR:cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const getColVal = d => useN ? cA
    : useTotal && barColorMode === 'binary'
      ? (d.ev>0?cG:d.ev<0?cR:cA)
      : _kpiTooltipColor(d.ev, 'avgr');

  wrap.innerHTML = sorted.map(d => {
    const val = valFn(d);
    const pct = Math.min(Math.abs(val)/absMax*100,100).toFixed(1);
    const colBar = getColBar(d);
    const colVal = getColVal(d);
    const valStr = useN ? String(val) : (val>=0?'+':'')+val.toFixed(useTotal?1:3)+'R';
    return `<div style="display:flex;align-items:center;gap:6px;padding:3px 8px">
      <div style="font-family:'DM Mono',monospace;font-size:var(--typo-table-body-size,10px);color:var(--body);width:64px;flex-shrink:0;font-weight:600">${d.label}</div>
      <div style="flex:1;height:8px;background:var(--bg3);border-radius:2px;overflow:hidden">
        <div style="height:100%;width:${pct}%;background:${colBar};border-radius:2px"></div>
      </div>
      <div style="font-family:'DM Mono',monospace;font-size:var(--typo-table-body-size,10px);color:${colVal};width:56px;text-align:right;flex-shrink:0">${valStr}</div>
    </div>`;
  }).join('');
}

// ── Mobile M15 Obstacles — pure HTML horizontal bars ──
let _mobObsChart = null; // kept for compat
function drawMobileObs(trades) {
  if (!_isMobile()) return;
  const wrap = document.getElementById('mob-obs-wrap');
  if (!wrap) return;
  if (!trades.length) { wrap.innerHTML = ''; return; }

  const useTotal = barMode === 'total';
  const useN     = barMode === 'n';
  const tpConfig = appState.ui.tpConfig;
  const obs = {};
  trades.forEach(t => {
    const r = computeEffectiveRR(t, tpConfig);
    (t.obstacles||[]).forEach(o => {
      if (!o) return;
      if (!obs[o]) obs[o] = { r:0, n:0 };
      obs[o].r += r; obs[o].n++;
    });
  });
  const valFn = d => useN ? d.n : useTotal ? d.totalR : d.ev;
  const all = Object.entries(obs)
    .filter(([,v]) => v.n>=1)
    .map(([o,v]) => ({ label:o, ev:v.r/v.n, totalR:v.r, n:v.n }));
  const sorted = all.sort((a,b) => valFn(b)-valFn(a)).slice(0,15);
  if (!sorted.length) { wrap.innerHTML = ''; return; }

  const absMax = useN ? (Math.max(...sorted.map(d=>d.n)) || 1) : (Math.max(...sorted.map(d=>Math.abs(valFn(d)))) || 1);
  const cG = tc('--g'), cR = tc('--r'), cA = tc('--gold'), cT = tc('--t');
  const getColBar = d => useN ? cA
    : barColorMode === 'binary'
      ? (d.ev>0?cG:d.ev<0?cR:cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const getColVal = d => useN ? cA
    : useTotal && barColorMode === 'binary'
      ? (d.ev>0?cG:d.ev<0?cR:cA)
      : _kpiTooltipColor(d.ev, 'avgr');

  wrap.innerHTML = sorted.map(d => {
    const val = valFn(d);
    const pct = Math.min(Math.abs(val)/absMax*100,100).toFixed(1);
    const colBar = getColBar(d);
    const colVal = getColVal(d);
    const valStr = useN ? String(val) : (val>=0?'+':'')+val.toFixed(useTotal?1:3)+'R';
    return `<div style="display:flex;align-items:center;gap:6px;padding:3px 8px">
      <div style="font-family:'DM Mono',monospace;font-size:var(--typo-micro-size,9px);color:var(--body);width:100px;flex-shrink:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${d.label}</div>
      <div style="flex:1;height:7px;background:var(--bg3);border-radius:2px;overflow:hidden">
        <div style="height:100%;width:${pct}%;background:${colBar};border-radius:2px"></div>
      </div>
      <div style="font-family:'DM Mono',monospace;font-size:var(--typo-micro-size,9px);color:${colVal};width:50px;text-align:right;flex-shrink:0">${valStr}</div>
    </div>`;
  }).join('');
}

// ── Mobile Setup — pure HTML horizontal bars ──
let _mobSetupChart = null; // kept for compat
function drawMobileSetup(trades) {
  if (!_isMobile()) return;
  const wrap = document.getElementById('mob-setup-wrap');
  if (!wrap) return;
  if (!trades.length) { wrap.innerHTML = ''; return; }

  const useTotal = barMode === 'total';
  const useN     = barMode === 'n';
  const data = groupByEV(trades, t=>t.setup, k=>SETUP_SHORT[k]||k);
  if (!data.length) { wrap.innerHTML = ''; return; }
  const valFn = d => useN ? d.n : useTotal ? d.totalR : d.ev;
  const sorted = [...data].sort((a,b) => valFn(b)-valFn(a));
  const absMax = useN ? (Math.max(...sorted.map(d=>d.n)) || 1) : (Math.max(...sorted.map(d=>Math.abs(valFn(d)))) || 1);
  const cG = tc('--g'), cR = tc('--r'), cA = tc('--gold'), cT = tc('--t');
  const getColBar = d => useN ? cA
    : barColorMode === 'binary'
      ? (d.ev>0?cG:d.ev<0?cR:cA)
      : _kpiTooltipColor(d.ev, 'avgr');
  const getColVal = d => useN ? cA
    : useTotal && barColorMode === 'binary'
      ? (d.ev>0?cG:d.ev<0?cR:cA)
      : _kpiTooltipColor(d.ev, 'avgr');

  wrap.innerHTML = sorted.map(d => {
    const val = valFn(d);
    const pct = Math.min(Math.abs(val)/absMax*100,100).toFixed(1);
    const colBar = getColBar(d);
    const colVal = getColVal(d);
    const valStr = useN ? String(val) : (val>=0?'+':'')+val.toFixed(useTotal?1:3)+'R';
    return `<div style="display:flex;align-items:center;gap:6px;padding:3px 8px">
      <div style="font-family:'DM Mono',monospace;font-size:var(--typo-table-body-size,10px);color:var(--body);width:80px;flex-shrink:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600">${d.label}</div>
      <div style="flex:1;height:8px;background:var(--bg3);border-radius:2px;overflow:hidden">
        <div style="height:100%;width:${pct}%;background:${colBar};border-radius:2px"></div>
      </div>
      <div style="font-family:'DM Mono',monospace;font-size:var(--typo-table-body-size,10px);color:${colVal};width:56px;text-align:right;flex-shrink:0">${valStr}</div>
    </div>`;
  }).join('');
}

function renderMobileHeatmap(trades) {
  if (!_isMobile()) return;
  const container = document.getElementById('mob-heatmap-container');
  if (!container) return;

  // Sessions from actual data, canonical order
  const _suSetM = new Set(trades.map(t => t.sessionUtc || t.session).filter(Boolean));
  const sessions  = SESSION_ORDER.filter(s => _suSetM.has(s))
                    .concat([..._suSetM].filter(s => !SESSION_ORDER.includes(s)).sort());
  // Days from actual data, canonical Mon→Sun first, then any non-canonical
  // keys (alphabetical) — mirrors the desktop heatmap path.
  const _daySetM = new Set(trades.map(t => t.day).filter(Boolean));
  const days      = DAY_ORDER.filter(d => _daySetM.has(d))
                     .concat([..._daySetM].filter(d => !DAY_ORDER.includes(d)).sort());
  const useTotal  = barMode === 'total';
  const useN      = barMode === 'n';
  const tpConfig = appState.ui.tpConfig;
  const data = {};
  trades.forEach(t => {
    const k = (t.sessionUtc || t.session) + '|' + t.day;
    if (!data[k]) data[k] = { r: 0, n: 0 };
    data[k].r += computeEffectiveRR(t, tpConfig); data[k].n++;
  });
  const valFn = v => useN ? v.n : useTotal ? v.r : v.r / v.n;
  let mn = Infinity, mx = -Infinity;
  sessions.forEach(ss => days.forEach(d => {
    const v = data[ss + '|' + d];
    if (v && v.n >= 2) { const val = valFn(v); mn = Math.min(mn, val); mx = Math.max(mx, val); }
  }));
  if (mn === Infinity) { mn = 0; mx = 1; }
  const range = Math.max(mx, Math.abs(mn)) || 1;

  container.style.cssText = `display:grid;grid-template-columns:70px repeat(${days.length},1fr);gap:2px;min-width:320px`;
  container.innerHTML = '';

  const blank = document.createElement('div');
  blank.style.height = '20px';
  container.appendChild(blank);
  days.forEach(d => {
    const el = document.createElement('div');
    el.style.cssText = 'text-align:center;font-family:"DM Mono",monospace;font-size:8px;color:var(--dim);padding:2px 0';
    el.textContent = DAY_EN[d] || d;
    container.appendChild(el);
  });

  sessions.forEach(ss => {
    const lbl = document.createElement('div');
    lbl.style.cssText = 'display:flex;align-items:center;font-size:9px;color:var(--body);padding-right:4px;white-space:nowrap';
    lbl.textContent = SESSION_SHORT[ss] || ss;
    container.appendChild(lbl);
    days.forEach(d => {
      const v    = data[ss + '|' + d];
      const cell = document.createElement('div');
      cell.style.cssText = 'height:26px;border-radius:3px;display:flex;align-items:center;justify-content:center;font-family:"DM Mono",monospace;font-size:var(--typo-micro-size,8px);font-weight:600';
      if (v && v.n >= 2) {
        const val   = valFn(v);
        const norm  = val / range;
        const alpha = Math.min(Math.abs(norm) * 0.85 + 0.30, 0.95);
        const toRgb = h => { const r = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h); return r ? `${parseInt(r[1],16)},${parseInt(r[2],16)},${parseInt(r[3],16)}` : '180,180,180'; };
        const posCell = useN ? true : val >= 0;
        cell.style.background = `rgba(${toRgb(posCell ? tc('--g') : tc('--r'))},${alpha})`;
        cell.style.color = alpha > 0.55 ? tc('--bg1') : (posCell ? tc('--g') : tc('--r'));
        cell.textContent = useN ? String(val) : (val >= 0 ? '+' : '') + val.toFixed(useTotal ? 1 : 2);
      } else {
        cell.style.background = 'var(--bg3)';
        cell.style.color = 'var(--mute)';
        cell.textContent = '—';
      }
      container.appendChild(cell);
    });
  });
}

// ── Mobile monthly ──
let _mobMonthlyChart = null;
function drawMobileMonthly(trades) {
  if (!_isMobile()) return;
  const canvas = document.getElementById('mobMonthlyCanvas');
  if (!canvas) return;

  if (_mobMonthlyChart) { _mobMonthlyChart.destroy(); _mobMonthlyChart = null; }

  if (!trades.length) return;

  const tpConfig = appState.ui.tpConfig;
  const months = {};
  trades.forEach(t => {
    if (!t.month || isNaN(t.month)) return;
    const m = t.month;
    if (!months[m]) months[m] = { tp:0, sl:0, be:0 };
    const r = computeEffectiveRR(t, tpConfig);
    if (t.outcome === 'TP') months[m].tp += r;
    else if (t.outcome === 'SL') months[m].sl += r;
    else months[m].be += r;
  });
  const labels = Object.keys(months).sort();
  if (!labels.length) return;

  const shortLabel = m => { const parts = m.split('-'); return parts[1] + '/' + parts[0].slice(2); };

  _mobMonthlyChart = new Chart(canvas, {
    type: 'bar',
    data: {
      labels: labels.map(shortLabel),
      datasets: [
        { label:'TP',   data: labels.map(m => months[m].tp),  backgroundColor: tc('--g'),    stack:'s' },
        { label:'Loss', data: labels.map(m => months[m].sl),  backgroundColor: tc('--r'),    stack:'s' },
        { label:'BE',   data: labels.map(m => months[m].be),  backgroundColor: tc('--gold'), stack:'s' },
      ]
    },
    options: {
      responsive: false, maintainAspectRatio: false, animation: false,
      plugins: { legend:{ display:false }, tooltip:{ enabled:true, bodyFont:{ size:_chartTipFs() }, titleFont:{ size:_chartTipFs() } } },
      scales: {
        x: { stacked:true, grid:{ color:tc('--line') }, ticks:{ color:tc('--dim'), font:{ size:8 } } },
        y: { stacked:true, grid:{ color:tc('--line') }, ticks:{ color:tc('--dim'), font:{ size:8 } } },
      }
    }
  });
}

function renderMobileTradeLog(trades) {
  if (!_isMobile()) return;
  const wrap = document.getElementById('mob-tradelog-wrap');
  if (!wrap) return;

  _mobTradeLogAll  = [...trades].sort((a,b) => (b.date||'').localeCompare(a.date||''));
  _mobTradeLogPage = 0;
  _renderMobTradeLogPage(wrap);
}

function _renderMobTradeLogPage(wrap) {
  const all    = _mobTradeLogAll;
  const page   = _mobTradeLogPage;
  const total  = all.length;
  const start  = 0;
  const end    = Math.min((page + 1) * MOB_PAGE_SIZE, total);
  const shown  = all.slice(start, end);

  if (!total) {
    wrap.innerHTML = '<div class="mob-tradelog-empty">No trades</div>';
    return;
  }

  const ocClass = { TP:'oc-tp', SL:'oc-sl', 'BE-TP':'oc-betp', 'BE-SL':'oc-besl' };
  const rowTone = { TP:'is-tp', SL:'is-sl', 'BE-TP':'is-betp', 'BE-SL':'is-besl' };

  let lastDate = null;
  let rows = '';
  shown.forEach(t => {
    if (t.date !== lastDate) {
      const dayLabel = t.day ? `${t.date} · ${DAY_EN[t.day]||t.day}` : (t.date||'—');
      rows += `<div class="mob-tradelog-day">${dayLabel}</div>`;
      lastDate = t.date;
    }
    const _rEff = t.effectiveR ?? computeEffectiveRR(t, appState.ui.tpConfig);
    const _cls  = t.effectiveClass === 'win' ? 'is-positive'
                : t.effectiveClass === 'loss' ? 'is-negative'
                : t.effectiveClass === 'be' ? 'is-neutral'
                : (_rEff > 0 ? 'is-positive' : _rEff < 0 ? 'is-negative' : 'is-neutral');
    rows += `<div class="mob-tradelog-row ${rowTone[t.outcome]||''}">
      <span class="mob-tradelog-pair">${_escapeHtml(t.pair||'—')}</span>
      <span class="mob-tradelog-setup">${_escapeHtml(SETUP_SHORT[t.setup]||t.setup||'—')}</span>
      <span class="${ocClass[t.outcome]||''} mob-tradelog-outcome">${_escapeHtml(t.outcome||'')}</span>
      <span class="mob-tradelog-r ${_cls}">${_rEff>0?'+':''}${_rEff.toFixed(1)}R</span>
    </div>`;
  });

  // Pagination buttons
  const hasMore = end < total;
  let footer = `<div class="mob-tradelog-footer">`;
  if (hasMore) {
    footer += `<button class="mob-tradelog-btn" data-action="mob-tradelog-more">
      +15 more <span class="mob-tradelog-btn-meta">(${end}/${total})</span>
    </button>`;
    footer += `<button class="mob-tradelog-btn" data-action="mob-tradelog-all" data-page="${Math.ceil(total/MOB_PAGE_SIZE)-1}">
      Show all (${total})
    </button>`;
  } else {
    footer += `<span class="mob-tradelog-total">${total} trades</span>`;
  }
  footer += `</div>`;

  wrap.innerHTML = rows + footer;
}

function renderMobile() {
  if (!_isMobile()) return;
  const filtered = getFiltered();
  const stats    = calcStats(filtered);
  updateMobileStats(stats);
  drawMobileEquity(filtered);
  drawMobileDonut(stats);
  drawMobileMonthly2(filtered);
  if (filtered.some(t => t.session && t.session.trim())) {
    renderMobileHeatmap(filtered);
  }
  drawMobilePair(filtered);
  drawMobileSetup(filtered);
  drawMobileObs(filtered);
  renderMobileTradeLog(filtered);
}

// ── Mobile preset switcher ──
function mobApplyPreset(id) {
  syncPresetSelectionState(id);
  if (id === null) {
    // Reset to P0
    clearChipFilters();
    appState.filters.exclusions.m15Exclude     = [...BASE_M15_EXCLUDE];
    appState.filters.exclusions.h4Exclude      = [];
    appState.filters.exclusions.sessionExclude = [...BASE_SESSION_EXCLUDE];
    appState.filters.exclusions.dayExclude     = [];
    appState.presets.activeId = null;
  } else {
    applyPreset(id);
  }
  renderMobile();
}

// ── Hook mobile render into main render — appelé depuis render() directement ──
// (pas de wrapper pour éviter la récursion infinie)

// ── Resize: redraw mobile charts on orientation change ──
window.addEventListener('resize', () => {
  if (_isMobile()) {
    const filtered = getFiltered();
    drawMobileEquity(filtered);
    drawMobilePair(filtered);
    drawMobileObs(filtered);
  }
  if (currentView === 'share') {
    requestAnimationFrame(() => _svDrawEquity(getFiltered()));
  }
});

// ── Chart.js lazy load for mobile donut / monthly ──
// Chart.js is not loaded by default — inject it if on mobile

// ── Mobile chart instances (declared at module level) ──
let _chartJsReady     = false;   // true once Chart.js script has loaded
let _mobTradeLogPage  = 0;
let _mobTradeLogAll   = [];
const MOB_PAGE_SIZE   = 15;

(function() {
  if (!_isMobile()) return;

  function _runMobileCharts() {
    const filtered = getFiltered();
    const stats    = calcStats(filtered);
    updateMobileStats(stats);
    drawMobileEquity(filtered);
    drawMobileDonut(stats);       // SVG — no Chart.js needed
    drawMobileMonthly2(filtered); // HTML — no Chart.js needed
    if (filtered.some(t => t.session && t.session.trim())) {
      renderMobileHeatmap(filtered);
    }
    drawMobilePair(filtered);     // HTML — no Chart.js needed
    drawMobileSetup(filtered);    // HTML — no Chart.js needed
    drawMobileObs(filtered);      // HTML — no Chart.js needed
    renderMobileTradeLog(filtered);
  }

  // Run after DOM ready — no delay needed, HTML rendering is synchronous
  if (document.readyState === 'complete' || document.readyState === 'interactive') {
    _runMobileCharts();
  } else {
    document.addEventListener('DOMContentLoaded', _runMobileCharts);
  }
})();

document.addEventListener('DOMContentLoaded', () => {
  // Small delay to let render() finish first
  setTimeout(() => {
    _injectEditButton();
    initGridstack();
  }, 120);
});
// ════════════════════════════════════════════════════════
//  SHARE VIEW
// ════════════════════════════════════════════════════════
let _shareMode = 'year';   // 'year' | 'month'
// Set to true while the share-view PNG export is mutating the DOM, so the
// ResizeObserver doesn't trigger a mid-capture renderShareView and undo the
// micro-hidden classes that the live view had already computed.
let _svExporting = false;

// ── Share view internal calendar caches (independent from main) ──
let _svCalDayMap  = {};
let _svCalYearMap = {};

function setShareMode(mode) {
  _shareMode = mode;
  document.getElementById('sv-btn-year')?.classList.toggle('active', mode === 'year');
  document.getElementById('sv-btn-month')?.classList.toggle('active', mode === 'month');
  // Year selector is visible in both modes; month selector only in month mode.
  const monthSel = document.getElementById('sv-month-sel');
  if (monthSel) setVisible(monthSel, mode === 'month');
  renderShareView();
}

function _clearActivePreset() {
  invalidateFilterCache();
  appState.ui.showRawAll = false;
  _exitRawBtn();
  appState.filters.exclusions.m15Exclude     = [...BASE_M15_EXCLUDE];
  appState.filters.exclusions.h4Exclude      = [];
  appState.filters.exclusions.sessionExclude = [...BASE_SESSION_EXCLUDE];
  appState.filters.exclusions.dayExclude     = [];
  // Use setActivePreset(null) instead of a direct assignment so the cleared
  // state persists in the profile-scoped slot — otherwise switching profiles
  // and switching back would restore the previously-active preset.
  setActivePreset(null);
  syncPresetSelectionState(null);
}

function _svSyncPresetSel() {
  const sel = document.getElementById('sv-preset-sel');
  if (!sel) return;

  sel.innerHTML =
    '<option value="">No Preset</option>' +
    PRESETS.map(p => `<option value="${p.id}">P${_getPresetDisplayNum(p.id)} - ${p.label}</option>`).join('');

  sel.value = typeof appState.presets.activeId === 'number' ? String(appState.presets.activeId) : '';
}

function setSharePreset(value) {
  if (value === '') {
    _clearActivePreset();
    render();
    return;
  }
  applyPreset(parseInt(value, 10));
}

// ── Build cal caches identical to _calRebuildCaches but targets sv vars ──
function _svRebuildCaches(trades) {
  _svCalDayMap  = {};
  _svCalYearMap = {};
  const tpConfig = appState.ui.tpConfig;
  for (const raw of trades) {
    if (!raw || !raw.date) continue;
    const t    = { ...raw, r: Number(raw.r) || 0 };
    const r    = computeEffectiveRR(t, tpConfig);
    const date = t.date;
    const year = date.slice(0, 4);
    const month = date.slice(0, 7);

    if (!_svCalDayMap[date]) _svCalDayMap[date] = { r: 0, n: 0, wins: 0, losses: 0, trades: [], hours: {}, sessions: {} };
    const d = _svCalDayMap[date];
    d.r += r; d.n++; if (isWinner(t)) d.wins++; if (isLoser(t)) d.losses++;
    d.trades.push(t);
    const hKey = (t.hour != null && !isNaN(t.hour)) ? Number(t.hour) : -1;
    if (!d.hours[hKey]) d.hours[hKey] = { r: 0, n: 0, ocs: {}, trades: [] };
    d.hours[hKey].r += r; d.hours[hKey].n++; d.hours[hKey].trades.push(t);
    d.hours[hKey].ocs[t.outcome || 'SL'] = (d.hours[hKey].ocs[t.outcome || 'SL'] || 0) + 1;

    if (!_svCalYearMap[year]) _svCalYearMap[year] = { maxAbs: 0, months: {} };
    if (!_svCalYearMap[year].months[month]) _svCalYearMap[year].months[month] = { trades: [] };
    _svCalYearMap[year].months[month].trades.push(t);
    _svCalYearMap[year].maxAbs = Math.max(_svCalYearMap[year].maxAbs, Math.abs(d.r));
  }
}

// ── Populate year/month selectors with available values from the dataset ──
// In year mode, an "All" option is prepended so users can aggregate across
// every year. In month mode, "All" is excluded because a month needs a year.
// Default selection: the previous value if still valid, else the current
// calendar year (if present in the data), else the most recent year, else
// "All" (year mode only).
function _svPopulateYearSel(trades, { includeAll = false } = {}) {
  const sel = document.getElementById('sv-year-sel');
  if (!sel) return null;

  const years = new Set();
  trades.forEach(t => { if (t.date) years.add(t.date.slice(0, 4)); });
  const sorted = [...years].sort().reverse();
  const prev = sel.value;

  const opts = [];
  if (includeAll) opts.push('<option value="all">All</option>');
  opts.push(...sorted.map(y => '<option value="' + y + '">' + y + '</option>'));
  sel.innerHTML = opts.join('');

  const validValues = includeAll ? ['all', ...sorted] : sorted;
  const currentYear = String(new Date().getFullYear());
  if (prev && validValues.includes(prev)) {
    sel.value = prev;
  } else if (sorted.includes(currentYear)) {
    sel.value = currentYear;
  } else if (sorted.length) {
    sel.value = sorted[0];
  } else {
    sel.value = includeAll ? 'all' : '';
  }

  return sel.value || null;
}

function _svPopulateMonthSel(trades, year) {
  const sel = document.getElementById('sv-month-sel');
  if (!sel) return null;

  const months = new Set();
  trades.forEach(t => {
    if (!t.date) return;
    if (year && t.date.slice(0, 4) !== year) return;
    months.add(t.date.slice(5, 7));
  });
  const sorted = [...months].sort().reverse();

  const prev = sel.value;
  sel.innerHTML = sorted.map(mo => (
    '<option value="' + mo + '">' + _CAL_MONTHS[parseInt(mo, 10) - 1] + '</option>'
  )).join('');

  if (prev && sorted.includes(prev)) sel.value = prev;
  else if (sorted.length) sel.value = sorted[0];
  else sel.value = '';

  return sel.value || null;
}

function _svGetSelectedYearMonth(trades) {
  // Year mode: "All" is a valid selection that aggregates every year.
  // Month mode: "All" is not offered — month picking requires a year.
  const includeAll = _shareMode === 'year';
  const year = _svPopulateYearSel(trades, { includeAll });
  const isAll = year === 'all';
  // Month select only populated/used in month mode (never in "All" year mode).
  const month = (_shareMode === 'month' && !isAll)
    ? _svPopulateMonthSel(trades, year)
    : null;
  return {
    year,
    month,
    isAll,
    ym: (year && !isAll && month) ? `${year}-${month}` : null,
  };
}

function _svFormatDateWidgetLabel(year, month) {
  if (!year) return '—';
  if (year === 'all') {
    // Show the actual range of years covered by the current dataset, e.g.
    // "2020-2025". Falls back to "All Time" when no year data is available.
    const years = Object.keys(_svCalYearMap || {}).sort();
    if (!years.length) return 'All Time';
    return years.length === 1 ? years[0] : `${years[0]}-${years[years.length - 1]}`;
  }
  if (_shareMode !== 'month' || !month) return String(year);

  const dt = new Date(Number(year), Number(month) - 1, 1);
  if (Number.isNaN(dt.getTime())) return `${month}/${year}`;

  const monthLabel = dt.toLocaleDateString('en-US', { month: 'long' });
  return `${monthLabel} ${year}`;
}

function _svRenderDateWidget(year, month) {
  const el = document.getElementById('sv-date-label');
  if (!el) return;
  el.textContent = _svFormatDateWidgetLabel(year, month);
}

// ── Compact equity curve for share view ──
function _svDrawEquity(trades) {
  const canvas = document.getElementById('sv-equity-canvas');
  const wrap   = document.getElementById('sv-equity-wrap');
  if (!canvas || !wrap) return;

  const W = wrap.getBoundingClientRect().width  || wrap.offsetWidth  || 400;
  const H = wrap.getBoundingClientRect().height || wrap.offsetHeight || 140;
  if (W < 10 || H < 10) return;

  const dpr = devicePixelRatio || 1;
  canvas.style.width  = W + 'px';
  canvas.style.height = H + 'px';
  canvas.width  = Math.round(W * dpr);
  canvas.height = Math.round(H * dpr);

  const ctx = canvas.getContext('2d');
  ctx.resetTransform();
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, W, H);

  if (!trades.length) return;

  const days = groupByDay(trades);
  const n    = days.length;
  if (!n) return;

  const equitySeries = [0, ...days.map(d => d.eqEnd)];
  const ddSeries     = [0, ...days.map(d => d.ddEnd)];
  const xDates       = [days[0]?.date || '', ...days.map(d => d.date)];
  const pointCount   = equitySeries.length;

  const fmtShareDate = iso => {
    if (!iso) return '';
    const [y, m, d] = String(iso).split('-').map(Number);
    const dt = new Date(y, (m || 1) - 1, d || 1);
    if (Number.isNaN(dt.getTime())) return iso;
    return dt.toLocaleDateString('fr-BE', { day: '2-digit', month: '2-digit' });
  };

  const pad = { t: 12, r: 12, b: 30, l: 38 };
  const cw  = W - pad.l - pad.r;
  const ch  = H - pad.t - pad.b;

  const eqMin   = Math.min(0, ...equitySeries, ...ddSeries);
  const eqMax   = Math.max(0.01, ...equitySeries);
  const eqRange = (eqMax - eqMin) || 1;
  const toX = i => pad.l + (i / (pointCount - 1 || 1)) * cw;
  const toY = v => pad.t + ch - ((v - eqMin) / eqRange) * ch;

  const cRed  = tc('--r')    || '#e05a72';
  const cGold = tc('--gold') || '#f5c451';
  const cGreen = tc('--g')   || '#6ee0b4';
  const cDim  = tc('--dim')  || '#4a6080';
  const cLine = tc('--line') || '#1c2840';
  const lastEq = equitySeries[pointCount - 1];
  const eqTone = lastEq >= 0 ? cGreen : cRed;

  // Grid lines
  const gridLevels = 4;
  ctx.strokeStyle = cLine;
  ctx.lineWidth = 0.5;
  ctx.font = '7px DM Mono, monospace';
  ctx.textAlign = 'right';
  ctx.fillStyle = cDim;
  for (let i = 0; i <= gridLevels; i++) {
    const v = eqMin + (eqRange * i / gridLevels);
    const y = toY(v);
    ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(W - pad.r, y); ctx.stroke();
    ctx.fillText((v >= 0 ? '+' : '') + v.toFixed(1) + 'R', pad.l - 3, y + 2.5);
  }

  // Zero line
  const y0 = toY(0);
  ctx.save();
  ctx.strokeStyle = tcRgba('--white', 0.12);
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 4]);
  ctx.beginPath(); ctx.moveTo(pad.l, y0); ctx.lineTo(W - pad.r, y0); ctx.stroke();
  ctx.setLineDash([]);
  ctx.restore();

  // X-axis date labels
  ctx.save();
  ctx.fillStyle = cDim;
  ctx.font = '7px DM Mono, monospace';
  ctx.textBaseline = 'top';
  const tickIdxs = [...new Set([0, Math.floor((pointCount - 1) / 2), pointCount - 1])];
  tickIdxs.forEach((idx, pos) => {
    const label = fmtShareDate(xDates[idx]);
    const x = toX(idx);
    ctx.textAlign = pos === 0 ? 'left' : (pos === tickIdxs.length - 1 ? 'right' : 'center');
    ctx.fillText(label, x, H - pad.b + 8);
  });
  ctx.restore();

  // Drawdown fill (shaded area between equity and running peak)
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(toX(0), toY(equitySeries[0]));
  for (let i = 0; i < pointCount; i++) ctx.lineTo(toX(i), toY(equitySeries[i]));
  for (let i = pointCount - 1; i >= 0; i--) {
    const peakAtI = equitySeries[i] - ddSeries[i];
    ctx.lineTo(toX(i), toY(peakAtI));
  }
  ctx.closePath();
  ctx.fillStyle = getLossColorAlpha(0.18);
  ctx.fill();
  ctx.restore();

  // Equity fill gradient
  ctx.save();
  const fillGrad = ctx.createLinearGradient(0, pad.t, 0, H - pad.b);
  fillGrad.addColorStop(0, eqTone === cGreen ? getWinColorAlpha(0.24) : getLossColorAlpha(0.22));
  fillGrad.addColorStop(1, eqTone === cGreen ? getWinColorAlpha(0.03) : getLossColorAlpha(0.03));
  ctx.beginPath();
  ctx.moveTo(toX(0), toY(0));
  for (let i = 0; i < pointCount; i++) ctx.lineTo(toX(i), toY(equitySeries[i]));
  ctx.lineTo(toX(pointCount - 1), y0);
  ctx.closePath();
  ctx.fillStyle = fillGrad;
  ctx.fill();
  ctx.restore();

  // Equity line
  ctx.beginPath();
  for (let i = 0; i < pointCount; i++) {
    if (i === 0) ctx.moveTo(toX(i), toY(equitySeries[i]));
    else ctx.lineTo(toX(i), toY(equitySeries[i]));
  }
  ctx.strokeStyle = eqTone;
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // Final dot
  ctx.beginPath();
  ctx.arc(toX(pointCount - 1), toY(lastEq), 3, 0, Math.PI * 2);
  ctx.fillStyle = eqTone;
  ctx.fill();

  // High / low cumulative RR markers
  const hiVal = Math.max(...equitySeries);
  const loVal = Math.min(...equitySeries);
  const hiIdx = equitySeries.indexOf(hiVal);
  const loIdx = equitySeries.indexOf(loVal);
  const drawPointLabel = (idx, value, color) => {
    const x = toX(idx);
    const y = toY(value);
    const isUpperHalf = y < pad.t + ch / 2;
    const defaultBoxY = isUpperHalf ? y + 12 : y - 28;
    const text = `${(value >= 0 ? '+' : '') + value.toFixed(2)}R`;

    ctx.save();
    ctx.beginPath();
    ctx.arc(x, y, 3.5, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();

    ctx.font = '9px DM Mono, monospace';
    const textW = Math.ceil(ctx.measureText(text).width);
    const boxW = textW + 12;
    const boxX = Math.max(pad.l, Math.min(x - boxW / 2, W - pad.r - boxW));
    const boxY = Math.max(pad.t, Math.min(defaultBoxY, H - pad.b - 20));

    ctx.fillStyle = tcRgba('--bg4', 0.88);
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(boxX, boxY, boxW, 18, 5);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = tc('--white');
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, boxX + boxW / 2, boxY + 9.5);
    ctx.restore();
  };

  drawPointLabel(hiIdx, hiVal, cGold);
  if (loIdx !== hiIdx) drawPointLabel(loIdx, loVal, loVal >= 0 ? cGreen : cRed);
  drawPointLabel(pointCount - 1, lastEq, eqTone);

  // Equity summary label
  const eqInfoEl = document.getElementById('sv-eq-info');
  if (eqInfoEl) {
    const sign = lastEq >= 0 ? '+' : '';
    eqInfoEl.textContent = [
      sign + lastEq.toFixed(2) + 'R',
      `${n} trading days`
    ].join(' · ');
    eqInfoEl.classList.remove('is-positive', 'is-negative');
    eqInfoEl.classList.add(lastEq >= 0 ? 'is-positive' : 'is-negative');
  }
}

function _svRenderCalDayHeaders(extraLabel = '') {
  const headers = _CAL_DAY_LABELS.map(dl => `<div class="sv-cal-dayhead">${dl}</div>`).join('');
  return extraLabel ? headers + `<div class="sv-cal-dayhead sv-cal-dayhead-extra">${extraLabel}</div>` : headers;
}

function _svAnnualCalDayCell(data, maxAbs, cG, cR) {
  if (!data) return '<div class="sv-cal-mini-day sv-cal-mini-day-empty"></div>';
  const isWin = data.r >= 0;
  const hexCol = isWin ? cG : cR;
  const rgb = _calHexToRgb(hexCol);
  const alpha = (0.2 + Math.min(Math.abs(data.r) / maxAbs, 1) * 0.7).toFixed(2);
  const txtCol = parseFloat(alpha) > 0.5 ? tc('--text-inverse') : hexCol;
  return `<div class="sv-cal-mini-day sv-cal-mini-day-value" style="--sv-cal-bg:rgba(${rgb},${alpha});--sv-cal-fg:${txtCol}">${data.r >= 0 ? '+' : ''}${data.r.toFixed(1)}</div>`;
}

function _svMonthlyCalDayCell(day, data, maxAbs, colors) {
  if (!data) {
    return `<div class="sv-cal-month-day sv-cal-month-day-empty"><span class="sv-cal-month-daynum sv-cal-month-daynum-empty">${day}</span></div>`;
  }
  // Heatmap on top of the KPI-tile palette: same green/red base as the
  // c-green / c-red topbar tiles, but the tint percentage scales with how
  // big the day's R is relative to the month's biggest move. Quiet days
  // stay near the 5% baseline (matches the resting tile colour); the
  // strongest day of the month maxes out at 30%.
  const intensity = Math.min(Math.abs(data.r) / maxAbs, 1);
  const pct = 5 + 25 * intensity;
  const bg = data.r > 0
    ? `color-mix(in srgb, var(--g) ${pct}%, var(--bg2))`
    : data.r < 0
    ? `color-mix(in srgb, var(--r) ${pct}%, var(--bg2))`
    : 'var(--bg2)';
  const sign = data.r >= 0 ? '+' : '';
  const totalClass = data.r >= 0 ? ' is-pos' : ' is-neg';

  // Per-trade rows, ordered by entry hour ascending. Each row prefixes a
  // win/loss dot (green = winner, red = loser, neutral = BE), then pair,
  // entry time (zero-padded hour), and the trade's effective R coloured by
  // sign. Direction info lives in the dot colour scheme below; the explicit
  // arrow was dropped at the user's request to match the cleaner layout.
  const trades = (data.trades || []).slice().sort((a, b) => {
    const ha = (a.hour != null && !isNaN(a.hour)) ? Number(a.hour) : 999;
    const hb = (b.hour != null && !isNaN(b.hour)) ? Number(b.hour) : 999;
    return ha - hb;
  });
  const tpConfig = appState.ui.tpConfig;
  const escapeHtml = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[c]);
  const tradesMarkup = trades.map(t => {
    // Notion-pure BE outcomes get their semantic colors (blue / violet)
    // regardless of the mode-dependent effective classification — the dot
    // mirrors the journal label, so a BE-TP that turned profitable in the
    // active TP mode still reads as a BE-TP, not a green winner.
    let dotClass;
    if (t.outcome === 'BE-TP')      dotClass = 'is-be-tp';
    else if (t.outcome === 'BE-SL') dotClass = 'is-be-sl';
    else if (isWinner(t, tpConfig)) dotClass = 'is-win';
    else if (isLoser(t, tpConfig))  dotClass = 'is-loss';
    else                            dotClass = 'is-be';
    return `<div class="sv-cal-month-trade-row">
      <span class="sv-cal-month-trade-dot ${dotClass}"></span>
      <span class="sv-cal-month-trade-pair">${escapeHtml(t.pair || '')}</span>
    </div>`;
  }).join('');

  return `<div class="sv-cal-month-day sv-cal-month-day-value" style="--sv-cal-bg:${bg};--sv-cal-daynum:${colors.dayTxt}">
    <div class="sv-cal-month-head">
      <span class="sv-cal-month-daynum">${day}</span>
      <span class="sv-cal-month-total${totalClass}">${sign}${data.r.toFixed(1)}R</span>
    </div>
    <div class="sv-cal-month-trade-list">${tradesMarkup}</div>
  </div>`;
}

function _svMonthlyCalWeekCell(wR, wN, wC, calWkBg) {
  if (wN > 0) {
    return `<div class="sv-cal-weekcell" style="--sv-cal-week-bg:${calWkBg};--sv-cal-week-fg:${wC}">
      <span class="sv-cal-weekvalue">${wR >= 0 ? '+' : ''}${wR.toFixed(1)}R</span>
      <span class="sv-cal-weektrades">${wN}T</span>
    </div>`;
  }
  return `<div class="sv-cal-weekcell sv-cal-weekcell-empty" style="--sv-cal-week-bg:${calWkBg}"></div>`;
}

// ── Annual P&L calendar for share view ──
function _svRenderCalAnnual(trades, selectedYear) {
  const grid = document.getElementById('sv-cal-grid');
  if (!grid) return;

  const years = Object.keys(_svCalYearMap).sort().reverse();
  if (!years.length) {
    grid.innerHTML = '<div class="no-data">No data</div>';
    return;
  }
  // Use the selected year when available and present in the dataset;
  // otherwise (e.g. "All" or missing year) fall back to the most recent.
  const year = (selectedYear && selectedYear !== 'all' && years.includes(selectedYear))
    ? selectedYear
    : years[0];
  const cG     = tc('--g') || '#6ee0b4';
  const cR     = tc('--r') || '#e05a72';
  const maxAbs = Math.max(_svCalYearMap[year]?.maxAbs || 0, 0.01);

  let html = '<div class="sv-cal-annual-grid">';

  for (let mo = 0; mo < 12; mo++) {
    const daysInMonth = new Date(parseInt(year, 10), mo + 1, 0).getDate();
    const firstDow    = (new Date(parseInt(year, 10), mo, 1).getDay() + 6) % 7;
    const moPrefix    = year + '-' + String(mo + 1).padStart(2, '0');
    const moTrades    = (_svCalYearMap[year]?.months?.[moPrefix]?.trades) || [];
    const moR         = moTrades.reduce((s, t) => s + (Number(computeEffectiveRR(t, appState.ui.tpConfig)) || 0), 0);
    const moN         = moTrades.length;
    const moCol       = moR >= 0 ? cG : cR;

    html += '<div class="sv-cal-mini-month">';
    html += '<div class="sv-cal-mini-head">';
    html += '<span class="sv-cal-mini-title">' + _CAL_MONTHS[mo] + '</span>';
    if (moN > 0) {
      html += '<span class="sv-cal-mini-total" style="--sv-cal-total:' + moCol + '">' + (moR >= 0 ? '+' : '') + moR.toFixed(1) + 'R</span>';
    }
    html += '</div>';
    html += '<div class="sv-cal-mini-days">';
    html += _svRenderCalDayHeaders();
    for (let i = 0; i < firstDow; i++) html += '<div class="sv-cal-mini-day sv-cal-mini-day-blank"></div>';
    for (let day = 1; day <= daysInMonth; day++) {
      const dateStr = year + '-' + String(mo + 1).padStart(2, '0') + '-' + String(day).padStart(2, '0');
      const data    = _svCalDayMap[dateStr];
      html += _svAnnualCalDayCell(data, maxAbs, cG, cR);
    }
    html += '</div></div>';
  }
  html += '</div>';

  const calLabel = document.getElementById('sv-cal-label');
  if (calLabel) calLabel.textContent = year;
  grid.innerHTML = html;
}

// ── Monthly P&L calendar for share view ──
function _svRenderCalMonth(yearMonth) {
  const grid = document.getElementById('sv-cal-grid');
  if (!grid) return;

  if (!yearMonth) {
    grid.innerHTML = '<div class="no-data">No month selected</div>';
    return;
  }

  const parts = yearMonth.split('-');
  const year  = parts[0];
  const mo2   = parts[1];
  const mo    = parseInt(mo2, 10) - 1;
  const daysInMonth = new Date(parseInt(year, 10), mo + 1, 0).getDate();
  const firstDow    = (new Date(parseInt(year, 10), mo, 1).getDay() + 6) % 7;
  const cG = tc('--g') || '#5dd6a8';
  const cR = tc('--r') || '#e05a6e';
  const calWkBg = 'rgba(32,36,49,0.98)';
  const calPosBase = [20, 55, 47];
  const calNegBase = [67, 36, 44];
  const calPosHi = _calHexToRgb(cG).split(',').map(Number);
  const calNegHi = _calHexToRgb(cR).split(',').map(Number);
  const calPosTxt = cG;
  const calNegTxt = cR;
  const calDayTxt = 'rgba(235,242,255,0.74)';
  const colorCfg = { posBase: calPosBase, negBase: calNegBase, posHi: calPosHi, negHi: calNegHi, dayTxt: calDayTxt };

  const mTrades = Object.keys(_svCalDayMap)
    .filter(d => d.startsWith(yearMonth))
    .flatMap(d => _svCalDayMap[d].trades);
  const tpConfig = appState.ui.tpConfig;
  const totR  = mTrades.reduce((s, t) => s + (Number(computeEffectiveRR(t, tpConfig)) || 0), 0);
  const wins  = mTrades.filter(isWinner).length;
  const losses = mTrades.filter(isLoser).length;
  const maxAbs = Math.max(
    ...Object.entries(_svCalDayMap).filter(([d]) => d.startsWith(yearMonth)).map(([, v]) => Math.abs(v.r)),
    0.01
  );
  const totColor = totR >= 0 ? calPosTxt : calNegTxt;

  const calLabel = document.getElementById('sv-cal-label');
  if (calLabel) calLabel.textContent = _CAL_MONTHS[mo] + ' ' + year;

  const numWeeks = Math.ceil((firstDow + daysInMonth) / 7);
  let html = '<div class="sv-cal-month-shell">';
  html += '<div class="sv-cal-month-summary">';
  html += '<span class="sv-cal-month-summary-meta">' + _CAL_MONTHS[mo] + ' ' + year + ' &nbsp;' + mTrades.length + 'T &nbsp;<span class="sv-cal-month-summary-win">' + wins + 'W</span> <span class="sv-cal-month-summary-loss">' + losses + 'L</span></span>';
  html += '<span class="sv-cal-month-summary-total" style="--sv-cal-total:' + totColor + '">' + (totR >= 0 ? '+' : '') + totR.toFixed(1) + 'R</span>';
  html += '</div>';

  html += '<div class="sv-cal-month-grid" style="--sv-cal-weeks:' + numWeeks + '">';
  html += _svRenderCalDayHeaders('Wk');

  for (let i = 0; i < firstDow; i++) html += '<div></div>';

  let col = firstDow;
  let wkTrades = [];

  for (let day = 1; day <= daysInMonth; day++) {
    const dateStr = year + '-' + mo2 + '-' + String(day).padStart(2, '0');
    const data    = _svCalDayMap[dateStr];

    if (data) wkTrades.push(...data.trades);

    html += _svMonthlyCalDayCell(day, data, maxAbs, colorCfg);

    col++;
    const isLastDay   = day === daysInMonth;
    const isEndOfWeek = col === 7;
    if (isEndOfWeek || isLastDay) {
      if (isLastDay && col < 7) for (let i = col; i < 7; i++) html += '<div></div>';
      const wR = wkTrades.reduce((s, t) => s + (Number(computeEffectiveRR(t, tpConfig)) || 0), 0);
      const wN = wkTrades.length;
      const wC = wR >= 0 ? calPosTxt : calNegTxt;
      html += _svMonthlyCalWeekCell(wR, wN, wC, calWkBg);
      wkTrades = [];
      col = 0;
    }
  }

  html += '</div>';
  grid.innerHTML = html + '</div>';

  // Uniform row heights: every week-row in the grid must be tall enough for
  // the busiest cell of the entire month, otherwise calm weeks would render
  // shorter than busy ones (the user wants every cell the same size). We
  // measure each cell's intrinsic content height (scrollHeight, ignores the
  // current row constraint and the cell's overflow:hidden) and pick the max.
  // The CSS rule then expands every row to at least that height via
  // minmax(var(--sv-cal-row-min-h), 1fr).
  const monthGrid = grid.querySelector('.sv-cal-month-grid');
  if (monthGrid) {
    let maxContentH = 0;
    monthGrid.querySelectorAll('.sv-cal-month-day-value').forEach(c => {
      if (c.scrollHeight > maxContentH) maxContentH = c.scrollHeight;
    });
    if (maxContentH > 0) {
      monthGrid.style.setProperty('--sv-cal-row-min-h', maxContentH + 'px');
    } else {
      monthGrid.style.removeProperty('--sv-cal-row-min-h');
    }
  }
}

const _SV_PF_THRESHOLDS = [0, 1, 1.3, 1.7, 2.2, 3, 4];
const _SV_AVG_R_THRESHOLDS = [-0.3, 0, 0.1, 0.3, 0.6, 1, 1.2];
const _SV_PROGRESS_Y = [17.5, 17.5, 14.5, 11.5, 7.5, 4.5, 3.5];
const _SV_STREAK_SCALE_MAX = 12;
const _SV_PROGRESSION_COLORS = {
  red: 'var(--r)',
  orange: '#f39a3d',
  yellow: 'var(--a)',
  green: 'var(--g)',
  blue: 'var(--b)',
  purple: '#9b6dff',
};

function _svClamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function _svLerp(a, b, t) {
  return a + (b - a) * t;
}

function _svScaleAgainstThresholds(value, thresholds) {
  if (!thresholds || thresholds.length < 2) return 0;
  const last = thresholds.length - 1;
  const clamped = _svClamp(Number.isFinite(value) ? value : thresholds[0], thresholds[0], thresholds[last]);
  for (let i = 0; i < last; i++) {
    const left = thresholds[i];
    const right = thresholds[i + 1];
    if (clamped <= right || i === last - 1) {
      const span = right - left || 1;
      const localT = _svClamp((clamped - left) / span, 0, 1);
      return (i + localT) / last;
    }
  }
  return 0;
}

function _svProgressPoint(value, thresholds) {
  const scale = _svScaleAgainstThresholds(value, thresholds);
  const x = 2 + scale * 38;
  const segs = _SV_PROGRESS_Y.length - 1;
  const pos = scale * segs;
  const i = Math.min(segs - 1, Math.floor(pos));
  const t = _svClamp(pos - i, 0, 1);
  const y = _svLerp(_SV_PROGRESS_Y[i], _SV_PROGRESS_Y[i + 1], t);
  return { x, y, scale };
}

function _svProgressMarkerColor(scale) {
  if (scale >= 5 / 6) return _SV_PROGRESSION_COLORS.purple;
  if (scale >= 4 / 6) return _SV_PROGRESSION_COLORS.blue;
  if (scale >= 3 / 6) return _SV_PROGRESSION_COLORS.green;
  if (scale >= 2 / 6) return _SV_PROGRESSION_COLORS.yellow;
  if (scale >= 1 / 6) return _SV_PROGRESSION_COLORS.orange;
  return _SV_PROGRESSION_COLORS.red;
}

function _svProgressTone(value, kind) {
  if (kind === 'pf') {
    if (value < 1) return { colorCls: 'c-red', valueCls: 'v-red' };
    if (value < 1.3) return { colorCls: 'c-orange', valueCls: 'v-orange' };
    if (value < 1.7) return { colorCls: 'c-yellow', valueCls: 'v-yellow' };
    if (value < 2.2) return { colorCls: 'c-green', valueCls: 'v-green' };
    if (value < 3) return { colorCls: 'c-blue', valueCls: 'v-blue' };
    return { colorCls: 'c-purple', valueCls: 'v-purple' };
  }
  if (value < 0) return { colorCls: 'c-red', valueCls: 'v-red' };
  if (value < 0.1) return { colorCls: 'c-orange', valueCls: 'v-orange' };
  if (value < 0.3) return { colorCls: 'c-yellow', valueCls: 'v-yellow' };
  if (value < 0.6) return { colorCls: 'c-green', valueCls: 'v-green' };
  if (value < 1) return { colorCls: 'c-blue', valueCls: 'v-blue' };
  return { colorCls: 'c-purple', valueCls: 'v-purple' };
}

function _svProgressionMicro(value, kind, idPrefix = 'stats') {
  const isPF = kind === 'pf';
  const thresholds = isPF ? _SV_PF_THRESHOLDS : _SV_AVG_R_THRESHOLDS;
  const gradientId = 'sv-micro-grad-' + idPrefix + '-' + kind;
  const marker = _svProgressPoint(value, thresholds);
  const markerColor = _svProgressMarkerColor(marker.scale);
  const xs = thresholds.map((_, i) => 2 + (i / (thresholds.length - 1)) * 38);
  const linePoints = xs.map((x, i) => x.toFixed(2) + ',' + _SV_PROGRESS_Y[i].toFixed(2)).join(' ');
  const fillPoints = '2,23 ' + linePoints + ' 40,23';
  const zoneStops = [
    { o: '0%', c: _SV_PROGRESSION_COLORS.red },
    { o: '16.66%', c: _SV_PROGRESSION_COLORS.red },
    { o: '16.66%', c: _SV_PROGRESSION_COLORS.orange },
    { o: '33.33%', c: _SV_PROGRESSION_COLORS.orange },
    { o: '33.33%', c: _SV_PROGRESSION_COLORS.yellow },
    { o: '50%', c: _SV_PROGRESSION_COLORS.yellow },
    { o: '50%', c: _SV_PROGRESSION_COLORS.green },
    { o: '66.66%', c: _SV_PROGRESSION_COLORS.green },
    { o: '66.66%', c: _SV_PROGRESSION_COLORS.blue },
    { o: '83.33%', c: _SV_PROGRESSION_COLORS.blue },
    { o: '83.33%', c: _SV_PROGRESSION_COLORS.purple },
    { o: '100%', c: _SV_PROGRESSION_COLORS.purple }
  ];
  return '' +
    '<div class="wst-cell-micro is-progression" aria-hidden="true">' +
      '<svg viewBox="0 0 42 24" preserveAspectRatio="none">' +
        '<defs>' +
          '<linearGradient id="' + gradientId + '" x1="0%" y1="0%" x2="100%" y2="0%">' +
            zoneStops.map(s => '<stop offset="' + s.o + '" stop-color="' + s.c + '" class="micro-zone-stop"></stop>').join('') +
          '</linearGradient>' +
        '</defs>' +
        '<line x1="2" y1="23" x2="40" y2="23" class="micro-track" stroke-width=".9"></line>' +
        '<polygon points="' + fillPoints + '" fill="url(#' + gradientId + ')" class="micro-fill-soft"></polygon>' +
        '<polyline points="' + linePoints + '" class="micro-line" stroke="url(#' + gradientId + ')" stroke-width="1.6"></polyline>' +
        '<circle cx="' + marker.x.toFixed(2) + '" cy="' + marker.y.toFixed(2) + '" r="3.1" class="micro-marker-dot" fill="' + markerColor + '"></circle>' +
      '</svg>' +
    '</div>';
}

function _svWinRateMicro(winRate, wins, losses) {
  const wr = _svClamp(Number.isFinite(winRate) ? winRate : 0, 0, 100);
  const safeWins = Math.max(0, Math.round(Number(wins) || 0));
  const safeLosses = Math.max(0, Math.round(Number(losses) || 0));
  const tone = _getWinRateTone(wr);
  const path = 'M 14 60 A 36 36 0 0 1 86 60';
  return '' +
    '<div class="wst-cell-micro is-gauge" aria-hidden="true">' +
      '<svg viewBox="0 0 100 78" preserveAspectRatio="none">' +
        '<path d="M 14 60 A 36 36 0 0 1 86 60 L 80 60 A 30 30 0 0 0 20 60 Z" class="micro-gauge-area" fill="color-mix(in srgb, var(--white) 5%, transparent)"></path>' +
        '<path d="' + path + '" class="micro-track" stroke-linecap="butt" pathLength="100"></path>' +
        '<path d="' + path + '" class="micro-gauge-bg" stroke="color-mix(in srgb, var(--r) 88%, var(--body))" stroke-linecap="butt" fill="none" pathLength="100" stroke-dasharray="100 100"></path>' +
        '<path d="' + path + '" class="micro-gauge-fill" stroke="' + tone.arc + '" stroke-linecap="butt" fill="none" pathLength="100" stroke-dasharray="' + wr.toFixed(2) + ' 100"></path>' +
        '<text x="18" y="72" class="micro-gauge-win" fill="' + tone.arc + '">' + safeWins + '</text>' +
        '<text x="82" y="72" class="micro-gauge-loss">' + safeLosses + '</text>' +
      '</svg>' +
    '</div>';
}

function _getWinRateTone(winRate) {
  const wr = Number.isFinite(winRate) ? winRate : 0;
  if (wr > 55) return { colorCls: 'c-purple', valueCls: 'v-purple', arc: 'var(--accent-purple, #9b6dff)' };
  if (wr >= 48) return { colorCls: 'c-blue', valueCls: 'v-blue', arc: 'var(--b)' };
  if (wr >= 40) return { colorCls: 'c-green', valueCls: 'v-green', arc: 'var(--g)' };
  if (wr >= 35) return { colorCls: 'c-yellow', valueCls: 'v-yellow', arc: 'var(--a)' };
  if (wr >= 30) return { colorCls: 'c-orange', valueCls: 'v-orange', arc: '#f39a3d' };
  return { colorCls: 'c-red', valueCls: 'v-red', arc: 'color-mix(in srgb, var(--r) 88%, var(--body))' };
}

// ── Monetised score tone (% of profitable trades) ──
function _getMonetisedTone(monetisedPct) {
  const m = Number.isFinite(monetisedPct) ? monetisedPct : 0;
  if (m > 70)  return { colorCls: 'c-purple', valueCls: 'v-purple', arc: 'var(--accent-purple, #9b6dff)' };
  if (m >= 60) return { colorCls: 'c-blue',   valueCls: 'v-blue',   arc: 'var(--b)' };
  if (m >= 50) return { colorCls: 'c-green',  valueCls: 'v-green',  arc: 'var(--g)' };
  if (m >= 40) return { colorCls: 'c-yellow', valueCls: 'v-yellow', arc: 'var(--a)' };
  if (m >= 30) return { colorCls: 'c-orange', valueCls: 'v-orange', arc: '#f39a3d' };
  return { colorCls: 'c-red', valueCls: 'v-red', arc: 'color-mix(in srgb, var(--r) 88%, var(--body))' };
}

// ── Stability score tone (0-100 composite) ──
function _getStabilityTone(stabilityScore) {
  const s = Number.isFinite(stabilityScore) ? stabilityScore : 0;
  if (s > 70)  return { colorCls: 'c-purple', valueCls: 'v-purple', arc: 'var(--accent-purple, #9b6dff)' };
  if (s >= 60) return { colorCls: 'c-blue',   valueCls: 'v-blue',   arc: 'var(--b)' };
  if (s >= 50) return { colorCls: 'c-green',  valueCls: 'v-green',  arc: 'var(--g)' };
  if (s >= 40) return { colorCls: 'c-yellow', valueCls: 'v-yellow', arc: 'var(--a)' };
  if (s >= 30) return { colorCls: 'c-orange', valueCls: 'v-orange', arc: '#f39a3d' };
  return { colorCls: 'c-red', valueCls: 'v-red', arc: 'color-mix(in srgb, var(--r) 88%, var(--body))' };
}

function _svStreakMicro(value, tone, idPrefix = 'stats') {
  const max = _SV_STREAK_SCALE_MAX;
  const amt = Math.round(_svClamp(Number(value) || 0, 0, max));
  const gradId = 'sv-micro-bar-' + idPrefix + '-' + tone;
  const start = tone === 'green' ? 'color-mix(in srgb, var(--g) 92%, white)' : 'color-mix(in srgb, var(--r) 90%, white)';
  const end = tone === 'green' ? 'color-mix(in srgb, var(--g) 58%, transparent)' : 'color-mix(in srgb, var(--r) 56%, transparent)';
  const bars = amt;
  const step = bars > 0 ? Math.min(4.1, 40 / bars) : 0;
  const barWidth = bars > 0 ? Math.max(2.8, Math.min(3.35, step - 0.35)) : 0;
  const totalWidth = bars > 0 ? (bars - 1) * step + barWidth : 0;
  const startX = 21 - totalWidth / 2;
  const barMarkup = Array.from({ length: bars }, (_, i) => {
    const t = bars <= 1 ? 1 : i / (bars - 1);
    const envelope = 0.16 + Math.pow(t, 1.35) * 0.84;
    const barHeight = 3 + envelope * 15;
    const x = startX + i * step;
    const y = 22 - barHeight;
    const opacity = 0.72 + t * 0.26;
    return '' +
      '<rect x="' + x.toFixed(2) + '" y="' + y.toFixed(2) + '" width="' + barWidth.toFixed(2) + '" height="' + barHeight.toFixed(2) + '" rx="1.1" fill="url(#' + gradId + ')" opacity="' + opacity.toFixed(2) + '"></rect>';
  }).join('');
  return '' +
    '<div class="wst-cell-micro is-bar" aria-hidden="true">' +
      '<svg viewBox="0 0 42 24" preserveAspectRatio="none">' +
        '<defs>' +
          '<linearGradient id="' + gradId + '" x1="0%" y1="0%" x2="0%" y2="100%">' +
            '<stop offset="0%" stop-color="' + start + '"></stop>' +
            '<stop offset="100%" stop-color="' + end + '"></stop>' +
          '</linearGradient>' +
        '</defs>' +
        '<rect x=".5" y="3" width="41" height="19" rx="6" class="micro-track-fill" opacity=".08"></rect>' +
        barMarkup +
      '</svg>' +
    '</div>';
}

// ── Stats Overview for share view ──
function _svRenderStats(trades, beTrades = trades, beCount = null) {
  const body = document.getElementById('sv-stats-body');
  const badge = document.getElementById('sv-stats-badge');
  if (!body) return;
  const stats = calcStats(trades);
  const beStats = calcStats(beTrades) || { be_tp: 0, be_sl: 0 };
  if (!stats || !stats.n) {
    body.innerHTML = '<div class="sel-empty sel-empty-compact">No data</div>';
    if (badge) badge.textContent = '';
    return;
  }
  const filtered = getFiltered();
  body.innerHTML = buildStatsOverviewMarkup(stats, filtered.length, 'share', beStats, beCount);
  if (badge) badge.textContent = '';
  _attachKpiTooltipHandlers(body);
  // Synchronous fit — apply hide classes before the browser paints the new
  // innerHTML so cells never flash in the "micros visible" state when the
  // ResizeObserver → renderShareView cycle rebuilds the overview. If the
  // cell isn't laid out yet (width 0, first render while the tab is still
  // mounting) the fit is a silent no-op; the rAF fallback below handles
  // that case.
  _fitSvStatsOverviewMicros(body);
  requestAnimationFrame(() => _fitSvStatsOverviewMicros(body));
}

// ── Main share view render orchestrator ──
function renderShareView() {
  if (currentView !== 'share') return;

  const filtered = getFiltered();
  const filteredWithBE = _getContextFiltered(false);
  const selectedPeriod = _svGetSelectedYearMonth(filtered);
  _svSyncPresetSel();

  // Scope trades to the active period:
  //  - Month mode with a YM selection → filter to that month
  //  - Year mode with a specific year → filter to that year
  //  - Year mode with "All"           → keep the full filtered dataset
  let trades = filtered;
  let beTrades = filteredWithBE;
  if (_shareMode === 'month') {
    const { ym } = selectedPeriod;
    if (ym) {
      trades = filtered.filter(t => t.date && t.date.startsWith(ym));
      beTrades = filteredWithBE.filter(t => t.date && t.date.startsWith(ym));
    }
  } else if (_shareMode === 'year' && !selectedPeriod.isAll && selectedPeriod.year) {
    const y = selectedPeriod.year;
    trades = filtered.filter(t => t.date && t.date.slice(0, 4) === y);
    beTrades = filteredWithBE.filter(t => t.date && t.date.slice(0, 4) === y);
  }

  // Build calendar caches from the full filtered dataset
  _svRebuildCaches(filtered);

  // Period label
  _svRenderDateWidget(selectedPeriod.year, selectedPeriod.month);

  // BE Trades KPI: union of (BE-out at active TP) and (BE Mgmt chip-matched).
  // _computeBeTradesKpi (called by buildStatsOverviewMarkup) ignores the
  // share-view period toggle, so compute it here against the active period.
  const _svBeTp = appState.ui.rrMinFilter !== null ? appState.ui.rrMinFilter : _SYSTEM_TP_R;
  const _svBeUnion = new Set([
    ..._getBeOutTradesAtTp(_svBeTp),
    ..._getBeMgmtChipMatchedTrades(),
    ..._getBeOutcomeExcludedTrades(),
  ]);
  let _svBeCount;
  if (_shareMode === 'month' && selectedPeriod.ym) {
    const ym = selectedPeriod.ym;
    _svBeCount = [..._svBeUnion].filter(t => t.date && t.date.startsWith(ym)).length;
  } else if (_shareMode === 'year' && !selectedPeriod.isAll && selectedPeriod.year) {
    const y = selectedPeriod.year;
    _svBeCount = [..._svBeUnion].filter(t => t.date && t.date.slice(0, 4) === y).length;
  } else {
    _svBeCount = _svBeUnion.size;
  }

  // Stats
  _svRenderStats(trades, beTrades, _svBeCount);

  // Equity chart: double rAF ensures layout is fully computed before drawing
  // Triple rAF: wait for CSS grid layout to fully settle before measuring
  // the equity wrap (which is flex:1 inside a grid row with auto height).
  requestAnimationFrame(() =>
    requestAnimationFrame(() =>
      requestAnimationFrame(() => _svDrawEquity(trades))
    )
  );

  // Calendar — in year mode the annual grid uses the selected year (or the
  // most recent year in the dataset when "All" is chosen, since one grid can
  // only show 12 months). In month mode, render a single-month calendar.
  if (_shareMode === 'year') {
    _svRenderCalAnnual(filtered, selectedPeriod.year);
  } else {
    _svRenderCalMonth(selectedPeriod.ym);
  }

  // Performance bars (reuse existing renderBars with sv-specific container IDs)
  const absMax = 1.8;
  renderBars(
    'sv-bars-pair',
    groupByEV(trades, t => t.pair),
    absMax, true, 'pair'
  );
  renderBars(
    'sv-bars-setup',
    groupByEV(
      trades,
      t => setupDetailMode ? (t.setupDetail || t.setup) : t.setup,
      k => setupDetailMode ? k : (SETUP_SHORT[k] || k)
    ),
    absMax, true, 'setup'
  );
}

// ── Convert color(srgb r g b / a) → rgba(R,G,B,A) for html2canvas compat ──
function _svConvertColor(str) {
  if (!str) return str;
  return str.replace(/color\(srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)(?:\s*\/\s*([\d.]+))?\s*\)/g,
    function(_, r, g, b, a) {
      const R = Math.min(255, Math.round(parseFloat(r) * 255));
      const G = Math.min(255, Math.round(parseFloat(g) * 255));
      const B = Math.min(255, Math.round(parseFloat(b) * 255));
      const A = a !== undefined ? parseFloat(a) : 1;
      return A < 0.999 ? 'rgba(' + R + ',' + G + ',' + B + ',' + A.toFixed(3) + ')' : 'rgb(' + R + ',' + G + ',' + B + ')';
    }
  );
}

// ── Build CSS variable → RGB string map from live document ──
function _svBuildVarRgbMap() {
  const cs = window.getComputedStyle(document.documentElement);
  const hexToRgb = hex => {
    hex = hex.trim().replace('#', '');
    if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
    return parseInt(hex.slice(0,2),16) + ',' + parseInt(hex.slice(2,4),16) + ',' + parseInt(hex.slice(4,6),16);
  };
  const names = ['--g','--r','--gold','--b','--t','--dim','--body','--white','--bg','--bg1','--bg2','--bg3','--bg4','--line','--line2','--mute','--a'];
  const map = {};
  names.forEach(n => { const v = cs.getPropertyValue(n).trim(); if (v && v[0] === '#') map[n] = hexToRgb(v); });
  return map;
}

// ── Replace all color-mix() in a CSS string with resolved rgba/rgb values ──
function _svResolveColorMixInCSS(css, varRgbMap) {
  // Pattern 1: color-mix(in srgb, var(--x) N%, transparent)
  css = css.replace(/color-mix\(\s*in srgb\s*,\s*var\((--[\w-]+)\)\s+(\d+)%\s*,\s*transparent\s*\)/gi,
    function(_, varName, pct) {
      const rgb = varRgbMap[varName];
      return rgb ? 'rgba(' + rgb + ',' + (parseInt(pct,10)/100).toFixed(2) + ')' : 'transparent';
    }
  );
  // Pattern 2: color-mix(in srgb, var(--x) N%, var(--y))
  css = css.replace(/color-mix\(\s*in srgb\s*,\s*var\((--[\w-]+)\)\s+(\d+)%\s*,\s*var\((--[\w-]+)\)\s*\)/gi,
    function(_, v1, pct, v2) {
      const rgb1 = varRgbMap[v1], rgb2 = varRgbMap[v2];
      if (!rgb1 || !rgb2) return 'currentColor';
      const f1 = parseInt(pct,10)/100, f2 = 1 - f1;
      const [r1,g1,b1] = rgb1.split(',').map(Number);
      const [r2,g2,b2] = rgb2.split(',').map(Number);
      return 'rgb(' + Math.round(r1*f1+r2*f2) + ',' + Math.round(g1*f1+g2*f2) + ',' + Math.round(b1*f1+b2*f2) + ')';
    }
  );
  return css;
}

// ── Export share view as a PNG image using dom-to-image ──
// dom-to-image uses SVG foreignObject (browser-native CSS), so color-mix() works correctly.
function exportShareView() {
  const btn       = document.getElementById('sv-share-btn');
  const container = document.getElementById('sv-export');
  if (!container) return;

  if (btn) { btn.innerHTML = '<span class="sv-share-btn-icon">⏳</span> Copying…'; btn.disabled = true; }

  // Gate the share-view ResizeObserver: while export mutates widget sizes,
  // we don't want it retriggering renderShareView — that would rebuild the
  // stats cells at the stretched capture width and unhide the micro-charts
  // we want to stay hidden. The flag is cleared in the .finally() below.
  _svExporting = true;

  // Ensure equity canvas is fully painted — same scoping as renderShareView
  // so the exported image matches what the user sees.
  const trades = (() => {
    const filtered = getFiltered();
    const period = _svGetSelectedYearMonth(filtered);
    if (_shareMode === 'month') {
      return period.ym ? filtered.filter(t => t.date && t.date.startsWith(period.ym)) : filtered;
    }
    if (_shareMode === 'year' && !period.isAll && period.year) {
      const y = period.year;
      return filtered.filter(t => t.date && t.date.slice(0, 4) === y);
    }
    return filtered;
  })();
  _svDrawEquity(trades);

  // ── Pin the panel to canonical export dimensions ────────────────────
  // Both width AND height are FIXED regardless of viewport so every
  // screen — laptop, ultrawide, anything in between — produces a byte-
  // identical PNG. Earlier iterations only enforced a minimum on each
  // axis, which let big screens use their native (taller) layout while
  // small screens fell back to a short, calendar-squashed render.
  //
  // Aspect 3760:1617 ≈ 2.326:1 matches the natural layout proportion
  // observed on the user's big-screen exports — the share view's grid
  // (`grid-template-rows: auto auto 1fr 1fr 2fr`) needs that vertical
  // budget for the monthly calendar cells to breathe.
  // Width 2400 live → 4800 PNG @ scale=2; height ~1032 live → ~2064 PNG.
  // Restored in the .finally() block so the live view is unaffected.
  const EXPORT_WIDTH  = 2400;
  const EXPORT_HEIGHT = Math.round(EXPORT_WIDTH * 1617 / 3760);
  const widthSnap = {
    width:     container.style.width,
    minWidth:  container.style.minWidth,
    maxWidth:  container.style.maxWidth,
    height:    container.style.height,
    minHeight: container.style.minHeight,
  };
  // Force the cross-axis (width) only — never `flex`, since #share-view is
  // flex-direction: column and a flex-basis would lock the height instead.
  // Height is set via the standalone `height` / `min-height` properties
  // which work in flex children without that side effect.
  container.style.width     = EXPORT_WIDTH + 'px';
  container.style.minWidth  = EXPORT_WIDTH + 'px';
  container.style.maxWidth  = EXPORT_WIDTH + 'px';
  container.style.height    = EXPORT_HEIGHT + 'px';
  container.style.minHeight = EXPORT_HEIGHT + 'px';
  // Force layout reflow before recomputing canvas + calendar dimensions.
  void container.offsetWidth;
  // Redraw the equity canvas at the new wrap dimensions (post-widening).
  _svDrawEquity(trades);
  // Recompute the uniform-row min-height for the wider cells, so the
  // calendar's monthly grid distributes correctly at export size.
  const _expMonthGrid = container.querySelector('.sv-cal-month-grid');
  if (_expMonthGrid) {
    let _expMaxH = 0;
    _expMonthGrid.querySelectorAll('.sv-cal-month-day-value').forEach(c => {
      if (c.scrollHeight > _expMaxH) _expMaxH = c.scrollHeight;
    });
    if (_expMaxH > 0) _expMonthGrid.style.setProperty('--sv-cal-row-min-h', _expMaxH + 'px');
  }

  const bgColor = getComputedStyle(document.documentElement).getPropertyValue('--bg').trim() || '#070c18';
  const scale   = 2;

  // Snapshot previous inline state before mutating anything.
  const prevInline = {
    overflowY:         container.style.overflowY,
    overflowX:         container.style.overflowX,
    height:            container.style.height,
    maxHeight:         container.style.maxHeight,
    scrollTop:         container.scrollTop,
    gridTemplateRows:  container.style.gridTemplateRows,
    alignContent:      container.style.alignContent,
  };

  // Every widget / scroll-well whose height we'll stretch to its content
  // during capture. Snapshot the original inline style first so we can
  // restore it from .finally() — even if an exception aborts the capture.
  const constrained = container.querySelectorAll(
    '#sv-w-pair, #sv-w-setup, #sv-w-equity, #sv-w-cal, #sv-w-stats, ' +
    '#sv-bars-pair, #sv-bars-setup, #sv-cal-grid, .wst-body, .bar-list, ' +
    '.sv-gs-widget, .sv-cal-annual-grid, .sv-cal-month-shell'
  );

  const snapshots = Array.from(constrained).map(el => ({
    el,
    overflow:   el.style.overflow,
    overflowY:  el.style.overflowY,
    overflowX:  el.style.overflowX,
    height:     el.style.height,
    maxHeight:  el.style.maxHeight,
    minHeight:  el.style.minHeight,
    flex:       el.style.flex,
    flexBasis:  el.style.flexBasis,
    flexGrow:   el.style.flexGrow,
    flexShrink: el.style.flexShrink,
    scrollTop:  el.scrollTop,
    scrollLeft: el.scrollLeft,
    // Remember the pre-mutation rendered size so we can grow-but-never-shrink.
    // (Widgets with absolutely-positioned canvases like #sv-w-equity have a
    // scrollHeight that doesn't include the canvas — we must not collapse
    // them to that zero-ish value.)
    preW: el.offsetWidth,
    preH: el.offsetHeight,
  }));

  // Release the grid container FIRST: swap fr-based row tracks to auto
  // so the grid rows size to content instead of distributing leftover
  // space. Without this, flex:1 children stay clamped to the original
  // fr track height.
  container.scrollTop = 0;
  container.style.overflowY         = 'visible';
  container.style.overflowX         = 'visible';
  container.style.maxHeight         = 'none';
  container.style.height            = 'auto';
  container.style.gridTemplateRows  = 'auto auto auto auto auto';
  // Disable the default `align-content: stretch` distribution. Without this,
  // the canonical-export min-height forces leftover space to be spread across
  // every auto row, which drifts pair / setup / cal bottoms relative to each
  // other (each widget has an explicit height that doesn't grow with the
  // stretched track). Excess space is instead absorbed by growing equity at
  // the end of the setTimeout block below.
  container.style.alignContent      = 'start';
  container.classList.add('sv-export-capture');

  // Neutralise flex constraints on every scroll-well so they can grow
  // to their natural content size.
  snapshots.forEach(({ el }) => {
    el.scrollTop  = 0;
    el.scrollLeft = 0;
    el.style.overflow  = 'visible';
    el.style.overflowY = 'visible';
    el.style.overflowX = 'visible';
    el.style.maxHeight = 'none';
    el.style.minHeight = '0';
    el.style.flex       = '0 0 auto';
    el.style.flexGrow   = '0';
    el.style.flexShrink = '0';
    el.style.flexBasis  = 'auto';
    el.style.height     = 'auto';
  });
  // Second pass: pin each element to its natural content height. Widgets that
  // contain an absolutely-positioned canvas (equity chart) have a misleading
  // scrollHeight of ~0 — for those, fall back to preH so the canvas stays
  // visible. For canvas-free widgets (bar lists, calendar grid), use
  // scrollHeight to grow them past their original visible area when needed.
  // sv-w-stats and sv-w-date are pinned to preH (live offsetHeight): with the
  // grid template flipped to all-auto rows, their inline `min-height: 0` +
  // `flex: 0 0 auto` (set in the first pass) lets the row collapse below its
  // rendered height while neighbour rows hold pinned widgets. The leftover
  // distribution pulls Equity & Drawdown and P&L Calendar upward in the
  // exported PNG. preH-pinning keeps the KPI strip exactly as the user sees it.
  snapshots.forEach(({ el, preH }) => {
    if (el.id === 'sv-w-stats' || el.id === 'sv-w-date') {
      if (preH > 0) el.style.height = preH + 'px';
      return;
    }
    const sh = el.scrollHeight;
    const hasCanvas = !!el.querySelector('canvas');
    const target = hasCanvas ? Math.max(preH || 0, sh || 0) : (sh || preH || 0);
    if (target > 0) el.style.height = target + 'px';
  });

  // Snapshots for the calendar-alignment block below (declared out here so
  // the .finally() restore can see them even if the if-branch doesn't run).
  let calSnap = null;
  let calGridSnap = null;
  let equitySnap = null;
  let annualSnap = null;
  let miniMonthSnaps = [];
  let miniDaysSnaps = [];
  let monthShellSnap = null;
  let monthGridSnap = null;
  let monthWeeksSnap = null;
  let monthDaysSnaps = [];
  let _capCal = null, _capCalGrid = null, _capAnnual = null;
  let _capMonthShell = null, _capMonthGrid = null, _capMonthWeeks = null;

  // Let the browser reflow after the height/overflow mutations before we
  // measure fullWidth/fullHeight — otherwise scrollHeight still reflects
  // the pre-mutation grid row tracks.
  setTimeout(() => {
    // Align the P&L calendar height to the left column and stretch all
    // calendar-internal containers (year and month modes) so their content
    // fits without overflow, and crucially without leaving a gap at the
    // bottom of the right column when Setup has grown past its baseline.
    //
    // Layout reminder: row 3-4 = Equity (spans 2 rows), row 5 = Pair | Setup
    // (side-by-side in the same row). Hence totalLeft = equity + max(pair,
    // setup) + 1 gap, NOT equity + pair + setup + 2 gaps.
    const elEquity = container.querySelector('#sv-w-equity');
    const elPair   = container.querySelector('#sv-w-pair');
    const elSetup  = container.querySelector('#sv-w-setup');
    const elCal    = container.querySelector('#sv-w-cal');

    if (elEquity && elPair && elSetup && elCal) {
      const gap       = 10;
      const hEquity   = elEquity.offsetHeight;
      const hPair     = elPair.offsetHeight;
      const hSetup    = elSetup.offsetHeight;
      // Pair and Setup sit in the same grid row (side-by-side). The grid row
      // sizes to max(pair, setup), but the SHORTER widget — pinned to its
      // own scrollHeight in the second pass — would render above the row's
      // bottom edge and leave its bottom Y above the taller widget's bottom
      // (and above the calendar bottom). Force both to the same height so
      // pair / setup / cal all bottom-align to the same Y in the export.
      const row5Height = Math.max(hPair, hSetup);
      elPair.style.height  = row5Height + 'px';
      elSetup.style.height = row5Height + 'px';
      const totalLeft = hEquity + row5Height + gap;

      // Calendar's intrinsic content height (the widget was pinned to its
      // scrollHeight in the second pass, so offsetHeight reflects the height
      // it WANTS to occupy with the uniform-row monthly grid). If that's
      // taller than the left column, we grow the equity widget by the delta
      // so both columns stay aligned at the bottom and nothing in the
      // calendar gets clipped in the exported PNG.
      const calNatural = elCal.offsetHeight;
      // Compute the height the lower 3 rows MUST fill to occupy the canonical
      // export container exactly. Without this, totalLeft + calNatural can be
      // smaller than the container's enforced min-height — leaving leftover
      // space that align-content would normally distribute across rows
      // (which we disabled with `align-content: start`). Forcing the cal/equity
      // pair to absorb that leftover keeps pair/setup/cal bottoms strictly
      // aligned with each other AND with the bottom edge of the PNG.
      const elDate  = container.querySelector('#sv-w-date');
      const elStats = container.querySelector('#sv-w-stats');
      const dateH   = elDate  ? elDate.offsetHeight  : 0;
      const statsH  = elStats ? elStats.offsetHeight : 0;
      const padding = 32; // 16 top + 16 bottom on #sv-export
      const lower3Available = container.clientHeight - padding - dateH - statsH - 2 * gap;
      const targetHeight = Math.max(totalLeft, calNatural, lower3Available);
      const equityDelta = targetHeight - totalLeft;
      if (equityDelta > 0) {
        equitySnap = {
          el:     elEquity,
          height: elEquity.style.height,
        };
        elEquity.style.height = (hEquity + equityDelta) + 'px';
        // Force layout reflow so the equity wrap reflects the new height,
        // then redraw the canvas at the new size — otherwise the chart stays
        // at its original pixel dimensions and leaves whitespace below.
        void elEquity.offsetHeight;
        _svDrawEquity(trades);
      }

      // Inner content area of the calendar widget: widget height minus its
      // own padding (widget-padding defaults to ~13px top + ~13px bottom
      // → roughly 32px total vertical padding) minus the widget header.
      const calHeader  = elCal.querySelector('.sv-widget-head, .cc-head');
      const calHeaderH = calHeader ? calHeader.offsetHeight + 10 : 32;
      const calInnerH  = Math.max(0, targetHeight - 32 - calHeaderH);

      // Snapshot + pin the widget itself
      calSnap = {
        el:        elCal,
        height:    elCal.style.height,
        minHeight: elCal.style.minHeight,
        overflow:  elCal.style.overflow,
      };
      _capCal = elCal;
      elCal.style.height    = targetHeight + 'px';
      elCal.style.minHeight = targetHeight + 'px';
      elCal.style.overflow  = 'hidden';

      // ── Main calendar scroll-well ──
      const calGrid = elCal.querySelector('#sv-cal-grid');
      if (calGrid) {
        calGridSnap = {
          el:        calGrid,
          height:    calGrid.style.height,
          maxHeight: calGrid.style.maxHeight,
          overflow:  calGrid.style.overflow,
        };
        _capCalGrid = calGrid;
        calGrid.style.height    = calInnerH + 'px';
        calGrid.style.maxHeight = calInnerH + 'px';
        calGrid.style.overflow  = 'hidden';
      }

      // ── Year mode ──
      const annualGrid = elCal.querySelector('.sv-cal-annual-grid');
      if (annualGrid) {
        annualSnap = {
          el:               annualGrid,
          height:           annualGrid.style.height,
          maxHeight:        annualGrid.style.maxHeight,
          gridTemplateRows: annualGrid.style.gridTemplateRows,
          overflow:         annualGrid.style.overflow,
        };
        _capAnnual = annualGrid;
        annualGrid.style.height           = '100%';
        annualGrid.style.maxHeight        = '100%';
        annualGrid.style.gridTemplateRows = 'repeat(3, 1fr)';
        annualGrid.style.overflow         = 'hidden';
      }

      const miniMonths = elCal.querySelectorAll('.sv-cal-mini-month');
      miniMonthSnaps = Array.from(miniMonths).map(el => ({
        el,
        height:    el.style.height,
        maxHeight: el.style.maxHeight,
        overflow:  el.style.overflow,
      }));
      miniMonths.forEach(el => {
        el.style.height    = '100%';
        el.style.maxHeight = '100%';
        el.style.overflow  = 'hidden';
      });

      const miniDays = elCal.querySelectorAll('.sv-cal-mini-days');
      miniDaysSnaps = Array.from(miniDays).map(el => ({
        el,
        overflow:  el.style.overflow,
        flex:      el.style.flex,
        minHeight: el.style.minHeight,
      }));
      miniDays.forEach(el => {
        el.style.overflow  = 'hidden';
        el.style.flex      = '1 1 0';
        el.style.minHeight = '0';
      });

      // ── Month mode ──
      const monthShell = elCal.querySelector('.sv-cal-month-shell');
      const monthGrid  = elCal.querySelector('.sv-cal-month-grid');
      // The current month DOM has no dedicated `.sv-cal-month-weeks`
      // wrapper — day cells are direct children of `.sv-cal-month-grid`.
      // The selector stays future-proof for any renderer refactor.
      const monthWeeks = elCal.querySelector('.sv-cal-month-weeks, .sv-cal-month-body');

      if (monthShell) {
        monthShellSnap = {
          el:       monthShell,
          height:   monthShell.style.height,
          overflow: monthShell.style.overflow,
        };
        _capMonthShell = monthShell;
        monthShell.style.height   = '100%';
        monthShell.style.overflow = 'hidden';
      }
      if (monthGrid) {
        monthGridSnap = {
          el:               monthGrid,
          height:           monthGrid.style.height,
          gridTemplateRows: monthGrid.style.gridTemplateRows,
        };
        _capMonthGrid = monthGrid;
        monthGrid.style.height = '100%';
        // Keep the existing `auto repeat(weeks, 1fr)` row template from
        // the base CSS — don't clobber it with `auto 1fr` which would
        // collapse all weeks into a single track.
      }
      if (monthWeeks) {
        monthWeeksSnap = {
          el:           monthWeeks,
          height:       monthWeeks.style.height,
          gridAutoRows: monthWeeks.style.gridAutoRows,
          overflow:     monthWeeks.style.overflow,
        };
        _capMonthWeeks = monthWeeks;
        monthWeeks.style.height       = '100%';
        monthWeeks.style.gridAutoRows = '1fr';
        monthWeeks.style.overflow     = 'hidden';
      }

      const monthDays = elCal.querySelectorAll(
        '.sv-cal-month-day, .sv-cal-month-day-empty, .sv-cal-month-day-value, .sv-cal-weekcell'
      );
      monthDaysSnaps = Array.from(monthDays).map(el => ({
        el,
        minHeight: el.style.minHeight,
        overflow:  el.style.overflow,
      }));
      monthDays.forEach(el => {
        el.style.minHeight = '0';
        el.style.overflow  = 'hidden';
      });
    }

    const fullWidth  = Math.max(container.scrollWidth,  container.offsetWidth);
    const fullHeight = Math.max(container.scrollHeight, container.offsetHeight);
    container.style.height = fullHeight + 'px';

    // Freeze the micro-hide decisions that are currently applied in the
    // live share view — do NOT re-measure against the capture geometry.
    // Capture-time cell widths can be briefly larger than the live layout
    // (height stretch, scrollbar removal, etc.), which would flip hidden
    // charts back on and let them overlap the KPI value on the PNG. The
    // user's rule: if the chart is hidden in the live view, it stays
    // hidden in the exported image too.

    const W = fullWidth  * scale;
    const H = fullHeight * scale;

    // Force inline styles so the centered layout survives dom-to-image's
    // clone. CSS rules with combinator selectors (`:not()`, `>`) sometimes
    // don't propagate cleanly through the clone, leaving values left-aligned
    // in the exported PNG even when the live DOM displays them correctly.
    const _statsCells = container.querySelectorAll('#sv-stats-body .wst-cell');
    const _statsCellSnapshots = [];
    _statsCells.forEach(cell => {
      const isHidden = cell.classList.contains('micro-hidden');
      const hasNoMicro = !cell.classList.contains('has-micro');
      const main = cell.querySelector('.wst-cell-main');
      _statsCellSnapshots.push({
        cell, main,
        cellJC: cell.style.justifyContent,
        cellPadRight: cell.style.paddingRight,
        mainFlex: main ? main.style.flex : null,
        mainWidth: main ? main.style.width : null,
        mainJC: main ? main.style.justifyContent : null,
      });
      // Always force padding-right symmetric during capture so [value+chart]
      // is centered. The asymmetric padding-right (78-98px) reserved for SVG
      // overflow is a live-view visual aid that's irrelevant in the PNG.
      cell.style.paddingRight = '14px';
      // For micro-hidden / no-chart cells, also force main to shrink so the
      // [label+value] pair vertically centers as a block (otherwise the
      // natural flex:1 1 auto grows main to cell height and top-anchors it).
      // Chart-visible cells keep their natural flex:1 1 auto + width:100% +
      // justify-content:center, so [value, gap, micro] centers in the cell.
      if ((isHidden || hasNoMicro) && main) {
        cell.style.justifyContent = 'center';
        main.style.flex = '0 0 auto';
        main.style.width = '100%';
        main.style.justifyContent = 'center';
      }
    });

    domtoimage.toBlob(container, {
      bgcolor: bgColor,
      width:   W,
      height:  H,
      style: {
        transform: 'scale(' + scale + ')',
        transformOrigin: 'top left',
        width:  fullWidth  + 'px',
        height: fullHeight + 'px',
        overflow: 'visible',
      },
    }).then(async blob => {
      if (!blob) throw new Error('Image blob generation failed');

      if (navigator.clipboard && window.ClipboardItem) {
        await navigator.clipboard.write([
          new ClipboardItem({ 'image/png': blob })
        ]);
        if (btn) btn.innerHTML = '<span class="sv-share-btn-icon">✓</span> Copied';
        return;
      }

      const objectUrl = URL.createObjectURL(blob);
      window.open(objectUrl, '_blank', 'noopener,noreferrer');
      setTimeout(() => URL.revokeObjectURL(objectUrl), 60000);
      alert('Image opened in a new tab because direct clipboard copy is not available here.');
    }).catch(err => {
      console.error('Export failed:', err);
      alert('Image copy failed. Please try again.');
    }).finally(() => {
      container.classList.remove('sv-export-capture');
      container.style.overflowY        = prevInline.overflowY;
      container.style.overflowX        = prevInline.overflowX;
      container.style.height           = prevInline.height;
      container.style.maxHeight        = prevInline.maxHeight;
      container.style.gridTemplateRows = prevInline.gridTemplateRows;
      container.style.alignContent     = prevInline.alignContent;
      container.scrollTop              = prevInline.scrollTop;
      // Restore the canonical-export-width override so the live panel goes
      // back to its viewport-driven size. Done first so the equity redraw
      // and calendar row recompute below see the live dimensions.
      container.style.width     = widthSnap.width;
      container.style.minWidth  = widthSnap.minWidth;
      container.style.maxWidth  = widthSnap.maxWidth;
      container.style.height    = widthSnap.height;
      container.style.minHeight = widthSnap.minHeight;
      void container.offsetWidth;
      try { _svDrawEquity(trades); } catch (e) { /* swallow restore draws */ }
      if (_expMonthGrid) {
        let _liveMaxH = 0;
        _expMonthGrid.querySelectorAll('.sv-cal-month-day-value').forEach(c => {
          if (c.scrollHeight > _liveMaxH) _liveMaxH = c.scrollHeight;
        });
        if (_liveMaxH > 0) _expMonthGrid.style.setProperty('--sv-cal-row-min-h', _liveMaxH + 'px');
        else _expMonthGrid.style.removeProperty('--sv-cal-row-min-h');
      }
      // Restore calendar-alignment snapshots (guarded — they are only
      // populated when the aligning if-branch ran).
      if (calSnap) {
        calSnap.el.style.height    = calSnap.height;
        calSnap.el.style.minHeight = calSnap.minHeight;
        calSnap.el.style.overflow  = calSnap.overflow;
      }
      if (calGridSnap) {
        calGridSnap.el.style.height    = calGridSnap.height;
        calGridSnap.el.style.maxHeight = calGridSnap.maxHeight;
        calGridSnap.el.style.overflow  = calGridSnap.overflow;
      }
      // Restore equity widget height (only set when calendar grew the left
      // column to match a busy month). Redraw the canvas back to live size.
      if (equitySnap) {
        equitySnap.el.style.height = equitySnap.height;
        void equitySnap.el.offsetHeight;
        try { _svDrawEquity(trades); } catch (e) { /* swallow restore-time draw errors */ }
      }
      if (annualSnap) {
        annualSnap.el.style.height           = annualSnap.height;
        annualSnap.el.style.maxHeight        = annualSnap.maxHeight;
        annualSnap.el.style.gridTemplateRows = annualSnap.gridTemplateRows;
        annualSnap.el.style.overflow         = annualSnap.overflow;
      }
      miniMonthSnaps.forEach(s => {
        s.el.style.height    = s.height;
        s.el.style.maxHeight = s.maxHeight;
        s.el.style.overflow  = s.overflow;
      });
      miniDaysSnaps.forEach(s => {
        s.el.style.overflow  = s.overflow;
        s.el.style.flex      = s.flex;
        s.el.style.minHeight = s.minHeight;
      });
      if (monthShellSnap) {
        monthShellSnap.el.style.height   = monthShellSnap.height;
        monthShellSnap.el.style.overflow = monthShellSnap.overflow;
      }
      if (monthGridSnap) {
        monthGridSnap.el.style.height           = monthGridSnap.height;
        monthGridSnap.el.style.gridTemplateRows = monthGridSnap.gridTemplateRows;
      }
      if (monthWeeksSnap) {
        monthWeeksSnap.el.style.height       = monthWeeksSnap.height;
        monthWeeksSnap.el.style.gridAutoRows = monthWeeksSnap.gridAutoRows;
        monthWeeksSnap.el.style.overflow     = monthWeeksSnap.overflow;
      }
      monthDaysSnaps.forEach(s => {
        s.el.style.minHeight = s.minHeight;
        s.el.style.overflow  = s.overflow;
      });
      // Restore stats cells inline styles (paired with the pre-capture forcing).
      _statsCellSnapshots.forEach(s => {
        s.cell.style.justifyContent = s.cellJC;
        s.cell.style.paddingRight = s.cellPadRight;
        if (s.main) {
          s.main.style.flex = s.mainFlex;
          s.main.style.width = s.mainWidth;
          s.main.style.justifyContent = s.mainJC;
        }
      });
      // Restore every constrained descendant
      snapshots.forEach(s => {
        s.el.style.overflow   = s.overflow;
        s.el.style.overflowY  = s.overflowY;
        s.el.style.overflowX  = s.overflowX;
        s.el.style.height     = s.height;
        s.el.style.maxHeight  = s.maxHeight;
        s.el.style.minHeight  = s.minHeight;
        s.el.style.flex       = s.flex;
        s.el.style.flexBasis  = s.flexBasis;
        s.el.style.flexGrow   = s.flexGrow;
        s.el.style.flexShrink = s.flexShrink;
        s.el.scrollTop  = s.scrollTop;
        s.el.scrollLeft = s.scrollLeft;
      });
      setTimeout(() => {
        if (btn) { btn.innerHTML = '<span class="sv-share-btn-icon">⧉</span> Copy Image'; btn.disabled = false; }
      }, 1200);
      // Release the ResizeObserver gate only after the DOM has settled
      // back into its live-view layout — otherwise the very restore above
      // re-triggers the observer into a renderShareView that defeats the
      // point (it would rebuild the stats cells at the wrong moment).
      requestAnimationFrame(() => requestAnimationFrame(() => {
        _svExporting = false;
      }));
    });
  }, 80);
}
